fn nativeFrameOptionsForLevel(level: c_int, options: FrameOptions) Error!NativeFrameOptions {
    if (level < min_compression_level or level > max_compression_level) return error.InvalidBlockPlan;
    var native_options: NativeFrameOptions = .{
        .content_checksum = options.content_checksum,
        .include_content_size = options.include_content_size,
    };
    if (level <= 0) {
        native_options.selection = .raw_or_rle;
        native_options.match_search_budget = 0;
    } else {
        // The bootstrap planner's budget is an explicit upper bound on branch
        // states, so it is the first meaningful level control available to the
        // native encoder. Keep level 1 latency bounded and spend progressively
        // more search through level 9; higher levels currently share the most
        // exhaustive supported search until additional parser strategies land.
        native_options.match_search_budget = switch (level) {
            1 => 16,
            2 => 32,
            3 => 64,
            4 => 96,
            5 => 128,
            else => 96,
        };
        // Upstream zstd's fast, double-fast, and greedy strategies check recent
        // offsets directly in their match loops. Enable Vort's bounded repeat
        // beam at levels 1-3 as well as ratio levels; level 1 uses its isolated
        // one-state variant. Level 3 may accept that fast candidate only behind
        // a conservative double-fast margin, while its fallback and the other
        // levels retain two states.
        // Outside that bounded speed-policy shortcut, complete block/frame
        // arbitration still rejects it whenever the repeat-aware stream is not
        // smaller.
        native_options.rep_beam_search = (level >= 1 and level <= 3) or level >= 9;
    }
    return native_options;
}

fn adaptiveLevelBlockSizes(level: c_int) [2]usize {
    return switch (level) {
        1, 2 => .{ 1024, 2 * 1024 },
        3...5 => .{ 2 * 1024, 4 * 1024 },
        else => .{ 4 * 1024, 8 * 1024 },
    };
}

fn adaptiveCandidateCanTriggerDeferred(candidate_len: usize, best_len: usize) bool {
    return candidate_len <= std.math.add(usize, best_len, deferred_adaptive_candidate_size_slack) catch
        std.math.maxInt(usize);
}

noinline fn largerAdaptiveCandidateIsDecisive(input: []const u8, larger_len: usize, primary_len: usize) bool {
    return !preferSerialMixedSearch(input) and
        larger_len <= primary_len - primary_len / 8;
}

noinline fn probeDecisiveLargerAdaptiveFrame(
    allocator: std.mem.Allocator,
    input: []const u8,
    level: c_int,
    options: FrameOptions,
) Error!?NativeFrameEncodeResult {
    const primary_options = try nativeFrameOptionsForLevel(level, options);
    if (level <= 0 or preferSerialMixedSearch(input) or !hasQuarterTailHistoryEvidence(input)) return null;
    const larger_block_size = preflightAdaptiveBlockSize(level);
    if (larger_block_size >= input.len or larger_block_size == primary_options.block_size_max) return null;
    var larger = try encodeNativeFrameWithOptionsAlloc(
        allocator,
        input,
        adaptiveLevelCandidateOptions(primary_options, larger_block_size),
    );
    if (level >= 19) {
        const fallback_block_size = adaptiveLevelBlockSizes(level)[1];
        if (fallback_block_size < input.len and fallback_block_size != larger_block_size) {
            const fallback = try encodeNativeFrameWithOptionsAlloc(
                allocator,
                input,
                adaptiveLevelCandidateOptions(primary_options, fallback_block_size),
            );
            if (fallback.frame.len < larger.frame.len) {
                allocator.free(larger.frame);
                larger = fallback;
            } else allocator.free(fallback.frame);
        }
    }
    if (larger.frame.len <= input.len / 4) return larger;
    allocator.free(larger.frame);
    return null;
}

fn preflightAdaptiveBlockSize(level: c_int) usize {
    return if (level <= 2)
        8 * 1024
    else if (level >= 19)
        32 * 1024
    else
        adaptiveLevelBlockSizes(level)[1];
}

fn hasQuarterTailHistoryEvidence(input: []const u8) bool {
    if (input.len < 256) return false;
    const tail_start = input.len - input.len / 4;
    const probe_len: usize = 64;
    if (tail_start + probe_len > input.len) return false;
    return std.mem.indexOf(u8, input[0..tail_start], input[tail_start..][0..probe_len]) != null;
}

fn adaptiveLevelCandidateOptions(primary: NativeFrameOptions, block_size: usize) NativeFrameOptions {
    var options = primary;
    options.block_size_max = block_size;
    options.match_search_budget = @min(options.match_search_budget, adaptive_split_match_search_budget_max);
    options.rep_beam_search = false;
    return options;
}

/// Snapshot of the native frame candidates evaluated by the one-shot level
/// facade. This is an observability surface for benchmark tooling, not a
/// promise that future levels will keep the same search budget or split ladder.
pub const NativeEncodeLevelDiagnostics = struct {
    primary_options: NativeFrameOptions,
    adaptive_block_sizes: [2]usize,
    adaptive_match_search_budget: usize,
};

/// Report the exact primary options and adaptive split sizes currently selected
/// for `encodeFrameWithLevelAndOptionsAlloc`. Keeping this policy lookup beside
/// the encoder prevents the stage benchmark from silently drifting when level
/// mappings are tuned.
pub fn nativeEncodeLevelDiagnostics(level: c_int, options: FrameOptions) Error!NativeEncodeLevelDiagnostics {
    const primary_options = try nativeFrameOptionsForLevel(level, options);
    return .{
        .primary_options = primary_options,
        .adaptive_block_sizes = adaptiveLevelBlockSizes(level),
        .adaptive_match_search_budget = @min(primary_options.match_search_budget, adaptive_split_match_search_budget_max),
    };
}

/// Emit a valid Zstandard frame composed of raw and RLE blocks.
///
/// This entrypoint is retained as an explicit subset alias; the general
/// `encodeFrameAlloc()` facade now uses the broader native writer directly.
pub fn encodeRawOrRleFrameAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    return try encodeRawOrRleFrameWithOptionsAlloc(allocator, input, .{});
}

pub fn encodeRawOrRleFrameWithOptionsAlloc(
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeFrameOptions,
) Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try encodeRawOrRleFrameAppend(allocator, &out, input, options);
    return out.toOwnedSlice(allocator);
}

pub fn encodeRawOrRleFrameAppend(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    input: []const u8,
    options: NativeFrameOptions,
) Error!void {
    _ = try nativeMatchSearchBudget(options);
    try emitFrameHeader(allocator, out, try checkedUsizeToU64(input.len), options);
    const block_size_max = try nativeBlockSizeMax(options);
    if (input.len == 0) {
        try emitBlock(allocator, out, "", true);
    } else {
        var offset: usize = 0;
        while (offset < input.len) {
            const search_end = @min(input.len, offset + block_size_max);
            if (findRleRun(input[offset..search_end])) |run| {
                const run_start = offset + run.start;
                if (run_start > offset) try emitBlock(allocator, out, input[offset..run_start], false);
                const run_end = run_start + run.len;
                try emitRleBlock(allocator, out, input[run_start], run.len, run_end == input.len);
                offset = run_end;
            } else {
                try emitBlock(allocator, out, input[offset..search_end], search_end == input.len);
                offset = search_end;
            }
        }
    }
    try emitContentChecksum(allocator, out, input, options);
}

const RawOrRleFrameShape = struct {
    encoded_len: usize,
    all_raw: bool = true,
};

const RawOrRleFrameShapeInspection = union(enum) {
    exact: RawOrRleFrameShape,
    exceeds_limit,
};

fn inspectRawOrRleFrameShape(input: []const u8, options: NativeFrameOptions) Error!RawOrRleFrameShape {
    return switch (try inspectRawOrRleFrameShapeLimited(input, options, null)) {
        .exact => |shape| shape,
        .exceeds_limit => unreachable,
    };
}

fn inspectRawOrRleFrameShapeLimited(
    input: []const u8,
    options: NativeFrameOptions,
    encoded_len_limit: ?usize,
) Error!RawOrRleFrameShapeInspection {
    _ = try nativeMatchSearchBudget(options);
    var shape: RawOrRleFrameShape = .{ .encoded_len = try nativeFrameHeaderLen(try checkedUsizeToU64(input.len), options) };
    const trailing_len: usize = if (options.content_checksum) 4 else 0;
    const block_size_max = try nativeBlockSizeMax(options);
    if (input.len == 0) {
        shape.encoded_len = std.math.add(usize, shape.encoded_len, 3) catch return error.IntegerOverflow;
    } else {
        var offset: usize = 0;
        while (offset < input.len) {
            const search_end = @min(input.len, offset + block_size_max);
            const block = input[offset..search_end];
            const run = switch (findRleRunForShape(block, shape.encoded_len, trailing_len, encoded_len_limit)) {
                .exceeds_limit => return .exceeds_limit,
                .found => |run| run,
                .none => null,
            };
            if (run) |value| {
                shape.all_raw = false;
                const run_start = offset + value.start;
                if (run_start > offset)
                    shape.encoded_len = try addRawOrRleBlockLen(shape.encoded_len, input[offset..run_start], &shape.all_raw);
                shape.encoded_len = std.math.add(usize, shape.encoded_len, 4) catch return error.IntegerOverflow;
                if (encoded_len_limit) |limit|
                    if (shape.encoded_len +| trailing_len > limit) return .exceeds_limit;
                offset = run_start + value.len;
            } else {
                shape.encoded_len = try addRawOrRleBlockLen(shape.encoded_len, block, &shape.all_raw);
                offset = search_end;
            }
        }
    }
    shape.encoded_len = std.math.add(usize, shape.encoded_len, trailing_len) catch return error.IntegerOverflow;
    return .{ .exact = shape };
}

const RleRunShapeSearch = union(enum) {
    found: RleRun,
    none,
    exceeds_limit,
};

fn findRleRunForShape(block: []const u8, encoded_prefix_len: usize, trailing_len: usize, encoded_len_limit: ?usize) RleRunShapeSearch {
    var i: usize = 0;
    var scanned_run_count: usize = 0;
    while (i < block.len) {
        const len = sameByteRunLen(block, i);
        if (len >= min_rle_split_len) return .{ .found = .{ .start = i, .len = len } };
        i += @max(len, 1);
        scanned_run_count += 1;
        if (encoded_len_limit) |limit| {
            // No qualifying run starts before `i`, so those bytes require at
            // least one block header. A lone short equal-byte prefix can still
            // use a one-byte RLE payload; after a second run the whole prefix
            // is necessarily raw. Ignore all future block costs to keep this
            // a conservative lower bound.
            const prefix_payload_len = if (scanned_run_count == 1) @min(i, 1) else i;
            const lower_bound = encoded_prefix_len +| trailing_len +| 3 +| prefix_payload_len;
            if (lower_bound > limit) return .exceeds_limit;
        }
    }
    return .none;
}

fn addRawOrRleBlockLen(total: usize, block: []const u8, all_raw: *bool) Error!usize {
    const payload_len: usize = if (rleByte(block) != null) blk: {
        all_raw.* = false;
        break :blk 1;
    } else block.len;
    return std.math.add(usize, total, 3 + payload_len) catch return error.IntegerOverflow;
}

fn encodeRawFrameAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, options: NativeFrameOptions) Error!void {
    try emitFrameHeader(allocator, out, try checkedUsizeToU64(input.len), options);
    const block_size_max = try nativeBlockSizeMax(options);
    if (input.len == 0) {
        try emitRawBlock(allocator, out, "", true);
    } else {
        var offset: usize = 0;
        while (offset < input.len) {
            const end = @min(input.len, offset + block_size_max);
            try emitRawBlock(allocator, out, input[offset..end], end == input.len);
            offset = end;
        }
    }
    try emitContentChecksum(allocator, out, input, options);
}

