/// Zero-allocation cursor over a single native Zstandard frame's blocks.
/// Returned block offsets are relative to `frame`; once the last block is
/// consumed, `next_header_offset` points just past the optional content
/// checksum. Use `NativeStreamIterator` for concatenated streams with skippable
/// frames.
pub const NativeFrameBlockIterator = struct {
    frame: []const u8,
    header: NativeFrameHeader,
    next_header_offset: usize,
    finished: bool = false,

    pub fn init(frame: []const u8) Error!NativeFrameBlockIterator {
        const header = try inspectNativeFrameHeader(frame);
        return .{
            .frame = frame,
            .header = header,
            .next_header_offset = header.payload_offset,
        };
    }

    pub fn next(self: *NativeFrameBlockIterator) Error!?NativeFrameBlockHeader {
        if (self.finished) return null;
        const block = try inspectNativeFrameBlockAt(self.frame, self.next_header_offset);
        self.next_header_offset = block.next_header_offset;
        if (block.last) {
            if (self.header.has_checksum) {
                if (self.frame.len - self.next_header_offset < 4) return error.TruncatedFrame;
                self.next_header_offset += 4;
            }
            self.finished = true;
        }
        return block;
    }
};

/// One non-skippable frame discovered inside a concatenated native Zstandard
/// stream. Slices borrow from the stream passed to `iterateNativeStream`.
pub const NativeStreamFrame = struct {
    offset: usize,
    bytes: []const u8,
    header: NativeFrameHeader,

    pub fn blockIterator(self: NativeStreamFrame) Error!NativeFrameBlockIterator {
        return try NativeFrameBlockIterator.init(self.bytes);
    }
};

/// One skippable frame discovered inside a concatenated native Zstandard stream.
pub const NativeStreamSkippableFrame = struct {
    offset: usize,
    bytes: []const u8,
    payload: []const u8,
    header: NativeSkippableFrameHeader,
};

/// Stream iterator item; all slices borrow from the input passed to
/// `iterateNativeStream`.
pub const NativeStreamElement = union(enum) {
    frame: NativeStreamFrame,
    skippable: NativeStreamSkippableFrame,
};

/// Zero-allocation cursor over concatenated native Zstandard frames and
/// skippable metadata frames. It validates frame boundaries before yielding so
/// callers can inspect frame/block layout without decoded-output allocation.
pub const NativeStreamIterator = struct {
    frames: []const u8,
    next_offset: usize = 0,

    pub fn init(frames: []const u8) NativeStreamIterator {
        return .{ .frames = frames };
    }

    pub fn next(self: *NativeStreamIterator) Error!?NativeStreamElement {
        if (self.next_offset >= self.frames.len) return null;
        if (self.frames.len - self.next_offset < 4) return error.TruncatedFrame;

        const start = self.next_offset;
        const magic = std.mem.readInt(u32, self.frames[start..][0..4], .little);
        if (magic == frame_magic_u32) {
            const end = try findNativeFrameEnd(self.frames, start);
            const bytes = self.frames[start..end];
            const header = try inspectNativeFrameHeader(bytes);
            self.next_offset = end;
            return .{ .frame = .{
                .offset = start,
                .bytes = bytes,
                .header = header,
            } };
        } else if (magic >= skippable_magic_min and magic <= skippable_magic_max) {
            const header = try inspectNativeSkippableFrame(self.frames[start..]);
            const end = start + header.next_frame_offset;
            self.next_offset = end;
            return .{ .skippable = .{
                .offset = start,
                .bytes = self.frames[start..end],
                .payload = self.frames[start + header.payload_offset .. end],
                .header = header,
            } };
        } else {
            return error.InvalidMagic;
        }
    }
};

pub fn iterateNativeFrameBlocks(frame: []const u8) Error!NativeFrameBlockIterator {
    return try NativeFrameBlockIterator.init(frame);
}

pub fn iterateNativeStream(frames: []const u8) NativeStreamIterator {
    return NativeStreamIterator.init(frames);
}

const RawOrRleFrameHeader = NativeFrameHeader;

fn validateBlockSize(header: RawOrRleFrameHeader, block_type: u32, block_len: usize) Error!void {
    // For raw/RLE blocks the header size is the regenerated byte count and must
    // fit the frame block limit directly. For compressed blocks it is the
    // compressed payload length; the literal-only decoder validates the
    // regenerated size after parsing the literals section.
    if (block_type == 2) {
        if (block_len > std.compress.zstd.block_size_max) return error.CorruptFrame;
    } else if (block_len > header.block_size_max) {
        return error.CorruptFrame;
    }
}

fn validateNativeDictionary(header: NativeFrameHeader, dictionary: ?NativeDictionary) Error![]const u8 {
    if (header.dictionary_id == 0)
        return if (dictionary) |dict| dict.content else &.{};
    const dict = dictionary orelse return error.NeedDictionary;
    if (dict.id != header.dictionary_id) return error.NeedDictionary;
    // The native subset currently uses preset dictionaries as external history
    // for sequence matches. Raw/RLE/literals-only frames decode identically, but
    // this explicit validation path lets callers enforce Dictionary_ID policy
    // without hidden global state.
    return dict.content;
}

fn initialSequenceFrameState(dictionary: ?NativeDictionary) Error!SequenceFrameState {
    const dict = dictionary orelse return .{};
    const bytes = dict.standard_bytes orelse return .{};
    return try parseStandardDictionaryState(dict, bytes);
}

fn parseStandardDictionaryState(dict: NativeDictionary, bytes: []const u8) Error!SequenceFrameState {
    const view = try inspectStandardDictionary(bytes);
    if (view.id != dict.id or view.content.ptr != dict.content.ptr or view.content.len != dict.content.len)
        return error.InvalidDictionaryMetadata;
    var offset: usize = 8;
    var reader: std.Io.Reader = .fixed(bytes[offset..]);
    var remaining: std.Io.Limit = .limited(bytes.len - offset);
    const huffman_tree = decodeStdZstdHuffmanTree(&reader, &remaining) catch return error.InvalidDictionaryMetadata;
    offset += reader.seek;
    const parse_table = struct {
        fn run(data: []const u8, position: *usize, bases: []const usize, bits: []const u8, symbol_count: usize, max_log: u4) Error!SequenceFseTable {
            return readFseSequenceTable(data, position, bases, bits, symbol_count, max_log) catch |err| switch (err) {
                error.TruncatedFrame => error.TruncatedFrame,
                else => error.InvalidDictionaryMetadata,
            };
        }
    }.run;
    const offset_fse = try parse_table(bytes, &offset, &of_base, &of_bits, sequence_table_symbol_count_max.offset, sequence_table_accuracy_log_max.offset);
    const match_fse = try parse_table(bytes, &offset, &ml_base, &ml_bits, sequence_table_symbol_count_max.match, sequence_table_accuracy_log_max.match);
    const literal_fse = try parse_table(bytes, &offset, &ll_base, &ll_bits, sequence_table_symbol_count_max.literal, sequence_table_accuracy_log_max.literal);
    if (offset + 12 != view.content_offset) return error.InvalidDictionaryMetadata;
    return .{
        .previous_tables = .{
            .ll_mode = .compressed,
            .of_mode = .compressed,
            .ml_mode = .compressed,
            .literal_rle = null,
            .offset_rle = null,
            .match_rle = null,
            .literal_fse = literal_fse,
            .offset_fse = offset_fse,
            .match_fse = match_fse,
        },
        .repeated_offsets = .{ view.repcodes[0], view.repcodes[1], view.repcodes[2] },
        .previous_huffman_tree = huffman_tree,
    };
}

fn dictionaryForNativeFrame(frame: []const u8, dictionary_set: NativeDictionarySet) Error!?NativeDictionary {
    const header = try inspectNativeFrameHeader(frame);
    if (header.dictionary_id == 0) return null;
    return dictionary_set.find(header.dictionary_id) orelse error.NeedDictionary;
}

fn decodeRawOrRleZstandardFrameInto(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    frame: []const u8,
    offset: *usize,
    dictionary: ?NativeDictionary,
) Error!void {
    const header = try parseRawOrRleFrameHeaderWithOptions(frame, offset, true);
    const dictionary_history = try validateNativeDictionary(header, dictionary);
    const frame_out_start = out.items.len;
    if (header.content_size) |size| try out.ensureUnusedCapacity(allocator, try checkedU64ToUsize(size));
    var frame_state = try initialSequenceFrameState(dictionary);

    while (true) {
        if (frame.len - offset.* < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset.*..][0..3], .little);
        offset.* += 3;
        const last = (block_header & 0x1) != 0;
        const block_type = (block_header >> 1) & 0x3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);

        switch (block_type) {
            0 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                try out.appendSlice(allocator, frame[offset.*..][0..block_len]);
                offset.* += block_len;
            },
            1 => {
                if (frame.len - offset.* < 1) return error.TruncatedFrame;
                const byte = frame[offset.*];
                offset.* += 1;
                try out.appendNTimes(allocator, byte, block_len);
            },
            2 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                try decodeLiteralOnlyCompressedBlockInto(allocator, out, frame[offset.*..][0..block_len], header.block_size_max, frame_out_start, dictionary_history, &frame_state, sequence_continuation.forLastBlock(last));
                offset.* += block_len;
            },
            else => return error.CorruptFrame,
        }

        if (last) break;
    }

    const decoded = out.items[frame_out_start..];
    if (header.content_size) |size| {
        if (try checkedUsizeToU64(decoded.len) != size) return error.SizeMismatch;
    }

    if (header.has_checksum) {
        if (frame.len - offset.* < 4) return error.TruncatedFrame;
        const expected = std.mem.readInt(u32, frame[offset.*..][0..4], .little);
        const actual: u32 = @truncate(std.hash.XxHash64.hash(0, decoded));
        if (actual != expected) return error.ChecksumMismatch;
        offset.* += 4;
    }
}

fn decodeRawOrRleZstandardFrameIntoBuffer(
    frame: []const u8,
    offset: *usize,
    output: []u8,
    written: *usize,
    dictionary: ?NativeDictionary,
) Error!void {
    const header = try parseRawOrRleFrameHeaderWithOptions(frame, offset, true);
    const dictionary_history = try validateNativeDictionary(header, dictionary);
    const frame_out_start = written.*;
    if (header.content_size) |size| {
        const needed = try checkedU64ToUsize(size);
        if (output.len - written.* < needed) return error.OutputTooSmall;
    }
    const frame_output = if (header.content_size) |size| blk: {
        const frame_end = std.math.add(usize, frame_out_start, try checkedU64ToUsize(size)) catch return error.IntegerOverflow;
        break :blk output[0..frame_end];
    } else output;
    var frame_state = try initialSequenceFrameState(dictionary);

    while (true) {
        if (frame.len - offset.* < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset.*..][0..3], .little);
        offset.* += 3;
        const last = (block_header & 0x1) != 0;
        const block_type = (block_header >> 1) & 0x3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);

        switch (block_type) {
            0 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                if (output.len - written.* < block_len) return error.OutputTooSmall;
                @memcpy(output[written.*..][0..block_len], frame[offset.*..][0..block_len]);
                written.* += block_len;
                offset.* += block_len;
            },
            1 => {
                if (frame.len - offset.* < 1) return error.TruncatedFrame;
                if (output.len - written.* < block_len) return error.OutputTooSmall;
                const byte = frame[offset.*];
                offset.* += 1;
                @memset(output[written.*..][0..block_len], byte);
                written.* += block_len;
            },
            2 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                const retain_split_sequence_tables = !last and
                    nextBlockMayUsePreviousSequenceTables(frame, offset.* + block_len);
                frame_state.retain_sequence_tables = retain_split_sequence_tables;
                decodeLiteralOnlyCompressedBlockIntoBufferSelected(
                    frame[offset.*..][0..block_len],
                    frame_output,
                    written,
                    header.block_size_max,
                    frame_out_start,
                    dictionary_history,
                    &frame_state,
                    sequence_continuation.forLastBlock(last),
                    header.content_size != null,
                ) catch |err| switch (err) {
                    error.OutputTooSmall => if (header.content_size != null) return error.SizeMismatch else return err,
                    else => return err,
                };
                offset.* += block_len;
            },
            else => return error.CorruptFrame,
        }

        if (last) break;
    }

    const decoded = output[frame_out_start..written.*];
    if (header.content_size) |size| {
        if (try checkedUsizeToU64(decoded.len) != size) return error.SizeMismatch;
    }

    if (header.has_checksum) {
        if (frame.len - offset.* < 4) return error.TruncatedFrame;
        const expected = std.mem.readInt(u32, frame[offset.*..][0..4], .little);
        const actual: u32 = @truncate(std.hash.XxHash64.hash(0, decoded));
        if (actual != expected) return error.ChecksumMismatch;
        offset.* += 4;
    }
}

noinline fn decodeRawOrRleZstandardFrameIntoBufferWithSequenceWorkspace(
    frame: []const u8,
    offset: *usize,
    output: []u8,
    written: *usize,
    decoder: *NativeFrameDecoder,
) linksection(reusable_decode_text_section) Error!void {
    const header = try parseRawOrRleFrameHeaderWithOptions(frame, offset, true);
    const dictionary_history = try validateNativeDictionary(header, null);
    const frame_out_start = written.*;
    if (header.content_size) |size| {
        const needed = try checkedU64ToUsize(size);
        if (output.len - written.* < needed) return error.OutputTooSmall;
    }
    const frame_output = if (header.content_size) |size| blk: {
        const frame_end = std.math.add(usize, frame_out_start, try checkedU64ToUsize(size)) catch return error.IntegerOverflow;
        break :blk output[0..frame_end];
    } else output;
    var frame_state: SequenceFrameState = .{};
    const use_sequence_cache = sequence_decode_policy.preferReusableDecodeCache(header.content_size);
    var sequence_workspace: ?*SequenceDecodeWorkspace = null;

    while (true) {
        if (frame.len - offset.* < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset.*..][0..3], .little);
        offset.* += 3;
        const last = (block_header & 0x1) != 0;
        const block_type = (block_header >> 1) & 0x3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);

        switch (block_type) {
            0 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                if (output.len - written.* < block_len) return error.OutputTooSmall;
                @memcpy(output[written.*..][0..block_len], frame[offset.*..][0..block_len]);
                written.* += block_len;
                offset.* += block_len;
            },
            1 => {
                if (frame.len - offset.* < 1) return error.TruncatedFrame;
                if (output.len - written.* < block_len) return error.OutputTooSmall;
                const byte = frame[offset.*];
                offset.* += 1;
                @memset(output[written.*..][0..block_len], byte);
                written.* += block_len;
            },
            2 => {
                if (frame.len - offset.* < block_len) return error.TruncatedFrame;
                if (use_sequence_cache and sequence_workspace == null)
                    sequence_workspace = decoder.sequenceWorkspace();
                if (sequence_workspace) |workspace| {
                    decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspaceSelected(
                        frame[offset.*..][0..block_len],
                        frame_output,
                        written,
                        header.block_size_max,
                        frame_out_start,
                        dictionary_history,
                        &frame_state,
                        sequence_continuation.forLastBlock(last),
                        workspace,
                        header.content_size != null,
                    ) catch |err| switch (err) {
                        error.OutputTooSmall => if (header.content_size != null) return error.SizeMismatch else return err,
                        else => return err,
                    };
                } else {
                    decodeLiteralOnlyCompressedBlockIntoBufferSelected(
                        frame[offset.*..][0..block_len],
                        frame_output,
                        written,
                        header.block_size_max,
                        frame_out_start,
                        dictionary_history,
                        &frame_state,
                        sequence_continuation.forLastBlock(last),
                        header.content_size != null,
                    ) catch |err| switch (err) {
                        error.OutputTooSmall => if (header.content_size != null) return error.SizeMismatch else return err,
                        else => return err,
                    };
                }
                offset.* += block_len;
            },
            else => return error.CorruptFrame,
        }

        if (last) break;
    }

    const decoded = output[frame_out_start..written.*];
    if (header.content_size) |size| {
        if (try checkedUsizeToU64(decoded.len) != size) return error.SizeMismatch;
    }
    if (header.has_checksum) {
        if (frame.len - offset.* < 4) return error.TruncatedFrame;
        const expected = std.mem.readInt(u32, frame[offset.*..][0..4], .little);
        const actual: u32 = @truncate(std.hash.XxHash64.hash(0, decoded));
        if (actual != expected) return error.ChecksumMismatch;
        offset.* += 4;
    }
}

fn decodeLiteralOnlyCompressedBlockInto(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    block_size_max: usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
) Error!void {
    const start = out.items.len;
    // Size preflight and decode both advance sequence-table and repeat-offset
    // state. Use a scratch copy for the preflight so the real state is advanced
    // exactly once by the decode path below.
    var preflight_state = frame_state.*;
    if (frame_output_start > out.items.len) return error.CorruptFrame;
    const frame_decoded_before_block = out.items.len - frame_output_start;
    const initial_history_len = std.math.add(usize, dictionary_history.len, frame_decoded_before_block) catch return error.IntegerOverflow;
    const decoded_len = try compressedLiteralOnlyBlockDecodedSize(block, block_size_max, initial_history_len, &preflight_state);
    try out.ensureUnusedCapacity(allocator, decoded_len);
    var written = out.items.len;
    try decodeLiteralOnlyCompressedBlockIntoBuffer(block, out.items.ptr[0..out.capacity], &written, block_size_max, frame_output_start, dictionary_history, frame_state, continuation, false);
    out.items.len = written;
    if (out.items.len - start != decoded_len) return error.SizeMismatch;
}

inline fn decodeLiteralOnlyCompressedBlockIntoBufferSelected(
    block: []const u8,
    output: []u8,
    written: *usize,
    block_size_max: usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    allow_wildcopy: bool,
) Error!void {
    if (allow_wildcopy)
        return decodeLiteralOnlyCompressedBlockIntoBuffer(block, output, written, block_size_max, frame_output_start, dictionary_history, frame_state, continuation, true);
    return decodeLiteralOnlyCompressedBlockIntoBuffer(block, output, written, block_size_max, frame_output_start, dictionary_history, frame_state, continuation, false);
}

fn decodeLiteralOnlyCompressedBlockIntoBuffer(
    block: []const u8,
    output: []u8,
    written: *usize,
    block_size_max: usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    comptime allow_wildcopy: bool,
) Error!void {
    const section = try parseLiteralsSection(block, frame_state);
    if (section.regenerated_size > block_size_max) return error.CorruptFrame;
    try validateSupportedLiteralSection(section);
    if (section.sequence_count != 0) return try decodeRleSequencesCompressedBlockIntoBuffer(block, section, output, written, frame_output_start, dictionary_history, frame_state, continuation, allow_wildcopy);
    try expectConsumedBlock(section.sequence_payload_offset, block.len);
    if (section.regenerated_size >= 16 * 1024 and section.huffman_streams == .four) {
        if (output.len - written.* < section.regenerated_size) return error.OutputTooSmall;
        if (try decodeLargeFourStreamHuffman(section, output[written.*..][0..section.regenerated_size])) {
            written.* += section.regenerated_size;
            return;
        }
    }
    try copyLiteralsFromSection(block, section, 0, output, written, section.regenerated_size);
}

inline fn decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspaceSelected(
    block: []const u8,
    output: []u8,
    written: *usize,
    block_size_max: usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    workspace: *SequenceDecodeWorkspace,
    allow_wildcopy: bool,
) Error!void {
    if (allow_wildcopy)
        return decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspace(block, output, written, block_size_max, frame_output_start, dictionary_history, frame_state, continuation, workspace, true);
    return decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspace(block, output, written, block_size_max, frame_output_start, dictionary_history, frame_state, continuation, workspace, false);
}

fn decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspace(
    block: []const u8,
    output: []u8,
    written: *usize,
    block_size_max: usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    workspace: *SequenceDecodeWorkspace,
    comptime allow_wildcopy: bool,
) Error!void {
    const section = try parseLiteralsSectionWithPreviousTreeAndCache(
        block,
        &frame_state.previous_huffman_tree,
        &workspace.huffman,
        null,
    );
    if (section.regenerated_size > block_size_max) return error.CorruptFrame;
    try validateSupportedLiteralSection(section);
    if (section.sequence_count >= 2 and section.sequence_count <= 256 and
        !continuation.retainsState() and dictionary_history.len == 0 and
        (section.kind == .compressed or section.kind == .treeless) and
        section.huffman_tree.?.max_bit_count > 0 and
        section.huffman_tree.?.max_bit_count <= NarrowHuffmanLiteralLookup.bit_width and
        section.sequence_payload_offset < block.len and block[section.sequence_payload_offset] == 0x20)
    {
        return decodeSmallHuffmanBlockWithSequenceWorkspace(block, &section, output, written, frame_output_start, frame_state.repeated_offsets, workspace);
    }
    if (section.sequence_count != 0) return try decodeRleSequencesCompressedBlockIntoBufferWithSequenceWorkspace(
        block,
        section,
        output,
        written,
        frame_output_start,
        dictionary_history,
        frame_state,
        continuation,
        workspace,
        allow_wildcopy,
    );
    try expectConsumedBlock(section.sequence_payload_offset, block.len);
    if (section.regenerated_size >= 16 * 1024 and section.huffman_streams == .four) {
        if (output.len - written.* < section.regenerated_size) return error.OutputTooSmall;
        if (try decodeLargeFourStreamHuffman(section, output[written.*..][0..section.regenerated_size])) {
            written.* += section.regenerated_size;
            return;
        }
    }
    try copyLiteralsFromSection(block, section, 0, output, written, section.regenerated_size);
}

fn copyLiteralsFromSection(
    block: []const u8,
    section: LiteralOnlySection,
    literal_offset: usize,
    output: []u8,
    written: *usize,
    literal_len: usize,
) Error!void {
    if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < literal_len) {
        return error.CorruptFrame;
    }
    if (literal_len == 0) {
        if ((section.kind == .compressed or section.kind == .treeless) and literal_offset == section.regenerated_size) {
            if (written.* > output.len) return error.OutputTooSmall;
            try copyHuffmanLiteralsFromSection(block, section, literal_offset, output[written.*..][0..0]);
        }
        return;
    }
    if (output.len - written.* < literal_len) return error.OutputTooSmall;
    switch (section.kind) {
        .raw => {
            @memcpy(
                output[written.*..][0..literal_len],
                block[section.literal_payload_offset + literal_offset ..][0..literal_len],
            );
        },
        .rle => {
            if (section.regenerated_size == 0) return error.CorruptFrame;
            @memset(output[written.*..][0..literal_len], block[section.literal_payload_offset]);
        },
        .compressed, .treeless => try copyHuffmanLiteralsFromSection(
            block,
            section,
            literal_offset,
            output[written.*..][0..literal_len],
        ),
    }
    written.* += literal_len;
}

fn copyHuffmanLiteralsFromSection(
    block: []const u8,
    section: LiteralOnlySection,
    literal_offset: usize,
    dest: []u8,
) Error!void {
    // Literal copies are requested in sequence order, but the current minimal
    // slice keeps no per-section cursor so preflight and decode can share the
    // same immutable `LiteralOnlySection`. Re-reading from the start is slower
    // for many small literal runs, yet it preserves exact behavior while this
    // native Zstd path is still correctness-first and sequence/FSE support is
    // incomplete.
    const huffman_tree = section.huffman_tree orelse return error.CorruptFrame;
    const end = std.math.add(usize, literal_offset, dest.len) catch return error.IntegerOverflow;
    var decoded_index: usize = 0;
    var output_index: usize = 0;
    var lookup: HuffmanLiteralLookup = undefined;
    const lookup_complete = lookup.buildComplete(&huffman_tree);
    if (!lookup_complete)
        lookup = HuffmanLiteralLookup.build(&huffman_tree);
    var cursor = try initHuffmanLiteralCursor(block, section);
    while (decoded_index < end) {
        // Large literal-only sections spend almost every cycle in lookup hits.
        // Keep their rare stream-tail tree walk out of line without imposing
        // that call boundary on short or sequence-interleaved literal runs.
        const symbol = if (section.sequence_count == 0 and section.regenerated_size >= 16 * 1024)
            try cursor.readFullSectionSymbol(&huffman_tree, &lookup)
        else
            try cursor.readSymbol(&huffman_tree, &lookup);
        if (decoded_index >= literal_offset) dest[output_index] = symbol;
        if (decoded_index >= literal_offset) output_index += 1;
        decoded_index += 1;
    }
    if (end == section.regenerated_size) try cursor.expectEnd();
}

noinline fn decodeLargeFourStreamHuffman(
    section: LiteralOnlySection,
    dest: []u8,
) align(64) linksection(huffman_only_decode_text_section) Error!bool {
    const huffman_tree = section.huffman_tree orelse return false;
    const use_wide_x2 = huffman_tree.max_bit_count == 7 and
        section.regenerated_size >= 64 * 1024 and
        section.compressed_size * 1000 <= section.regenerated_size * 900;
    if ((!builtin.is_test or !test_disable_x2_huffman_decode) and
        section.regenerated_size >= split_x2_huffman_literal_min and
        (section.compressed_size * 1000 <= section.regenerated_size * 660 or use_wide_x2))
    {
        const streams = switch (section.huffman_streams) {
            .four => |four| four,
            else => return false,
        };
        const request: huffman_x2_abi.Request = .{
            .tree = &huffman_tree,
            .stream_ptrs = .{ streams[0].ptr, streams[1].ptr, streams[2].ptr, streams[3].ptr },
            .stream_lens = .{ streams[0].len, streams[1].len, streams[2].len, streams[3].len },
            .dest_ptr = dest.ptr,
            .dest_len = dest.len,
        };
        const status: huffman_x2_abi.Status = if (builtin.is_test) status: {
            break :status if (use_wide_x2)
                huffman_x2_test.decodeWideRequest(&request)
            else
                huffman_x2_test.decodeRequest(&request);
        } else if (use_wide_x2)
            @enumFromInt(vortZstdHuffmanWideX2Decode(&request))
        else
            @enumFromInt(vortZstdHuffmanX2Decode(&request));
        switch (status) {
            .success => {
                if (builtin.is_test) test_x2_huffman_decode_hits += 1;
                return true;
            },
            .unsupported => {},
            .truncated => return error.TruncatedFrame,
            .corrupt => return error.CorruptFrame,
        }
    }
    var lookup: CompleteHuffmanLiteralLookup = undefined;
    if (!lookup.buildComplete(&huffman_tree)) return false;
    const segment_len = (section.regenerated_size + 3) / 4;
    const streams = section.huffman_streams.four;
    var readers = [4]ReverseBitReader{
        try ReverseBitReader.init(streams[0]),
        try ReverseBitReader.init(streams[1]),
        try ReverseBitReader.init(streams[2]),
        try ReverseBitReader.init(streams[3]),
    };
    var positions = [4]usize{ 0, segment_len, segment_len * 2, segment_len * 3 };
    const ends = [4]usize{
        segment_len,
        segment_len * 2,
        segment_len * 3,
        section.regenerated_size,
    };
    const width = huffman_tree.max_bit_count;
    const total_bits: u6 = @as(u6, width) * 5;
    const mask = (@as(u64, 1) << width) - 1;
    if (readers[0].available() > 56 and
        readers[1].available() > 56 and
        readers[2].available() > 56 and
        readers[3].available() > 56)
    {
        decodeFourStreamHuffmanReservoir(&readers, &positions, ends, width, &lookup, dest);
    }
    for (0..4) |stream_index| {
        var stream_cursor = HuffmanLiteralCursor{
            .streams = .one,
            .reader = readers[stream_index],
        };
        var segment_start = positions[stream_index];
        const segment_end = ends[stream_index];
        while (segment_end - segment_start >= 5 and stream_cursor.reader.available() >= @as(usize, huffman_tree.max_bit_count) * 5) {
            const bits = stream_cursor.reader.peekBulkHuffmanFive(width);
            var consumed: u6 = 0;
            inline for (0..5) |index| {
                const shift = total_bits - width - consumed;
                const prefix: usize = @intCast((bits >> @intCast(shift)) & mask);
                const entry = lookup.lookupAssumeComplete(prefix << @intCast(11 - width));
                dest[segment_start + index] = entry.symbol;
                consumed += @intCast(entry.bit_count);
            }
            stream_cursor.reader.skipBulkHuffman(consumed);
            segment_start += 5;
        }
        while (segment_end - segment_start >= 2 and stream_cursor.reader.available() >= @as(usize, huffman_tree.max_bit_count) * 2) {
            const pair = stream_cursor.reader.peekBulkHuffmanPair(width);
            const first = lookup.lookupAssumeComplete((pair >> width) << @intCast(11 - width));
            const first_bit_count: u4 = @intCast(first.bit_count);
            const second_prefix = (pair >> @intCast(width - first_bit_count)) & ((@as(u32, 1) << width) - 1);
            const second = lookup.lookupAssumeComplete(second_prefix << @intCast(11 - width));
            stream_cursor.reader.skipBulkHuffman(@intCast(@as(u9, first.bit_count) + second.bit_count));
            dest[segment_start] = first.symbol;
            dest[segment_start + 1] = second.symbol;
            segment_start += 2;
        }
        while (segment_start < segment_end and stream_cursor.reader.available() >= huffman_tree.max_bit_count) : (segment_start += 1) {
            const prefix = stream_cursor.reader.peekBulkHuffman(width);
            const entry = lookup.lookupAssumeComplete(prefix << @intCast(11 - width));
            stream_cursor.reader.skipBulkHuffman(entry.bit_count);
            dest[segment_start] = entry.symbol;
        }
        while (segment_start < segment_end) : (segment_start += 1) {
            dest[segment_start] = try readHuffmanLiteralSymbolFromCursorCold(&stream_cursor, &huffman_tree);
        }
        try stream_cursor.expectEnd();
    }
    return true;
}

noinline fn decodeFourStreamHuffmanReservoir(
    readers: *[4]ReverseBitReader,
    positions: *[4]usize,
    ends: [4]usize,
    width: u4,
    lookup: *const CompleteHuffmanLiteralLookup,
    dest: []u8,
) align(64) linksection(huffman_only_decode_text_section) void {
    var output_positions = positions.*;
    var reservoirs = [4]huffman_reservoir.Reservoir{
        huffman_reservoir.Reservoir.init(readers[0]) orelse unreachable,
        huffman_reservoir.Reservoir.init(readers[1]) orelse unreachable,
        huffman_reservoir.Reservoir.init(readers[2]) orelse unreachable,
        huffman_reservoir.Reservoir.init(readers[3]) orelse unreachable,
    };
    if (width <= 7) {
        while (ends[3] - output_positions[3] >= 8 and
            reservoirs[0].canDecodeEight(width) and
            reservoirs[1].canDecodeEight(width) and
            reservoirs[2].canDecodeEight(width) and
            reservoirs[3].canDecodeEight(width))
        {
            for (0..4) |stream_index| {
                var decoded: [8]u8 = undefined;
                inline for (0..8) |symbol_index| {
                    const prefix = reservoirs[stream_index].peek(CompleteHuffmanLiteralLookup.bit_width);
                    const entry = lookup.lookupAssumeComplete(prefix);
                    decoded[symbol_index] = entry.symbol;
                    reservoirs[stream_index].consume(entry.bit_count);
                }
                dest[output_positions[stream_index]..][0..8].* = decoded;
            }
            inline for (0..4) |stream_index| {
                reservoirs[stream_index].reload();
                output_positions[stream_index] += 8;
            }
        }
    }
    while (ends[3] - output_positions[3] >= 5 and
        reservoirs[0].canDecodeFive(width) and
        reservoirs[1].canDecodeFive(width) and
        reservoirs[2].canDecodeFive(width) and
        reservoirs[3].canDecodeFive(width))
    {
        inline for (0..5) |symbol_index| {
            inline for (0..4) |stream_index| {
                // The complete 11-bit table already replicates every shorter
                // canonical prefix. Index it directly from the reservoir's
                // high bits, matching libzstd's fast X1 loop and avoiding an
                // extra width-dependent shift for every decoded symbol.
                const prefix = reservoirs[stream_index].peek(CompleteHuffmanLiteralLookup.bit_width);
                const entry = lookup.lookupAssumeComplete(prefix);
                dest[output_positions[stream_index] + symbol_index] = entry.symbol;
                reservoirs[stream_index].consume(entry.bit_count);
            }
        }
        inline for (0..4) |stream_index| {
            reservoirs[stream_index].reload();
            output_positions[stream_index] += 5;
        }
    }
    inline for (0..4) |stream_index| {
        readers[stream_index].remaining_bits = reservoirs[stream_index].remainingBits();
        positions[stream_index] = output_positions[stream_index];
    }
}

const HuffmanLiteralDecodeState = struct {
    cursor: HuffmanLiteralCursor,
    tree: StdZstdHuffmanTree,
    lookup: HuffmanLiteralLookup,
    decoded: usize = 0,
};

fn initHuffmanLiteralDecodeState(block: []const u8, section: LiteralOnlySection) Error!?HuffmanLiteralDecodeState {
    if (section.kind != .compressed and section.kind != .treeless) return null;
    const tree = section.huffman_tree orelse return error.CorruptFrame;
    var lookup: HuffmanLiteralLookup = undefined;
    if (!lookup.buildComplete(&tree))
        lookup = HuffmanLiteralLookup.build(&tree);
    return .{
        .cursor = try initHuffmanLiteralCursor(block, section),
        .tree = tree,
        .lookup = lookup,
    };
}

fn copyLiteralsFromHuffmanState(
    state: *HuffmanLiteralDecodeState,
    section: *const LiteralOnlySection,
    literal_offset: usize,
    dest: []u8,
) Error!void {
    if (literal_offset != state.decoded) return error.CorruptFrame;
    if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < dest.len) return error.CorruptFrame;
    for (dest) |*out| {
        out.* = try readHuffmanLiteralSymbolFromCursorWithLookup(&state.cursor, &state.tree, &state.lookup);
        state.decoded += 1;
    }
    if (state.decoded == section.regenerated_size) try state.cursor.expectEnd();
}

/// Decode one sequence literal run with the common full-width lookup kept in
/// this loop. The generic state helper remains the cold path for a stream tail
/// or malformed prefix and owns all four-stream boundary validation.
inline fn copyLiteralsFromHuffmanStateFast(
    state: *HuffmanLiteralDecodeState,
    section: *const LiteralOnlySection,
    literal_offset: usize,
    dest: []u8,
) Error!void {
    if (literal_offset != state.decoded) return error.CorruptFrame;
    if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < dest.len) return error.CorruptFrame;
    for (dest) |*out| {
        if (state.tree.max_bit_count != 0 and state.cursor.reader.available() >= state.tree.max_bit_count) {
            const width = state.tree.max_bit_count;
            // The guard proves a full prefix remains in the current stream.
            // Use the unchecked bulk primitives here just as the whole-section
            // decoder does, leaving checked stream-tail handling below.
            const prefix = state.cursor.reader.peekBulkHuffman(width);
            if (state.lookup.lookup(prefix << @intCast(11 - width))) |entry| {
                state.cursor.reader.skipBulkHuffman(entry.bit_count);
                out.* = entry.symbol;
                state.decoded += 1;
                continue;
            }
        }
        out.* = try readHuffmanLiteralSymbolFromCursorCold(&state.cursor, &state.tree);
        state.decoded += 1;
    }
    if (state.decoded == section.regenerated_size) try state.cursor.expectEnd();
}

fn validateHuffmanLiteralsConsumed(block: []const u8, section: LiteralOnlySection) Error!void {
    if (section.kind != .compressed and section.kind != .treeless) return;
    const huffman_tree = section.huffman_tree orelse return error.CorruptFrame;
    var cursor = try initHuffmanLiteralCursor(block, section);
    const lookup = HuffmanLiteralLookup.build(&huffman_tree);
    for (0..section.regenerated_size) |_| {
        _ = try cursor.readSymbol(&huffman_tree, &lookup);
    }
    try cursor.expectEnd();
}

fn huffmanLiteralStreamReader(block: []const u8, section: LiteralOnlySection) Error!ReverseBitReader {
    const stream_end = std.math.add(usize, section.literal_payload_offset, section.compressed_size) catch return error.IntegerOverflow;
    if (section.huffman_stream_offset > stream_end or stream_end > block.len) return error.CorruptFrame;
    return try ReverseBitReader.init(block[section.huffman_stream_offset..stream_end]);
}

const HuffmanLiteralCursor = struct {
    streams: HuffmanLiteralStreams,
    stream_index: usize = 0,
    reader: ReverseBitReader,

    fn read(self: *HuffmanLiteralCursor, bit_count: u4) Error!usize {
        return self.reader.read(bit_count) catch |err| switch (err) {
            error.TruncatedFrame => {
                if (self.streams == .four and self.stream_index < 3) {
                    self.stream_index += 1;
                    self.reader = try ReverseBitReader.init(self.streams.four[self.stream_index]);
                    return self.reader.read(bit_count) catch |next_err| switch (next_err) {
                        error.TruncatedFrame => return error.CorruptFrame,
                        else => |e| return e,
                    };
                }
                return error.CorruptFrame;
            },
            else => |e| return e,
        };
    }

    fn expectEnd(self: *HuffmanLiteralCursor) Error!void {
        switch (self.streams) {
            .one => try self.reader.expectEnd(),
            .four => {
                if (self.stream_index != 3) return error.CorruptFrame;
                try self.reader.expectEnd();
            },
            .none => return error.CorruptFrame,
        }
    }

    fn readSymbol(
        self: *HuffmanLiteralCursor,
        tree: *const StdZstdHuffmanTree,
        lookup: *const HuffmanLiteralLookup,
    ) Error!u8 {
        const width: u8 = @intCast(@min(@as(usize, tree.max_bit_count), self.reader.available()));
        if (width == tree.max_bit_count and width != 0) {
            const prefix = try self.reader.peekSmall(@intCast(width));
            if (lookup.lookup(prefix << @intCast(11 - width))) |entry| {
                try self.reader.skip(entry.bit_count);
                return entry.symbol;
            }
        }
        // A valid four-stream section may end the current stream with fewer
        // than `max_bit_count` bits. Decode that tail through the canonical
        // tree, which also performs the stream transition when needed.
        return try readHuffmanLiteralSymbolFromCursor(self, tree);
    }

    /// Full-section literal decode keeps the rare stream-tail tree walk out of
    /// the dominant lookup loop. Sequence interleaving continues to use
    /// `readSymbol`, whose inlining choices are better for short literal runs.
    fn readFullSectionSymbol(
        self: *HuffmanLiteralCursor,
        tree: *const StdZstdHuffmanTree,
        lookup: *const HuffmanLiteralLookup,
    ) Error!u8 {
        const width: u8 = @intCast(@min(@as(usize, tree.max_bit_count), self.reader.available()));
        if (width == tree.max_bit_count and width != 0) {
            const prefix = try self.reader.peekSmall(@intCast(width));
            if (lookup.lookup(prefix << @intCast(11 - width))) |entry| {
                try self.reader.skip(entry.bit_count);
                return entry.symbol;
            }
        }
        return readHuffmanLiteralSymbolFromCursorCold(self, tree);
    }

    /// Decode a symbol while the caller guarantees a full-width prefix remains
    /// in the current Huffman stream. Four-stream literal sections have known
    /// regenerated segment lengths, so their bulk loops can keep stream-tail
    /// handling outside this per-symbol path.
    fn readFullWidthSymbol(
        self: *HuffmanLiteralCursor,
        width: u4,
        lookup: *const HuffmanLiteralLookup,
    ) Error!u8 {
        const prefix = self.reader.peekBulkHuffman(width);
        const entry = lookup.lookup(prefix << @intCast(11 - width)) orelse
            return error.CorruptFrame;
        self.reader.skipBulkHuffman(entry.bit_count);
        return entry.symbol;
    }
};

fn initHuffmanLiteralCursor(block: []const u8, section: LiteralOnlySection) Error!HuffmanLiteralCursor {
    switch (section.huffman_streams) {
        .one => return .{
            .streams = .one,
            .reader = try huffmanLiteralStreamReader(block, section),
        },
        .four => |streams| return .{
            .streams = .{ .four = streams },
            .reader = try ReverseBitReader.init(streams[0]),
        },
        .none => return error.CorruptFrame,
    }
}

fn readHuffmanLiteralSymbolFromCursor(cursor: *HuffmanLiteralCursor, huffman_tree: *const StdZstdHuffmanTree) Error!u8 {
    const max_bit_count = huffman_tree.max_bit_count;
    const starting_bit_count = StdZstdHuffmanTree.weightToBitCount(
        huffman_tree.nodes[huffman_tree.symbol_count_minus_one].weight,
        max_bit_count,
    );
    var bits_read: u4 = 0;
    var huffman_tree_index: usize = huffman_tree.symbol_count_minus_one;
    var bit_count_to_read = starting_bit_count;
    var prefix: u16 = 0;
    while (true) {
        const new_bits = try cursor.read(bit_count_to_read);
        prefix <<= bit_count_to_read;
        prefix |= @intCast(new_bits);
        bits_read += bit_count_to_read;
        const result = queryHuffmanTree(huffman_tree, huffman_tree_index, prefix) catch return error.CorruptFrame;

        switch (result) {
            .symbol => |symbol| return symbol,
            .index => |index| {
                huffman_tree_index = index;
                const bit_count = StdZstdHuffmanTree.weightToBitCount(
                    huffman_tree.nodes[index].weight,
                    max_bit_count,
                );
                if (bit_count <= bits_read) return error.CorruptFrame;
                bit_count_to_read = bit_count - bits_read;
            },
        }
    }
}

fn queryHuffmanTree(
    tree: *const StdZstdHuffmanTree,
    index: usize,
    prefix: u16,
) error{HuffmanTreeIncomplete}!StdZstdHuffmanTree.Result {
    // Zig std's method currently receives the 1 KiB tree by value. Calling it
    // for every symbol therefore materializes a full memcpy in optimized code.
    // Keep the same search algorithm but borrow the immutable tree instead.
    var node = tree.nodes[index];
    const weight = node.weight;
    var i = index;
    while (node.weight == weight) {
        if (node.prefix == prefix) return .{ .symbol = node.symbol };
        if (i == 0) return error.HuffmanTreeIncomplete;
        i -= 1;
        node = tree.nodes[i];
    }
    return .{ .index = i };
}

noinline fn readHuffmanLiteralSymbolFromCursorCold(cursor: *HuffmanLiteralCursor, huffman_tree: *const StdZstdHuffmanTree) Error!u8 {
    // Zig std's tree query currently receives the 1 KiB tree by value. Keeping
    // this rare fallback out of line prevents that copy frame from spilling
    // the full-section lookup loop on every successfully table-decoded symbol.
    return readHuffmanLiteralSymbolFromCursor(cursor, huffman_tree);
}

fn readHuffmanLiteralSymbolFromCursorWithLookup(
    cursor: *HuffmanLiteralCursor,
    huffman_tree: *const StdZstdHuffmanTree,
    lookup: *const HuffmanLiteralLookup,
) Error!u8 {
    return try cursor.readSymbol(huffman_tree, lookup);
}

inline fn expectHuffmanLiteralCursorEnd(cursor: *HuffmanLiteralCursor) Error!void {
    return cursor.expectEnd();
}

fn compressedLiteralOnlyBlockDecodedSize(
    block: []const u8,
    block_size_max: usize,
    initial_output_len: usize,
    frame_state: *SequenceFrameState,
) Error!usize {
    const section = try parseLiteralsSection(block, frame_state);
    if (section.regenerated_size > block_size_max) return error.CorruptFrame;
    try validateSupportedLiteralSection(section);
    if (section.sequence_count == 0) {
        try expectConsumedBlock(section.sequence_payload_offset, block.len);
        try validateHuffmanLiteralsConsumed(block, section);
        return section.regenerated_size;
    }
    return try rleSequencesCompressedBlockDecodedSize(block, section, initial_output_len, frame_state);
}

fn validateSupportedLiteralSection(section: LiteralOnlySection) Error!void {
    switch (section.kind) {
        .raw, .rle => {},
        .compressed => {
            if (section.huffman_tree == null) return error.CorruptFrame;
            if (section.huffman_streams == .none) return error.CorruptFrame;
        },
        .treeless => {
            if (section.huffman_tree == null) return error.CorruptFrame;
            if (section.huffman_streams == .none) return error.CorruptFrame;
        },
    }
}

fn compressedLiteralOnlyBlockDecodedSizeLimited(
    block: []const u8,
    total: usize,
    frame_start: usize,
    max_output_len: usize,
    block_size_max: usize,
    frame_state: *SequenceFrameState,
) Error!usize {
    if (frame_start > total) return error.CorruptFrame;
    const decoded_len = try compressedLiteralOnlyBlockDecodedSize(block, block_size_max, total - frame_start, frame_state);
    return checkedAddWithinLimit(total, decoded_len, max_output_len);
}

const LiteralsKind = enum { raw, rle, compressed, treeless };

const LiteralOnlySection = struct {
    kind: LiteralsKind,
    size_format: u2,
    regenerated_size: usize,
    literal_payload_offset: usize,
    huffman_stream_offset: usize,
    huffman_streams: HuffmanLiteralStreams,
    compressed_size: usize = 0,
    sequence_count: usize,
    sequence_payload_offset: usize,
    huffman_tree: ?StdZstdHuffmanTree = null,
};

const HuffmanLiteralStreams = union(enum) {
    none,
    one,
    four: [4][]const u8,
};

fn parseLiteralsSection(block: []const u8, frame_state: *SequenceFrameState) Error!LiteralOnlySection {
    return parseLiteralsSectionWithPreviousTreeAndCache(block, &frame_state.previous_huffman_tree, null, null);
}

inline fn parseLiteralsSectionWithPreviousTree(
    block: []const u8,
    previous_huffman_tree: *?StdZstdHuffmanTree,
) Error!LiteralOnlySection {
    return parseLiteralsSectionWithPreviousTreeAndCache(block, previous_huffman_tree, null, null);
}

inline fn parseLiteralsSectionWithPreviousTreeAndNarrowLookup(
    block: []const u8,
    previous_huffman_tree: *?StdZstdHuffmanTree,
    prepared_narrow: *PreparedNarrowHuffmanLookup,
) Error!LiteralOnlySection {
    return parseLiteralsSectionWithPreviousTreeAndCache(block, previous_huffman_tree, null, prepared_narrow);
}

inline fn parseLiteralsSectionWithPreviousTreeAndCache(
    block: []const u8,
    previous_huffman_tree: *?StdZstdHuffmanTree,
    cache: ?*huffman_tree_cache.Cache(StdZstdHuffmanTree),
    prepared_narrow: ?*PreparedNarrowHuffmanLookup,
) Error!LiteralOnlySection {
    if (prepared_narrow) |prepared| prepared.complete = false;
    var offset: usize = 0;
    const literal_header = try parseLiteralsHeader(block, &offset);
    const literal_payload_offset = offset;
    const literal_payload_len: usize = switch (literal_header.kind) {
        .raw => literal_header.regenerated_size,
        .rle => 1,
        .compressed, .treeless => literal_header.compressed_size,
    };
    if (block.len - offset < literal_payload_len) return error.TruncatedFrame;
    offset += literal_payload_len;
    if (literal_header.kind == .treeless and previous_huffman_tree.* == null) {
        return error.CorruptFrame;
    }
    var huffman_tree: ?StdZstdHuffmanTree = null;
    var huffman_stream_offset = literal_payload_offset;
    var huffman_streams: HuffmanLiteralStreams = .none;
    switch (literal_header.kind) {
        .compressed => {
            const payload = block[literal_payload_offset..][0..literal_payload_len];
            if (if (cache) |tree_cache| tree_cache.find(payload) else null) |hit| {
                huffman_tree = hit.tree.*;
                huffman_stream_offset += hit.description_len;
                if (prepared_narrow) |prepared|
                    prepared.complete = prepared.table.buildComplete(&huffman_tree.?);
            } else {
                var reader: std.Io.Reader = .fixed(payload);
                var remaining: std.Io.Limit = .limited(payload.len);
                // FSE-compressed weights use the local linear canonical builder;
                // direct weights retain Zig std's parser and tree representation.
                huffman_tree = decodeFrameHuffmanTree(payload, &reader, &remaining, prepared_narrow) catch |err| switch (err) {
                    error.EndOfStream => return error.TruncatedFrame,
                    else => return error.CorruptFrame,
                };
                huffman_stream_offset += reader.seek;
                if (cache) |tree_cache| tree_cache.store(payload, reader.seek, huffman_tree.?);
            }
            previous_huffman_tree.* = huffman_tree;
            huffman_streams = try parseHuffmanLiteralStreams(block, literal_header.size_format, literal_payload_offset, huffman_stream_offset, literal_header.compressed_size);
        },
        .treeless => {
            huffman_tree = previous_huffman_tree.*.?;
            huffman_streams = try parseHuffmanLiteralStreams(block, literal_header.size_format, literal_payload_offset, huffman_stream_offset, literal_header.compressed_size);
        },
        .raw, .rle => {},
    }
    const sequence_count = try parseSequenceCount(block, &offset);
    return .{
        .kind = literal_header.kind,
        .size_format = literal_header.size_format,
        .regenerated_size = literal_header.regenerated_size,
        .literal_payload_offset = literal_payload_offset,
        .huffman_stream_offset = huffman_stream_offset,
        .huffman_streams = huffman_streams,
        .compressed_size = literal_header.compressed_size,
        .sequence_count = sequence_count,
        .sequence_payload_offset = offset,
        .huffman_tree = huffman_tree,
    };
}

fn parseHuffmanLiteralStreams(
    block: []const u8,
    size_format: u2,
    literal_payload_offset: usize,
    huffman_stream_offset: usize,
    compressed_size: usize,
) Error!HuffmanLiteralStreams {
    const stream_data_end = std.math.add(usize, literal_payload_offset, compressed_size) catch return error.IntegerOverflow;
    if (huffman_stream_offset > stream_data_end or stream_data_end > block.len) return error.CorruptFrame;
    const stream_data = block[huffman_stream_offset..stream_data_end];
    if (size_format == 0) return .one;
    if (stream_data.len < 6) return error.CorruptFrame;
    const stream_1_length: usize = std.mem.readInt(u16, stream_data[0..2], .little);
    const stream_2_length: usize = std.mem.readInt(u16, stream_data[2..4], .little);
    const stream_3_length: usize = std.mem.readInt(u16, stream_data[4..6], .little);
    const stream_1_start: usize = 6;
    const stream_2_start = std.math.add(usize, stream_1_start, stream_1_length) catch return error.IntegerOverflow;
    const stream_3_start = std.math.add(usize, stream_2_start, stream_2_length) catch return error.IntegerOverflow;
    const stream_4_start = std.math.add(usize, stream_3_start, stream_3_length) catch return error.IntegerOverflow;
    if (stream_4_start > stream_data.len) return error.CorruptFrame;
    return .{ .four = .{
        stream_data[stream_1_start..stream_2_start],
        stream_data[stream_2_start..stream_3_start],
        stream_data[stream_3_start..stream_4_start],
        stream_data[stream_4_start..],
    } };
}

const LiteralsHeaderInfo = struct {
    kind: LiteralsKind,
    size_format: u2,
    regenerated_size: usize,
    compressed_size: usize = 0,
};

fn parseLiteralsHeader(block: []const u8, offset: *usize) Error!LiteralsHeaderInfo {
    if (offset.* >= block.len) return error.TruncatedFrame;
    const byte0 = block[offset.*];
    offset.* += 1;
    const block_type = byte0 & 0x03;
    const size_format: u2 = @intCast((byte0 >> 2) & 0x03);
    const kind: LiteralsKind = switch (block_type) {
        0 => .raw,
        1 => .rle,
        2 => .compressed,
        else => .treeless,
    };

    if (kind == .compressed or kind == .treeless) {
        return try parseHuffmanLiteralsHeader(block, offset, byte0, size_format, kind);
    }

    const regenerated_size: usize = switch (size_format) {
        0, 2 => byte0 >> 3,
        1 => blk: {
            if (block.len - offset.* < 1) return error.TruncatedFrame;
            const byte1 = block[offset.*];
            offset.* += 1;
            break :blk @as(usize, byte0 >> 4) + (@as(usize, byte1) << 4);
        },
        else => blk: {
            if (block.len - offset.* < 2) return error.TruncatedFrame;
            const byte1 = block[offset.*];
            const byte2 = block[offset.* + 1];
            offset.* += 2;
            break :blk @as(usize, byte0 >> 4) + (@as(usize, byte1) << 4) + (@as(usize, byte2) << 12);
        },
    };
    return .{ .kind = kind, .size_format = size_format, .regenerated_size = regenerated_size };
}

fn parseHuffmanLiteralsHeader(
    block: []const u8,
    offset: *usize,
    byte0: u8,
    size_format: u2,
    kind: LiteralsKind,
) Error!LiteralsHeaderInfo {
    return switch (size_format) {
        0, 1 => blk: {
            if (block.len - offset.* < 2) return error.TruncatedFrame;
            const byte1 = block[offset.*];
            const byte2 = block[offset.* + 1];
            offset.* += 2;
            const value = @as(usize, byte0 >> 4) |
                (@as(usize, byte1) << 4) |
                (@as(usize, byte2) << 12);
            const regenerated_size = value & 0x3ff;
            const compressed_size = (value >> 10) & 0x3ff;
            if (compressed_size == 0) return error.CorruptFrame;
            if (size_format == 1 and compressed_size < 10) return error.CorruptFrame;
            break :blk .{ .kind = kind, .size_format = size_format, .regenerated_size = regenerated_size, .compressed_size = compressed_size };
        },
        2 => blk: {
            if (block.len - offset.* < 3) return error.TruncatedFrame;
            const byte1 = block[offset.*];
            const byte2 = block[offset.* + 1];
            const byte3 = block[offset.* + 2];
            offset.* += 3;
            const value = @as(usize, byte0 >> 4) |
                (@as(usize, byte1) << 4) |
                (@as(usize, byte2) << 12) |
                (@as(usize, byte3) << 20);
            const regenerated_size = value & 0x3fff;
            const compressed_size = (value >> 14) & 0x3fff;
            if (compressed_size < 10) return error.CorruptFrame;
            break :blk .{ .kind = kind, .size_format = size_format, .regenerated_size = regenerated_size, .compressed_size = compressed_size };
        },
        else => blk: {
            if (block.len - offset.* < 4) return error.TruncatedFrame;
            const byte1 = block[offset.*];
            const byte2 = block[offset.* + 1];
            const byte3 = block[offset.* + 2];
            const byte4 = block[offset.* + 3];
            offset.* += 4;
            const value = @as(usize, byte0 >> 4) |
                (@as(usize, byte1) << 4) |
                (@as(usize, byte2) << 12) |
                (@as(usize, byte3) << 20) |
                (@as(usize, byte4) << 28);
            const regenerated_size = value & 0x3ffff;
            const compressed_size = (value >> 18) & 0x3ffff;
            if (compressed_size < 10) return error.CorruptFrame;
            break :blk .{ .kind = kind, .size_format = size_format, .regenerated_size = regenerated_size, .compressed_size = compressed_size };
        },
    };
}

fn decodeStdZstdHuffmanTree(
    reader: *std.Io.Reader,
    remaining: *std.Io.Limit,
) StdZstdHuffmanTree.DecodeError!StdZstdHuffmanTree {
    return StdZstdHuffmanTree.decode(reader, remaining);
}

fn decodeFrameHuffmanTree(
    payload: []const u8,
    reader: *std.Io.Reader,
    remaining: *std.Io.Limit,
    prepared_narrow: ?*PreparedNarrowHuffmanLookup,
) StdZstdHuffmanTree.DecodeError!StdZstdHuffmanTree {
    // Direct-weight trees keep the established std implementation and call
    // shape. Only FSE-compressed weight headers use the linear stable builder.
    if (payload.len == 0) return error.EndOfStream;
    if (payload[0] >= 128) {
        const tree = try StdZstdHuffmanTree.decode(reader, remaining);
        if (prepared_narrow) |prepared|
            prepared.complete = prepared.table.buildComplete(&tree);
        return tree;
    }
    return decodeLinearZstdHuffmanTree(reader, remaining, prepared_narrow) catch |err| switch (err) {
        error.TruncatedFrame => error.EndOfStream,
        else => error.MalformedHuffmanTree,
    };
}

noinline fn decodeLinearZstdHuffmanTree(
    reader: *std.Io.Reader,
    remaining: *std.Io.Limit,
    prepared_narrow: ?*PreparedNarrowHuffmanLookup,
) linksection(huffman_build_text_section) Error!StdZstdHuffmanTree {
    remaining.* = remaining.subtract(1) orelse return error.TruncatedFrame;
    const header = reader.takeByte() catch return error.TruncatedFrame;
    var weights: [256]u4 = undefined;
    if (header < 128) {
        const compressed_size: usize = header;
        remaining.* = remaining.subtract(compressed_size) orelse return error.TruncatedFrame;
        const compressed = reader.take(compressed_size) catch return error.TruncatedFrame;
        var decoded = try decodeHuffmanWeightsFse(compressed, &weights);
        return buildHuffmanTreeFromWeightStats(
            &weights,
            decoded.symbol_count,
            decoded.power_sum,
            &decoded.counts,
            prepared_narrow,
        );
    }

    const encoded_symbol_count: usize = header - 127;
    const byte_count = (encoded_symbol_count + 1) / 2;
    remaining.* = remaining.subtract(byte_count) orelse return error.TruncatedFrame;
    const encoded = reader.take(byte_count) catch return error.TruncatedFrame;
    for (encoded, 0..) |byte, index| {
        weights[index * 2] = @intCast(byte >> 4);
        weights[index * 2 + 1] = @intCast(byte & 0x0f);
    }
    return buildHuffmanTreeFromWeights(&weights, encoded_symbol_count + 1, prepared_narrow);
}

const DecodedHuffmanWeights = struct {
    symbol_count: usize,
    power_sum: u32,
    counts: [16]u16,
};

inline fn recordDecodedHuffmanWeight(
    weights: *[256]u4,
    index: usize,
    symbol: u8,
    power_sum: *u32,
    counts: *[16]u16,
) Error!void {
    if (symbol > 11) return error.CorruptFrame;
    const weight: u4 = @intCast(symbol);
    weights[index] = weight;
    power_sum.* += (@as(u16, 1) << weight) >> 1;
    counts[weight] += 1;
}

inline fn decodeHuffmanWeightsFse(compressed: []const u8, weights: *[256]u4) Error!DecodedHuffmanWeights {
    var entries: [max_sequence_fse_table_size]FseTableEntry = undefined;
    var values: [256]u16 = undefined;
    const decoded = try huffman_weight_fse.parseNormalizedCounts(compressed, &values);
    try buildFseTable(values[0..decoded.value_count], entries[0..decoded.table_len]);
    if (decoded.bytes_consumed >= compressed.len) return error.TruncatedFrame;
    var reverse = try ReverseBitReader.init(compressed[decoded.bytes_consumed..]);
    const table_len = decoded.table_len;
    const accuracy_log: u8 = @intCast(std.math.log2_int(usize, table_len));
    var even_state = try reverse.readSmall(@intCast(accuracy_log));
    var odd_state = try reverse.readSmall(@intCast(accuracy_log));
    var index: usize = 0;
    var power_sum: u32 = 0;
    var counts: [16]u16 = @splat(0);
    if (huffman_reservoir.Reservoir.init(reverse)) |initial_reservoir| {
        var reservoir = initial_reservoir;
        while (index <= 248 and reservoir.canDecodeFive(6)) {
            inline for (0..3) |_| {
                const even = entries[even_state];
                const odd = entries[odd_state];
                try recordDecodedHuffmanWeight(weights, index, even.symbol, &power_sum, &counts);
                try recordDecodedHuffmanWeight(weights, index + 1, odd.symbol, &power_sum, &counts);
                index += 2;
                const even_bits = if (even.bits == 0) 0 else blk: {
                    const value = reservoir.peek(@intCast(even.bits));
                    reservoir.consume(even.bits);
                    break :blk value;
                };
                const odd_bits = if (odd.bits == 0) 0 else blk: {
                    const value = reservoir.peek(@intCast(odd.bits));
                    reservoir.consume(odd.bits);
                    break :blk value;
                };
                even_state = even.baseline + even_bits;
                odd_state = odd.baseline + odd_bits;
                if (even_state >= table_len or odd_state >= table_len) return error.CorruptFrame;
                if (builtin.is_test) test_huffman_weight_pair_group_hits += 1;
            }
            reservoir.reload();
        }
        reverse.remaining_bits = reservoir.remainingBits();
    }
    while (index < 254) {
        const even = entries[even_state];
        try recordDecodedHuffmanWeight(weights, index, even.symbol, &power_sum, &counts);
        index += 1;
        const even_bits = try readHuffmanWeightFseBits(&reverse, even.bits);
        if (even_bits.count < even.bits) {
            const odd = entries[odd_state];
            try recordDecodedHuffmanWeight(weights, index, odd.symbol, &power_sum, &counts);
            index += 1;
            break;
        }
        even_state = even.baseline + even_bits.value;
        if (even_state >= table_len) return error.CorruptFrame;

        const odd = entries[odd_state];
        try recordDecodedHuffmanWeight(weights, index, odd.symbol, &power_sum, &counts);
        index += 1;
        const odd_bits = try readHuffmanWeightFseBits(&reverse, odd.bits);
        if (odd_bits.count < odd.bits) {
            if (index == 255) return error.CorruptFrame;
            const final_even = entries[even_state];
            try recordDecodedHuffmanWeight(weights, index, final_even.symbol, &power_sum, &counts);
            index += 1;
            break;
        }
        odd_state = odd.baseline + odd_bits.value;
        if (odd_state >= table_len) return error.CorruptFrame;
    } else return error.CorruptFrame;
    if (reverse.available() != 0) return error.CorruptFrame;
    return .{ .symbol_count = index + 1, .power_sum = power_sum, .counts = counts };
}

const HuffmanWeightFseBits = struct { value: usize, count: u8 };

fn readHuffmanWeightFseBits(reader: *ReverseBitReader, bit_count: u8) Error!HuffmanWeightFseBits {
    const result = try reader.readSmallAvailable(@intCast(bit_count));
    return .{ .value = result.value, .count = result.count };
}

inline fn buildHuffmanTreeFromWeights(
    weights: *[256]u4,
    symbol_count: usize,
    prepared_narrow: ?*PreparedNarrowHuffmanLookup,
) Error!StdZstdHuffmanTree {
    if (symbol_count < 2 or symbol_count > weights.len) return error.CorruptFrame;
    var weight_power_sum: u32 = 0;
    var counts: [16]u16 = @splat(0);
    for (weights[0 .. symbol_count - 1]) |weight| {
        if (weight > 11) return error.CorruptFrame;
        weight_power_sum += (@as(u16, 1) << weight) >> 1;
        counts[weight] += 1;
    }
    return buildHuffmanTreeFromWeightStats(weights, symbol_count, weight_power_sum, &counts, prepared_narrow);
}

inline fn buildHuffmanTreeFromWeightStats(
    weights: *[256]u4,
    symbol_count: usize,
    weight_power_sum: u32,
    counts: *[16]u16,
    prepared_narrow: ?*PreparedNarrowHuffmanLookup,
) Error!StdZstdHuffmanTree {
    if (symbol_count < 2 or symbol_count > weights.len) return error.CorruptFrame;
    if (weight_power_sum >= 1 << 11) return error.CorruptFrame;
    const max_bit_count: u4 = @intCast(if (weight_power_sum == 0) 1 else std.math.log2_int(u32, weight_power_sum) + 1);
    const remaining_power = (@as(u32, 1) << max_bit_count) - weight_power_sum;
    if (remaining_power == 0) return error.CorruptFrame;
    const implied_weight: u4 = @intCast(std.math.log2_int(u32, remaining_power) + 1);
    weights[symbol_count - 1] = implied_weight;
    counts[implied_weight] += 1;
    const first_invalid_weight: usize = @as(usize, max_bit_count) + 2;
    for (counts[first_invalid_weight..]) |count|
        if (count != 0) return error.CorruptFrame;
    if (prepared_narrow) |prepared| {
        prepared.complete = max_bit_count <= NarrowHuffmanLiteralLookup.bit_width;
    }
    var prepared_entry_count: usize = 0;
    var starts: [16]u16 = @splat(0);
    var active_count: usize = 0;
    for (1..counts.len) |weight| {
        starts[weight] = @intCast(active_count);
        active_count += counts[weight];
    }
    if (active_count == 0 or active_count > 256) return error.CorruptFrame;

    var tree: StdZstdHuffmanTree = undefined;
    var next = starts;
    for (weights[0..symbol_count], 0..) |weight, symbol| {
        if (weight == 0) continue;
        const slot = next[weight];
        tree.nodes[slot].symbol = @intCast(symbol);
        tree.nodes[slot].weight = weight;
        next[weight] += 1;
    }
    var prefix: u16 = 0;
    var previous_weight: u4 = 0;
    for (1..counts.len) |weight_usize| {
        const count = counts[weight_usize];
        if (count == 0) continue;
        const weight: u4 = @intCast(weight_usize);
        if (previous_weight != 0)
            prefix = ((prefix - 1) >> @intCast(weight - previous_weight)) + 1;
        const start = starts[weight];
        for (tree.nodes[start..][0..count]) |*node| {
            node.prefix = prefix;
            if (prepared_narrow) |prepared| {
                if (prepared.complete) {
                    const bit_count: u4 = max_bit_count + 1 - weight;
                    prepared.complete = prepared.table.fillCanonical(prefix, bit_count, node.symbol);
                    prepared_entry_count += @as(usize, 1) << @intCast(NarrowHuffmanLiteralLookup.bit_width - bit_count);
                }
            }
            prefix += 1;
        }
        previous_weight = weight;
    }
    if (prepared_narrow) |prepared|
        prepared.complete = prepared.complete and prepared_entry_count == NarrowHuffmanLiteralLookup.len;
    tree.max_bit_count = max_bit_count;
    tree.symbol_count_minus_one = @intCast(active_count - 1);
    return tree;
}

fn expectLinearHuffmanTreeMatchesStd(encoded: []const u8) !void {
    var expected_reader: std.Io.Reader = .fixed(encoded);
    var expected_remaining: std.Io.Limit = .limited(encoded.len);
    const expected = try StdZstdHuffmanTree.decode(&expected_reader, &expected_remaining);
    var actual_reader: std.Io.Reader = .fixed(encoded);
    var actual_remaining: std.Io.Limit = .limited(encoded.len);
    const actual = try decodeLinearZstdHuffmanTree(&actual_reader, &actual_remaining, null);
    try std.testing.expectEqual(expected_reader.seek, actual_reader.seek);
    try std.testing.expectEqual(expected_remaining, actual_remaining);
    try expectHuffmanTreesEqual(expected, actual);
}

fn expectHuffmanTreesEqual(expected: StdZstdHuffmanTree, actual: StdZstdHuffmanTree) !void {
    try std.testing.expectEqual(expected.max_bit_count, actual.max_bit_count);
    try std.testing.expectEqual(expected.symbol_count_minus_one, actual.symbol_count_minus_one);
    try std.testing.expectEqualSlices(
        StdZstdHuffmanTree.PrefixedSymbol,
        expected.nodes[0 .. @as(usize, expected.symbol_count_minus_one) + 1],
        actual.nodes[0 .. @as(usize, actual.symbol_count_minus_one) + 1],
    );
}

test "zstd linear Huffman tree builder matches standard direct and FSE trees" {
    const direct = [_]u8{ 0x83, 0x11, 0x11 };
    try expectLinearHuffmanTreeMatchesStd(&direct);

    const fse_hex =
        "3710657a2b5cbc991677a0b3d956ae1aa76ac132b29a169ab2abdcef38e438a8e62e6e" ++
        "8751108babaaaaaaaaaaaaaaaaaaaaaaaaaaaa6a82";
    var fse: [fse_hex.len / 2]u8 = undefined;
    _ = try std.fmt.hexToBytes(&fse, fse_hex);
    test_huffman_weight_pair_group_hits = 0;
    defer test_huffman_weight_pair_group_hits = 0;
    try expectLinearHuffmanTreeMatchesStd(&fse);
    try std.testing.expect(test_huffman_weight_pair_group_hits != 0);

    var weights: [256]u4 = undefined;
    const compressed_size: usize = fse[0];
    const decoded = try decodeHuffmanWeightsFse(fse[1..][0..compressed_size], &weights);
    var expected_power_sum: u32 = 0;
    var expected_counts: [16]u16 = @splat(0);
    for (weights[0 .. decoded.symbol_count - 1]) |weight| {
        expected_power_sum += (@as(u16, 1) << weight) >> 1;
        expected_counts[weight] += 1;
    }
    try std.testing.expectEqual(expected_power_sum, decoded.power_sum);
    try std.testing.expectEqualSlices(u16, &expected_counts, &decoded.counts);
}

test "zstd linear Huffman tree parser matches standard acceptance" {
    var state: u32 = 0x243f_6a88;
    for (0..512) |seed| {
        const len = 1 + seed % 96;
        var encoded: [96]u8 = undefined;
        for (encoded[0..len]) |*byte| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = @truncate(state >> 24);
        }
        var expected_reader: std.Io.Reader = .fixed(encoded[0..len]);
        var expected_remaining: std.Io.Limit = .limited(len);
        const expected_result = StdZstdHuffmanTree.decode(&expected_reader, &expected_remaining);
        var actual_reader: std.Io.Reader = .fixed(encoded[0..len]);
        var actual_remaining: std.Io.Limit = .limited(len);
        const actual_result = decodeLinearZstdHuffmanTree(&actual_reader, &actual_remaining, null);
        if (expected_result) |expected_tree| {
            const actual_tree = try actual_result;
            try std.testing.expectEqual(expected_reader.seek, actual_reader.seek);
            try std.testing.expectEqual(expected_remaining, actual_remaining);
            try expectHuffmanTreesEqual(expected_tree, actual_tree);
        } else |expected_error| switch (expected_error) {
            error.EndOfStream => try std.testing.expectError(error.TruncatedFrame, actual_result),
            else => try std.testing.expectError(error.CorruptFrame, actual_result),
        }
    }
}

test "zstd linear Huffman tree parser matches generated trees" {
    var state: u32 = 0x9e37_79b9;
    var direct_count: usize = 0;
    var fse_count: usize = 0;
    for (0..64) |seed| {
        var payload: [4096]u8 = undefined;
        const alphabet = 2 + seed * 251 / 63;
        for (&payload) |*byte| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = @intCast((state >> 16) % alphabet);
        }
        const plan = smallHuffmanLiteralPlan(&payload) orelse continue;
        var encoded: std.ArrayList(u8) = .empty;
        defer encoded.deinit(std.testing.allocator);
        if (!try emitSmallHuffmanTree(std.testing.allocator, &encoded, &plan)) continue;
        if (encoded.items[0] < 128) fse_count += 1 else direct_count += 1;
        try expectLinearHuffmanTreeMatchesStd(encoded.items);
    }
    try std.testing.expect(direct_count != 0);
    try std.testing.expect(fse_count != 0);
}

fn parseSequenceCount(block: []const u8, offset: *usize) Error!usize {
    if (offset.* >= block.len) return error.TruncatedFrame;
    const byte0 = block[offset.*];
    offset.* += 1;
    if (byte0 == 0) return 0;
    if (byte0 < 128) {
        return byte0;
    }
    if (byte0 < 255) {
        if (block.len - offset.* < 1) return error.TruncatedFrame;
        const count = (@as(usize, byte0 - 128) << 8) + block[offset.*];
        offset.* += 1;
        return count;
    }
    if (block.len - offset.* < 2) return error.TruncatedFrame;
    const count = @as(usize, block[offset.*]) + (@as(usize, block[offset.* + 1]) << 8) + 0x7f00;
    offset.* += 2;
    return count;
}

/// Conservatively determine whether the immediately following block can use
/// the current block's sequence tables. A fully present compressed successor
/// with at least one sequence and no Repeat_Mode field proves that the current
/// tables can be discarded; every malformed, literal-only, raw, or RLE shape
/// keeps the established retention behavior.
noinline fn nextBlockMayUsePreviousSequenceTables(frame: []const u8, header_offset: usize) bool {
    if (header_offset > frame.len or frame.len - header_offset < 3) return true;
    const block_header = std.mem.readInt(u24, frame[header_offset..][0..3], .little);
    const block_type = (block_header >> 1) & 0x3;
    const block_len: usize = @intCast(block_header >> 3);
    if (block_type != 2 or frame.len - header_offset - 3 < block_len) return true;

    const block = frame[header_offset + 3 ..][0..block_len];
    var offset: usize = 0;
    const literal_header = parseLiteralsHeader(block, &offset) catch return true;
    const literal_payload_len: usize = switch (literal_header.kind) {
        .raw => literal_header.regenerated_size,
        .rle => 1,
        .compressed, .treeless => literal_header.compressed_size,
    };
    if (offset > block.len or block.len - offset < literal_payload_len) return true;
    offset += literal_payload_len;
    const sequence_count = parseSequenceCount(block, &offset) catch return true;
    if (sequence_count == 0 or offset >= block.len) return true;

    const mode = block[offset];
    if ((mode & 0x03) != 0) return true;
    const repeat_value = @intFromEnum(SymbolMode.repeat);
    return mode >> 6 == repeat_value or
        ((mode >> 4) & 0x03) == repeat_value or
        ((mode >> 2) & 0x03) == repeat_value;
}

const SymbolMode = enum(u2) {
    predefined = 0,
    rle = 1,
    compressed = 2,
    repeat = 3,
};

const SequenceModeSpec = struct {
    ll_mode: SymbolMode,
    of_mode: SymbolMode,
    ml_mode: SymbolMode,
    literal_rle: ?SequenceSymbol,
    offset_rle: ?SequenceSymbol,
    match_rle: ?SequenceSymbol,
    literal_fse: SequenceFseTable = .{},
    offset_fse: SequenceFseTable = .{},
    match_fse: SequenceFseTable = .{},
    bitstream_offset: usize,

    fn tables(self: *const SequenceModeSpec) SequenceTables {
        return .{
            .ll_mode = self.ll_mode,
            .of_mode = self.of_mode,
            .ml_mode = self.ml_mode,
            .literal_rle = self.literal_rle,
            .offset_rle = self.offset_rle,
            .match_rle = self.match_rle,
            .literal_fse = self.literal_fse,
            .offset_fse = self.offset_fse,
            .match_fse = self.match_fse,
        };
    }
};

const SequenceSymbol = sequence_predefined.Symbol;

const max_sequence_fse_table_size = 1 << 9;

const SequenceFseTable = struct {
    entries: [max_sequence_fse_table_size]SequenceSymbol = undefined,
    len: usize = 0,
    accuracy_log: u8 = 0,

    fn symbol(self: *const SequenceFseTable, state: usize) Error!SequenceSymbol {
        if (state >= self.len) {
            @branchHint(.unlikely);
            return error.CorruptFrame;
        }
        return self.entries[state];
    }

    inline fn symbolUnchecked(self: *const SequenceFseTable, state: usize) SequenceSymbol {
        std.debug.assert(state < self.len);
        return self.entries[state];
    }

    inline fn symbolWordUnchecked(self: *const SequenceFseTable, state: usize) u64 {
        std.debug.assert(state < self.len);
        const bytes: *const [8]u8 = @ptrCast(&self.entries[state]);
        return std.mem.readInt(u64, bytes, .little);
    }
};

comptime {
    std.debug.assert(@sizeOf(SequenceSymbol) == @sizeOf(u64));
    std.debug.assert(@offsetOf(SequenceSymbol, "base") == 0);
    std.debug.assert(@offsetOf(SequenceSymbol, "next_state") == 4);
    std.debug.assert(@offsetOf(SequenceSymbol, "additional_bits") == 6);
    std.debug.assert(@offsetOf(SequenceSymbol, "state_bits") == 7);
}

inline fn sequenceSymbolBase(word: u64) usize {
    return @intCast(@as(u32, @truncate(word)));
}

inline fn sequenceSymbolNextState(word: u64) usize {
    return @intCast(@as(u16, @truncate(word >> 32)));
}

inline fn sequenceSymbolAdditionalBits(word: u64) u8 {
    return @truncate(word >> 48);
}

inline fn sequenceSymbolStateBits(word: u64) u8 {
    return @truncate(word >> 56);
}

const sequence_table_accuracy_log_max = struct {
    const literal: u4 = 9;
    const match: u4 = 9;
    const offset: u4 = 8;
};

const sequence_table_symbol_count_max = struct {
    const literal = 36;
    const match = 53;
    const offset = 32;
};

const SequenceTables = struct {
    ll_mode: SymbolMode,
    of_mode: SymbolMode,
    ml_mode: SymbolMode,
    literal_rle: ?SequenceSymbol,
    offset_rle: ?SequenceSymbol,
    match_rle: ?SequenceSymbol,
    literal_fse: SequenceFseTable = .{},
    offset_fse: SequenceFseTable = .{},
    match_fse: SequenceFseTable = .{},
};

const SequenceFrameState = struct {
    // Zstandard repeats sequence tables, recent offsets, and Huffman literal
    // trees across compressed blocks in a frame. Raw/RLE blocks are
    // intentionally skipped. Keeping this small state object explicit makes the
    // native fallback decoder closer to the spec without hiding unsupported FSE
    // tables.
    previous_tables: ?SequenceTables = null,
    repeated_offsets: [3]usize = initial_repeated_offsets,
    previous_huffman_tree: ?StdZstdHuffmanTree = null,
    retain_sequence_tables: bool = true,
};

// Four entries retain every compressed block in the common 512 KiB frame. The
// public decoder owns this workspace out of line so its stack-facing handle
// stays compact and raw/RLE-only workloads never pay for it.
const SequenceDecodeWorkspace = struct {
    sequence: sequence_decode_cache.Cache(SequenceModeSpec) = .{},
    huffman: huffman_tree_cache.Cache(StdZstdHuffmanTree) = .{},
};

comptime {
    std.debug.assert(@sizeOf(NativeFrameDecoder) <= 64);
    std.debug.assert(@sizeOf(SequenceDecodeWorkspace) <= 64 * 1024);
}

const ResolvedSymbolTable = struct {
    mode: SymbolMode,
    rle: ?SequenceSymbol,
    fse: SequenceFseTable = .{},
};

fn parseSequenceModeSpec(block: []const u8, offset: *usize, sequence_count: usize) Error!SequenceModeSpec {
    var spec: SequenceModeSpec = undefined;
    try parseSequenceModeSpecInto(&spec, block, offset, sequence_count);
    return spec;
}

fn parseSequenceModeSpecInto(
    spec: *SequenceModeSpec,
    block: []const u8,
    offset: *usize,
    sequence_count: usize,
) Error!void {
    if (sequence_count == 0) return error.CorruptFrame;
    if (block.len - offset.* < 1) return error.TruncatedFrame;
    const mode = block[offset.*];
    offset.* += 1;
    if ((mode & 0x03) != 0) return error.CorruptFrame;
    const ll_mode: SymbolMode = @enumFromInt(mode >> 6);
    const of_mode: SymbolMode = @enumFromInt((mode >> 4) & 0x03);
    const ml_mode: SymbolMode = @enumFromInt((mode >> 2) & 0x03);
    if (ll_mode == .predefined and
        of_mode == .predefined and
        ml_mode == .predefined)
    {
        const bitstream_offset = offset.*;
        if (bitstream_offset >= block.len) return error.TruncatedFrame;
        offset.* = block.len;
        spec.* = .{
            .ll_mode = .predefined,
            .of_mode = .predefined,
            .ml_mode = .predefined,
            .literal_rle = null,
            .offset_rle = null,
            .match_rle = null,
            .bitstream_offset = bitstream_offset,
        };
        return;
    }

    spec.ll_mode = ll_mode;
    spec.of_mode = of_mode;
    spec.ml_mode = ml_mode;
    spec.literal_rle = null;
    spec.offset_rle = null;
    spec.match_rle = null;
    // Only `len` and `accuracy_log` are observed for non-compressed modes. Do
    // not zero three 4 KiB entry arrays before immediately overwriting the
    // compressed ones; the active mode guards every entry access.
    spec.literal_fse.len = 0;
    spec.literal_fse.accuracy_log = 0;
    spec.offset_fse.len = 0;
    spec.offset_fse.accuracy_log = 0;
    spec.match_fse.len = 0;
    spec.match_fse.accuracy_log = 0;

    // Sequence table payloads are serialized in LL, OF, ML order. Each table's
    // mode decides whether the next bytes are a one-byte RLE symbol or a full
    // FSE table. Reading all RLE bytes before all FSE tables corrupts mixed
    // mode blocks such as LL=FSE, OF=FSE, ML=RLE.
    switch (ll_mode) {
        .rle => spec.literal_rle = try readRleSymbolCode(block, offset, &ll_base, &ll_bits),
        .compressed => try readFseSequenceTableInto(&spec.literal_fse, block, offset, &ll_base, &ll_bits, sequence_table_symbol_count_max.literal, sequence_table_accuracy_log_max.literal),
        .predefined, .repeat => {},
    }
    switch (of_mode) {
        .rle => spec.offset_rle = try readRleSymbolCode(block, offset, &of_base, &of_bits),
        .compressed => try readFseSequenceTableInto(&spec.offset_fse, block, offset, &of_base, &of_bits, sequence_table_symbol_count_max.offset, sequence_table_accuracy_log_max.offset),
        .predefined, .repeat => {},
    }
    switch (ml_mode) {
        .rle => spec.match_rle = try readRleSymbolCode(block, offset, &ml_base, &ml_bits),
        .compressed => try readFseSequenceTableInto(&spec.match_fse, block, offset, &ml_base, &ml_bits, sequence_table_symbol_count_max.match, sequence_table_accuracy_log_max.match),
        .predefined, .repeat => {},
    }

    const bitstream_offset = offset.*;
    if (bitstream_offset >= block.len) return error.TruncatedFrame;
    offset.* = block.len;
    spec.bitstream_offset = bitstream_offset;
}

fn resolveSymbolTable(
    mode: SymbolMode,
    rle: ?SequenceSymbol,
    fse: SequenceFseTable,
    previous: ?SequenceTables,
    selector: enum { ll, of, ml },
) Error!ResolvedSymbolTable {
    return switch (mode) {
        .repeat => blk: {
            const tables = previous orelse return error.CorruptFrame;
            break :blk switch (selector) {
                .ll => .{ .mode = tables.ll_mode, .rle = tables.literal_rle, .fse = tables.literal_fse },
                .of => .{ .mode = tables.of_mode, .rle = tables.offset_rle, .fse = tables.offset_fse },
                .ml => .{ .mode = tables.ml_mode, .rle = tables.match_rle, .fse = tables.match_fse },
            };
        },
        else => .{ .mode = mode, .rle = rle, .fse = fse },
    };
}

fn resolveSequenceModeSpec(spec: SequenceModeSpec, previous: ?SequenceTables) Error!SequenceModeSpec {
    if (spec.ll_mode == .predefined and
        spec.of_mode == .predefined and
        spec.ml_mode == .predefined)
    {
        return spec;
    }
    const ll = try resolveSymbolTable(spec.ll_mode, spec.literal_rle, spec.literal_fse, previous, .ll);
    const of = try resolveSymbolTable(spec.of_mode, spec.offset_rle, spec.offset_fse, previous, .of);
    const ml = try resolveSymbolTable(spec.ml_mode, spec.match_rle, spec.match_fse, previous, .ml);
    return .{
        .ll_mode = ll.mode,
        .of_mode = of.mode,
        .ml_mode = ml.mode,
        .literal_rle = ll.rle,
        .offset_rle = of.rle,
        .match_rle = ml.rle,
        .literal_fse = ll.fse,
        .offset_fse = of.fse,
        .match_fse = ml.fse,
        .bitstream_offset = spec.bitstream_offset,
    };
}

fn expectSequenceModeSpecsEqual(expected: *const SequenceModeSpec, actual: *const SequenceModeSpec) !void {
    try std.testing.expectEqual(expected.ll_mode, actual.ll_mode);
    try std.testing.expectEqual(expected.of_mode, actual.of_mode);
    try std.testing.expectEqual(expected.ml_mode, actual.ml_mode);
    try std.testing.expectEqual(expected.literal_rle, actual.literal_rle);
    try std.testing.expectEqual(expected.offset_rle, actual.offset_rle);
    try std.testing.expectEqual(expected.match_rle, actual.match_rle);
    try std.testing.expectEqual(expected.bitstream_offset, actual.bitstream_offset);
    inline for (.{
        .{ &expected.literal_fse, &actual.literal_fse },
        .{ &expected.offset_fse, &actual.offset_fse },
        .{ &expected.match_fse, &actual.match_fse },
    }) |tables| {
        try std.testing.expectEqual(tables[0].len, tables[1].len);
        try std.testing.expectEqual(tables[0].accuracy_log, tables[1].accuracy_log);
        try std.testing.expectEqualSlices(SequenceSymbol, tables[0].entries[0..tables[0].len], tables[1].entries[0..tables[1].len]);
    }
}

fn readRleSymbolCode(block: []const u8, offset: *usize, bases: []const usize, bits: []const u8) Error!SequenceSymbol {
    if (offset.* >= block.len) return error.TruncatedFrame;
    const code = block[offset.*];
    offset.* += 1;
    if (code >= bases.len) return error.CorruptFrame;
    return .{ .base = @intCast(bases[code]), .additional_bits = bits[code], .next_state = 0, .state_bits = 0 };
}

fn readFseSequenceTable(
    block: []const u8,
    offset: *usize,
    bases: []const usize,
    bits: []const u8,
    expected_symbol_count: usize,
    max_accuracy_log: u4,
) Error!SequenceFseTable {
    var table: SequenceFseTable = undefined;
    try readFseSequenceTableInto(&table, block, offset, bases, bits, expected_symbol_count, max_accuracy_log);
    return table;
}

fn readFseSequenceTableInto(
    table: *SequenceFseTable,
    block: []const u8,
    offset: *usize,
    bases: []const usize,
    bits: []const u8,
    expected_symbol_count: usize,
    max_accuracy_log: u4,
) Error!void {
    // Parse normalized counts once, then build final SequenceSymbol entries
    // directly. This avoids the former 512-entry intermediate table plus a
    // second full conversion pass for every compressed LL/OF/ML table.
    if (offset.* >= block.len) return error.TruncatedFrame;
    var values: [256]u16 = undefined;
    const decoded = try sequence_normalized_counts.parse(block[offset.*..], expected_symbol_count, max_accuracy_log, &values);
    offset.* = std.math.add(usize, offset.*, decoded.bytes_consumed) catch return error.IntegerOverflow;
    if (offset.* > block.len) return error.TruncatedFrame;

    table.len = decoded.table_len;
    table.accuracy_log = @intCast(std.math.log2_int(usize, decoded.table_len));
    const normalized = values[0..decoded.value_count];
    if (decoded.table_len == 256) {
        var no_low_probability = true;
        for (normalized) |value| no_low_probability = no_low_probability and value != 0;
        if (no_low_probability) {
            if (builtin.is_test) test_large_fse_no_low_builder_hits += 1;
            large_fse_table.buildNoLowProbabilityAssumeValid(
                normalized,
                table.entries[0..decoded.table_len],
                bases,
                bits,
            );
            return;
        }
    }
    try sequence_fse_builder.buildMapped(normalized, table.entries[0..decoded.table_len], bases, bits);
}

const FseTableEntry = sequence_fse_builder.Entry;

fn decodeFseTable(
    reader: *ForwardBitReader,
    expected_symbol_count: usize,
    max_accuracy_log: u4,
    entries: *[max_sequence_fse_table_size]FseTableEntry,
) Error!usize {
    var values: [256]u16 = undefined;
    const decoded = try decodeFseNormalizedCounts(reader, expected_symbol_count, max_accuracy_log, &values);
    try buildFseTable(values[0..decoded.value_count], entries[0..decoded.table_len]);
    return decoded.table_len;
}

const DecodedFseNormalizedCounts = struct {
    value_count: usize,
    table_len: usize,
};

noinline fn decodeFseNormalizedCounts(
    reader: *ForwardBitReader,
    expected_symbol_count: usize,
    max_accuracy_log: u4,
    values: *[256]u16,
) Error!DecodedFseNormalizedCounts {
    const accuracy_log_biased = try reader.readBits(u4, 4);
    if (accuracy_log_biased > max_accuracy_log -| 5) return error.CorruptFrame;
    const accuracy_log = accuracy_log_biased + 5;

    var value_count: usize = 0;
    const total_probability = @as(u16, 1) << accuracy_log;
    var accumulated_probability: u16 = 0;
    while (accumulated_probability < total_probability) {
        const max_bits = std.math.log2_int(u16, total_probability - accumulated_probability + 1) + 1;
        const small = try reader.readBits(u16, max_bits - 1);
        const cutoff = (@as(u16, 1) << @intCast(max_bits)) - 1 - (total_probability - accumulated_probability + 1);
        const value = if (small < cutoff)
            small
        else value: {
            const value_read = small + ((try reader.readBits(u16, 1)) << @intCast(max_bits - 1));
            break :value if (value_read < @as(u16, 1) << @intCast(max_bits - 1))
                value_read
            else
                value_read - cutoff;
        };

        accumulated_probability += if (value != 0) value - 1 else 1;
        values[value_count] = value;
        value_count += 1;

        if (value == 1) {
            while (true) {
                const repeat_flag: usize = try reader.readBits(u2, 2);
                if (repeat_flag + value_count > values.len) return error.CorruptFrame;
                for (0..repeat_flag) |_| {
                    values[value_count] = 1;
                    value_count += 1;
                }
                if (repeat_flag < 3) break;
            }
        }
        if (value_count == values.len) break;
    }
    reader.alignToByte();

    if (value_count < 2) return error.CorruptFrame;
    if (accumulated_probability != total_probability) return error.CorruptFrame;
    if (value_count > expected_symbol_count) return error.CorruptFrame;
    const table_len: usize = @as(usize, 1) << @intCast(accuracy_log);
    return .{ .value_count = value_count, .table_len = table_len };
}

test "zstd Huffman weight normalized-count parser matches generic decoder" {
    const Adapter = struct {
        fn parse(bytes: []const u8, values: *[256]u16) Error!huffman_weight_fse.ParseResult {
            var reader: ForwardBitReader = .{ .bytes = bytes };
            const decoded = try decodeFseNormalizedCounts(&reader, 256, 6, values);
            return .{
                .value_count = decoded.value_count,
                .table_len = decoded.table_len,
                .bytes_consumed = reader.byteIndex(),
            };
        }
    };
    try huffman_weight_fse.expectMatchesGeneric(Adapter.parse);
}

test "zstd sequence normalized-count reservoir matches generic decoder" {
    const Adapter = struct {
        fn parse(
            bytes: []const u8,
            expected_symbol_count: usize,
            max_accuracy_log: u4,
            values: *[256]u16,
        ) Error!sequence_normalized_counts.Result {
            var reader: ForwardBitReader = .{ .bytes = bytes };
            const decoded = try decodeFseNormalizedCounts(&reader, expected_symbol_count, max_accuracy_log, values);
            return .{
                .value_count = decoded.value_count,
                .table_len = decoded.table_len,
                .bytes_consumed = reader.byteIndex(),
            };
        }
    };
    try sequence_normalized_counts.expectMatchesGeneric(Adapter.parse);
}

fn buildFseTable(values: []const u16, entries: []FseTableEntry) Error!void {
    // Large tables dominate construction cost in sequence-heavy blocks. Their
    // linear state pass is kept out of line so uncommon table setup does not
    // inflate the hot decode loop's instruction footprint.
    if (entries.len >= 256) return sequence_fse_builder.build(values, entries);

    const total_probability: u16 = @intCast(entries.len);
    const accuracy_log = std.math.log2_int(u16, total_probability);
    var less_than_one_count: usize = 0;
    for (values, 0..) |value, symbol| {
        if (value == 0) {
            entries[entries.len - 1 - less_than_one_count] = .{
                .symbol = @intCast(symbol),
                .baseline = 0,
                .bits = accuracy_log,
            };
            less_than_one_count += 1;
        }
    }

    var position: usize = 0;
    var temp_states: [max_sequence_fse_table_size]u16 = undefined;
    for (values, 0..) |value, symbol| {
        if (value == 0 or value == 1) continue;
        const probability = value - 1;
        const state_share_dividend = std.math.ceilPowerOfTwo(u16, probability) catch return error.CorruptFrame;
        const share_size = @divExact(total_probability, state_share_dividend);
        const double_state_count = state_share_dividend - probability;
        const single_state_count = probability - double_state_count;
        const share_size_log = std.math.log2_int(u16, share_size);

        var state_mask: u32 = 0;
        for (0..probability) |i| {
            if (entries.len == 32)
                state_mask |= @as(u32, 1) << @intCast(position)
            else
                temp_states[i] = @intCast(position);
            position += (entries.len >> 1) + (entries.len >> 3) + 3;
            position &= entries.len - 1;
            while (position >= entries.len - less_than_one_count) {
                position += (entries.len >> 1) + (entries.len >> 3) + 3;
                position &= entries.len - 1;
            }
        }
        if (entries.len != 32) std.mem.sort(u16, temp_states[0..probability], {}, std.sort.asc(u16));
        for (0..probability) |i| {
            const state = if (entries.len == 32) blk: {
                std.debug.assert(state_mask != 0);
                const next: u16 = @intCast(@ctz(state_mask));
                state_mask &= state_mask - 1;
                break :blk next;
            } else temp_states[i];
            entries[state] = if (i < double_state_count) .{
                .symbol = @intCast(symbol),
                .bits = @intCast(share_size_log + 1),
                .baseline = @intCast(single_state_count * share_size + @as(u16, @intCast(i)) * 2 * share_size),
            } else .{
                .symbol = @intCast(symbol),
                .bits = @intCast(share_size_log),
                .baseline = @intCast((@as(u16, @intCast(i)) - double_state_count) * share_size),
            };
        }
    }
}

fn defaultLiteralLengthSymbol(state: usize) Error!SequenceSymbol {
    return sequence_predefined.literal(state);
}

fn defaultOffsetSymbol(state: usize) Error!SequenceSymbol {
    return sequence_predefined.offset(state);
}

fn defaultMatchLengthSymbol(state: usize) Error!SequenceSymbol {
    return sequence_predefined.match(state);
}

const ReverseBitReader = sequence_bit_reader.Reader;

test "zstd reverse bit peek matches consuming reader" {
    const bytes = [_]u8{ 0xa7, 0x3c, 0xe1, 0x5b };
    for (1..bytes.len * 8 + 1) |remaining_bits| {
        const max_count = @min(@as(usize, 11), remaining_bits);
        for (1..max_count + 1) |count| {
            const reader = ReverseBitReader{
                .bytes = &bytes,
                .remaining_bits = remaining_bits,
            };
            var consuming = reader;
            const expected = try consuming.read(@intCast(count));
            try std.testing.expectEqual(
                expected,
                try reader.peekSmall(@intCast(count)),
            );
            try std.testing.expectEqual(remaining_bits, reader.remaining_bits);
        }
    }
}

const low_bit_mask = [9]u8{
    0b00000000,
    0b00000001,
    0b00000011,
    0b00000111,
    0b00001111,
    0b00011111,
    0b00111111,
    0b01111111,
    0b11111111,
};

fn ReadBitsResult(comptime T: type) type {
    return struct { T, u16 };
}

const ForwardBitReader = struct {
    bytes: []const u8,
    index: usize = 0,
    bits: u8 = 0,
    count: u4 = 0,

    fn readBits(self: *ForwardBitReader, comptime T: type, num: u16) Error!T {
        const value, const read_count = try self.readBitsTuple(T, num);
        if (read_count < num) return error.TruncatedFrame;
        return value;
    }

    fn readBitsTuple(self: *ForwardBitReader, comptime T: type, num: u16) Error!ReadBitsResult(T) {
        const UT = std.meta.Int(.unsigned, @bitSizeOf(T));
        const U = if (@bitSizeOf(T) < 8) u8 else UT;

        if (num <= self.count) return initReadBitsResult(T, self.removeBits(@intCast(num)), num);

        var out_count: u16 = self.count;
        var out: U = self.removeBits(self.count);
        const full_bytes_left = (num - out_count) / 8;
        for (0..full_bytes_left) |_| {
            const byte = self.takeByte() catch return initReadBitsResult(T, out, out_count);
            out |= @as(U, byte) << @intCast(out_count);
            out_count += 8;
        }

        const bits_left = num - out_count;
        const keep = 8 - bits_left;
        if (bits_left == 0) return initReadBitsResult(T, out, out_count);

        const final_byte = self.takeByte() catch return initReadBitsResult(T, out, out_count);
        out |= @as(U, final_byte & low_bit_mask[bits_left]) << @intCast(out_count);
        self.bits = final_byte >> @intCast(bits_left);
        self.count = @intCast(keep);
        return initReadBitsResult(T, out, num);
    }

    fn takeByte(self: *ForwardBitReader) error{EndOfStream}!u8 {
        if (self.index >= self.bytes.len) return error.EndOfStream;
        const result = self.bytes[self.index];
        self.index += 1;
        return result;
    }

    fn removeBits(self: *ForwardBitReader, num: u4) u8 {
        if (num == 8) {
            self.count = 0;
            return self.bits;
        }
        const keep = self.count - num;
        const bits = self.bits & low_bit_mask[num];
        self.bits >>= @intCast(num);
        self.count = keep;
        return bits;
    }

    fn alignToByte(self: *ForwardBitReader) void {
        self.bits = 0;
        self.count = 0;
    }

    fn byteIndex(self: ForwardBitReader) usize {
        return self.index;
    }

    fn initReadBitsResult(comptime T: type, out: anytype, num: u16) ReadBitsResult(T) {
        const UT = std.meta.Int(.unsigned, @bitSizeOf(T));
        return .{ @bitCast(@as(UT, @intCast(out))), num };
    }
};

fn decodeRleSequencesCompressedBlockIntoBuffer(
    block: []const u8,
    section: LiteralOnlySection,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    comptime allow_wildcopy: bool,
) Error!void {
    if (frame_output_start > written.*) return error.CorruptFrame;
    var offset = section.sequence_payload_offset;
    if (section.sequence_count == 1 and
        offset < block.len and
        sequence_predefined.isModeByte(block[offset]))
    {
        return try decodeSinglePredefinedSequence(
            block,
            section,
            offset + 1,
            output,
            written,
            frame_output_start,
            dictionary_history,
            frame_state,
            continuation,
        );
    }
    var spec: SequenceModeSpec = undefined;
    try parseSequenceModeSpecInto(&spec, block, &offset, section.sequence_count);
    if (spec.ll_mode == .repeat or spec.of_mode == .repeat or spec.ml_mode == .repeat)
        spec = try resolveSequenceModeSpec(spec, frame_state.previous_tables);
    try expectConsumedBlock(offset, block.len);
    const bit_reader = try ReverseBitReader.init(block[spec.bitstream_offset..]);

    if ((!builtin.is_test or !test_disable_split_huffman_decode) and
        spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferSplit(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0 and
        section.regenerated_size <= split_wide_huffman_literal_capacity)
    {
        var state = try initSequenceDecodeState(&spec, section.sequence_count, bit_reader, frame_state.repeated_offsets);
        if (sequence_decode_policy.preferSmallCopies(section.regenerated_size, section.sequence_count)) {
            if (try tryDecodeAllFseSplitHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
            )) {
                if (frame_state.retain_sequence_tables) frame_state.previous_tables = spec.tables();
                return;
            }
        } else if (section.regenerated_size <= split_huffman_literal_capacity) {
            if (try tryDecodeAllFseSplitDenseHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
            )) {
                if (frame_state.retain_sequence_tables) frame_state.previous_tables = spec.tables();
                return;
            }
        } else if (try tryDecodeAllFseSplitWideHuffmanSequences(
            section,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
            allow_wildcopy,
        )) {
            if (frame_state.retain_sequence_tables) frame_state.previous_tables = spec.tables();
            return;
        }
    }
    var state = try initSequenceDecodeState(&spec, section.sequence_count, bit_reader, frame_state.repeated_offsets);
    if ((!builtin.is_test or !test_disable_split_huffman_decode) and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferGenericSplit(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0 and
        section.regenerated_size <= split_wide_huffman_literal_capacity)
    {
        if (try tryDecodeGenericSplitHuffmanSequences(
            section,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
        )) return;
    }
    if (comptime allow_wildcopy) {
        if ((!builtin.is_test or !test_disable_split_huffman_decode) and
            spec.ll_mode == .compressed and
            spec.of_mode == .compressed and
            spec.ml_mode == .compressed and
            (section.kind == .compressed or section.kind == .treeless) and
            sequence_decode_policy.preferMediumSplitHuffman(block.len, section.regenerated_size, section.sequence_count) and
            dictionary_history.len == 0)
        {
            if (try tryDecodeMediumSplitHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
            )) return;
        }
    }
    var huffman_literals = try initHuffmanLiteralDecodeState(block, section);
    var literal_offset: usize = 0;
    if ((!builtin.is_test or !test_disable_all_fse_raw_decode) and
        spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        section.kind == .raw and
        sequence_decode_policy.preferRawAllFse(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0)
    {
        if (sequence_decode_policy.preferWideRawMatchCopy(section.regenerated_size))
            return try decodeAllFseRawSequences(
                block,
                section,
                &spec,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
                true,
                false,
            );
        return try decodeAllFseRawSequencesNarrow(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
            allow_wildcopy,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .rle and
        section.kind == .raw and
        section.sequence_count >= 1024)
    {
        return try decodeFseFseRleSequences(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            dictionary_history,
            frame_state,
            continuation,
            &state,
            huffman_literals,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .rle and
        spec.ml_mode == .rle and
        section.kind == .raw and
        section.sequence_count >= 1024 and
        dictionary_history.len == 0)
    {
        return try decodeFseRleRleRawSequences(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferHuffmanAllFse(section.sequence_count) and
        dictionary_history.len == 0)
    {
        const initial_huffman = huffman_literals orelse return error.CorruptFrame;
        if (sequence_decode_policy.preferHuffmanMatchWildcopy(block.len, section.sequence_count))
            return try decodeAllFseHuffmanSequences(section, &spec, output, written, frame_output_start, frame_state, continuation, &state, allow_wildcopy, true, initial_huffman);
        return try decodeAllFseHuffmanSequences(section, &spec, output, written, frame_output_start, frame_state, continuation, &state, allow_wildcopy, false, initial_huffman);
    }
    while (state.remaining != 0) {
        const sequence = try readModeSequence(&state);
        const literal_len = sequence.literal_len;
        if (huffman_literals) |*huffman_state| {
            if (output.len - written.* < literal_len) return error.OutputTooSmall;
            try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..literal_len]);
            written.* += literal_len;
        } else {
            try copyLiteralsFromSection(block, section, literal_offset, output, written, literal_len);
        }
        literal_offset = std.math.add(usize, literal_offset, literal_len) catch return error.IntegerOverflow;
        try copyMatchFromHistory(output, written, frame_output_start, dictionary_history, sequence.match_offset, sequence.match_len);
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    const last_literals = section.regenerated_size - literal_offset;
    if (huffman_literals) |*huffman_state| {
        if (output.len - written.* < last_literals) return error.OutputTooSmall;
        try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..last_literals]);
        written.* += last_literals;
    } else {
        try copyLiteralsFromSection(block, section, literal_offset, output, written, last_literals);
    }
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

noinline fn decodeRleSequencesCompressedBlockIntoBufferWithSequenceWorkspace(
    block: []const u8,
    section: LiteralOnlySection,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    workspace: *SequenceDecodeWorkspace,
    comptime allow_wildcopy: bool,
) linksection(reusable_decode_text_section) Error!void {
    if (frame_output_start > written.*) return error.CorruptFrame;
    const description_start = section.sequence_payload_offset;
    if (section.sequence_count == 1 and
        description_start < block.len and
        sequence_predefined.isModeByte(block[description_start]))
    {
        return try decodeSinglePredefinedSequence(
            block,
            section,
            description_start + 1,
            output,
            written,
            frame_output_start,
            dictionary_history,
            frame_state,
            continuation,
        );
    }

    var offset = description_start;
    var spec: SequenceModeSpec = undefined;
    if (workspace.sequence.find(block, description_start, section.sequence_count)) |cached| {
        copyCachedSequenceModeSpec(&spec, cached.spec, description_start + cached.description_len);
        offset = block.len;
    } else {
        try parseSequenceModeSpecInto(&spec, block, &offset, section.sequence_count);
        const has_repeat = spec.ll_mode == .repeat or spec.of_mode == .repeat or spec.ml_mode == .repeat;
        if (has_repeat) spec = try resolveSequenceModeSpec(spec, frame_state.previous_tables);
        if (!has_repeat)
            workspace.sequence.store(block, description_start, section.sequence_count, spec);
    }
    try expectConsumedBlock(offset, block.len);
    const bit_reader = try ReverseBitReader.init(block[spec.bitstream_offset..]);

    if ((!builtin.is_test or !test_disable_split_huffman_decode) and
        spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferSplit(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0 and
        section.regenerated_size <= split_wide_huffman_literal_capacity)
    {
        var state = try initSequenceDecodeState(&spec, section.sequence_count, bit_reader, frame_state.repeated_offsets);
        if (sequence_decode_policy.preferSmallCopies(section.regenerated_size, section.sequence_count)) {
            if (try tryDecodeAllFseSplitHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
            )) {
                if (continuation.retainsState()) frame_state.previous_tables = spec.tables();
                return;
            }
        } else if (section.regenerated_size <= split_huffman_literal_capacity) {
            if (try tryDecodeAllFseSplitDenseHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
            )) {
                if (continuation.retainsState()) frame_state.previous_tables = spec.tables();
                return;
            }
        } else if (try tryDecodeAllFseSplitWideHuffmanSequences(
            section,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
            allow_wildcopy,
        )) {
            if (continuation.retainsState()) frame_state.previous_tables = spec.tables();
            return;
        }
    }
    var state = try initSequenceDecodeState(&spec, section.sequence_count, bit_reader, frame_state.repeated_offsets);
    if ((!builtin.is_test or !test_disable_split_huffman_decode) and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferGenericSplit(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0 and
        section.regenerated_size <= split_wide_huffman_literal_capacity)
    {
        if (try tryDecodeGenericSplitHuffmanSequences(
            section,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
        )) return;
    }
    if (comptime allow_wildcopy) {
        if ((!builtin.is_test or !test_disable_split_huffman_decode) and
            spec.ll_mode == .compressed and
            spec.of_mode == .compressed and
            spec.ml_mode == .compressed and
            (section.kind == .compressed or section.kind == .treeless) and
            sequence_decode_policy.preferMediumSplitHuffman(block.len, section.regenerated_size, section.sequence_count) and
            dictionary_history.len == 0)
        {
            if (try tryDecodeMediumSplitHuffmanSequences(
                section,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
            )) return;
        }
    }
    var huffman_literals = try initHuffmanLiteralDecodeState(block, section);
    var literal_offset: usize = 0;
    if ((!builtin.is_test or !test_disable_all_fse_raw_decode) and
        spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        section.kind == .raw and
        sequence_decode_policy.preferRawAllFse(section.regenerated_size, section.sequence_count) and
        dictionary_history.len == 0)
    {
        if (sequence_decode_policy.preferWideRawMatchCopy(section.regenerated_size))
            return try decodeAllFseRawSequences(
                block,
                section,
                &spec,
                output,
                written,
                frame_output_start,
                frame_state,
                continuation,
                &state,
                allow_wildcopy,
                true,
                false,
            );
        return try decodeAllFseRawSequencesNarrow(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
            allow_wildcopy,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .rle and
        section.kind == .raw and
        section.sequence_count >= 1024)
    {
        return try decodeFseFseRleSequences(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            dictionary_history,
            frame_state,
            continuation,
            &state,
            huffman_literals,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .rle and
        spec.ml_mode == .rle and
        section.kind == .raw and
        section.sequence_count >= 1024 and
        dictionary_history.len == 0)
    {
        return try decodeFseRleRleRawSequences(
            block,
            section,
            &spec,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            &state,
        );
    }
    if (spec.ll_mode == .compressed and
        spec.of_mode == .compressed and
        spec.ml_mode == .compressed and
        (section.kind == .compressed or section.kind == .treeless) and
        sequence_decode_policy.preferHuffmanAllFse(section.sequence_count))
    {
        const initial_huffman = huffman_literals orelse return error.CorruptFrame;
        if (sequence_decode_policy.preferHuffmanMatchWildcopy(block.len, section.sequence_count))
            return try decodeAllFseHuffmanSequences(section, &spec, output, written, frame_output_start, frame_state, continuation, &state, allow_wildcopy, true, initial_huffman);
        return try decodeAllFseHuffmanSequences(section, &spec, output, written, frame_output_start, frame_state, continuation, &state, allow_wildcopy, false, initial_huffman);
    }
    while (state.remaining != 0) {
        const sequence = try readModeSequence(&state);
        const literal_len = sequence.literal_len;
        if (huffman_literals) |*huffman_state| {
            if (output.len - written.* < literal_len) return error.OutputTooSmall;
            try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..literal_len]);
            written.* += literal_len;
        } else if (literal_len != 0) {
            try copyLiteralsFromSection(block, section, literal_offset, output, written, literal_len);
        }
        literal_offset = std.math.add(usize, literal_offset, literal_len) catch return error.IntegerOverflow;
        const available_in_frame = written.* - frame_output_start;
        if (sequence.match_len == 56 and sequence.match_offset >= 56 and sequence.match_offset <= available_in_frame) {
            if (output.len - written.* < 56) return error.OutputTooSmall;
            if (builtin.is_test) test_reusable_match_56_hits += 1;
            sequence_match_copy.appendNonOverlapping56(output, written, written.* - sequence.match_offset);
        } else if ((sequence.match_len == 6 or sequence.match_len == 7) and
            sequence.match_offset >= sequence.match_len and sequence.match_offset <= available_in_frame)
        {
            if (output.len - written.* < sequence.match_len) return error.OutputTooSmall;
            if (builtin.is_test) test_reusable_match_6_7_hits += 1;
            sequence_match_copy.appendNonOverlapping6Or7(
                output,
                written,
                written.* - sequence.match_offset,
                sequence.match_len,
            );
        } else {
            try copyMatchFromHistory(output, written, frame_output_start, dictionary_history, sequence.match_offset, sequence.match_len);
        }
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    const last_literals = section.regenerated_size - literal_offset;
    if (huffman_literals) |*huffman_state| {
        if (output.len - written.* < last_literals) return error.OutputTooSmall;
        try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..last_literals]);
        written.* += last_literals;
    } else {
        try copyLiteralsFromSection(block, section, literal_offset, output, written, last_literals);
    }
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

inline fn copyCachedSequenceModeSpec(
    out: *SequenceModeSpec,
    cached: *const SequenceModeSpec,
    bitstream_offset: usize,
) void {
    out.ll_mode = cached.ll_mode;
    out.of_mode = cached.of_mode;
    out.ml_mode = cached.ml_mode;
    out.literal_rle = cached.literal_rle;
    out.offset_rle = cached.offset_rle;
    out.match_rle = cached.match_rle;
    out.bitstream_offset = bitstream_offset;

    if (cached.ll_mode == .compressed) out.literal_fse = cached.literal_fse else {
        out.literal_fse.len = 0;
        out.literal_fse.accuracy_log = 0;
    }
    if (cached.of_mode == .compressed) out.offset_fse = cached.offset_fse else {
        out.offset_fse.len = 0;
        out.offset_fse.accuracy_log = 0;
    }
    if (cached.ml_mode == .compressed) out.match_fse = cached.match_fse else {
        out.match_fse.len = 0;
        out.match_fse.accuracy_log = 0;
    }
}

test "cached sequence spec copies only active compressed tables" {
    var cached: SequenceModeSpec = undefined;
    cached.ll_mode = .predefined;
    cached.of_mode = .compressed;
    cached.ml_mode = .rle;
    cached.literal_rle = null;
    cached.offset_rle = null;
    cached.match_rle = .{ .base = 17, .additional_bits = 2, .next_state = 0, .state_bits = 0 };
    cached.literal_fse.len = 31;
    cached.literal_fse.accuracy_log = 5;
    cached.offset_fse.len = 2;
    cached.offset_fse.accuracy_log = 1;
    cached.offset_fse.entries[0] = .{ .base = 4, .additional_bits = 3, .next_state = 1, .state_bits = 1 };
    cached.offset_fse.entries[1] = .{ .base = 8, .additional_bits = 4, .next_state = 0, .state_bits = 1 };
    cached.match_fse.len = 63;
    cached.match_fse.accuracy_log = 6;
    cached.bitstream_offset = 77;

    var actual: SequenceModeSpec = undefined;
    @memset(std.mem.asBytes(&actual), 0xa5);
    copyCachedSequenceModeSpec(&actual, &cached, 123);

    try std.testing.expectEqual(SymbolMode.predefined, actual.ll_mode);
    try std.testing.expectEqual(SymbolMode.compressed, actual.of_mode);
    try std.testing.expectEqual(SymbolMode.rle, actual.ml_mode);
    try std.testing.expectEqual(cached.match_rle, actual.match_rle);
    try std.testing.expectEqual(@as(usize, 123), actual.bitstream_offset);
    try std.testing.expectEqual(@as(usize, 0), actual.literal_fse.len);
    try std.testing.expectEqual(@as(u8, 0), actual.literal_fse.accuracy_log);
    try std.testing.expectEqual(cached.offset_fse.len, actual.offset_fse.len);
    try std.testing.expectEqual(cached.offset_fse.accuracy_log, actual.offset_fse.accuracy_log);
    try std.testing.expectEqualSlices(SequenceSymbol, cached.offset_fse.entries[0..cached.offset_fse.len], actual.offset_fse.entries[0..actual.offset_fse.len]);
    try std.testing.expectEqual(@as(usize, 0), actual.match_fse.len);
    try std.testing.expectEqual(@as(u8, 0), actual.match_fse.accuracy_log);
}

noinline fn decodeAllFseRawSequencesNarrow(
    block: []const u8,
    section: LiteralOnlySection,
    spec: *const SequenceModeSpec,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
    allow_wildcopy: bool,
) linksection(raw_fse_decode_text_section) Error!void {
    // Route once per block so the ordinary compact executor remains byte-for-
    // byte stable; putting this policy in both large callers moved unrelated
    // FSE/RLE hot code enough to produce a measurable control regression.
    if (sequence_decode_policy.preferRawShortPairs(section.regenerated_size, section.sequence_count))
        return try decodeAllFseRawSequences(
            block,
            section,
            spec,
            output,
            written,
            frame_output_start,
            frame_state,
            continuation,
            state,
            allow_wildcopy,
            false,
            true,
        );
    return try decodeAllFseRawSequences(
        block,
        section,
        spec,
        output,
        written,
        frame_output_start,
        frame_state,
        continuation,
        state,
        allow_wildcopy,
        false,
        false,
    );
}

noinline fn decodeAllFseRawSequences(
    block: []const u8,
    section: LiteralOnlySection,
    spec: *const SequenceModeSpec,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
    allow_wildcopy: bool,
    comptime adaptive_match_copy: bool,
    comptime dense_short_pairs: bool,
) linksection(raw_fse_decode_text_section) Error!void {
    std.debug.assert(section.kind == .raw);
    const literals = block[section.literal_payload_offset..][0..section.regenerated_size];
    if (frame_output_start > written.*) return error.CorruptFrame;
    var literal_offset: usize = 0;
    var reader = state.reader;
    var remaining = state.remaining;
    while (remaining != 0) {
        const ll_word = spec.literal_fse.symbolWordUnchecked(state.ll_state);
        const of_word = spec.offset_fse.symbolWordUnchecked(state.of_state);
        const ml_word = spec.match_fse.symbolWordUnchecked(state.ml_state);
        if (comptime dense_short_pairs) {
            // Packed words are base:u32, next_state:u16, extra:u8, state:u8.
            // Ignore next_state while recognizing the zero-extra LL/OF and
            // one-bit ML transition shared by the alternating 8/23-byte run.
            const shape_mask: u64 = 0xffff_0000_ffff_ffff;
            const ml_shape = ml_word & shape_mask;
            const repeated_1 = state.repeated_offsets[1];
            const common_shape = remaining > 1 and
                ll_word & shape_mask == 0 and
                of_word & shape_mask == 0 and
                ((ml_shape == 0x0100_0000_0000_0008 and repeated_1 == 7) or
                    (ml_shape == 0x0100_0000_0000_0017 and repeated_1 >= 23 and
                        allow_wildcopy and output.len - written.* >= 32));
            if (common_shape) {
                if (repeated_1 > written.* - frame_output_start) return error.InvalidMatch;
                if (reader.remaining_bits == 0) return error.TruncatedFrame;
                reader.remaining_bits -= 1;
                const bit_index: u3 = @intCast(reader.remaining_bits & 7);
                const ml_transition = (reader.bytes[reader.remaining_bits >> 3] >> bit_index) & 1;
                const previous_0 = state.repeated_offsets[0];
                state.repeated_offsets[0] = repeated_1;
                state.repeated_offsets[1] = previous_0;
                state.ll_state = sequenceSymbolNextState(ll_word);
                state.ml_state = sequenceSymbolNextState(ml_word) + ml_transition;
                state.of_state = sequenceSymbolNextState(of_word);
                remaining -= 1;
                if (builtin.is_test) test_all_fse_raw_short_pair_hits += 1;
                if (ml_shape == 0x0100_0000_0000_0008)
                    sequence_match_copy.appendOverlapping8Offset7(output, written)
                else
                    sequence_match_copy.appendForwardWildcopy16(
                        output,
                        written,
                        written.* - repeated_1,
                        23,
                    );
                continue;
            }
        }
        const literal_base_value = sequenceSymbolBase(ll_word);
        const offset_base_value = sequenceSymbolBase(of_word);
        const match_base_value = sequenceSymbolBase(ml_word);
        const ll_additional_bits = sequenceSymbolAdditionalBits(ll_word);
        const of_additional_bits = sequenceSymbolAdditionalBits(of_word);
        const ml_additional_bits = sequenceSymbolAdditionalBits(ml_word);
        const ll_state_bits = sequenceSymbolStateBits(ll_word);
        const of_state_bits = sequenceSymbolStateBits(of_word);
        const ml_state_bits = sequenceSymbolStateBits(ml_word);
        const ll_next_state = sequenceSymbolNextState(ll_word);
        const of_next_state = sequenceSymbolNextState(of_word);
        const ml_next_state = sequenceSymbolNextState(ml_word);
        const transition_bits: u8 = if (remaining == 1)
            0
        else
            ll_state_bits + ml_state_bits + of_state_bits;
        const total_bits: u8 = of_additional_bits + ml_additional_bits +
            ll_additional_bits + transition_bits;
        var field_group = sequence_field_group.Group.init(&reader, total_bits);
        const fields_are_grouped = field_group != null;
        if (builtin.is_test and fields_are_grouped) test_all_fse_raw_field_group_hits += 1;
        const offset_extra = if (fields_are_grouped)
            field_group.?.read(of_additional_bits)
        else
            try reader.readSequenceField(of_additional_bits);
        const match_len = match_base_value + if (fields_are_grouped)
            field_group.?.read(ml_additional_bits)
        else
            try reader.readSequenceField(ml_additional_bits);
        const literal_len = literal_base_value + if (fields_are_grouped)
            field_group.?.read(ll_additional_bits)
        else
            try reader.readSequenceField(ll_additional_bits);
        const match_offset = if (of_additional_bits > 1) blk: {
            const offset = offset_base_value + offset_extra;
            const previous_0 = state.repeated_offsets[0];
            const previous_1 = state.repeated_offsets[1];
            state.repeated_offsets = .{ offset, previous_0, previous_1 };
            break :blk offset;
        } else if (of_additional_bits == 0 and literal_len != 0)
            try large_offset.positiveLiteralRep0(&state.repeated_offsets)
        else
            try resolveSequenceOffset(offset_base_value, of_additional_bits, offset_extra, literal_len, &state.repeated_offsets);
        remaining -= 1;
        if (remaining != 0) {
            if (fields_are_grouped) {
                state.ll_state = ll_next_state + field_group.?.read(ll_state_bits);
                state.ml_state = ml_next_state + field_group.?.read(ml_state_bits);
                state.of_state = of_next_state + field_group.?.read(of_state_bits);
            } else {
                state.ll_state = ll_next_state + try reader.readSequenceField(ll_state_bits);
                state.ml_state = ml_next_state + try reader.readSequenceField(ml_state_bits);
                state.of_state = of_next_state + try reader.readSequenceField(of_state_bits);
            }
        } else try reader.expectEnd();

        if (comptime dense_short_pairs) {
            if (literal_len == 0 and match_len == 8 and match_offset == 7) {
                if (written.* - frame_output_start < 7) return error.InvalidMatch;
                if (output.len - written.* < 8) return error.OutputTooSmall;
                sequence_match_copy.appendOverlapping8Offset7(output, written);
                continue;
            }
            if (literal_len == 0 and
                match_len == 23 and
                match_offset >= 23 and
                allow_wildcopy and
                match_offset <= written.* - frame_output_start and
                output.len - written.* >= 32)
            {
                sequence_match_copy.appendForwardWildcopy16(
                    output,
                    written,
                    written.* - match_offset,
                    match_len,
                );
                continue;
            }
        }

        if (literal_offset > literals.len or literals.len - literal_offset < literal_len) return error.CorruptFrame;
        if (output.len - written.* < literal_len) return error.OutputTooSmall;
        const rounded_match_len = (match_len + 15) & ~@as(usize, 15);
        if (allow_wildcopy and
            match_offset >= 16 and
            match_offset <= written.* - frame_output_start + literal_len and
            output.len - written.* - literal_len >= rounded_match_len)
        {
            if (literal_len == 1) {
                output[written.*] = literals[literal_offset];
                written.* += 1;
                literal_offset += 1;
            } else if (literal_len >= 2 and literal_len <= 15) {
                literal_copy.append2To15(output, written, literals, &literal_offset, literal_len);
            } else if (literal_len != 0) {
                @memcpy(output[written.*..][0..literal_len], literals[literal_offset..][0..literal_len]);
                written.* += literal_len;
                literal_offset += literal_len;
            }
            if (builtin.is_test) test_all_fse_raw_wildcopy_hits += 1;
            if (comptime adaptive_match_copy)
                _ = sequence_match_copy.appendForwardWildcopy(output, written, written.* - match_offset, match_len)
            else
                sequence_match_copy.appendForwardWildcopy16(output, written, written.* - match_offset, match_len);
            continue;
        }

        if (literal_len == 1) {
            output[written.*] = literals[literal_offset];
            written.* += 1;
            literal_offset += 1;
        } else if (literal_len >= 2 and literal_len <= 15) {
            literal_copy.append2To15(output, written, literals, &literal_offset, literal_len);
        } else if (literal_len != 0) {
            @memcpy(output[written.*..][0..literal_len], literals[literal_offset..][0..literal_len]);
            written.* += literal_len;
            literal_offset += literal_len;
        }
        if (match_offset == 0 or match_offset > written.* - frame_output_start) return error.InvalidMatch;
        if (output.len - written.* < match_len) return error.OutputTooSmall;
        if (match_len == 3 and match_offset >= 3)
            sequence_match_copy.appendNonOverlapping3(output, written, written.* - match_offset)
        else if (match_len >= 4 and match_len <= 7 and match_offset >= match_len)
            sequence_match_copy.appendNonOverlapping4To7(output, written, written.* - match_offset, match_len, false)
        else if (match_len >= 8 and match_len <= 15 and match_offset >= match_len)
            sequence_match_copy.appendNonOverlapping8To15(output, written, written.* - match_offset, match_len, false)
        else if (match_len >= 16 and match_len <= 31 and match_offset >= match_len)
            sequence_match_copy.appendNonOverlapping16To31(output, written, written.* - match_offset, match_len)
        else if (match_len >= 32 and match_len <= 63 and match_offset >= match_len)
            sequence_match_copy.appendNonOverlapping32To63(output, written, written.* - match_offset, match_len)
        else if (match_len >= 68 and match_len <= 70 and match_offset >= match_len)
            sequence_match_copy.appendNonOverlapping68To70(output, written, written.* - match_offset, match_len)
        else if (match_len == 71 and match_offset >= 71)
            sequence_match_copy.appendNonOverlapping71(output, written, written.* - match_offset)
        else if (match_len == 8 and match_offset == 7)
            sequence_match_copy.appendOverlapping8Offset7(output, written)
        else if (match_len == 23 and match_offset >= 23)
            sequence_match_copy.appendNonOverlapping23(output, written, written.* - match_offset)
        else
            sequence_match_copy.append(output, written, written.* - match_offset, match_len);
    }
    const last_literals = literals.len - literal_offset;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    @memcpy(output[written.*..][0..last_literals], literals[literal_offset..]);
    written.* += last_literals;
    state.remaining = remaining;
    state.reader = reader;
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

noinline fn decodeAllFseHuffmanSequences(
    section: LiteralOnlySection,
    spec: *const SequenceModeSpec,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
    comptime allow_wildcopy: bool,
    comptime use_match_wildcopy: bool,
    initial_huffman: HuffmanLiteralDecodeState,
) align(256) Error!void {
    var huffman_state = initial_huffman;
    var literal_offset: usize = 0;
    while (state.remaining != 0) {
        const ll_word = spec.literal_fse.symbolWordUnchecked(state.ll_state);
        const of_word = spec.offset_fse.symbolWordUnchecked(state.of_state);
        const ml_word = spec.match_fse.symbolWordUnchecked(state.ml_state);
        const literal_base_value = sequenceSymbolBase(ll_word);
        const offset_base_value = sequenceSymbolBase(of_word);
        const match_base_value = sequenceSymbolBase(ml_word);
        const ll_additional_bits = sequenceSymbolAdditionalBits(ll_word);
        const of_additional_bits = sequenceSymbolAdditionalBits(of_word);
        const ml_additional_bits = sequenceSymbolAdditionalBits(ml_word);
        const ll_state_bits = sequenceSymbolStateBits(ll_word);
        const of_state_bits = sequenceSymbolStateBits(of_word);
        const ml_state_bits = sequenceSymbolStateBits(ml_word);
        const ll_next_state = sequenceSymbolNextState(ll_word);
        const of_next_state = sequenceSymbolNextState(of_word);
        const ml_next_state = sequenceSymbolNextState(ml_word);
        state.remaining -= 1;
        const transition_bits: u8 = if (state.remaining == 0)
            0
        else
            ll_state_bits + ml_state_bits + of_state_bits;
        const total_bits: u8 = of_additional_bits + ml_additional_bits +
            ll_additional_bits + transition_bits;
        var field_group: ?sequence_field_group.Group =
            sequence_field_group.Group.init(&state.reader, total_bits);
        const fields_are_grouped = field_group != null;
        const offset_extra = if (fields_are_grouped)
            field_group.?.read(of_additional_bits)
        else
            try state.reader.readSequenceField(of_additional_bits);
        const match_len = match_base_value + if (fields_are_grouped)
            field_group.?.read(ml_additional_bits)
        else
            try state.reader.readSequenceField(ml_additional_bits);
        const literal_len = literal_base_value + if (fields_are_grouped)
            field_group.?.read(ll_additional_bits)
        else
            try state.reader.readSequenceField(ll_additional_bits);
        const match_offset = try resolveSequenceOffset(offset_base_value, of_additional_bits, offset_extra, literal_len, &state.repeated_offsets);
        if (state.remaining != 0) {
            if (fields_are_grouped) {
                state.ll_state = ll_next_state + field_group.?.read(ll_state_bits);
                state.ml_state = ml_next_state + field_group.?.read(ml_state_bits);
                state.of_state = of_next_state + field_group.?.read(of_state_bits);
            } else {
                state.ll_state = ll_next_state + try state.reader.readSequenceField(ll_state_bits);
                state.ml_state = ml_next_state + try state.reader.readSequenceField(ml_state_bits);
                state.of_state = of_next_state + try state.reader.readSequenceField(of_state_bits);
            }
        } else try state.reader.expectEnd();

        if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < literal_len) return error.CorruptFrame;
        if (output.len - written.* < literal_len) return error.OutputTooSmall;
        try copyLiteralsFromHuffmanStateFast(&huffman_state, &section, literal_offset, output[written.*..][0..literal_len]);
        written.* += literal_len;
        literal_offset += literal_len;
        const rounded_match_len = (match_len + 15) & ~@as(usize, 15);
        if (match_len == 71 and match_offset >= 71 and frame_output_start <= written.* and match_offset <= written.* - frame_output_start) {
            if (output.len - written.* < match_len) return error.OutputTooSmall;
            sequence_match_copy.appendNonOverlapping71(output, written, written.* - match_offset);
        } else if (use_match_wildcopy and allow_wildcopy and
            frame_output_start <= written.* and
            match_len >= 16 and
            match_offset >= 16 and
            match_offset <= written.* - frame_output_start and
            output.len - written.* >= rounded_match_len)
        {
            _ = sequence_match_copy.appendForwardWildcopy(
                output,
                written,
                written.* - match_offset,
                match_len,
            );
        } else {
            try copyMatchFromHistory(output, written, frame_output_start, &.{}, match_offset, match_len);
        }
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    const last_literals = section.regenerated_size - literal_offset;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    try copyLiteralsFromHuffmanStateFast(&huffman_state, &section, literal_offset, output[written.*..][0..last_literals]);
    written.* += last_literals;
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

/// Decode the small-literal medium-density blocks selected by
/// `preferHuffmanMatchWildcopy` without inheriting the large split executor's
/// synthetic-corpus pair and fixed-length branches.
noinline fn tryDecodeMediumSplitHuffmanSequences(
    section: LiteralOnlySection,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
) align(256) linksection(medium_split_literal_decode_text_section) Error!bool {
    if (section.regenerated_size > sequence_decode_policy.medium_split_literal_max or
        section.huffman_streams != .four)
        return false;
    if (frame_output_start > written.*) return error.CorruptFrame;

    var literals: [sequence_decode_policy.medium_split_literal_max + 16]u8 = undefined;
    if (!try decodeLargeFourStreamHuffman(section, literals[0..section.regenerated_size])) return false;
    @memset(literals[section.regenerated_size..][0..16], 0);

    const spec = state.spec;
    var reader = state.reader;
    var remaining = state.remaining;
    var literal_offset: usize = 0;
    while (remaining != 0) {
        const ll_word = spec.literal_fse.symbolWordUnchecked(state.ll_state);
        const of_word = spec.offset_fse.symbolWordUnchecked(state.of_state);
        const ml_word = spec.match_fse.symbolWordUnchecked(state.ml_state);
        const literal_base_value = sequenceSymbolBase(ll_word);
        const offset_base_value = sequenceSymbolBase(of_word);
        const match_base_value = sequenceSymbolBase(ml_word);
        const ll_additional_bits = sequenceSymbolAdditionalBits(ll_word);
        const of_additional_bits = sequenceSymbolAdditionalBits(of_word);
        const ml_additional_bits = sequenceSymbolAdditionalBits(ml_word);
        const ll_state_bits = sequenceSymbolStateBits(ll_word);
        const of_state_bits = sequenceSymbolStateBits(of_word);
        const ml_state_bits = sequenceSymbolStateBits(ml_word);
        const ll_next_state = sequenceSymbolNextState(ll_word);
        const of_next_state = sequenceSymbolNextState(of_word);
        const ml_next_state = sequenceSymbolNextState(ml_word);
        remaining -= 1;
        const transition_bits: u8 = if (remaining == 0)
            0
        else
            ll_state_bits + ml_state_bits + of_state_bits;
        const total_bits: u8 = of_additional_bits + ml_additional_bits +
            ll_additional_bits + transition_bits;
        var field_group = sequence_field_group.Group.init(&reader, total_bits);
        const fields_are_grouped = field_group != null;
        const offset_extra = if (fields_are_grouped)
            field_group.?.read(of_additional_bits)
        else
            try reader.readSequenceField(of_additional_bits);
        const match_len = match_base_value + if (fields_are_grouped)
            field_group.?.read(ml_additional_bits)
        else
            try reader.readSequenceField(ml_additional_bits);
        const literal_len = literal_base_value + if (fields_are_grouped)
            field_group.?.read(ll_additional_bits)
        else
            try reader.readSequenceField(ll_additional_bits);
        const match_offset = try resolveSequenceOffset(
            offset_base_value,
            of_additional_bits,
            offset_extra,
            literal_len,
            &state.repeated_offsets,
        );
        if (remaining != 0) {
            if (fields_are_grouped) {
                state.ll_state = ll_next_state + field_group.?.read(ll_state_bits);
                state.ml_state = ml_next_state + field_group.?.read(ml_state_bits);
                state.of_state = of_next_state + field_group.?.read(of_state_bits);
            } else {
                state.ll_state = ll_next_state + try reader.readSequenceField(ll_state_bits);
                state.ml_state = ml_next_state + try reader.readSequenceField(ml_state_bits);
                state.of_state = of_next_state + try reader.readSequenceField(of_state_bits);
            }
        } else try reader.expectEnd();

        const rounded_match_len = (match_len + 15) & ~@as(usize, 15);
        if (literal_len <= 15 and
            literal_offset <= section.regenerated_size and
            section.regenerated_size - literal_offset >= literal_len and
            match_len >= 16 and
            match_offset >= 16 and
            match_offset <= written.* - frame_output_start + literal_len and
            output.len - written.* >= literal_len + rounded_match_len)
        {
            literal_copy.appendUpTo15Wildcopy16(
                output,
                written,
                &literals,
                &literal_offset,
                literal_len,
            );
            _ = sequence_match_copy.appendForwardWildcopy(
                output,
                written,
                written.* - match_offset,
                match_len,
            );
            continue;
        }

        if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < literal_len)
            return error.CorruptFrame;
        if (output.len - written.* < literal_len) return error.OutputTooSmall;
        if (literal_len == 1) {
            output[written.*] = literals[literal_offset];
            written.* += 1;
            literal_offset += 1;
        } else if (literal_len >= 2 and literal_len <= 15) {
            literal_copy.append2To15(output, written, &literals, &literal_offset, literal_len);
        } else if (literal_len != 0) {
            @memcpy(output[written.*..][0..literal_len], literals[literal_offset..][0..literal_len]);
            written.* += literal_len;
            literal_offset += literal_len;
        }
        if (match_offset == 0 or match_offset > written.* - frame_output_start) return error.InvalidMatch;
        if (output.len - written.* < match_len) return error.OutputTooSmall;
        try copyMatchFromHistory(output, written, frame_output_start, &.{}, match_offset, match_len);
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    const last_literals = section.regenerated_size - literal_offset;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    @memcpy(output[written.*..][0..last_literals], literals[literal_offset..][0..last_literals]);
    written.* += last_literals;
    state.remaining = remaining;
    state.reader = reader;
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
    return true;
}

