}

inline fn shouldUseSplitSequenceWildcopy(
    comptime use_wide_copies: bool,
    comptime use_long_match_wildcopy: bool,
    match_len: usize,
) bool {
    return use_wide_copies or
        (use_long_match_wildcopy and (match_len < 68 or match_len >= 72));
}

test "zstd compact split wildcopy preserves fixed match cluster" {
    for (3..68) |match_len|
        try std.testing.expect(shouldUseSplitSequenceWildcopy(false, true, match_len));
    for (68..72) |match_len|
        try std.testing.expect(!shouldUseSplitSequenceWildcopy(false, true, match_len));
    for (72..129) |match_len|
        try std.testing.expect(shouldUseSplitSequenceWildcopy(false, true, match_len));
    for (3..129) |match_len| {
        try std.testing.expect(!shouldUseSplitSequenceWildcopy(false, false, match_len));
        try std.testing.expect(shouldUseSplitSequenceWildcopy(true, false, match_len));
    }
}

noinline fn tryDecodeGenericSplitHuffmanSequences(
    section: LiteralOnlySection,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
) linksection(split_generic_literal_decode_text_section) Error!bool {
    if (section.huffman_streams != .four) return false;
    if (frame_output_start > written.*) return error.CorruptFrame;

    var literals: [split_wide_huffman_literal_capacity]u8 = undefined;
    if (!try decodeLargeFourStreamHuffman(section, literals[0..section.regenerated_size])) return false;
    var literal_offset: usize = 0;
    while (state.remaining != 0) {
        const sequence = try readModeSequence(state);
        if (literal_offset > section.regenerated_size or
            section.regenerated_size - literal_offset < sequence.literal_len)
            return error.CorruptFrame;
        if (output.len - written.* < sequence.literal_len) return error.OutputTooSmall;
        if (sequence.literal_len != 0) {
            @memcpy(
                output[written.*..][0..sequence.literal_len],
                literals[literal_offset..][0..sequence.literal_len],
            );
            written.* += sequence.literal_len;
            literal_offset += sequence.literal_len;
        }
        try copyMatchFromHistory(
            output,
            written,
            frame_output_start,
            &.{},
            sequence.match_offset,
            sequence.match_len,
        );
    }

    const last_literals = section.regenerated_size - literal_offset;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    @memcpy(output[written.*..][0..last_literals], literals[literal_offset..][0..last_literals]);
    written.* += last_literals;
    if (continuation.retainsState()) {
        frame_state.previous_tables = state.spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
    return true;
}

noinline fn executeSplitHuffmanSequenceCold(
    literals: []const u8,
    regenerated_size: usize,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    literal_offset: *usize,
    literal_len: usize,
    match_offset: usize,
    match_len: usize,
) Error!void {
    if (literal_offset.* > regenerated_size or regenerated_size - literal_offset.* < literal_len) return error.CorruptFrame;
    if (output.len - written.* < literal_len) return error.OutputTooSmall;
    if (literal_len <= 15 and output.len - written.* >= 16) {
        literal_copy.appendUpTo15Wildcopy16(output, written, literals, literal_offset, literal_len);
    } else if (literal_len != 0) {
        @memcpy(output[written.*..][0..literal_len], literals[literal_offset.*..][0..literal_len]);
        written.* += literal_len;
        literal_offset.* += literal_len;
    }
    try copyMatchFromHistory(output, written, frame_output_start, &.{}, match_offset, match_len);
}

noinline fn decodeFseFseRleSequences(
    block: []const u8,
    section: LiteralOnlySection,
    spec: *const SequenceModeSpec,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
    maybe_huffman: ?HuffmanLiteralDecodeState,
) linksection(fse_fse_rle_decode_text_section) Error!void {
    var huffman_literals = maybe_huffman;
    var literal_offset: usize = 0;
    const ml_symbol = spec.match_rle orelse return error.CorruptFrame;
    while (state.remaining != 0) {
        const ll_symbol = spec.literal_fse.symbolUnchecked(state.ll_state);
        const of_symbol = spec.offset_fse.symbolUnchecked(state.of_state);
        const offset_extra = try state.reader.readSequenceField(of_symbol.additional_bits);
        const match_len = std.math.add(usize, ml_symbol.base, try state.reader.readSequenceField(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
        const literal_len = std.math.add(usize, ll_symbol.base, try state.reader.readSequenceField(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
        const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &state.repeated_offsets);
        state.remaining -= 1;
        if (state.remaining != 0) {
            state.ll_state = try nextSequenceState(&state.reader, ll_symbol);
            state.of_state = try nextSequenceState(&state.reader, of_symbol);
        } else try state.reader.expectEnd();

        if (huffman_literals) |*huffman_state| {
            if (output.len - written.* < literal_len) return error.OutputTooSmall;
            try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..literal_len]);
            written.* += literal_len;
        } else try copyLiteralsFromSection(block, section, literal_offset, output, written, literal_len);
        literal_offset = std.math.add(usize, literal_offset, literal_len) catch return error.IntegerOverflow;
        const available_in_frame = written.* - frame_output_start;
        if (match_len == 48 and match_offset >= 48 and match_offset <= available_in_frame) {
            if (output.len - written.* < match_len) return error.OutputTooSmall;
            sequence_match_copy.appendNonOverlapping48(output, written, written.* - match_offset);
        } else {
            try copyMatchFromHistory(output, written, frame_output_start, dictionary_history, match_offset, match_len);
        }
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    const last_literals = section.regenerated_size - literal_offset;
    if (huffman_literals) |*huffman_state| {
        if (output.len - written.* < last_literals) return error.OutputTooSmall;
        try copyLiteralsFromHuffmanState(huffman_state, &section, literal_offset, output[written.*..][0..last_literals]);
        written.* += last_literals;
    } else try copyLiteralsFromSection(block, section, literal_offset, output, written, last_literals);
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

noinline fn decodeFseRleRleRawSequences(
    block: []const u8,
    section: LiteralOnlySection,
    spec: *const SequenceModeSpec,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
    state: *SequenceDecodeState,
) linksection(fse_rle_rle_decode_text_section) Error!void {
    std.debug.assert(section.kind == .raw);
    const literals = block[section.literal_payload_offset..][0..section.regenerated_size];
    const of_symbol = spec.offset_rle orelse return error.CorruptFrame;
    const ml_symbol = spec.match_rle orelse return error.CorruptFrame;
    var literal_offset: usize = 0;
    while (state.remaining != 0) {
        const ll_symbol = spec.literal_fse.symbolUnchecked(state.ll_state);
        const offset_extra = try state.reader.readSequenceField(of_symbol.additional_bits);
        const match_len = std.math.add(usize, ml_symbol.base, try state.reader.readSequenceField(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
        const literal_len = std.math.add(usize, ll_symbol.base, try state.reader.readSequenceField(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
        const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &state.repeated_offsets);
        state.remaining -= 1;
        if (state.remaining != 0)
            state.ll_state = try nextSequenceState(&state.reader, ll_symbol)
        else
            try state.reader.expectEnd();

        if (literal_offset > literals.len or literals.len - literal_offset < literal_len) return error.CorruptFrame;
        if (output.len - written.* < literal_len) return error.OutputTooSmall;
        if (literal_len == 16) {
            const literal_chunk: @Vector(16, u8) = literals[literal_offset..][0..16].*;
            output[written.*..][0..16].* = literal_chunk;
            written.* += 16;
            literal_offset += 16;
        } else if (literal_len != 0) {
            @memcpy(output[written.*..][0..literal_len], literals[literal_offset..][0..literal_len]);
            written.* += literal_len;
            literal_offset += literal_len;
        }
        if (frame_output_start > written.*) return error.CorruptFrame;
        if (match_offset == 0 or match_offset > written.* - frame_output_start) return error.InvalidMatch;
        if (output.len - written.* < match_len) return error.OutputTooSmall;
        if (match_len == 48 and match_offset >= 48)
            sequence_match_copy.appendNonOverlapping48(output, written, written.* - match_offset)
        else
            sequence_match_copy.append(output, written, written.* - match_offset, match_len);
    }
    const last_literals = literals.len - literal_offset;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    @memcpy(output[written.*..][0..last_literals], literals[literal_offset..]);
    written.* += last_literals;
    if (continuation.retainsState()) {
        frame_state.previous_tables = spec.tables();
        frame_state.repeated_offsets = state.repeated_offsets;
    }
}

test "zstd FSE RLE RLE raw sequence loop matches generic decode" {
    const sequence_count = 1024;
    const prefix_len = 64;
    const literal_len = 16;
    const match_len = 48;
    const output_len = prefix_len + sequence_count * (literal_len + match_len);

    var literals: [sequence_count * literal_len]u8 = undefined;
    for (&literals, 0..) |*byte, index| byte.* = @truncate(index * 37 + 11);
    const section: LiteralOnlySection = .{
        .kind = .raw,
        .size_format = 0,
        .regenerated_size = literals.len,
        .literal_payload_offset = 0,
        .huffman_stream_offset = 0,
        .huffman_streams = .none,
        .sequence_count = sequence_count,
        .sequence_payload_offset = literals.len,
    };
    var literal_table: SequenceFseTable = .{};
    literal_table.len = 2;
    literal_table.accuracy_log = 1;
    literal_table.entries[0] = .{ .base = literal_len, .additional_bits = 0, .next_state = 0, .state_bits = 1 };
    literal_table.entries[1] = literal_table.entries[0];
    const spec: SequenceModeSpec = .{
        .ll_mode = .compressed,
        .of_mode = .rle,
        .ml_mode = .rle,
        .literal_rle = null,
        .offset_rle = try sequenceRleSymbol(.offset, 0),
        .match_rle = try sequenceRleSymbol(.match, try sequenceCodeForValue(match_len, &ml_base, &ml_bits)),
        .literal_fse = literal_table,
        .offset_fse = .{},
        .match_fse = .{},
        .bitstream_offset = 0,
    };

    var fields: [sequence_count * 2]BitField = undefined;
    var field_count: usize = 0;
    fields[field_count] = .{ .value = 0, .bits = 1 };
    field_count += 1;
    for (0..sequence_count) |index| {
        fields[field_count] = .{ .value = 1, .bits = 2 };
        field_count += 1;
        if (index + 1 < sequence_count) {
            fields[field_count] = .{ .value = index & 1, .bits = 1 };
            field_count += 1;
        }
    }
    var sequence_bits: std.ArrayList(u8) = .empty;
    defer sequence_bits.deinit(std.testing.allocator);
    try emitReverseBitstreamFromReadOrder(std.testing.allocator, &sequence_bits, fields[0..field_count]);

    var expected: [output_len]u8 = undefined;
    for (expected[0..prefix_len], 0..) |*byte, index| byte.* = @truncate(index * 19 + 7);
    var expected_written: usize = prefix_len;
    var expected_state = try initSequenceDecodeState(&spec, sequence_count, try ReverseBitReader.init(sequence_bits.items), .{ prefix_len, 4, 8 });
    var literal_offset: usize = 0;
    while (expected_state.remaining != 0) {
        const sequence = try readModeSequence(&expected_state);
        try copyLiteralsFromSection(&literals, section, literal_offset, &expected, &expected_written, sequence.literal_len);
        literal_offset += sequence.literal_len;
        try copyMatchFromHistory(&expected, &expected_written, 0, &.{}, sequence.match_offset, sequence.match_len);
    }
    try std.testing.expectEqual(literals.len, literal_offset);
    try std.testing.expectEqual(output_len, expected_written);

    var actual: [output_len]u8 = undefined;
    @memcpy(actual[0..prefix_len], expected[0..prefix_len]);
    @memset(actual[prefix_len..], 0xa5);
    var actual_written: usize = prefix_len;
    var actual_state = try initSequenceDecodeState(&spec, sequence_count, try ReverseBitReader.init(sequence_bits.items), .{ prefix_len, 4, 8 });
    var actual_frame_state: SequenceFrameState = .{ .repeated_offsets = .{ prefix_len, 4, 8 } };
    try decodeFseRleRleRawSequences(
        &literals,
        section,
        &spec,
        &actual,
        &actual_written,
        0,
        &actual_frame_state,
        .followed_by_block,
        &actual_state,
    );
    try std.testing.expectEqual(expected_written, actual_written);
    try std.testing.expectEqualSlices(u8, &expected, &actual);
    try std.testing.expectEqual(expected_state.repeated_offsets, actual_state.repeated_offsets);
    try std.testing.expectEqual(actual_state.repeated_offsets, actual_frame_state.repeated_offsets);
    try std.testing.expectEqual(SymbolMode.compressed, actual_frame_state.previous_tables.?.ll_mode);
    try std.testing.expectEqual(SymbolMode.rle, actual_frame_state.previous_tables.?.of_mode);
    try std.testing.expectEqual(SymbolMode.rle, actual_frame_state.previous_tables.?.ml_mode);

    var short_state = try initSequenceDecodeState(&spec, sequence_count, try ReverseBitReader.init(sequence_bits.items), .{ prefix_len, 4, 8 });
    var short_written: usize = prefix_len;
    var short_frame_state: SequenceFrameState = .{ .repeated_offsets = .{ prefix_len, 4, 8 } };
    try std.testing.expectError(error.OutputTooSmall, decodeFseRleRleRawSequences(
        &literals,
        section,
        &spec,
        actual[0 .. actual.len - 1],
        &short_written,
        0,
        &short_frame_state,
        .terminal,
        &short_state,
    ));

    var invalid_state = try initSequenceDecodeState(&spec, sequence_count, try ReverseBitReader.init(sequence_bits.items), .{ prefix_len + literal_len + 1, 4, 8 });
    var invalid_written: usize = prefix_len;
    var invalid_frame_state: SequenceFrameState = .{ .repeated_offsets = .{ prefix_len + literal_len + 1, 4, 8 } };
    try std.testing.expectError(error.InvalidMatch, decodeFseRleRleRawSequences(
        &literals,
        section,
        &spec,
        &actual,
        &invalid_written,
        0,
        &invalid_frame_state,
        .terminal,
        &invalid_state,
    ));
}

fn decodeSinglePredefinedSequence(
    block: []const u8,
    section: LiteralOnlySection,
    bitstream_offset: usize,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    frame_state: *SequenceFrameState,
    continuation: sequence_continuation.Context,
) Error!void {
    if (bitstream_offset >= block.len) return error.TruncatedFrame;
    const sequence = try single_predefined.decode(block[bitstream_offset..]);
    var repeated_offsets = frame_state.repeated_offsets;
    const match_offset = try resolveSequenceOffset(
        sequence.offset_base,
        sequence.offset_bits,
        sequence.offset_extra,
        sequence.literal_len,
        &repeated_offsets,
    );

    try copyLiteralsFromSection(
        block,
        section,
        0,
        output,
        written,
        sequence.literal_len,
    );
    try copyMatchFromHistory(
        output,
        written,
        frame_output_start,
        dictionary_history,
        match_offset,
        sequence.match_len,
    );
    if (section.regenerated_size < sequence.literal_len) {
        return error.CorruptFrame;
    }
    try copyLiteralsFromSection(
        block,
        section,
        sequence.literal_len,
        output,
        written,
        section.regenerated_size - sequence.literal_len,
    );
    if (continuation.retainsState()) {
        frame_state.previous_tables = .{
            .ll_mode = .predefined,
            .of_mode = .predefined,
            .ml_mode = .predefined,
            .literal_rle = null,
            .offset_rle = null,
            .match_rle = null,
        };
        frame_state.repeated_offsets = repeated_offsets;
    }
}

fn rleSequencesCompressedBlockDecodedSize(
    block: []const u8,
    section: LiteralOnlySection,
    initial_output_len: usize,
    frame_state: *SequenceFrameState,
) Error!usize {
    var offset = section.sequence_payload_offset;
    const parsed_spec = try parseSequenceModeSpec(block, &offset, section.sequence_count);
    const spec = try resolveSequenceModeSpec(parsed_spec, frame_state.previous_tables);
    try expectConsumedBlock(offset, block.len);
    const bit_reader = try ReverseBitReader.init(block[spec.bitstream_offset..]);

    var state = try initSequenceDecodeState(&spec, section.sequence_count, bit_reader, frame_state.repeated_offsets);
    var literal_offset: usize = 0;
    var produced: usize = 0;
    while (state.remaining != 0) {
        const sequence = try readModeSequence(&state);
        const literal_len = sequence.literal_len;
        if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < literal_len) {
            return error.CorruptFrame;
        }
        literal_offset = std.math.add(usize, literal_offset, literal_len) catch return error.IntegerOverflow;
        produced = std.math.add(usize, produced, literal_len) catch return error.IntegerOverflow;
        const available = std.math.add(usize, initial_output_len, produced) catch return error.IntegerOverflow;
        if (sequence.match_offset == 0 or sequence.match_offset > available) return error.InvalidMatch;
        produced = std.math.add(usize, produced, sequence.match_len) catch return error.IntegerOverflow;
    }
    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
    produced = std.math.add(usize, produced, section.regenerated_size - literal_offset) catch return error.IntegerOverflow;
    try validateHuffmanLiteralsConsumed(block, section);
    frame_state.previous_tables = spec.tables();
    frame_state.repeated_offsets = state.repeated_offsets;
    return produced;
}

const SequenceDecodeState = struct {
    // The parsed tables remain owned by the surrounding block decoder. Keep a
    // borrowed pointer here so every cursor and specialized executor does not
    // copy the three 512-entry table buffers across its hot call boundary.
    spec: *const SequenceModeSpec,
    reader: ReverseBitReader,
    ll_state: usize = 0,
    of_state: usize = 0,
    ml_state: usize = 0,
    repeated_offsets: [3]usize = initial_repeated_offsets,
    remaining: usize,
};

comptime {
    std.debug.assert(@sizeOf(SequenceDecodeState) <= 128);
}

/// Resumable sequence cursor used by the incremental block-stream path. The
/// resolved tables live in `SequenceFrameState`, avoiding another copy of the
/// three bounded FSE tables in every decoder instance.
const StreamingSequenceDecodeState = struct {
    reader: ReverseBitReader,
    ll_state: usize = 0,
    of_state: usize = 0,
    ml_state: usize = 0,
    repeated_offsets: [3]usize = initial_repeated_offsets,
    remaining: usize,
};

fn initStreamingSequenceDecodeState(
    spec: SequenceModeSpec,
    sequence_count: usize,
    reader: ReverseBitReader,
    repeated_offsets: [3]usize,
) Error!StreamingSequenceDecodeState {
    var initialized_reader = reader;
    const ll_state = try readInitialSequenceState(&initialized_reader, spec.ll_mode, spec.literal_fse.accuracy_log, 6);
    const of_state = try readInitialSequenceState(&initialized_reader, spec.of_mode, spec.offset_fse.accuracy_log, 5);
    const ml_state = try readInitialSequenceState(&initialized_reader, spec.ml_mode, spec.match_fse.accuracy_log, 6);
    return .{
        .reader = initialized_reader,
        .ll_state = ll_state,
        .of_state = of_state,
        .ml_state = ml_state,
        .repeated_offsets = repeated_offsets,
        .remaining = sequence_count,
    };
}

fn readStreamingModeSequence(tables: *const SequenceTables, state: *StreamingSequenceDecodeState) Error!DecodedSequence {
    if (state.remaining == 0) return error.CorruptFrame;
    const ll_symbol = try currentStreamingSymbol(tables.ll_mode, tables.literal_rle, &tables.literal_fse, state.ll_state, .literal);
    const of_symbol = try currentStreamingSymbol(tables.of_mode, tables.offset_rle, &tables.offset_fse, state.of_state, .offset);
    const ml_symbol = try currentStreamingSymbol(tables.ml_mode, tables.match_rle, &tables.match_fse, state.ml_state, .match);
    const offset_extra = try state.reader.read(of_symbol.additional_bits);
    const match_len = std.math.add(usize, ml_symbol.base, try state.reader.read(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
    const literal_len = std.math.add(usize, ll_symbol.base, try state.reader.read(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
    const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &state.repeated_offsets);
    state.remaining -= 1;
    if (state.remaining != 0) {
        if (tables.ll_mode == .predefined or tables.ll_mode == .compressed) state.ll_state = try nextSequenceState(&state.reader, ll_symbol);
        if (tables.ml_mode == .predefined or tables.ml_mode == .compressed) state.ml_state = try nextSequenceState(&state.reader, ml_symbol);
        if (tables.of_mode == .predefined or tables.of_mode == .compressed) state.of_state = try nextSequenceState(&state.reader, of_symbol);
    } else {
        try state.reader.expectEnd();
    }
    return .{ .literal_len = literal_len, .match_len = match_len, .match_offset = match_offset };
}

fn currentStreamingSymbol(
    mode: SymbolMode,
    rle: ?SequenceSymbol,
    fse: *const SequenceFseTable,
    state: usize,
    selector: enum { literal, offset, match },
) Error!SequenceSymbol {
    return switch (mode) {
        .predefined => switch (selector) {
            .literal => try defaultLiteralLengthSymbol(state),
            .offset => try defaultOffsetSymbol(state),
            .match => try defaultMatchLengthSymbol(state),
        },
        .rle => rle orelse error.CorruptFrame,
        .compressed => try fse.symbol(state),
        .repeat => unreachable,
    };
}

fn initSequenceDecodeState(
    spec: *const SequenceModeSpec,
    sequence_count: usize,
    reader: ReverseBitReader,
    repeated_offsets: [3]usize,
) Error!SequenceDecodeState {
    var initialized_reader = reader;
    const ll_state = try readInitialSequenceState(&initialized_reader, spec.ll_mode, spec.literal_fse.accuracy_log, 6);
    const of_state = try readInitialSequenceState(&initialized_reader, spec.of_mode, spec.offset_fse.accuracy_log, 5);
    const ml_state = try readInitialSequenceState(&initialized_reader, spec.ml_mode, spec.match_fse.accuracy_log, 6);
    return .{
        .spec = spec,
        .reader = initialized_reader,
        .ll_state = ll_state,
        .of_state = of_state,
        .ml_state = ml_state,
        .repeated_offsets = repeated_offsets,
        .remaining = sequence_count,
    };
}

fn readInitialSequenceState(reader: *ReverseBitReader, mode: SymbolMode, fse_accuracy_log: u8, predefined_accuracy_log: u8) Error!usize {
    return switch (mode) {
        .predefined => try reader.readSmall(@intCast(predefined_accuracy_log)),
        .compressed => try reader.readSmall(@intCast(fse_accuracy_log)),
        .rle => 0,
        .repeat => unreachable,
    };
}

fn readModeSequence(state: *SequenceDecodeState) Error!DecodedSequence {
    if (state.remaining == 0) return error.CorruptFrame;

    // Keep the compact cursor behind a pointer so symbol lookup shares both the
    // cursor and its borrowed tables without copying either one on hot paths.
    const ll_symbol = try currentLiteralSymbol(state);
    const of_symbol = try currentOffsetSymbol(state);
    const ml_symbol = try currentMatchSymbol(state);

    // Zstandard stores the offset extra bits before match/literal extra bits,
    // but repeat-offset selection depends on the *fully decoded* literal
    // length, not merely the literal-length symbol base. Keep the bit-read order
    // intact while delaying repeat-offset mutation until the literal extra bits
    // are known.
    const offset_extra = try state.reader.read(of_symbol.additional_bits);
    const match_len = std.math.add(usize, ml_symbol.base, try state.reader.read(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
    const literal_len = std.math.add(usize, ll_symbol.base, try state.reader.read(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
    const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &state.repeated_offsets);

    state.remaining -= 1;
    if (state.remaining != 0) {
        try updateLiteralState(state, ll_symbol);
        try updateMatchState(state, ml_symbol);
        try updateOffsetState(state, of_symbol);
    } else {
        try state.reader.expectEnd();
    }

    return .{ .literal_len = literal_len, .match_len = match_len, .match_offset = match_offset };
}

fn currentLiteralSymbol(state: *const SequenceDecodeState) Error!SequenceSymbol {
    return switch (state.spec.ll_mode) {
        .predefined => try defaultLiteralLengthSymbol(state.ll_state),
        .rle => state.spec.literal_rle orelse error.CorruptFrame,
        .compressed => try state.spec.literal_fse.symbol(state.ll_state),
        .repeat => unreachable,
    };
}

fn currentOffsetSymbol(state: *const SequenceDecodeState) Error!SequenceSymbol {
    return switch (state.spec.of_mode) {
        .predefined => try defaultOffsetSymbol(state.of_state),
        .rle => state.spec.offset_rle orelse error.CorruptFrame,
        .compressed => try state.spec.offset_fse.symbol(state.of_state),
        .repeat => unreachable,
    };
}

fn currentMatchSymbol(state: *const SequenceDecodeState) Error!SequenceSymbol {
    return switch (state.spec.ml_mode) {
        .predefined => try defaultMatchLengthSymbol(state.ml_state),
        .rle => state.spec.match_rle orelse error.CorruptFrame,
        .compressed => try state.spec.match_fse.symbol(state.ml_state),
        .repeat => unreachable,
    };
}

fn updateLiteralState(state: *SequenceDecodeState, symbol: SequenceSymbol) Error!void {
    if (state.spec.ll_mode == .predefined or state.spec.ll_mode == .compressed) state.ll_state = try nextSequenceState(&state.reader, symbol);
}

fn updateOffsetState(state: *SequenceDecodeState, symbol: SequenceSymbol) Error!void {
    if (state.spec.of_mode == .predefined or state.spec.of_mode == .compressed) state.of_state = try nextSequenceState(&state.reader, symbol);
}

fn updateMatchState(state: *SequenceDecodeState, symbol: SequenceSymbol) Error!void {
    if (state.spec.ml_mode == .predefined or state.spec.ml_mode == .compressed) state.ml_state = try nextSequenceState(&state.reader, symbol);
}

const DecodedSequence = struct {
    literal_len: usize,
    match_len: usize,
    match_offset: usize,
};

const NativeSequenceDecodeStagePath = enum {
    generic,
    bounded_all_fse,
    wide_all_fse,
};

const PreparedNativeSequenceDecodeBlock = struct {
    spec: SequenceModeSpec,
    bitstream: []const u8,
    sequence_count: usize,
    repeated_offsets: [3]usize,
    path: NativeSequenceDecodeStagePath,
};

const NativeSequenceDecodeStageCursor = struct {
    reader: ReverseBitReader,
    ll_state: usize,
    of_state: usize,
    ml_state: usize,
    repeated_offsets: [3]usize,
    remaining: usize,
};

const NativeSequenceDecodeStageBlockResult = struct {
    literal_bytes: usize = 0,
    match_bytes: usize = 0,
    offset_sum: usize = 0,
    ordered_checksum: u64 = 0x6a09_e667_f3bc_c909,
    repeated_offsets: [3]usize,
};

fn initNativeSequenceDecodeStageCursor(
    block: *const PreparedNativeSequenceDecodeBlock,
) Error!NativeSequenceDecodeStageCursor {
    var reader = try ReverseBitReader.init(block.bitstream);
    const ll_state = try readInitialSequenceState(&reader, block.spec.ll_mode, block.spec.literal_fse.accuracy_log, 6);
    const of_state = try readInitialSequenceState(&reader, block.spec.of_mode, block.spec.offset_fse.accuracy_log, 5);
    const ml_state = try readInitialSequenceState(&reader, block.spec.ml_mode, block.spec.match_fse.accuracy_log, 6);
    return .{
        .reader = reader,
        .ll_state = ll_state,
        .of_state = of_state,
        .ml_state = ml_state,
        .repeated_offsets = block.repeated_offsets,
        .remaining = block.sequence_count,
    };
}

inline fn accumulateNativeSequenceDecodeStage(
    result: *NativeSequenceDecodeStageBlockResult,
    literal_len: usize,
    match_len: usize,
    match_offset: usize,
) void {
    result.literal_bytes +%= literal_len;
    result.match_bytes +%= match_len;
    result.offset_sum +%= match_offset;
    const fields = @as(u64, @intCast(literal_len)) *% 0x9e37_79b1_85eb_ca87 +%
        @as(u64, @intCast(match_len)) *% 0xc2b2_ae3d_27d4_eb4f +%
        @as(u64, @intCast(match_offset)) *% 0x1656_67b1_9e37_79f9;
    result.ordered_checksum = std.math.rotl(u64, result.ordered_checksum ^ fields, 17) *% 0x94d0_49bb_1331_11eb;
}

noinline fn decodePreparedNativeSequenceBlockGeneric(
    block: *const PreparedNativeSequenceDecodeBlock,
) Error!NativeSequenceDecodeStageBlockResult {
    var cursor = try initNativeSequenceDecodeStageCursor(block);
    var result: NativeSequenceDecodeStageBlockResult = .{ .repeated_offsets = undefined };
    while (cursor.remaining != 0) {
        const ll_symbol = switch (block.spec.ll_mode) {
            .predefined => try defaultLiteralLengthSymbol(cursor.ll_state),
            .rle => block.spec.literal_rle orelse return error.CorruptFrame,
            .compressed => try block.spec.literal_fse.symbol(cursor.ll_state),
            .repeat => unreachable,
        };
        const of_symbol = switch (block.spec.of_mode) {
            .predefined => try defaultOffsetSymbol(cursor.of_state),
            .rle => block.spec.offset_rle orelse return error.CorruptFrame,
            .compressed => try block.spec.offset_fse.symbol(cursor.of_state),
            .repeat => unreachable,
        };
        const ml_symbol = switch (block.spec.ml_mode) {
            .predefined => try defaultMatchLengthSymbol(cursor.ml_state),
            .rle => block.spec.match_rle orelse return error.CorruptFrame,
            .compressed => try block.spec.match_fse.symbol(cursor.ml_state),
            .repeat => unreachable,
        };
        const offset_extra = try cursor.reader.read(of_symbol.additional_bits);
        const match_len = std.math.add(usize, ml_symbol.base, try cursor.reader.read(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
        const literal_len = std.math.add(usize, ll_symbol.base, try cursor.reader.read(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
        const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &cursor.repeated_offsets);
        accumulateNativeSequenceDecodeStage(&result, literal_len, match_len, match_offset);

        cursor.remaining -= 1;
        if (cursor.remaining != 0) {
            if (block.spec.ll_mode == .predefined or block.spec.ll_mode == .compressed)
                cursor.ll_state = try nextSequenceState(&cursor.reader, ll_symbol);
            if (block.spec.ml_mode == .predefined or block.spec.ml_mode == .compressed)
                cursor.ml_state = try nextSequenceState(&cursor.reader, ml_symbol);
            if (block.spec.of_mode == .predefined or block.spec.of_mode == .compressed)
                cursor.of_state = try nextSequenceState(&cursor.reader, of_symbol);
        } else try cursor.reader.expectEnd();
    }
    result.repeated_offsets = cursor.repeated_offsets;
    return result;
}

noinline fn decodePreparedNativeSequenceBlockAllFse(
    block: *const PreparedNativeSequenceDecodeBlock,
    comptime wide: bool,
) Error!NativeSequenceDecodeStageBlockResult {
    std.debug.assert(block.spec.ll_mode == .compressed);
    std.debug.assert(block.spec.of_mode == .compressed);
    std.debug.assert(block.spec.ml_mode == .compressed);
    var cursor = try initNativeSequenceDecodeStageCursor(block);
    var result: NativeSequenceDecodeStageBlockResult = .{ .repeated_offsets = undefined };
    while (cursor.remaining != 0) {
        const ll_word = block.spec.literal_fse.symbolWordUnchecked(cursor.ll_state);
        const of_word = block.spec.offset_fse.symbolWordUnchecked(cursor.of_state);
        const ml_word = block.spec.match_fse.symbolWordUnchecked(cursor.ml_state);
        const ll_additional_bits = sequenceSymbolAdditionalBits(ll_word);
        const of_additional_bits = sequenceSymbolAdditionalBits(of_word);
        const ml_additional_bits = sequenceSymbolAdditionalBits(ml_word);
        const ll_state_bits = sequenceSymbolStateBits(ll_word);
        const of_state_bits = sequenceSymbolStateBits(of_word);
        const ml_state_bits = sequenceSymbolStateBits(ml_word);
        const transition_bits: u8 = if (cursor.remaining == 1)
            0
        else
            ll_state_bits + ml_state_bits + of_state_bits;
        const total_bits: u8 = of_additional_bits + ml_additional_bits +
            ll_additional_bits + transition_bits;
        var field_group: ?sequence_field_group.Group = if (wide) sequence_field_group.Group.init(&cursor.reader, total_bits) else null;
        const fields_are_grouped = field_group != null;
        const offset_extra = if (fields_are_grouped)
            field_group.?.read(of_additional_bits)
        else
            try cursor.reader.readSequenceField(of_additional_bits);
        const match_len = sequenceSymbolBase(ml_word) + if (fields_are_grouped)
            field_group.?.read(ml_additional_bits)
        else
            try cursor.reader.readSequenceField(ml_additional_bits);
        const literal_len = sequenceSymbolBase(ll_word) + if (fields_are_grouped)
            field_group.?.read(ll_additional_bits)
        else
            try cursor.reader.readSequenceField(ll_additional_bits);
        const match_offset = if (wide and of_additional_bits > 1) blk: {
            const offset = sequenceSymbolBase(of_word) + offset_extra;
            const previous_0 = cursor.repeated_offsets[0];
            const previous_1 = cursor.repeated_offsets[1];
            cursor.repeated_offsets = .{ offset, previous_0, previous_1 };
            break :blk offset;
        } else if (of_additional_bits == 0 and literal_len != 0)
            try large_offset.positiveLiteralRep0(&cursor.repeated_offsets)
        else
            try resolveSequenceOffset(sequenceSymbolBase(of_word), of_additional_bits, offset_extra, literal_len, &cursor.repeated_offsets);
        accumulateNativeSequenceDecodeStage(&result, literal_len, match_len, match_offset);

        cursor.remaining -= 1;
        if (cursor.remaining != 0) {
            if (fields_are_grouped) {
                cursor.ll_state = sequenceSymbolNextState(ll_word) + field_group.?.read(ll_state_bits);
                cursor.ml_state = sequenceSymbolNextState(ml_word) + field_group.?.read(ml_state_bits);
                cursor.of_state = sequenceSymbolNextState(of_word) + field_group.?.read(of_state_bits);
            } else if (wide) {
                cursor.ll_state = sequenceSymbolNextState(ll_word) + try cursor.reader.readSequenceField(ll_state_bits);
                cursor.ml_state = sequenceSymbolNextState(ml_word) + try cursor.reader.readSequenceField(ml_state_bits);
                cursor.of_state = sequenceSymbolNextState(of_word) + try cursor.reader.readSequenceField(of_state_bits);
            } else {
                cursor.ll_state = sequenceSymbolNextState(ll_word) + try cursor.reader.readSmall(@intCast(ll_state_bits));
                cursor.ml_state = sequenceSymbolNextState(ml_word) + try cursor.reader.readSmall(@intCast(ml_state_bits));
                cursor.of_state = sequenceSymbolNextState(of_word) + try cursor.reader.readSmall(@intCast(of_state_bits));
            }
        } else try cursor.reader.expectEnd();
    }
    result.repeated_offsets = cursor.repeated_offsets;
    return result;
}

fn decodePreparedNativeSequenceBlock(
    block: *const PreparedNativeSequenceDecodeBlock,
) Error!NativeSequenceDecodeStageBlockResult {
    return switch (block.path) {
        .generic => decodePreparedNativeSequenceBlockGeneric(block),
        .bounded_all_fse => decodePreparedNativeSequenceBlockAllFse(block, false),
        .wide_all_fse => decodePreparedNativeSequenceBlockAllFse(block, true),
    };
}

noinline fn decodePreparedNativeSequenceBlocks(
    blocks: []const PreparedNativeSequenceDecodeBlock,
) Error!NativeSequenceDecodeStageResult {
    var sequence_count: usize = 0;
    var checksum: u64 = 0;
    for (blocks) |*block| {
        const decoded = try decodePreparedNativeSequenceBlock(block);
        sequence_count +%= block.sequence_count;
        checksum +%= @as(u64, @intCast(decoded.literal_bytes)) *% 0x9e37_79b1_85eb_ca87;
        checksum +%= @as(u64, @intCast(decoded.match_bytes)) *% 0xc2b2_ae3d_27d4_eb4f;
        checksum +%= @as(u64, @intCast(decoded.offset_sum)) *% 0x1656_67b1_9e37_79f9;
        checksum +%= @as(u64, @intCast(decoded.repeated_offsets[0])) *% 0x85eb_ca77_c2b2_ae63;
        checksum = std.math.rotl(u64, checksum ^ decoded.ordered_checksum, 23);
    }
    return .{ .sequence_count = sequence_count, .checksum = checksum };
}

fn nextSequenceState(reader: *ReverseBitReader, symbol: SequenceSymbol) Error!usize {
    return std.math.add(usize, symbol.next_state, try reader.readSmall(@intCast(symbol.state_bits))) catch return error.IntegerOverflow;
}

inline fn nextSequenceStateWide(reader: *ReverseBitReader, symbol: SequenceSymbol) Error!usize {
    return std.math.add(usize, symbol.next_state, try reader.readSequenceField(symbol.state_bits)) catch return error.IntegerOverflow;
}

inline fn nextSequenceStateProvenWide(reader: *ReverseBitReader, symbol: SequenceSymbol) usize {
    return @as(usize, symbol.next_state) + reader.readSequenceFieldWide(symbol.state_bits);
}

test "wide sequence transition matches bounded reader" {
    var bytes: [24]u8 = undefined;
    for (&bytes, 0..) |*byte, index| byte.* = @truncate(index * 73 + 19);
    bytes[bytes.len - 1] |= 0x80;
    for (0..96) |consumed| {
        var positioned = try ReverseBitReader.init(&bytes);
        if (consumed != 0) try positioned.skip(@intCast(consumed));
        const max_width = @min(@as(usize, 9), positioned.available());
        for (0..max_width + 1) |width| {
            var bounded = positioned;
            var wide = positioned;
            const symbol: SequenceSymbol = .{
                .base = 0,
                .additional_bits = 0,
                .next_state = 511,
                .state_bits = @intCast(width),
            };
            try std.testing.expectEqual(
                try nextSequenceState(&bounded, symbol),
                try nextSequenceStateWide(&wide, symbol),
            );
            try std.testing.expectEqual(bounded.available(), wide.available());
        }
    }
}

/// Resolve repeat/direct offsets inside the per-sequence decode loop. This is
/// deliberately forced inline: all arguments are already live at the caller,
/// and profiling showed the tiny helper's call/return boundary consuming a
/// measurable share of FSE-heavy blocks. The resolver's focused selector tests
/// below remain the behavior oracle for the expanded hot path.
inline fn resolveSequenceOffset(
    offset_base: usize,
    offset_bits: u8,
    offset_extra: usize,
    literal_len: usize,
    repeated_offsets: *[3]usize,
) Error!usize {
    if (offset_bits > 1) {
        const offset = std.math.add(usize, offset_base, offset_extra) catch return error.IntegerOverflow;
        updateRepeatedOffsets(repeated_offsets, offset);
        return offset;
    }

    const literal_len_is_zero = literal_len == 0;
    if (offset_bits == 0) {
        return try useRepeatedOffset(repeated_offsets, if (literal_len_is_zero) 1 else 0);
    }

    const raw_base = std.math.add(usize, offset_base, if (literal_len_is_zero) 1 else 0) catch return error.IntegerOverflow;
    const raw_offset = std.math.add(
        usize,
        raw_base,
        offset_extra,
    ) catch return error.IntegerOverflow;
    if (raw_offset == 3) {
        if (repeated_offsets[0] == 0) return error.InvalidMatch;
        const offset = repeated_offsets[0] - 1;
        if (offset == 0) return error.InvalidMatch;
        updateRepeatedOffsets(repeated_offsets, offset);
        return offset;
    }
    if (raw_offset >= repeated_offsets.len) return error.CorruptFrame;
    return try useRepeatedOffset(repeated_offsets, raw_offset);
}

fn updateRepeatedOffsets(repeated_offsets: *[3]usize, offset: usize) void {
    const previous_0 = repeated_offsets[0];
    const previous_1 = repeated_offsets[1];
    repeated_offsets.* = .{ offset, previous_0, previous_1 };
}

inline fn useRepeatedOffset(repeated_offsets: *[3]usize, index: usize) Error!usize {
    switch (index) {
        0 => {},
        1 => std.mem.swap(usize, &repeated_offsets[0], &repeated_offsets[1]),
        2 => {
            std.mem.swap(usize, &repeated_offsets[0], &repeated_offsets[2]);
            std.mem.swap(usize, &repeated_offsets[1], &repeated_offsets[2]);
        },
        else => return error.CorruptFrame,
    }
    if (repeated_offsets[0] == 0) return error.InvalidMatch;
    return repeated_offsets[0];
}

test "zstd native default sequence tables reject invalid states as corrupt" {
    try std.testing.expectError(error.CorruptFrame, defaultLiteralLengthSymbol(sequence_predefined.literal_symbols.len));
    try std.testing.expectError(error.CorruptFrame, defaultOffsetSymbol(sequence_predefined.offset_symbols.len));
    try std.testing.expectError(error.CorruptFrame, defaultMatchLengthSymbol(sequence_predefined.match_symbols.len));
}

test "zstd compressed sequence tables preserve checked state bounds" {
    const expected: SequenceSymbol = .{
        .base = 17,
        .additional_bits = 3,
        .next_state = 5,
        .state_bits = 2,
    };
    var table: SequenceFseTable = .{ .len = 1, .accuracy_log = 1 };
    table.entries[0] = expected;
    try std.testing.expectEqual(expected, try table.symbol(0));
    try std.testing.expectError(error.CorruptFrame, table.symbol(1));
}

test "zstd native repeat-offset resolver follows selector updates" {
    var offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 1), try resolveSequenceOffset(0, 0, 0, 1, &offsets));
    try std.testing.expectEqual([3]usize{ 1, 4, 8 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 4), try resolveSequenceOffset(0, 0, 0, 0, &offsets));
    try std.testing.expectEqual([3]usize{ 4, 1, 8 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 4), try resolveSequenceOffset(1, 1, 0, 1, &offsets));
    try std.testing.expectEqual([3]usize{ 4, 1, 8 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 8), try resolveSequenceOffset(1, 1, 1, 1, &offsets));
    try std.testing.expectEqual([3]usize{ 8, 1, 4 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 8), try resolveSequenceOffset(1, 1, 0, 0, &offsets));
    try std.testing.expectEqual([3]usize{ 8, 1, 4 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectError(error.InvalidMatch, resolveSequenceOffset(1, 1, 1, 0, &offsets));
    try std.testing.expectEqual(initial_repeated_offsets, offsets);

    offsets = .{ 2, 4, 8 };
    try std.testing.expectEqual(@as(usize, 1), try resolveSequenceOffset(1, 1, 1, 0, &offsets));
    try std.testing.expectEqual([3]usize{ 1, 2, 4 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectError(error.CorruptFrame, resolveSequenceOffset(2, 1, 1, 0, &offsets));
    try std.testing.expectEqual(initial_repeated_offsets, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectError(error.CorruptFrame, useRepeatedOffset(&offsets, 3));
    try std.testing.expectEqual(initial_repeated_offsets, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 5), try resolveSequenceOffset(5, 2, 0, 0, &offsets));
    try std.testing.expectEqual([3]usize{ 5, 1, 4 }, offsets);

    offsets = initial_repeated_offsets;
    try std.testing.expectEqual(@as(usize, 1), try resolveSequenceOffset(0, 0, 0, 1, &offsets)); // positive-literal rep0.
    try std.testing.expectEqual([3]usize{ 1, 4, 8 }, offsets);
    try std.testing.expectEqual(@as(usize, 4), try resolveSequenceOffset(1, 1, 0, 1, &offsets)); // positive-literal rep1.
    try std.testing.expectEqual([3]usize{ 4, 1, 8 }, offsets);
    try std.testing.expectEqual(@as(usize, 8), try resolveSequenceOffset(1, 1, 1, 1, &offsets)); // positive-literal rep2.
    try std.testing.expectEqual([3]usize{ 8, 4, 1 }, offsets);
}

fn copyMatchFromOutputBuffer(
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    match_offset: usize,
    match_len: usize,
) Error!void {
    return try copyMatchFromHistory(output, written, frame_output_start, &.{}, match_offset, match_len);
}

fn copyMatchFromHistory(
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    dictionary_history: []const u8,
    match_offset: usize,
    match_len: usize,
) Error!void {
    if (frame_output_start > written.*) return error.CorruptFrame;
    const available_in_frame = written.* - frame_output_start;
    const available = std.math.add(usize, dictionary_history.len, available_in_frame) catch return error.IntegerOverflow;
    if (match_offset == 0 or match_offset > available) return error.InvalidMatch;
    if (output.len - written.* < match_len) return error.OutputTooSmall;
    if (match_offset <= available_in_frame) {
        const repeat_start = written.* - match_offset;
        appendRepeatedMatch(output, written, repeat_start, match_len);
        return;
    }

    const destination_start = written.*;
    for (0..match_len) |i| {
        const logical_source = available + i - match_offset;
        output[destination_start + i] = if (logical_source < dictionary_history.len)
            dictionary_history[logical_source]
        else
            output[frame_output_start + logical_source - dictionary_history.len];
    }
    written.* += match_len;
}

fn appendRepeatedMatch(output: []u8, written: *usize, repeat_start: usize, match_len: usize) void {
    sequence_match_copy.append(output, written, repeat_start, match_len);
}

fn rawOrRleDecodedSizeLimited(frame: []const u8, max_output_len: usize) Error!usize {
    return try rawOrRleDecodedSizeLimitedWithDictionary(frame, max_output_len, null);
}

fn rawOrRleDecodedSizeLimitedWithDictionary(
    frame: []const u8,
    max_output_len: usize,
    dictionary: ?NativeDictionary,
) Error!usize {
    var offset: usize = 0;
    var total: usize = 0;
    while (offset < frame.len) {
        if (frame.len - offset < 4) return error.TruncatedFrame;
        const magic = std.mem.readInt(u32, frame[offset..][0..4], .little);
        offset += 4;
        if (magic == frame_magic_u32) {
            const header = try parseRawOrRleFrameHeaderWithOptions(frame, &offset, true);
            const dictionary_history = try validateNativeDictionary(header, dictionary);
            const frame_start = total;
            var frame_state = try initialSequenceFrameState(dictionary);
            while (true) {
                if (frame.len - offset < 3) return error.TruncatedFrame;
                const block_header = std.mem.readInt(u24, frame[offset..][0..3], .little);
                offset += 3;
                const last = (block_header & 0x1) != 0;
                const block_type = (block_header >> 1) & 0x3;
                const block_len: usize = @intCast(block_header >> 3);
                try validateBlockSize(header, block_type, block_len);

                switch (block_type) {
                    0 => {
                        if (frame.len - offset < block_len) return error.TruncatedFrame;
                        offset += block_len;
                        total = try checkedAddWithinLimit(total, block_len, max_output_len);
                    },
                    1 => {
                        if (frame.len - offset < 1) return error.TruncatedFrame;
                        offset += 1;
                        total = try checkedAddWithinLimit(total, block_len, max_output_len);
                    },
                    2 => {
                        if (frame.len - offset < block_len) return error.TruncatedFrame;
                        const produced_in_frame = total - frame_start;
                        const initial_history_len = std.math.add(usize, dictionary_history.len, produced_in_frame) catch return error.IntegerOverflow;
                        const decoded_len = try compressedLiteralOnlyBlockDecodedSize(frame[offset..][0..block_len], header.block_size_max, initial_history_len, &frame_state);
                        total = try checkedAddWithinLimit(total, decoded_len, max_output_len);
                        offset += block_len;
                    },
                    else => return error.CorruptFrame,
                }
                if (last) break;
            }

            const frame_decoded_len = total - frame_start;
            if (header.content_size) |size| {
                if (try checkedUsizeToU64(frame_decoded_len) != size) return error.SizeMismatch;
            }
            if (header.has_checksum) {
                if (frame.len - offset < 4) return error.TruncatedFrame;
                offset += 4;
            }
        } else if (magic >= skippable_magic_min and magic <= skippable_magic_max) {
            if (frame.len - offset < 4) return error.TruncatedFrame;
            const skip_len: usize = @intCast(std.mem.readInt(u32, frame[offset..][0..4], .little));
            offset += 4;
            if (frame.len - offset < skip_len) return error.TruncatedFrame;
            offset += skip_len;
        } else {
            return error.InvalidMagic;
        }
    }
    return total;
}

fn checkedAddWithinLimit(current: usize, additional: usize, max: usize) Error!usize {
    const next = std.math.add(usize, current, additional) catch return error.IntegerOverflow;
    if (next > max) return error.OutputLimitExceeded;
    return next;
}

fn expectConsumedBlock(offset: usize, block_len: usize) Error!void {
    if (offset != block_len) return error.CorruptFrame;
}

fn checkedAdd(a: usize, b: usize) Error!usize {
    return std.math.add(usize, a, b) catch return error.IntegerOverflow;
}

fn parseRawOrRleFrameHeaderWithOptions(frame: []const u8, offset: *usize, allow_nonzero_dictionary_id: bool) Error!RawOrRleFrameHeader {
    if (frame.len - offset.* < 1) return error.TruncatedFrame;
    const descriptor = frame[offset.*];
    offset.* += 1;

    if ((descriptor & 0x08) != 0) return error.CorruptFrame;
    // Bit 4 is unused by the Zstandard frame descriptor. Reference decoders
    // accept it as a don't-care bit, so native parsing must not reject otherwise
    // valid frames that set it.

    const dictionary_id_flag = descriptor & 0x03;
    const has_checksum = (descriptor & 0x04) != 0;
    const single_segment = (descriptor & 0x20) != 0;
    const content_size_flag = descriptor >> 6;

    const window_size = if (single_segment) null else blk: {
        if (frame.len - offset.* < 1) return error.TruncatedFrame;
        const window_descriptor = frame[offset.*];
        offset.* += 1;
        break :blk decodeWindowSize(window_descriptor);
    };

    const dictionary_id_len: usize = switch (dictionary_id_flag) {
        0 => 0,
        1 => 1,
        2 => 2,
        else => 4,
    };
    if (frame.len - offset.* < dictionary_id_len) return error.TruncatedFrame;
    const dictionary_id_u64 = try readU64Field(frame, offset, dictionary_id_len);
    const dictionary_id = try checkedU64ToU32(dictionary_id_u64);
    if (dictionary_id != 0 and !allow_nonzero_dictionary_id) return error.NeedDictionary;

    const content_size: ?u64 = if (single_segment or content_size_flag != 0) blk: {
        const field_size: usize = @as(usize, 1) << @intCast(content_size_flag);
        const encoded_size = try readU64Field(frame, offset, field_size);
        break :blk if (field_size == 2) encoded_size + 256 else encoded_size;
    } else null;

    const effective_window = if (single_segment) content_size.? else window_size.?;
    const block_size_max = @min(
        std.compress.zstd.block_size_max,
        try checkedU64ToUsize(effective_window),
    );

    return .{
        .content_size = content_size,
        .has_checksum = has_checksum,
        .window_size = effective_window,
        .block_size_max = block_size_max,
        .dictionary_id = dictionary_id,
        .payload_offset = offset.*,
    };
}

fn parseRawOrRleFrameHeader(frame: []const u8, offset: *usize) Error!RawOrRleFrameHeader {
    return try parseRawOrRleFrameHeaderWithOptions(frame, offset, false);
}

pub fn inspectNativeFrameHeader(frame: []const u8) Error!NativeFrameHeader {
    if (frame.len < 4) return error.TruncatedFrame;
    const magic = std.mem.readInt(u32, frame[0..4], .little);
    if (magic != frame_magic_u32) return error.InvalidMagic;
    var offset: usize = 4;
    return try parseRawOrRleFrameHeaderWithOptions(frame, &offset, true);
}

pub fn inspectNativeFrameBlockAt(frame: []const u8, header_offset: usize) Error!NativeFrameBlockHeader {
    const header = try inspectNativeFrameHeader(frame);
    if (header_offset < header.payload_offset) return error.CorruptFrame;
    if (frame.len - header_offset < 3) return error.TruncatedFrame;
    const block_header = std.mem.readInt(u24, frame[header_offset..][0..3], .little);
    const block_type_raw = (block_header >> 1) & 0x03;
    const payload_len: usize = @intCast(block_header >> 3);
    const block_type: NativeBlockType = switch (block_type_raw) {
        0 => .raw,
        1 => .rle,
        2 => .compressed,
        else => return error.CorruptFrame,
    };
    try validateBlockSize(header, block_type_raw, payload_len);
    const payload_offset = header_offset + 3;
    const required_payload_len: usize = if (block_type == .rle) 1 else payload_len;
    if (frame.len - payload_offset < required_payload_len) return error.TruncatedFrame;
    return .{
        .header_offset = header_offset,
        .payload_offset = payload_offset,
        .payload_len = payload_len,
        .block_type = block_type,
        .last = (block_header & 1) != 0,
        .next_header_offset = payload_offset + required_payload_len,
    };
}

pub fn inspectNativeFrameFirstBlock(frame: []const u8) Error!NativeFrameBlockHeader {
    const header = try inspectNativeFrameHeader(frame);
    return try inspectNativeFrameBlockAt(frame, header.payload_offset);
}

pub fn inspectNativeFrameBlockSequenceModes(frame: []const u8, block: NativeFrameBlockHeader) Error!NativeSequenceModeSummary {
    try validateNativeFrameBlockPayloadAvailable(frame, block);
    if (block.block_type != .compressed) return nativeSequenceModeSummaryForLiteralBlock(block);
    var frame_state = try replayNativeFrameBlockInspectState(frame, block.header_offset, .{});
    return try inspectNativeFrameBlockSequenceModesWithState(frame, block, &frame_state);
}

fn profileNativeSequenceTableMode(
    profile: *NativeSequenceCopyProfile,
    mode: SymbolMode,
    block: []const u8,
    offset: *usize,
    expected_symbol_count: usize,
    max_accuracy_log: u4,
) Error!void {
    switch (mode) {
        .compressed => {
            if (offset.* >= block.len) return error.TruncatedFrame;
            var reader: ForwardBitReader = .{ .bytes = block[offset.*..] };
            var values: [256]u16 = undefined;
            const decoded = try decodeFseNormalizedCounts(&reader, expected_symbol_count, max_accuracy_log, &values);
            offset.* = std.math.add(usize, offset.*, reader.byteIndex()) catch return error.IntegerOverflow;
            if (offset.* > block.len) return error.TruncatedFrame;

            profile.compressed_table_modes += 1;
            const accuracy_log = std.math.log2_int(usize, decoded.table_len);
            if (accuracy_log >= profile.fse_accuracy_log_histogram.len) return error.CorruptFrame;
            profile.fse_accuracy_log_histogram[accuracy_log] += 1;
            var no_low_probability = true;
            for (values[0..decoded.value_count]) |value| no_low_probability = no_low_probability and value != 0;
            if (no_low_probability) {
                profile.no_low_probability_tables += 1;
                profile.no_low_fse_accuracy_log_histogram[accuracy_log] += 1;
            } else {
                profile.low_probability_tables += 1;
            }
        },
        .repeat => profile.repeat_table_modes += 1,
        .rle => {
            if (offset.* >= block.len) return error.TruncatedFrame;
            offset.* += 1;
            profile.rle_table_modes += 1;
        },
        .predefined => profile.predefined_table_modes += 1,
    }
}

/// Profile serialized sequence-table descriptions separately from production
/// parsing so the diagnostic does not add bookkeeping to decoder hot paths.
fn profileNativeSequenceTables(
    profile: *NativeSequenceCopyProfile,
    block: []const u8,
    offset: *usize,
) Error!void {
    if (offset.* >= block.len) return error.TruncatedFrame;
    const mode_byte = block[offset.*];
    offset.* += 1;
    if ((mode_byte & 0x03) != 0) return error.CorruptFrame;
    const ll_mode: SymbolMode = @enumFromInt(mode_byte >> 6);
    const of_mode: SymbolMode = @enumFromInt((mode_byte >> 4) & 0x03);
    const ml_mode: SymbolMode = @enumFromInt((mode_byte >> 2) & 0x03);

    profile.sequence_block_count += 1;
    try profileNativeSequenceTableMode(profile, ll_mode, block, offset, sequence_table_symbol_count_max.literal, sequence_table_accuracy_log_max.literal);
    try profileNativeSequenceTableMode(profile, of_mode, block, offset, sequence_table_symbol_count_max.offset, sequence_table_accuracy_log_max.offset);
    try profileNativeSequenceTableMode(profile, ml_mode, block, offset, sequence_table_symbol_count_max.match, sequence_table_accuracy_log_max.match);
}

/// Inspect decoded sequence-copy shapes without executing output writes. This
/// diagnostic is intentionally kept out of the production decode loop.
pub fn benchmarkNativeSequenceCopyProfile(frame: []const u8) Error!NativeSequenceCopyProfile {
    if (frame.len < 4 or std.mem.readInt(u32, frame[0..4], .little) != frame_magic_u32) return error.InvalidMagic;
    var offset: usize = 4;
    const header = try parseRawOrRleFrameHeader(frame, &offset);
    var frame_state: SequenceFrameState = .{};
    var profile: NativeSequenceCopyProfile = .{};
    var produced: usize = 0;

    while (true) {
        if (frame.len - offset < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset..][0..3], .little);
        offset += 3;
        const last = block_header & 1 != 0;
        const block_type = (block_header >> 1) & 3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);
        switch (block_type) {
            0 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                offset += block_len;
                produced = try checkedAdd(produced, block_len);
            },
            1 => {
                if (frame.len - offset < 1) return error.TruncatedFrame;
                offset += 1;
                produced = try checkedAdd(produced, block_len);
            },
            2 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                const block = frame[offset..][0..block_len];
                const section = try parseLiteralsSection(block, &frame_state);
                if (section.regenerated_size > header.block_size_max) return error.CorruptFrame;
                try validateSupportedLiteralSection(section);
                switch (section.kind) {
                    .raw => profile.raw_literal_blocks += 1,
                    .rle => profile.rle_literal_blocks += 1,
                    .compressed => profile.compressed_literal_blocks += 1,
                    .treeless => profile.treeless_literal_blocks += 1,
                }
                profile.literal_bytes = try checkedAdd(profile.literal_bytes, section.regenerated_size);
                if (section.sequence_count == 0) {
                    try expectConsumedBlock(section.sequence_payload_offset, block.len);
                    try validateHuffmanLiteralsConsumed(block, section);
                    produced = try checkedAdd(produced, section.regenerated_size);
                } else {
                    var sequence_offset = section.sequence_payload_offset;
                    var table_profile_offset = sequence_offset;
                    try profileNativeSequenceTables(&profile, block, &table_profile_offset);
                    const parsed_spec = try parseSequenceModeSpec(block, &sequence_offset, section.sequence_count);
                    const spec = try resolveSequenceModeSpec(parsed_spec, frame_state.previous_tables);
                    try expectConsumedBlock(sequence_offset, block.len);
                    if (table_profile_offset != parsed_spec.bitstream_offset) return error.CorruptFrame;
                    const huffman_literals = section.kind == .compressed or section.kind == .treeless;
                    const prefer_generic_split = sequence_decode_policy.preferGenericSplit(section.regenerated_size, section.sequence_count);
                    const four_huffman_streams = section.huffman_streams == .four;
                    var complete_huffman_lookup = false;
                    if (huffman_literals and prefer_generic_split and four_huffman_streams) {
                        const tree = section.huffman_tree orelse return error.CorruptFrame;
                        var lookup: CompleteHuffmanLiteralLookup = undefined;
                        complete_huffman_lookup = lookup.buildComplete(&tree);
                    }
                    const split_path = sequence_split_profile.classify(.{
                        .huffman_literals = huffman_literals,
                        .prefer_generic = prefer_generic_split,
                        .four_streams = four_huffman_streams,
                        .complete_lookup = complete_huffman_lookup,
                        .all_fse = spec.ll_mode == .compressed and spec.of_mode == .compressed and spec.ml_mode == .compressed,
                        .prefer_all_fse = sequence_decode_policy.preferSplit(section.regenerated_size, section.sequence_count),
                    });
                    profile.split_paths.recordBlock(split_path, section.regenerated_size);
                    var state = try initSequenceDecodeState(
                        &spec,
                        section.sequence_count,
                        try ReverseBitReader.init(block[spec.bitstream_offset..]),
                        frame_state.repeated_offsets,
                    );
                    var literal_offset: usize = 0;
                    while (state.remaining != 0) {
                        const sequence = try readModeSequence(&state);
                        if (literal_offset > section.regenerated_size or section.regenerated_size - literal_offset < sequence.literal_len) return error.CorruptFrame;
                        literal_offset = try checkedAdd(literal_offset, sequence.literal_len);
                        produced = try checkedAdd(produced, sequence.literal_len);
                        if (sequence.match_offset == 0 or sequence.match_offset > produced) return error.InvalidMatch;
                        profile.sequence_count += 1;
                        profile.split_paths.recordSequence(split_path, sequence.match_len);
                        profile.zero_literal_sequences += @intFromBool(sequence.literal_len == 0);
                        profile.match_bytes = try checkedAdd(profile.match_bytes, sequence.match_len);
                        profile.match_length_histogram[sequenceCopyLengthBucket(sequence.match_len)] += 1;
                        profile.offset_histogram[sequenceCopyOffsetBucket(sequence.match_offset)] += 1;
                        if (sequence.match_len >= NativeSequenceCopyProfile.medium_length_min and
                            sequence.match_len <= NativeSequenceCopyProfile.medium_length_max)
                        {
                            profile.medium_length_histogram[sequence.match_len - NativeSequenceCopyProfile.medium_length_min] += 1;
                        }
                        if (sequence.match_len > sequence.match_offset) {
                            profile.overlapping_matches += 1;
                            profile.overlapping_match_bytes = try checkedAdd(profile.overlapping_match_bytes, sequence.match_len);
                        } else {
                            profile.non_overlapping_matches += 1;
                            profile.non_overlapping_match_bytes = try checkedAdd(profile.non_overlapping_match_bytes, sequence.match_len);
                            if (sequence.match_offset >= 32 and sequence.match_len >= 32) {
                                profile.vector32_eligible_matches += 1;
                                profile.vector32_eligible_bytes = try checkedAdd(profile.vector32_eligible_bytes, sequence.match_len);
                            }
                        }
                        produced = try checkedAdd(produced, sequence.match_len);
                    }
                    if (section.regenerated_size < literal_offset) return error.CorruptFrame;
                    produced = try checkedAdd(produced, section.regenerated_size - literal_offset);
                    try validateHuffmanLiteralsConsumed(block, section);
                    frame_state.previous_tables = spec.tables();
                    frame_state.repeated_offsets = state.repeated_offsets;
                }
                offset += block_len;
            },
            else => return error.CorruptFrame,
        }
        if (last) break;
    }
    if (header.content_size) |expected| if (try checkedUsizeToU64(produced) != expected) return error.SizeMismatch;
    if (header.has_checksum) {
        if (frame.len - offset < 4) return error.TruncatedFrame;
        offset += 4;
    }
    if (offset != frame.len) return error.TrailingData;
    return profile;
}

fn decodePreparedNativeInterleavedBlock(
    prepared: *const PreparedNativeInterleavedBlock,
    output: []u8,
    expected_output: []const u8,
) Error!u64 {
    var state = try initSequenceDecodeState(
        &prepared.spec,
        prepared.section.sequence_count,
        try ReverseBitReader.init(prepared.block[prepared.spec.bitstream_offset..]),
        prepared.repeated_offsets,
    );
    var frame_state: SequenceFrameState = .{
        .repeated_offsets = prepared.repeated_offsets,
        .retain_sequence_tables = false,
    };
    var written = prepared.output_offset;
    const used_medium_split = prepared.use_match_wildcopy and
        prepared.section.regenerated_size <= sequence_decode_policy.medium_split_literal_max and
        try tryDecodeMediumSplitHuffmanSequences(
            prepared.section,
            output,
            &written,
            0,
            &frame_state,
            .terminal,
            &state,
        );
    if (!used_medium_split) {
        const huffman_state = (try initHuffmanLiteralDecodeState(prepared.block, prepared.section)) orelse
            return error.CorruptFrame;
        if (prepared.use_match_wildcopy)
            try decodeAllFseHuffmanSequences(
                prepared.section,
                &prepared.spec,
                output,
                &written,
                0,
                &frame_state,
                .terminal,
                &state,
                true,
                true,
                huffman_state,
            )
        else
            try decodeAllFseHuffmanSequences(
                prepared.section,
                &prepared.spec,
                output,
                &written,
                0,
                &frame_state,
                .terminal,
                &state,
                true,
                false,
                huffman_state,
            );
    }
    if (written != prepared.output_offset + prepared.decoded_bytes) return error.SizeMismatch;
    const decoded = output[prepared.output_offset..written];
    const checksum = @as(u64, decoded[0]) |
        (@as(u64, decoded[decoded.len / 2]) << 8) |
        (@as(u64, decoded[decoded.len - 1]) << 16) |
        (@as(u64, @intCast(decoded.len)) << 24);
    const restore_end = @min(written + 64, expected_output.len);
    @memcpy(output[written..restore_end], expected_output[written..restore_end]);
    if (restore_end - written < 64)
        @memset(output[restore_end .. written + 64], 0xa5);
    return checksum;
}

/// Prepare every medium all-FSE/four-stream-Huffman block selected by the
/// production medium-decoder policy. The expected output seeds immutable frame
/// history once; timed decodes overwrite only the selected block ranges.
pub fn prepareNativeInterleavedDecodeStage(
    allocator: std.mem.Allocator,
    frame: []const u8,
    expected_output: []const u8,
    options: NativeInterleavedDecodeStageOptions,
) Error!NativeInterleavedDecodeStage {
    if (options.min_sequence_count == 0 or options.max_sequence_count < options.min_sequence_count)
        return error.InvalidBlockPlan;
    if (frame.len < 4 or std.mem.readInt(u32, frame[0..4], .little) != frame_magic_u32) return error.InvalidMagic;
    var offset: usize = 4;
    const header = try parseRawOrRleFrameHeader(frame, &offset);
    if (header.content_size) |size| if (try checkedU64ToUsize(size) != expected_output.len)
        return error.SizeMismatch;
    const output_len = std.math.add(usize, expected_output.len, 64) catch return error.IntegerOverflow;
    const output = try allocator.alloc(u8, output_len);
    errdefer allocator.free(output);
    @memcpy(output[0..expected_output.len], expected_output);
    @memset(output[expected_output.len..], 0xa5);

    var prepared_blocks: std.ArrayList(PreparedNativeInterleavedBlock) = .empty;
    defer prepared_blocks.deinit(allocator);
    var shape: NativeInterleavedDecodeStageShape = .{
        .block_count = 0,
        .match_wildcopy_block_count = 0,
        .compressed_bytes = 0,
        .decoded_bytes = 0,
        .literal_bytes = 0,
        .sequence_count = 0,
    };
    var frame_state: SequenceFrameState = .{};
    var produced: usize = 0;
    while (true) {
        if (frame.len - offset < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset..][0..3], .little);
        offset += 3;
        const last = block_header & 1 != 0;
        const block_type = (block_header >> 1) & 3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);
        switch (block_type) {
            0 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                produced = try checkedAdd(produced, block_len);
                offset += block_len;
            },
            1 => {
                if (frame.len - offset < 1) return error.TruncatedFrame;
                produced = try checkedAdd(produced, block_len);
                offset += 1;
            },
            2 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                const block = frame[offset..][0..block_len];
                const section = try parseLiteralsSection(block, &frame_state);
                if (section.regenerated_size > header.block_size_max) return error.CorruptFrame;
                try validateSupportedLiteralSection(section);
                if (section.sequence_count == 0) {
                    try expectConsumedBlock(section.sequence_payload_offset, block.len);
                    try validateHuffmanLiteralsConsumed(block, section);
                    produced = try checkedAdd(produced, section.regenerated_size);
                } else {
                    const block_output_start = produced;
                    var sequence_offset = section.sequence_payload_offset;
                    const parsed_spec = try parseSequenceModeSpec(block, &sequence_offset, section.sequence_count);
                    const spec = try resolveSequenceModeSpec(parsed_spec, frame_state.previous_tables);
                    try expectConsumedBlock(sequence_offset, block.len);
                    const sequence_block: PreparedNativeSequenceDecodeBlock = .{
                        .spec = spec,
                        .bitstream = block[spec.bitstream_offset..],
                        .sequence_count = section.sequence_count,
                        .repeated_offsets = frame_state.repeated_offsets,
                        .path = .generic,
                    };
                    const decoded = try decodePreparedNativeSequenceBlockGeneric(&sequence_block);
                    if (decoded.literal_bytes > section.regenerated_size) return error.CorruptFrame;
                    const block_decoded_bytes = try checkedAdd(section.regenerated_size, decoded.match_bytes);
                    produced = try checkedAdd(produced, block_decoded_bytes);
                    try validateHuffmanLiteralsConsumed(block, section);

                    const use_match_wildcopy = sequence_decode_policy.preferHuffmanMatchWildcopy(block.len, section.sequence_count);
                    const selected_interleaved = spec.ll_mode == .compressed and
                        spec.of_mode == .compressed and
                        spec.ml_mode == .compressed and
                        (section.kind == .compressed or section.kind == .treeless) and
                        section.huffman_streams == .four and
                        section.sequence_count >= options.min_sequence_count and
                        section.sequence_count <= options.max_sequence_count and
                        (!options.require_match_wildcopy or use_match_wildcopy);
                    if (selected_interleaved) {
                        try prepared_blocks.append(allocator, .{
                            .block = block,
                            .section = section,
                            .spec = spec,
                            .repeated_offsets = frame_state.repeated_offsets,
                            .output_offset = block_output_start,
                            .decoded_bytes = block_decoded_bytes,
                            .use_match_wildcopy = use_match_wildcopy,
                        });
                        shape.block_count += 1;
                        shape.match_wildcopy_block_count += @intFromBool(use_match_wildcopy);
                        shape.compressed_bytes = try checkedAdd(shape.compressed_bytes, block.len);
                        shape.decoded_bytes = try checkedAdd(shape.decoded_bytes, block_decoded_bytes);
                        shape.literal_bytes = try checkedAdd(shape.literal_bytes, section.regenerated_size);
                        shape.sequence_count = try checkedAdd(shape.sequence_count, section.sequence_count);
                    }
                    frame_state.previous_tables = spec.tables();
                    frame_state.repeated_offsets = decoded.repeated_offsets;
                }
                offset += block_len;
            },
            else => return error.CorruptFrame,
        }
        if (last) break;
    }
    if (header.content_size) |size| if (try checkedUsizeToU64(produced) != size) return error.SizeMismatch;
    if (produced != expected_output.len) return error.SizeMismatch;
    if (header.has_checksum) {
        if (frame.len - offset < 4) return error.TruncatedFrame;
        offset += 4;
    }
    if (offset != frame.len) return error.TrailingData;
    if (prepared_blocks.items.len == 0) return error.InvalidBlockPlan;

    const prepared = try prepared_blocks.toOwnedSlice(allocator);
    errdefer allocator.free(prepared);
    var stage: NativeInterleavedDecodeStage = .{
        .allocator = allocator,
        .prepared = prepared,
        .output = output,
        .expected_output = expected_output,
        .prepared_shape = shape,
    };
    const result = try stage.decode();
    if (result.block_count != shape.block_count or
        result.decoded_bytes != shape.decoded_bytes or
        !std.mem.eql(u8, expected_output, stage.decoded())) return error.SizeMismatch;
    return stage;
}

/// Parse a complete dictionary-free Zstandard frame into a caller-owned list
/// of prepared sequence blocks. This deliberately validates every sequence
/// once before returning so benchmark timings cannot turn malformed data into
/// unchecked FSE table access.
pub fn prepareNativeSequenceDecodeStage(
    allocator: std.mem.Allocator,
    frame: []const u8,
) Error!NativeSequenceDecodeStage {
    // Establish a checked decode oracle before the timed stage is allowed to
    // use the same unchecked table lookups as the production all-FSE loops.
    const validated_profile = try benchmarkNativeSequenceCopyProfile(frame);
    if (frame.len < 4 or std.mem.readInt(u32, frame[0..4], .little) != frame_magic_u32) return error.InvalidMagic;
    var offset: usize = 4;
    const header = try parseRawOrRleFrameHeader(frame, &offset);
    var frame_state: SequenceFrameState = .{};
    var blocks: std.ArrayList(PreparedNativeSequenceDecodeBlock) = .empty;
    defer blocks.deinit(allocator);
    var shape: NativeSequenceDecodeStageShape = .{};
    var produced: usize = 0;

    while (true) {
        if (frame.len - offset < 3) return error.TruncatedFrame;
        const block_header = std.mem.readInt(u24, frame[offset..][0..3], .little);
        offset += 3;
        const last = block_header & 1 != 0;
        const block_type = (block_header >> 1) & 3;
        const block_len: usize = @intCast(block_header >> 3);
        try validateBlockSize(header, block_type, block_len);
        switch (block_type) {
            0 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                offset += block_len;
                produced = try checkedAdd(produced, block_len);
            },
            1 => {
                if (frame.len - offset < 1) return error.TruncatedFrame;
                offset += 1;
                produced = try checkedAdd(produced, block_len);
            },
            2 => {
                if (frame.len - offset < block_len) return error.TruncatedFrame;
                const block = frame[offset..][0..block_len];
                const section = try parseLiteralsSection(block, &frame_state);
                if (section.regenerated_size > header.block_size_max) return error.CorruptFrame;
                try validateSupportedLiteralSection(section);
                if (section.sequence_count == 0) {
                    try expectConsumedBlock(section.sequence_payload_offset, block.len);
                    try validateHuffmanLiteralsConsumed(block, section);
                    produced = try checkedAdd(produced, section.regenerated_size);
                } else {
                    var sequence_offset = section.sequence_payload_offset;
                    const parsed = try parseSequenceModeSpec(block, &sequence_offset, section.sequence_count);
                    var spec = try resolveSequenceModeSpec(parsed, frame_state.previous_tables);
                    try expectConsumedBlock(sequence_offset, block.len);
                    const path: NativeSequenceDecodeStagePath = if (spec.ll_mode == .compressed and
                        spec.of_mode == .compressed and
                        spec.ml_mode == .compressed and
                        (section.kind == .compressed or section.kind == .treeless) and
                        sequence_decode_policy.preferSplit(section.regenerated_size, section.sequence_count) and
                        section.huffman_streams == .four and
                        section.regenerated_size <= split_wide_huffman_literal_capacity) .wide_all_fse else if (spec.ll_mode == .compressed and
                        spec.of_mode == .compressed and
                        spec.ml_mode == .compressed and
                        section.kind == .raw and
                        sequence_decode_policy.preferRawAllFse(section.regenerated_size, section.sequence_count))
                        .wide_all_fse
                    else if (spec.ll_mode == .compressed and
                        spec.of_mode == .compressed and
                        spec.ml_mode == .compressed and
                        sequence_decode_policy.preferHuffmanAllFse(section.sequence_count))
                        .bounded_all_fse
                    else
                        .generic;
                    const prepared = PreparedNativeSequenceDecodeBlock{
                        .spec = spec,
                        .bitstream = block[spec.bitstream_offset..],
                        .sequence_count = section.sequence_count,
                        .repeated_offsets = frame_state.repeated_offsets,
                        .path = path,
                    };
                    const decoded = try decodePreparedNativeSequenceBlock(&prepared);
                    var generic_prepared = prepared;
                    generic_prepared.path = .generic;
                    const generic_decoded = try decodePreparedNativeSequenceBlock(&generic_prepared);
                    if (decoded.literal_bytes != generic_decoded.literal_bytes or
                        decoded.match_bytes != generic_decoded.match_bytes or
                        decoded.offset_sum != generic_decoded.offset_sum or
                        decoded.ordered_checksum != generic_decoded.ordered_checksum or
                        !std.mem.eql(usize, &decoded.repeated_offsets, &generic_decoded.repeated_offsets))
                        return error.CorruptFrame;
                    if (decoded.literal_bytes > section.regenerated_size) return error.CorruptFrame;
                    produced = try checkedAdd(produced, decoded.literal_bytes);
                    produced = try checkedAdd(produced, decoded.match_bytes);
                    produced = try checkedAdd(produced, section.regenerated_size - decoded.literal_bytes);
                    try validateHuffmanLiteralsConsumed(block, section);
                    frame_state.previous_tables = spec.tables();
                    frame_state.repeated_offsets = decoded.repeated_offsets;
                    try blocks.append(allocator, prepared);
                    shape.sequence_count = try checkedAdd(shape.sequence_count, section.sequence_count);
                    shape.sequence_block_count += 1;
                    switch (path) {
                        .generic => shape.generic_block_count += 1,
                        .bounded_all_fse => shape.bounded_all_fse_block_count += 1,
                        .wide_all_fse => shape.wide_all_fse_block_count += 1,
                    }
                }
                offset += block_len;
            },
            else => return error.CorruptFrame,
        }
        if (last) break;
    }
    if (shape.sequence_count == 0) return error.InvalidBlockPlan;
    if (shape.sequence_count != validated_profile.sequence_count) return error.CorruptFrame;
    if (header.content_size) |expected| if (try checkedUsizeToU64(produced) != expected) return error.SizeMismatch;
    if (header.has_checksum) {
        if (frame.len - offset < 4) return error.TruncatedFrame;
        offset += 4;
    }
    if (offset != frame.len) return error.TrailingData;
    const owned_blocks = try blocks.toOwnedSlice(allocator);
    errdefer allocator.free(owned_blocks);
    const expected = try decodePreparedNativeSequenceBlocks(owned_blocks);
    return .{
        .allocator = allocator,
        .blocks = owned_blocks,
        .prepared_shape = shape,
        .expected_checksum = expected.checksum,
    };
}

fn sequenceCopyLengthBucket(length: usize) usize {
    return if (length < 4) 0 else if (length < 8) 1 else if (length < 16) 2 else if (length < 32) 3 else if (length < 64) 4 else if (length < 128) 5 else if (length < 256) 6 else 7;
}

fn sequenceCopyOffsetBucket(offset: usize) usize {
    return if (offset < 4) 0 else if (offset < 8) 1 else if (offset < 16) 2 else if (offset < 32) 3 else if (offset < 64) 4 else if (offset < 256) 5 else if (offset < 1024) 6 else if (offset < 4096) 7 else 8;
}

pub fn inspectNativeFrameBlockSequenceModesWithDictionary(frame: []const u8, block: NativeFrameBlockHeader, dictionary: NativeDictionary) Error!NativeSequenceModeSummary {
    const active_dictionary = try dictionaryForInspectedFrame(frame, dictionary);
    var frame_state = try replayNativeFrameBlockInspectState(frame, block.header_offset, try initialSequenceFrameState(active_dictionary));
    return try inspectNativeFrameBlockSequenceModesWithState(frame, block, &frame_state);
}

pub fn inspectNativeFrameBlockSequenceModesWithDictionarySet(frame: []const u8, block: NativeFrameBlockHeader, dictionary_set: NativeDictionarySet) Error!NativeSequenceModeSummary {
    try dictionary_set.validate();
    const active_dictionary = try dictionaryForNativeFrame(frame, dictionary_set);
    var frame_state = try replayNativeFrameBlockInspectState(frame, block.header_offset, try initialSequenceFrameState(active_dictionary));
    return try inspectNativeFrameBlockSequenceModesWithState(frame, block, &frame_state);
}

test "zstd dictionary-aware sequence inspector seeds trained repeat tables" {
    const dictionary_hex = std.mem.trim(u8, @embedFile("zstd/testdata/libzstd-trained-repeat.dict.hex"), " \r\n\t");
    const frame_hex = std.mem.trim(u8, @embedFile("zstd/testdata/libzstd-trained-repeat.frame.hex"), " \r\n\t");
    const dictionary_bytes = try std.testing.allocator.alloc(u8, dictionary_hex.len / 2);
    defer std.testing.allocator.free(dictionary_bytes);
    _ = try std.fmt.hexToBytes(dictionary_bytes, dictionary_hex);
    const frame = try std.testing.allocator.alloc(u8, frame_hex.len / 2);
    defer std.testing.allocator.free(frame);
    _ = try std.fmt.hexToBytes(frame, frame_hex);

    const standard = try NativeDictionary.initFromStandardDictionary(dictionary_bytes);
    try std.testing.expectEqual(@as(u32, 0x7c06_9d4d), standard.dictionary.id);
    const block = try inspectNativeFrameFirstBlock(frame);
    try std.testing.expectEqual(NativeBlockType.compressed, block.block_type);
    try std.testing.expectError(error.CorruptFrame, inspectNativeFrameBlockSequenceModes(frame, block));
    const block_bytes = frame[block.payload_offset..][0..block.payload_len];
    var parse_state = try initialSequenceFrameState(standard.dictionary);
    const section = try parseLiteralsSection(block_bytes, &parse_state);
    var returned_offset = section.sequence_payload_offset;
    const returned_parsed = try parseSequenceModeSpec(block_bytes, &returned_offset, section.sequence_count);
    var direct_parsed: SequenceModeSpec = undefined;
    @memset(std.mem.asBytes(&direct_parsed), 0xa5);
    var direct_offset = section.sequence_payload_offset;
    try parseSequenceModeSpecInto(&direct_parsed, block_bytes, &direct_offset, section.sequence_count);
    try std.testing.expectEqual(returned_offset, direct_offset);
    try expectSequenceModeSpecsEqual(&returned_parsed, &direct_parsed);
    const returned_resolved = try resolveSequenceModeSpec(returned_parsed, parse_state.previous_tables);
    const direct_resolved = try resolveSequenceModeSpec(direct_parsed, parse_state.previous_tables);
    try expectSequenceModeSpecsEqual(&returned_resolved, &direct_resolved);

    const modes = try inspectNativeFrameBlockSequenceModesWithDictionary(frame, block, standard.dictionary);
    try std.testing.expectEqual(@as(usize, 57), modes.sequence_count);
    try std.testing.expectEqual(NativeLiteralsKind.raw, modes.literals_kind);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, modes.literal_length_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, modes.match_length_mode);

    const set = NativeDictionarySet.init(&.{standard.dictionary});
    try std.testing.expectEqual(modes, try inspectNativeFrameBlockSequenceModesWithDictionarySet(frame, block, set));
    try std.testing.expectError(error.NeedDictionary, inspectNativeFrameBlockSequenceModesWithDictionary(frame, block, NativeDictionary.init(standard.dictionary.id + 1, standard.dictionary.content)));
    try std.testing.expectError(error.NeedDictionary, inspectNativeFrameBlockSequenceModesWithDictionarySet(frame, block, NativeDictionarySet.init(&.{})));
    try std.testing.expectError(error.CorruptFrame, inspectNativeFrameBlockSequenceModesWithDictionary(frame, block, NativeDictionary.init(standard.dictionary.id, standard.dictionary.content)));
    var inconsistent = standard.dictionary;
    inconsistent.content = inconsistent.content[1..];
    try std.testing.expectError(error.InvalidDictionaryMetadata, inspectNativeFrameBlockSequenceModesWithDictionary(frame, block, inconsistent));
    try std.testing.expectError(error.InvalidDictionaryMetadata, decodedNativeFrameSizeWithDictionary(frame, inconsistent));
    try std.testing.expectError(error.InvalidDictionaryMetadata, decodeNativeFrameAllocWithDictionary(std.testing.allocator, frame, inconsistent));

    const decoded = try decodeNativeFrameAllocWithDictionary(std.testing.allocator, frame, standard.dictionary);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqual(@as(usize, 2304), decoded.len);
    try std.testing.expectEqual(@as(u32, 1_658_167_111), checksum_mod.crc32(decoded));
}

test "zstd native writer can reuse standard dictionary sequence tables" {
    const dictionary_hex = std.mem.trim(u8, @embedFile("zstd/testdata/libzstd-trained-repeat.dict.hex"), " \r\n\t");
    const frame_hex = std.mem.trim(u8, @embedFile("zstd/testdata/libzstd-trained-repeat.frame.hex"), " \r\n\t");
    const dictionary_bytes = try std.testing.allocator.alloc(u8, dictionary_hex.len / 2);
    defer std.testing.allocator.free(dictionary_bytes);
    _ = try std.fmt.hexToBytes(dictionary_bytes, dictionary_hex);
    const source_frame = try std.testing.allocator.alloc(u8, frame_hex.len / 2);
    defer std.testing.allocator.free(source_frame);
    _ = try std.fmt.hexToBytes(source_frame, frame_hex);

    const standard = try NativeDictionary.initFromStandardDictionary(dictionary_bytes);
    const payload = try decodeNativeFrameAllocWithDictionary(std.testing.allocator, source_frame, standard.dictionary);
    defer std.testing.allocator.free(payload);
    const encoded = try encodeNativeFrameWithDictionaryAlloc(std.testing.allocator, payload, .{
        .selection = .literal_only,
        .content_checksum = false,
    }, standard.dictionary);
    defer std.testing.allocator.free(encoded.frame);
    const block = try inspectNativeFrameFirstBlock(encoded.frame);
    const modes = try inspectNativeFrameBlockSequenceModesWithDictionary(encoded.frame, block, standard.dictionary);
    try std.testing.expect(modes.sequence_count != 0);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, modes.literal_length_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.compressed, modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.compressed, modes.match_length_mode);
    const decoded = try decodeFrameAllocWithDictionary(std.testing.allocator, encoded.frame, standard.dictionary);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
}

fn dictionaryForInspectedFrame(frame: []const u8, dictionary: NativeDictionary) Error!?NativeDictionary {
    const header = try inspectNativeFrameHeader(frame);
    if (header.dictionary_id == 0) return dictionary;
    if (dictionary.id != header.dictionary_id) return error.NeedDictionary;
    return dictionary;
}

fn replayNativeFrameBlockInspectState(frame: []const u8, target_header_offset: usize, initial_state: SequenceFrameState) Error!SequenceFrameState {
    const header = try inspectNativeFrameHeader(frame);
    if (target_header_offset < header.payload_offset) return error.CorruptFrame;
    var frame_state = initial_state;
    var offset = header.payload_offset;
    while (offset < target_header_offset) {
        const previous_block = try inspectNativeFrameBlockAt(frame, offset);
        if (previous_block.header_offset >= target_header_offset) break;
        if (previous_block.block_type == .compressed) {
            _ = try inspectNativeFrameBlockSequenceModesWithState(frame, previous_block, &frame_state);
        }
        if (previous_block.last) return error.CorruptFrame;
        offset = previous_block.next_header_offset;
    }
    if (offset != target_header_offset) return error.CorruptFrame;
    return frame_state;
}

fn inspectNativeFrameBlockSequenceModesWithState(
    frame: []const u8,
    block: NativeFrameBlockHeader,
    frame_state: *SequenceFrameState,
) Error!NativeSequenceModeSummary {
    try validateNativeFrameBlockPayloadAvailable(frame, block);
    if (block.block_type != .compressed) return nativeSequenceModeSummaryForLiteralBlock(block);
    const payload = frame[block.payload_offset..][0..block.payload_len];
    const section = try parseLiteralsSection(payload, frame_state);
    if (section.sequence_count == 0) {
        return .{
            .literals_kind = nativeLiteralsKind(section.kind),
            .regenerated_literals_size = section.regenerated_size,
            .sequence_count = 0,
            .literal_length_mode = .predefined,
            .offset_mode = .predefined,
            .match_length_mode = .predefined,
        };
    }
    var offset = section.sequence_payload_offset;
    if (offset >= payload.len) return error.TruncatedFrame;
    if (sequence_predefined.isModeByte(payload[offset])) {
        // A predefined table is still the active table for a later block's
        // Repeat_Mode. The decoder commits this state after executing the
        // block; inspection must mirror that transition while replaying prior
        // blocks even though no table payload needs parsing here.
        frame_state.previous_tables = predefinedSequenceTables();
        return .{
            .literals_kind = nativeLiteralsKind(section.kind),
            .regenerated_literals_size = section.regenerated_size,
            .sequence_count = section.sequence_count,
            .literal_length_mode = .predefined,
            .offset_mode = .predefined,
            .match_length_mode = .predefined,
        };
    }
    const spec = try parseSequenceModeSpec(payload, &offset, section.sequence_count);
    const resolved = try resolveSequenceModeSpec(spec, frame_state.previous_tables);
    frame_state.previous_tables = resolved.tables();
    return .{
        .literals_kind = nativeLiteralsKind(section.kind),
        .regenerated_literals_size = section.regenerated_size,
        .sequence_count = section.sequence_count,
        .literal_length_mode = nativeSequenceTableMode(spec.ll_mode),
        .offset_mode = nativeSequenceTableMode(spec.of_mode),
        .match_length_mode = nativeSequenceTableMode(spec.ml_mode),
    };
}

fn validateNativeFrameBlockPayloadAvailable(frame: []const u8, block: NativeFrameBlockHeader) Error!void {
    const required_payload_len: usize = if (block.block_type == .rle) 1 else block.payload_len;
    if (block.payload_offset > frame.len or frame.len - block.payload_offset < required_payload_len) return error.TruncatedFrame;
}

fn nativeSequenceModeSummaryForLiteralBlock(block: NativeFrameBlockHeader) NativeSequenceModeSummary {
    return .{
        .literals_kind = switch (block.block_type) {
            .raw => .raw,
            .rle => .rle,
            .compressed => unreachable,
        },
        .regenerated_literals_size = block.payload_len,
        .sequence_count = 0,
        .literal_length_mode = .predefined,
        .offset_mode = .predefined,
        .match_length_mode = .predefined,
    };
}

fn nativeLiteralsKind(kind: LiteralsKind) NativeLiteralsKind {
    return switch (kind) {
        .raw => .raw,
        .rle => .rle,
        .compressed => .compressed,
        .treeless => .treeless,
    };
}

fn nativeSequenceTableMode(mode: SymbolMode) NativeSequenceTableMode {
    return switch (mode) {
        .predefined => .predefined,
        .rle => .rle,
        .compressed => .compressed,
        .repeat => .repeat,
    };
}

pub fn summarizeNativeFrameBlocks(frame: []const u8) Error!NativeFrameBlockSummary {
    const header = try inspectNativeFrameHeader(frame);
    var offset = header.payload_offset;
    var summary: NativeFrameBlockSummary = .{};
    while (true) {
        const block = try inspectNativeFrameBlockAt(frame, offset);
        summary.block_count += 1;
        switch (block.block_type) {
            .raw => summary.raw_block_count += 1,
            .rle => summary.rle_block_count += 1,
            .compressed => summary.compressed_block_count += 1,
        }
        summary.payload_bytes = std.math.add(usize, summary.payload_bytes, block.payload_len) catch return error.IntegerOverflow;
        if (block.last) break;
        offset = block.next_header_offset;
    }
    return summary;
}

pub fn inspectNativeSkippableFrame(frame: []const u8) Error!NativeSkippableFrameHeader {
    if (frame.len < 8) return error.TruncatedFrame;
    const magic = std.mem.readInt(u32, frame[0..4], .little);
    if (magic < skippable_magic_min or magic > skippable_magic_max) return error.InvalidMagic;
    const payload_len: usize = @intCast(std.mem.readInt(u32, frame[4..8], .little));
    if (frame.len - 8 < payload_len) return error.TruncatedFrame;
    return .{
        .skippable_id = @intCast(magic - skippable_magic_min),
        .payload_offset = 8,
        .payload_len = payload_len,
        .next_frame_offset = 8 + payload_len,
    };
}

/// Parse the seek table terminating a complete Zstandard seekable stream. The
/// footer is located from EOF, as required by the contrib seekable format, and
/// the table's cumulative compressed sizes must point exactly at its own
/// skippable header. This rejects a valid-looking footer detached from the
/// frames it claims to index.
pub fn inspectNativeSeekTable(stream: []const u8) Error!NativeSeekTable {
    return seekable.inspect(stream);
}

/// Locate the seekable frame that contains an uncompressed byte offset.
pub fn nativeSeekTableFrameIndexForOffset(table: NativeSeekTable, offset: u64) Error!u32 {
    return seekable.frameIndexForOffset(table, offset);
}

/// Materialize cumulative seek-table entries into caller-owned storage. The
/// returned index borrows both `storage` and the stream retained by `table`;
/// neither may be changed while the index is in use.
pub fn buildNativeSeekIndex(table: NativeSeekTable, storage: []NativeSeekTableEntry) Error!NativeSeekIndex {
    return seekable.buildIndex(table, storage);
}

pub fn encodedNativeSeekTableBound(entry_count: usize, with_checksums: bool) Error!usize {
    return seekable.encodedTableBound(entry_count, with_checksums);
}

pub fn encodeNativeSeekTableAlloc(allocator: std.mem.Allocator, entries: []const NativeSeekTableFrameSize, with_checksums: bool) Error![]u8 {
    return seekable.encodeTableAlloc(allocator, entries, with_checksums);
}

pub fn encodeNativeSeekTableAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), entries: []const NativeSeekTableFrameSize, with_checksums: bool) Error!void {
    return seekable.encodeTableAppend(allocator, out, entries, with_checksums);
}

pub fn encodeNativeSeekTableInto(entries: []const NativeSeekTableFrameSize, with_checksums: bool, output: []u8) Error!usize {
    return seekable.encodeTableInto(entries, with_checksums, output);
}

/// Return a conservative output bound for a native Zstandard seekable stream.
/// The bound covers every independently compressed frame plus the terminal
/// seek table, so callers can allocate once and use the matching `IntoSlice`
/// encoder without growing the destination.
pub fn encodedNativeSeekableStreamBound(input_len: usize, options: NativeSeekableOptions) Error!usize {
    try validateNativeSeekableOptions(options);
    return encodedNativeSeekableStreamBoundInternal(input_len, options, null);
}

pub fn encodedNativeSeekableStreamBoundWithDictionary(input_len: usize, options: NativeSeekableOptions, dictionary: NativeDictionary) Error!usize {
    try validateNativeSeekableOptions(options);
    return encodedNativeSeekableStreamBoundInternal(input_len, options, dictionary);
}

pub fn encodedNativeSeekableStreamBoundWithDictionarySet(input_len: usize, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error!usize {
    const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
    return encodedNativeSeekableStreamBoundWithDictionary(input_len, options, dictionary);
}

fn encodedNativeSeekableStreamBoundInternal(input_len: usize, options: NativeSeekableOptions, dictionary: ?NativeDictionary) Error!usize {
    const frame_count = try nativeSeekableFrameCount(input_len, options.frame_size);
    const frame_options = optionsWithNativeDictionary(options.frame_options, dictionary);
    var bound = try encodedNativeSeekTableBound(frame_count, options.seek_checksums);
    if (input_len == 0)
        return std.math.add(usize, bound, try encodedNativeFrameBoundWithOptions(0, frame_options)) catch return error.IntegerOverflow;

    const full_frame_count = input_len / options.frame_size;
    if (full_frame_count != 0) {
        const full_frame_bound = try encodedNativeFrameBoundWithOptions(options.frame_size, frame_options);
        bound = std.math.add(usize, bound, std.math.mul(usize, full_frame_count, full_frame_bound) catch return error.IntegerOverflow) catch return error.IntegerOverflow;
    }
    const tail_len = input_len % options.frame_size;
    if (tail_len != 0)
        bound = std.math.add(usize, bound, try encodedNativeFrameBoundWithOptions(tail_len, frame_options)) catch return error.IntegerOverflow;
    return bound;
}

/// Encode independently decompressible native Zstandard frames followed by the
/// standardized terminal seek table. Per-entry checksums use the low 32 bits of
/// XXH64 as required by the seekable-format specification and are independent
/// of each frame's optional content checksum setting.
pub fn encodeNativeSeekableStreamAlloc(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions) Error![]u8 {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeAlloc(input, options);
}

pub fn encodeNativeSeekableStreamAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions) Error!void {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeAppend(out, input, options);
}

pub fn encodeNativeSeekableStreamIntoSlice(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions, output: []u8) Error!usize {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeIntoSlice(input, options, output);
}

pub fn encodeNativeSeekableStreamWithDictionaryAlloc(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary) Error![]u8 {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeWithDictionaryAlloc(input, options, dictionary);
}

pub fn encodeNativeSeekableStreamAppendWithDictionary(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary) Error!void {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeAppendWithDictionary(out, input, options, dictionary);
}

pub fn encodeNativeSeekableStreamIntoSliceWithDictionary(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary, output: []u8) Error!usize {
    var encoder = NativeSeekableStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeIntoSliceWithDictionary(input, options, dictionary, output);
}

pub fn encodeNativeSeekableStreamWithDictionarySetAlloc(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error![]u8 {
    const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
    return encodeNativeSeekableStreamWithDictionaryAlloc(allocator, input, options, dictionary);
}

/// Maximum caller-requested concurrency for the native seekable encoder.
/// Actual concurrency is additionally capped by the number of independent
/// frames, and the calling thread participates in the work queue.
pub const native_seekable_parallel_workers_max: usize = 256;

/// Encode independent native Zstandard frames concurrently and append the
/// standardized seek table in deterministic frame order. A worker count of one
/// uses the existing serial encoder directly. Failure to create an optional
/// worker reduces concurrency; it never changes the wire or abandons queued
/// work.
pub fn encodeNativeSeekableStreamParallelAlloc(
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeSeekableOptions,
    worker_count: usize,
) Error![]u8 {
    try validateNativeSeekableOptions(options);
    return encodeNativeSeekableStreamParallelInternal(allocator, input, options, null, worker_count);
}

pub fn encodeNativeSeekableStreamParallelWithDictionaryAlloc(
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeSeekableOptions,
    dictionary: NativeDictionary,
    worker_count: usize,
) Error![]u8 {
    try validateNativeSeekableOptions(options);
    return encodeNativeSeekableStreamParallelInternal(allocator, input, options, dictionary, worker_count);
}

pub fn encodeNativeSeekableStreamParallelWithDictionarySetAlloc(
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeSeekableOptions,
    dictionary_set: NativeDictionarySet,
    dictionary_id: u32,
    worker_count: usize,
) Error![]u8 {
    const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
    return encodeNativeSeekableStreamParallelWithDictionaryAlloc(allocator, input, options, dictionary, worker_count);
}

pub fn encodeNativeSeekableStreamAppendWithDictionarySet(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error!void {
    const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
    return encodeNativeSeekableStreamAppendWithDictionary(allocator, out, input, options, dictionary);
}

pub fn encodeNativeSeekableStreamIntoSliceWithDictionarySet(allocator: std.mem.Allocator, input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32, output: []u8) Error!usize {
    const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
    return encodeNativeSeekableStreamIntoSliceWithDictionary(allocator, input, options, dictionary, output);
}

fn validateNativeSeekableOptions(options: NativeSeekableOptions) Error!void {
    if (options.frame_size == 0 or options.frame_size > seekable.max_frame_decompressed_size or options.frame_options.dictionary_id != 0) return error.InvalidBlockPlan;
}

fn nativeSeekableFrameCount(input_len: usize, frame_size: usize) Error!usize {
    if (input_len == 0) return 1;
    const frame_count = std.math.divCeil(usize, input_len, frame_size) catch return error.IntegerOverflow;
    if (frame_count > seekable.max_frames) return error.InvalidBlockPlan;
    return frame_count;
}

const ParallelNativeSeekableFrameResult = struct {
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeFrameOptions,
    dictionary: ?NativeDictionary,
    seek_checksums: bool,
    entry: *NativeSeekTableFrameSize,
    frame: ?[]u8 = null,
    err: ?Error = null,

    fn run(self: *ParallelNativeSeekableFrameResult) void {
        var encoder = NativeFrameEncoder.init(self.allocator);
        defer encoder.deinit();
        const encoded = if (self.dictionary) |dictionary|
            encoder.encodeWithDictionaryAlloc(self.input, self.options, dictionary)
        else
            encoder.encodeWithOptionsAlloc(self.input, self.options);
        const result = encoded catch |err| {
            self.err = err;
            return;
        };
        self.frame = result.frame;
        self.entry.* = nativeSeekableFrameSize(result.frame.len, self.input, self.seek_checksums) catch |err| {
            self.err = err;
            return;
        };
    }
};

const ParallelNativeSeekableQueue = struct {
    next: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
    results: []ParallelNativeSeekableFrameResult,

    fn run(self: *ParallelNativeSeekableQueue) void {
        while (true) {
            const index = self.next.fetchAdd(1, .monotonic);
            if (index >= self.results.len) return;
            self.results[index].run();
        }
    }
};

fn encodeNativeSeekableStreamParallelInternal(
    allocator: std.mem.Allocator,
    input: []const u8,
    options: NativeSeekableOptions,
    dictionary: ?NativeDictionary,
    worker_count: usize,
) Error![]u8 {
    if (worker_count == 0 or worker_count > native_seekable_parallel_workers_max) return error.InvalidBlockPlan;
    const frame_count = try nativeSeekableFrameCount(input.len, options.frame_size);
    if (worker_count == 1 or frame_count == 1 or comptime builtin.single_threaded) {
        return if (dictionary) |dict|
            encodeNativeSeekableStreamWithDictionaryAlloc(allocator, input, options, dict)
        else
            encodeNativeSeekableStreamAlloc(allocator, input, options);
    }

    var locked_allocator = LockedAllocator{ .child = allocator };
    const parallel_allocator = locked_allocator.allocator();
    const entries = try allocator.alloc(NativeSeekTableFrameSize, frame_count);
    defer allocator.free(entries);
    const results = try allocator.alloc(ParallelNativeSeekableFrameResult, frame_count);
    defer allocator.free(results);
    for (results, 0..) |*result, frame_index| {
        const start = frame_index * options.frame_size;
        const end = @min(input.len, start + options.frame_size);
        result.* = .{
            .allocator = parallel_allocator,
            .input = input[start..end],
            .options = options.frame_options,
            .dictionary = dictionary,
            .seek_checksums = options.seek_checksums,
            .entry = &entries[frame_index],
        };
    }
    defer for (results) |result| if (result.frame) |frame| parallel_allocator.free(frame);

    const actual_workers = @min(worker_count, frame_count);
    const threads = try allocator.alloc(std.Thread, actual_workers - 1);
    defer allocator.free(threads);
    var queue: ParallelNativeSeekableQueue = .{ .results = results };
    var spawned: usize = 0;
    while (spawned < threads.len) : (spawned += 1) {
        threads[spawned] = std.Thread.spawn(.{}, ParallelNativeSeekableQueue.run, .{&queue}) catch break;
    }
    queue.run();
    for (threads[0..spawned]) |thread| thread.join();

    for (results) |result| if (result.err) |err| return err;
    var total_len = try encodedNativeSeekTableBound(frame_count, options.seek_checksums);
    for (results) |result|
        total_len = std.math.add(usize, total_len, result.frame.?.len) catch return error.IntegerOverflow;
    const stream = try allocator.alloc(u8, total_len);
    errdefer allocator.free(stream);
    var written: usize = 0;
    for (results) |result| {
        const frame = result.frame.?;
        @memcpy(stream[written..][0..frame.len], frame);
        written += frame.len;
    }
    written += try encodeNativeSeekTableInto(entries, options.seek_checksums, stream[written..]);
    if (written != stream.len) return error.CorruptFrame;
    return stream;
}

/// Reusable native seekable-stream encoder. It retains both per-frame codec
/// scratch (including block-candidate arbitration buffers and match-parser
/// workspaces), the seek-entry array, and optional scratch output across calls.
/// Caller-owned destinations remain available through the append/into methods.
pub const NativeSeekableStreamEncoder = struct {
    allocator: std.mem.Allocator,
    frame_encoder: NativeFrameEncoder,
    entries: std.ArrayList(NativeSeekTableFrameSize) = .empty,
    output_scratch: std.ArrayList(u8) = .empty,

    pub fn init(allocator: std.mem.Allocator) NativeSeekableStreamEncoder {
        return .{ .allocator = allocator, .frame_encoder = NativeFrameEncoder.init(allocator) };
    }

    pub fn deinit(self: *NativeSeekableStreamEncoder) void {
        self.output_scratch.deinit(self.allocator);
        self.entries.deinit(self.allocator);
        self.frame_encoder.deinit();
        self.* = undefined;
    }

    pub fn encodeAlloc(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions) Error![]u8 {
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(self.allocator);
        try self.encodeAppend(&out, input, options);
        return out.toOwnedSlice(self.allocator);
    }

    pub fn encodeWithDictionaryAlloc(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary) Error![]u8 {
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(self.allocator);
        try self.encodeAppendWithDictionary(&out, input, options, dictionary);
        return out.toOwnedSlice(self.allocator);
    }

    pub fn encodeWithDictionarySetAlloc(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error![]u8 {
        const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
        return self.encodeWithDictionaryAlloc(input, options, dictionary);
    }

    pub fn encodeScratch(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions) Error![]const u8 {
        try validateNativeSeekableOptions(options);
        return self.encodeScratchInternal(input, options, null);
    }

    pub fn encodeScratchWithDictionary(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary) Error![]const u8 {
        try validateNativeSeekableOptions(options);
        return self.encodeScratchInternal(input, options, dictionary);
    }

    pub fn encodeScratchWithDictionarySet(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error![]const u8 {
        const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
        return self.encodeScratchWithDictionary(input, options, dictionary);
    }

    pub fn encodeAppend(self: *NativeSeekableStreamEncoder, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions) Error!void {
        try validateNativeSeekableOptions(options);
        return self.encodeAppendInternal(out, input, options, null);
    }

    pub fn encodeAppendWithDictionary(self: *NativeSeekableStreamEncoder, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary) Error!void {
        try validateNativeSeekableOptions(options);
        return self.encodeAppendInternal(out, input, options, dictionary);
    }

    pub fn encodeAppendWithDictionarySet(self: *NativeSeekableStreamEncoder, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32) Error!void {
        const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
        return self.encodeAppendWithDictionary(out, input, options, dictionary);
    }

    pub fn encodeIntoSlice(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, output: []u8) Error!usize {
        try validateNativeSeekableOptions(options);
        return self.encodeIntoSliceInternal(input, options, null, output);
    }

    pub fn encodeIntoSliceWithDictionary(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary: NativeDictionary, output: []u8) Error!usize {
        try validateNativeSeekableOptions(options);
        return self.encodeIntoSliceInternal(input, options, dictionary, output);
    }

    pub fn encodeIntoSliceWithDictionarySet(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary_set: NativeDictionarySet, dictionary_id: u32, output: []u8) Error!usize {
        const dictionary = try dictionaryFromSet(dictionary_set, dictionary_id);
        return self.encodeIntoSliceWithDictionary(input, options, dictionary, output);
    }

    fn prepareEntries(self: *NativeSeekableStreamEncoder, input_len: usize, frame_size: usize) Error![]NativeSeekTableFrameSize {
        const frame_count = try nativeSeekableFrameCount(input_len, frame_size);
        try self.entries.resize(self.allocator, frame_count);
        return self.entries.items;
    }

    fn encodeScratchInternal(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary: ?NativeDictionary) Error![]const u8 {
        self.output_scratch.clearRetainingCapacity();
        self.encodeAppendInternal(&self.output_scratch, input, options, dictionary) catch |err| {
            self.output_scratch.clearRetainingCapacity();
            return err;
        };
        return self.output_scratch.items;
    }

    fn encodeAppendInternal(self: *NativeSeekableStreamEncoder, out: *std.ArrayList(u8), input: []const u8, options: NativeSeekableOptions, dictionary: ?NativeDictionary) Error!void {
        const entries = try self.prepareEntries(input.len, options.frame_size);
        const original_len = out.items.len;
        errdefer out.shrinkRetainingCapacity(original_len);
        for (entries, 0..) |*entry_value, frame_index| {
            const start = if (input.len == 0) 0 else frame_index * options.frame_size;
            const end = if (input.len == 0) 0 else @min(input.len, start + options.frame_size);
            const chunk = input[start..end];
            const compressed_start = out.items.len;
            if (dictionary) |dict|
                _ = try self.frame_encoder.encodeAppendWithDictionary(out, chunk, options.frame_options, dict)
            else
                _ = try self.frame_encoder.encodeAppend(out, chunk, options.frame_options);
            entry_value.* = try nativeSeekableFrameSize(out.items.len - compressed_start, chunk, options.seek_checksums);
        }
        try encodeNativeSeekTableAppend(self.allocator, out, entries, options.seek_checksums);
    }

    fn encodeIntoSliceInternal(self: *NativeSeekableStreamEncoder, input: []const u8, options: NativeSeekableOptions, dictionary: ?NativeDictionary, output: []u8) Error!usize {
        const entries = try self.prepareEntries(input.len, options.frame_size);
        var written: usize = 0;
        for (entries, 0..) |*entry_value, frame_index| {
            const start = if (input.len == 0) 0 else frame_index * options.frame_size;
            const end = if (input.len == 0) 0 else @min(input.len, start + options.frame_size);
            const chunk = input[start..end];
            const encoded = if (dictionary) |dict|
                try self.frame_encoder.encodeScratchWithDictionary(chunk, options.frame_options, dict)
            else
                try self.frame_encoder.encodeScratch(chunk, options.frame_options);
            if (encoded.frame.len > output.len -| written) return error.OutputTooSmall;
            @memcpy(output[written..][0..encoded.frame.len], encoded.frame);
            written += encoded.frame.len;
            entry_value.* = try nativeSeekableFrameSize(encoded.frame.len, chunk, options.seek_checksums);
        }
        written += try encodeNativeSeekTableInto(entries, options.seek_checksums, output[written..]);
        return written;
    }
};

pub const SeekableStreamEncoder = NativeSeekableStreamEncoder;

fn nativeSeekableFrameSize(compressed_len: usize, input: []const u8, with_checksum: bool) Error!NativeSeekTableFrameSize {
    return .{
        .compressed_size = try checkedUsizeToU32(compressed_len),
        .decompressed_size = try checkedUsizeToU32(input.len),
        .checksum = if (with_checksum) @truncate(std.hash.XxHash64.hash(0, input)) else null,
    };
}

pub fn nativeSeekableRangeScratchLen(table: NativeSeekTable, offset: u64, length: usize) Error!usize {
    const range_end = try nativeSeekableRangeEnd(table, offset, length);
    if (length == 0) return 0;

    var needed: usize = 0;
    var entries = table.iterator();
    while (try entries.next()) |entry_value| {
        const frame_end = std.math.add(u64, entry_value.decompressed_offset, entry_value.decompressed_size) catch return error.IntegerOverflow;
        if (frame_end <= offset) continue;
        if (entry_value.decompressed_offset >= range_end) break;
        needed = @max(needed, std.math.cast(usize, entry_value.decompressed_size) orelse return error.IntegerOverflow);
    }
    return needed;
}

/// Return the exact scratch requirement using a previously built seek index.
/// Offset lookup is O(log n), and only intersecting entries are then scanned.
pub fn nativeSeekableRangeScratchLenWithIndex(index: NativeSeekIndex, offset: u64, length: usize) Error!usize {
    return (try prepareNativeSeekableIndexedRange(index, offset, length)).scratch_len;
}

const NativeSeekableIndexedRange = struct {
    range_end: u64,
    first_entry: usize,
    scratch_len: usize,
};

fn prepareNativeSeekableIndexedRange(index: NativeSeekIndex, offset: u64, length: usize) Error!NativeSeekableIndexedRange {
    const range_end = try nativeSeekableRangeEnd(index.table, offset, length);
    if (length == 0) return .{ .range_end = range_end, .first_entry = 0, .scratch_len = 0 };

    const first = std.math.cast(usize, try index.frameIndexForDecompressedOffset(offset)) orelse return error.IntegerOverflow;
    var needed: usize = 0;
    for (index.entries[first..]) |entry_value| {
        if (entry_value.decompressed_offset >= range_end) break;
        needed = @max(needed, std.math.cast(usize, entry_value.decompressed_size) orelse return error.IntegerOverflow);
    }
    return .{ .range_end = range_end, .first_entry = first, .scratch_len = needed };
}

fn nativeSeekableRangeEnd(table: NativeSeekTable, offset: u64, length: usize) Error!u64 {
    const length_u64 = std.math.cast(u64, length) orelse return error.IntegerOverflow;
    const range_end = std.math.add(u64, offset, length_u64) catch return error.IntegerOverflow;
    if (offset > table.decompressed_size or range_end > table.decompressed_size) return error.RangeOutOfBounds;
    return range_end;
}

/// Decode only seekable frames intersecting `[offset, offset + output.len)`.
/// `frame_scratch` must fit the largest selected decompressed frame; callers can
/// obtain the exact requirement from `nativeSeekableRangeScratchLen`.
pub fn decodeNativeSeekableRangeInto(stream: []const u8, offset: u64, output: []u8, frame_scratch: []u8) Error!usize {
    return decodeNativeSeekableRangeIntoInternal(stream, offset, output, frame_scratch, .none);
}

pub fn decodeNativeSeekableRangeIntoWithDictionary(stream: []const u8, offset: u64, output: []u8, frame_scratch: []u8, dictionary: NativeDictionary) Error!usize {
    return decodeNativeSeekableRangeIntoInternal(stream, offset, output, frame_scratch, .{ .explicit = dictionary });
}

pub fn decodeNativeSeekableRangeIntoWithDictionarySet(stream: []const u8, offset: u64, output: []u8, frame_scratch: []u8, dictionary_set: NativeDictionarySet) Error!usize {
    try dictionary_set.validate();
    return decodeNativeSeekableRangeIntoInternal(stream, offset, output, frame_scratch, .{ .set = dictionary_set });
}

/// Decode a range through a reusable caller-owned index, avoiding terminal
/// table parsing and the linear scan from entry zero on every request.
pub fn decodeNativeSeekableRangeIntoWithIndex(index: NativeSeekIndex, offset: u64, output: []u8, frame_scratch: []u8) Error!usize {
    return decodeNativeSeekableRangeIntoWithIndexInternal(index, offset, output, frame_scratch, .none);
}

pub fn decodeNativeSeekableRangeIntoWithIndexAndDictionary(index: NativeSeekIndex, offset: u64, output: []u8, frame_scratch: []u8, dictionary: NativeDictionary) Error!usize {
    return decodeNativeSeekableRangeIntoWithIndexInternal(index, offset, output, frame_scratch, .{ .explicit = dictionary });
}

pub fn decodeNativeSeekableRangeIntoWithIndexAndDictionarySet(index: NativeSeekIndex, offset: u64, output: []u8, frame_scratch: []u8, dictionary_set: NativeDictionarySet) Error!usize {
    try dictionary_set.validate();
    return decodeNativeSeekableRangeIntoWithIndexInternal(index, offset, output, frame_scratch, .{ .set = dictionary_set });
}

const NativeSeekableDictionaryResolver = union(enum) {
    none,
    explicit: NativeDictionary,
    set: NativeDictionarySet,
};

fn decodeNativeSeekableRangeIntoInternal(stream: []const u8, offset: u64, output: []u8, frame_scratch: []u8, dictionary_resolver: NativeSeekableDictionaryResolver) Error!usize {
    const table = try inspectNativeSeekTable(stream);
    const needed_scratch = try nativeSeekableRangeScratchLen(table, offset, output.len);
    if (frame_scratch.len < needed_scratch) return error.OutputTooSmall;
    if (output.len == 0) return 0;

    const range_end = std.math.add(u64, offset, @as(u64, @intCast(output.len))) catch return error.IntegerOverflow;
    var output_offset: usize = 0;
    var entries = table.iterator();
    while (try entries.next()) |entry_value| {
        const frame_end = std.math.add(u64, entry_value.decompressed_offset, entry_value.decompressed_size) catch return error.IntegerOverflow;
        if (frame_end <= offset) continue;
        if (entry_value.decompressed_offset >= range_end) break;
        if (entry_value.decompressed_size == 0) continue;

        output_offset += try decodeNativeSeekableEntryRange(table, entry_value, offset, range_end, output[output_offset..], frame_scratch, dictionary_resolver);
    }
    if (output_offset != output.len) return error.SizeMismatch;
    return output_offset;
}

fn decodeNativeSeekableRangeIntoWithIndexInternal(index: NativeSeekIndex, offset: u64, output: []u8, frame_scratch: []u8, dictionary_resolver: NativeSeekableDictionaryResolver) Error!usize {
    // Preflight range bounds, first-frame lookup, and scratch sizing together.
    // Repeated one-frame reads otherwise paid for the binary search twice.
    const range = try prepareNativeSeekableIndexedRange(index, offset, output.len);
    if (frame_scratch.len < range.scratch_len) return error.OutputTooSmall;
    return decodeNativeSeekablePreparedRangeInto(index, range, offset, output, frame_scratch, dictionary_resolver);
}

fn decodeNativeSeekablePreparedRangeInto(index: NativeSeekIndex, range: NativeSeekableIndexedRange, offset: u64, output: []u8, frame_scratch: []u8, dictionary_resolver: NativeSeekableDictionaryResolver) Error!usize {
    if (output.len == 0) return 0;

    var output_offset: usize = 0;
    for (index.entries[range.first_entry..]) |entry_value| {
        if (entry_value.decompressed_offset >= range.range_end) break;
        if (entry_value.decompressed_size == 0) continue;
        output_offset += try decodeNativeSeekableEntryRange(index.table, entry_value, offset, range.range_end, output[output_offset..], frame_scratch, dictionary_resolver);
    }
    if (output_offset != output.len) return error.SizeMismatch;
    return output_offset;
}

fn decodeNativeSeekableEntryRange(table: NativeSeekTable, entry_value: NativeSeekTableEntry, offset: u64, range_end: u64, output: []u8, frame_scratch: []u8, dictionary_resolver: NativeSeekableDictionaryResolver) Error!usize {
    const frame_end = std.math.add(u64, entry_value.decompressed_offset, entry_value.decompressed_size) catch return error.IntegerOverflow;
    const compressed_start = std.math.cast(usize, entry_value.compressed_offset) orelse return error.IntegerOverflow;
    const compressed_size = std.math.cast(usize, entry_value.compressed_size) orelse return error.IntegerOverflow;
    const compressed_end = std.math.add(usize, compressed_start, compressed_size) catch return error.IntegerOverflow;
    if (table.frame_offset > table.stream.len or compressed_end > table.frame_offset) return error.CorruptFrame;
    const decompressed_size = std.math.cast(usize, entry_value.decompressed_size) orelse return error.IntegerOverflow;
    if (decompressed_size > frame_scratch.len) return error.OutputTooSmall;
    const decoded_frame = frame_scratch[0..decompressed_size];
    const frame = table.stream[compressed_start..compressed_end];
    _ = switch (dictionary_resolver) {
        .none => try decodeNativeFrameIntoExactSize(frame, decoded_frame, decompressed_size),
        .explicit => |dictionary| try decodeNativeFrameIntoWithDictionaryExactSize(frame, decoded_frame, dictionary, decompressed_size),
        .set => |set| try decodeNativeFrameIntoWithDictionarySetExactSize(frame, decoded_frame, set, decompressed_size),
    };
    if (entry_value.checksum) |expected| {
        const actual: u32 = @truncate(std.hash.XxHash64.hash(0, decoded_frame));
        if (actual != expected) return error.ChecksumMismatch;
    }

    const copy_start_u64 = @max(offset, entry_value.decompressed_offset) - entry_value.decompressed_offset;
    const copy_end_u64 = @min(range_end, frame_end) - entry_value.decompressed_offset;
    const copy_start = std.math.cast(usize, copy_start_u64) orelse return error.IntegerOverflow;
    const copy_end = std.math.cast(usize, copy_end_u64) orelse return error.IntegerOverflow;
    if (copy_start > copy_end or copy_end > decoded_frame.len) return error.CorruptFrame;
    const copy_len = copy_end - copy_start;
    if (copy_len > output.len) return error.OutputTooSmall;
    @memcpy(output[0..copy_len], decoded_frame[copy_start..copy_end]);
    return copy_len;
}

pub fn decodeNativeSeekableRangeAlloc(allocator: std.mem.Allocator, stream: []const u8, offset: u64, length: usize) Error![]u8 {
    return decodeNativeSeekableRangeAllocInternal(allocator, stream, offset, length, .none);
}

pub fn decodeNativeSeekableRangeAllocWithDictionary(allocator: std.mem.Allocator, stream: []const u8, offset: u64, length: usize, dictionary: NativeDictionary) Error![]u8 {
    return decodeNativeSeekableRangeAllocInternal(allocator, stream, offset, length, .{ .explicit = dictionary });
}

pub fn decodeNativeSeekableRangeAllocWithDictionarySet(allocator: std.mem.Allocator, stream: []const u8, offset: u64, length: usize, dictionary_set: NativeDictionarySet) Error![]u8 {
    try dictionary_set.validate();
    return decodeNativeSeekableRangeAllocInternal(allocator, stream, offset, length, .{ .set = dictionary_set });
}

pub fn decodeNativeSeekableRangeAllocWithIndex(allocator: std.mem.Allocator, index: NativeSeekIndex, offset: u64, length: usize) Error![]u8 {
    return decodeNativeSeekableRangeAllocWithIndexInternal(allocator, index, offset, length, .none);
}

pub fn decodeNativeSeekableRangeAllocWithIndexAndDictionary(allocator: std.mem.Allocator, index: NativeSeekIndex, offset: u64, length: usize, dictionary: NativeDictionary) Error![]u8 {
    return decodeNativeSeekableRangeAllocWithIndexInternal(allocator, index, offset, length, .{ .explicit = dictionary });
}

pub fn decodeNativeSeekableRangeAllocWithIndexAndDictionarySet(allocator: std.mem.Allocator, index: NativeSeekIndex, offset: u64, length: usize, dictionary_set: NativeDictionarySet) Error![]u8 {
    try dictionary_set.validate();
    return decodeNativeSeekableRangeAllocWithIndexInternal(allocator, index, offset, length, .{ .set = dictionary_set });
}

fn decodeNativeSeekableRangeAllocInternal(allocator: std.mem.Allocator, stream: []const u8, offset: u64, length: usize, dictionary_resolver: NativeSeekableDictionaryResolver) Error![]u8 {
    const table = try inspectNativeSeekTable(stream);
    const scratch_len = try nativeSeekableRangeScratchLen(table, offset, length);
    const output = try allocator.alloc(u8, length);
    errdefer allocator.free(output);
    const scratch = try allocator.alloc(u8, scratch_len);
    defer allocator.free(scratch);
    _ = try decodeNativeSeekableRangeIntoInternal(stream, offset, output, scratch, dictionary_resolver);
    return output;
}

fn decodeNativeSeekableRangeAllocWithIndexInternal(allocator: std.mem.Allocator, index: NativeSeekIndex, offset: u64, length: usize, dictionary_resolver: NativeSeekableDictionaryResolver) Error![]u8 {
    const range = try prepareNativeSeekableIndexedRange(index, offset, length);
    const output = try allocator.alloc(u8, length);
    errdefer allocator.free(output);
    const scratch = try allocator.alloc(u8, range.scratch_len);
    defer allocator.free(scratch);
    _ = try decodeNativeSeekablePreparedRangeInto(index, range, offset, output, scratch, dictionary_resolver);
    return output;
}

pub fn summarizeNativeStream(frames: []const u8) Error!NativeStreamSummary {
    var diagnostics: NativeStreamSummaryErrorDiagnostics = .{};
    return summarizeNativeStreamWithDiagnostics(frames, &diagnostics);
}

pub fn summarizeNativeStreamWithDiagnostics(frames: []const u8, diagnostics: *NativeStreamSummaryErrorDiagnostics) Error!NativeStreamSummary {
    return try summarizeNativeStreamInternal(frames, null, diagnostics);
}

pub fn summarizeNativeStreamWithDictionarySet(frames: []const u8, dictionary_set: NativeDictionarySet) Error!NativeStreamSummary {
    var diagnostics: NativeStreamSummaryErrorDiagnostics = .{};
    return try summarizeNativeStreamWithDictionarySetAndDiagnostics(frames, dictionary_set, &diagnostics);
}

pub fn summarizeNativeStreamWithDictionary(frames: []const u8, dictionary: NativeDictionary) Error!NativeStreamSummary {
    if (dictionary.id == 0) return try summarizeNativeStream(frames);
    return try summarizeNativeStreamWithDictionarySet(frames, NativeDictionarySet.init(&.{dictionary}));
}

pub fn summarizeNativeStreamWithDictionaryDiagnostics(frames: []const u8, dictionary: NativeDictionary, diagnostics: *NativeStreamSummaryErrorDiagnostics) Error!NativeStreamSummary {
    if (dictionary.id == 0) return try summarizeNativeStreamWithDiagnostics(frames, diagnostics);
    return try summarizeNativeStreamWithDictionarySetAndDiagnostics(frames, NativeDictionarySet.init(&.{dictionary}), diagnostics);
}

pub fn summarizeNativeStreamWithDictionarySetAndDiagnostics(frames: []const u8, dictionary_set: NativeDictionarySet, diagnostics: *NativeStreamSummaryErrorDiagnostics) Error!NativeStreamSummary {
    // Match dictionary-set codec entry points: unchecked static catalogs are
    // accepted by `init`, but every consuming API rejects zero and duplicate
    // IDs before selecting a frame dictionary. Without this validation, the
    // first duplicate silently won and summary metadata could disagree with
    // the dictionary the decoder was permitted to consume.
    dictionary_set.validate() catch |err| {
        diagnostics.* = .{ .phase = .stream, .offset = 0 };
        return err;
    };
    return try summarizeNativeStreamInternal(frames, dictionary_set, diagnostics);
}

fn summarizeNativeStreamInternal(frames: []const u8, dictionary_set: ?NativeDictionarySet, diagnostics: *NativeStreamSummaryErrorDiagnostics) Error!NativeStreamSummary {
    diagnostics.* = .{};
    var offset: usize = 0;
    var summary: NativeStreamSummary = .{};
    while (offset < frames.len) {
        if (frames.len - offset < 4) {
            diagnostics.* = .{ .phase = .magic, .offset = frames.len };
            return error.TruncatedFrame;
        }
        const magic_offset = offset;
        const magic = std.mem.readInt(u32, frames[offset..][0..4], .little);
        offset += 4;
        if (magic == frame_magic_u32) {
            const frame_start = offset - 4;
            const header = parseRawOrRleFrameHeaderWithOptions(frames, &offset, true) catch |err| {
                diagnostics.* = .{ .phase = .frame_header, .offset = frames.len };
                return err;
            };
            if (header.has_checksum) summary.checksum_frame_count += 1;
            if (header.dictionary_id != 0) {
                summary.dictionary_id_frame_count += 1;
                if (dictionary_set) |set| {
                    const dictionary = set.find(header.dictionary_id) orelse {
                        diagnostics.* = .{ .phase = .frame_header, .offset = frame_start };
                        return error.NeedDictionary;
                    };
                    summary.resolved_dictionary_frame_count += 1;
                    summary.standard_dictionary_frame_count += @intFromBool(dictionary.kind() == .standard_full);
                }
            }
            if (header.content_size) |content_size| {
                summary.content_size_frame_count += 1;
                summary.declared_content_bytes = std.math.add(u64, summary.declared_content_bytes, content_size) catch return error.IntegerOverflow;
            }
            while (true) {
                const block = inspectNativeFrameBlockAtWithDiagnostics(frames[frame_start..], frame_start, offset - frame_start, diagnostics) catch |err| {
                    return err;
                };
                summary.block_count += 1;
                switch (block.block_type) {
                    .raw => summary.raw_block_count += 1,
                    .rle => summary.rle_block_count += 1,
                    .compressed => summary.compressed_block_count += 1,
                }
                summary.payload_bytes = std.math.add(usize, summary.payload_bytes, block.payload_len) catch return error.IntegerOverflow;
                offset = frame_start + block.next_header_offset;
                if (block.last) break;
            }
            if (header.has_checksum) {
                if (frames.len - offset < 4) {
                    diagnostics.* = .{ .phase = .frame_checksum, .offset = frames.len };
                    return error.TruncatedFrame;
                }
                offset += 4;
            }
            summary.frame_count += 1;
        } else if (magic >= skippable_magic_min and magic <= skippable_magic_max) {
            if (frames.len - offset < 4) {
                diagnostics.* = .{ .phase = .skippable_header, .offset = frames.len };
                return error.TruncatedFrame;
            }
            const skip_len: usize = @intCast(std.mem.readInt(u32, frames[offset..][0..4], .little));
            offset += 4;
            if (frames.len - offset < skip_len) {
                diagnostics.* = .{ .phase = .skippable_payload, .offset = frames.len };
                return error.TruncatedFrame;
            }
            summary.skippable_frame_count += 1;
            summary.skippable_payload_bytes = std.math.add(usize, summary.skippable_payload_bytes, skip_len) catch return error.IntegerOverflow;
            offset += skip_len;
        } else {
            diagnostics.* = .{ .phase = .magic, .offset = magic_offset };
            return error.InvalidMagic;
        }
    }
    return summary;
}

fn inspectNativeFrameBlockAtWithDiagnostics(frame: []const u8, frame_start: usize, header_offset: usize, diagnostics: *NativeStreamSummaryErrorDiagnostics) Error!NativeFrameBlockHeader {
    const header = inspectNativeFrameHeader(frame) catch |err| {
        diagnostics.* = .{ .phase = .frame_header, .offset = frame_start + frame.len };
        return err;
    };
    if (header_offset < header.payload_offset) {
        diagnostics.* = .{ .phase = .frame, .offset = frame_start + header_offset };
        return error.CorruptFrame;
    }
    if (frame.len - header_offset < 3) {
        diagnostics.* = .{ .phase = .frame_body, .offset = frame_start + frame.len };
        return error.TruncatedFrame;
    }
    const block_header = std.mem.readInt(u24, frame[header_offset..][0..3], .little);
    const block_type_raw = (block_header >> 1) & 0x03;
    const payload_len: usize = @intCast(block_header >> 3);
    const block_type: NativeBlockType = switch (block_type_raw) {
        0 => .raw,
        1 => .rle,
        2 => .compressed,
        else => {
            diagnostics.* = .{ .phase = .frame, .offset = frame_start + header_offset };
            return error.CorruptFrame;
        },
    };
    validateBlockSize(header, block_type_raw, payload_len) catch |err| {
        diagnostics.* = .{ .phase = .frame, .offset = frame_start + header_offset };
        return err;
    };
    const payload_offset = header_offset + 3;
    const required_payload_len: usize = if (block_type == .rle) 1 else payload_len;
    if (frame.len - payload_offset < required_payload_len) {
        diagnostics.* = .{ .phase = .frame_body, .offset = frame_start + frame.len };
        return error.TruncatedFrame;
    }
    return .{
        .header_offset = header_offset,
        .payload_offset = payload_offset,
        .payload_len = payload_len,
        .block_type = block_type,
        .last = (block_header & 1) != 0,
        .next_header_offset = payload_offset + required_payload_len,
    };
}

fn nativeSummaryFrameErrorPhase(err: anyerror) NativeStreamSummaryErrorPhase {
    return switch (err) {
        error.TruncatedFrame => .frame_body,
        else => .frame,
    };
}

fn findNativeFrameEnd(frames: []const u8, frame_start: usize) Error!usize {
    if (frame_start > frames.len) return error.TruncatedFrame;
    if (frames.len - frame_start < 4) return error.TruncatedFrame;
    if (std.mem.readInt(u32, frames[frame_start..][0..4], .little) != frame_magic_u32) return error.InvalidMagic;

    var offset = frame_start + 4;
    const header = try parseRawOrRleFrameHeaderWithOptions(frames, &offset, true);
    while (true) {
        const block = try inspectNativeFrameBlockAt(frames[frame_start..], offset - frame_start);
        offset = frame_start + block.next_header_offset;
        if (block.last) break;
    }
    if (header.has_checksum) {
        if (frames.len - offset < 4) return error.TruncatedFrame;
        offset += 4;
    }
    return offset;
}

fn decodeWindowSize(descriptor: u8) u64 {
    const exponent = (descriptor & 0b1111_1000) >> 3;
    const mantissa = descriptor & 0b0000_0111;
    const window_log = 10 + @as(u6, @intCast(exponent));
    const window_base = @as(u64, 1) << window_log;
    return window_base + (window_base / 8) * mantissa;
}

fn readU64Field(frame: []const u8, offset: *usize, field_size: usize) Error!u64 {
    if (frame.len - offset.* < field_size) return error.TruncatedFrame;
    var value: u64 = 0;
    for (frame[offset.*..][0..field_size], 0..) |byte, i| {
        value |= @as(u64, byte) << @as(u6, @intCast(i * 8));
    }
    offset.* += field_size;
    return value;
}

fn rleByte(block: []const u8) ?u8 {
    if (block.len < 2) return null;
    const first = block[0];
    for (block[1..]) |byte| {
        if (byte != first) return null;
    }
    return first;
}

const RleRun = struct {
    start: usize,
    len: usize,
};

fn findRleRun(block: []const u8) ?RleRun {
    var i: usize = 0;
    while (i < block.len) {
        const len = sameByteRunLen(block, i);
        if (len >= min_rle_split_len) return .{ .start = i, .len = len };
        i += @max(len, 1);
    }
    return null;
}

fn sameByteRunLen(block: []const u8, start: usize) usize {
    const byte = block[start];
    var end = start + 1;
    while (end < block.len and block[end] == byte) : (end += 1) {}
    return end - start;
}

fn emitBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool) Error!void {
    if (rleByte(block)) |byte| return try emitRleBlock(allocator, out, byte, block.len, last);
    return try emitRawBlock(allocator, out, block, last);
}

fn emitLiteralOnlyCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, state: *LiteralOnlyEncoderState) Error!void {
    return try emitLiteralOnlyCompressedBlockWithDictionary(allocator, out, block, last, state, null, 0, mixed_match_path_search_budget, false, null);
}

fn emitLiteralOnlyCompressedBlockWithDictionary(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    state: *LiteralOnlyEncoderState,
    dictionary: ?NativeDictionary,
    frame_offset: usize,
    match_search_budget: usize,
    rep_beam_search: bool,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
) Error!void {
    return try emitLiteralOnlyCompressedBlockWithHistory(
        allocator,
        out,
        block,
        last,
        state,
        dictionary,
        emptyIncrementalHistoryView(),
        frame_offset,
        match_search_budget,
        rep_beam_search,
        rep_beam_scratch,
    );
}

fn emptyIncrementalHistoryView() incremental_history.View {
    const Empty = struct {
        var index: incremental_history_index.Index = .{};
    };
    return .{ .bytes = &.{}, .absolute_start = 0, .index = &Empty.index };
}

fn emitLiteralOnlyCompressedBlockWithHistory(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    state: *LiteralOnlyEncoderState,
    dictionary: ?NativeDictionary,
    frame_history: incremental_history.View,
    frame_offset: usize,
    match_search_budget: usize,
    rep_beam_search: bool,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
) Error!void {
    return try emitLiteralOnlyCompressedBlockWithHistoryAndScratch(
        allocator,
        out,
        block,
        last,
        state,
        dictionary,
        frame_history,
        frame_offset,
        match_search_budget,
        rep_beam_search,
        rep_beam_scratch,
        null,
    );
}

fn emitLiteralOnlyCompressedBlockWithHistoryAndScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    state: *LiteralOnlyEncoderState,
    dictionary: ?NativeDictionary,
    frame_history: incremental_history.View,
    frame_offset: usize,
    match_search_budget: usize,
    rep_beam_search: bool,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
    large_sequence_scratch: ?*LargeSequenceScratch,
) Error!void {
    return try emitLiteralOnlyCompressedBlockWithHistoryAndScratchImpl(
        true,
        allocator,
        out,
        block,
        last,
        state,
        dictionary,
        frame_history,
        frame_offset,
        match_search_budget,
        rep_beam_search,
        rep_beam_scratch,
        large_sequence_scratch,
        null,
    );
}

const NativeBlockEncodeScratch = struct {
    candidate: std.ArrayList(u8) = .empty,
    best: std.ArrayList(u8) = .empty,
    match_candidate: std.ArrayList(u8) = .empty,
    match_best: std.ArrayList(u8) = .empty,
    greedy_tokens: std.ArrayList(lz77.Token) = .empty,
    lazy_tokens: std.ArrayList(lz77.Token) = .empty,
    optimal: lz77.OptimalScratch = .{},
    single_sequence_emit: SingleSequenceEmitScratch = .{},

    fn clearRetainingCapacity(self: *NativeBlockEncodeScratch) void {
        self.candidate.clearRetainingCapacity();
        self.best.clearRetainingCapacity();
    }

    fn clearMatchRetainingCapacity(self: *NativeBlockEncodeScratch) void {
        self.match_candidate.clearRetainingCapacity();
        self.match_best.clearRetainingCapacity();
        self.greedy_tokens.clearRetainingCapacity();
        self.lazy_tokens.clearRetainingCapacity();
        self.single_sequence_emit.repeated_prune_best_len = 0;
        self.single_sequence_emit.repeated_prune_max_byte_frequency = 0;
    }

    fn deinit(self: *NativeBlockEncodeScratch, allocator: std.mem.Allocator) void {
        self.single_sequence_emit.deinit(allocator);
        self.optimal.deinit(allocator);
        self.lazy_tokens.deinit(allocator);
        self.greedy_tokens.deinit(allocator);
        self.match_best.deinit(allocator);
        self.match_candidate.deinit(allocator);
        self.best.deinit(allocator);
        self.candidate.deinit(allocator);
        self.* = .{};
    }
};

const reusable_hash_token_initial_capacity = 64;

fn ensureReusableHashTokenCapacity(tokens: *std.ArrayList(lz77.Token), allocator: std.mem.Allocator, block_len: usize) Error!void {
    try tokens.ensureTotalCapacityPrecise(allocator, @min(block_len, reusable_hash_token_initial_capacity));
}

const SingleSequenceEmitScratch = struct {
    literals_prefix: std.ArrayList(u8) = .empty,
    payload: std.ArrayList(u8) = .empty,
    sequence_bits: std.ArrayList(u8) = .empty,
    repeated_prune_best_len: usize = 0,
    repeated_prune_max_byte_frequency: u16 = 0,

    fn clearRetainingCapacity(self: *SingleSequenceEmitScratch) void {
        self.literals_prefix.clearRetainingCapacity();
        self.payload.clearRetainingCapacity();
        self.sequence_bits.clearRetainingCapacity();
    }

    fn deinit(self: *SingleSequenceEmitScratch, allocator: std.mem.Allocator) void {
        self.sequence_bits.deinit(allocator);
        self.payload.deinit(allocator);
        self.literals_prefix.deinit(allocator);
        self.* = .{};
    }
};

fn emitLiteralOnlyCompressedBlockWithHistoryAndScratchImpl(
    comptime enable_decisive_history: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    state: *LiteralOnlyEncoderState,
    dictionary: ?NativeDictionary,
    frame_history: incremental_history.View,
    frame_offset: usize,
    match_search_budget: usize,
    rep_beam_search: bool,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) Error!void {
    try ensureEncoderSequenceState(state, dictionary);
    const CandidateKind = enum { dictionary, history, huffman, match };
    var local_block_scratch: NativeBlockEncodeScratch = .{};
    defer if (block_scratch == null) local_block_scratch.deinit(allocator);
    const scratch = block_scratch orelse &local_block_scratch;
    scratch.clearRetainingCapacity();
    const candidate = &scratch.candidate;
    const best = &scratch.best;
    var best_kind: ?CandidateKind = null;
    var match_tested = false;

    const dictionary_ok = if (dictionary) |dict|
        try emitDictionaryMatchCompressedBlock(allocator, candidate, block, last, dict, frame_offset, match_search_budget)
    else
        false;
    const dictionary_ready = dictionary_ok and try prepareSequenceCandidateForFrameWithScratch(allocator, candidate, block, last, &state.sequence_state, large_sequence_scratch);
    if (dictionary_ready) {
        try best.appendSlice(allocator, candidate.items);
        best_kind = .dictionary;
    }

    candidate.clearRetainingCapacity();
    // The history planner already owns the decoded sequence values. Emit them
    // against the current frame state directly instead of first serializing
    // with the initial tables/repcodes and then decoding that temporary block
    // only to serialize the same sequence list again.
    const history_ready = try emitFrameHistoryMatchCompressedBlock(
        allocator,
        candidate,
        block,
        last,
        frame_history,
        &state.sequence_state,
    );
    if (history_ready and (best_kind == null or candidate.items.len < best.items.len)) {
        best.clearRetainingCapacity();
        try best.appendSlice(allocator, candidate.items);
        best_kind = .history;
        // An almost-complete history copy is decisive without further shape
        // checks. A broader speed shortcut is restricted to wide alphabets
        // without a long periodic segment; narrow/periodic blocks can still be
        // improved materially by the local repeated-match family.
        if (enable_decisive_history and dictionary == null and decisiveHistoryCandidate(block, candidate.items.len)) {
            state.previous_huffman_plan = null;
            try appendSequenceCandidateAndCommit(allocator, out, candidate.items, last, &state.sequence_state);
            return;
        }
        if (enable_decisive_history and dictionary == null and
            candidate.items.len <= block.len / decisive_wide_history_ratio and decisiveWideHistoryBlock(block))
        {
            state.previous_huffman_plan = null;
            try appendSequenceCandidateAndCommit(allocator, out, candidate.items, last, &state.sequence_state);
            return;
        }
    }

    if (best_kind == null and rep_beam_search and rleByte(block) == null) {
        candidate.clearRetainingCapacity();
        var match_state_applied = false;
        const match_ok = if (shouldProbeDecisiveWideMatch(block, match_search_budget, true)) blk: {
            break :blk try emitNativeMatchCompressedBlockWithWideProbeForFrame(allocator, candidate, block, last, match_search_budget, rep_beam_scratch, &state.sequence_state, &match_state_applied, large_sequence_scratch);
        } else try emitNativeMatchCompressedBlockWithScratch(allocator, candidate, block, last, match_search_budget, true, rep_beam_scratch, large_sequence_scratch, scratch);
        const match_ready = match_ok and (match_state_applied or try prepareSequenceCandidateForFrameWithScratch(allocator, candidate, block, last, &state.sequence_state, large_sequence_scratch));
        match_tested = true;
        if (match_ready) {
            // A literal-only prefix code needs at least one bit for every input
            // byte when the block is not RLE. The match candidate includes its
            // block/section headers, so meeting this lower bound proves that no
            // raw, RLE, or Huffman-only candidate can tie or beat it.
            if (candidate.items.len <= block.len / 8) {
                state.previous_huffman_plan = null;
                try appendSequenceCandidateAndCommit(allocator, out, candidate.items, last, &state.sequence_state);
                return;
            }
            try best.appendSlice(allocator, candidate.items);
            best_kind = .match;
        }
    }

    var huffman_plan = state.previous_huffman_plan;
    candidate.clearRetainingCapacity();
    const huffman_ok = try emitSmallHuffmanLiteralBlock(allocator, candidate, block, last, &huffman_plan);
    // Preserve the historical Huffman-on-equal tie preference.
    if (huffman_ok and (best_kind == null or candidate.items.len <= best.items.len)) {
        best.clearRetainingCapacity();
        try best.appendSlice(allocator, candidate.items);
        best_kind = .huffman;
    }

    if (!match_tested) {
        candidate.clearRetainingCapacity();
        const match_ok = try emitNativeMatchCompressedBlockWithScratch(allocator, candidate, block, last, match_search_budget, rep_beam_search, rep_beam_scratch, large_sequence_scratch, scratch);
        const match_ready = match_ok and try prepareSequenceCandidateForFrameWithScratch(allocator, candidate, block, last, &state.sequence_state, large_sequence_scratch);
        if (match_ready and (best_kind == null or candidate.items.len < best.items.len)) {
            best.clearRetainingCapacity();
            try best.appendSlice(allocator, candidate.items);
            best_kind = .match;
        }
    }

    if (best_kind) |kind| switch (kind) {
        .dictionary => {
            state.previous_huffman_plan = null;
            try appendSequenceCandidateAndCommit(allocator, out, best.items, last, &state.sequence_state);
            return;
        },
        .history => {
            state.previous_huffman_plan = null;
            try appendSequenceCandidateAndCommit(allocator, out, best.items, last, &state.sequence_state);
            return;
        },
        .huffman => {
            try out.appendSlice(allocator, best.items);
            state.previous_huffman_plan = huffman_plan;
            return;
        },
        .match => {
            state.previous_huffman_plan = null;
            try appendSequenceCandidateAndCommit(allocator, out, best.items, last, &state.sequence_state);
            return;
        },
    };

    const literal_kind: LiteralsKind = if (rleByte(block) != null) .rle else .raw;
    const literal_payload_len: usize = switch (literal_kind) {
        .raw => block.len,
        .rle => 1,
        .compressed, .treeless => unreachable,
    };
    const header_len = try literalsHeaderLen(block.len);
    const payload_prefix_len = std.math.add(usize, header_len, literal_payload_len) catch return error.IntegerOverflow;
    const payload_len = std.math.add(
        usize,
        payload_prefix_len,
        1, // sequence_count=0: the compressed block is literals-only.
    ) catch return error.IntegerOverflow;
    // The reference encoder avoids compressed blocks when entropy/literal
    // section headers erase the size win. Requiring an actual size reduction
    // also sidesteps deployed zstd CLI/lib builds that reject some
    // sequence-free compressed blocks once Block_Size exceeds the regenerated
    // block size.
    if (payload_len >= block.len) return try emitBlock(allocator, out, block, last);

    candidate.clearRetainingCapacity();
    const payload = candidate;
    if (literal_kind == .rle) {
        try emitLiteralsHeader(allocator, payload, .rle, block.len);
        try payload.append(allocator, block[0]);
    } else {
        try emitLiteralsHeader(allocator, payload, .raw, block.len);
        try payload.appendSlice(allocator, block);
    }
    try payload.append(allocator, 0); // sequence_count=0: the compressed block is literals-only.
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
}

fn emitFastCompressedBlockWithScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    state: *LiteralOnlyEncoderState,
    dictionary: ?NativeDictionary,
    large_sequence_scratch: *LargeSequenceScratch,
    scratch: *NativeBlockEncodeScratch,
) Error!void {
    try ensureEncoderSequenceState(state, dictionary);
    if (rleByte(block)) |byte| {
        try emitRleBlock(allocator, out, byte, block.len, last);
        return;
    }
    scratch.clearRetainingCapacity();
    const candidate = &scratch.candidate;
    const best = &scratch.best;
    var best_is_match = false;

    if (findPrefixTailDuplicateMatch(block)) |match| {
        const literal_lens = [_]usize{match.second_start};
        const offsets = [_]usize{match.second_start - match.first_start};
        const match_lens = [_]usize{match.len};
        const literal_ends = [_]usize{match.second_start + match.len};
        if (try emitBestSequenceCompressedBlockWithScratch(
            allocator,
            candidate,
            block,
            last,
            &literal_lens,
            &offsets,
            &match_lens,
            &literal_ends,
            literal_ends[0],
            &scratch.single_sequence_emit,
        ) and
            try prepareSequenceCandidateForFrameWithScratch(allocator, candidate, block, last, &state.sequence_state, large_sequence_scratch))
        {
            if (candidate.items.len <= block.len / 8) {
                state.previous_huffman_plan = null;
                try appendSequenceCandidateAndCommit(allocator, out, candidate.items, last, &state.sequence_state);
                return;
            }
            try best.appendSlice(allocator, candidate.items);
            best_is_match = true;
        }
    }

    candidate.clearRetainingCapacity();
    const match_result = try emitFastMatchCandidate(allocator, candidate, block, last, large_sequence_scratch, scratch);
    const match_ok = match_result.match_ok;
    const use_fast_large_planner = match_result.use_fast_large_planner;
    if (comptime builtin.is_test) {
        test_fast_large_direct_transition_hits += @intFromBool(match_ok and use_fast_large_planner and !test_disable_fast_large_direct_transitions);
        test_fast_large_cached_planner_hits += @intFromBool(match_ok and use_fast_large_planner and !test_disable_fast_large_cached_planner);
        test_fast_sequence_record_hits += @intFromBool(match_ok and match_result.used_sequence_records and use_fast_large_planner);
    }
    const match_ready = match_ok and try prepareSequenceCandidateForFrameWithScratch(
        allocator,
        candidate,
        block,
        last,
        &state.sequence_state,
        large_sequence_scratch,
    );
    if (match_ready and (best.items.len == 0 or candidate.items.len < best.items.len)) {
        if (!builtin.is_test or !test_disable_fast_direct_match_commit) {
            if (comptime builtin.is_test) test_fast_direct_match_commit_hits += 1;
            state.previous_huffman_plan = null;
            const can_commit_known_offsets = !last and
                match_ok and use_fast_large_planner and
                dictionary == null and
                state.sequence_state.previous_tables == null and
                std.meta.eql(state.sequence_state.repeated_offsets, initial_repeated_offsets) and
                (!builtin.is_test or !test_disable_fast_large_known_offsets_commit);
            if (can_commit_known_offsets) {
                if (comptime builtin.is_test) test_fast_large_known_offsets_commit_hits += 1;
                try appendSequenceCandidateAndCommitKnownOffsets(
                    allocator,
                    out,
                    candidate.items,
                    &state.sequence_state,
                    large_sequence_scratch.offset_extras.items[0..3].*,
                );
            } else {
                try appendSequenceCandidateAndCommit(allocator, out, candidate.items, last, &state.sequence_state);
            }
            return;
        }
        best.clearRetainingCapacity();
        try best.appendSlice(allocator, candidate.items);
        best_is_match = true;
    }
    if (best_is_match) {
        state.previous_huffman_plan = null;
        try appendSequenceCandidateAndCommit(allocator, out, best.items, last, &state.sequence_state);
        return;
    }

    candidate.clearRetainingCapacity();
    var next_huffman_plan = state.previous_huffman_plan;
    const huffman_ok = try emitSmallHuffmanLiteralBlock(allocator, candidate, block, last, &next_huffman_plan);
    if (huffman_ok and (best.items.len == 0 or candidate.items.len <= best.items.len)) {
        try out.appendSlice(allocator, candidate.items);
        state.previous_huffman_plan = next_huffman_plan;
        return;
    }
    if (huffman_ok) {
        try out.appendSlice(allocator, candidate.items);
        state.previous_huffman_plan = next_huffman_plan;
        return;
    }
    try emitBlock(allocator, out, block, last);
}

inline fn decisiveHistoryCandidate(block: []const u8, encoded_len: usize) bool {
    return rleByte(block) == null and encoded_len <= block.len / decisive_history_ratio;
}

noinline fn decisiveWideHistoryBlock(block: []const u8) bool {
    if (rleByte(block) != null or preferSerialMixedSearch(block)) return false;
    if (findRepeatedPatternSegment(block)) |pattern|
        return pattern.match_len < 16;
    return true;
}

fn emitNativeMatchCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match_search_budget: usize, rep_beam_search: bool, rep_beam_scratch: ?*lz77.RepBeamScratch) Error!bool {
    return try emitNativeMatchCompressedBlockWithSequenceScratch(allocator, out, block, last, match_search_budget, rep_beam_search, rep_beam_scratch, null);
}

fn emitNativeMatchCompressedBlockWithSequenceScratch(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match_search_budget: usize, rep_beam_search: bool, rep_beam_scratch: ?*lz77.RepBeamScratch, large_sequence_scratch: ?*LargeSequenceScratch) Error!bool {
    return try emitNativeMatchCompressedBlockWithScratch(allocator, out, block, last, match_search_budget, rep_beam_search, rep_beam_scratch, large_sequence_scratch, null);
}

fn emitNativeMatchCompressedBlockWithScratch(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match_search_budget: usize, rep_beam_search: bool, rep_beam_scratch: ?*lz77.RepBeamScratch, large_sequence_scratch: ?*LargeSequenceScratch, block_scratch: ?*NativeBlockEncodeScratch) Error!bool {
    return try emitNativeMatchCompressedBlockImpl(false, allocator, out, block, last, match_search_budget, rep_beam_search, rep_beam_scratch, undefined, large_sequence_scratch, block_scratch);
}

fn emitNativeMatchCompressedBlockWithPrecomputedBeam(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match_search_budget: usize, rep_beam_scratch: *lz77.RepBeamScratch, rep_beam_stats: lz77.PlanStats) Error!bool {
    return try emitNativeMatchCompressedBlockImpl(true, allocator, out, block, last, match_search_budget, true, rep_beam_scratch, rep_beam_stats, null, null);
}

fn emitNativeMatchCompressedBlockImpl(
    comptime has_precomputed_rep_beam: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    rep_beam_search: bool,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
    precomputed_rep_beam_stats: lz77.PlanStats,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) Error!bool {
    if (match_search_budget == 0) return false;
    // A prefix repeated through the end is already represented by one
    // sequence. Ratio levels retain the measured 32x cutoff; lower levels use
    // a deliberately stricter 256x cutoff so only overwhelmingly decisive
    // large-block results bypass their normal candidate arbitration.
    if (rep_beam_search or block.len > 8 * 1024) {
        if (findPrefixTailDuplicateMatch(block)) |match| {
            var candidate: std.ArrayList(u8) = .empty;
            defer candidate.deinit(allocator);
            const decisive_ratio: usize = if (rep_beam_search) 32 else 256;
            if (try emitSingleMatchCompressedBlockFromMatch(allocator, &candidate, block, last, match) and
                candidate.items.len <= block.len / decisive_ratio)
            {
                try out.appendSlice(allocator, candidate.items);
                return true;
            }
        }
    }
    if (match_search_budget >= mixed_match_min_search_budget) {
        if (rep_beam_search and block.len >= serial_mixed_input_min and preferSerialMixedSearch(block)) {
            // Low-alphabet structured blocks make the repeat beam decisive in
            // the retained corpus. Evaluate the cheap bounded families first
            // so that proof can skip recursive mixed search without creating
            // and then joining a worker. Non-decisive blocks still run and
            // arbitrate the exact same mixed candidate below.
            const non_mixed_budget = mixed_match_min_search_budget - 1;
            var mixed_dominated = false;
            if (!has_precomputed_rep_beam) {
                if (try emitAbsoluteDecisiveBeamFirst(
                    allocator,
                    out,
                    block,
                    last,
                    non_mixed_budget,
                    rep_beam_scratch,
                    &mixed_dominated,
                    large_sequence_scratch,
                )) |fast_ok| return fast_ok;
            }
            const non_mixed_ok = try emitNativeMatchCompressedBlockSerialWithBeamDispatch(has_precomputed_rep_beam, true, allocator, out, block, last, non_mixed_budget, rep_beam_search, rep_beam_scratch, &mixed_dominated, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch);
            if (mixed_dominated) return non_mixed_ok;

            var mixed: std.ArrayList(u8) = .empty;
            defer mixed.deinit(allocator);
            const mixed_ok = try emitMixedDuplicateRepeatedMatchCompressedBlock(allocator, &mixed, block, last, match_search_budget, null, null);
            // Mixed historically ran first, so retain its equal-length tie.
            if (mixed_ok and (!non_mixed_ok or mixed.items.len <= out.items.len)) {
                out.clearRetainingCapacity();
                try out.appendSlice(allocator, mixed.items);
            }
            return out.items.len != 0;
        }

        var cancel_mixed: std.atomic.Value(bool) = .init(false);
        var mixed_candidate: MixedBlockCandidate = .{
            .block = block,
            .last = last,
            .match_search_budget = match_search_budget,
            .cancelled = &cancel_mixed,
        };
        // Wide-alphabet data is less likely to prove the mixed candidate
        // dominated. Preserve parallel arbitration there so the classifier
        // cannot serialize two expensive searches.
        if (std.Thread.spawn(.{}, MixedBlockCandidate.run, .{&mixed_candidate})) |thread| {
            const non_mixed_budget = mixed_match_min_search_budget - 1;
            var mixed_dominated = false;
            const non_mixed_ok = emitNativeMatchCompressedBlockSerialWithBeamDispatch(has_precomputed_rep_beam, true, allocator, out, block, last, non_mixed_budget, rep_beam_search, rep_beam_scratch, &mixed_dominated, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch) catch |err| {
                cancel_mixed.store(true, .release);
                thread.join();
                if (mixed_candidate.frame) |frame| std.heap.smp_allocator.free(frame);
                return err;
            };
            if (mixed_dominated) cancel_mixed.store(true, .release);
            thread.join();
            const mixed_cancelled = cancel_mixed.load(.acquire);
            if (mixed_candidate.err) |err| return err;
            if (mixed_candidate.frame) |mixed| {
                defer std.heap.smp_allocator.free(mixed);
                if (!mixed_cancelled and (!non_mixed_ok or mixed.len <= out.items.len)) {
                    out.clearRetainingCapacity();
                    try out.appendSlice(allocator, mixed);
                }
            }
            return out.items.len != 0;
        } else |_| {}
        // Thread creation is an optimization only. If the platform refuses a
        // worker, fall through to the byte-identical serial selector below.
    }
    return try emitNativeMatchCompressedBlockSerialWithBeamDispatch(has_precomputed_rep_beam, false, allocator, out, block, last, match_search_budget, rep_beam_search, rep_beam_scratch, null, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch);
}

noinline fn emitAbsoluteDecisiveBeamFirst(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
    mixed_dominated: *bool,
    large_sequence_scratch: ?*LargeSequenceScratch,
) linksection(fast_encode_helper_text_section) Error!?bool {
    if (match_search_budget != mixed_match_min_search_budget - 1 or
        block.len <= 32 * 1024 or block.len > duplicate_index_max_input_len) return null;

    var local_rep_beam: lz77.RepBeamScratch = .{};
    defer if (reusable_rep_beam == null) local_rep_beam.deinit(allocator);
    const beam_scratch = reusable_rep_beam orelse &local_rep_beam;
    const beam_stats = lz77.optimalRepBeamPlanZstdReuse(beam_scratch, allocator, block) catch |err| switch (err) {
        error.InvalidBlockPlan => return null,
        else => return err,
    };
    var local_sequence_scratch: LargeSequenceScratch = .{};
    defer if (large_sequence_scratch == null) local_sequence_scratch.deinit(allocator);
    const sequence_scratch = large_sequence_scratch orelse &local_sequence_scratch;
    var beam: std.ArrayList(u8) = .empty;
    defer beam.deinit(allocator);
    if (!try emitHashTokenSequenceBlockReuse(allocator, &beam, block, last, beam_scratch.reversed.items, beam_stats, sequence_scratch) or
        beam.items.len * 32 > block.len) return null;

    const parser_options = zstdHashParserOptions(block.len);
    const greedy = try lz77.hashGreedyPlanAutoTinyAlloc(allocator, block, parser_options);
    defer greedy.deinit(allocator);
    if (!try hashTokenSequenceCannotBeat(block, greedy.tokens, greedy.stats, beam.items.len)) return null;
    const lazy = try lz77.lazyGreedyPlanAlloc(allocator, block, parser_options);
    defer lazy.deinit(allocator);
    if (!try hashTokenSequenceCannotBeat(block, lazy.tokens, lazy.stats, beam.items.len)) return null;

    var repeated: std.ArrayList(u8) = .empty;
    defer repeated.deinit(allocator);
    const repeated_ok = try emitRepeatedPatternCompressedBlock(allocator, &repeated, block, last);
    if (repeated_ok and beam.items.len > repeated.items.len / decisive_mixed_dominance_ratio) return null;

    const dominance_limit = std.math.mul(usize, beam.items.len, decisive_mixed_dominance_ratio) catch std.math.maxInt(usize);
    if (!boundedSingleMatchDominatedBy(block, dominance_limit)) {
        var duplicate_index: DuplicateMatchIndex = undefined;
        duplicate_index.buildBounded(block);
        if (try findBestDuplicateMatchIndexed(block, 0, &duplicate_index) != null) return null;
    } else if (comptime builtin.is_test) test_decisive_single_lower_bound_hits += 1;

    mixed_dominated.* = true;
    try out.appendSlice(allocator, beam.items);
    return true;
}

inline fn shouldProbeDecisiveWideMatch(block: []const u8, match_search_budget: usize, rep_beam_search: bool) bool {
    return rep_beam_search and match_search_budget >= decisive_wide_match_min_search_budget and
        block.len >= serial_mixed_input_min and !preferSerialMixedSearch(block);
}

const WideMatchSpeedPolicy = enum { strict, fastest, fast };

inline fn wideMatchSpeedPolicy(match_search_budget: usize) WideMatchSpeedPolicy {
    return switch (match_search_budget) {
        fastest_wide_match_search_budget => .fastest,
        fast_wide_match_search_budget => .fast,
        else => .strict,
    };
}

inline fn acceptWideDoubleFastTradeoff(policy: WideMatchSpeedPolicy, encoded_len: usize, block_len: usize) bool {
    return switch (policy) {
        .strict => false,
        .fastest => encoded_len * 15 <= block_len * 4,
        .fast => encoded_len * 16 <= block_len,
    };
}

noinline fn emitNativeMatchCompressedBlockWithWideProbe(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
) Error!bool {
    return try emitNativeMatchCompressedBlockWithWideProbeInternal(allocator, out, block, last, match_search_budget, rep_beam_scratch, null, null, null);
}

noinline fn emitNativeMatchCompressedBlockWithWideProbeForFrame(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
    sequence_state: *const SequenceEncoderState,
    state_applied: *bool,
    large_sequence_scratch: ?*LargeSequenceScratch,
) Error!bool {
    state_applied.* = false;
    return try emitNativeMatchCompressedBlockWithWideProbeInternal(allocator, out, block, last, match_search_budget, rep_beam_scratch, sequence_state, state_applied, large_sequence_scratch);
}

noinline fn emitNativeMatchCompressedBlockWithWideProbeInternal(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    rep_beam_scratch: ?*lz77.RepBeamScratch,
    sequence_state: ?*const SequenceEncoderState,
    state_applied: ?*bool,
    large_sequence_scratch: ?*LargeSequenceScratch,
) Error!bool {
    var local_rep_beam: lz77.RepBeamScratch = .{};
    defer if (rep_beam_scratch == null) local_rep_beam.deinit(allocator);
    const beam_scratch = rep_beam_scratch orelse &local_rep_beam;
    var rep_beam_stats: ?lz77.PlanStats = null;
    const speed_policy = wideMatchSpeedPolicy(match_search_budget);
    // Strict/ratio levels promise equivalence with complete arbitration under
    // the legacy first-pass wire. Speed levels already accept their documented
    // bounded tradeoff, so they can encode a decisive wide candidate directly
    // against the current frame state and avoid a decode/re-encode pass.
    const direct_sequence_state = if (speed_policy == .strict) null else sequence_state;
    if (try emitDecisiveWideMatchCompressedBlockInternal(
        allocator,
        out,
        block,
        last,
        speed_policy,
        beam_scratch,
        &rep_beam_stats,
        direct_sequence_state,
        state_applied,
        large_sequence_scratch,
    )) return true;
    if (rep_beam_stats) |stats|
        return try emitNativeMatchCompressedBlockImpl(true, allocator, out, block, last, match_search_budget, true, beam_scratch, stats, large_sequence_scratch, null);
    return try emitNativeMatchCompressedBlockWithSequenceScratch(allocator, out, block, last, match_search_budget, true, rep_beam_scratch, large_sequence_scratch);
}

noinline fn emitDecisiveWideMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    speed_policy: WideMatchSpeedPolicy,
    rep_beam: *lz77.RepBeamScratch,
    precomputed_rep_beam_stats: *?lz77.PlanStats,
) Error!bool {
    return try emitDecisiveWideMatchCompressedBlockInternal(allocator, out, block, last, speed_policy, rep_beam, precomputed_rep_beam_stats, null, null, null);
}

noinline fn emitDecisiveWideMatchCompressedBlockInternal(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    speed_policy: WideMatchSpeedPolicy,
    rep_beam: *lz77.RepBeamScratch,
    precomputed_rep_beam_stats: *?lz77.PlanStats,
    sequence_state: ?*const SequenceEncoderState,
    state_applied: ?*bool,
    large_sequence_scratch: ?*LargeSequenceScratch,
) Error!bool {
    const output_start = out.items.len;
    errdefer out.items.len = output_start;
    precomputed_rep_beam_stats.* = null;
    if (state_applied) |applied| applied.* = false;
    var double_fast_tokens: std.ArrayList(lz77.Token) = .empty;
    defer double_fast_tokens.deinit(allocator);
    const parser_options = zstdHashParserOptions(block.len);
    const double_fast_stats = double_fast_match.planReuse(&double_fast_tokens, allocator, block, parser_options) catch |err| switch (err) {
        error.InvalidBlockPlan => return false,
        else => return err,
    };
    if (!try emitHashTokenSequenceBlockReuseForFrame(allocator, out, block, last, double_fast_tokens.items, double_fast_stats, large_sequence_scratch, sequence_state) or
        out.items.len - output_start > block.len / 3)
    {
        out.items.len = output_start;
        return false;
    }
    const direct_state_applied = sequence_state != null and double_fast_stats.matches > max_native_sequence_count;
    if (acceptWideDoubleFastTradeoff(speed_policy, out.items.len - output_start, block.len)) {
        if (state_applied) |applied| applied.* = direct_state_applied;
        return true;
    }

    const rep_beam_stats = lz77.optimalRepBeamPlanZstdReuse(rep_beam, allocator, block) catch |err| switch (err) {
        error.InvalidBlockPlan => {
            out.items.len = output_start;
            return false;
        },
        else => return err,
    };
    precomputed_rep_beam_stats.* = rep_beam_stats;
    if (!std.meta.eql(double_fast_stats, rep_beam_stats) or
        !nativeMatchTokenSlicesEqual(double_fast_tokens.items, rep_beam.reversed.items))
    {
        out.items.len = output_start;
        return false;
    }

    if (state_applied) |applied| applied.* = direct_state_applied;
    return true;
}

fn nativeMatchTokenSlicesEqual(a: []const lz77.Token, b: []const lz77.Token) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| switch (left) {
        .literal => |literal| switch (right) {
            .literal => |other| if (literal != other) return false,
            .match => return false,
        },
        .match => |match| switch (right) {
            .literal => return false,
            .match => |other| if (match.length != other.length or match.distance != other.distance) return false,
        },
    };
    return true;
}

fn preferSerialMixedSearch(block: []const u8) bool {
    var seen: [4]u64 = @splat(0);
    var distinct: usize = 0;
    // This is a scheduling hint, not a correctness predicate: both branches
    // perform the same exact arbitration. Four distributed windows distinguish
    // structured low-alphabet cases without adding a full input pass or being
    // fooled by an unrepresentative text prefix on otherwise binary data.
    const window_len = @min(block.len, serial_mixed_sample_window_len);
    const last_start = block.len - window_len;
    inline for (0..4) |window_index| {
        const start = window_index * last_start / 3;
        for (block[start..][0..window_len]) |byte| {
            const bit = @as(u64, 1) << @intCast(byte & 63);
            const word = &seen[byte >> 6];
            if (word.* & bit != 0) continue;
            word.* |= bit;
            distinct += 1;
            if (distinct > serial_mixed_distinct_symbol_max) return false;
        }
    }
    return true;
}

test "zstd mixed scheduling separates narrow and wide alphabets" {
    try std.testing.expect(preferSerialMixedSearch("structured JSON 0123456789" ** 32));
    var misleading_prefix: [serial_mixed_input_min]u8 = @splat('a');
    for (misleading_prefix[serial_mixed_sample_window_len..], 0..) |*byte, i| byte.* = @intCast(i & 63);
    try std.testing.expect(!preferSerialMixedSearch(&misleading_prefix));
    var wide: [serial_mixed_distinct_symbol_max + 1]u8 = undefined;
    for (&wide, 0..) |*byte, i| byte.* = @intCast(i);
    try std.testing.expect(!preferSerialMixedSearch(&wide));
}

fn findPrefixTailDuplicateMatch(block: []const u8) ?DuplicateMatch {
    if (block.len < 16) return null;
    const scan_end = @min(block.len / 2, 1024);
    var second: usize = 1;
    while (second + 8 <= scan_end) : (second += 1) {
        if (!std.mem.eql(u8, block[0..8], block[second..][0..8])) continue;
        const len = duplicateMatchLengthAfterAnchor(block, 0, second);
        if (len == block.len - second) {
            return .{ .first_start = 0, .second_start = second, .len = len };
        }
    }
    return null;
}

fn emitNativeMatchCompressedBlockSerialWithBeam(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match_search_budget: usize, enable_rep_beam: bool, reusable_rep_beam: ?*lz77.RepBeamScratch, mixed_dominated: ?*bool) Error!bool {
    if (mixed_dominated) |value|
        return try emitNativeMatchCompressedBlockSerialWithBeamDispatch(false, true, allocator, out, block, last, match_search_budget, enable_rep_beam, reusable_rep_beam, value, undefined, null, null);
    return try emitNativeMatchCompressedBlockSerialWithBeamDispatch(false, false, allocator, out, block, last, match_search_budget, enable_rep_beam, reusable_rep_beam, null, undefined, null, null);
}

fn emitNativeMatchCompressedBlockSerialWithTwoStateBeamReference(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
) Error!bool {
    return try emitNativeMatchCompressedBlockSerialWithBeamImpl(
        false,
        false,
        allocator,
        out,
        block,
        last,
        match_search_budget,
        true,
        reusable_rep_beam,
        null,
        undefined,
        null,
        null,
    );
}

fn emitNativeMatchCompressedBlockSerialWithDeepSingleBeamReference(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
) Error!bool {
    var beam_scratch: lz77.RepBeamScratch = .{};
    defer beam_scratch.deinit(allocator);
    var single_scratch: single_beam_match.Scratch = .{};
    defer single_scratch.deinit(allocator);
    const stats = single_beam_match.planDeepReferenceReuse(&single_scratch, allocator, block) catch |err| switch (err) {
        error.InvalidBlockPlan => return false,
        else => return err,
    };
    try beam_scratch.reversed.appendSlice(allocator, single_scratch.reversed.items);
    return try emitNativeMatchCompressedBlockSerialWithBeamImpl(
        true,
        false,
        allocator,
        out,
        block,
        last,
        match_search_budget,
        true,
        &beam_scratch,
        null,
        stats,
        null,
        null,
    );
}

inline fn emitNativeMatchCompressedBlockSerialWithBeamDispatch(
    comptime has_precomputed_rep_beam: bool,
    comptime prove_mixed_dominance: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    enable_rep_beam: bool,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
    mixed_dominated: ?*bool,
    precomputed_rep_beam_stats: lz77.PlanStats,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) Error!bool {
    if (match_search_budget == 0) return false;
    if (match_search_budget < multi_duplicate_min_search_budget)
        return try emitNativeMatchCompressedBlockSerialWithSingleStateBeam(has_precomputed_rep_beam, prove_mixed_dominance, allocator, out, block, last, match_search_budget, enable_rep_beam, reusable_rep_beam, mixed_dominated, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch);
    if (!has_precomputed_rep_beam and enable_rep_beam and shouldTryLevelThreeSingleBeam(block, match_search_budget))
        return try emitNativeMatchCompressedBlockSerialWithFastLevelThree(prove_mixed_dominance, allocator, out, block, last, match_search_budget, reusable_rep_beam, mixed_dominated, large_sequence_scratch, block_scratch);
    return try emitNativeMatchCompressedBlockSerialWithBeamImpl(has_precomputed_rep_beam, prove_mixed_dominance, allocator, out, block, last, match_search_budget, enable_rep_beam, reusable_rep_beam, mixed_dominated, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch);
}

inline fn shouldTryLevelThreeSingleBeam(block: []const u8, match_search_budget: usize) bool {
    return match_search_budget == fast_wide_match_search_budget and
        block.len > 32 * 1024 and
        preferSerialMixedSearch(block) and
        findPrefixTailDuplicateMatch(block) == null;
}

inline fn acceptLevelThreeSingleBeam(
    single_len: usize,
    single_fixed_bits: usize,
    double_fast_fixed_bits: usize,
    block_len: usize,
) bool {
    // Extremely small candidates leave enough absolute byte savings for the
    // two-state ratio parser to matter; keep it below the existing 1/128
    // decisive-history boundary. The moderate 1/32 band is the speed-policy
    // region where a clear fixed-cost win over double-fast can accept one-state
    // output without serializing a second complete entropy-coded block.
    return single_len > block_len / 128 and
        single_len <= block_len / 32 and
        single_fixed_bits <= double_fast_fixed_bits - double_fast_fixed_bits / 32;
}

noinline fn emitNativeMatchCompressedBlockSerialWithSingleStateBeam(
    comptime has_precomputed_rep_beam: bool,
    comptime prove_mixed_dominance: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    enable_rep_beam: bool,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
    mixed_dominated: ?*bool,
    precomputed_rep_beam_stats: lz77.PlanStats,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) linksection(fast_encode_helper_text_section) Error!bool {
    if (has_precomputed_rep_beam or !enable_rep_beam)
        return try emitNativeMatchCompressedBlockSerialWithBeamImpl(has_precomputed_rep_beam, prove_mixed_dominance, allocator, out, block, last, match_search_budget, enable_rep_beam, reusable_rep_beam, mixed_dominated, precomputed_rep_beam_stats, large_sequence_scratch, block_scratch);
    var local_rep_beam: lz77.RepBeamScratch = .{};
    defer if (reusable_rep_beam == null) local_rep_beam.deinit(allocator);
    const beam_scratch = reusable_rep_beam orelse &local_rep_beam;
    var single_scratch: single_beam_match.Scratch = .{};
    defer single_scratch.deinit(allocator);
    const single_stats = single_beam_match.planReuse(&single_scratch, allocator, block) catch |err| switch (err) {
        error.InvalidBlockPlan => return try emitNativeMatchCompressedBlockSerialWithBeamImpl(false, prove_mixed_dominance, allocator, out, block, last, match_search_budget, false, beam_scratch, mixed_dominated, undefined, large_sequence_scratch, block_scratch),
        else => return err,
    };
    beam_scratch.reversed.clearRetainingCapacity();
    try beam_scratch.reversed.appendSlice(allocator, single_scratch.reversed.items);
    return try emitNativeMatchCompressedBlockSerialWithBeamImpl(true, prove_mixed_dominance, allocator, out, block, last, match_search_budget, true, beam_scratch, mixed_dominated, single_stats, large_sequence_scratch, block_scratch);
}

noinline fn emitNativeMatchCompressedBlockSerialWithFastLevelThree(
    comptime prove_mixed_dominance: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
    mixed_dominated: ?*bool,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) linksection(fast_encode_helper_text_section) Error!bool {
    const output_start = out.items.len;
    errdefer out.items.len = output_start;
    {
        var single_scratch: single_beam_match.Scratch = .{};
        defer single_scratch.deinit(allocator);
        const single_stats = single_beam_match.planReuse(&single_scratch, allocator, block) catch |err| switch (err) {
            error.InvalidBlockPlan => return try emitNativeMatchCompressedBlockSerialWithBeamImpl(false, prove_mixed_dominance, allocator, out, block, last, match_search_budget, true, reusable_rep_beam, mixed_dominated, undefined, large_sequence_scratch, block_scratch),
            else => return err,
        };
        var local_large_sequence_scratch: LargeSequenceScratch = .{};
        defer if (large_sequence_scratch == null) local_large_sequence_scratch.deinit(allocator);
        const sequence_scratch = large_sequence_scratch orelse &local_large_sequence_scratch;
        var single: std.ArrayList(u8) = .empty;
        defer single.deinit(allocator);
        const single_ok = try emitHashTokenSequenceBlockReuse(allocator, &single, block, last, single_scratch.reversed.items, single_stats, sequence_scratch);

        var double_fast_tokens: std.ArrayList(lz77.Token) = .empty;
        defer double_fast_tokens.deinit(allocator);
        _ = double_fast_match.planReuse(&double_fast_tokens, allocator, block, zstdHashParserOptions(block.len)) catch |err| switch (err) {
            error.InvalidBlockPlan => return try emitNativeMatchCompressedBlockSerialWithBeamImpl(false, prove_mixed_dominance, allocator, out, block, last, match_search_budget, true, reusable_rep_beam, mixed_dominated, undefined, sequence_scratch, block_scratch),
            else => return err,
        };
        if (single_ok and acceptLevelThreeSingleBeam(
            single.items.len,
            lz77.fixedBitCost(single_scratch.reversed.items),
            lz77.fixedBitCost(double_fast_tokens.items),
            block.len,
        )) {
            if (mixed_dominated) |value| value.* = false;
            try out.appendSlice(allocator, single.items);
            return true;
        }
    }
    return try emitNativeMatchCompressedBlockSerialWithBeamImpl(false, prove_mixed_dominance, allocator, out, block, last, match_search_budget, true, reusable_rep_beam, mixed_dominated, undefined, large_sequence_scratch, block_scratch);
}

fn emitNativeMatchCompressedBlockSerialWithBeamImpl(
    comptime has_precomputed_rep_beam: bool,
    comptime prove_mixed_dominance: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    enable_rep_beam: bool,
    reusable_rep_beam: ?*lz77.RepBeamScratch,
    mixed_dominated: ?*bool,
    precomputed_rep_beam_stats: lz77.PlanStats,
    large_sequence_scratch: ?*LargeSequenceScratch,
    block_scratch: ?*NativeBlockEncodeScratch,
) Error!bool {
    if (match_search_budget == 0) return false;
    if (comptime prove_mixed_dominance) mixed_dominated.?.* = false;

    // The bootstrap match emitters are intentionally independent heuristics.
    // Reuse one scratch buffer and retain only the current winner so a broad
    // mixed plan cannot hide a tighter single-family plan found later without
    // keeping seven complete temporary blocks alive.
    var local_block_scratch: NativeBlockEncodeScratch = .{};
    defer if (block_scratch == null) local_block_scratch.deinit(allocator);
    const match_scratch = block_scratch orelse &local_block_scratch;
    match_scratch.clearMatchRetainingCapacity();
    const candidate = &match_scratch.match_candidate;
    const best = &match_scratch.match_best;
    var local_large_sequence_scratch: LargeSequenceScratch = .{};
    defer if (large_sequence_scratch == null) local_large_sequence_scratch.deinit(allocator);
    const sequence_scratch = large_sequence_scratch orelse &local_large_sequence_scratch;
    const greedy_tokens = &match_scratch.greedy_tokens;
    const lazy_tokens = &match_scratch.lazy_tokens;
    const optimal_scratch = &match_scratch.optimal;
    var duplicate_index: DuplicateMatchIndex = undefined;
    // Level 1 may already have a serialized beam before its single-duplicate
    // candidate is needed. Delay the large paired index until a direct bounded
    // scan has had a chance to prove that single candidate irrelevant.
    const defer_level_one_index = has_precomputed_rep_beam and !prove_mixed_dominance and
        match_search_budget < multi_duplicate_min_search_budget and
        block.len > duplicate_exact_hash_input_max and
        block.len <= duplicate_index_max_input_len and
        (!builtin.is_test or !test_disable_precomputed_beam_single_index_prune);
    var duplicate_index_ptr: ?*DuplicateMatchIndex = null;
    if (!defer_level_one_index and block.len > duplicate_exact_hash_input_max and block.len <= duplicate_index_max_input_len) {
        if (match_search_budget < multi_duplicate_min_search_budget)
            duplicate_index.buildBounded(block)
        else
            duplicate_index.build(block);
        duplicate_index_ptr = &duplicate_index;
    }
    // Level 1 skips multi-duplicate search, so its final single candidate has
    // no earlier query to reuse. Evaluate that candidate up front for large
    // blocks; an extreme 256x win can safely bypass the much slower optimal
    // and repeated passes. Non-decisive results stay in scratch and enter the
    // original final arbitration position, preserving tie behavior.
    var early_single_tested = false;
    var early_single_match: ?DuplicateMatch = null;
    var skip_level_one_single = false;
    var single_max_byte_frequency: ?u16 = null;
    const evaluateEarlySingle = struct {
        fn run(
            block_bytes: []const u8,
            index: ?*DuplicateMatchIndex,
            match_out: *?DuplicateMatch,
            tested: *bool,
            skip: *bool,
        ) Error!void {
            const decisive_total_len = block_bytes.len / 256;
            if (index) |built| {
                skip.* = indexedSingleMatchCannotBeat(block_bytes, built, decisive_total_len + 1);
                if (!skip.*) {
                    match_out.* = try findBestDuplicateMatchIndexed(block_bytes, 0, built);
                    tested.* = true;
                }
            } else {
                tested.* = true;
                match_out.* = try findBestDuplicateMatch(block_bytes);
            }
        }
    }.run;
    if (!defer_level_one_index and match_search_budget < multi_duplicate_min_search_budget and block.len > duplicate_exact_hash_input_max) {
        try evaluateEarlySingle(block, duplicate_index_ptr, &early_single_match, &early_single_tested, &skip_level_one_single);
        if (early_single_match) |match| {
            if (match.payload_len + 3 <= block.len / 256)
                return try emitSingleMatchCompressedBlockFromMatch(allocator, out, block, last, match);
        }
    }
    const mixed_ok = if (match_search_budget >= mixed_match_min_search_budget)
        try emitMixedDuplicateRepeatedMatchCompressedBlock(allocator, candidate, block, last, match_search_budget, duplicate_index_ptr, null)
    else
        false;
    try retainShortestCandidate(allocator, mixed_ok, candidate.items, best);

    var pre_emitted_beam_len: ?usize = null;
    if (comptime has_precomputed_rep_beam) {
        if (match_search_budget < multi_duplicate_min_search_budget and
            (!builtin.is_test or !test_disable_precomputed_beam_greedy_prune))
        {
            const precomputed_beam = reusable_rep_beam orelse return error.InvalidBlockPlan;
            candidate.clearRetainingCapacity();
            const beam_ok = try emitHashTokenSequenceBlockReuse(
                allocator,
                candidate,
                block,
                last,
                precomputed_beam.reversed.items,
                precomputed_rep_beam_stats,
                sequence_scratch,
            );
            if (beam_ok) {
                pre_emitted_beam_len = candidate.items.len;
                try retainShortestCandidate(allocator, true, candidate.items, best);
            }
        }
    }

    if (defer_level_one_index) {
        if (pre_emitted_beam_len) |beam_len| {
            // The legacy path returns a <= 1/256 single candidate before the
            // beam is considered. It later accepts only a candidate strictly
            // shorter than the current winner. Prove strict loss against both
            // boundaries before omitting the index and exact single scoring.
            const strict_single_limit = try precomputedBeamSingleDominanceLimit(beam_len, block.len);
            if (boundedSingleMatchCannotBeatWithSummary(block, strict_single_limit, &single_max_byte_frequency)) {
                skip_level_one_single = true;
                early_single_tested = true;
                if (comptime builtin.is_test) test_precomputed_beam_single_index_prune_hits += 1;
            } else {
                if (comptime builtin.is_test) test_precomputed_beam_single_index_fallbacks += 1;
                duplicate_index.buildBounded(block);
                duplicate_index_ptr = &duplicate_index;
                try evaluateEarlySingle(block, duplicate_index_ptr, &early_single_match, &early_single_tested, &skip_level_one_single);
            }
        } else {
            if (comptime builtin.is_test) test_precomputed_beam_single_index_fallbacks += 1;
            duplicate_index.buildBounded(block);
            duplicate_index_ptr = &duplicate_index;
            try evaluateEarlySingle(block, duplicate_index_ptr, &early_single_match, &early_single_tested, &skip_level_one_single);
        }
        if (early_single_match) |match| {
            if (match.payload_len + 3 <= block.len / 256)
                return try emitSingleMatchCompressedBlockFromMatch(allocator, out, block, last, match);
        }
    }
    candidate.clearRetainingCapacity();
    var greedy_len: ?usize = null;
    const greedy_ok = if (comptime has_precomputed_rep_beam) blk: {
        if (match_search_budget < multi_duplicate_min_search_budget) {
            if (pre_emitted_beam_len) |beam_len| {
                if (beam_len * 32 <= block.len)
                    break :blk try emitGreedyHashMatchCompressedBlockReuseUnlessDominated(
                        allocator,
                        candidate,
                        block,
                        last,
                        greedy_tokens,
                        sequence_scratch,
                        beam_len,
                        if (!prove_mixed_dominance and skip_level_one_single) single_max_byte_frequency else null,
                        &match_scratch.single_sequence_emit,
                    );
            }
        }
        break :blk if (block.len <= 32 * 1024)
            try emitGreedyHashMatchCompressedBlockReuse(allocator, candidate, block, last, greedy_tokens)
        else
            try emitHashMatchCompressedBlockWithSequenceScratch(allocator, candidate, block, last, .greedy, sequence_scratch);
    } else if (block.len <= 32 * 1024)
        try emitGreedyHashMatchCompressedBlockReuse(allocator, candidate, block, last, greedy_tokens)
    else
        try emitHashMatchCompressedBlockWithSequenceScratch(allocator, candidate, block, last, .greedy, sequence_scratch);
    if (greedy_ok) greedy_len = candidate.items.len;
    if (comptime has_precomputed_rep_beam) {
        if (match_search_budget < multi_duplicate_min_search_budget) {
            // Greedy was historically considered before the beam, so it keeps
            // an equal-length tie even when the precomputed beam is emitted
            // first.
            if (greedy_ok and (best.items.len == 0 or candidate.items.len <= best.items.len)) {
                best.clearRetainingCapacity();
                try best.appendSlice(allocator, candidate.items);
            }
        } else {
            try retainShortestCandidate(allocator, greedy_ok, candidate.items, best);
        }
    } else try retainShortestCandidate(allocator, greedy_ok, candidate.items, best);

    candidate.clearRetainingCapacity();
    // The separate lazy pass duplicates hash search at level 1 without winning
    // a locked corpus block. Level 2+ retains it because it can still produce a
    // different ratio-oriented candidate as the planner budget grows.
    const lazy_ok = if (match_search_budget >= lazy_match_min_search_budget)
        if (block.len <= 32 * 1024)
            try emitLazyHashMatchCompressedBlockReuse(allocator, candidate, block, last, lazy_tokens)
        else
            try emitHashMatchCompressedBlockWithSequenceScratch(allocator, candidate, block, last, .lazy, sequence_scratch)
    else
        false;
    try retainShortestCandidate(allocator, lazy_ok, candidate.items, best);

    candidate.clearRetainingCapacity();
    var local_rep_beam: lz77.RepBeamScratch = .{};
    defer if (reusable_rep_beam == null) local_rep_beam.deinit(allocator);
    const rep_beam_scratch = reusable_rep_beam orelse &local_rep_beam;
    const rep_beam_stats: ?lz77.PlanStats = if (!enable_rep_beam)
        null
    else if (has_precomputed_rep_beam)
        precomputed_rep_beam_stats
    else
        lz77.optimalRepBeamPlanZstdReuse(rep_beam_scratch, allocator, block) catch |err| switch (err) {
            error.InvalidBlockPlan => null,
            else => return err,
        };
    const pre_beam_best_len = if (pre_emitted_beam_len != null) greedy_len orelse best.items.len else best.items.len;
    var rep_beam_len: ?usize = pre_emitted_beam_len;
    if (rep_beam_stats) |stats| {
        if (pre_emitted_beam_len == null) {
            const rep_beam_ok = try emitHashTokenSequenceBlockReuse(allocator, candidate, block, last, rep_beam_scratch.reversed.items, stats, sequence_scratch);
            if (rep_beam_ok) rep_beam_len = candidate.items.len;
            try retainShortestCandidate(allocator, rep_beam_ok, candidate.items, best);
        }
    }

    // An absolute 32x reduction handles tiny final blocks. On larger blocks, a
    // beam result that beats every already-emitted linear candidate by at least
    // 1/32 has enough margin to skip the much slower ordinary optimal DP.
    const beam_is_decisive = rep_beam_stats != null and
        (best.items.len * 32 <= block.len or
            (pre_beam_best_len != 0 and rep_beam_len != null and rep_beam_len.? * 32 <= pre_beam_best_len * 31));
    if (!beam_is_decisive) {
        candidate.clearRetainingCapacity();
        const optimal_candidates = zstdOptimalCandidateBudget(match_search_budget);
        const optimal_ok = if (useFourByteOptimal(block.len, optimal_candidates))
            try emitFourByteOptimalHashMatchCompressedBlockReuseWithSequenceScratch(
                allocator,
                candidate,
                block,
                last,
                optimal_scratch,
                sequence_scratch,
                optimal_candidates,
            )
        else
            try emitOptimalHashMatchCompressedBlockReuseWithSequenceScratch(
                allocator,
                candidate,
                block,
                last,
                optimal_scratch,
                sequence_scratch,
                optimal_candidates,
            );
        try retainShortestCandidate(allocator, optimal_ok, candidate.items, best);
    }
    if (!prove_mixed_dominance and match_scratch.single_sequence_emit.repeated_prune_best_len == 0 and
        best.items.len != 0 and best.items.len * 32 <= block.len and
        (!builtin.is_test or !test_disable_precomputed_beam_repeated_prune))
    {
        if (single_max_byte_frequency) |maximum| {
            match_scratch.single_sequence_emit.repeated_prune_best_len = best.items.len;
            match_scratch.single_sequence_emit.repeated_prune_max_byte_frequency = maximum;
        } else if (duplicate_index_ptr) |index| {
            match_scratch.single_sequence_emit.repeated_prune_best_len = best.items.len;
            match_scratch.single_sequence_emit.repeated_prune_max_byte_frequency = index.max_byte_frequency;
        }
    }

    candidate.clearRetainingCapacity();
    const repeated_ok = try emitRepeatedPatternCompressedBlockWithScratch(allocator, candidate, block, last, &match_scratch.single_sequence_emit);
    const repeated_len: ?usize = if (repeated_ok) candidate.items.len else null;
    try retainShortestCandidate(allocator, repeated_ok, candidate.items, best);

    candidate.clearRetainingCapacity();
    var first_duplicate: ?DuplicateMatch = null;
    if (!early_single_tested and
        match_search_budget < multi_duplicate_min_search_budget and
        duplicate_index_ptr != null and rleByte(block) == null)
    {
        const index = duplicate_index_ptr.?;
        skip_level_one_single = indexedSingleMatchCannotBeat(block, index, best.items.len);
        if (!skip_level_one_single) early_single_match = try findBestDuplicateMatchIndexed(block, 0, index);
        early_single_tested = true;
    } else if (shouldQueryDecisiveSingleDuplicate(early_single_tested, beam_is_decisive, rleByte(block) != null)) {
        // The decisive-beam policy omits multi's iterative follow-up searches,
        // but the single-duplicate candidate still wins on some repetitive
        // text. Run only the first query shared by both duplicate planners and
        // pass its result to the single emitter below. Level 1 already ran and
        // retained this exact query in `early_single`, so repeating it here
        // would scan and score the complete block for a value never consumed.
        first_duplicate = if (duplicate_index_ptr) |index|
            if (comptime prove_mixed_dominance)
                try findBestDecisiveSingleDuplicate(block, index, rep_beam_len, best.items.len, repeated_len)
            else
                try findBestDuplicateMatchIndexed(block, 0, index)
        else
            try findBestDuplicateMatch(block);
    }
    const multi_duplicate_ok = if (shouldSearchMultiDuplicate(block.len, match_search_budget, beam_is_decisive))
        try emitMultiDuplicateMatchCompressedBlockWithFirst(allocator, candidate, block, last, duplicate_index_ptr, &first_duplicate)
    else
        false;
    try retainShortestCandidate(allocator, multi_duplicate_ok, candidate.items, best);

    candidate.clearRetainingCapacity();
    // Multi-duplicate starts with the exact same global-best query as the
    // single candidate. Reuse that result rather than walking/scoring the block
    // again. A decisive beam has already completed that query even when no
    // match exists; only paths that skipped both searches need the fallback.
    var single_len: ?usize = null;
    if (early_single_tested) {
        if (early_single_match) |match| {
            const exact_index_score = duplicate_index_ptr == null or duplicate_index_ptr.?.high_byte_count == 0;
            const estimated_total_len = match.payload_len + 3;
            single_len = estimated_total_len;
            if (!exact_index_score or best.items.len == 0 or estimated_total_len < best.items.len) {
                const single_ok = try emitSingleMatchCompressedBlockFromMatch(allocator, candidate, block, last, match);
                if (single_ok) single_len = candidate.items.len;
                try retainShortestCandidate(allocator, single_ok, candidate.items, best);
            }
        }
    } else {
        const single_duplicate_ok = if (first_duplicate) |match|
            try emitSingleMatchCompressedBlockFromMatch(allocator, candidate, block, last, match)
        else if (beam_is_decisive)
            false
        else if (block.len <= duplicate_exact_hash_input_max and (!builtin.is_test or !test_disable_small_single_emit_prune)) blk: {
            const match = try findBestDuplicateMatch(block) orelse break :blk false;
            const estimated_total_len = std.math.add(usize, match.payload_len, 3) catch return error.IntegerOverflow;
            single_len = estimated_total_len;
            if (best.items.len != 0 and estimated_total_len >= best.items.len) {
                if (comptime builtin.is_test) test_small_single_emit_prune_hits += 1;
                break :blk false;
            }
            break :blk try emitSingleMatchCompressedBlockFromMatch(allocator, candidate, block, last, match);
        } else try emitSingleMatchCompressedBlock(allocator, candidate, block, last, duplicate_index_ptr);
        if (single_duplicate_ok) single_len = candidate.items.len;
        try retainShortestCandidate(allocator, single_duplicate_ok, candidate.items, best);
    }

    if (best.items.len == 0) return false;
    if (comptime prove_mixed_dominance) {
        const value = mixed_dominated.?;
        if (beam_is_decisive and rep_beam_len != null and best.items.len == rep_beam_len.?) {
            const rep_len = rep_beam_len.?;
            const repeated_is_dominated = repeated_len == null or rep_len <= repeated_len.? / decisive_mixed_dominance_ratio;
            const single_is_dominated = single_len == null or rep_len <= single_len.? / decisive_mixed_dominance_ratio;
            value.* = repeated_is_dominated and single_is_dominated;
        }
    }
    try out.appendSlice(allocator, best.items);
    return true;
}

fn shouldSearchMultiDuplicate(block_len: usize, match_search_budget: usize, beam_is_decisive: bool) bool {
    return !beam_is_decisive and
        match_search_budget >= multi_duplicate_min_search_budget and
        block_len >= multi_duplicate_min_input_len;
}

fn shouldQueryDecisiveSingleDuplicate(early_single_tested: bool, beam_is_decisive: bool, is_rle: bool) bool {
    return !early_single_tested and beam_is_decisive and !is_rle;
}

noinline fn findBestDecisiveSingleDuplicate(
    block: []const u8,
    index: *DuplicateMatchIndex,
    rep_beam_len: ?usize,
    best_len: usize,
    repeated_len: ?usize,
) linksection(fast_encode_helper_text_section) Error!?DuplicateMatch {
    if (rep_beam_len != null and best_len == rep_beam_len.? and
        (repeated_len == null or rep_beam_len.? <= repeated_len.? / decisive_mixed_dominance_ratio))
    {
        const dominance_limit = std.math.mul(usize, rep_beam_len.?, decisive_mixed_dominance_ratio) catch std.math.maxInt(usize);
        if (indexedSingleMatchDominatedBy(block, index, dominance_limit)) {
            if (comptime builtin.is_test) test_decisive_single_lower_bound_hits += 1;
            return null;
        }
    }
    return try findBestDuplicateMatchIndexed(block, 0, index);
}

test "zstd decisive single lookup reuses the level one result" {
    try std.testing.expect(!shouldQueryDecisiveSingleDuplicate(true, true, false));
    try std.testing.expect(shouldQueryDecisiveSingleDuplicate(false, true, false));
    try std.testing.expect(!shouldQueryDecisiveSingleDuplicate(false, false, false));
    try std.testing.expect(!shouldQueryDecisiveSingleDuplicate(false, true, true));
}

test "zstd small single candidate length prune preserves selector wire" {
    const payload = "reusable seekable zstd frame payload-" ** 96;
    test_small_single_emit_prune_hits = 0;
    test_disable_small_single_emit_prune = false;
    defer {
        test_disable_small_single_emit_prune = false;
        test_small_single_emit_prune_hits = 0;
    }

    var offset: usize = 0;
    while (offset < payload.len) {
        const end = @min(payload.len, offset + small_sequence_stack_input_max);
        const block = payload[offset..end];
        var optimized: std.ArrayList(u8) = .empty;
        defer optimized.deinit(std.testing.allocator);
        const optimized_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
            std.testing.allocator,
            &optimized,
            block,
            end == payload.len,
            mixed_match_path_search_budget,
            false,
            null,
            null,
        );

        test_disable_small_single_emit_prune = true;
        var reference: std.ArrayList(u8) = .empty;
        defer reference.deinit(std.testing.allocator);
        const reference_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
            std.testing.allocator,
            &reference,
            block,
            end == payload.len,
            mixed_match_path_search_budget,
            false,
            null,
            null,
        );
        test_disable_small_single_emit_prune = false;

        try std.testing.expectEqual(reference_ok, optimized_ok);
        try std.testing.expectEqualSlices(u8, reference.items, optimized.items);
        offset = end;
    }
    try std.testing.expectEqual(@as(usize, 4), test_small_single_emit_prune_hits);

    const budgets = [_]usize{ 16, 64, 96, mixed_match_path_search_budget };
    var generated_prune_hits: usize = 0;
    for (0..32) |seed| {
        const len = 96 + seed * 29;
        var generated: [small_sequence_stack_input_max]u8 = undefined;
        var random_state: u32 = @truncate(0x9e37_79b9 +% seed *% 0x0100_0193);
        for (generated[0..len], 0..) |*byte, i| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => "abcdefghijklmnop"[i & 15],
                1 => @truncate(random_state >> 24),
                2 => @intCast('a' + ((i * 7 + seed) % 23)),
                else => @intCast('0' + ((i / 9 + seed) % 10)),
            };
        }
        if ((seed & 3) == 1 and len >= 96) {
            const copy_len = @min(@as(usize, 64), len / 3);
            @memcpy(generated[len - copy_len .. len], generated[8..][0..copy_len]);
        }
        const block = generated[0..len];
        if (try findBestDuplicateMatch(block)) |match| {
            var single: std.ArrayList(u8) = .empty;
            defer single.deinit(std.testing.allocator);
            try std.testing.expect(try emitSingleMatchCompressedBlockFromMatch(std.testing.allocator, &single, block, true, match));
            try std.testing.expectEqual(match.payload_len + 3, single.items.len);
        }

        for (budgets) |budget| for ([_]bool{ false, true }) |rep_beam_search| {
            const hits_before = test_small_single_emit_prune_hits;
            var optimized: std.ArrayList(u8) = .empty;
            defer optimized.deinit(std.testing.allocator);
            const optimized_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
                std.testing.allocator,
                &optimized,
                block,
                true,
                budget,
                rep_beam_search,
                null,
                null,
            );
            generated_prune_hits += test_small_single_emit_prune_hits - hits_before;

            test_disable_small_single_emit_prune = true;
            var reference: std.ArrayList(u8) = .empty;
            defer reference.deinit(std.testing.allocator);
            const reference_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
                std.testing.allocator,
                &reference,
                block,
                true,
                budget,
                rep_beam_search,
                null,
                null,
            );
            test_disable_small_single_emit_prune = false;
            try std.testing.expectEqual(reference_ok, optimized_ok);
            try std.testing.expectEqualSlices(u8, reference.items, optimized.items);
        };
    }
    try std.testing.expect(generated_prune_hits != 0);
}

test "zstd level three single-state beam policy is bounded" {
    const short = "structured JSON 0123456789" ** 1024;
    var long: [32 * 1024 + 1]u8 = undefined;
    var state: u32 = 0x243f_6a88;
    for (&long) |*byte| {
        state = state *% 1_664_525 +% 1_013_904_223;
        byte.* = @intCast('A' + ((state >> 24) & 31));
    }
    const repeated = "one repeated text line for a prefix-tail match\n" ** 1024;
    try std.testing.expect(!shouldTryLevelThreeSingleBeam(short, fast_wide_match_search_budget));
    try std.testing.expect(shouldTryLevelThreeSingleBeam(&long, fast_wide_match_search_budget));
    try std.testing.expect(!shouldTryLevelThreeSingleBeam(&long, 32));
    try std.testing.expect(!shouldTryLevelThreeSingleBeam(repeated, fast_wide_match_search_budget));
    try std.testing.expect(acceptLevelThreeSingleBeam(636, 14_597, 16_296, 32 * 1024));
    try std.testing.expect(!acceptLevelThreeSingleBeam(190, 10_000, 12_000, 32 * 1024));
    try std.testing.expect(acceptLevelThreeSingleBeam(355, 10_000, 12_000, 16_389));
    try std.testing.expect(!acceptLevelThreeSingleBeam(636, 15_800, 16_000, 32 * 1024));
    try std.testing.expect(!acceptLevelThreeSingleBeam(1025, 10_000, 12_000, 32 * 1024));
}

/// Candidate families evaluated by the native compressed-block selector.
///
/// These names intentionally mirror the selector order above so stage reports
/// can be compared with profiles without exposing the internal emitters as a
/// general encoding API.
pub const NativeMatchStage = enum {
    mixed,
    double_fast,
    greedy,
    lazy,
    optimal,
    rep_beam,
    rep_beam_single,
    repeated,
    multi_duplicate,
    single_duplicate,
};

pub const NativeMatchStageResult = struct {
    available: bool,
    encoded_len: usize,
    sequence_count: usize = 0,
    literals_bytes: usize = 0,
    sequence_bytes: usize = 0,
};

pub const NativeSingleBeamProfile = single_beam_match.Profile;
pub const NativeOptimalSearchProfile = lz77.OptimalSearchProfile;

pub const NativeMatchStageScratch = struct {
    candidate: std.ArrayList(u8) = .empty,
    greedy_tokens: std.ArrayList(lz77.Token) = .empty,
    double_fast_tokens: std.ArrayList(lz77.Token) = .empty,
    lazy_tokens: std.ArrayList(lz77.Token) = .empty,
    optimal: lz77.OptimalScratch = .{},
    rep_beam: lz77.RepBeamScratch = .{},
    single_beam: single_beam_match.Scratch = .{},
    large_sequences: LargeSequenceScratch = .{},
    duplicate_index: ?*DuplicateMatchIndex = null,
    duplicate_index_input_ptr: ?[*]const u8 = null,
    duplicate_index_input_len: usize = 0,
    duplicate_index_fingerprint: u64 = 0,

    pub fn deinit(self: *NativeMatchStageScratch, allocator: std.mem.Allocator) void {
        if (self.duplicate_index) |index| allocator.destroy(index);
        self.large_sequences.deinit(allocator);
        self.optimal.deinit(allocator);
        self.single_beam.deinit(allocator);
        self.rep_beam.deinit(allocator);
        self.lazy_tokens.deinit(allocator);
        self.double_fast_tokens.deinit(allocator);
        self.greedy_tokens.deinit(allocator);
        self.candidate.deinit(allocator);
        self.* = undefined;
    }
};

/// Prepare the predecessor index shared by duplicate-aware benchmark stages.
/// Returns false for blocks handled by the standalone exact matcher or the
/// unindexed oversized fallback, neither of which has a distinct setup phase.
pub fn benchmarkPrepareNativeMatchStageScratch(
    allocator: std.mem.Allocator,
    block: []const u8,
    match_search_budget: usize,
    scratch: *NativeMatchStageScratch,
) Error!bool {
    scratch.duplicate_index_input_ptr = null;
    scratch.duplicate_index_input_len = 0;
    scratch.duplicate_index_fingerprint = 0;
    if (block.len <= duplicate_exact_hash_input_max or block.len > duplicate_index_max_input_len) return false;
    const index = scratch.duplicate_index orelse blk: {
        const allocated = try allocator.create(DuplicateMatchIndex);
        scratch.duplicate_index = allocated;
        break :blk allocated;
    };
    if (match_search_budget < multi_duplicate_min_search_budget)
        index.buildBounded(block)
    else
        index.build(block);
    scratch.duplicate_index_input_ptr = block.ptr;
    scratch.duplicate_index_input_len = block.len;
    scratch.duplicate_index_fingerprint = duplicateIndexInputFingerprint(block);
    return true;
}

/// Drop the prepared-index identity after a benchmark repetition. The index
/// storage remains allocated so the next build measures only production setup
/// work rather than allocator noise.
pub fn benchmarkInvalidateNativeMatchStageScratch(scratch: *NativeMatchStageScratch) void {
    scratch.duplicate_index_input_ptr = null;
    scratch.duplicate_index_input_len = 0;
    scratch.duplicate_index_fingerprint = 0;
}

pub fn benchmarkNativeSingleBeamProfile(
    allocator: std.mem.Allocator,
    block: []const u8,
    scratch: *NativeMatchStageScratch,
    profile: *NativeSingleBeamProfile,
) Error!lz77.PlanStats {
    return try single_beam_match.planReuseProfiled(&scratch.single_beam, allocator, block, profile);
}

pub fn benchmarkNativeOptimalProfile(
    io: std.Io,
    allocator: std.mem.Allocator,
    block: []const u8,
    match_search_budget: usize,
    scratch: *NativeMatchStageScratch,
    profile: *NativeOptimalSearchProfile,
) Error!lz77.PlanStats {
    const options = zstdOptimalParserOptions(block.len, match_search_budget);
    return if (useFourByteOptimal(block.len, options.max_candidates))
        try optimal_four_match.planReuseProfiled(&scratch.optimal, allocator, block, options, io, profile)
    else
        try lz77.optimalPlanReuseProfiled(&scratch.optimal, allocator, block, options, io, profile);
}

fn duplicateIndexInputFingerprint(block: []const u8) u64 {
    std.debug.assert(block.len > duplicate_exact_hash_input_max);
    const first = std.mem.readInt(u64, block[0..8], .little);
    const middle_start = block.len / 2 - 4;
    const middle = std.mem.readInt(u64, block[middle_start..][0..8], .little);
    const last = std.mem.readInt(u64, block[block.len - 8 ..][0..8], .little);
    return first ^ std.math.rotl(u64, middle, 21) ^ std.math.rotl(u64, last, 42);
}

/// Evaluate one native match-family candidate for benchmark diagnostics.
///
/// The caller owns reusable scratch so repeated measurements exercise the same
/// retained-buffer behavior as production. Large-block duplicate predecessors
/// must be prepared once per block through the companion function, mirroring
/// production's sharing across the three duplicate-aware families. This
/// function is deliberately not re-exported from `root.zig`; normal callers
/// should use the complete frame encoder, whose arbitration and fallback rules
/// remain intact.
pub fn benchmarkNativeMatchStage(
    allocator: std.mem.Allocator,
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    stage: NativeMatchStage,
    scratch: *NativeMatchStageScratch,
) Error!NativeMatchStageResult {
    if (match_search_budget > mixed_match_path_search_budget) return error.InvalidBlockPlan;
    scratch.candidate.clearRetainingCapacity();

    const duplicate_index: ?*DuplicateMatchIndex = if ((stage == .mixed or stage == .multi_duplicate or stage == .single_duplicate) and
        block.len > duplicate_exact_hash_input_max and
        block.len <= duplicate_index_max_input_len)
    blk: {
        if (scratch.duplicate_index_input_ptr == null or
            scratch.duplicate_index_input_ptr.? != block.ptr or
            scratch.duplicate_index_input_len != block.len or
            scratch.duplicate_index_fingerprint != duplicateIndexInputFingerprint(block)) return error.InvalidBlockPlan;
        break :blk scratch.duplicate_index.?;
    } else null;

    var sequence_count: usize = 0;
    const available = switch (stage) {
        .mixed => if (match_search_budget >= mixed_match_min_search_budget)
            try emitMixedDuplicateRepeatedMatchCompressedBlock(allocator, &scratch.candidate, block, last, match_search_budget, duplicate_index, null)
        else
            false,
        .double_fast => if (block.len <= double_fast_match.max_input_len) blk: {
            const parser_options = zstdHashParserOptions(block.len);
            const stats = try double_fast_match.planReuse(&scratch.double_fast_tokens, allocator, block, parser_options);
            sequence_count = stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.double_fast_tokens.items, stats, &scratch.large_sequences);
        } else false,
        .greedy => if (block.len <= 32 * 1024) blk: {
            const parser_options = zstdHashParserOptions(block.len);
            const stats = try lz77.hashGreedyPlanAutoTinyReuse(&scratch.greedy_tokens, allocator, block, parser_options);
            sequence_count = stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.greedy_tokens.items, stats, &scratch.large_sequences);
        } else blk: {
            const plan = try lz77.hashGreedyPlanAutoTinyAlloc(allocator, block, zstdHashParserOptions(block.len));
            defer plan.deinit(allocator);
            sequence_count = plan.stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, plan.tokens, plan.stats, &scratch.large_sequences);
        },
        .lazy => if (match_search_budget >= lazy_match_min_search_budget)
            if (block.len <= 32 * 1024) blk: {
                const parser_options = zstdHashParserOptions(block.len);
                const stats = try lz77.hashLazyGreedyPlanTinyReuse(&scratch.lazy_tokens, allocator, block, parser_options);
                sequence_count = stats.matches;
                break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.lazy_tokens.items, stats, &scratch.large_sequences);
            } else blk: {
                const plan = try lz77.lazyGreedyPlanAlloc(allocator, block, zstdHashParserOptions(block.len));
                defer plan.deinit(allocator);
                sequence_count = plan.stats.matches;
                break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, plan.tokens, plan.stats, &scratch.large_sequences);
            }
        else
            false,
        .optimal => blk: {
            const options = zstdOptimalParserOptions(block.len, match_search_budget);
            const stats = if (useFourByteOptimal(block.len, options.max_candidates))
                try optimal_four_match.planReuse(&scratch.optimal, allocator, block, options)
            else
                try lz77.optimalPlanReuse(&scratch.optimal, allocator, block, options);
            sequence_count = stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.optimal.tokens.items, stats, &scratch.large_sequences);
        },
        .rep_beam => blk: {
            const stats = lz77.optimalRepBeamPlanZstdReuse(&scratch.rep_beam, allocator, block) catch |err| switch (err) {
                error.InvalidBlockPlan => break :blk false,
                else => return err,
            };
            sequence_count = stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.rep_beam.reversed.items, stats, &scratch.large_sequences);
        },
        .rep_beam_single => blk: {
            const stats = single_beam_match.planReuse(&scratch.single_beam, allocator, block) catch |err| switch (err) {
                error.InvalidBlockPlan => break :blk false,
                else => return err,
            };
            sequence_count = stats.matches;
            break :blk try emitHashTokenSequenceBlockReuse(allocator, &scratch.candidate, block, last, scratch.single_beam.reversed.items, stats, &scratch.large_sequences);
        },
        .repeated => try emitRepeatedPatternCompressedBlock(allocator, &scratch.candidate, block, last),
        .multi_duplicate => if (match_search_budget >= multi_duplicate_min_search_budget)
            try emitMultiDuplicateMatchCompressedBlock(allocator, &scratch.candidate, block, last, duplicate_index)
        else
            false,
        .single_duplicate => try emitSingleMatchCompressedBlock(allocator, &scratch.candidate, block, last, duplicate_index),
    };
    var literals_bytes: usize = 0;
    var sequence_bytes: usize = 0;
    if (available) {
        if (scratch.candidate.items.len < 3) return error.CorruptFrame;
        var frame_state: SequenceFrameState = .{};
        const section = try parseLiteralsSection(scratch.candidate.items[3..], &frame_state);
        literals_bytes = section.sequence_payload_offset;
        sequence_bytes = scratch.candidate.items.len - 3 - literals_bytes;
    }
    return .{
        .available = available,
        .encoded_len = if (available) scratch.candidate.items.len else 0,
        .sequence_count = sequence_count,
        .literals_bytes = literals_bytes,
        .sequence_bytes = sequence_bytes,
    };
}

fn zstdHashParserOptions(block_len: usize) lz77.GreedyOptions {
    return .{
        .window_len = @min(block_len, lz77.default_window_len),
        .max_chain = 128,
        .nice_len = 258,
        .max_candidates = default_optimal_candidate_budget,
        .min_match = 4,
        .max_match = lz77.max_match_len,
        .min_savings_bits = 0,
        // A new explicit offset also changes the OF symbol distribution/table;
        // this small proxy prevents a two-byte local gain from replacing a long
        // repeat-offset run with a costlier block-wide representation.
        .new_distance_penalty_bits = 4,
        .lazy_min_gain = 1,
    };
}

fn zstdOptimalParserOptions(block_len: usize, match_search_budget: usize) lz77.GreedyOptions {
    var options = zstdHashParserOptions(block_len);
    options.max_candidates = zstdOptimalCandidateBudget(match_search_budget);
    return options;
}

inline fn zstdOptimalCandidateBudget(match_search_budget: usize) usize {
    return if (match_search_budget == fastest_wide_match_search_budget)
        fastest_optimal_candidate_budget
    else
        default_optimal_candidate_budget;
}

inline fn useFourByteOptimal(block_len: usize, max_candidates: usize) bool {
    if (comptime builtin.is_test) if (test_disable_four_byte_optimal) return false;
    return block_len >= optimal_four_match.min_input_len and
        block_len <= optimal_four_match.max_input_len and
        max_candidates == optimal_four_match.candidate_count;
}

test "zstd four-byte optimal route is limited to large fastest blocks" {
    try std.testing.expect(!useFourByteOptimal(64 * 1024, fastest_optimal_candidate_budget));
    try std.testing.expect(useFourByteOptimal(64 * 1024 + 1, fastest_optimal_candidate_budget));
    try std.testing.expect(useFourByteOptimal(128 * 1024, fastest_optimal_candidate_budget));
    try std.testing.expect(!useFourByteOptimal(128 * 1024 + 1, fastest_optimal_candidate_budget));
    try std.testing.expect(!useFourByteOptimal(128 * 1024, default_optimal_candidate_budget));
}

test "zstd four-byte optimal route preserves generated frame quality" {
    test_disable_four_byte_optimal = false;
    defer test_disable_four_byte_optimal = false;
    var baseline_total: usize = 0;
    var candidate_total: usize = 0;
    var changed: usize = 0;
    var larger: usize = 0;
    var worst_extra: usize = 0;
    for (0..32) |seed| {
        const length = optimal_four_match.min_input_len + (seed % 4) * 16 * 1024;
        const payload = try std.testing.allocator.alloc(u8, length);
        defer std.testing.allocator.free(payload);
        var random_state: u32 = @truncate(0x6a09_e667 +% seed *% 0x0100_0193);
        for (payload, 0..) |*byte, position| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @truncate(random_state >> 24),
                1 => @intCast('a' + (position / (3 + seed)) % 23),
                2 => if (position % 64 < 56) @truncate(position * 17 + seed) else @truncate(random_state >> 24),
                else => @truncate((position * 37 + (position / 11) * 17 + seed) & 0xff),
            };
        }
        if (seed % 3 == 0) {
            const copied = payload.len / 4;
            @memcpy(payload[payload.len - copied ..], payload[payload.len / 4 ..][0..copied]);
        }

        test_disable_four_byte_optimal = true;
        const baseline = try encodeNativeFrameWithOptionsAlloc(std.testing.allocator, payload, try nativeFrameOptionsForLevel(1, .{}));
        defer std.testing.allocator.free(baseline.frame);
        test_disable_four_byte_optimal = false;
        const candidate = try encodeNativeFrameWithOptionsAlloc(std.testing.allocator, payload, try nativeFrameOptionsForLevel(1, .{}));
        defer std.testing.allocator.free(candidate.frame);
        baseline_total += baseline.frame.len;
        candidate_total += candidate.frame.len;
        changed += @intFromBool(baseline.frame.len != candidate.frame.len);
        if (candidate.frame.len > baseline.frame.len) {
            larger += 1;
            worst_extra = @max(worst_extra, candidate.frame.len - baseline.frame.len);
        }
        const decoded = try decodeNativeFrameAlloc(std.testing.allocator, candidate.frame);
        defer std.testing.allocator.free(decoded);
        try std.testing.expectEqualSlices(u8, payload, decoded);
    }
    std.debug.print(
        "four-byte optimal frame audit: changed={d} larger={d} total={d}/{d} worst_extra={d}\n",
        .{ changed, larger, candidate_total, baseline_total, worst_extra },
    );
    try std.testing.expect(candidate_total <= baseline_total);
    try std.testing.expect(worst_extra <= 8);
}

test "zstd optimal candidate budget is level-one-only" {
    try std.testing.expectEqual(@as(usize, fastest_optimal_candidate_budget), zstdOptimalCandidateBudget(fastest_wide_match_search_budget));
    try std.testing.expectEqual(@as(usize, default_optimal_candidate_budget), zstdOptimalCandidateBudget(0));
    try std.testing.expectEqual(@as(usize, default_optimal_candidate_budget), zstdOptimalCandidateBudget(fast_wide_match_search_budget));
    try std.testing.expectEqual(@as(usize, default_optimal_candidate_budget), zstdOptimalCandidateBudget(96));
}

test "zstd fastest optimal candidate budget audits generated block sizes" {
    var changed: usize = 0;
    var larger: usize = 0;
    var smaller: usize = 0;
    var total_fastest: usize = 0;
    var total_default: usize = 0;
    var worst_extra: usize = 0;
    for (0..32) |seed| {
        const length = 8 * 1024 + (seed % 8) * 8 * 1024;
        const payload = try std.testing.allocator.alloc(u8, length);
        defer std.testing.allocator.free(payload);
        var random_state: u32 = @truncate(0x6a09_e667 +% seed *% 0x0100_0193);
        for (payload, 0..) |*byte, position| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @truncate(random_state >> 24),
                1 => @intCast('a' + (position / 7 + seed) % 23),
                2 => if (position % 64 < 56) @intCast(' ' + (position + seed) % 64) else @truncate(random_state >> 24),
                else => @truncate((position * 37 + (position / 11) * 17 + seed) & 0xff),
            };
        }
        if (seed % 3 == 0) {
            const copy_len = payload.len / 4;
            @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
        }

        var fastest_scratch: lz77.OptimalScratch = .{};
        defer fastest_scratch.deinit(std.testing.allocator);
        const fastest_stats = try lz77.optimalPlanReuse(
            &fastest_scratch,
            std.testing.allocator,
            payload,
            zstdOptimalParserOptions(payload.len, fastest_wide_match_search_budget),
        );
        const fastest_replay = try lz77.replayAlloc(std.testing.allocator, fastest_scratch.tokens.items);
        defer std.testing.allocator.free(fastest_replay);
        try std.testing.expectEqualSlices(u8, payload, fastest_replay);
        var fastest: std.ArrayList(u8) = .empty;
        defer fastest.deinit(std.testing.allocator);
        const fastest_ok = try emitHashTokenSequenceBlock(
            std.testing.allocator,
            &fastest,
            payload,
            true,
            fastest_scratch.tokens.items,
            fastest_stats,
        );

        var default_scratch: lz77.OptimalScratch = .{};
        defer default_scratch.deinit(std.testing.allocator);
        const default_stats = try lz77.optimalPlanReuse(
            &default_scratch,
            std.testing.allocator,
            payload,
            zstdOptimalParserOptions(payload.len, fast_wide_match_search_budget),
        );
        const default_replay = try lz77.replayAlloc(std.testing.allocator, default_scratch.tokens.items);
        defer std.testing.allocator.free(default_replay);
        try std.testing.expectEqualSlices(u8, payload, default_replay);
        var default: std.ArrayList(u8) = .empty;
        defer default.deinit(std.testing.allocator);
        const default_ok = try emitHashTokenSequenceBlock(
            std.testing.allocator,
            &default,
            payload,
            true,
            default_scratch.tokens.items,
            default_stats,
        );

        const fastest_len = if (fastest_ok) fastest.items.len else payload.len + 3;
        const default_len = if (default_ok) default.items.len else payload.len + 3;
        changed += @intFromBool(fastest_len != default_len);
        larger += @intFromBool(fastest_len > default_len);
        smaller += @intFromBool(fastest_len < default_len);
        total_fastest += fastest_len;
        total_default += default_len;
        worst_extra = @max(worst_extra, fastest_len -| default_len);
    }
    std.debug.print(
        "fastest optimal budget audit: changed={d} larger={d} smaller={d} total={d}/{d} worst_extra={d}\n",
        .{ changed, larger, smaller, total_fastest, total_default, worst_extra },
    );
    try std.testing.expectEqual(@as(usize, 3), changed);
    try std.testing.expectEqual(@as(usize, 0), larger);
    try std.testing.expectEqual(@as(usize, 3), smaller);
    try std.testing.expectEqual(@as(usize, 230_779), total_fastest);
    try std.testing.expectEqual(@as(usize, 230_784), total_default);
    try std.testing.expectEqual(@as(usize, 0), worst_extra);
}

fn retainShortestCandidate(allocator: std.mem.Allocator, ok: bool, candidate: []const u8, best: *std.ArrayList(u8)) Error!void {
    if (!ok or (best.items.len != 0 and candidate.len >= best.items.len)) return;
    best.clearRetainingCapacity();
    try best.appendSlice(allocator, candidate);
}

const ZstdHashParser = enum { greedy, lazy, optimal };

fn emitHashMatchCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, parser: ZstdHashParser) Error!bool {
    var scratch: LargeSequenceScratch = .{};
    defer scratch.deinit(allocator);
    return try emitHashMatchCompressedBlockWithSequenceScratch(allocator, out, block, last, parser, &scratch);
}

fn emitHashMatchCompressedBlockWithSequenceScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    parser: ZstdHashParser,
    sequence_scratch: *LargeSequenceScratch,
) Error!bool {
    const parser_options: lz77.GreedyOptions = .{
        .window_len = @min(block.len, lz77.default_window_len),
        .max_chain = 128,
        .nice_len = 258,
        .max_candidates = 8,
        .min_match = 4,
        .max_match = lz77.max_match_len,
        .min_savings_bits = 0,
        .lazy_min_gain = 1,
    };
    const plan = switch (parser) {
        .greedy => try lz77.hashGreedyPlanAutoTinyAlloc(allocator, block, parser_options),
        .lazy => try lz77.lazyGreedyPlanAlloc(allocator, block, parser_options),
        .optimal => try lz77.optimalPlanAlloc(allocator, block, parser_options),
    };
    defer plan.deinit(allocator);
    return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, plan.tokens, plan.stats, sequence_scratch);
}

fn emitGreedyHashMatchCompressedBlockReuse(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: *std.ArrayList(lz77.Token),
) Error!bool {
    try ensureReusableHashTokenCapacity(tokens, allocator, block.len);
    const parser_options: lz77.GreedyOptions = .{
        .window_len = @min(block.len, lz77.default_window_len),
        .max_chain = 128,
        .nice_len = 258,
        .max_candidates = 8,
        .min_match = 4,
        .max_match = lz77.max_match_len,
        .min_savings_bits = 0,
        .lazy_min_gain = 1,
    };
    const stats = try lz77.hashGreedyPlanAutoTinyReuse(tokens, allocator, block, parser_options);
    return try emitHashTokenSequenceBlock(allocator, out, block, last, tokens.items, stats);
}

noinline fn emitGreedyHashMatchCompressedBlockReuseUnlessDominated(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: *std.ArrayList(lz77.Token),
    sequence_scratch: *LargeSequenceScratch,
    best_len: usize,
    single_max_byte_frequency: ?u16,
    single_sequence_scratch: *SingleSequenceEmitScratch,
) linksection(fast_encode_helper_text_section) Error!bool {
    const parser_options = zstdHashParserOptions(block.len);
    if (block.len <= 32 * 1024) {
        try ensureReusableHashTokenCapacity(tokens, allocator, block.len);
        const stats = try lz77.hashGreedyPlanAutoTinyReuse(tokens, allocator, block, parser_options);
        if (try hashTokenSequenceCannotBeat(block, tokens.items, stats, best_len)) {
            if (comptime builtin.is_test) test_precomputed_beam_greedy_prune_hits += 1;
            if (single_max_byte_frequency != null and
                (!builtin.is_test or !test_disable_precomputed_beam_repeated_prune))
            {
                single_sequence_scratch.repeated_prune_best_len = best_len;
                single_sequence_scratch.repeated_prune_max_byte_frequency = single_max_byte_frequency.?;
            }
            return false;
        }
        return try emitHashTokenSequenceBlock(allocator, out, block, last, tokens.items, stats);
    }

    const plan = try lz77.hashGreedyPlanAutoAlloc(allocator, block, parser_options);
    defer plan.deinit(allocator);
    if (try hashTokenSequenceCannotBeat(block, plan.tokens, plan.stats, best_len)) {
        if (comptime builtin.is_test) test_precomputed_beam_greedy_prune_hits += 1;
        if (single_max_byte_frequency != null and
            (!builtin.is_test or !test_disable_precomputed_beam_repeated_prune))
        {
            single_sequence_scratch.repeated_prune_best_len = best_len;
            single_sequence_scratch.repeated_prune_max_byte_frequency = single_max_byte_frequency.?;
        }
        return false;
    }
    return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, plan.tokens, plan.stats, sequence_scratch);
}

fn emitLazyHashMatchCompressedBlockReuse(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
