fn emitOptimalHashMatchCompressedBlockReuse(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    scratch: *lz77.OptimalScratch,
) Error!bool {
    var sequence_scratch: LargeSequenceScratch = .{};
    defer sequence_scratch.deinit(allocator);
    return try emitOptimalHashMatchCompressedBlockReuseWithSequenceScratch(
        allocator,
        out,
        block,
        last,
        scratch,
        &sequence_scratch,
        default_optimal_candidate_budget,
    );
}

fn emitOptimalHashMatchCompressedBlockReuseWithSequenceScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    scratch: *lz77.OptimalScratch,
    sequence_scratch: *LargeSequenceScratch,
    max_candidates: usize,
) Error!bool {
    try ensureReusableHashTokenCapacity(&scratch.tokens, allocator, block.len);
    var parser_options = zstdHashParserOptions(block.len);
    parser_options.max_candidates = max_candidates;
    const stats = try lz77.optimalPlanReuse(scratch, allocator, block, parser_options);
    return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, scratch.tokens.items, stats, sequence_scratch);
}

noinline fn emitFourByteOptimalHashMatchCompressedBlockReuseWithSequenceScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    scratch: *lz77.OptimalScratch,
    sequence_scratch: *LargeSequenceScratch,
    max_candidates: usize,
) linksection(optimal_four_match.text_section) Error!bool {
    var parser_options = zstdHashParserOptions(block.len);
    parser_options.max_candidates = max_candidates;
    const stats = try optimal_four_match.planReuse(scratch, allocator, block, parser_options);
    return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, scratch.tokens.items, stats, sequence_scratch);
}

test "zstd reusable greedy hash emitter matches allocating wire" {
    const payload = ("{\"service\":\"vort\",\"message\":\"reusable greedy hash\"}\n" ** 48) ++ ("abcdefghijklmnop" ** 32);
    var expected: std.ArrayList(u8) = .empty;
    defer expected.deinit(std.testing.allocator);
    try std.testing.expect(try emitHashMatchCompressedBlock(std.testing.allocator, &expected, payload, true, .greedy));

    var tokens: std.ArrayList(lz77.Token) = .empty;
    defer tokens.deinit(std.testing.allocator);
    var actual: std.ArrayList(u8) = .empty;
    defer actual.deinit(std.testing.allocator);
    try std.testing.expect(try emitGreedyHashMatchCompressedBlockReuse(std.testing.allocator, &actual, payload, true, &tokens));
    try std.testing.expectEqualSlices(u8, expected.items, actual.items);

    const retained_capacity = tokens.capacity;
    actual.clearRetainingCapacity();
    try std.testing.expect(try emitGreedyHashMatchCompressedBlockReuse(std.testing.allocator, &actual, payload, true, &tokens));
    try std.testing.expectEqual(retained_capacity, tokens.capacity);
    try std.testing.expectEqualSlices(u8, expected.items, actual.items);
}

