test "zstd hash emitter supports more than bootstrap sequence capacity" {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(std.testing.allocator);
    while (payload.items.len < 32 * 1024) {
        var line: [128]u8 = undefined;
        const index = payload.items.len / 64;
        const formatted = try std.fmt.bufPrint(&line, "{{\"id\":{d},\"service\":\"vort\",\"message\":\"structured zstd encode corpus\"}}\n", .{index});
        try payload.appendSlice(std.testing.allocator, formatted);
    }
    const parser_options = zstdHashParserOptions(payload.items.len);
    var scratch: lz77.OptimalScratch = .{};
    defer scratch.deinit(std.testing.allocator);
    const stats = try lz77.optimalPlanReuse(&scratch, std.testing.allocator, payload.items, parser_options);
    try std.testing.expect(stats.matches > max_bootstrap_sequence_count);
    try std.testing.expect(stats.matches <= max_native_sequence_count);

    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, payload.items.len, .{ .content_checksum = false });
    try std.testing.expect(try emitHashTokenSequenceBlock(std.testing.allocator, &frame, payload.items, true, scratch.tokens.items, stats));
    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload.items, decoded);
}

test "zstd hash emitter uses dynamic scratch beyond native stack capacity" {
    const sequence_count = max_native_sequence_count + 1;
    const block_len = 32 * 1024 + 1;
    var payload: [block_len]u8 = undefined;
    var tokens: [block_len - sequence_count * 3]lz77.Token = undefined;
    @memcpy(payload[0..4], "abcd");
    for ("abcd", 0..) |byte, i| tokens[i] = .{ .literal = byte };
    var payload_len: usize = 4;
    var token_len: usize = 4;
    for (0..sequence_count) |_| {
        @memcpy(payload[payload_len..][0..4], "abcd");
        payload_len += 4;
        tokens[token_len] = .{ .match = .{ .length = 4, .distance = 4 } };
        token_len += 1;
    }
    var state: u32 = 0x6a09_e667;
    while (payload_len < payload.len) {
        state = state *% 1_664_525 +% 1_013_904_223;
        const byte: u8 = @truncate(state >> 24);
        payload[payload_len] = byte;
        tokens[token_len] = .{ .literal = byte };
        payload_len += 1;
        token_len += 1;
    }
    const stats: lz77.PlanStats = .{
        .literals = block_len - sequence_count * 4,
        .matches = sequence_count,
        .matched_bytes = sequence_count * 4,
    };
    try std.testing.expectEqual(stats.tokenCount(), token_len);

    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, payload.len, .{ .content_checksum = false });
    try std.testing.expect(try emitHashTokenSequenceBlock(std.testing.allocator, &frame, &payload, true, tokens[0..token_len], stats));
    const first_block = try inspectNativeFrameFirstBlock(frame.items);
    const modes = try inspectNativeFrameBlockSequenceModes(frame.items, first_block);
    try std.testing.expectEqual(sequence_count, modes.sequence_count);
    try std.testing.expectEqual(NativeSequenceTableMode.compressed, modes.literal_length_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.compressed, modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.rle, modes.match_length_mode);

    var inverse_scratch: LargeSequenceScratch = .{};
    defer inverse_scratch.deinit(std.testing.allocator);
    var inverse_block: std.ArrayList(u8) = .empty;
    defer inverse_block.deinit(std.testing.allocator);
    try std.testing.expect(try emitHashTokenSequenceBlockReuse(
        std.testing.allocator,
        &inverse_block,
        &payload,
        true,
        tokens[0..token_len],
        stats,
        &inverse_scratch,
    ));
    var direct_scratch: LargeSequenceScratch = .{};
    defer direct_scratch.deinit(std.testing.allocator);
    var direct_block: std.ArrayList(u8) = .empty;
    defer direct_block.deinit(std.testing.allocator);
    try std.testing.expect(try emitLargeHashTokenSequenceBlockReuseFast(
        std.testing.allocator,
        &direct_block,
        &payload,
        true,
        tokens[0..token_len],
        stats,
        &direct_scratch,
    ));
    try std.testing.expectEqualSlices(u8, inverse_block.items, direct_block.items);

    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, &payload, decoded);

    const Test = struct {
        fn run(allocator: std.mem.Allocator, input: []const u8, input_tokens: []const lz77.Token, input_stats: lz77.PlanStats) !void {
            var out: std.ArrayList(u8) = .empty;
            defer out.deinit(allocator);
            try out.appendSlice(allocator, "prefix");
            _ = emitHashTokenSequenceBlock(allocator, &out, input, true, input_tokens, input_stats) catch |err| {
                try std.testing.expectEqualSlices(u8, "prefix", out.items);
                return err;
            };
            try std.testing.expectEqualSlices(u8, "prefix", out.items[0.."prefix".len]);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Test.run, .{ &payload, tokens[0..token_len], stats });

    const FastTest = struct {
        fn run(allocator: std.mem.Allocator, input: []const u8, input_tokens: []const lz77.Token, input_stats: lz77.PlanStats) !void {
            var local_scratch: LargeSequenceScratch = .{};
            defer local_scratch.deinit(allocator);
            var out: std.ArrayList(u8) = .empty;
            defer out.deinit(allocator);
            try out.appendSlice(allocator, "prefix");
            _ = emitLargeHashTokenSequenceBlockReuseFast(
                allocator,
                &out,
                input,
                true,
                input_tokens,
                input_stats,
                &local_scratch,
            ) catch |err| {
                try std.testing.expectEqualSlices(u8, "prefix", out.items);
                return err;
            };
            try std.testing.expectEqualSlices(u8, "prefix", out.items[0.."prefix".len]);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, FastTest.run, .{ &payload, tokens[0..token_len], stats });
}

