        &payload,
        true,
        tokens[0..token_len],
        stats,
        &scratch,
    ));
    try std.testing.expect(try prepareSequenceCandidateForFrame(
        std.testing.allocator,
        &rewritten_second,
        &payload,
        true,
        &sequence_state,
    ));
    var direct_second: std.ArrayList(u8) = .empty;
    defer direct_second.deinit(std.testing.allocator);
    try std.testing.expect(try emitHashTokenSequenceBlockReuseWithState(
        std.testing.allocator,
        &direct_second,
        &payload,
        true,
        tokens[0..token_len],
        stats,
        &scratch,
        previous_tables,
        sequence_state.repeated_offsets,
    ));
    try std.testing.expectEqualSlices(u8, rewritten_second.items, direct_second.items);
    try frame.appendSlice(std.testing.allocator, direct_second.items);

    var reference_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var reference_scratch: LargeSequenceScratch = .{};
    defer reference_scratch.deinit(reference_allocator.allocator());
    var reference_second: std.ArrayList(u8) = .empty;
    defer reference_second.deinit(reference_allocator.allocator());
    try std.testing.expect(try emitHashTokenSequenceBlockReuse(
        reference_allocator.allocator(),
        &reference_second,
        &payload,
        true,
        tokens[0..token_len],
        stats,
        &reference_scratch,
    ));
    try std.testing.expect(try prepareSequenceCandidateForFrame(
        reference_allocator.allocator(),
        &reference_second,
        &payload,
        true,
        &sequence_state,
    ));
    var direct_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var direct_scratch: LargeSequenceScratch = .{};
    defer direct_scratch.deinit(direct_allocator.allocator());
    var measured_direct: std.ArrayList(u8) = .empty;
    defer measured_direct.deinit(direct_allocator.allocator());
    try std.testing.expect(try emitHashTokenSequenceBlockReuseForFrame(
        direct_allocator.allocator(),
        &measured_direct,
        &payload,
        true,
        tokens[0..token_len],
        stats,
        &direct_scratch,
        &sequence_state,
    ));
    try std.testing.expectEqualSlices(u8, reference_second.items, measured_direct.items);
    try std.testing.expectEqual(reference_allocator.allocations - 16, direct_allocator.allocations);
    try std.testing.expectEqual(reference_allocator.allocated_bytes - 237_173, direct_allocator.allocated_bytes);
    const expected_repeat_mask_words = @max(
        try repeatSequenceMaskWordCount(previousSequenceTable(previous_tables, .literal)),
        @max(
            try repeatSequenceMaskWordCount(previousSequenceTable(previous_tables, .offset)),
            try repeatSequenceMaskWordCount(previousSequenceTable(previous_tables, .match)),
        ),
    );
    try std.testing.expectEqual(sequence_count * expected_repeat_mask_words, direct_scratch.repeat_viable_masks.items.len);
    try std.testing.expectEqual(@as(usize, 2), expected_repeat_mask_words);

    const first_block = try inspectNativeFrameFirstBlock(frame.items);
    const first_modes = try inspectNativeFrameBlockSequenceModes(frame.items, first_block);
    try std.testing.expectEqual(sequence_count, first_modes.sequence_count);
    const second_block = try inspectNativeFrameBlockAt(frame.items, first_block.next_header_offset);
    const second_modes = try inspectNativeFrameBlockSequenceModes(frame.items, second_block);
    try std.testing.expectEqual(sequence_count, second_modes.sequence_count);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, second_modes.literal_length_mode);
    // The first block leaves distance four in rep0. The second block therefore
    // encodes every offset as rep0 and replaces its mixed compressed table with
    // RLE, while LL and ML can reuse their preceding compressed/RLE tables.
    try std.testing.expectEqual(NativeSequenceTableMode.rle, second_modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.repeat, second_modes.match_length_mode);

    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqual(payload.len * 2, decoded.len);
    try std.testing.expectEqualSlices(u8, &payload, decoded[0..payload.len]);
    try std.testing.expectEqualSlices(u8, &payload, decoded[payload.len..]);
    const std_decoded = try decodeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(std_decoded);
    try std.testing.expectEqualSlices(u8, decoded, std_decoded);

    const Test = struct {
        fn run(
            allocator: std.mem.Allocator,
            input: []const u8,
            input_tokens: []const lz77.Token,
            input_stats: lz77.PlanStats,
            tables: SequenceTables,
            offsets: [3]usize,
        ) !void {
            var local_scratch: LargeSequenceScratch = .{};
            defer local_scratch.deinit(allocator);
            var out: std.ArrayList(u8) = .empty;
            defer out.deinit(allocator);
            try out.appendSlice(allocator, "prefix");
            _ = emitHashTokenSequenceBlockReuseWithState(
                allocator,
                &out,
                input,
                true,
                input_tokens,
                input_stats,
                &local_scratch,
                &tables,
                offsets,
            ) catch |err| {
                try std.testing.expectEqualSlices(u8, "prefix", out.items);
                return err;
            };
            try std.testing.expectEqualSlices(u8, "prefix", out.items[0.."prefix".len]);
        }
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        Test.run,
        .{ &payload, tokens[0..token_len], stats, previous_tables.*, sequence_state.repeated_offsets },
    );
}

test "zstd dynamic hash emitter writes three-byte sequence counts" {
    const sequence_count = 0x7f00;
    const block_len = 4 + sequence_count * 4;
    const payload = try std.testing.allocator.alloc(u8, block_len);
    defer std.testing.allocator.free(payload);
    const tokens = try std.testing.allocator.alloc(lz77.Token, 4 + sequence_count);
    defer std.testing.allocator.free(tokens);

    @memcpy(payload[0..4], "abcd");
    for ("abcd", 0..) |byte, i| tokens[i] = .{ .literal = byte };
    for (0..sequence_count) |i| {
        @memcpy(payload[4 + i * 4 ..][0..4], "abcd");
        tokens[4 + i] = .{ .match = .{ .length = 4, .distance = 4 } };
    }
    const stats: lz77.PlanStats = .{
        .literals = 4,
        .matches = sequence_count,
        .matched_bytes = sequence_count * 4,
    };
    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, payload.len, .{ .content_checksum = false });
    try std.testing.expect(try emitHashTokenSequenceBlock(std.testing.allocator, &frame, payload, true, tokens, stats));
    const first_block = try inspectNativeFrameFirstBlock(frame.items);
    const modes = try inspectNativeFrameBlockSequenceModes(frame.items, first_block);
    try std.testing.expectEqual(sequence_count, modes.sequence_count);
    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
}

