test "zstd large predefined planner matches small planner" {
    var values: [max_native_sequence_count]usize = undefined;
    var large_states: [max_native_sequence_count]u8 = undefined;
    var viable_masks: [max_native_sequence_count]u64 = undefined;
    var state: u32 = 0x510e_527f;
    const cases = [_]struct { []const SequenceSymbol, u8, usize }{
        .{ &sequence_predefined.literal_symbols, 0, 4096 },
        .{ &sequence_predefined.offset_symbols, 2, 32 * 1024 },
        .{ &sequence_predefined.match_symbols, 0, 1024 },
    };
    for (cases) |case| {
        for (&values) |*value| {
            state = state *% 1_664_525 +% 1_013_904_223;
            value.* = (state >> 16) % case[2];
        }
        const expected = try planPredefinedSequenceValues(&values, case[0], case[1]);
        const actual = planLargePredefinedSequenceValues(&values, case[0], case[1], &large_states, &viable_masks);
        try std.testing.expectEqual(expected != null, actual);
        if (expected) |plan| try std.testing.expectEqualSlices(u8, plan.states[0..plan.len], &large_states);
    }
}

test "zstd large predefined code planner matches scalar reference" {
    const max_len = 2047;
    var codes: [max_len]u8 = undefined;
    var expected_states: [max_len]u8 = undefined;
    var actual_states: [max_len]u8 = undefined;
    var compact_states: [max_len]u8 = undefined;
    var expected_masks: [max_len]u64 = undefined;
    var actual_masks: [max_len]u64 = undefined;
    var compact_masks: [max_len]u32 = undefined;

    const Test = struct {
        fn plan(
            input_codes: []const u8,
            symbols: []const SequenceSymbol,
            kind: SequenceTableKind,
            states: []u8,
            viable_masks: []u64,
        ) bool {
            if (input_codes.len == 0 or states.len != input_codes.len or viable_masks.len != input_codes.len) return false;
            var viable_next: u64 = 0;
            var pos = input_codes.len;
            while (pos > 0) {
                pos -= 1;
                var viable_current: u64 = 0;
                for (symbols, 0..) |symbol, state| {
                    if (!sequenceSymbolMatchesCode(symbol, kind, input_codes[pos])) continue;
                    if (pos == input_codes.len - 1) {
                        viable_current |= @as(u64, 1) << @intCast(state);
                        continue;
                    }
                    const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
                    const first_next: usize = symbol.next_state;
                    const end_next = @min(symbols.len, first_next + transition_count);
                    const width = end_next - first_next;
                    const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
                    if (viable_next & (low_mask << @intCast(first_next)) != 0)
                        viable_current |= @as(u64, 1) << @intCast(state);
                }
                viable_next = viable_current;
                viable_masks[pos] = viable_current;
            }
            if (viable_next == 0) return false;
            states[0] = @intCast(@ctz(viable_next));
            for (0..input_codes.len - 1) |i| {
                const symbol = symbols[states[i]];
                const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
                const first_next: usize = symbol.next_state;
                const end_next = @min(symbols.len, first_next + transition_count);
                const width = end_next - first_next;
                const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
                const possible = viable_masks[i + 1] & (low_mask << @intCast(first_next));
                if (possible == 0) return false;
                states[i + 1] = @intCast(@ctz(possible));
            }
            return true;
        }
    };

    var random_state: u32 = 0x1319_8a2e;
    inline for (std.meta.tags(SequenceTableKind)) |kind| {
        const symbols = sequenceTablePredefinedSymbols(kind);
        for ([_]usize{ 513, 1024, max_len }) |len| {
            for (codes[0..len]) |*code| {
                random_state = random_state *% 1_664_525 +% 1_013_904_223;
                const symbol = symbols[(random_state >> 16) % symbols.len];
                code.* = try sequenceCodeForValue(symbol.base, sequenceTableBases(kind), sequenceTableBits(kind));
            }
            const expected = Test.plan(codes[0..len], symbols, kind, expected_states[0..len], expected_masks[0..len]);
            const actual = large_predefined.plan(
                codes[0..len],
                switch (kind) {
                    .literal => &predefined_literal_state_masks,
                    .offset => &predefined_offset_code_state_masks,
                    .match => &predefined_match_state_masks,
                },
                switch (kind) {
                    .literal => .literal,
                    .offset => .offset,
                    .match => .match,
                },
                actual_states[0..len],
                actual_masks[0..len],
            );
            try std.testing.expectEqual(expected, actual);
            if (expected) {
                try std.testing.expectEqualSlices(u8, expected_states[0..len], actual_states[0..len]);
                try std.testing.expectEqualSlices(u64, expected_masks[0..len], actual_masks[0..len]);
            }
            if (kind == .offset) {
                const compact = large_predefined.planOffset(
                    codes[0..len],
                    &predefined_offset_code_state_masks,
                    compact_states[0..len],
                    compact_masks[0..len],
                );
                try std.testing.expectEqual(expected, compact);
                if (expected) {
                    try std.testing.expectEqualSlices(u8, expected_states[0..len], compact_states[0..len]);
                    for (expected_masks[0..len], compact_masks[0..len]) |expected_mask, compact_mask|
                        try std.testing.expectEqual(@as(u32, @intCast(expected_mask)), compact_mask);
                }
            }
        }
    }
}

test "zstd native match stage benchmark mirrors production emitters" {
    const payload = ("{\"service\":\"vort\",\"message\":\"native stage benchmark\"}\n" ** 96) ++ ("abcdefghijklmnop" ** 32);
    var scratch: NativeMatchStageScratch = .{};
    defer scratch.deinit(std.testing.allocator);
    try std.testing.expect(try benchmarkPrepareNativeMatchStageScratch(std.testing.allocator, payload, 192, &scratch));

    inline for (std.meta.tags(NativeMatchStage)) |stage| {
        var expected: std.ArrayList(u8) = .empty;
        defer expected.deinit(std.testing.allocator);
        const expected_ok = switch (stage) {
            .mixed => try emitMixedDuplicateRepeatedMatchCompressedBlock(std.testing.allocator, &expected, payload, true, 192, scratch.duplicate_index, null),
            .double_fast => blk: {
                const stats = try double_fast_match.planReuse(&scratch.double_fast_tokens, std.testing.allocator, payload, zstdHashParserOptions(payload.len));
                break :blk try emitHashTokenSequenceBlock(std.testing.allocator, &expected, payload, true, scratch.double_fast_tokens.items, stats);
            },
            .greedy => try emitGreedyHashMatchCompressedBlockReuse(std.testing.allocator, &expected, payload, true, &scratch.greedy_tokens),
            .lazy => try emitLazyHashMatchCompressedBlockReuse(std.testing.allocator, &expected, payload, true, &scratch.lazy_tokens),
            .optimal => try emitOptimalHashMatchCompressedBlockReuse(std.testing.allocator, &expected, payload, true, &scratch.optimal),
            .rep_beam => blk: {
                const plan = try lz77.optimalRepBeamPlanAlloc(std.testing.allocator, payload, zstdHashParserOptions(payload.len));
                defer plan.deinit(std.testing.allocator);
                break :blk try emitHashTokenSequenceBlock(std.testing.allocator, &expected, payload, true, plan.tokens, plan.stats);
            },
            .rep_beam_single => blk: {
                var single_scratch: single_beam_match.Scratch = .{};
                defer single_scratch.deinit(std.testing.allocator);
                const stats = try single_beam_match.planReuse(&single_scratch, std.testing.allocator, payload);
                break :blk try emitHashTokenSequenceBlock(std.testing.allocator, &expected, payload, true, single_scratch.reversed.items, stats);
            },
            .repeated => try emitRepeatedPatternCompressedBlock(std.testing.allocator, &expected, payload, true),
            .multi_duplicate => try emitMultiDuplicateMatchCompressedBlock(std.testing.allocator, &expected, payload, true, scratch.duplicate_index),
            .single_duplicate => try emitSingleMatchCompressedBlock(std.testing.allocator, &expected, payload, true, scratch.duplicate_index),
        };
        const result = try benchmarkNativeMatchStage(std.testing.allocator, payload, true, 192, stage, &scratch);
        try std.testing.expectEqual(expected_ok, result.available);
        try std.testing.expectEqual(if (expected_ok) expected.items.len else 0, result.encoded_len);
        if (result.available) {
            try std.testing.expectEqual(result.encoded_len, 3 + result.literals_bytes + result.sequence_bytes);
        } else {
            try std.testing.expectEqual(@as(usize, 0), result.literals_bytes);
            try std.testing.expectEqual(@as(usize, 0), result.sequence_bytes);
        }
    }
}

