test "zstd decisive rep beam reuses multi first duplicate match wire" {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(std.testing.allocator);
    while (payload.items.len < 32 * 1024) {
        var line: [128]u8 = undefined;
        const index = payload.items.len / 64;
        const formatted = try std.fmt.bufPrint(&line, "{{\"id\":{d},\"service\":\"vort\",\"message\":\"structured zstd encode corpus\"}}\n", .{index});
        try payload.appendSlice(std.testing.allocator, formatted);
    }
    const plan = try lz77.optimalRepBeamPlanAlloc(std.testing.allocator, payload.items, zstdHashParserOptions(payload.items.len));
    defer plan.deinit(std.testing.allocator);
    var beam: std.ArrayList(u8) = .empty;
    defer beam.deinit(std.testing.allocator);
    try std.testing.expect(try emitHashTokenSequenceBlock(std.testing.allocator, &beam, payload.items, true, plan.tokens, plan.stats));
    try std.testing.expect(beam.items.len * 32 <= payload.items.len);

    var index: DuplicateMatchIndex = undefined;
    index.build(payload.items);
    const decisive_first = try findBestDuplicateMatchIndexed(payload.items, 0, &index) orelse return error.CorruptFrame;
    var multi: std.ArrayList(u8) = .empty;
    defer multi.deinit(std.testing.allocator);
    var first: ?DuplicateMatch = null;
    try std.testing.expect(try emitMultiDuplicateMatchCompressedBlockWithFirst(std.testing.allocator, &multi, payload.items, true, &index, &first));
    try std.testing.expectEqual(decisive_first, first orelse return error.CorruptFrame);

    var expected: std.ArrayList(u8) = .empty;
    defer expected.deinit(std.testing.allocator);
    try std.testing.expect(try emitSingleMatchCompressedBlock(std.testing.allocator, &expected, payload.items, true, &index));
    var actual: std.ArrayList(u8) = .empty;
    defer actual.deinit(std.testing.allocator);
    try std.testing.expect(try emitSingleMatchCompressedBlockFromMatch(std.testing.allocator, &actual, payload.items, true, decisive_first));
    try std.testing.expectEqualSlices(u8, expected.items, actual.items);
}

fn emitHashTokenSequenceBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
) Error!bool {
    var scratch: LargeSequenceScratch = .{};
    defer scratch.deinit(allocator);
    return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, tokens, stats, &scratch);
}

const LargeSequenceScratch = struct {
    values: std.ArrayList(usize) = .empty,
    states: std.ArrayList(u8) = .empty,
    viable_masks: std.ArrayList(u64) = .empty,
    codes: std.ArrayList(u8) = .empty,
    next_states: std.ArrayList(u8) = .empty,
    state_bits: std.ArrayList(u8) = .empty,
    transition_values: std.ArrayList(u8) = .empty,
    transition_bits: std.ArrayList(u8) = .empty,
    repeat_states: std.ArrayList(u16) = .empty,
    repeat_viable_masks: std.ArrayList(u64) = .empty,
    offset_extras: std.ArrayList(usize) = .empty,
    literals_prefix: std.ArrayList(u8) = .empty,
    payload: std.ArrayList(u8) = .empty,
    sequence_bits: std.ArrayList(u8) = .empty,
    direct_transitions: bool = false,

    fn deinit(self: *LargeSequenceScratch, allocator: std.mem.Allocator) void {
        self.sequence_bits.deinit(allocator);
        self.payload.deinit(allocator);
        self.literals_prefix.deinit(allocator);
        self.offset_extras.deinit(allocator);
        self.repeat_viable_masks.deinit(allocator);
        self.repeat_states.deinit(allocator);
        self.transition_bits.deinit(allocator);
        self.transition_values.deinit(allocator);
        self.state_bits.deinit(allocator);
        self.next_states.deinit(allocator);
        self.codes.deinit(allocator);
        self.viable_masks.deinit(allocator);
        self.states.deinit(allocator);
        self.values.deinit(allocator);
        self.* = .{};
    }
};

fn emitHashTokenSequenceBlockReuse(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    scratch: *LargeSequenceScratch,
) Error!bool {
    return try emitHashTokenSequenceBlockReuseWithState(allocator, out, block, last, tokens, stats, scratch, null, initial_repeated_offsets);
}

fn emitHashTokenSequenceBlockReuseForFrame(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    scratch: ?*LargeSequenceScratch,
    sequence_state: ?*const SequenceEncoderState,
) Error!bool {
    if (stats.matches <= max_native_sequence_count or sequence_state == null) {
        if (scratch) |large_scratch|
            return try emitHashTokenSequenceBlockReuse(allocator, out, block, last, tokens, stats, large_scratch);
        return try emitHashTokenSequenceBlock(allocator, out, block, last, tokens, stats);
    }
    const state = sequence_state.?;
    var local_scratch: LargeSequenceScratch = .{};
    defer if (scratch == null) local_scratch.deinit(allocator);
    return try emitHashTokenSequenceBlockReuseWithState(
        allocator,
        out,
        block,
        last,
        tokens,
        stats,
        scratch orelse &local_scratch,
        if (state.previous_tables) |*tables| tables else null,
        state.repeated_offsets,
    );
}

fn emitHashTokenSequenceBlockReuseWithState(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    scratch: *LargeSequenceScratch,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!bool {
    return try emitHashTokenSequenceBlockReuseWithStatePolicy(false, allocator, out, block, last, tokens, stats, scratch, previous_tables, initial_offsets);
}

fn emitHashTokenSequenceBlockReuseWithStatePolicy(
    comptime use_fast_cached_planner: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    scratch: *LargeSequenceScratch,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!bool {
    if (stats.matches < 2 or
        stats.matches > max_large_native_sequence_count or
        stats.matches > block.len / lz77.min_match_len) return false;
    if (stats.matches > max_native_sequence_count) {
        // Preserve the compact-block wire and allocation profile. The dynamic
        // path exists for wide Zstd blocks whose natural sequence count cannot
        // fit the legacy stack scratch. Small blocks retain their existing
        // bounded parser policy even if an unusually dense parse exceeds it.
        if (block.len <= 32 * 1024) return false;
        const value_count = std.math.mul(usize, stats.matches, 4) catch return error.IntegerOverflow;
        try scratch.values.resize(allocator, value_count);
        const literal_lens = scratch.values.items[0..stats.matches];
        const offsets = scratch.values.items[stats.matches .. stats.matches * 2];
        const match_lens = scratch.values.items[stats.matches * 2 .. stats.matches * 3];
        const literal_ends = scratch.values.items[stats.matches * 3 .. stats.matches * 4];
        return try emitLargeHashTokenSequenceBlockWithStatePolicy(
            use_fast_cached_planner,
            allocator,
            out,
            block,
            last,
            tokens,
            literal_lens,
            offsets,
            match_lens,
            literal_ends,
            scratch,
            previous_tables,
            initial_offsets,
        );
    }
    var literal_lens: [max_native_sequence_count]usize = undefined;
    var offsets: [max_native_sequence_count]usize = undefined;
    var match_lens: [max_native_sequence_count]usize = undefined;
    var literal_ends: [max_native_sequence_count]usize = undefined;
    var position: usize = 0;
    var literal_start: usize = 0;
    var count: usize = 0;
    for (tokens) |token| switch (token) {
        .literal => position += 1,
        .match => |match| {
            if (count == max_native_sequence_count) return false;
            literal_lens[count] = position - literal_start;
            offsets[count] = match.distance;
            match_lens[count] = match.length;
            position += match.length;
            literal_ends[count] = position;
            literal_start = position;
            count += 1;
        },
    };
    if (position != block.len or count < 2) return false;
    if (block.len <= small_sequence_stack_input_max) {
        @branchHint(.unlikely);
        return try emitBestSequenceCompressedBlockSmall(allocator, out, block, last, literal_lens[0..count], offsets[0..count], match_lens[0..count], literal_ends[0..count], literal_start);
    }
    return try emitBestSequenceCompressedBlock(allocator, out, block, last, literal_lens[0..count], offsets[0..count], match_lens[0..count], literal_ends[0..count], literal_start);
}

noinline fn emitLargeHashTokenSequenceBlockReuseFast(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    scratch: *LargeSequenceScratch,
) linksection(fast_encode_helper_text_section) Error!bool {
    std.debug.assert(stats.matches > max_native_sequence_count);
    const previous_direct = scratch.direct_transitions;
    scratch.direct_transitions = !builtin.is_test or !test_disable_fast_large_direct_transitions;
    defer scratch.direct_transitions = previous_direct;
    if (comptime builtin.is_test) if (test_disable_fast_large_cached_planner)
        return try emitHashTokenSequenceBlockReuseWithStatePolicy(
            false,
            allocator,
            out,
            block,
            last,
            tokens,
            stats,
            scratch,
            null,
            initial_repeated_offsets,
        );
    return try emitHashTokenSequenceBlockReuseWithStatePolicy(
        true,
        allocator,
        out,
        block,
        last,
        tokens,
        stats,
        scratch,
        null,
        initial_repeated_offsets,
    );
}

const FastMatchCandidateResult = struct {
    match_ok: bool,
    use_fast_large_planner: bool,
    used_sequence_records: bool,
};

noinline fn emitFastMatchCandidate(
    allocator: std.mem.Allocator,
    candidate: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    large_sequence_scratch: *LargeSequenceScratch,
    scratch: *NativeBlockEncodeScratch,
) linksection(fast_encode_helper_text_section) Error!FastMatchCandidateResult {
    const parser_options = zstdHashParserOptions(block.len);
    if (block.len >= double_fast_match.sequence_plan_input_min and
        (!builtin.is_test or !test_disable_fast_sequence_records))
    {
        return try emitFastSequenceRecordCandidate(
            allocator,
            candidate,
            block,
            last,
            large_sequence_scratch,
            scratch,
            parser_options,
        );
    }
    const stats: lz77.PlanStats = double_fast_match.planReuse(&scratch.greedy_tokens, allocator, block, parser_options) catch |err| switch (err) {
        error.InvalidBlockPlan => lz77.PlanStats{},
        else => return err,
    };
    const use_fast_large_planner = stats.matches > max_native_sequence_count;
    const match_ok = stats.matches != 0 and if (use_fast_large_planner)
        try emitLargeHashTokenSequenceBlockReuseFast(
            allocator,
            candidate,
            block,
            last,
            scratch.greedy_tokens.items,
            stats,
            large_sequence_scratch,
        )
    else
        try emitHashTokenSequenceBlockReuse(
            allocator,
            candidate,
            block,
            last,
            scratch.greedy_tokens.items,
            stats,
            large_sequence_scratch,
        );
    return .{
        .match_ok = match_ok,
        .use_fast_large_planner = use_fast_large_planner,
        .used_sequence_records = false,
    };
}

noinline fn emitFastSequenceRecordCandidate(
    allocator: std.mem.Allocator,
    candidate: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    large_sequence_scratch: *LargeSequenceScratch,
    scratch: *NativeBlockEncodeScratch,
    parser_options: lz77.GreedyOptions,
) linksection(fast_sequence_record_text_section) Error!FastMatchCandidateResult {
    const stats: lz77.PlanStats = double_fast_match.planSequencesReuse(
        &large_sequence_scratch.viable_masks,
        allocator,
        block,
        parser_options,
    ) catch |err| switch (err) {
        error.InvalidBlockPlan => lz77.PlanStats{},
        else => return err,
    };
    const use_fast_large_planner = stats.matches > max_native_sequence_count;
    if (!use_fast_large_planner and stats.matches != 0)
        if (!try double_fast_sequence_plan.materializeTokens(
            &scratch.greedy_tokens,
            allocator,
            block,
            large_sequence_scratch.viable_masks.items,
        )) return error.CorruptFrame;
    const match_ok = stats.matches != 0 and if (use_fast_large_planner)
        try emitLargeDoubleFastSequenceBlockReuseFast(
            allocator,
            candidate,
            block,
            last,
            large_sequence_scratch.viable_masks.items,
            stats,
            large_sequence_scratch,
        )
    else
        try emitHashTokenSequenceBlockReuse(
            allocator,
            candidate,
            block,
            last,
            scratch.greedy_tokens.items,
            stats,
            large_sequence_scratch,
        );
    return .{
        .match_ok = match_ok,
        .use_fast_large_planner = use_fast_large_planner,
        .used_sequence_records = true,
    };
}

noinline fn emitLargeDoubleFastSequenceBlockReuseFast(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    records: []const double_fast_sequence_plan.Record,
    stats: lz77.PlanStats,
    scratch: *LargeSequenceScratch,
) linksection(fast_sequence_record_text_section) Error!bool {
    const prepared = try large_sequence_record_values.prepare(
        &scratch.values,
        allocator,
        records,
        block.len,
        stats,
        max_native_sequence_count,
    ) orelse return false;

    const previous_direct = scratch.direct_transitions;
    scratch.direct_transitions = !builtin.is_test or !test_disable_fast_large_direct_transitions;
    defer scratch.direct_transitions = previous_direct;
    if (comptime builtin.is_test) if (test_disable_fast_large_cached_planner)
        return try emitLargeSequenceCompressedBlockWithStatePolicy(
            false,
            allocator,
            out,
            block,
            last,
            prepared.literal_lens,
            prepared.offsets,
            prepared.match_lens,
            prepared.literal_ends,
            prepared.tail_start,
            scratch,
            null,
            initial_repeated_offsets,
        );
    return try emitLargeSequenceCompressedBlockWithStatePolicy(
        true,
        allocator,
        out,
        block,
        last,
        prepared.literal_lens,
        prepared.offsets,
        prepared.match_lens,
        prepared.literal_ends,
        prepared.tail_start,
        scratch,
        null,
        initial_repeated_offsets,
    );
}

fn hashTokenSequenceBlockLowerBound(
    block: []const u8,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
) Error!?usize {
    if (stats.matches < 2 or stats.matches > max_native_sequence_count) return null;

    var frequencies: [256]u32 = @splat(0);
    var active_symbols: [256]u8 = undefined;
    var active_count: usize = 0;
    var position: usize = 0;
    var sequence_count: usize = 0;
    var sequence_extra_bits: usize = 0;
    var literal_len: usize = 0;
    var repeated_offsets = initial_repeated_offsets;
    for (tokens) |token| switch (token) {
        .literal => |literal| {
            if (position >= block.len or block[position] != literal) return error.CorruptFrame;
            frequencies[literal] += 1;
            position += 1;
            literal_len += 1;
        },
        .match => |match| {
            if (match.length < lz77.min_match_len or match.distance == 0 or match.distance > position or
                match.length > block.len - position) return error.CorruptFrame;
            const literal_code = try sequenceCodeForValue(literal_len, &ll_base, &ll_bits);
            const match_code = try sequenceCodeForValue(match.length, &ml_base, &ml_bits);
            const offset_code = try chooseOffsetSequenceCode(literal_len, match.distance, &repeated_offsets);
            const literal_extra_bits = ll_bits[literal_code];
            const match_extra_bits = ml_bits[match_code];
            const direct_offset_code = try sequenceCodeForValue(match.distance, &of_base, &of_bits);
            const offset_extra_bits = @min(of_bits[offset_code], of_bits[direct_offset_code]);
            sequence_extra_bits = std.math.add(usize, sequence_extra_bits, literal_extra_bits) catch return error.IntegerOverflow;
            sequence_extra_bits = std.math.add(usize, sequence_extra_bits, match_extra_bits) catch return error.IntegerOverflow;
            sequence_extra_bits = std.math.add(usize, sequence_extra_bits, offset_extra_bits) catch return error.IntegerOverflow;
            position += match.length;
            sequence_count += 1;
            literal_len = 0;
        },
    };
    if (position != block.len or sequence_count != stats.matches) return error.CorruptFrame;

    var regenerated_literals: usize = 0;
    for (frequencies, 0..) |frequency, symbol| {
        regenerated_literals += frequency;
        if (frequency == 0) continue;
        active_symbols[active_count] = @intCast(symbol);
        active_count += 1;
    }
    var literal_payload_lower_bound: usize = regenerated_literals;
    if (active_count == 1) {
        literal_payload_lower_bound = 1;
    } else if (active_count > 1) {
        const lengths = huffman.treeCodeLengthsKnownActive(
            256,
            &frequencies,
            11,
            active_symbols[0..active_count],
        );
        var huffman_bits: usize = 0;
        for (active_symbols[0..active_count]) |symbol| {
            huffman_bits = std.math.add(
                usize,
                huffman_bits,
                std.math.mul(usize, frequencies[symbol], lengths[symbol]) catch return error.IntegerOverflow,
            ) catch return error.IntegerOverflow;
        }
        literal_payload_lower_bound = @min(literal_payload_lower_bound, (huffman_bits + 7) / 8);
    }

    var lower_bound: usize = 3; // Compressed block header.
    lower_bound = std.math.add(usize, lower_bound, literal_payload_lower_bound) catch return error.IntegerOverflow;
    lower_bound = std.math.add(usize, lower_bound, try sequenceCountLen(sequence_count)) catch return error.IntegerOverflow;
    lower_bound = std.math.add(usize, lower_bound, 1) catch return error.IntegerOverflow; // Sequence mode byte.
    lower_bound = std.math.add(usize, lower_bound, (sequence_extra_bits + 1 + 7) / 8) catch return error.IntegerOverflow;
    return lower_bound;
}

fn minimumPredefinedSequenceExtraBits(value: usize, symbols: []const SequenceSymbol, min_additional_bits: u8) u8 {
    var minimum: u8 = std.math.maxInt(u8);
    for (symbols) |symbol| {
        if (predefinedSymbolCanEncode(symbol, value, min_additional_bits))
            minimum = @min(minimum, symbol.additional_bits);
    }
    return minimum;
}

test "zstd direct sequence codes lower-bound predefined extra bits" {
    for (0..std.math.maxInt(u17) + 1) |value| {
        const code = sequenceCodeForValue(value, &ll_base, &ll_bits) catch continue;
        try std.testing.expect(ll_bits[code] <= minimumPredefinedSequenceExtraBits(
            value,
            &sequence_predefined.literal_symbols,
            0,
        ));
    }
    for (lz77.min_match_len..lz77.max_match_len + 1) |value| {
        const code = try sequenceCodeForValue(value, &ml_base, &ml_bits);
        try std.testing.expect(ml_bits[code] <= minimumPredefinedSequenceExtraBits(
            value,
            &sequence_predefined.match_symbols,
            0,
        ));
    }
    for (1..lz77.default_window_len + 1) |value| {
        const code = try sequenceCodeForValue(value, &of_base, &of_bits);
        const cached = try large_fast_plan.valueField(&.{code}, &of_base, &of_bits, 0);
        const symbol = try sequenceRleSymbol(.offset, code);
        try std.testing.expectEqual(@as(usize, symbol.base), cached.base);
        try std.testing.expectEqual(symbol.additional_bits, cached.additional_bits);
        try std.testing.expect(of_bits[code] <= minimumPredefinedSequenceExtraBits(
            value,
            &sequence_predefined.offset_symbols,
            2,
        ));
    }
}

fn hashTokenSequenceCannotBeat(
    block: []const u8,
    tokens: []const lz77.Token,
    stats: lz77.PlanStats,
    best_len: usize,
) Error!bool {
    if (comptime builtin.is_test) if (test_disable_hash_token_lower_bound) return false;
    const lower_bound = (try hashTokenSequenceBlockLowerBound(block, tokens, stats)) orelse return false;
    const cannot_beat = lower_bound > best_len;
    if (comptime builtin.is_test) test_hash_token_lower_bound_hits += @intFromBool(cannot_beat);
    return cannot_beat;
}

fn emitLargeHashTokenSequenceBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    literal_lens: []usize,
    offsets: []usize,
    match_lens: []usize,
    literal_ends: []usize,
    scratch: *LargeSequenceScratch,
) Error!bool {
    return try emitLargeHashTokenSequenceBlockWithState(
        allocator,
        out,
        block,
        last,
        tokens,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        scratch,
        null,
        initial_repeated_offsets,
    );
}

fn emitLargeHashTokenSequenceBlockWithState(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    literal_lens: []usize,
    offsets: []usize,
    match_lens: []usize,
    literal_ends: []usize,
    scratch: *LargeSequenceScratch,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!bool {
    return try emitLargeHashTokenSequenceBlockWithStatePolicy(false, allocator, out, block, last, tokens, literal_lens, offsets, match_lens, literal_ends, scratch, previous_tables, initial_offsets);
}

fn emitLargeHashTokenSequenceBlockWithStatePolicy(
    comptime use_fast_cached_planner: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    tokens: []const lz77.Token,
    literal_lens: []usize,
    offsets: []usize,
    match_lens: []usize,
    literal_ends: []usize,
    scratch: *LargeSequenceScratch,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!bool {
    const output_start = out.items.len;
    errdefer out.items.len = output_start;
    const sequence_count = literal_lens.len;
    if (sequence_count <= max_native_sequence_count or
        sequence_count > max_large_native_sequence_count or
        offsets.len != sequence_count or
        match_lens.len != sequence_count or
        literal_ends.len != sequence_count) return false;

    var position: usize = 0;
    var literal_start: usize = 0;
    var count: usize = 0;
    for (tokens) |token| switch (token) {
        .literal => {
            position = std.math.add(usize, position, 1) catch return false;
            if (position > block.len) return false;
        },
        .match => |match| {
            if (count == sequence_count or match.length < lz77.min_match_len or match.distance == 0) return false;
            literal_lens[count] = position - literal_start;
            offsets[count] = match.distance;
            match_lens[count] = match.length;
            position = std.math.add(usize, position, match.length) catch return false;
            if (position > block.len) return false;
            literal_ends[count] = position;
            literal_start = position;
            count += 1;
        },
    };
    if (position != block.len or count != sequence_count) return false;

    return try emitLargeSequenceCompressedBlockWithStatePolicy(
        use_fast_cached_planner,
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        literal_start,
        scratch,
        previous_tables,
        initial_offsets,
    );
}

