    return try emitLargeSequenceCompressedBlockWithStatePolicy(false, allocator, out, block, last, literal_lens, offsets, match_lens, literal_ends, tail_start, scratch, previous_tables, initial_offsets);
}

fn emitLargeSequenceCompressedBlockWithStatePolicy(
    comptime use_fast_cached_planner: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    scratch: *LargeSequenceScratch,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!bool {
    const sequence_count = literal_lens.len;
    if (sequence_count <= max_native_sequence_count or
        sequence_count > max_large_native_sequence_count or
        offsets.len != sequence_count or
        match_lens.len != sequence_count or
        literal_ends.len != sequence_count) return false;

    scratch.literals_prefix.clearRetainingCapacity();
    _ = try emitSequenceLiteralsSection(
        allocator,
        &scratch.literals_prefix,
        block,
        literal_lens,
        literal_ends,
        tail_start,
    );

    const state_len = std.math.mul(usize, sequence_count, 3) catch return error.IntegerOverflow;
    try scratch.states.resize(allocator, state_len);
    try scratch.viable_masks.resize(allocator, sequence_count);
    try scratch.codes.resize(allocator, state_len);
    try scratch.next_states.resize(allocator, state_len);
    try scratch.state_bits.resize(allocator, state_len);
    try scratch.transition_values.resize(allocator, state_len);
    try scratch.transition_bits.resize(allocator, state_len);
    const repeat_mask_words = if (previous_tables) |tables| @max(
        try repeatSequenceMaskWordCount(previousSequenceTable(tables, .literal)),
        @max(
            try repeatSequenceMaskWordCount(previousSequenceTable(tables, .offset)),
            try repeatSequenceMaskWordCount(previousSequenceTable(tables, .match)),
        ),
    ) else 0;
    const repeat_mask_len = std.math.mul(usize, sequence_count, repeat_mask_words) catch return error.IntegerOverflow;
    if (previous_tables != null) {
        try scratch.repeat_states.resize(allocator, state_len);
        try scratch.repeat_viable_masks.resize(allocator, repeat_mask_len);
    }
    try scratch.offset_extras.resize(allocator, sequence_count);
    const literal_states = scratch.states.items[0..sequence_count];
    const offset_states = scratch.states.items[sequence_count .. sequence_count * 2];
    const match_states = scratch.states.items[sequence_count * 2 .. sequence_count * 3];
    const repeat_states = if (previous_tables != null) scratch.repeat_states.items[0..state_len] else scratch.repeat_states.items[0..0];
    const repeat_viable_masks = if (previous_tables != null) scratch.repeat_viable_masks.items[0..repeat_mask_len] else scratch.repeat_viable_masks.items[0..0];
    const literal_repeat_states = if (previous_tables != null) repeat_states[0..sequence_count] else repeat_states;
    const offset_repeat_states = if (previous_tables != null) repeat_states[sequence_count .. sequence_count * 2] else repeat_states;
    const match_repeat_states = if (previous_tables != null) repeat_states[sequence_count * 2 .. sequence_count * 3] else repeat_states;
    const literal_compressed = LargeCompressedSequenceBuffers{
        .direct_transitions = scratch.direct_transitions,
        .codes = scratch.codes.items[0..sequence_count],
        .next_states = scratch.next_states.items[0..sequence_count],
        .state_bits = scratch.state_bits.items[0..sequence_count],
        .transition_values = scratch.transition_values.items[0..sequence_count],
        .transition_bits = scratch.transition_bits.items[0..sequence_count],
    };
    const offset_compressed = LargeCompressedSequenceBuffers{
        .direct_transitions = scratch.direct_transitions,
        .codes = scratch.codes.items[sequence_count .. sequence_count * 2],
        .next_states = scratch.next_states.items[sequence_count .. sequence_count * 2],
        .state_bits = scratch.state_bits.items[sequence_count .. sequence_count * 2],
        .transition_values = scratch.transition_values.items[sequence_count .. sequence_count * 2],
        .transition_bits = scratch.transition_bits.items[sequence_count .. sequence_count * 2],
    };
    const match_compressed = LargeCompressedSequenceBuffers{
        .direct_transitions = scratch.direct_transitions,
        .codes = scratch.codes.items[sequence_count * 2 .. sequence_count * 3],
        .next_states = scratch.next_states.items[sequence_count * 2 .. sequence_count * 3],
        .state_bits = scratch.state_bits.items[sequence_count * 2 .. sequence_count * 3],
        .transition_values = scratch.transition_values.items[sequence_count * 2 .. sequence_count * 3],
        .transition_bits = scratch.transition_bits.items[sequence_count * 2 .. sequence_count * 3],
    };
    const literal_alternatives = try largeSequenceTablePlanAlternatives(
        literal_lens,
        .literal,
        literal_states,
        scratch.viable_masks.items,
        literal_compressed,
        literal_repeat_states,
        repeat_viable_masks,
        if (previous_tables) |tables| previousSequenceTable(tables, .literal) else null,
    );
    const offset_alternatives = try largeOffsetSequenceTablePlanAlternatives(
        literal_lens,
        offsets,
        offset_states,
        scratch.viable_masks.items,
        offset_compressed,
        offset_repeat_states,
        repeat_viable_masks,
        if (previous_tables) |tables| previousSequenceTable(tables, .offset) else null,
        initial_offsets,
    );
    const match_alternatives = try largeSequenceTablePlanAlternatives(
        match_lens,
        .match,
        match_states,
        scratch.viable_masks.items,
        match_compressed,
        match_repeat_states,
        repeat_viable_masks,
        if (previous_tables) |tables| previousSequenceTable(tables, .match) else null,
    );
    const plan = (if (comptime use_fast_cached_planner)
        try bestLargeSequenceTablePlanFast(
            literal_lens,
            offsets,
            match_lens,
            scratch.literals_prefix.items.len,
            literal_alternatives,
            offset_alternatives,
            match_alternatives,
            literal_compressed.codes,
            offset_compressed.codes,
            match_compressed.codes,
        )
    else
        try bestLargeSequenceTablePlan(
            literal_lens,
            offsets,
            match_lens,
            scratch.literals_prefix.items.len,
            literal_alternatives,
            offset_alternatives,
            match_alternatives,
            initial_offsets,
        )) orelse return false;

    scratch.payload.clearRetainingCapacity();
    try scratch.payload.appendSlice(allocator, scratch.literals_prefix.items);
    try emitSequenceCount(allocator, &scratch.payload, sequence_count);
    try scratch.payload.append(allocator, largeSequenceModeByte(plan.plan));
    try appendLargeSequenceTablePayload(allocator, &scratch.payload, &plan.plan.literal);
    try appendLargeSequenceTablePayload(allocator, &scratch.payload, &plan.plan.offset);
    try appendLargeSequenceTablePayload(allocator, &scratch.payload, &plan.plan.match);

    scratch.sequence_bits.clearRetainingCapacity();
    var writer: ReverseBitstreamWriter = .{};
    var repeated_offsets = initial_offsets;
    // Offset selectors update in forward sequence order. Resolve and retain
    // their extra-bit values before writing the bitstream in reverse order.
    const offset_extras = scratch.offset_extras.items;
    for (0..sequence_count) |sequence_index| {
        const offset_symbol = try largeSequenceTableSymbol(&plan.plan.offset, .offset, sequence_index);
        offset_extras[sequence_index] = try sequenceOffsetExtraForEncodedOffset(
            offset_symbol,
            literal_lens[sequence_index],
            offsets[sequence_index],
            &repeated_offsets,
        );
    }
    var i = sequence_count;
    while (i > 0) {
        i -= 1;
        const literal_value = if (comptime use_fast_cached_planner)
            try large_fast_plan.valueField(literal_compressed.codes, &ll_base, &ll_bits, i)
        else value: {
            const symbol = try largeSequenceTableSymbol(&plan.plan.literal, .literal, i);
            break :value large_fast_plan.ValueField{ .base = symbol.base, .additional_bits = symbol.additional_bits };
        };
        const offset_symbol = if (comptime use_fast_cached_planner) symbol: {
            const value = try large_fast_plan.valueField(offset_compressed.codes, &of_base, &of_bits, i);
            break :symbol SequenceSymbol{
                .base = @intCast(value.base),
                .additional_bits = value.additional_bits,
                .next_state = 0,
                .state_bits = 0,
            };
        } else try largeSequenceTableSymbol(&plan.plan.offset, .offset, i);
        const match_value = if (comptime use_fast_cached_planner)
            try large_fast_plan.valueField(match_compressed.codes, &ml_base, &ml_bits, i)
        else value: {
            const symbol = try largeSequenceTableSymbol(&plan.plan.match, .match, i);
            break :value large_fast_plan.ValueField{ .base = symbol.base, .additional_bits = symbol.additional_bits };
        };

        if (i + 1 < sequence_count) {
            try appendLargeSequenceTransitionBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.offset, .offset, i);
            try appendLargeSequenceTransitionBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.match, .match, i);
            try appendLargeSequenceTransitionBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.literal, .literal, i);
        }
        try addCheckedReverseBits(&writer, allocator, &scratch.sequence_bits, literal_lens[i] - literal_value.base, literal_value.additional_bits);
        try addCheckedReverseBits(&writer, allocator, &scratch.sequence_bits, match_lens[i] - match_value.base, match_value.additional_bits);
        try addCheckedReverseBits(&writer, allocator, &scratch.sequence_bits, offset_extras[i], offset_symbol.additional_bits);
    }
    try appendLargeInitialSequenceStateBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.match, .match);
    try appendLargeInitialSequenceStateBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.offset, .offset);
    try appendLargeInitialSequenceStateBits(&writer, allocator, &scratch.sequence_bits, &plan.plan.literal, .literal);
    try writer.finish(allocator, &scratch.sequence_bits);
    try scratch.payload.appendSlice(allocator, scratch.sequence_bits.items);
    if (scratch.payload.items.len != plan.payload_len) return error.CorruptFrame;

    const raw_block_len = std.math.add(usize, 3, block.len) catch return error.IntegerOverflow;
    if (scratch.payload.items.len + 3 >= raw_block_len) return false;
    try emitBlockHeader(allocator, out, 2, scratch.payload.items.len, last);
    try out.appendSlice(allocator, scratch.payload.items);
    // The encoded candidate no longer needs its per-sequence offset extras.
    // Retain the final repcode ring in their first three slots for the
    // fast-frame commit path without enlarging the shared scratch object.
    scratch.offset_extras.items[0..3].* = repeated_offsets;
    return true;
}

fn emitDictionaryMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    dictionary: NativeDictionary,
    frame_offset: usize,
    match_search_budget: usize,
) Error!bool {
    var mixed_block: std.ArrayList(u8) = .empty;
    defer mixed_block.deinit(allocator);
    const mixed_ok = try emitMixedDictionaryDuplicateMatchCompressedBlock(allocator, &mixed_block, block, last, dictionary, frame_offset, match_search_budget);

    var multi_block: std.ArrayList(u8) = .empty;
    defer multi_block.deinit(allocator);
    const multi_ok = try emitMultiDictionaryMatchCompressedBlock(allocator, &multi_block, block, last, dictionary, frame_offset);

    var single_block: std.ArrayList(u8) = .empty;
    defer single_block.deinit(allocator);
    const single_ok = try emitSingleDictionaryMatchCompressedBlock(allocator, &single_block, block, last, dictionary, frame_offset);

    var best: ?[]const u8 = null;
    var best_len: usize = std.math.maxInt(usize);
    chooseShortestPlannedBlock(mixed_ok, mixed_block.items, &best, &best_len);
    chooseShortestPlannedBlock(multi_ok, multi_block.items, &best, &best_len);
    chooseShortestPlannedBlock(single_ok, single_block.items, &best, &best_len);

    const best_block = best orelse return false;
    try out.appendSlice(allocator, best_block);
    return true;
}

fn chooseShortestPlannedBlock(ok: bool, block: []const u8, best: *?[]const u8, best_len: *usize) void {
    if (!ok or block.len >= best_len.*) return;
    best.* = block;
    best_len.* = block.len;
}

fn emitFrameHistoryMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    history: incremental_history.View,
    current: ?*const SequenceEncoderState,
) Error!bool {
    const plan = incremental_history_match.findPlan(history, block);
    if (plan.len == 0) return false;
    var literal_lens: [incremental_history_match.max_matches]usize = undefined;
    var offsets: [incremental_history_match.max_matches]usize = undefined;
    var match_lens: [incremental_history_match.max_matches]usize = undefined;
    var literal_ends: [incremental_history_match.max_matches]usize = undefined;
    var literal_start: usize = 0;
    for (plan.slice(), 0..) |match, i| {
        literal_lens[i] = match.block_start - literal_start;
        offsets[i] = match.offset(history.bytes.len) orelse return error.IntegerOverflow;
        match_lens[i] = match.len;
        literal_ends[i] = match.block_start + match.len;
        literal_start = literal_ends[i];
    }
    if (current) |sequence_state| {
        // Match prepareSequenceCandidateForFrame's initial-state fast path so
        // frames whose earlier blocks did not establish sequence state retain
        // their existing RLE/predefined tie behavior.
        if (sequence_state.previous_tables != null or
            !std.meta.eql(sequence_state.repeated_offsets, initial_repeated_offsets))
        {
            return try replaceSequenceCandidateWithFrameState(
                allocator,
                out,
                block,
                last,
                literal_lens[0..plan.len],
                offsets[0..plan.len],
                match_lens[0..plan.len],
                literal_ends[0..plan.len],
                literal_start,
                sequence_state,
            );
        }
    }
    return try emitBestSequenceCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens[0..plan.len],
        offsets[0..plan.len],
        match_lens[0..plan.len],
        literal_ends[0..plan.len],
        literal_start,
    );
}

fn emitSingleDictionaryMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    dictionary: NativeDictionary,
    frame_offset: usize,
) Error!bool {
    const match = findDictionaryMatch(dictionary.content, block, frame_offset) orelse return false;
    const literal_len = match.block_start;
    const match_offset = try dictionaryMatchOffset(dictionary.content.len, frame_offset, match);
    const tail_start = match.block_start + match.len;
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{match_offset};
    const match_lens = [_]usize{match.len};
    const literal_ends = [_]usize{tail_start};
    return try emitBestSequenceCompressedBlock(allocator, out, block, last, &literal_lens, &offsets, &match_lens, &literal_ends, tail_start);
}

const MixedMatchKind = enum { dictionary, duplicate, repeated };

const MixedMatchCandidate = struct {
    literal_len: usize,
    offset: usize,
    match_len: usize,
    literal_end: usize,
    payload_len: usize,
    kind: MixedMatchKind,
};

const MixedMatchKindSet = struct {
    dictionary: bool = false,
    duplicate: bool = false,
    repeated: bool = false,

    fn contains(self: MixedMatchKindSet, kind: MixedMatchKind) bool {
        return switch (kind) {
            .dictionary => self.dictionary,
            .duplicate => self.duplicate,
            .repeated => self.repeated,
        };
    }

    fn eql(self: MixedMatchKindSet, other: MixedMatchKindSet) bool {
        return self.dictionary == other.dictionary and
            self.duplicate == other.duplicate and
            self.repeated == other.repeated;
    }
};

const MixedMatchRequirement = union(enum) {
    kind: MixedMatchKind,
    non_dictionary,
};

const MixedMatchLookaheadRequirements = struct {
    first: MixedMatchRequirement,
    second: MixedMatchRequirement,
};

const MixedLiteralHistogram = struct {
    frequencies: [256]u32 = .{0} ** 256,
    regenerated_len: usize = 0,
    unique_count: usize = 0,
    max_symbol: u8 = 0,

    fn init(bytes: []const u8) MixedLiteralHistogram {
        var histogram: MixedLiteralHistogram = .{};
        histogram.add(bytes);
        return histogram;
    }

    fn remove(self: *MixedLiteralHistogram, bytes: []const u8) void {
        self.regenerated_len -= bytes.len;
        for (bytes) |byte| {
            std.debug.assert(self.frequencies[byte] != 0);
            self.frequencies[byte] -= 1;
            if (self.frequencies[byte] == 0) self.unique_count -= 1;
        }
        if (self.unique_count == 0) {
            self.max_symbol = 0;
        } else if (self.frequencies[self.max_symbol] == 0) {
            var symbol: usize = self.max_symbol;
            while (self.frequencies[symbol] == 0) symbol -= 1;
            self.max_symbol = @intCast(symbol);
        }
    }

    fn add(self: *MixedLiteralHistogram, bytes: []const u8) void {
        for (bytes) |byte| {
            if (self.frequencies[byte] == 0) self.unique_count += 1;
            self.frequencies[byte] += 1;
            self.max_symbol = @max(self.max_symbol, byte);
        }
        self.regenerated_len += bytes.len;
    }
};

const MixedHuffmanBitPrefix = struct {
    bit_counts: [256]u8 = @splat(0),
    prefix: [std.compress.zstd.block_size_max + 1]u32 = undefined,
    block_len: usize = 0,
    valid: bool = false,

    fn prepare(self: *MixedHuffmanBitPrefix, block: []const u8, plan: *const SmallHuffmanLiteralPlan) Error!void {
        if (block.len > std.compress.zstd.block_size_max) return error.CorruptFrame;
        if (self.valid and self.block_len == block.len and std.mem.eql(u8, &self.bit_counts, &plan.bit_counts)) return;
        self.prefix[0] = 0;
        var total: u32 = 0;
        for (block, 0..) |byte, i| {
            total += plan.bit_counts[byte];
            self.prefix[i + 1] = total;
        }
        self.bit_counts = plan.bit_counts;
        self.block_len = block.len;
        self.valid = true;
    }

    fn range(self: *const MixedHuffmanBitPrefix, start: usize, len: usize) Error!usize {
        if (!self.valid or start > self.block_len or len > self.block_len - start) return error.CorruptFrame;
        return self.prefix[start + len] - self.prefix[start];
    }
};

fn emitMixedDictionaryDuplicateMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    dictionary: NativeDictionary,
    frame_offset: usize,
    match_search_budget: usize,
) Error!bool {
    const plan = try bestMixedMatchLookaheadPlan(dictionary.content, block, frame_offset, .{
        .dictionary = true,
        .duplicate = true,
        .repeated = true,
    }, .{ .kind = .dictionary }, .non_dictionary, match_search_budget, null, null) orelse return false;
    return try emitBestSequenceCompressedBlockFromLookaheadPlan(
        allocator,
        out,
        block,
        last,
        plan,
    );
}

fn emitMixedDuplicateRepeatedMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    match_search_budget: usize,
    duplicate_index: ?*DuplicateMatchIndex,
    cancelled: ?*const std.atomic.Value(bool),
) Error!bool {
    const plan = try bestMixedMatchLookaheadPlan(&.{}, block, 0, .{
        .dictionary = false,
        .duplicate = true,
        .repeated = true,
    }, .{ .kind = .duplicate }, .{ .kind = .repeated }, match_search_budget, duplicate_index, cancelled) orelse return false;
    return try emitBestSequenceCompressedBlockFromLookaheadPlan(
        allocator,
        out,
        block,
        last,
        plan,
    );
}

fn emitBestSequenceCompressedBlockFromLookaheadPlan(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    plan: MixedMatchLookaheadPlan,
) Error!bool {
    return try emitBestSequenceCompressedBlock(
        allocator,
        out,
        block,
        last,
        plan.literal_lens[0..plan.count],
        plan.offsets[0..plan.count],
        plan.match_lens[0..plan.count],
        plan.literal_ends[0..plan.count],
        plan.tail_start,
    );
}

fn dictionaryMixedMatchCandidate(
    dictionary: []const u8,
    block: []const u8,
    literal_start: usize,
    frame_offset: usize,
) Error!?MixedMatchCandidate {
    const match = findDictionaryMatchIn(dictionary, block, literal_start, frame_offset) orelse return null;
    const payload_len = dictionaryMatchPayloadLenFrom(block, match, literal_start, frame_offset, dictionary.len) orelse return null;
    return .{
        .literal_len = match.block_start - literal_start,
        .offset = try dictionaryMatchOffset(dictionary.len, frame_offset, match),
        .match_len = match.len,
        .literal_end = match.block_start + match.len,
        .payload_len = payload_len,
        .kind = .dictionary,
    };
}

fn duplicateMixedMatchCandidate(
    block: []const u8,
    literal_start: usize,
    duplicate_index: ?*DuplicateMatchIndex,
    cancelled: ?*const std.atomic.Value(bool),
) Error!?MixedMatchCandidate {
    const best = if (duplicate_index) |index|
        try findBestDuplicateMatchIndexedCancellable(block, literal_start, index, cancelled)
    else
        try findBestDuplicateMatchIn(block, literal_start);
    if (best) |match| {
        return .{
            .literal_len = match.second_start - literal_start,
            .offset = match.second_start - match.first_start,
            .match_len = match.len,
            .literal_end = match.second_start + match.len,
            .payload_len = match.payload_len,
            .kind = .duplicate,
        };
    }
    return null;
}

fn repeatedMixedMatchCandidate(block: []const u8, literal_start: usize) ?MixedMatchCandidate {
    if (findRepeatedPatternSegmentIn(block, literal_start, block.len)) |segment| {
        if (repeatedPatternPayloadLenFrom(block, segment, literal_start)) |payload_len| {
            const literal_len = segment.start - literal_start + segment.period;
            return .{
                .literal_len = literal_len,
                .offset = segment.period,
                .match_len = segment.match_len,
                .literal_end = segment.start + segment.period + segment.match_len,
                .payload_len = payload_len,
                .kind = .repeated,
            };
        }
    }
    return null;
}

fn mixedCandidateLookaheadPayloadLen(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    candidate: MixedMatchCandidate,
) Error!?usize {
    const plan = try bestMixedCandidateLookaheadPlanFromFirst(
        dictionary,
        block,
        frame_offset,
        .{ .dictionary = true, .duplicate = true, .repeated = true },
        null,
        candidate,
    ) orelse return null;
    return plan.payload_len;
}

const MixedMatchLookaheadPlan = struct {
    literal_lens: [max_bootstrap_sequence_count]usize = undefined,
    offsets: [max_bootstrap_sequence_count]usize = undefined,
    match_lens: [max_bootstrap_sequence_count]usize = undefined,
    literal_ends: [max_bootstrap_sequence_count]usize = undefined,
    kinds: [max_bootstrap_sequence_count]MixedMatchKind = undefined,
    count: usize = 0,
    tail_start: usize = 0,
    payload_len: usize = 0,
};

const MixedMatchCandidateCacheEntry = struct {
    literal_start: usize = 0,
    allowed: MixedMatchKindSet = .{},
    candidates: [mixed_candidates_per_position]MixedMatchCandidate = undefined,
    count: usize = 0,
};

const mixed_candidate_cache_slot_count = 1024;
const mixed_candidate_cache_invalid = std.math.maxInt(u16);

const MixedMatchCandidateCache = struct {
    entries: [mixed_match_path_search_budget]MixedMatchCandidateCacheEntry = undefined,
    slots: [mixed_candidate_cache_slot_count]u16 = @splat(mixed_candidate_cache_invalid),
    owned_duplicate_index: DuplicateMatchIndex = undefined,
    duplicate_index: ?*DuplicateMatchIndex = null,
    cancelled: ?*const std.atomic.Value(bool) = null,
    len: usize = 0,
    lookup_count: usize = 0,
    hit_count: usize = 0,

    fn initWithDuplicateIndex(duplicate_index: ?*DuplicateMatchIndex, cancelled: ?*const std.atomic.Value(bool)) MixedMatchCandidateCache {
        // Keep the large owned fallback index undefined. Initializing the
        // enclosing value with `.{}` can otherwise zero or copy megabytes of
        // dead storage before the externally prepared index is installed.
        var cache: MixedMatchCandidateCache = undefined;
        cache.slots = @splat(mixed_candidate_cache_invalid);
        cache.duplicate_index = duplicate_index;
        cache.cancelled = cancelled;
        cache.len = 0;
        cache.lookup_count = 0;
        cache.hit_count = 0;
        return cache;
    }

    fn candidatesAt(
        self: *MixedMatchCandidateCache,
        dictionary: []const u8,
        block: []const u8,
        literal_start: usize,
        frame_offset: usize,
        allowed: MixedMatchKindSet,
        out: []MixedMatchCandidate,
    ) Error!usize {
        if (out.len < mixed_candidates_per_position) return error.OutputTooSmall;
        if (self.cancelled) |flag| if (flag.load(.acquire)) return 0;
        self.lookup_count += 1;
        const allowed_bits = @as(usize, @intFromBool(allowed.dictionary)) |
            (@as(usize, @intFromBool(allowed.duplicate)) << 1) |
            (@as(usize, @intFromBool(allowed.repeated)) << 2);
        var slot = (literal_start *% 0x9e37_79b1 +% allowed_bits) & (mixed_candidate_cache_slot_count - 1);
        while (self.slots[slot] != mixed_candidate_cache_invalid) : (slot = (slot + 1) & (mixed_candidate_cache_slot_count - 1)) {
            const entry = self.entries[self.slots[slot]];
            if (entry.literal_start == literal_start and entry.allowed.eql(allowed)) {
                self.hit_count += 1;
                @memcpy(out[0..entry.count], entry.candidates[0..entry.count]);
                return entry.count;
            }
        }

        if (allowed.duplicate and block.len > duplicate_exact_hash_input_max and block.len <= duplicate_index_max_input_len and self.duplicate_index == null) {
            self.owned_duplicate_index.build(block);
            self.duplicate_index = &self.owned_duplicate_index;
        }
        const count = try mixedMatchCandidatesAtUncached(dictionary, block, literal_start, frame_offset, allowed, self.duplicate_index, self.cancelled, out);
        if (self.len < self.entries.len) {
            const entry_index: u16 = @intCast(self.len);
            self.entries[entry_index] = .{
                .literal_start = literal_start,
                .allowed = allowed,
                .count = count,
            };
            @memcpy(self.entries[entry_index].candidates[0..count], out[0..count]);
            self.slots[slot] = entry_index;
            self.len += 1;
        }
        return count;
    }
};

fn bestMixedCandidateLookaheadPlan(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    first_candidate: MixedMatchCandidate,
) Error!?MixedMatchLookaheadPlan {
    return try bestMixedCandidateLookaheadPlanFromFirst(
        dictionary,
        block,
        frame_offset,
        .{ .dictionary = true, .duplicate = true, .repeated = true },
        null,
        first_candidate,
    );
}

fn bestMixedMatchLookaheadPlan(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    required_first: MixedMatchRequirement,
    required_second: MixedMatchRequirement,
    match_search_budget: usize,
    duplicate_index: ?*DuplicateMatchIndex,
    cancelled: ?*const std.atomic.Value(bool),
) Error!?MixedMatchLookaheadPlan {
    if (match_search_budget == 0) return null;
    var first_candidates: [mixed_candidates_per_position]MixedMatchCandidate = undefined;
    var candidate_cache = MixedMatchCandidateCache.initWithDuplicateIndex(duplicate_index, cancelled);
    const first_count = try candidate_cache.candidatesAt(dictionary, block, 0, frame_offset, allowed, first_candidates[0..]);
    if (first_count == 0) return null;

    const requirements: MixedMatchLookaheadRequirements = .{
        .first = required_first,
        .second = required_second,
    };
    var plan: MixedMatchLookaheadPlan = .{};
    var best: MixedMatchLookaheadPlan = .{};
    var have_best = false;
    var literal_histogram = MixedLiteralHistogram.init(block);
    var huffman_bit_prefix: MixedHuffmanBitPrefix = .{};
    for (first_candidates[0..first_count]) |candidate| {
        // Preserve the historical contract: each top-level alternative gets
        // the caller's complete bounded search budget.
        var search_budget = match_search_budget;
        var seen: MixedMatchKindSet = .{};
        try searchMixedCandidateLookaheadPlans(
            dictionary,
            block,
            frame_offset,
            allowed,
            requirements,
            &candidate_cache,
            candidate,
            &plan,
            0,
            &search_budget,
            &seen,
            &best,
            &have_best,
            &literal_histogram,
            &huffman_bit_prefix,
            cancelled,
        );
    }
    return if (have_best) best else null;
}

fn bestMixedCandidateLookaheadPlanFromFirst(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    requirements: ?MixedMatchLookaheadRequirements,
    first_candidate: MixedMatchCandidate,
) Error!?MixedMatchLookaheadPlan {
    var candidate_cache: MixedMatchCandidateCache = .{};
    return try bestMixedCandidateLookaheadPlanFromFirstWithCache(
        dictionary,
        block,
        frame_offset,
        allowed,
        requirements,
        &candidate_cache,
        first_candidate,
        mixed_match_path_search_budget,
    );
}

fn bestMixedCandidateLookaheadPlanFromFirstWithCache(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    requirements: ?MixedMatchLookaheadRequirements,
    candidate_cache: *MixedMatchCandidateCache,
    first_candidate: MixedMatchCandidate,
    match_search_budget: usize,
) Error!?MixedMatchLookaheadPlan {
    if (match_search_budget == 0) return null;
    if (!allowed.contains(first_candidate.kind)) return null;
    var plan: MixedMatchLookaheadPlan = .{};
    var best: MixedMatchLookaheadPlan = .{};
    var have_best = false;
    var search_budget: usize = match_search_budget;
    var seen: MixedMatchKindSet = .{};
    var literal_histogram = MixedLiteralHistogram.init(block);
    var huffman_bit_prefix: MixedHuffmanBitPrefix = .{};
    try searchMixedCandidateLookaheadPlans(
        dictionary,
        block,
        frame_offset,
        allowed,
        requirements,
        candidate_cache,
        first_candidate,
        &plan,
        0,
        &search_budget,
        &seen,
        &best,
        &have_best,
        &literal_histogram,
        &huffman_bit_prefix,
        null,
    );
    if (!have_best or best.count < 2) return null;
    return best;
}

fn searchMixedCandidateLookaheadPlans(
    dictionary: []const u8,
    block: []const u8,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    requirements: ?MixedMatchLookaheadRequirements,
    candidate_cache: *MixedMatchCandidateCache,
    candidate: MixedMatchCandidate,
    plan: *MixedMatchLookaheadPlan,
    depth: usize,
    search_budget: *usize,
    seen: *MixedMatchKindSet,
    best: *MixedMatchLookaheadPlan,
    have_best: *bool,
    literal_histogram: *MixedLiteralHistogram,
    huffman_bit_prefix: *MixedHuffmanBitPrefix,
    cancelled: ?*const std.atomic.Value(bool),
) Error!void {
    if (search_budget.* == 0 or depth >= max_bootstrap_sequence_count or
        (cancelled != null and cancelled.?.load(.acquire))) return;
    search_budget.* -= 1;

    const previous_seen = seen.*;
    noteMixedMatchKind(seen, candidate.kind);
    plan.literal_lens[depth] = candidate.literal_len;
    plan.offsets[depth] = candidate.offset;
    plan.match_lens[depth] = candidate.match_len;
    plan.literal_ends[depth] = candidate.literal_end;
    plan.kinds[depth] = candidate.kind;
    const count = depth + 1;
    // Match the scorer's logical source cursor, which always starts at byte
    // zero even when a test seeds lookahead from a candidate found later.
    const previous_end = if (depth == 0) 0 else plan.literal_ends[depth - 1];
    const covered_start = std.math.add(usize, previous_end, candidate.literal_len) catch return error.IntegerOverflow;
    if (covered_start > candidate.literal_end or candidate.literal_end > block.len) return error.CorruptFrame;
    const covered = block[covered_start..candidate.literal_end];
    literal_histogram.remove(covered);
    defer literal_histogram.add(covered);

    if (cancelled) |flag| if (flag.load(.acquire)) return;

    // Treat "stop matching here and carry the remaining bytes as literals"
    // as one valid branch once there are enough sequences to form a mixed
    // block. Extra sequences are not free: their table state transitions and
    // extra bits can outweigh the literals they remove. Keeping this prefix
    // candidate also makes the bounded search degrade safely if dense
    // candidate graphs exhaust the small bootstrap budget.
    try considerMixedMatchLookaheadPlan(block, plan, count, candidate.literal_end, seen.*, requirements, best, have_best, literal_histogram, huffman_bit_prefix);
    if (candidate.literal_end < block.len and count < max_bootstrap_sequence_count and
        (cancelled == null or !cancelled.?.load(.acquire)))
    {
        var next_candidates: [mixed_candidates_per_position]MixedMatchCandidate = undefined;
        const next_count = try candidate_cache.candidatesAt(dictionary, block, candidate.literal_end, frame_offset, allowed, next_candidates[0..]);
        for (next_candidates[0..next_count]) |next| {
            try searchMixedCandidateLookaheadPlans(
                dictionary,
                block,
                frame_offset,
                allowed,
                requirements,
                candidate_cache,
                next,
                plan,
                count,
                search_budget,
                seen,
                best,
                have_best,
                literal_histogram,
                huffman_bit_prefix,
                cancelled,
            );
            if (search_budget.* == 0) break;
        }
    }

    plan.count = depth;
    seen.* = previous_seen;
}

fn considerMixedMatchLookaheadPlan(
    block: []const u8,
    plan: *MixedMatchLookaheadPlan,
    count: usize,
    tail_start: usize,
    seen: MixedMatchKindSet,
    requirements: ?MixedMatchLookaheadRequirements,
    best: *MixedMatchLookaheadPlan,
    have_best: *bool,
    literal_histogram: *const MixedLiteralHistogram,
    huffman_bit_prefix: *MixedHuffmanBitPrefix,
) Error!void {
    if (count < 2) return;
    if (requirements) |required| {
        if (!mixedMatchRequirementMet(seen, required.first) or
            !mixedMatchRequirementMet(seen, required.second)) return;
    }
    const payload_len = try bestSequencePayloadLenWithLiteralEndsAndHistogram(
        block,
        plan.literal_lens[0..count],
        plan.offsets[0..count],
        plan.match_lens[0..count],
        plan.literal_ends[0..count],
        tail_start,
        literal_histogram,
        huffman_bit_prefix,
    );
    if (!mixedMatchLookaheadPlanMetadataBetter(payload_len, count, plan.literal_ends[count - 1], best, have_best.*)) return;

    // Only a new winner needs its path materialized. The old return-by-value
    // recursion copied all five 128-entry arrays for every finalized branch
    // and again while unwinding, even when that branch immediately lost.
    @memcpy(best.literal_lens[0..count], plan.literal_lens[0..count]);
    @memcpy(best.offsets[0..count], plan.offsets[0..count]);
    @memcpy(best.match_lens[0..count], plan.match_lens[0..count]);
    @memcpy(best.literal_ends[0..count], plan.literal_ends[0..count]);
    @memcpy(best.kinds[0..count], plan.kinds[0..count]);
    best.count = count;
    best.tail_start = tail_start;
    best.payload_len = payload_len;
    have_best.* = true;
}

fn noteMixedMatchKind(seen: *MixedMatchKindSet, kind: MixedMatchKind) void {
    switch (kind) {
        .dictionary => seen.dictionary = true,
        .duplicate => seen.duplicate = true,
        .repeated => seen.repeated = true,
    }
}

fn mixedMatchRequirementMet(seen: MixedMatchKindSet, requirement: MixedMatchRequirement) bool {
    return switch (requirement) {
        .kind => |kind| seen.contains(kind),
        .non_dictionary => seen.duplicate or seen.repeated,
    };
}

fn mixedMatchLookaheadPlanMetadataBetter(payload_len: usize, count: usize, last_literal_end: usize, current: *const MixedMatchLookaheadPlan, have_current: bool) bool {
    if (!have_current) return true;
    if (payload_len != current.payload_len) return payload_len < current.payload_len;
    if (count != current.count) return count > current.count;
    return last_literal_end > current.literal_ends[current.count - 1];
}

fn mixedMatchCandidatesAt(
    dictionary: []const u8,
    block: []const u8,
    literal_start: usize,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    out: []MixedMatchCandidate,
) Error!usize {
    // This helper is used by tests/probes that need one deterministic candidate
    // snapshot. The recursive planner passes an explicit MixedMatchCandidateCache
    // through its call tree so repeated positions share scan results; allocating a
    // fresh full-size cache here would only add stack pressure without reuse.
    return try mixedMatchCandidatesAtUncached(dictionary, block, literal_start, frame_offset, allowed, null, null, out);
}

fn mixedMatchCandidatesAtUncached(
    dictionary: []const u8,
    block: []const u8,
    literal_start: usize,
    frame_offset: usize,
    allowed: MixedMatchKindSet,
    duplicate_index: ?*DuplicateMatchIndex,
    cancelled: ?*const std.atomic.Value(bool),
    out: []MixedMatchCandidate,
) Error!usize {
    if (out.len < mixed_candidates_per_position) return error.OutputTooSmall;
    var count: usize = 0;
    if (allowed.dictionary) {
        if (try dictionaryMixedMatchCandidate(dictionary, block, literal_start, frame_offset)) |candidate| {
            out[count] = candidate;
            count += 1;
        }
    }
    if (allowed.duplicate) {
        if (try duplicateMixedMatchCandidate(block, literal_start, duplicate_index, cancelled)) |candidate| {
            out[count] = candidate;
            count += 1;
            if (cancelled) |flag| if (flag.load(.acquire)) return 0;
            // Also expose the match starting exactly at the current cursor.
            // The existing global-best candidate often skips useful bytes to
            // buy a longer match; lookahead needs both choices to avoid turning
            // those skipped bytes into literals across the whole plan.
            if (try duplicateMixedMatchCandidateAtCursor(block, literal_start, duplicate_index, cancelled)) |cursor_candidate| {
                if (cursor_candidate.literal_end != candidate.literal_end or cursor_candidate.offset != candidate.offset) {
                    out[count] = cursor_candidate;
                    count += 1;
                }
            }
        }
    }
    if (allowed.repeated) {
        if (cancelled) |flag| if (flag.load(.acquire)) return 0;
        if (repeatedMixedMatchCandidate(block, literal_start)) |candidate| {
            out[count] = candidate;
            count += 1;
        }
    }
    std.mem.sort(MixedMatchCandidate, out[0..count], {}, mixedMatchCandidateSortLessThan);
    return count;
}

fn duplicateMixedMatchCandidateAtCursor(
    block: []const u8,
    literal_start: usize,
    duplicate_index: ?*DuplicateMatchIndex,
    cancelled: ?*const std.atomic.Value(bool),
) Error!?MixedMatchCandidate {
    if (literal_start == 0 or literal_start + 8 > block.len) return null;
    var best: ?DuplicateMatch = null;
    if (duplicate_index) |index| {
        var candidate_index = index.hash_predecessors[literal_start];
        while (candidate_index != duplicate_index_invalid) {
            if (cancelled) |flag| if (flag.load(.acquire)) return null;
            considerCursorDuplicateMatch(block, literal_start, candidate_index, &best);
            // The chain is newest first. A match reaching the block end has
            // the maximum possible length, and later nodes can only offer the
            // same length at a larger offset, which loses the tie-break.
            if (best) |match| if (match.len == block.len - literal_start) break;
            candidate_index = index.hash_predecessors[candidate_index];
        }
    } else if (block.len > 4096) {
        // Large blocks use the same eight-byte hash-chain candidate policy as
        // the global finder; scanning all prior bytes here would turn the new
        // alternative into another quadratic hot path.
        const wanted_hash = duplicateHash8(block[literal_start..][0..8]);
        var first: usize = 0;
        while (first + 8 <= literal_start) : (first += 1) {
            if (duplicateHash8(block[first..][0..8]) != wanted_hash) continue;
            considerCursorDuplicateMatch(block, literal_start, first, &best);
        }
    } else {
        var first: usize = 0;
        while (first < literal_start) : (first += 1) considerCursorDuplicateMatch(block, literal_start, first, &best);
    }
    const match = best orelse return null;
    const payload_len = singleMatchPayloadLenFrom(block, match, literal_start) catch return null;
    return .{
        .literal_len = 0,
        .offset = match.second_start - match.first_start,
        .match_len = match.len,
        .literal_end = match.second_start + match.len,
        .payload_len = payload_len,
        .kind = .duplicate,
    };
}

fn duplicateMixedMatchCandidateAtCursorScan(block: []const u8, literal_start: usize) Error!?MixedMatchCandidate {
    return duplicateMixedMatchCandidateAtCursor(block, literal_start, null, null);
}

fn considerCursorDuplicateMatch(block: []const u8, literal_start: usize, first: usize, best: *?DuplicateMatch) void {
    var len: usize = 0;
    while (literal_start + len < block.len and block[first + len] == block[literal_start + len]) : (len += 1) {}
    if (len < 8) return;
    const candidate: DuplicateMatch = .{ .first_start = first, .second_start = literal_start, .len = len };
    if (best.* == null or candidate.len > best.*.?.len or
        (candidate.len == best.*.?.len and candidate.second_start - candidate.first_start < best.*.?.second_start - best.*.?.first_start)) best.* = candidate;
}

fn mixedMatchCandidateSortLessThan(_: void, a: MixedMatchCandidate, b: MixedMatchCandidate) bool {
    if (a.payload_len != b.payload_len) return a.payload_len < b.payload_len;
    if (a.match_len != b.match_len) return a.match_len > b.match_len;
    if (a.literal_len != b.literal_len) return a.literal_len < b.literal_len;
    return mixedMatchKindRank(a.kind) > mixedMatchKindRank(b.kind);
}

fn mixedMatchCandidateBetter(candidate: MixedMatchCandidate, current: ?MixedMatchCandidate) bool {
    const existing = current orelse return true;
    if (candidate.payload_len != existing.payload_len) return candidate.payload_len < existing.payload_len;
    if (candidate.match_len != existing.match_len) return candidate.match_len > existing.match_len;
    if (candidate.literal_len != existing.literal_len) return candidate.literal_len < existing.literal_len;
    return mixedMatchKindRank(candidate.kind) > mixedMatchKindRank(existing.kind);
}

fn mixedMatchKindRank(kind: MixedMatchKind) u2 {
    return switch (kind) {
        .duplicate => 0,
        .dictionary => 1,
        .repeated => 2,
    };
}

fn emitMultiDictionaryMatchCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    dictionary: NativeDictionary,
    frame_offset: usize,
) Error!bool {
    var literal_lens: [max_bootstrap_sequence_count]usize = undefined;
    var offsets: [max_bootstrap_sequence_count]usize = undefined;
    var match_lens: [max_bootstrap_sequence_count]usize = undefined;
    var literal_ends: [max_bootstrap_sequence_count]usize = undefined;
    var count: usize = 0;
    var literal_start: usize = 0;
    while (count < max_bootstrap_sequence_count and literal_start < block.len) {
        const match = findDictionaryMatchIn(dictionary.content, block, literal_start, frame_offset) orelse break;
        literal_lens[count] = match.block_start - literal_start;
        offsets[count] = try dictionaryMatchOffset(dictionary.content.len, frame_offset, match);
        match_lens[count] = match.len;
        literal_ends[count] = match.block_start + match.len;
        literal_start = literal_ends[count];
        count += 1;
    }
    if (count < 2) return false;

    return try emitBestSequenceCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        literal_start,
    );
}

fn emitSingleMatchCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, duplicate_index: ?*DuplicateMatchIndex) Error!bool {
    if (rleByte(block) != null) return false;
    const match = if (duplicate_index) |index|
        try findBestDuplicateMatchIndexed(block, 0, index) orelse return false
    else
        try findBestDuplicateMatch(block) orelse return false;
    return try emitSingleMatchCompressedBlockFromMatch(allocator, out, block, last, match);
}

fn emitSingleMatchCompressedBlockFromMatch(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, match: DuplicateMatch) Error!bool {
    const literal_len = match.second_start;
    const offset = match.second_start - match.first_start;
    const tail_start = match.second_start + match.len;
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{offset};
    const match_lens = [_]usize{match.len};
    const literal_ends = [_]usize{tail_start};
    return try emitBestSequenceCompressedBlock(allocator, out, block, last, &literal_lens, &offsets, &match_lens, &literal_ends, tail_start);
}

fn emitMultiDuplicateMatchCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, duplicate_index: ?*DuplicateMatchIndex) Error!bool {
    var first_match: ?DuplicateMatch = null;
    return try emitMultiDuplicateMatchCompressedBlockWithFirst(allocator, out, block, last, duplicate_index, &first_match);
}

fn emitMultiDuplicateMatchCompressedBlockWithFirst(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, duplicate_index: ?*DuplicateMatchIndex, first_match: *?DuplicateMatch) Error!bool {
    first_match.* = null;
    if (rleByte(block) != null or block.len < 32) return false;
    var matches: [max_bootstrap_sequence_count]DuplicateMatch = undefined;
    var literal_lens: [max_bootstrap_sequence_count]usize = undefined;
    var count: usize = 0;
    var literal_start: usize = 0;
    while (count < matches.len and literal_start < block.len) {
        const match = if (duplicate_index) |index|
            try findBestDuplicateMatchIndexed(block, literal_start, index) orelse break
        else
            try findBestDuplicateMatchIn(block, literal_start) orelse break;
        const literal_len = match.second_start - literal_start;
        if (count == 0) first_match.* = match;
        matches[count] = match;
        literal_lens[count] = literal_len;
        count += 1;
        literal_start = match.second_start + match.len;
    }
    if (count < 2) return false;
    const tail_start = literal_start;
    var offsets: [max_bootstrap_sequence_count]usize = undefined;
    var match_lens: [max_bootstrap_sequence_count]usize = undefined;
    var literal_ends: [max_bootstrap_sequence_count]usize = undefined;
    for (matches[0..count], 0..) |match, i| {
        offsets[i] = match.second_start - match.first_start;
        match_lens[i] = match.len;
        literal_ends[i] = match.second_start + match.len;
    }
    return try emitBestSequenceCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        tail_start,
    );
}

fn emitMultiDuplicateMatchPredefinedCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    matches: []const DuplicateMatch,
    literal_lens: []const usize,
    tail_start: usize,
) Error!bool {
    if (matches.len != literal_lens.len or matches.len < 2 or matches.len > max_bootstrap_sequence_count) return false;

    var offsets: [max_bootstrap_sequence_count]usize = undefined;
    var match_lens: [max_bootstrap_sequence_count]usize = undefined;
    var literal_ends: [max_bootstrap_sequence_count]usize = undefined;
    for (matches, 0..) |match, i| {
        offsets[i] = match.second_start - match.first_start;
        match_lens[i] = match.len;
        literal_ends[i] = match.second_start + match.len;
    }
    return try emitMultiSequencePredefinedCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets[0..matches.len],
        match_lens[0..matches.len],
        literal_ends[0..matches.len],
        tail_start,
    );
}

fn emitBestSequenceCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    return try emitBestSequenceCompressedBlockWithScratch(
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        tail_start,
        null,
    );
}

fn emitBestSequenceCompressedBlockWithScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    single_scratch: ?*SingleSequenceEmitScratch,
) Error!bool {
    var local_literals_prefix: std.ArrayList(u8) = .empty;
    defer if (single_scratch == null) local_literals_prefix.deinit(allocator);
    const literals_prefix = if (single_scratch) |scratch| blk: {
        scratch.clearRetainingCapacity();
        break :blk &scratch.literals_prefix;
    } else &local_literals_prefix;
    _ = try emitSequenceLiteralsSection(allocator, literals_prefix, block, literal_lens, literal_ends, tail_start);

    if (literal_lens.len == 1 and offsets.len == 1 and match_lens.len == 1 and
        (!builtin.is_test or !test_disable_single_sequence_winner_only))
    {
        if (comptime builtin.is_test) test_single_sequence_winner_only_hits += 1;
        const rle_payload_len = try rleSequencePayloadLenForValuesWithLiteralsLen(
            literal_lens,
            offsets,
            match_lens,
            literals_prefix.items.len,
        );
        const predefined_payload_len: ?usize = predefinedSequencePayloadLenWithLiteralsLen(
            literal_lens,
            offsets,
            match_lens,
            literals_prefix.items.len,
        ) catch |err| switch (err) {
            // The generic path treats values outside the predefined tables as
            // an unavailable candidate and keeps the valid RLE candidate.
            error.CorruptFrame => null,
            else => return err,
        };
        // Preserve the existing arbitration order: equal-sized candidates
        // keep the RLE representation that was emitted first.
        const use_predefined = if (predefined_payload_len) |payload_len|
            payload_len < rle_payload_len
        else
            false;
        const selected_payload_len = if (use_predefined) predefined_payload_len.? else rle_payload_len;
        const encoded_len = std.math.add(usize, selected_payload_len, 3) catch return error.IntegerOverflow;
        const raw_block_len = std.math.add(usize, block.len, 3) catch return error.IntegerOverflow;
        if (encoded_len >= raw_block_len) return false;

        // The selected emitter appends the header only after constructing its
        // private payload. Reserve the whole result now so a later append
        // cannot leave a partial block in the caller's output on OOM.
        try out.ensureUnusedCapacity(allocator, encoded_len);
        if (use_predefined) {
            if (single_scratch) |scratch| return try emitMultiSequencePredefinedCompressedBlockWithLiteralsAndScratch(
                allocator,
                out,
                block,
                last,
                literals_prefix.items,
                literal_lens,
                offsets,
                match_lens,
                &scratch.payload,
                &scratch.sequence_bits,
            ) else return try emitMultiSequencePredefinedCompressedBlockWithLiterals(allocator, out, block, last, literals_prefix.items, literal_lens, offsets, match_lens);
        }
        if (single_scratch) |scratch| return try emitRleSequenceCompressedBlockWithLiteralsAndScratch(
            allocator,
            out,
            block,
            last,
            literals_prefix.items,
            literal_lens,
            offsets,
            match_lens,
            &scratch.payload,
            &scratch.sequence_bits,
        ) else return try emitRleSequenceCompressedBlockWithLiterals(allocator, out, block, last, literals_prefix.items, literal_lens, offsets, match_lens);
    }
    if (builtin.is_test and (literal_lens.len == 1 or test_disable_multi_sequence_winner_only))
        return try emitBestMultiSequenceCompressedBlockGeneric(
            allocator,
            out,
            block,
            last,
            literals_prefix.items,
            literal_lens,
            offsets,
            match_lens,
            literal_ends,
            tail_start,
        );
    return try emitBestMultiSequenceCompressedBlockWinnerOnly(
        allocator,
        out,
        block,
        last,
        literals_prefix.items,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        tail_start,
    );
}

noinline fn emitBestMultiSequenceCompressedBlockWinnerOnly(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) linksection(multi_sequence_winner_text_section) Error!bool {
    const MultiSequenceWinner = enum { rle, predefined, table_plan };
    var winner: ?MultiSequenceWinner = null;
    var best_payload_len: usize = std.math.maxInt(usize);

    if (rleSequencePayloadLenForValuesWithLiteralsLen(literal_lens, offsets, match_lens, literals_prefix.len)) |payload_len| {
        winner = .rle;
        best_payload_len = payload_len;
    } else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }
    var predefined_payload_len: ?usize = null;
    const table_plan = try bestTablePlanSequenceWithLiteralsLenAndPredefinedPayload(
        literal_lens,
        offsets,
        match_lens,
        literals_prefix.len,
        &predefined_payload_len,
    );
    if (predefined_payload_len) |payload_len| {
        if (winner == null or payload_len < best_payload_len) {
            winner = .predefined;
            best_payload_len = payload_len;
        }
    }
    if (table_plan) |plan| {
        if (winner == null or plan.payload_len < best_payload_len) {
            winner = .table_plan;
            best_payload_len = plan.payload_len;
        }
    }
    const selected = winner orelse return false;
    if (best_payload_len >= block.len) return false;
    if (comptime builtin.is_test) {
        test_multi_sequence_winner_only_hits += 1;
        test_multi_sequence_winner_hits[@intFromEnum(selected)] += 1;
    }

    const output_start = out.items.len;
    errdefer out.items.len = output_start;
    try out.ensureUnusedCapacity(allocator, best_payload_len + 3);
    const emitted = switch (selected) {
        .rle => try emitRleSequenceCompressedBlockWithLiterals(
            allocator,
            out,
            block,
            last,
            literals_prefix,
            literal_lens,
            offsets,
            match_lens,
        ),
        .predefined => try emitMultiSequencePredefinedCompressedBlockWithLiterals(
            allocator,
            out,
            block,
            last,
            literals_prefix,
            literal_lens,
            offsets,
            match_lens,
        ),
        .table_plan => if (literal_lens.len >= wide_borrowed_sequence_plan_min)
            try emitSequenceCompressedBlockWithTablePlansAndOffsetsBorrowed(
                allocator,
                out,
                block,
                last,
                literal_lens,
                offsets,
                match_lens,
                literal_ends,
                tail_start,
                &table_plan.?.plan,
                literals_prefix,
                null,
                initial_repeated_offsets,
            )
        else
            try emitSequenceCompressedBlockWithTablePlans(
                allocator,
                out,
                block,
                last,
                literal_lens,
                offsets,
                match_lens,
                literal_ends,
                tail_start,
                table_plan.?.plan,
                literals_prefix,
                null,
            ),
    };
    if (!emitted or out.items.len - output_start != best_payload_len + 3) return error.CorruptFrame;
    return true;
}

fn emitBestMultiSequenceCompressedBlockGeneric(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    var candidate_block: std.ArrayList(u8) = .empty;
    defer candidate_block.deinit(allocator);
    var best_block: std.ArrayList(u8) = .empty;
    defer best_block.deinit(allocator);

    const rle_ok = try emitRleSequenceCompressedBlockWithLiterals(allocator, &candidate_block, block, last, literals_prefix, literal_lens, offsets, match_lens);
    if (rle_ok) try best_block.appendSlice(allocator, candidate_block.items);

    candidate_block.clearRetainingCapacity();
    const predefined_ok = try emitMultiSequencePredefinedCompressedBlockWithLiterals(allocator, &candidate_block, block, last, literals_prefix, literal_lens, offsets, match_lens);
    if (predefined_ok and (best_block.items.len == 0 or candidate_block.items.len < best_block.items.len)) {
        best_block.clearRetainingCapacity();
        try best_block.appendSlice(allocator, candidate_block.items);
    }

    candidate_block.clearRetainingCapacity();
    const table_plan_ok = try emitTablePlanSequenceCompressedBlockWithLiterals(allocator, &candidate_block, block, last, literals_prefix, literal_lens, offsets, match_lens, literal_ends, tail_start);
    if (table_plan_ok and (best_block.items.len == 0 or candidate_block.items.len < best_block.items.len)) {
        best_block.clearRetainingCapacity();
        try best_block.appendSlice(allocator, candidate_block.items);
    }

    if (best_block.items.len == 0) return false;
    try out.appendSlice(allocator, best_block.items);
    return true;
}

noinline fn emitBestSequenceCompressedBlockSmall(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) linksection(fast_encode_helper_text_section) Error!bool {
    var storage: [small_sequence_stack_scratch_len]u8 align(@alignOf(usize)) = undefined;
    return try emitBestSequenceCompressedBlockWithStackStorage(allocator, out, block, last, literal_lens, offsets, match_lens, literal_ends, tail_start, &storage);
}

fn emitBestSequenceCompressedBlockWithStackStorage(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    storage: []u8,
) Error!bool {
    var fixed = std.heap.FixedBufferAllocator.init(storage);
    var encoded: std.ArrayList(u8) = .empty;
    const ok = emitBestSequenceCompressedBlock(fixed.allocator(), &encoded, block, last, literal_lens, offsets, match_lens, literal_ends, tail_start) catch |err| switch (err) {
        error.OutOfMemory => return try emitBestSequenceCompressedBlock(allocator, out, block, last, literal_lens, offsets, match_lens, literal_ends, tail_start),
        else => return err,
    };
    if (!ok) return false;
    try out.appendSlice(allocator, encoded.items);
    return true;
}

test "zstd single sequence winner-only emission preserves generic wire" {
    test_disable_single_sequence_winner_only = false;
    test_single_sequence_winner_only_hits = 0;
    defer {
        test_disable_single_sequence_winner_only = false;
        test_single_sequence_winner_only_hits = 0;
    }

    var successful_hits: usize = 0;
    var predefined_wins: usize = 0;
    var ties: usize = 0;
    var tie_rle_modes: usize = 0;
    for (0..64) |seed| {
        const period = 1 + (seed * 7) % 48;
        const repeats = 3 + seed % 13;
        const tail_len = (seed * 5) % 17;
        const match_len = period * repeats;
        const len = period + match_len + tail_len;
        var block: [848]u8 = undefined;
        var random_state: u32 = @truncate(0x243f_6a88 +% seed *% 0x9e37_79b9);
        for (block[0..period]) |*byte| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            byte.* = @truncate(random_state >> 24);
        }
        for (period..period + match_len) |i| block[i] = block[i - period];
        for (block[period + match_len .. len]) |*byte| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            byte.* = @truncate(random_state >> 24);
        }

        const literal_lens = [_]usize{period};
        const offsets = [_]usize{period};
        const match_lens = [_]usize{match_len};
        const literal_ends = [_]usize{period + match_len};
        const literals_len = try sequenceLiteralsPayloadSectionLen(
            block[0..len],
            &literal_lens,
            &literal_ends,
            literal_ends[0],
        );
        const rle_len = try rleSequencePayloadLenForValuesWithLiteralsLen(&literal_lens, &offsets, &match_lens, literals_len);
        const predefined_len = try predefinedSequencePayloadLenWithLiteralsLen(&literal_lens, &offsets, &match_lens, literals_len);
        if (predefined_len < rle_len)
            predefined_wins += 1
        else if (predefined_len == rle_len)
            ties += 1;

        const hits_before = test_single_sequence_winner_only_hits;
        var optimized: std.ArrayList(u8) = .empty;
        defer optimized.deinit(std.testing.allocator);
        const optimized_ok = try emitBestSequenceCompressedBlock(
            std.testing.allocator,
            &optimized,
            block[0..len],
            seed & 1 == 0,
            &literal_lens,
            &offsets,
            &match_lens,
            &literal_ends,
            literal_ends[0],
        );
        try std.testing.expectEqual(hits_before + 1, test_single_sequence_winner_only_hits);
        successful_hits += @intFromBool(optimized_ok);
        if (optimized_ok and predefined_len == rle_len) {
            var frame_state: SequenceFrameState = .{};
            const section = try parseLiteralsSection(optimized.items[3..], &frame_state);
            try std.testing.expectEqual(@as(u8, 0x54), optimized.items[3 + section.sequence_payload_offset]);
            tie_rle_modes += 1;
        }

        test_disable_single_sequence_winner_only = true;
        var reference: std.ArrayList(u8) = .empty;
        defer reference.deinit(std.testing.allocator);
        const reference_ok = try emitBestSequenceCompressedBlock(
            std.testing.allocator,
            &reference,
            block[0..len],
            seed & 1 == 0,
            &literal_lens,
            &offsets,
            &match_lens,
            &literal_ends,
            literal_ends[0],
        );
        test_disable_single_sequence_winner_only = false;

        try std.testing.expectEqual(reference_ok, optimized_ok);
        try std.testing.expectEqualSlices(u8, reference.items, optimized.items);
    }
    try std.testing.expect(successful_hits != 0);
    try std.testing.expect(predefined_wins != 0);
    try std.testing.expect(ties != 0);
    try std.testing.expect(tie_rle_modes != 0);

    const AllocationFailureTest = struct {
        fn run(allocator: std.mem.Allocator) !void {
            const block = "abcd" ** 32;
            const literal_lens = [_]usize{4};
            const offsets = [_]usize{4};
            const match_lens = [_]usize{block.len - 4};
            const literal_ends = [_]usize{block.len};
            var output = try std.ArrayList(u8).initCapacity(allocator, "prefix".len);
            defer output.deinit(allocator);
            output.appendSliceAssumeCapacity("prefix");
            const emitted = emitBestSequenceCompressedBlock(
                allocator,
                &output,
                block,
                true,
                &literal_lens,
                &offsets,
                &match_lens,
                &literal_ends,
                block.len,
            ) catch |err| {
                try std.testing.expectEqualSlices(u8, "prefix", output.items);
                return err;
            };
            try std.testing.expect(emitted);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, AllocationFailureTest.run, .{});
}

test "zstd multi sequence winner-only emission preserves generic wire" {
    const Test = struct {
        fn compare(
            block: []const u8,
            literal_lens: []const usize,
            offsets: []const usize,
            match_lens: []const usize,
            literal_ends: []const usize,
            tail_start: usize,
        ) !void {
            const hits_before = test_multi_sequence_winner_only_hits;
            var optimized: std.ArrayList(u8) = .empty;
            defer optimized.deinit(std.testing.allocator);
            const optimized_ok = try emitBestSequenceCompressedBlock(
                std.testing.allocator,
                &optimized,
                block,
                true,
                literal_lens,
                offsets,
                match_lens,
                literal_ends,
                tail_start,
            );
            try std.testing.expectEqual(hits_before + @intFromBool(optimized_ok), test_multi_sequence_winner_only_hits);

            test_disable_multi_sequence_winner_only = true;
            var reference: std.ArrayList(u8) = .empty;
            defer reference.deinit(std.testing.allocator);
            const reference_ok = try emitBestSequenceCompressedBlock(
                std.testing.allocator,
                &reference,
                block,
                true,
                literal_lens,
                offsets,
                match_lens,
                literal_ends,
                tail_start,
            );
            test_disable_multi_sequence_winner_only = false;

            try std.testing.expectEqual(reference_ok, optimized_ok);
            try std.testing.expectEqualSlices(u8, reference.items, optimized.items);
            if (optimized_ok) {
                var frame: std.ArrayList(u8) = .empty;
                defer frame.deinit(std.testing.allocator);
                try emitFrameHeader(std.testing.allocator, &frame, block.len, .{ .content_checksum = false });
                try frame.appendSlice(std.testing.allocator, optimized.items);
                const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
                defer std.testing.allocator.free(decoded);
                try std.testing.expectEqualSlices(u8, block, decoded);
            }
        }
    };

    test_disable_multi_sequence_winner_only = false;
    test_multi_sequence_winner_only_hits = 0;
    test_multi_sequence_winner_hits = @splat(0);
    defer {
        test_disable_multi_sequence_winner_only = false;
        test_multi_sequence_winner_only_hits = 0;
        test_multi_sequence_winner_hits = @splat(0);
    }

    var numbered_json: std.ArrayList(u8) = .empty;
    defer numbered_json.deinit(std.testing.allocator);
    while (numbered_json.items.len < 32 * 1024) {
        var line: [128]u8 = undefined;
        const index = numbered_json.items.len / 64;
        const formatted = try std.fmt.bufPrint(
            &line,
            "{{\"id\":{d},\"service\":\"vort\",\"message\":\"structured zstd encode corpus\"}}\n",
            .{index},
        );
        try numbered_json.appendSlice(std.testing.allocator, formatted);
    }

    var binary: [32 * 1024]u8 = undefined;
    var random_state: u32 = 0xfeed_beef;
    for (&binary, 0..) |*byte, index| {
        random_state = random_state *% 1_664_525 +% 1_013_904_223;
        byte.* = if (index % 64 < 48) @truncate(index * 17) else @truncate(random_state >> 16);
    }

    for ([_][]const u8{
        "Zstandard encode benchmark text with repeated structure and punctuation.\n" ** 512,
        numbered_json.items,
        &binary,
    }) |payload| {
        var tokens: std.ArrayList(lz77.Token) = .empty;
        defer tokens.deinit(std.testing.allocator);
        const stats = try double_fast_match.planReuse(&tokens, std.testing.allocator, payload, zstdHashParserOptions(payload.len));
        try std.testing.expect(stats.matches > 1);
        var literal_lens: [max_native_sequence_count]usize = undefined;
        var offsets: [max_native_sequence_count]usize = undefined;
        var match_lens: [max_native_sequence_count]usize = undefined;
        var literal_ends: [max_native_sequence_count]usize = undefined;
        var position: usize = 0;
        var literal_start: usize = 0;
        var count: usize = 0;
        for (tokens.items) |token| switch (token) {
            .literal => position += 1,
            .match => |match| {
                literal_lens[count] = position - literal_start;
                offsets[count] = match.distance;
                match_lens[count] = match.length;
                position += match.length;
                literal_ends[count] = position;
                literal_start = position;
                count += 1;
            },
        };
        try std.testing.expectEqual(payload.len, position);
        try std.testing.expectEqual(stats.matches, count);
        try Test.compare(payload, literal_lens[0..count], offsets[0..count], match_lens[0..count], literal_ends[0..count], literal_start);
    }

    var rle_payload: std.ArrayList(u8) = .empty;
    defer rle_payload.deinit(std.testing.allocator);
    var rle_literal_lens: [128]usize = undefined;
    var rle_offsets: [128]usize = undefined;
    var rle_match_lens: [128]usize = undefined;
    var rle_literal_ends: [128]usize = undefined;
    const rle_lengths = [_]usize{ 1, 2, 4, 8, 16, 32, 64 };
    const rle_matches = [_]usize{ 3, 4, 8, 16, 32, 64, 128, 258 };
    const rle_counts = [_]usize{ 2, 4, 8, 16, 32, 64, 128 };
    outer: for (rle_lengths) |literal_len| for (rle_matches) |match_len| for (rle_counts) |count| {
        rle_payload.clearRetainingCapacity();
        @memset(rle_literal_lens[0..count], literal_len);
        @memset(rle_offsets[0..count], literal_len);
        @memset(rle_match_lens[0..count], match_len);
        random_state = 0x510e_527f;
        for (0..count) |i| {
            for (0..literal_len) |_| {
                random_state = random_state *% 1_664_525 +% 1_013_904_223;
                try rle_payload.append(std.testing.allocator, @truncate(random_state >> 24));
            }
            for (0..match_len) |_|
                try rle_payload.append(std.testing.allocator, rle_payload.items[rle_payload.items.len - literal_len]);
            rle_literal_ends[i] = rle_payload.items.len;
        }
        const rle_hits_before = test_multi_sequence_winner_hits[0];
        try Test.compare(rle_payload.items, rle_literal_lens[0..count], rle_offsets[0..count], rle_match_lens[0..count], rle_literal_ends[0..count], rle_payload.items.len);
        if (test_multi_sequence_winner_hits[0] != rle_hits_before) break :outer;
    };

    const predefined_literal_lens = [_]usize{ 4, 5, 6 };
    const predefined_offsets = [_]usize{ 4, 8, 12 };
    const predefined_match_lens = [_]usize{ 4, 5, 6 };
    var predefined_literal_ends: [predefined_literal_lens.len]usize = undefined;
    var predefined_payload: std.ArrayList(u8) = .empty;
    defer predefined_payload.deinit(std.testing.allocator);
    for (predefined_literal_lens, predefined_offsets, predefined_match_lens, 0..) |literal_len, offset, match_len, i| {
        for (0..literal_len) |j| try predefined_payload.append(std.testing.allocator, @intCast('a' + (i * 7 + j) % 26));
        for (0..match_len) |_|
            try predefined_payload.append(std.testing.allocator, predefined_payload.items[predefined_payload.items.len - offset]);
        predefined_literal_ends[i] = predefined_payload.items.len;
    }
    try Test.compare(predefined_payload.items, &predefined_literal_lens, &predefined_offsets, &predefined_match_lens, &predefined_literal_ends, predefined_payload.items.len);

    for (0..32) |seed| {
        var generated: std.ArrayList(u8) = .empty;
        defer generated.deinit(std.testing.allocator);
        var literal_lens: [64]usize = undefined;
        var offsets: [64]usize = undefined;
        var match_lens: [64]usize = undefined;
        var literal_ends: [64]usize = undefined;
        const count = 2 + seed % 31;
        random_state = @truncate(0x6a09_e667 +% seed *% 0x0100_0193);
        for (0..count) |i| {
            const literal_len: usize = if (i == 0) 8 else (random_state >> 28) & 7;
            literal_lens[i] = literal_len;
            for (0..literal_len) |_| {
                random_state = random_state *% 1_664_525 +% 1_013_904_223;
                try generated.append(std.testing.allocator, @truncate(random_state >> 24));
            }
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            offsets[i] = 1 + random_state % @min(generated.items.len, 32);
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            match_lens[i] = 3 + (random_state >> 27) % 30;
            for (0..match_lens[i]) |_|
                try generated.append(std.testing.allocator, generated.items[generated.items.len - offsets[i]]);
            literal_ends[i] = generated.items.len;
        }
        const tail_start = generated.items.len;
        for (0..seed % 9) |_| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            try generated.append(std.testing.allocator, @truncate(random_state >> 24));
        }
        try Test.compare(generated.items, literal_lens[0..count], offsets[0..count], match_lens[0..count], literal_ends[0..count], tail_start);
    }

    try std.testing.expect(test_multi_sequence_winner_only_hits >= 36);
    try std.testing.expect(test_multi_sequence_winner_hits[0] != 0);
    try std.testing.expect(test_multi_sequence_winner_hits[1] != 0);
    try std.testing.expect(test_multi_sequence_winner_hits[2] != 0);

    var reference_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var reference_output: std.ArrayList(u8) = .empty;
    defer reference_output.deinit(reference_allocator.allocator());
    test_disable_multi_sequence_winner_only = true;
    try std.testing.expect(try emitBestSequenceCompressedBlock(
        reference_allocator.allocator(),
        &reference_output,
        predefined_payload.items,
        true,
        &predefined_literal_lens,
        &predefined_offsets,
        &predefined_match_lens,
        &predefined_literal_ends,
        predefined_payload.items.len,
    ));
    test_disable_multi_sequence_winner_only = false;

    var direct_allocator = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var direct_output: std.ArrayList(u8) = .empty;
    defer direct_output.deinit(direct_allocator.allocator());
    try std.testing.expect(try emitBestSequenceCompressedBlock(
        direct_allocator.allocator(),
        &direct_output,
        predefined_payload.items,
        true,
        &predefined_literal_lens,
        &predefined_offsets,
        &predefined_match_lens,
        &predefined_literal_ends,
        predefined_payload.items.len,
    ));
    try std.testing.expectEqualSlices(u8, reference_output.items, direct_output.items);
    try std.testing.expectEqual(reference_allocator.allocations - 2, direct_allocator.allocations);
    try std.testing.expect(direct_allocator.allocated_bytes + reference_output.items.len * 2 <= reference_allocator.allocated_bytes);

    const AllocationFailureTest = struct {
        fn run(allocator: std.mem.Allocator) !void {
            const payload = "abcdabcdwxyzwxyzABCDABCD";
            const literal_lens = [_]usize{ 4, 4, 4 };
            const offsets = [_]usize{ 4, 4, 4 };
            const match_lens = [_]usize{ 4, 4, 4 };
            const literal_ends = [_]usize{ 8, 16, 24 };
            var output = try std.ArrayList(u8).initCapacity(allocator, "prefix".len);
            defer output.deinit(allocator);
            output.appendSliceAssumeCapacity("prefix");
            const emitted = emitBestSequenceCompressedBlock(
                allocator,
                &output,
                payload,
                true,
                &literal_lens,
                &offsets,
                &match_lens,
                &literal_ends,
                payload.len,
            ) catch |err| {
                try std.testing.expectEqualSlices(u8, "prefix", output.items);
                return err;
            };
            try std.testing.expect(emitted);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, AllocationFailureTest.run, .{});
}

test "zstd small sequence stack scratch preserves caller OOM and heap fallback" {
    const literal_lens = [_]usize{ 4, 4, 4 };
    const offsets = [_]usize{ 4, 4, 4 };
    const match_lens = [_]usize{ 4, 4, 4 };
    const literal_ends = [_]usize{ 8, 16, 24 };
    const payload = "abcdabcdwxyzwxyzABCDABCD";

    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var output = try std.ArrayList(u8).initCapacity(failing.allocator(), "prefix".len);
    defer output.deinit(failing.allocator());
    output.appendSliceAssumeCapacity("prefix");
    failing.fail_index = failing.alloc_index;
    failing.resize_fail_index = failing.resize_index;
    try std.testing.expectError(error.OutOfMemory, emitBestSequenceCompressedBlockSmall(
        failing.allocator(),
        &output,
        payload,
        true,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        payload.len,
    ));
    try std.testing.expectEqualSlices(u8, "prefix", output.items);

    var expected: std.ArrayList(u8) = .empty;
    defer expected.deinit(std.testing.allocator);
    try std.testing.expect(try emitBestSequenceCompressedBlock(
        std.testing.allocator,
        &expected,
        payload,
        true,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        payload.len,
    ));

    var tiny_storage: [1]u8 = undefined;
    var fallback: std.ArrayList(u8) = .empty;
    defer fallback.deinit(std.testing.allocator);
    try std.testing.expect(try emitBestSequenceCompressedBlockWithStackStorage(
        std.testing.allocator,
        &fallback,
        payload,
        true,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        payload.len,
        &tiny_storage,
    ));
    try std.testing.expectEqualSlices(u8, expected.items, fallback.items);
}

fn emitRleSequenceCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    var literals_prefix: std.ArrayList(u8) = .empty;
    defer literals_prefix.deinit(allocator);
    _ = try emitSequenceLiteralsSection(allocator, &literals_prefix, block, literal_lens, literal_ends, tail_start);
    return try emitRleSequenceCompressedBlockWithLiterals(allocator, out, block, last, literals_prefix.items, literal_lens, offsets, match_lens);
}

fn emitRleSequenceCompressedBlockWithLiterals(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
) Error!bool {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(allocator);
    var sequence_bits: std.ArrayList(u8) = .empty;
    defer sequence_bits.deinit(allocator);
    return try emitRleSequenceCompressedBlockWithLiteralsAndScratch(
        allocator,
        out,
        block,
        last,
        literals_prefix,
        literal_lens,
        offsets,
        match_lens,
        &payload,
        &sequence_bits,
    );
}

fn emitRleSequenceCompressedBlockWithLiteralsAndScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    payload: *std.ArrayList(u8),
    sequence_bits: *std.ArrayList(u8),
) Error!bool {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return false;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return false;
    payload.clearRetainingCapacity();
    sequence_bits.clearRetainingCapacity();

    const literal_code = try sequenceCodeForValue(literal_lens[0], &ll_base, &ll_bits);
    const offset_code = try sequenceCodeForValue(offsets[0], &of_base, &of_bits);
    const match_code = try sequenceCodeForValue(match_lens[0], &ml_base, &ml_bits);
    for (1..literal_lens.len) |i| {
        if (try sequenceCodeForValue(literal_lens[i], &ll_base, &ll_bits) != literal_code) return false;
        if (try sequenceCodeForValue(offsets[i], &of_base, &of_bits) != offset_code) return false;
        if (try sequenceCodeForValue(match_lens[i], &ml_base, &ml_bits) != match_code) return false;
    }

    try payload.appendSlice(allocator, literals_prefix);
    try emitSequenceCount(allocator, payload, literal_lens.len);
    try payload.append(allocator, 0x54); // LL, OF, and ML use RLE_Mode.
    try payload.append(allocator, literal_code);
    try payload.append(allocator, offset_code);
    try payload.append(allocator, match_code);

    var fields: [max_native_sequence_count * 3]BitField = undefined;
    var field_count: usize = 0;
    var i = literal_lens.len;
    while (i > 0) {
        i -= 1;
        fields[field_count] = .{ .value = literal_lens[i] - ll_base[literal_code], .bits = ll_bits[literal_code] };
        field_count += 1;
        fields[field_count] = .{ .value = match_lens[i] - ml_base[match_code], .bits = ml_bits[match_code] };
        field_count += 1;
        fields[field_count] = .{ .value = offsets[i] - of_base[offset_code], .bits = of_bits[offset_code] };
        field_count += 1;
    }
    try emitReverseBitstream(allocator, sequence_bits, fields[0..field_count]);
    try payload.appendSlice(allocator, sequence_bits.items);

    const raw_block_len = std.math.add(usize, 3, block.len) catch return error.IntegerOverflow;
    if (payload.items.len + 3 >= raw_block_len) return false;
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
    return true;
}

fn emitTablePlanSequenceCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    var literals_prefix: std.ArrayList(u8) = .empty;
    defer literals_prefix.deinit(allocator);
    _ = try emitSequenceLiteralsSection(allocator, &literals_prefix, block, literal_lens, literal_ends, tail_start);
    return try emitTablePlanSequenceCompressedBlockWithLiterals(allocator, out, block, last, literals_prefix.items, literal_lens, offsets, match_lens, literal_ends, tail_start);
}

fn emitTablePlanSequenceCompressedBlockWithLiterals(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    const best = (try bestTablePlanSequenceWithLiteralsLen(
        literal_lens,
        offsets,
        match_lens,
        literals_prefix.len,
    )) orelse return false;

    if (literal_lens.len >= wide_borrowed_sequence_plan_min) {
        @branchHint(.unlikely);
        return try emitSequenceCompressedBlockWithTablePlansAndOffsetsBorrowed(
            allocator,
            out,
            block,
            last,
            literal_lens,
            offsets,
            match_lens,
            literal_ends,
            tail_start,
            &best.plan,
            literals_prefix,
            null,
            initial_repeated_offsets,
        );
    }
    return try emitSequenceCompressedBlockWithTablePlans(
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        tail_start,
        best.plan,
        literals_prefix,
        null,
    );
}

fn emitSequenceCompressedBlockWithTablePlans(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    plan: SequenceCombinedEmitPlan,
    prebuilt_literals: ?[]const u8,
    prebuilt_read_fields: ?[]const BitField,
) Error!bool {
    return try emitSequenceCompressedBlockWithTablePlansAndOffsets(
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets,
        match_lens,
        literal_ends,
        tail_start,
        plan,
        prebuilt_literals,
        prebuilt_read_fields,
        initial_repeated_offsets,
    );
}

fn emitSequenceCompressedBlockWithTablePlansAndOffsets(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    plan: SequenceCombinedEmitPlan,
    prebuilt_literals: ?[]const u8,
    prebuilt_read_fields: ?[]const BitField,
    initial_offsets: [3]usize,
) Error!bool {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(allocator);
    if (prebuilt_literals) |prefix|
        try payload.appendSlice(allocator, prefix)
    else
        _ = try emitSequenceLiteralsSection(allocator, &payload, block, literal_lens, literal_ends, tail_start);
    try emitSequenceCount(allocator, &payload, literal_lens.len);
    try payload.append(allocator, sequenceModeByte(plan));
    try appendSequenceTablePayload(allocator, &payload, plan.literal);
    try appendSequenceTablePayload(allocator, &payload, plan.offset);
    try appendSequenceTablePayload(allocator, &payload, plan.match);

    var read_fields: [max_native_sequence_count * 6]BitField = undefined;
    const selected_read_fields = if (prebuilt_read_fields) |fields| fields else blk: {
        const read_field_count = try sequenceReadFieldsWithTablePlansAndOffsets(
            read_fields[0..],
            literal_lens,
            offsets,
            match_lens,
            plan,
            initial_offsets,
        );
        break :blk read_fields[0..read_field_count];
    };

    var sequence_bits: std.ArrayList(u8) = .empty;
    defer sequence_bits.deinit(allocator);
    try emitReverseBitstreamFromReadOrder(allocator, &sequence_bits, selected_read_fields);
    try payload.appendSlice(allocator, sequence_bits.items);

    const raw_block_len = std.math.add(usize, 3, block.len) catch return error.IntegerOverflow;
    if (payload.items.len + 3 >= raw_block_len) return false;
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
    return true;
}

noinline fn emitSequenceCompressedBlockWithTablePlansAndOffsetsBorrowed(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    plan: *const SequenceCombinedEmitPlan,
    prebuilt_literals: ?[]const u8,
    prebuilt_read_fields: ?[]const BitField,
    initial_offsets: [3]usize,
) linksection(wide_sequence_emit_text_section) Error!bool {
    if (literal_lens.len < wide_borrowed_sequence_plan_min or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(allocator);
    if (prebuilt_literals) |prefix|
        try payload.appendSlice(allocator, prefix)
    else
        _ = try emitSequenceLiteralsSection(allocator, &payload, block, literal_lens, literal_ends, tail_start);
    try emitSequenceCount(allocator, &payload, literal_lens.len);
    try payload.append(allocator, sequenceModeByteBorrowed(plan));
    try appendSequenceTablePayloadBorrowed(allocator, &payload, &plan.literal);
    try appendSequenceTablePayloadBorrowed(allocator, &payload, &plan.offset);
    try appendSequenceTablePayloadBorrowed(allocator, &payload, &plan.match);

    var read_fields: [max_native_sequence_count * 6]BitField = undefined;
    const selected_read_fields = if (prebuilt_read_fields) |fields| fields else blk: {
        const read_field_count = try sequenceReadFieldsWithTablePlansAndOffsetsBorrowed(
            read_fields[0..],
            literal_lens,
            offsets,
            match_lens,
            plan,
            initial_offsets,
        );
        break :blk read_fields[0..read_field_count];
    };

    var sequence_bits: std.ArrayList(u8) = .empty;
    defer sequence_bits.deinit(allocator);
    try emitReverseBitstreamFromReadOrder(allocator, &sequence_bits, selected_read_fields);
    try payload.appendSlice(allocator, sequence_bits.items);

    const raw_block_len = std.math.add(usize, 3, block.len) catch return error.IntegerOverflow;
    if (payload.items.len + 3 >= raw_block_len) return false;
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
    return true;
}

fn prepareSequenceCandidateForFrame(
    allocator: std.mem.Allocator,
    candidate: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    current: *const SequenceEncoderState,
) Error!bool {
    return try prepareSequenceCandidateForFrameWithScratch(allocator, candidate, block, last, current, null);
}

fn prepareSequenceCandidateForFrameWithScratch(
    allocator: std.mem.Allocator,
    candidate: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    current: *const SequenceEncoderState,
    large_sequence_scratch: ?*LargeSequenceScratch,
) Error!bool {
    if (candidate.items.len < 3) return error.CorruptFrame;
    const header = std.mem.readInt(u24, candidate.items[0..3], .little);
    if (((header >> 1) & 0x3) != 2) return error.CorruptFrame;
    const payload_len: usize = @intCast(header >> 3);
    if (candidate.items.len != payload_len + 3) return error.CorruptFrame;
    // A dictionary-free first block already uses the standard initial tables
    // and repcodes. Keep its candidate wire unchanged; if it is non-terminal,
    // the commit path parses only the winner to establish the next block state.
    if (current.previous_tables == null and std.meta.eql(current.repeated_offsets, initial_repeated_offsets)) return true;
    const payload = candidate.items[3..];

    var original_state: SequenceFrameState = .{};
    const section = try parseLiteralsSection(payload, &original_state);
    if (section.sequence_count == 0) return true;
    if (section.sequence_count > max_native_sequence_count) {
        var sequence_offset = section.sequence_payload_offset;
        const original_spec = try resolveSequenceModeSpec(
            try parseSequenceModeSpec(payload, &sequence_offset, section.sequence_count),
            null,
        );
        var local_scratch: LargeSequenceScratch = .{};
        defer if (large_sequence_scratch == null) local_scratch.deinit(allocator);
        const scratch = large_sequence_scratch orelse &local_scratch;
        const value_count = std.math.mul(usize, section.sequence_count, 4) catch return error.IntegerOverflow;
        try scratch.values.resize(allocator, value_count);
        const literal_lens = scratch.values.items[0..section.sequence_count];
        const offsets = scratch.values.items[section.sequence_count .. section.sequence_count * 2];
        const match_lens = scratch.values.items[section.sequence_count * 2 .. section.sequence_count * 3];
        const literal_ends = scratch.values.items[section.sequence_count * 3 .. section.sequence_count * 4];
        var decode_state = try initSequenceDecodeState(
            &original_spec,
            section.sequence_count,
            try ReverseBitReader.init(payload[original_spec.bitstream_offset..]),
            initial_repeated_offsets,
        );
        var cursor: usize = 0;
        for (0..section.sequence_count) |i| {
            const sequence = try readModeSequence(&decode_state);
            literal_lens[i] = sequence.literal_len;
            offsets[i] = sequence.match_offset;
            match_lens[i] = sequence.match_len;
            cursor = std.math.add(usize, cursor, sequence.literal_len) catch return error.IntegerOverflow;
            cursor = std.math.add(usize, cursor, sequence.match_len) catch return error.IntegerOverflow;
            if (cursor > block.len) return error.CorruptFrame;
            literal_ends[i] = cursor;
        }
        var replacement: std.ArrayList(u8) = .empty;
        defer replacement.deinit(allocator);
        if (!try emitLargeSequenceCompressedBlockWithState(
            allocator,
            &replacement,
            block,
            last,
            literal_lens,
            offsets,
            match_lens,
            literal_ends,
            cursor,
            scratch,
            if (current.previous_tables) |*tables| tables else null,
            current.repeated_offsets,
        )) return false;
        try candidate.ensureTotalCapacity(allocator, replacement.items.len);
        candidate.clearRetainingCapacity();
        candidate.appendSliceAssumeCapacity(replacement.items);
        return true;
    }
    if (section.sequence_count == 1 and
        section.sequence_payload_offset < payload.len and
        sequence_predefined.isModeByte(payload[section.sequence_payload_offset]))
    {
        const sequence = try single_predefined.decode(payload[section.sequence_payload_offset + 1 ..]);
        var repeated_offsets = initial_repeated_offsets;
        const match_offset = try resolveSequenceOffset(
            sequence.offset_base,
            sequence.offset_bits,
            sequence.offset_extra,
            sequence.literal_len,
            &repeated_offsets,
        );
        const literal_lens = [_]usize{sequence.literal_len};
        const offsets = [_]usize{match_offset};
        const match_lens = [_]usize{sequence.match_len};
        const literal_end = std.math.add(usize, sequence.literal_len, sequence.match_len) catch return error.IntegerOverflow;
        const literal_ends = [_]usize{literal_end};
        return try replaceSequenceCandidateWithFrameState(
            allocator,
            candidate,
            block,
            last,
            &literal_lens,
            &offsets,
            &match_lens,
            &literal_ends,
            literal_end,
            current,
        );
    }

    var sequence_offset = section.sequence_payload_offset;
    const original_spec = try resolveSequenceModeSpec(
        try parseSequenceModeSpec(payload, &sequence_offset, section.sequence_count),
        null,
    );
    var decode_state = try initSequenceDecodeState(
        &original_spec,
        section.sequence_count,
        try ReverseBitReader.init(payload[original_spec.bitstream_offset..]),
        initial_repeated_offsets,
    );
    var literal_lens: [max_native_sequence_count]usize = undefined;
    var offsets: [max_native_sequence_count]usize = undefined;
    var match_lens: [max_native_sequence_count]usize = undefined;
    var literal_ends: [max_native_sequence_count]usize = undefined;
    var cursor: usize = 0;
    for (0..section.sequence_count) |i| {
        const sequence = try readModeSequence(&decode_state);
        literal_lens[i] = sequence.literal_len;
        offsets[i] = sequence.match_offset;
        match_lens[i] = sequence.match_len;
        cursor = std.math.add(usize, cursor, sequence.literal_len) catch return error.IntegerOverflow;
        cursor = std.math.add(usize, cursor, sequence.match_len) catch return error.IntegerOverflow;
        if (cursor > block.len) return error.CorruptFrame;
        literal_ends[i] = cursor;
    }
    const count = section.sequence_count;
    return try replaceSequenceCandidateWithFrameState(
        allocator,
        candidate,
        block,
        last,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        cursor,
        current,
    );
}

fn appendSequenceCandidateAndCommit(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    candidate: []const u8,
    last: bool,
    state: *SequenceEncoderState,
) Error!void {
    if (last) return out.appendSlice(allocator, candidate);

    // Decode only the compact sequence description to derive the committed
    // table and repcode state. Do this into a local copy and append first so an
    // allocation failure cannot advance state past bytes the caller never got.
    if (candidate.len < 3) return error.CorruptFrame;
    const header = std.mem.readInt(u24, candidate[0..3], .little);
    if (((header >> 1) & 0x3) != 2) return error.CorruptFrame;
    const payload_len: usize = @intCast(header >> 3);
    if (candidate.len != payload_len + 3) return error.CorruptFrame;
    const payload = candidate[3..];
    var next = state.*;
    var parse_state: SequenceFrameState = .{ .previous_tables = next.previous_tables };
    const section = try parseLiteralsSection(payload, &parse_state);
    if (section.sequence_count != 0) {
        var sequence_offset = section.sequence_payload_offset;
        const spec = try resolveSequenceModeSpec(
            try parseSequenceModeSpec(payload, &sequence_offset, section.sequence_count),
            next.previous_tables,
        );
        var decode_state = try initSequenceDecodeState(
            &spec,
            section.sequence_count,
            try ReverseBitReader.init(payload[spec.bitstream_offset..]),
            next.repeated_offsets,
        );
        while (decode_state.remaining != 0) _ = try readModeSequence(&decode_state);
        next.previous_tables = spec.tables();
        next.repeated_offsets = decode_state.repeated_offsets;
    }
    try out.appendSlice(allocator, candidate);
    state.* = next;
}

noinline fn appendSequenceCandidateAndCommitKnownOffsets(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    candidate: []const u8,
    state: *SequenceEncoderState,
    repeated_offsets: [3]usize,
) linksection(fast_sequence_record_text_section) Error!void {
    if (state.previous_tables != null or
        !std.meta.eql(state.repeated_offsets, initial_repeated_offsets)) return error.CorruptFrame;
    if (candidate.len < 3) return error.CorruptFrame;
    const header = std.mem.readInt(u24, candidate[0..3], .little);
    if (((header >> 1) & 0x3) != 2) return error.CorruptFrame;
    const payload_len: usize = @intCast(header >> 3);
    if (candidate.len != payload_len + 3) return error.CorruptFrame;

    const payload = candidate[3..];
    var next = state.*;
    var parse_state: SequenceFrameState = .{ .previous_tables = next.previous_tables };
    const section = try parseLiteralsSection(payload, &parse_state);
    if (section.sequence_count == 0) return error.CorruptFrame;
    var sequence_offset = section.sequence_payload_offset;
    const spec = try resolveSequenceModeSpec(
        try parseSequenceModeSpec(payload, &sequence_offset, section.sequence_count),
        next.previous_tables,
    );
    _ = try ReverseBitReader.init(payload[spec.bitstream_offset..]);
    next.previous_tables = spec.tables();
    next.repeated_offsets = repeated_offsets;

    try out.appendSlice(allocator, candidate);
    state.* = next;
}

fn replaceSequenceCandidateWithFrameState(
    allocator: std.mem.Allocator,
    candidate: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    current: *const SequenceEncoderState,
) Error!bool {
    const count = literal_lens.len;
    const plan = (try bestTablePlanSequenceWithPreviousTables(
        block,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        tail_start,
        if (current.previous_tables) |*tables| tables else null,
        current.repeated_offsets,
    )) orelse return false;

    var replacement: std.ArrayList(u8) = .empty;
    defer replacement.deinit(allocator);
    const replacement_ok = if (count >= wide_borrowed_sequence_plan_min) blk: {
        @branchHint(.unlikely);
        break :blk try emitSequenceCompressedBlockWithTablePlansAndOffsetsBorrowed(
            allocator,
            &replacement,
            block,
            last,
            literal_lens[0..count],
            offsets[0..count],
            match_lens[0..count],
            literal_ends[0..count],
            tail_start,
            &plan.plan,
            null,
            null,
            current.repeated_offsets,
        );
    } else try emitSequenceCompressedBlockWithTablePlansAndOffsets(
        allocator,
        &replacement,
        block,
        last,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        tail_start,
        plan.plan,
        null,
        null,
        current.repeated_offsets,
    );
    if (!replacement_ok) return false;
    try candidate.ensureTotalCapacity(allocator, replacement.items.len);
    candidate.clearRetainingCapacity();
    candidate.appendSliceAssumeCapacity(replacement.items);
    return true;
}

fn predefinedSequenceTables() SequenceTables {
    return .{
        .ll_mode = .predefined,
        .of_mode = .predefined,
        .ml_mode = .predefined,
        .literal_rle = null,
        .offset_rle = null,
        .match_rle = null,
    };
}

fn sequenceTablesFromEmitPlan(plan: SequenceCombinedEmitPlan, previous: ?*const SequenceTables) Error!SequenceTables {
    const literal = try sequenceTableFromEmitPlan(plan.literal, .literal, previous);
    const offset = try sequenceTableFromEmitPlan(plan.offset, .offset, previous);
    const match = try sequenceTableFromEmitPlan(plan.match, .match, previous);
    return .{
        .ll_mode = literal.mode,
        .of_mode = offset.mode,
        .ml_mode = match.mode,
        .literal_rle = literal.rle,
        .offset_rle = offset.rle,
        .match_rle = match.rle,
        .literal_fse = literal.fse,
        .offset_fse = offset.fse,
        .match_fse = match.fse,
    };
}

fn sequenceTableFromEmitPlan(
    plan: SequenceTableEmitPlan,
    kind: SequenceTableKind,
    previous: ?*const SequenceTables,
) Error!ResolvedSymbolTable {
    return switch (plan) {
        .rle => |code| .{ .mode = .rle, .rle = try sequenceRleSymbol(kind, code) },
        .predefined => .{ .mode = .predefined, .rle = null },
        .compressed => |compressed| blk: {
            var offset: usize = 0;
            const table = try readFseSequenceTable(
                compressed.table_payload[0..compressed.table_payload_len],
                &offset,
                sequenceTableBases(kind),
                sequenceTableBits(kind),
                sequenceTableSymbolCountMax(kind),
                sequenceTableAccuracyLogMax(kind),
            );
            if (offset != compressed.table_payload_len) return error.CorruptFrame;
            break :blk .{ .mode = .compressed, .rle = null, .fse = table };
        },
        .repeat => blk: {
            const tables = previous orelse return error.CorruptFrame;
            break :blk switch (kind) {
                .literal => .{ .mode = tables.ll_mode, .rle = tables.literal_rle, .fse = tables.literal_fse },
                .offset => .{ .mode = tables.of_mode, .rle = tables.offset_rle, .fse = tables.offset_fse },
                .match => .{ .mode = tables.ml_mode, .rle = tables.match_rle, .fse = tables.match_fse },
            };
        },
    };
}

fn emitMultiSequencePredefinedCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!bool {
    var literals_prefix: std.ArrayList(u8) = .empty;
    defer literals_prefix.deinit(allocator);
    _ = try emitSequenceLiteralsSection(allocator, &literals_prefix, block, literal_lens, literal_ends, tail_start);
    return try emitMultiSequencePredefinedCompressedBlockWithLiterals(allocator, out, block, last, literals_prefix.items, literal_lens, offsets, match_lens);
}

fn emitMultiSequencePredefinedCompressedBlockWithLiterals(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
) Error!bool {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(allocator);
    var sequence_bits: std.ArrayList(u8) = .empty;
    defer sequence_bits.deinit(allocator);
    return try emitMultiSequencePredefinedCompressedBlockWithLiteralsAndScratch(
        allocator,
        out,
        block,
        last,
        literals_prefix,
        literal_lens,
        offsets,
        match_lens,
        &payload,
        &sequence_bits,
    );
}

fn emitMultiSequencePredefinedCompressedBlockWithLiteralsAndScratch(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    literals_prefix: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    payload: *std.ArrayList(u8),
    sequence_bits: *std.ArrayList(u8),
) Error!bool {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return false;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return false;
    payload.clearRetainingCapacity();
    sequence_bits.clearRetainingCapacity();

    const literal_plan = (try planPredefinedSequenceValues(literal_lens, &sequence_predefined.literal_symbols, 0)) orelse return false;
    const offset_plan = (try planPredefinedSequenceValues(offsets, &sequence_predefined.offset_symbols, 2)) orelse return false;
    const match_plan = (try planPredefinedSequenceValues(match_lens, &sequence_predefined.match_symbols, 0)) orelse return false;

    try payload.appendSlice(allocator, literals_prefix);
    try emitSequenceCount(allocator, payload, literal_lens.len);
    try payload.append(allocator, 0x00); // LL, OF, and ML all use Predefined_Mode.

    var read_fields: [max_native_sequence_count * 6]BitField = undefined;
    const read_field_count = try predefinedSequenceReadFields(
        read_fields[0..],
        literal_plan,
        offset_plan,
        match_plan,
        literal_lens,
        offsets,
        match_lens,
    );

    try emitReverseBitstreamFromReadOrder(allocator, sequence_bits, read_fields[0..read_field_count]);
    try payload.appendSlice(allocator, sequence_bits.items);

    const raw_block_len = std.math.add(usize, 3, block.len) catch return error.IntegerOverflow;
    if (payload.items.len + 3 >= raw_block_len) return false;
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
    return true;
}

const SequenceLiteralsInfo = struct {
    regenerated_len: usize,
    payload_len: usize,
    rle_byte: ?u8 = null,
};

fn emitSequenceLiteralsSection(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!SequenceLiteralsInfo {
    const info = try sequenceLiteralsInfo(block, literal_lens, literal_ends, tail_start);
    if (info.rle_byte) |byte| {
        try emitLiteralsHeader(allocator, out, .rle, info.regenerated_len);
        try out.append(allocator, byte);
        return info;
    }

    if (try emitSequenceHuffmanLiteralsSection(allocator, out, block, literal_lens, literal_ends, tail_start, info)) {
        return info;
    }

    try emitLiteralsHeader(allocator, out, .raw, info.regenerated_len);
    try appendSequenceRawLiterals(allocator, out, block, literal_lens, literal_ends, tail_start);
    return info;
}

fn emitSequenceHuffmanLiteralsSection(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    info: SequenceLiteralsInfo,
) Error!bool {
    if (info.regenerated_len < 64) return false;
    var literals: std.ArrayList(u8) = .empty;
    defer literals.deinit(allocator);
    try literals.ensureTotalCapacity(allocator, info.regenerated_len);
    try appendSequenceRawLiterals(allocator, &literals, block, literal_lens, literal_ends, tail_start);
    if (literals.items.len != info.regenerated_len) return error.CorruptFrame;

    const plan = smallHuffmanLiteralPlan(literals.items) orelse return false;
    var huffman_tree: std.ArrayList(u8) = .empty;
    defer huffman_tree.deinit(allocator);
    if (!try emitSmallHuffmanTree(allocator, &huffman_tree, &plan)) return false;

    var compressed: std.ArrayList(u8) = .empty;
    defer compressed.deinit(allocator);
    try emitHuffmanLiteralsSectionWithPlan(allocator, &compressed, literals.items, &plan, huffman_tree.items, false) orelse return false;

    const raw_header_len = try literalsHeaderLen(info.regenerated_len);
    const raw_len = std.math.add(usize, raw_header_len, info.payload_len) catch return error.IntegerOverflow;
    if (compressed.items.len >= raw_len) return false;
    try out.appendSlice(allocator, compressed.items);
    return true;
}

fn appendSequenceRawLiterals(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!void {
    if (literal_lens.len != literal_ends.len) return error.CorruptFrame;
    var literal_start: usize = 0;
    for (literal_lens, 0..) |literal_len, i| {
        if (literal_start > block.len or literal_len > block.len - literal_start) return error.CorruptFrame;
        try out.appendSlice(allocator, block[literal_start..][0..literal_len]);
        if (literal_ends[i] < literal_start + literal_len or literal_ends[i] > block.len) return error.CorruptFrame;
        literal_start = literal_ends[i];
    }
    if (tail_start > block.len) return error.CorruptFrame;
    try out.appendSlice(allocator, block[tail_start..]);
}

fn sequenceLiteralsInfo(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!SequenceLiteralsInfo {
    if (literal_lens.len != literal_ends.len) return error.CorruptFrame;
    if (tail_start > block.len) return error.CorruptFrame;
    var info: SequenceLiteralsInfo = .{
        .regenerated_len = block.len - tail_start,
        .payload_len = block.len - tail_start,
    };
    var first_literal_byte: u8 = 0;
    var have_literal_byte = false;
    var all_same = true;

    var literal_start: usize = 0;
    for (literal_lens, 0..) |literal_len, i| {
        if (literal_start > block.len or literal_len > block.len - literal_start) return error.CorruptFrame;
        info.regenerated_len = std.math.add(usize, info.regenerated_len, literal_len) catch return error.IntegerOverflow;
        info.payload_len = info.regenerated_len;
        updateLiteralRunInfo(block[literal_start..][0..literal_len], &first_literal_byte, &have_literal_byte, &all_same);
        if (literal_ends[i] < literal_start + literal_len or literal_ends[i] > block.len) return error.CorruptFrame;
        literal_start = literal_ends[i];
    }
    updateLiteralRunInfo(block[tail_start..], &first_literal_byte, &have_literal_byte, &all_same);

    // Sequence-compressed blocks often carry only a handful of separator or
    // tail literals. When all regenerated literals are the same byte, the
    // standard RLE-literals section avoids storing those bytes repeatedly while
    // keeping the sequence table and match replay unchanged.
    if (info.regenerated_len != 0 and all_same) {
        info.rle_byte = first_literal_byte;
        info.payload_len = 1;
    }
    return info;
}

fn sequenceLiteralsPayloadSectionLen(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: ?[]const usize,
    tail_start: usize,
) Error!usize {
    const info = try sequenceLiteralsPayloadInfo(block, literal_lens, literal_ends, tail_start);
    var best = std.math.add(usize, try literalsHeaderLen(info.regenerated_len), info.payload_len) catch return error.IntegerOverflow;
    if (literal_ends) |ends| {
        if (try sequenceHuffmanLiteralsSectionLen(block, literal_lens, ends, tail_start, info)) |candidate| {
            if (candidate < best) best = candidate;
        }
    }
    return best;
}

fn sequenceLiteralsPayloadSectionLenFromHistogram(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    histogram: *const MixedLiteralHistogram,
    huffman_bit_prefix: *MixedHuffmanBitPrefix,
) Error!usize {
    const raw_payload_len = if (histogram.unique_count == 1) 1 else histogram.regenerated_len;
    var best = std.math.add(usize, try literalsHeaderLen(histogram.regenerated_len), raw_payload_len) catch return error.IntegerOverflow;
    if (histogram.unique_count < 2 or histogram.regenerated_len < 64) return best;

    var plan: SmallHuffmanLiteralPlan = .{};
    plan.frequencies = histogram.frequencies;
    plan.max_symbol = histogram.max_symbol;
    for (histogram.frequencies, 0..) |frequency, symbol| {
        if (frequency == 0) continue;
        plan.symbols[plan.len] = @intCast(symbol);
        plan.len += 1;
    }
    finalizeSmallHuffmanLiteralPlan(&plan) orelse return best;
    const tree_len = try smallHuffmanTreeSerializedLen(&plan) orelse return best;
    try huffman_bit_prefix.prepare(block, &plan);
    const streams_len = try smallHuffmanLiteralStreamsSerializedLenFromPrefix(block, literal_lens, literal_ends, tail_start, histogram.regenerated_len, huffman_bit_prefix) orelse return best;
    const compressed_size = std.math.add(usize, tree_len, streams_len) catch return error.IntegerOverflow;
    const header_len = huffmanLiteralsHeaderLen(histogram.regenerated_len, compressed_size) catch |err| switch (err) {
        error.UnsupportedZstdFeature => return best,
        else => return err,
    };
    const compressed = std.math.add(usize, header_len, compressed_size) catch return error.IntegerOverflow;
    if (compressed < best) best = compressed;
    return best;
}

fn sequenceHuffmanLiteralsSectionLen(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    info: SequenceLiteralsInfo,
) Error!?usize {
    if (info.rle_byte != null or info.regenerated_len < 64) return null;
    const plan = smallHuffmanLiteralPlanFromSequence(block, literal_lens, literal_ends, tail_start, info.regenerated_len) orelse return null;
    const tree_len = try smallHuffmanTreeSerializedLen(&plan) orelse return null;
    const streams_len = try smallHuffmanLiteralStreamsSerializedLenFromSequence(
        block,
        literal_lens,
        literal_ends,
        tail_start,
        info.regenerated_len,
        &plan,
    ) orelse return null;
    const compressed_size = std.math.add(usize, tree_len, streams_len) catch return error.IntegerOverflow;
    const header_len = huffmanLiteralsHeaderLen(info.regenerated_len, compressed_size) catch |err| switch (err) {
        error.UnsupportedZstdFeature => return null,
        else => return err,
    };
    return std.math.add(usize, header_len, compressed_size) catch return error.IntegerOverflow;
}

fn huffmanLiteralsHeaderLen(regenerated_size: usize, compressed_size: usize) Error!usize {
    if (compressed_size == 0) return error.CorruptFrame;
    if (regenerated_size <= 0x3ff and compressed_size <= 0x3ff) return 3;
    if (regenerated_size <= 0x3fff and compressed_size <= 0x3fff) return 4;
    if (regenerated_size <= 0x3ffff and compressed_size <= 0x3ffff) return 5;
    return error.UnsupportedZstdFeature;
}

fn smallHuffmanLiteralPlanFromSequence(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    regenerated_len: usize,
) ?SmallHuffmanLiteralPlan {
    if (regenerated_len < 64 or regenerated_len > 0x3ffff) return null;
    if (literal_lens.len != literal_ends.len) return null;
    // Four independent lanes break the loop-carried read/modify/write chain
    // for common literal bytes. Mixed lookahead rebuilds this histogram for
    // many candidate paths, where repeated JSON punctuation otherwise makes
    // a single frequency slot serialize most of the scan.
    var frequencies: SmallHuffmanFrequencies = @splat(@splat(0));
    var literal_bytes: usize = 0;
    var literal_start: usize = 0;
    for (literal_lens, 0..) |literal_len, i| {
        if (literal_start > block.len or literal_len > block.len - literal_start) return null;
        literal_bytes += literal_len;
        addBytesToSmallHuffmanFrequencies(&frequencies, block[literal_start..][0..literal_len]);
        if (literal_ends[i] < literal_start + literal_len or literal_ends[i] > block.len) return null;
        literal_start = literal_ends[i];
    }
    if (tail_start > block.len) return null;
    literal_bytes += block.len - tail_start;
    if (literal_bytes != regenerated_len) return null;
    addBytesToSmallHuffmanFrequencies(&frequencies, block[tail_start..]);
    var plan = smallHuffmanLiteralPlanFromFrequencies(&frequencies);
    finalizeSmallHuffmanLiteralPlan(&plan) orelse return null;
    return plan;
}

const small_huffman_frequency_lane_count = 4;
const SmallHuffmanFrequencies = [small_huffman_frequency_lane_count][256]u32;

fn addBytesToSmallHuffmanFrequencies(frequencies: *SmallHuffmanFrequencies, bytes: []const u8) void {
    var cursor: usize = 0;
    while (cursor + small_huffman_frequency_lane_count <= bytes.len) : (cursor += small_huffman_frequency_lane_count) {
        inline for (0..small_huffman_frequency_lane_count) |lane| frequencies[lane][bytes[cursor + lane]] += 1;
    }
    for (bytes[cursor..]) |byte| frequencies[0][byte] += 1;
}

fn smallHuffmanLiteralPlanFromFrequencies(frequencies: *const SmallHuffmanFrequencies) SmallHuffmanLiteralPlan {
    // This loop overwrites every frequency slot. Avoid zeroing the 1 KiB field
    // first while retaining the plan's zero-initialized code lookup tables.
    var plan: SmallHuffmanLiteralPlan = .{ .frequencies = undefined };
    for (0..256) |symbol| {
        var frequency: u32 = 0;
        inline for (0..small_huffman_frequency_lane_count) |lane| frequency += frequencies[lane][symbol];
        plan.frequencies[symbol] = frequency;
        if (frequency == 0) continue;
        plan.symbols[plan.len] = @intCast(symbol);
        plan.len += 1;
    }
    return plan;
}

fn finalizeSmallHuffmanLiteralPlan(plan: *SmallHuffmanLiteralPlan) ?void {
    if (plan.len < 2 or plan.len > plan.symbols.len) return null;
    plan.max_symbol = 0;
    for (plan.symbols[0..plan.len]) |symbol| plan.max_symbol = @max(plan.max_symbol, symbol);
    fillSmallHuffmanWeights(plan) orelse return null;
}

fn smallHuffmanLiteralStreamsSerializedLenFromSequence(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    regenerated_len: usize,
    plan: *const SmallHuffmanLiteralPlan,
) Error!?usize {
    // Every generated literal consumes at most max_bit_count bits. Proving the
    // aggregate bound once keeps overflow checks out of the byte-wise hot loop
    // used for every mixed-plan candidate.
    _ = std.math.mul(usize, regenerated_len, @as(usize, plan.max_bit_count)) catch return error.IntegerOverflow;
    if (regenerated_len <= 1023) {
        var bit_count: usize = 0;
        var literal_start: usize = 0;
        for (literal_lens, 0..) |literal_len, i| {
            if (literal_start > block.len or literal_len > block.len - literal_start) return error.CorruptFrame;
            for (block[literal_start..][0..literal_len]) |byte| {
                const bits = plan.bit_counts[byte];
                if (bits == 0) return error.CorruptFrame;
                bit_count += bits;
            }
            if (literal_ends[i] < literal_start + literal_len or literal_ends[i] > block.len) return error.CorruptFrame;
            literal_start = literal_ends[i];
        }
        if (tail_start > block.len) return error.CorruptFrame;
        for (block[tail_start..]) |byte| {
            const bits = plan.bit_counts[byte];
            if (bits == 0) return error.CorruptFrame;
            bit_count = std.math.add(usize, bit_count, bits) catch return error.IntegerOverflow;
        }
        return (bit_count + 1 + 7) / 8;
    }

    var bit_counts: [4]usize = .{ 0, 0, 0, 0 };
    var literal_index: usize = 0;
    const segment_len = (regenerated_len + 3) / 4;
    var literal_start: usize = 0;
    for (literal_lens, 0..) |literal_len, i| {
        if (literal_start > block.len or literal_len > block.len - literal_start) return error.CorruptFrame;
        try addSmallHuffmanStreamBitsKnown(block[literal_start..][0..literal_len], plan, regenerated_len, segment_len, &literal_index, &bit_counts);
        if (literal_ends[i] < literal_start + literal_len or literal_ends[i] > block.len) return error.CorruptFrame;
        literal_start = literal_ends[i];
    }
    if (tail_start > block.len) return error.CorruptFrame;
    try addSmallHuffmanStreamBitsKnown(block[tail_start..], plan, regenerated_len, segment_len, &literal_index, &bit_counts);
    if (literal_index != regenerated_len) return error.CorruptFrame;

    var len: usize = 6;
    for (bit_counts) |bits| {
        const stream_len = (bits + 1 + 7) / 8;
        if (stream_len > std.math.maxInt(u16)) return null;
        len = std.math.add(usize, len, stream_len) catch return error.IntegerOverflow;
    }
    return len;
}

fn smallHuffmanLiteralStreamsSerializedLenFromPrefix(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    regenerated_len: usize,
    prefix: *const MixedHuffmanBitPrefix,
) Error!?usize {
    if (literal_lens.len != literal_ends.len or tail_start > block.len or prefix.block_len != block.len) return error.CorruptFrame;
    var bit_counts: [4]usize = @splat(0);
    var literal_index: usize = 0;
    const segment_len = if (regenerated_len <= 1023) regenerated_len else (regenerated_len + 3) / 4;
    var literal_start: usize = 0;
    for (literal_lens, literal_ends) |literal_len, literal_end| {
        if (literal_start > block.len or literal_len > block.len - literal_start) return error.CorruptFrame;
        try addSmallHuffmanStreamBitsFromPrefix(prefix, literal_start, literal_len, regenerated_len, segment_len, &literal_index, &bit_counts);
        if (literal_end < literal_start + literal_len or literal_end > block.len) return error.CorruptFrame;
        literal_start = literal_end;
    }
    try addSmallHuffmanStreamBitsFromPrefix(prefix, tail_start, block.len - tail_start, regenerated_len, segment_len, &literal_index, &bit_counts);
    if (literal_index != regenerated_len) return error.CorruptFrame;

    if (regenerated_len <= 1023) return (bit_counts[0] + 1 + 7) / 8;
    var len: usize = 6;
    for (bit_counts) |bits| {
        const stream_len = (bits + 1 + 7) / 8;
        if (stream_len > std.math.maxInt(u16)) return null;
        len = std.math.add(usize, len, stream_len) catch return error.IntegerOverflow;
    }
    return len;
}

fn addSmallHuffmanStreamBitsFromPrefix(
    prefix: *const MixedHuffmanBitPrefix,
    physical_start: usize,
    len: usize,
    regenerated_len: usize,
    segment_len: usize,
    literal_index: *usize,
    bit_counts: *[4]usize,
) Error!void {
    var physical = physical_start;
    var remaining = len;
    while (remaining != 0) {
        if (literal_index.* >= regenerated_len) return error.CorruptFrame;
        const stream_index = if (regenerated_len <= 1023) 0 else @min(literal_index.* / segment_len, 3);
        const stream_end = if (regenerated_len <= 1023 or stream_index == 3) regenerated_len else (stream_index + 1) * segment_len;
        const run_len = @min(remaining, stream_end - literal_index.*);
        if (run_len == 0) return error.CorruptFrame;
        bit_counts[stream_index] += try prefix.range(physical, run_len);
        physical += run_len;
        remaining -= run_len;
        literal_index.* += run_len;
    }
}

fn addSmallHuffmanStreamBits(
    bytes: []const u8,
    plan: *const SmallHuffmanLiteralPlan,
    regenerated_len: usize,
    segment_len: usize,
    literal_index: *usize,
    bit_counts: *[4]usize,
) Error!void {
    var cursor: usize = 0;
    while (cursor < bytes.len) {
        if (literal_index.* >= regenerated_len) return error.CorruptFrame;
        const stream_index: usize = if (regenerated_len <= 1023)
            0
        else
            @min(literal_index.* / segment_len, 3);
        const stream_end = if (regenerated_len <= 1023) regenerated_len else @min(regenerated_len, (stream_index + 1) * segment_len);
        const run_len = @min(bytes.len - cursor, stream_end - literal_index.*);
        if (run_len == 0) return error.CorruptFrame;
        const run = bytes[cursor..][0..run_len];

        var run_index: usize = 0;
        while (run_index + 8 <= run.len) : (run_index += 8) {
            const chunk = run[run_index..][0..8];
            var chunk_bits: usize = 0;
            inline for (0..8) |i| {
                const bits = plan.bit_counts[chunk[i]];
                if (bits == 0) return error.CorruptFrame;
                chunk_bits += bits;
            }
            bit_counts[stream_index] += chunk_bits;
        }
        for (run[run_index..]) |byte| {
            const bits = plan.bit_counts[byte];
            if (bits == 0) return error.CorruptFrame;
            bit_counts[stream_index] += bits;
        }
        cursor += run_len;
        literal_index.* += run_len;
    }
}

fn addSmallHuffmanStreamBitsKnown(
    bytes: []const u8,
    plan: *const SmallHuffmanLiteralPlan,
    regenerated_len: usize,
    segment_len: usize,
    literal_index: *usize,
    bit_counts: *[4]usize,
) Error!void {
    // This variant is called only with a plan built from this exact logical
    // literal stream, so every indexed code width is non-zero. Keep all range
    // and stream-boundary checks, but omit the redundant per-byte membership
    // branch from the hot four-stream sizing pass.
    var cursor: usize = 0;
    while (cursor < bytes.len) {
        if (literal_index.* >= regenerated_len) return error.CorruptFrame;
        const stream_index: usize = @min(literal_index.* / segment_len, 3);
        const stream_end = @min(regenerated_len, (stream_index + 1) * segment_len);
        const run_len = @min(bytes.len - cursor, stream_end - literal_index.*);
        if (run_len == 0) return error.CorruptFrame;
        const run = bytes[cursor..][0..run_len];

        var run_index: usize = 0;
        while (run_index + 8 <= run.len) : (run_index += 8) {
            const chunk = run[run_index..][0..8];
            var chunk_bits: usize = 0;
            inline for (0..8) |i| chunk_bits += plan.bit_counts[chunk[i]];
            bit_counts[stream_index] += chunk_bits;
        }
        for (run[run_index..]) |byte| bit_counts[stream_index] += plan.bit_counts[byte];
        cursor += run_len;
        literal_index.* += run_len;
    }
}

fn updateLiteralRunInfo(bytes: []const u8, first_literal_byte: *u8, have_literal_byte: *bool, all_same: *bool) void {
    if (bytes.len == 0 or !all_same.*) return;
    if (!have_literal_byte.*) {
        first_literal_byte.* = bytes[0];
        have_literal_byte.* = true;
    }
    if (!std.mem.allEqual(u8, bytes, first_literal_byte.*)) all_same.* = false;
}

test "zstd literal run info matches byte reference" {
    const Case = struct { bytes: []const u8, initial: ?u8 };
    const cases = [_]Case{
        .{ .bytes = "", .initial = null },
        .{ .bytes = "a", .initial = null },
        .{ .bytes = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", .initial = null },
        .{ .bytes = "aaaaaaaaaaaaaaabaaaaaaaaaaaaaaaa", .initial = null },
        .{ .bytes = "aaaaaaaaaaaaaaaa", .initial = 'a' },
        .{ .bytes = "aaaaaaaaaaaaaaaa", .initial = 'b' },
    };
    for (cases) |case| {
        var expected_first: u8 = case.initial orelse 0;
        var expected_have = case.initial != null;
        var expected_same = true;
        for (case.bytes) |byte| {
            if (!expected_have) {
                expected_first = byte;
                expected_have = true;
            } else if (byte != expected_first) expected_same = false;
        }
        var actual_first: u8 = case.initial orelse 0;
        var actual_have = case.initial != null;
        var actual_same = true;
        updateLiteralRunInfo(case.bytes, &actual_first, &actual_have, &actual_same);
        try std.testing.expectEqual(expected_first, actual_first);
        try std.testing.expectEqual(expected_have, actual_have);
        try std.testing.expectEqual(expected_same, actual_same);
    }
}

fn multiSequencePayloadLen(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    tail_start: usize,
) Error!usize {
    return try multiSequencePayloadLenInternal(block, literal_lens, offsets, match_lens, null, tail_start);
}

fn multiSequencePayloadLenWithLiteralEnds(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!usize {
    return try multiSequencePayloadLenInternal(block, literal_lens, offsets, match_lens, literal_ends, tail_start);
}

fn bestSequencePayloadLenWithLiteralEnds(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!usize {
    // Match-finder scoring must use the same RLE/predefined/mixed table choice
    // as the emitter. Otherwise a candidate that encodes smaller with
    // predefined tables (notably single-sequence blocks, which avoid three RLE
    // symbol bytes) or with a mixed table-mode byte can be incorrectly
    // discarded before emitBestSequenceCompressedBlock has a chance to choose
    // the smaller wire representation.
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len or literal_lens.len != literal_ends.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    // All three sequence-table families serialize the same literal section.
    // Mixed lookahead calls this scorer hundreds of times, so build the
    // histogram/Huffman estimate once per candidate rather than once per
    // table family.
    const literals_section_len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);

    var best: ?usize = null;
    if (rleSequencePayloadLenForValuesWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |len| {
        chooseShortestPayloadLen(len, &best);
    } else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }

    if (predefinedSequencePayloadLenWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |len| {
        chooseShortestPayloadLen(len, &best);
    } else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }

    if (literal_lens.len > 1) {
        if (try bestTablePayloadLenWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |payload_len| {
            chooseShortestPayloadLen(payload_len, &best);
        }
    }

    return best orelse error.CorruptFrame;
}

fn bestSequencePayloadLenWithLiteralEndsAndHistogram(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    histogram: *const MixedLiteralHistogram,
    huffman_bit_prefix: *MixedHuffmanBitPrefix,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len or literal_lens.len != literal_ends.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count or tail_start > block.len) return error.CorruptFrame;
    var expected_literals = block.len - tail_start;
    for (literal_lens) |literal_len| expected_literals += literal_len;
    if (expected_literals != histogram.regenerated_len) return error.CorruptFrame;
    const literals_section_len = try sequenceLiteralsPayloadSectionLenFromHistogram(block, literal_lens, literal_ends, tail_start, histogram, huffman_bit_prefix);
    var best: ?usize = null;
    if (rleSequencePayloadLenForValuesWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |len| chooseShortestPayloadLen(len, &best) else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }
    if (predefinedSequencePayloadLenWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |len| chooseShortestPayloadLen(len, &best) else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }
    if (literal_lens.len > 1) {
        if (try bestTablePayloadLenWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len)) |payload_len| chooseShortestPayloadLen(payload_len, &best);
    }
    return best orelse error.CorruptFrame;
}

fn chooseShortestPayloadLen(candidate: usize, best: *?usize) void {
    const current = best.* orelse {
        best.* = candidate;
        return;
    };
    if (candidate < current) best.* = candidate;
}

const SequenceTableKind = enum { literal, offset, match };

const SequenceTableEmitPlan = union(enum) {
    rle: u8,
    predefined: PredefinedSequencePlan,
    compressed: CompressedSequencePlan,
    repeat: RepeatSequencePlan,
};

const CompressedSequencePlan = struct {
    len: usize = 0,
    accuracy_log: u8 = 0,
    codes: if (builtin.is_test) [max_native_sequence_count]u8 else void = if (builtin.is_test) undefined else {},
    initial_state: u8 = 0,
    value_bit_count: u16 = 0,
    transition_bit_count: u16 = 0,
    // These state details are valuable to the three-way transition oracle but
    // redundant in production: emission consumes the canonical codes plus the
    // independently stored transition values/widths below.
    next_states: if (builtin.is_test) [max_native_sequence_count]u8 else void = if (builtin.is_test) undefined else {},
    state_bits: if (builtin.is_test) [max_native_sequence_count]u8 else void = if (builtin.is_test) undefined else {},
    transition_values: if (builtin.is_test) [max_native_sequence_count]u8 else void = if (builtin.is_test) undefined else {},
    transition_bits: if (builtin.is_test) [max_native_sequence_count]u8 else void = if (builtin.is_test) undefined else {},
    // Production needs only the canonical code plus the transition value and
    // width: 6 + 7 + 3 bits fit exactly in one u16. Tests retain the expanded
    // fields above so the independent transition builders remain inspectable.
    packed_steps: if (builtin.is_test) void else [max_native_sequence_count]u16 = if (builtin.is_test) {} else undefined,
    table_payload: [64]u8 = undefined,
    table_payload_len: usize = 0,
};

const compressed_sequence_code_bits = 6;
const compressed_sequence_transition_value_bits = 7;
const compressed_sequence_transition_width_bits = 3;
const compressed_sequence_code_mask: u16 = (1 << compressed_sequence_code_bits) - 1;
const compressed_sequence_transition_value_mask: u16 = (1 << compressed_sequence_transition_value_bits) - 1;
const compressed_sequence_transition_width_mask: u16 = (1 << compressed_sequence_transition_width_bits) - 1;

comptime {
    std.debug.assert(max_fse_compression_symbol <= compressed_sequence_code_mask);
    std.debug.assert(max_native_sequence_count * @as(usize, of_bits[of_bits.len - 1]) <= std.math.maxInt(u16));
    std.debug.assert((max_native_sequence_count - 1) * compressed_sequence_transition_width_mask <= std.math.maxInt(u16));
}

inline fn compressedSequencePackedStep(plan: *const CompressedSequencePlan, index: usize) u16 {
    if (comptime !builtin.is_test) return plan.packed_steps[index];
    const transition_value = if (index + 1 < plan.len) plan.transition_values[index] else 0;
    const transition_bits = if (index + 1 < plan.len) plan.transition_bits[index] else 0;
    return @as(u16, plan.codes[index]) |
        (@as(u16, transition_value) << compressed_sequence_code_bits) |
        (@as(u16, transition_bits) << (compressed_sequence_code_bits + compressed_sequence_transition_value_bits));
}

inline fn compressedSequencePackedCode(step: u16) u8 {
    return @intCast(step & compressed_sequence_code_mask);
}

inline fn compressedSequencePackedTransitionValue(step: u16) u8 {
    return @intCast((step >> compressed_sequence_code_bits) & compressed_sequence_transition_value_mask);
}

inline fn compressedSequencePackedTransitionBits(step: u16) u8 {
    return @intCast(step >> (compressed_sequence_code_bits + compressed_sequence_transition_value_bits));
}

inline fn compressedSequenceCode(plan: *const CompressedSequencePlan, index: usize) u8 {
    return if (comptime builtin.is_test)
        plan.codes[index]
    else
        compressedSequencePackedCode(plan.packed_steps[index]);
}

inline fn setCompressedSequenceCode(plan: *CompressedSequencePlan, index: usize, code: u8) void {
    std.debug.assert(code <= max_fse_compression_symbol);
    if (comptime builtin.is_test)
        plan.codes[index] = code
    else
        plan.packed_steps[index] = code;
}

inline fn compressedSequenceTransitionValue(plan: *const CompressedSequencePlan, index: usize) u8 {
    return if (comptime builtin.is_test)
        plan.transition_values[index]
    else
        compressedSequencePackedTransitionValue(plan.packed_steps[index]);
}

inline fn compressedSequenceTransitionBits(plan: *const CompressedSequencePlan, index: usize) u8 {
    return if (comptime builtin.is_test)
        plan.transition_bits[index]
    else
        compressedSequencePackedTransitionBits(plan.packed_steps[index]);
}

inline fn setCompressedSequenceTransition(plan: *CompressedSequencePlan, index: usize, value: u8, bits: u8) void {
    std.debug.assert(
        plan.accuracy_log <= compressed_sequence_transition_width_mask and
            bits <= plan.accuracy_log and
            value <= compressed_sequence_transition_value_mask,
    );
    if (comptime builtin.is_test) {
        plan.transition_values[index] = value;
        plan.transition_bits[index] = bits;
    } else {
        const code = plan.packed_steps[index] & compressed_sequence_code_mask;
        plan.packed_steps[index] = code |
            (@as(u16, value) << compressed_sequence_code_bits) |
            (@as(u16, bits) << (compressed_sequence_code_bits + compressed_sequence_transition_value_bits));
    }
}

const RepeatSequenceSource = struct {
    mode: SymbolMode,
    rle: ?SequenceSymbol,
    symbols: []const SequenceSymbol,
    accuracy_log: u8,
};

const RepeatSequencePlan = struct {
    len: usize,
    source: RepeatSequenceSource,
    states: [max_native_sequence_count]u16 = undefined,
};

const LargeCompressedSequenceBuffers = struct {
    direct_transitions: bool = false,
    codes: []u8,
    next_states: []u8,
    state_bits: []u8,
    transition_values: []u8,
    transition_bits: []u8,
};

const LargeCompressedSequencePlan = struct {
    accuracy_log: u8,
    codes: []const u8,
    initial_state: u8,
    next_states: []const u8,
    state_bits: []const u8,
    transition_values: []const u8,
    transition_bits: []const u8,
    table_payload: [64]u8,
    table_payload_len: usize,
};

const LargeSequenceTableEmitPlan = union(enum) {
    rle: u8,
    predefined: []const u8,
    compressed: LargeCompressedSequencePlan,
    repeat: LargeRepeatSequencePlan,
};

const LargeRepeatSequencePlan = struct {
    len: usize,
    source: RepeatSequenceSource,
    states: []const u16,
};

const LargeSequenceCombinedEmitPlan = struct {
    literal: LargeSequenceTableEmitPlan,
    offset: LargeSequenceTableEmitPlan,
    match: LargeSequenceTableEmitPlan,
};

const LargeSequenceCombinedPlanCandidate = struct {
    plan: LargeSequenceCombinedEmitPlan,
    payload_len: usize,
};

const LargeSequenceTablePlanAlternatives = struct {
    items: [4]LargeSequenceTableEmitPlan = undefined,
    len: usize = 0,
    value_bit_count: usize = 0,

    fn add(self: *LargeSequenceTablePlanAlternatives, plan: LargeSequenceTableEmitPlan) Error!void {
        if (self.len >= self.items.len) return error.CorruptFrame;
        self.items[self.len] = plan;
        self.len += 1;
    }
};

fn largeSequenceTablePlanAlternatives(
    values: []const usize,
    kind: SequenceTableKind,
    predefined_states: []u8,
    viable_masks: []u64,
    compressed_buffers: LargeCompressedSequenceBuffers,
    repeat_states: []u16,
    repeat_viable_masks: []u64,
    previous: ?RepeatSequenceSource,
) linksection(wide_sequence_emit_text_section) Error!LargeSequenceTablePlanAlternatives {
    var alternatives: LargeSequenceTablePlanAlternatives = .{};
    if (values.len == 0 or values.len > max_large_native_sequence_count or
        compressed_buffers.codes.len != values.len) return alternatives;

    // RLE, predefined, compressed, and repeat alternatives all consume the
    // same canonical code stream. Materialize it once instead of remapping
    // every LL/ML value independently for each candidate family.
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    for (values, 0..) |value, i| {
        const code = sequenceCodeForValue(value, bases, bits) catch |err| switch (err) {
            error.CorruptFrame => return alternatives,
            else => return err,
        };
        if (code > max_fse_compression_symbol) return alternatives;
        compressed_buffers.codes[i] = code;
        alternatives.value_bit_count += bits[code];
    }
    if (rleSequenceCode(compressed_buffers.codes)) |code|
        try alternatives.add(.{ .rle = code });
    const predefined_ok = large_predefined.plan(
        compressed_buffers.codes,
        switch (kind) {
            .literal => &predefined_literal_state_masks,
            .offset => &predefined_offset_code_state_masks,
            .match => &predefined_match_state_masks,
        },
        switch (kind) {
            .literal => .literal,
            .offset => .offset,
            .match => .match,
        },
        predefined_states,
        viable_masks,
    );
    if (predefined_ok) try alternatives.add(.{ .predefined = predefined_states });
    if (try planLargeCompressedSequenceCodes(values.len, compressed_buffers)) |plan|
        try alternatives.add(.{ .compressed = plan });
    if (previous) |source| if (try planLargeRepeatSequenceCodes(compressed_buffers.codes, kind, source, repeat_states, repeat_viable_masks)) |plan|
        try alternatives.add(.{ .repeat = plan });
    if (comptime builtin.is_test)
        std.debug.assert(alternatives.value_bit_count == (large_fast_plan.valueBits(compressed_buffers.codes, bits) catch unreachable));
    return alternatives;
}

fn planLargeRepeatSequenceCodes(
    codes: []const u8,
    kind: SequenceTableKind,
    source: RepeatSequenceSource,
    states: []u16,
    viable_masks: []u64,
) Error!?LargeRepeatSequencePlan {
    if (codes.len == 0 or codes.len > max_large_native_sequence_count or states.len != codes.len) return null;
    if (source.mode == .rle) {
        const symbol = source.rle orelse return null;
        for (codes) |code| if (!sequenceSymbolMatchesCode(symbol, kind, code)) return null;
        return .{ .len = codes.len, .source = source, .states = states };
    }
    const symbols = switch (source.mode) {
        .predefined => sequenceTablePredefinedSymbols(kind),
        .compressed => source.symbols,
        .rle => unreachable,
        .repeat => return null,
    };
    const mask_words = try repeatSequenceMaskWordCount(source);
    const required_mask_len = std.math.mul(usize, codes.len, mask_words) catch return error.IntegerOverflow;
    if (viable_masks.len < required_mask_len) return null;
    const masks = viable_masks[0..required_mask_len];
    @memset(masks, 0);
    var pos = codes.len;
    while (pos > 0) {
        pos -= 1;
        const current_row = masks[pos * mask_words ..][0..mask_words];
        for (symbols, 0..) |symbol, state| {
            if (!sequenceSymbolMatchesCode(symbol, kind, codes[pos])) continue;
            if (pos == codes.len - 1) {
                setSequenceStateBit(current_row, state);
                continue;
            }
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            const next_row = masks[(pos + 1) * mask_words ..][0..mask_words];
            if (first_next < end_next and firstSequenceStateInRange(next_row, first_next, end_next) != null)
                setSequenceStateBit(current_row, state);
        }
    }
    states[0] = @intCast(firstSequenceStateInRange(masks[0..mask_words], 0, symbols.len) orelse return null);
    for (0..codes.len - 1) |i| {
        const symbol = symbols[states[i]];
        const end_next = @min(symbols.len, @as(usize, symbol.next_state) + (@as(usize, 1) << @intCast(symbol.state_bits)));
        const next_row = masks[(i + 1) * mask_words ..][0..mask_words];
        states[i + 1] = @intCast(firstSequenceStateInRange(next_row, symbol.next_state, end_next) orelse return null);
    }
    return .{ .len = codes.len, .source = source, .states = states };
}

fn repeatSequenceMaskWordCount(source: RepeatSequenceSource) Error!usize {
    return switch (source.mode) {
        .rle => 0,
        .predefined, .compressed => if (source.symbols.len != 0 and source.symbols.len <= max_sequence_fse_table_size)
            (source.symbols.len + 63) / 64
        else
            error.CorruptFrame,
        .repeat => error.CorruptFrame,
    };
}

fn largeOffsetSequenceTablePlanAlternatives(
    literal_lens: []const usize,
    offsets: []const usize,
    predefined_states: []u8,
    viable_masks: []u64,
    compressed_buffers: LargeCompressedSequenceBuffers,
    repeat_states: []u16,
    repeat_viable_masks: []u64,
    previous: ?RepeatSequenceSource,
    initial_offsets: [3]usize,
) linksection(wide_sequence_emit_text_section) Error!LargeSequenceTablePlanAlternatives {
    if (literal_lens.len != offsets.len) return error.CorruptFrame;
    var alternatives: LargeSequenceTablePlanAlternatives = .{};
    var repeated_offsets = initial_offsets;
    for (offsets, 0..) |offset, i| {
        const code = try chooseOffsetSequenceCode(literal_lens[i], offset, &repeated_offsets);
        compressed_buffers.codes[i] = code;
        alternatives.value_bit_count += of_bits[code];
    }
    if (rleSequenceCode(compressed_buffers.codes)) |code|
        try alternatives.add(.{ .rle = code });
    const offset_viable_bytes = std.mem.sliceAsBytes(viable_masks);
    const offset_viable_masks = std.mem.bytesAsSlice(u32, offset_viable_bytes[0 .. offsets.len * @sizeOf(u32)]);
    const predefined_ok = large_predefined.planOffset(
        compressed_buffers.codes,
        &predefined_offset_code_state_masks,
        predefined_states,
        offset_viable_masks,
    );
    if (predefined_ok) try alternatives.add(.{ .predefined = predefined_states });
    if (try planLargeCompressedSequenceCodes(offsets.len, compressed_buffers)) |plan|
        try alternatives.add(.{ .compressed = plan });
    if (previous) |source| if (try planLargeRepeatSequenceCodes(compressed_buffers.codes, .offset, source, repeat_states, repeat_viable_masks)) |plan|
        try alternatives.add(.{ .repeat = plan });
    if (comptime builtin.is_test)
        std.debug.assert(alternatives.value_bit_count == (large_fast_plan.valueBits(compressed_buffers.codes, &of_bits) catch unreachable));
    return alternatives;
}

fn bestLargeSequenceTablePlan(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    literal_alternatives: LargeSequenceTablePlanAlternatives,
    offset_alternatives: LargeSequenceTablePlanAlternatives,
    match_alternatives: LargeSequenceTablePlanAlternatives,
    initial_offsets: [3]usize,
) Error!?LargeSequenceCombinedPlanCandidate {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len <= max_native_sequence_count or literal_lens.len > max_large_native_sequence_count) return error.CorruptFrame;
    if (literal_alternatives.len == 0 or offset_alternatives.len == 0 or match_alternatives.len == 0) return null;

    var literal_costs: [4]?SequenceTableBitCost = @splat(null);
    var offset_costs: [4]?SequenceTableBitCost = @splat(null);
    var match_costs: [4]?SequenceTableBitCost = @splat(null);
    for (literal_alternatives.items[0..literal_alternatives.len], 0..) |*plan, i|
        literal_costs[i] = try largeSequenceTablePlanBitCost(plan, .literal, literal_lens, literal_lens, offsets, initial_offsets);
    for (offset_alternatives.items[0..offset_alternatives.len], 0..) |*plan, i|
        offset_costs[i] = try largeSequenceTablePlanBitCost(plan, .offset, offsets, literal_lens, offsets, initial_offsets);
    for (match_alternatives.items[0..match_alternatives.len], 0..) |*plan, i|
        match_costs[i] = try largeSequenceTablePlanBitCost(plan, .match, match_lens, literal_lens, offsets, initial_offsets);

    var best: ?LargeSequenceCombinedPlanCandidate = null;
    for (literal_alternatives.items[0..literal_alternatives.len], 0..) |*literal_plan, literal_i| {
        for (offset_alternatives.items[0..offset_alternatives.len], 0..) |*offset_plan, offset_i| {
            for (match_alternatives.items[0..match_alternatives.len], 0..) |*match_plan, match_i| {
                const literal_cost = literal_costs[literal_i] orelse continue;
                const offset_cost = offset_costs[offset_i] orelse continue;
                const match_cost = match_costs[match_i] orelse continue;
                var payload_len = literals_section_len;
                payload_len = std.math.add(usize, payload_len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, 1) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, literal_cost.payload_len + offset_cost.payload_len + match_cost.payload_len) catch return error.IntegerOverflow;
                const bit_count = std.math.add(usize, 1 + literal_cost.bit_count, offset_cost.bit_count + match_cost.bit_count) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
                if (best == null or payload_len < best.?.payload_len) best = .{
                    .plan = .{ .literal = literal_plan.*, .offset = offset_plan.*, .match = match_plan.* },
                    .payload_len = payload_len,
                };
            }
        }
    }
    return best;
}

noinline fn bestLargeSequenceTablePlanFast(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    literal_alternatives: LargeSequenceTablePlanAlternatives,
    offset_alternatives: LargeSequenceTablePlanAlternatives,
    match_alternatives: LargeSequenceTablePlanAlternatives,
    literal_codes: []const u8,
    offset_codes: []const u8,
    match_codes: []const u8,
) linksection(fast_encode_helper_text_section) Error!?LargeSequenceCombinedPlanCandidate {
    const len = literal_lens.len;
    if (len != offsets.len or len != match_lens.len or
        len != literal_codes.len or len != offset_codes.len or len != match_codes.len or
        len <= max_native_sequence_count or len > max_large_native_sequence_count) return error.CorruptFrame;
    if (literal_alternatives.len == 0 or offset_alternatives.len == 0 or match_alternatives.len == 0) return null;

    const literal_value_bits = literal_alternatives.value_bit_count;
    const offset_value_bits = offset_alternatives.value_bit_count;
    const match_value_bits = match_alternatives.value_bit_count;
    var literal_costs: [4]large_fast_plan.Cost = undefined;
    var offset_costs: [4]large_fast_plan.Cost = undefined;
    var match_costs: [4]large_fast_plan.Cost = undefined;
    for (literal_alternatives.items[0..literal_alternatives.len], 0..) |*plan, i|
        literal_costs[i] = try largeFastSequenceTableCost(plan, .literal, len, literal_value_bits);
    for (offset_alternatives.items[0..offset_alternatives.len], 0..) |*plan, i|
        offset_costs[i] = try largeFastSequenceTableCost(plan, .offset, len, offset_value_bits);
    for (match_alternatives.items[0..match_alternatives.len], 0..) |*plan, i|
        match_costs[i] = try largeFastSequenceTableCost(plan, .match, len, match_value_bits);

    const selected = (try large_fast_plan.select(
        try sequenceCountLen(len),
        literals_section_len,
        literal_costs[0..literal_alternatives.len],
        offset_costs[0..offset_alternatives.len],
        match_costs[0..match_alternatives.len],
    )) orelse return null;
    return .{
        .plan = .{
            .literal = literal_alternatives.items[selected.literal_index],
            .offset = offset_alternatives.items[selected.offset_index],
            .match = match_alternatives.items[selected.match_index],
        },
        .payload_len = selected.payload_len,
    };
}

noinline fn largeFastSequenceTableCost(
    plan: *const LargeSequenceTableEmitPlan,
    kind: SequenceTableKind,
    len: usize,
    value_bits: usize,
) linksection(fast_encode_helper_text_section) Error!large_fast_plan.Cost {
    try validateLargeSequenceTablePlanLen(plan, len);
    return switch (plan.*) {
        .rle => large_fast_plan.rleCost(value_bits),
        .predefined => |states| try large_fast_plan.predefinedCost(
            states,
            sequenceTablePredefinedSymbols(kind),
            predefinedInitialStateBits(kind),
            value_bits,
        ),
        .compressed => |compressed| try large_fast_plan.compressedCost(
            compressed.transition_bits,
            compressed.accuracy_log,
            compressed.table_payload_len,
            value_bits,
        ),
        .repeat => |repeat| try large_fast_plan.repeatCost(
            repeat.states,
            repeat.source.symbols,
            repeat.source.mode == .rle,
            repeatSequenceInitialStateBits(repeat.source),
            value_bits,
        ),
    };
}

fn largeSequenceTablePlanBitCost(
    plan: *const LargeSequenceTableEmitPlan,
    kind: SequenceTableKind,
    values: []const usize,
    literal_lens: []const usize,
    offsets: []const usize,
    initial_offsets: [3]usize,
) Error!?SequenceTableBitCost {
    try validateLargeSequenceTablePlanLen(plan, values.len);
    var bit_count: usize = switch (plan.*) {
        .rle => 0,
        .predefined => predefinedInitialStateBits(kind),
        .compressed => |compressed| compressed.accuracy_log,
        .repeat => |repeat| repeatSequenceInitialStateBits(repeat.source),
    };
    var repeated_offsets = initial_offsets;
    for (values, 0..) |value, i| {
        const symbol = try largeSequenceTableSymbol(plan, kind, i);
        if (!try sequenceSymbolAcceptsValue(symbol, kind, value, literal_lens[i], offsets[i], &repeated_offsets)) return null;
        bit_count = std.math.add(usize, bit_count, symbol.additional_bits) catch return error.IntegerOverflow;
        if (i + 1 < values.len) bit_count = std.math.add(usize, bit_count, switch (plan.*) {
            .rle => 0,
            .predefined => symbol.state_bits,
            .compressed => |compressed| compressed.transition_bits[i],
            .repeat => symbol.state_bits,
        }) catch return error.IntegerOverflow;
    }
    return .{ .payload_len = largeSequenceTablePayloadLen(plan), .bit_count = bit_count };
}

const SequenceCombinedEmitPlan = struct {
    literal: SequenceTableEmitPlan,
    offset: SequenceTableEmitPlan,
    match: SequenceTableEmitPlan,
};

const SequenceCombinedPlanCandidate = struct {
    plan: SequenceCombinedEmitPlan,
    payload_len: usize,
};

const SequenceTablePlanAlternatives = struct {
    items: [4]SequenceTableEmitPlan = undefined,
    len: usize = 0,

    fn add(self: *SequenceTablePlanAlternatives, plan: SequenceTableEmitPlan) Error!void {
        if (self.len >= self.items.len) return error.CorruptFrame;
        self.items[self.len] = plan;
        self.len += 1;
    }
};

const SequenceTableBitCost = struct {
    payload_len: usize,
    bit_count: usize,
};

fn bestTablePlanSequence(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!?SequenceCombinedPlanCandidate {
    return try bestTablePlanSequenceWithPreviousTables(block, literal_lens, offsets, match_lens, literal_ends, tail_start, null, initial_repeated_offsets);
}

fn bestTablePlanSequenceWithPreviousTables(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!?SequenceCombinedPlanCandidate {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len != literal_ends.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;

    const literals_section_len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);
    return try bestTablePlanSequenceWithLiteralsLenAndPreviousTables(literal_lens, offsets, match_lens, literals_section_len, previous_tables, initial_offsets);
}

fn bestTablePlanSequenceWithLiteralsLen(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
) Error!?SequenceCombinedPlanCandidate {
    return try bestTablePlanSequenceWithLiteralsLenAndPreviousTables(literal_lens, offsets, match_lens, literals_section_len, null, initial_repeated_offsets);
}

fn bestTablePlanSequenceWithLiteralsLenAndPreviousTables(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!?SequenceCombinedPlanCandidate {
    return try bestTablePlanSequenceWithLiteralsLenInternal(literal_lens, offsets, match_lens, literals_section_len, true, previous_tables, initial_offsets, null);
}

fn bestTablePlanSequenceWithLiteralsLenAndPredefinedPayload(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    predefined_payload_len: *?usize,
) Error!?SequenceCombinedPlanCandidate {
    return try bestTablePlanSequenceWithLiteralsLenInternal(
        literal_lens,
        offsets,
        match_lens,
        literals_section_len,
        true,
        null,
        initial_repeated_offsets,
        predefined_payload_len,
    );
}

fn bestTablePayloadLenWithLiteralsLen(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
) Error!?usize {
    const candidate = try bestTablePlanSequenceWithLiteralsLenInternal(literal_lens, offsets, match_lens, literals_section_len, false, null, initial_repeated_offsets, null) orelse return null;
    return candidate.payload_len;
}

fn bestTablePlanSequenceWithLiteralsLenInternal(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    comptime retain_plan: bool,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
    predefined_payload_len_out: ?*?usize,
) Error!?SequenceCombinedPlanCandidate {
    if (predefined_payload_len_out) |out| out.* = null;
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;

    const literal_alternatives = try sequenceTablePlanAlternativesWithPrevious(literal_lens, .literal, previous_tables);
    const offset_alternatives = try offsetSequenceTablePlanAlternativesWithPrevious(literal_lens, offsets, previous_tables, initial_offsets);
    const match_alternatives = try sequenceTablePlanAlternativesWithPrevious(match_lens, .match, previous_tables);
    if (literal_alternatives.len == 0 or offset_alternatives.len == 0 or match_alternatives.len == 0) return null;
    var literal_costs: [4]?SequenceTableBitCost = @splat(null);
    var offset_costs: [4]?SequenceTableBitCost = @splat(null);
    var match_costs: [4]?SequenceTableBitCost = @splat(null);
    var predefined_literal_cost: ?SequenceTableBitCost = null;
    var predefined_offset_cost: ?SequenceTableBitCost = null;
    var predefined_match_cost: ?SequenceTableBitCost = null;
    for (literal_alternatives.items[0..literal_alternatives.len], 0..) |*plan, i| {
        literal_costs[i] = switch (plan.*) {
            .compressed => |*compressed| compressedSequencePlanBitCostKnownValid(compressed),
            else => try sequenceTablePlanBitCostWithOffsets(plan.*, .literal, literal_lens, literal_lens, offsets, initial_offsets),
        };
        if (plan.* == .predefined) predefined_literal_cost = literal_costs[i];
    }
    for (offset_alternatives.items[0..offset_alternatives.len], 0..) |*plan, i| {
        offset_costs[i] = switch (plan.*) {
            .compressed => |*compressed| try compressedOffsetSequenceTablePlanBitCostKnownValid(compressed),
            else => try sequenceTablePlanBitCostWithOffsets(plan.*, .offset, offsets, literal_lens, offsets, initial_offsets),
        };
        if (plan.* == .predefined) predefined_offset_cost = offset_costs[i];
    }
    for (match_alternatives.items[0..match_alternatives.len], 0..) |*plan, i| {
        match_costs[i] = switch (plan.*) {
            .compressed => |*compressed| compressedSequencePlanBitCostKnownValid(compressed),
            else => try sequenceTablePlanBitCostWithOffsets(plan.*, .match, match_lens, literal_lens, offsets, initial_offsets),
        };
        if (plan.* == .predefined) predefined_match_cost = match_costs[i];
    }
    if (predefined_payload_len_out) |out| {
        if (predefined_literal_cost != null and predefined_offset_cost != null and predefined_match_cost != null) {
            var payload_len = literals_section_len;
            payload_len = std.math.add(usize, payload_len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
            payload_len = std.math.add(usize, payload_len, 1) catch return error.IntegerOverflow;
            const bit_count = std.math.add(usize, 1 + predefined_literal_cost.?.bit_count, predefined_offset_cost.?.bit_count + predefined_match_cost.?.bit_count) catch return error.IntegerOverflow;
            out.* = std.math.add(usize, payload_len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
        }
    }

    var best_plan: SequenceCombinedEmitPlan = undefined;
    var best_payload_len: usize = std.math.maxInt(usize);
    var have_best = false;
    // The bootstrap table families expose only a few alternatives (RLE,
    // predefined, and limited compressed FSE). Trying all combinations keeps the
    // planner exact for this subset and avoids baking in heuristics such as
    // "all-RLE" or "all-predefined" when one family is cheaper in a different
    // mode than the others.
    for (literal_alternatives.items[0..literal_alternatives.len], 0..) |literal_plan, literal_i| {
        for (offset_alternatives.items[0..offset_alternatives.len], 0..) |offset_plan, offset_i| {
            for (match_alternatives.items[0..match_alternatives.len], 0..) |match_plan, match_i| {
                const combined: SequenceCombinedEmitPlan = .{
                    .literal = literal_plan,
                    .offset = offset_plan,
                    .match = match_plan,
                };
                if (previous_tables == null and !sequenceCombinedPlanNeedsGenericEmitter(combined)) continue;
                const literal_cost = literal_costs[literal_i] orelse continue;
                const offset_cost = offset_costs[offset_i] orelse continue;
                const match_cost = match_costs[match_i] orelse continue;
                var payload_len = literals_section_len;
                payload_len = std.math.add(usize, payload_len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, 1) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, literal_cost.payload_len + offset_cost.payload_len + match_cost.payload_len) catch return error.IntegerOverflow;
                const bit_count = std.math.add(usize, 1 + literal_cost.bit_count, offset_cost.bit_count + match_cost.bit_count) catch return error.IntegerOverflow;
                payload_len = std.math.add(usize, payload_len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
                if (!have_best or payload_len < best_payload_len) {
                    if (retain_plan) best_plan = combined;
                    best_payload_len = payload_len;
                    have_best = true;
                }
            }
        }
    }
    if (!have_best) return null;

    // Keep the scoring result compact. The emitter materializes read fields
    // only for the single selected block; lookahead needs only the byte length
    // and table plan and would otherwise return/copy a 768-entry array for
    // every finalized branch.
    return .{ .plan = if (retain_plan) best_plan else undefined, .payload_len = best_payload_len };
}

fn sequenceTablePlanBitCost(
    plan: SequenceTableEmitPlan,
    kind: SequenceTableKind,
    values: []const usize,
    literal_lens: []const usize,
    offsets: []const usize,
) Error!?SequenceTableBitCost {
    return try sequenceTablePlanBitCostWithOffsets(plan, kind, values, literal_lens, offsets, initial_repeated_offsets);
}

fn sequenceTablePlanBitCostWithOffsets(
    plan: SequenceTableEmitPlan,
    kind: SequenceTableKind,
    values: []const usize,
    literal_lens: []const usize,
    offsets: []const usize,
    initial_offsets: [3]usize,
) Error!?SequenceTableBitCost {
    try validateSequenceTablePlanLen(plan, values.len);
    var bit_count: usize = 0;
    var repeated_offsets = initial_offsets;
    switch (plan) {
        .rle => |code| {
            const symbol = try sequenceRleSymbol(kind, code);
            for (values, 0..) |value, i| {
                if (!try sequenceSymbolAcceptsValue(symbol, kind, value, literal_lens[i], offsets[i], &repeated_offsets)) return null;
                bit_count += symbol.additional_bits;
            }
        },
        .predefined => |predefined| {
            bit_count = predefinedInitialStateBits(kind);
            const symbols = sequenceTablePredefinedSymbols(kind);
            for (values, 0..) |value, i| {
                const state = predefined.states[i];
                if (state >= symbols.len) return error.CorruptFrame;
                const symbol = symbols[state];
                if (!try sequenceSymbolAcceptsValue(symbol, kind, value, literal_lens[i], offsets[i], &repeated_offsets)) return null;
                bit_count += symbol.additional_bits;
                if (i + 1 < values.len) bit_count += symbol.state_bits;
            }
        },
        .compressed => |compressed| {
            bit_count = compressed.accuracy_log;
            const bases = sequenceTableBases(kind);
            const bits = sequenceTableBits(kind);
            for (values, 0..) |value, i| {
                const code = compressedSequenceCode(&compressed, i);
                if (code >= bases.len or code >= bits.len) return error.CorruptFrame;
                const symbol: SequenceSymbol = .{
                    .base = @intCast(bases[code]),
                    .additional_bits = bits[code],
                    .next_state = 0,
                    .state_bits = 0,
                };
                if (!try sequenceSymbolAcceptsValue(symbol, kind, value, literal_lens[i], offsets[i], &repeated_offsets)) return null;
                bit_count += symbol.additional_bits;
                if (i + 1 < values.len) bit_count += compressedSequenceTransitionBits(&compressed, i);
            }
        },
        .repeat => |repeat| {
            bit_count = repeatSequenceInitialStateBits(repeat.source);
            for (values, 0..) |value, i| {
                const symbol = try sequenceTableSymbol(plan, kind, i);
                if (!try sequenceSymbolAcceptsValue(symbol, kind, value, literal_lens[i], offsets[i], &repeated_offsets)) return null;
                bit_count += symbol.additional_bits;
                if (i + 1 < values.len) bit_count += symbol.state_bits;
            }
        },
    }
    return .{ .payload_len = sequenceTablePayloadLen(plan), .bit_count = bit_count };
}

fn compressedOffsetSequenceTablePlanBitCostKnownValid(plan: *const CompressedSequencePlan) Error!SequenceTableBitCost {
    if (plan.len == 0 or plan.len > max_native_sequence_count) return error.CorruptFrame;
    return compressedSequencePlanBitCostKnownValid(plan);
}

inline fn compressedSequencePlanBitCostKnownValid(plan: *const CompressedSequencePlan) SequenceTableBitCost {
    return .{
        .payload_len = plan.table_payload_len,
        .bit_count = @as(usize, plan.accuracy_log) + plan.value_bit_count + plan.transition_bit_count,
    };
}

test "zstd predefined minimum-cost LUT is a valid dominance lower bound" {
    var values: [max_native_sequence_count]usize = undefined;
    var random_state: u32 = 0x243f_6a88;
    var proof_hits: usize = 0;
    const cases = [_]struct { SequenceTableKind, usize }{
        .{ .literal, 131_071 },
        .{ .match, 131_074 },
    };
    for (cases) |case| {
        for ([_]usize{ 12, 31, 127, 256, max_native_sequence_count }) |len| {
            for (0..32) |_| {
                for (values[0..len]) |*value| {
                    random_state = random_state *% 1_664_525 +% 1_013_904_223;
                    value.* = random_state % case[1];
                    if (case[0] == .match) value.* += lz77.min_match_len;
                }
                const compressed = (try planCompressedSequenceValues(values[0..len], case[0])) orelse continue;
                if (!try compressedSequencePlanStrictlyDominatesPredefinedCodes(&compressed, case[0], values[0..len])) continue;
                proof_hits += 1;
                const predefined = (try planPredefinedSequenceValues(
                    values[0..len],
                    sequenceTablePredefinedSymbols(case[0]),
                    sequenceTablePredefinedMinAdditionalBits(case[0]),
                )) orelse continue;
                const compressed_cost = (try sequenceTablePlanBitCostWithOffsets(
                    .{ .compressed = compressed },
                    case[0],
                    values[0..len],
                    values[0..len],
                    values[0..len],
                    initial_repeated_offsets,
                )) orelse return error.CorruptFrame;
                try std.testing.expectEqual(compressed_cost, compressedSequencePlanBitCostKnownValid(&compressed));
                const predefined_cost = (try sequenceTablePlanBitCostWithOffsets(
                    .{ .predefined = predefined },
                    case[0],
                    values[0..len],
                    values[0..len],
                    values[0..len],
                    initial_repeated_offsets,
                )) orelse return error.CorruptFrame;
                const compressed_bytes = compressed_cost.payload_len + (compressed_cost.bit_count + 1 + 7) / 8;
                const predefined_bytes = predefined_cost.payload_len + (predefined_cost.bit_count + 1 + 7) / 8;
                try std.testing.expect(compressed_bytes < predefined_bytes);
            }
        }
    }

    var literal_lens: [max_native_sequence_count]usize = undefined;
    for ([_]usize{ 12, 31, 127, 256, max_native_sequence_count }) |len| {
        for (0..32) |_| {
            for (literal_lens[0..len], values[0..len]) |*literal_len, *offset| {
                random_state = random_state *% 1_664_525 +% 1_013_904_223;
                literal_len.* = (random_state >> 28) & 7;
                random_state = random_state *% 1_664_525 +% 1_013_904_223;
                offset.* = 1 + (random_state % 32_768);
            }
            const compressed = (try planCompressedOffsetSequenceValues(literal_lens[0..len], values[0..len])) orelse continue;
            if (!try compressedSequencePlanStrictlyDominatesPredefinedCodes(&compressed, .offset, values[0..len])) continue;
            proof_hits += 1;
            const predefined = (try planPredefinedSequenceValues(values[0..len], &sequence_predefined.offset_symbols, 2)) orelse continue;
            const compressed_cost = (try sequenceTablePlanBitCostWithOffsets(
                .{ .compressed = compressed },
                .offset,
                values[0..len],
                literal_lens[0..len],
                values[0..len],
                initial_repeated_offsets,
            )) orelse return error.CorruptFrame;
            const predefined_cost = (try sequenceTablePlanBitCostWithOffsets(
                .{ .predefined = predefined },
                .offset,
                values[0..len],
                literal_lens[0..len],
                values[0..len],
                initial_repeated_offsets,
            )) orelse return error.CorruptFrame;
            const compressed_bytes = compressed_cost.payload_len + (compressed_cost.bit_count + 1 + 7) / 8;
            const predefined_bytes = predefined_cost.payload_len + (predefined_cost.bit_count + 1 + 7) / 8;
            try std.testing.expect(compressed_bytes < predefined_bytes);
        }
    }
    try std.testing.expect(proof_hits != 0);
}

fn sequenceTablePlanBitCostReference(
    plan: SequenceTableEmitPlan,
    kind: SequenceTableKind,
    values: []const usize,
    literal_lens: []const usize,
    offsets: []const usize,
) Error!?SequenceTableBitCost {
    try validateSequenceTablePlanLen(plan, values.len);
    var bit_count: usize = switch (plan) {
        .rle => 0,
        .predefined => predefinedInitialStateBits(kind),
        .compressed => |compressed| compressed.accuracy_log,
        .repeat => |repeat| repeatSequenceInitialStateBits(repeat.source),
    };
    var repeated_offsets = initial_repeated_offsets;
    for (values, 0..) |value, i| {
        const symbol = try sequenceTableSymbol(plan, kind, i);
        if (kind == .offset) {
            _ = sequenceOffsetExtraForEncodedOffset(symbol, literal_lens[i], offsets[i], &repeated_offsets) catch |err| switch (err) {
                error.InvalidMatch, error.UnsupportedZstdFeature, error.CorruptFrame => return null,
                else => return err,
            };
        } else if (value < symbol.base) return null;
        bit_count = std.math.add(usize, bit_count, symbol.additional_bits) catch return error.IntegerOverflow;
        if (i + 1 < values.len) {
            bit_count = std.math.add(usize, bit_count, switch (plan) {
                .rle => 0,
                .predefined => symbol.state_bits,
                .compressed => |compressed| compressed.transition_bits[i],
                .repeat => symbol.state_bits,
            }) catch return error.IntegerOverflow;
        }
    }
    return .{ .payload_len = sequenceTablePayloadLen(plan), .bit_count = bit_count };
}

fn sequenceSymbolAcceptsValue(
    symbol: SequenceSymbol,
    kind: SequenceTableKind,
    value: usize,
    literal_len: usize,
    offset: usize,
    repeated_offsets: *[3]usize,
) Error!bool {
    if (kind == .offset) {
        _ = sequenceOffsetExtraForEncodedOffset(symbol, literal_len, offset, repeated_offsets) catch |err| switch (err) {
            error.InvalidMatch, error.UnsupportedZstdFeature, error.CorruptFrame => return false,
            else => return err,
        };
        return true;
    }
    return value >= symbol.base;
}

fn sequenceCombinedPlanNeedsGenericEmitter(plan: SequenceCombinedEmitPlan) bool {
    const literal_mode = sequenceTableMode(plan.literal);
    const offset_mode = sequenceTableMode(plan.offset);
    const match_mode = sequenceTableMode(plan.match);
    // All-RLE and all-predefined plans are already handled by dedicated emitters
    // that are cheaper to score directly.  All-compressed plans have no such
    // separate path, so keep them in the generic table-plan search instead of
    // accidentally discarding the only route to LL/OF/ML=FSE blocks.
    if (literal_mode == .rle and offset_mode == .rle and match_mode == .rle) return false;
    if (literal_mode == .predefined and offset_mode == .predefined and match_mode == .predefined) return false;
    return true;
}

fn sequenceTablePlanAlternatives(values: []const usize, kind: SequenceTableKind) Error!SequenceTablePlanAlternatives {
    return try sequenceTablePlanAlternativesWithPrevious(values, kind, null);
}

fn sequenceTablePlanAlternativesWithPrevious(values: []const usize, kind: SequenceTableKind, previous_tables: ?*const SequenceTables) Error!SequenceTablePlanAlternatives {
    if (previous_tables == null and kind != .offset) {
        var alternatives: SequenceTablePlanAlternatives = undefined;
        alternatives.len = 0;
        if (values.len == 0 or values.len > max_native_sequence_count) return alternatives;

        var codes: [max_native_sequence_count]u8 = undefined;
        if (kind == .match) {
            for (values, 0..) |value, i|
                codes[i] = matchLengthCode(value) catch return alternatives;
        } else {
            for (values, 0..) |value, i|
                codes[i] = sequenceCodeForValue(value, &ll_base, &ll_bits) catch return alternatives;
        }
        const active_codes = codes[0..values.len];
        if (rleSequenceCode(active_codes)) |code| try alternatives.add(.{ .rle = code });
        const compressed = try planCompressedSequenceCodes(active_codes, kind);
        const skip_predefined = if (compressed) |*plan|
            try compressedSequencePlanStrictlyDominatesPredefinedCodeSlice(plan, kind, active_codes)
        else
            false;
        if (!skip_predefined)
            if (try planPredefinedSequenceCodes(active_codes, sequenceTablePredefinedSymbols(kind), kind)) |plan|
                try alternatives.add(.{ .predefined = plan });
        if (compressed) |plan| try alternatives.add(.{ .compressed = plan });
        return alternatives;
    }
    return try sequenceTablePlanAlternativesWithPreviousUnshared(values, kind, previous_tables);
}

fn sequenceTablePlanAlternativesWithPreviousUnshared(
    values: []const usize,
    kind: SequenceTableKind,
    previous_tables: ?*const SequenceTables,
) Error!SequenceTablePlanAlternatives {
    // `add` initializes every slot before `len` exposes it. Leave the inactive
    // multi-kilobyte union tail undefined instead of clearing it on every plan.
    var alternatives: SequenceTablePlanAlternatives = undefined;
    alternatives.len = 0;
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    if (try rleSequenceCodeForValues(values, bases, bits)) |code| {
        try alternatives.add(.{ .rle = code });
    }
    const compressed = try planCompressedSequenceValues(values, kind);
    const skip_predefined = if (compressed) |*plan|
        try compressedSequencePlanStrictlyDominatesPredefinedCodes(plan, kind, values)
    else
        false;
    if (!skip_predefined)
        if (try planPredefinedSequenceValues(values, sequenceTablePredefinedSymbols(kind), sequenceTablePredefinedMinAdditionalBits(kind))) |plan| {
            try alternatives.add(.{ .predefined = plan });
        };
    if (compressed) |plan| try alternatives.add(.{ .compressed = plan });
    if (previous_tables) |tables| {
        if (try planRepeatSequenceValues(values, kind, previousSequenceTable(tables, kind))) |plan|
            try alternatives.add(.{ .repeat = plan });
    }
    return alternatives;
}

fn offsetSequenceTablePlanAlternatives(literal_lens: []const usize, offsets: []const usize) Error!SequenceTablePlanAlternatives {
    return try offsetSequenceTablePlanAlternativesWithPrevious(literal_lens, offsets, null, initial_repeated_offsets);
}

fn offsetSequenceTablePlanAlternativesWithPrevious(
    literal_lens: []const usize,
    offsets: []const usize,
    previous_tables: ?*const SequenceTables,
    initial_offsets: [3]usize,
) Error!SequenceTablePlanAlternatives {
    if (literal_lens.len != offsets.len) return error.CorruptFrame;
    // Consumers inspect only `items[0..len]`; each visible slot is written by
    // `add`, so clearing the remaining large union entries is unnecessary.
    var alternatives: SequenceTablePlanAlternatives = undefined;
    alternatives.len = 0;
    if (previous_tables == null and std.meta.eql(initial_offsets, initial_repeated_offsets))
        return try offsetSequenceTablePlanAlternativesLegacy(literal_lens, offsets);

    var codes: [max_native_sequence_count]u8 = undefined;
    var repeated_offsets = initial_offsets;
    for (offsets, 0..) |offset, i|
        codes[i] = try chooseOffsetSequenceCode(literal_lens[i], offset, &repeated_offsets);
    if (rleSequenceCode(codes[0..offsets.len])) |code| {
        try alternatives.add(.{ .rle = code });
    }
    if (try planPredefinedSequenceCodes(codes[0..offsets.len], &sequence_predefined.offset_symbols, .offset)) |plan| {
        try alternatives.add(.{ .predefined = plan });
    }
    if (try planCompressedSequenceCodes(codes[0..offsets.len], .offset)) |plan| {
        try alternatives.add(.{ .compressed = plan });
    }
    if (previous_tables) |tables| {
        if (try planRepeatSequenceCodes(codes[0..offsets.len], .offset, previousSequenceTable(tables, .offset))) |plan|
            try alternatives.add(.{ .repeat = plan });
    }
    return alternatives;
}

fn offsetSequenceTablePlanAlternativesLegacy(literal_lens: []const usize, offsets: []const usize) Error!SequenceTablePlanAlternatives {
    // Match the general builder's initialized-prefix contract.
    var alternatives: SequenceTablePlanAlternatives = undefined;
    alternatives.len = 0;
    if (try rleSequenceCodeForValues(offsets, &of_base, &of_bits)) |code|
        try alternatives.add(.{ .rle = code });
    const compressed = try planCompressedOffsetSequenceValues(literal_lens, offsets);
    const skip_predefined = if (compressed) |*plan|
        try compressedSequencePlanStrictlyDominatesPredefinedCodes(plan, .offset, offsets)
    else
        false;
    if (!skip_predefined)
        if (try planPredefinedSequenceValues(offsets, &sequence_predefined.offset_symbols, 2)) |plan|
            try alternatives.add(.{ .predefined = plan });
    if (compressed) |plan| try alternatives.add(.{ .compressed = plan });
    return alternatives;
}

fn sequenceTablePlanAlternativesInitializedReference(
    values: []const usize,
    kind: SequenceTableKind,
) Error!SequenceTablePlanAlternatives {
    var alternatives: SequenceTablePlanAlternatives = .{};
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    if (try rleSequenceCodeForValues(values, bases, bits)) |code|
        try alternatives.add(.{ .rle = code });
    if (try planPredefinedSequenceValues(values, sequenceTablePredefinedSymbols(kind), sequenceTablePredefinedMinAdditionalBits(kind))) |plan|
        try alternatives.add(.{ .predefined = plan });
    if (try planCompressedSequenceValues(values, kind)) |plan|
        try alternatives.add(.{ .compressed = plan });
    return alternatives;
}

fn offsetSequenceTablePlanAlternativesInitializedReference(
    literal_lens: []const usize,
    offsets: []const usize,
) Error!SequenceTablePlanAlternatives {
    var alternatives: SequenceTablePlanAlternatives = .{};
    if (try rleSequenceCodeForValues(offsets, &of_base, &of_bits)) |code|
        try alternatives.add(.{ .rle = code });
    if (try planPredefinedSequenceValues(offsets, &sequence_predefined.offset_symbols, 2)) |plan|
        try alternatives.add(.{ .predefined = plan });
    if (try planCompressedOffsetSequenceValues(literal_lens, offsets)) |plan|
        try alternatives.add(.{ .compressed = plan });
    return alternatives;
}

fn previousSequenceTable(tables: *const SequenceTables, kind: SequenceTableKind) RepeatSequenceSource {
    return switch (kind) {
        .literal => .{
            .mode = tables.ll_mode,
            .rle = tables.literal_rle,
            .symbols = if (tables.ll_mode == .predefined) sequenceTablePredefinedSymbols(.literal) else tables.literal_fse.entries[0..tables.literal_fse.len],
            .accuracy_log = if (tables.ll_mode == .predefined) predefinedInitialStateBits(.literal) else tables.literal_fse.accuracy_log,
        },
        .offset => .{
            .mode = tables.of_mode,
            .rle = tables.offset_rle,
            .symbols = if (tables.of_mode == .predefined) sequenceTablePredefinedSymbols(.offset) else tables.offset_fse.entries[0..tables.offset_fse.len],
            .accuracy_log = if (tables.of_mode == .predefined) predefinedInitialStateBits(.offset) else tables.offset_fse.accuracy_log,
        },
        .match => .{
            .mode = tables.ml_mode,
            .rle = tables.match_rle,
            .symbols = if (tables.ml_mode == .predefined) sequenceTablePredefinedSymbols(.match) else tables.match_fse.entries[0..tables.match_fse.len],
            .accuracy_log = if (tables.ml_mode == .predefined) predefinedInitialStateBits(.match) else tables.match_fse.accuracy_log,
        },
    };
}

fn repeatSequenceInitialStateBits(source: RepeatSequenceSource) u8 {
    return switch (source.mode) {
        .predefined, .compressed => source.accuracy_log,
        .rle => 0,
        .repeat => unreachable,
    };
}

fn planRepeatSequenceValues(
    values: []const usize,
    kind: SequenceTableKind,
    source: RepeatSequenceSource,
) Error!?RepeatSequencePlan {
    if (values.len == 0 or values.len > max_native_sequence_count) return null;
    var codes: [max_native_sequence_count]u8 = undefined;
    for (values, 0..) |value, i|
        codes[i] = sequenceCodeForValue(value, sequenceTableBases(kind), sequenceTableBits(kind)) catch return null;
    return try planRepeatSequenceCodes(codes[0..values.len], kind, source);
}

fn planRepeatSequenceCodes(codes: []const u8, kind: SequenceTableKind, source: RepeatSequenceSource) Error!?RepeatSequencePlan {
    if (codes.len == 0 or codes.len > max_native_sequence_count) return null;
    var plan: RepeatSequencePlan = .{ .len = codes.len, .source = source };
    if (source.mode == .rle) {
        const symbol = source.rle orelse return null;
        for (codes) |code| if (!sequenceSymbolMatchesCode(symbol, kind, code)) return null;
        return plan;
    }
    const symbols = switch (source.mode) {
        .predefined => sequenceTablePredefinedSymbols(kind),
        .compressed => source.symbols,
        .rle => unreachable,
        .repeat => return null,
    };
    if (symbols.len == 0 or symbols.len > max_sequence_fse_table_size) return null;
    const mask_words = max_sequence_fse_table_size / 64;
    var viable: [max_native_sequence_count][mask_words]u64 = @splat(@splat(0));
    var pos = codes.len;
    while (pos > 0) {
        pos -= 1;
        for (symbols, 0..) |symbol, state| {
            if (!sequenceSymbolMatchesCode(symbol, kind, codes[pos])) continue;
            if (pos == codes.len - 1) {
                setSequenceStateBit(&viable[pos], state);
                continue;
            }
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            if (first_next < end_next and firstSequenceStateInRange(&viable[pos + 1], first_next, end_next) != null)
                setSequenceStateBit(&viable[pos], state);
        }
    }
    plan.states[0] = @intCast(firstSequenceStateInRange(&viable[0], 0, symbols.len) orelse return null);
    for (0..codes.len - 1) |i| {
        const symbol = symbols[plan.states[i]];
        const end_next = @min(symbols.len, @as(usize, symbol.next_state) + (@as(usize, 1) << @intCast(symbol.state_bits)));
        plan.states[i + 1] = @intCast(firstSequenceStateInRange(&viable[i + 1], symbol.next_state, end_next) orelse return null);
    }
    return plan;
}

fn rleSequenceCode(codes: []const u8) ?u8 {
    if (codes.len == 0) return null;
    const code = codes[0];
    for (codes[1..]) |other| if (other != code) return null;
    return code;
}

fn planPredefinedSequenceCodes(
    codes: []const u8,
    symbols: []const SequenceSymbol,
    kind: SequenceTableKind,
) Error!?PredefinedSequencePlan {
    if (codes.len == 0 or codes.len > max_native_sequence_count or symbols.len > max_predefined_sequence_states) return null;
    var next_choice: [max_native_sequence_count][max_predefined_sequence_states]u8 = undefined;
    var viable_next: u64 = 0;
    var pos = codes.len;
    while (pos > 0) {
        pos -= 1;
        var viable_current: u64 = 0;
        var encodable_states: u64 = switch (kind) {
            .literal => if (codes[pos] < predefined_literal_state_masks.len) predefined_literal_state_masks[codes[pos]] else 0,
            .match => if (codes[pos] < predefined_match_state_masks.len) predefined_match_state_masks[codes[pos]] else 0,
            .offset => blk: {
                var mask: u64 = 0;
                for (symbols, 0..) |symbol, state| {
                    if (sequenceSymbolMatchesCode(symbol, kind, codes[pos])) {
                        mask |= @as(u64, 1) << @intCast(state);
                    }
                }
                break :blk mask;
            },
        };
        while (encodable_states != 0) {
            const state: usize = @ctz(encodable_states);
            encodable_states &= encodable_states - 1;
            const symbol = symbols[state];
            if (pos == codes.len - 1) {
                viable_current |= @as(u64, 1) << @intCast(state);
                continue;
            }
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            if (first_next >= end_next) continue;
            const width = end_next - first_next;
            const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
            const possible = viable_next & (low_mask << @intCast(first_next));
            if (possible == 0) continue;
            viable_current |= @as(u64, 1) << @intCast(state);
            next_choice[pos][state] = @intCast(@ctz(possible));
        }
        viable_next = viable_current;
    }
    if (viable_next == 0) return null;
    var plan: PredefinedSequencePlan = .{ .len = codes.len };
    plan.states[0] = @intCast(@ctz(viable_next));
    for (0..codes.len - 1) |i| plan.states[i + 1] = next_choice[i][plan.states[i]];
    return plan;
}

fn planPredefinedSequenceCodesReference(
    codes: []const u8,
    symbols: []const SequenceSymbol,
    kind: SequenceTableKind,
) Error!?PredefinedSequencePlan {
    if (codes.len == 0 or codes.len > max_native_sequence_count or symbols.len > max_predefined_sequence_states) return null;
    var next_choice: [max_native_sequence_count][max_predefined_sequence_states]u8 = undefined;
    var viable_next: u64 = 0;
    var pos = codes.len;
    while (pos > 0) {
        pos -= 1;
        var viable_current: u64 = 0;
        for (symbols, 0..) |symbol, state| {
            if (!sequenceSymbolMatchesCode(symbol, kind, codes[pos])) continue;
            if (pos == codes.len - 1) {
                viable_current |= @as(u64, 1) << @intCast(state);
                continue;
            }
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            if (first_next >= end_next) continue;
            const width = end_next - first_next;
            const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
            const possible = viable_next & (low_mask << @intCast(first_next));
            if (possible == 0) continue;
            viable_current |= @as(u64, 1) << @intCast(state);
            next_choice[pos][state] = @intCast(@ctz(possible));
        }
        viable_next = viable_current;
    }
    if (viable_next == 0) return null;
    var plan: PredefinedSequencePlan = .{ .len = codes.len };
    plan.states[0] = @intCast(@ctz(viable_next));
    for (0..codes.len - 1) |i| plan.states[i + 1] = next_choice[i][plan.states[i]];
    return plan;
}

fn sequenceSymbolMatchesCode(symbol: SequenceSymbol, kind: SequenceTableKind, code: u8) bool {
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    return code < bases.len and code < bits.len and symbol.base == bases[code] and symbol.additional_bits == bits[code];
}

fn setSequenceStateBit(mask: []u64, state: usize) void {
    std.debug.assert(state < mask.len * 64);
    mask[state / 64] |= @as(u64, 1) << @intCast(state % 64);
}

fn firstSequenceStateInRange(mask: []const u64, start: usize, end: usize) ?usize {
    if (start >= end or end > mask.len * 64) return null;
    var state = start;
    while (state < end) {
        const word = mask[state / 64] >> @intCast(state % 64);
        if (word != 0) {
            const found = state + @ctz(word);
            if (found < end) return found;
        }
        state = ((state / 64) + 1) * 64;
    }
    return null;
}

fn rleSequenceCodeForValues(values: []const usize, bases: []const usize, bits: []const u8) Error!?u8 {
    if (values.len == 0) return null;
    const code = sequenceCodeForValue(values[0], bases, bits) catch |err| switch (err) {
        error.CorruptFrame => return null,
        else => return err,
    };
    for (values[1..]) |value| {
        const next_code = sequenceCodeForValue(value, bases, bits) catch |err| switch (err) {
            error.CorruptFrame => return null,
            else => return err,
        };
        if (next_code != code) return null;
    }
    return code;
}

fn planCompressedSequenceValues(values: []const usize, kind: SequenceTableKind) Error!?CompressedSequencePlan {
    if (values.len < min_compressed_sequence_table_count or values.len > max_native_sequence_count) return null;
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);

    var codes: [max_native_sequence_count]u8 = undefined;
    for (values, 0..) |value, i| {
        const code = sequenceCodeForValue(value, bases, bits) catch |err| switch (err) {
            error.CorruptFrame => return null,
            else => return err,
        };
        if (code > max_fse_compression_symbol) return null;
        if (kind == .offset and of_bits[code] <= 1) return null;
        codes[i] = code;
    }
    return try planCompressedSequenceCodes(codes[0..values.len], kind);
}

fn planCompressedOffsetSequenceValues(literal_lens: []const usize, offsets: []const usize) Error!?CompressedSequencePlan {
    return try planCompressedOffsetSequenceValuesWithOffsets(literal_lens, offsets, initial_repeated_offsets);
}

fn planCompressedOffsetSequenceValuesWithOffsets(
    literal_lens: []const usize,
    offsets: []const usize,
    initial_offsets: [3]usize,
) Error!?CompressedSequencePlan {
    if (literal_lens.len != offsets.len) return error.CorruptFrame;
    if (offsets.len < min_compressed_sequence_table_count or offsets.len > max_native_sequence_count) return null;

    var codes: [max_native_sequence_count]u8 = undefined;
    var repeated_offsets = initial_offsets;
    for (offsets, 0..) |offset, i| {
        codes[i] = try chooseOffsetSequenceCode(literal_lens[i], offset, &repeated_offsets);
    }
    return try planCompressedSequenceCodes(codes[0..offsets.len], .offset);
}

fn chooseOffsetSequenceCode(literal_len: usize, offset: usize, repeated_offsets: *[3]usize) Error!u8 {
    // Prefer the dedicated repeat-offset selectors when they describe the
    // requested match distance. Besides using fewer extra bits, this preserves
    // the same repeated-offset history that a normal zstd encoder would expose
    // to later sequences.
    for ([_]u8{ 0, 1 }) |code| {
        const symbol = try sequenceRleSymbol(.offset, code);
        var trial_offsets = repeated_offsets.*;
        _ = sequenceOffsetExtraForEncodedOffset(symbol, literal_len, offset, &trial_offsets) catch |err| switch (err) {
            error.CorruptFrame => continue,
            else => return err,
        };
        repeated_offsets.* = trial_offsets;
        return code;
    }

    const code = try absoluteOffsetSequenceCode(offset);
    var trial_offsets = repeated_offsets.*;
    _ = try sequenceOffsetExtraForEncodedOffset(try sequenceRleSymbol(.offset, code), literal_len, offset, &trial_offsets);
    repeated_offsets.* = trial_offsets;
    return code;
}

fn absoluteOffsetSequenceCode(offset: usize) Error!u8 {
    var best: ?usize = null;
    for (of_base, 0..) |base, code| {
        if (of_bits[code] <= 1) continue;
        if (offset < base) continue;
        const span = @as(usize, 1) << @intCast(of_bits[code]);
        if (offset - base >= span) continue;
        if (best == null or base >= of_base[best.?]) best = code;
    }
    return @intCast(best orelse return error.CorruptFrame);
}

noinline fn planCompressedSequenceCodes(codes: []const u8, kind: SequenceTableKind) linksection(fse_encode_helper_text_section) Error!?CompressedSequencePlan {
    if (codes.len < min_compressed_sequence_table_count or codes.len > max_native_sequence_count) return null;

    // Match FSE_optimalTableLog's source-size cap with the current compact u8
    // state representation: 256+ symbols can amortize one extra state bit,
    // while smaller plans retain the faster 32-state table.
    const accuracy_log: u8 = if (codes.len >= 256) 7 else 5;
    var plan: CompressedSequencePlan = .{ .len = codes.len, .accuracy_log = accuracy_log };
    var counts: [max_fse_compression_symbol + 1]u32 = .{0} ** (max_fse_compression_symbol + 1);
    var max_code: u8 = 0;
    for (codes, 0..) |code, i| {
        if (code > max_fse_compression_symbol) return null;
        setCompressedSequenceCode(&plan, i, code);
        counts[code] += 1;
        max_code = @max(max_code, code);
    }

    var max_count: u32 = 0;
    var non_zero_count: usize = 0;
    var value_bit_count: u16 = 0;
    const value_bits = sequenceTableBits(kind);
    if (max_code >= value_bits.len) return null;
    for (counts[0 .. @as(usize, max_code) + 1], 0..) |count, code| {
        if (count != 0) non_zero_count += 1;
        max_count = @max(max_count, count);
        value_bit_count += @as(u16, @intCast(count)) * value_bits[code];
    }
    plan.value_bit_count = value_bit_count;
    if (non_zero_count < 2 or non_zero_count > (@as(usize, 1) << @intCast(plan.accuracy_log))) return null;
    // RLE and predefined modes are already cheaper for these degenerate shapes;
    // keep the compressed table candidate for cases with enough repeated code
    // distribution to amortize the normalized-count header.
    if (max_count == codes.len or max_count == 1) return null;

    var normalized: [max_fse_compression_symbol + 1]i16 = .{0} ** (max_fse_compression_symbol + 1);
    normalizeFseCounts(
        counts[0 .. @as(usize, max_code) + 1],
        codes.len,
        plan.accuracy_log,
        normalized[0 .. @as(usize, max_code) + 1],
    ) orelse return null;

    emitFseNormalizedCountFixed(
        &plan.table_payload,
        &plan.table_payload_len,
        normalized[0 .. @as(usize, max_code) + 1],
        max_code,
        plan.accuracy_log,
    ) catch |err| switch (err) {
        error.OutputTooSmall => return null,
        else => return err,
    };
    // A compressed sequence table pays an upfront normalized-count header before
    // it can save state-transition bits. For small bootstrap blocks, reject
    // candidates whose table header alone is no smaller than one byte per
    // sequence; RLE/predefined modes remain available and avoid the FSE setup
    // cost in those cases.
    if (plan.table_payload_len >= codes.len) return null;

    var compression_table: FseCompressionTable = undefined;
    try buildFseCompressionTable(
        &compression_table,
        normalized[0 .. @as(usize, max_code) + 1],
        max_code,
        plan.accuracy_log,
    );
    if (comptime builtin.is_test) {
        var entries: [max_sequence_fse_table_size]FseTableEntry = undefined;
        const table_len = try buildFseDecodeTableFromNormalized(
            normalized[0 .. @as(usize, max_code) + 1],
            plan.accuracy_log,
            &entries,
        );
        try fillCompressedSequenceTransitionsFromCompressionTable(&plan, entries[0..table_len], &compression_table);
    } else {
        try fillCompressedSequenceTransitionsDirect(&plan, &compression_table);
    }
    return plan;
}

fn planLargeCompressedSequenceValues(
    values: []const usize,
    kind: SequenceTableKind,
    buffers: LargeCompressedSequenceBuffers,
) Error!?LargeCompressedSequencePlan {
    if (values.len < min_compressed_sequence_table_count or values.len > max_large_native_sequence_count) return null;
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    for (values, 0..) |value, i| {
        const code = sequenceCodeForValue(value, bases, bits) catch |err| switch (err) {
            error.CorruptFrame => return null,
            else => return err,
        };
        if (code > max_fse_compression_symbol or (kind == .offset and of_bits[code] <= 1)) return null;
        buffers.codes[i] = code;
    }
    return try planLargeCompressedSequenceCodes(values.len, buffers);
}

fn planLargeCompressedOffsetSequenceValues(
    literal_lens: []const usize,
    offsets: []const usize,
    buffers: LargeCompressedSequenceBuffers,
) Error!?LargeCompressedSequencePlan {
    if (literal_lens.len != offsets.len) return error.CorruptFrame;
    if (offsets.len < min_compressed_sequence_table_count or offsets.len > max_large_native_sequence_count) return null;
    var repeated_offsets = initial_repeated_offsets;
    for (offsets, 0..) |offset, i|
        buffers.codes[i] = try chooseOffsetSequenceCode(literal_lens[i], offset, &repeated_offsets);
    return try planLargeCompressedSequenceCodes(offsets.len, buffers);
}

fn planLargeCompressedSequenceCodes(
    len: usize,
    buffers: LargeCompressedSequenceBuffers,
) Error!?LargeCompressedSequencePlan {
    if (len < min_compressed_sequence_table_count or len > max_large_native_sequence_count or
        buffers.codes.len != len or buffers.next_states.len != len or buffers.state_bits.len != len or
        buffers.transition_values.len != len or buffers.transition_bits.len != len) return null;

    const accuracy_log: u8 = 7;
    var counts: [max_fse_compression_symbol + 1]u32 = .{0} ** (max_fse_compression_symbol + 1);
    var max_code: u8 = 0;
    for (buffers.codes) |code| {
        if (code > max_fse_compression_symbol) return null;
        counts[code] += 1;
        max_code = @max(max_code, code);
    }
    var max_count: u32 = 0;
    var non_zero_count: usize = 0;
    for (counts[0 .. @as(usize, max_code) + 1]) |count| {
        if (count != 0) non_zero_count += 1;
        max_count = @max(max_count, count);
    }
    if (non_zero_count < 2 or non_zero_count > (@as(usize, 1) << @intCast(accuracy_log)) or
        max_count == len or max_count == 1) return null;

    var normalized: [max_fse_compression_symbol + 1]i16 = .{0} ** (max_fse_compression_symbol + 1);
    normalizeFseCounts(
        counts[0 .. @as(usize, max_code) + 1],
        len,
        accuracy_log,
        normalized[0 .. @as(usize, max_code) + 1],
    ) orelse return null;

    var table_payload: [64]u8 = undefined;
    var table_payload_len: usize = 0;
    emitFseNormalizedCountFixed(
        &table_payload,
        &table_payload_len,
        normalized[0 .. @as(usize, max_code) + 1],
        max_code,
        accuracy_log,
    ) catch |err| switch (err) {
        error.OutputTooSmall => return null,
        else => return err,
    };
    if (table_payload_len >= len) return null;

    const initial_state = if (buffers.direct_transitions) blk: {
        var compression_table: FseCompressionTable = undefined;
        try buildFseCompressionTable(
            &compression_table,
            normalized[0 .. @as(usize, max_code) + 1],
            max_code,
            accuracy_log,
        );
        break :blk try fillLargeCompressedSequenceTransitionsDirect(buffers, &compression_table);
    } else blk: {
        var entries: [max_sequence_fse_table_size]FseTableEntry = undefined;
        const table_len = try buildFseDecodeTableFromNormalized(
            normalized[0 .. @as(usize, max_code) + 1],
            accuracy_log,
            &entries,
        );
        break :blk try fillLargeCompressedSequenceTransitions(buffers, entries[0..table_len]);
    };
    return .{
        .accuracy_log = accuracy_log,
        .codes = buffers.codes,
        .initial_state = initial_state,
        .next_states = buffers.next_states,
        .state_bits = buffers.state_bits,
        .transition_values = buffers.transition_values,
        .transition_bits = buffers.transition_bits,
        .table_payload = table_payload,
        .table_payload_len = table_payload_len,
    };
}

fn fillLargeCompressedSequenceTransitions(
    buffers: LargeCompressedSequenceBuffers,
    entries: []const FseTableEntry,
) Error!u8 {
    if (buffers.codes.len == 0) return error.CorruptFrame;
    const invalid_state = std.math.maxInt(u8);
    var symbol_heads: [max_fse_compression_symbol + 1]u8 = @splat(invalid_state);
    var symbol_next: [max_sequence_fse_table_size]u8 = undefined;
    var state = entries.len;
    while (state > 0) {
        state -= 1;
        const symbol = entries[state].symbol;
        if (symbol > max_fse_compression_symbol) return error.CorruptFrame;
        symbol_next[state] = symbol_heads[symbol];
        symbol_heads[symbol] = @intCast(state);
    }

    const last = buffers.codes.len - 1;
    const last_state = symbol_heads[buffers.codes[last]];
    if (last_state == invalid_state) return error.CorruptFrame;
    var next_state = last_state;
    buffers.next_states[last] = @intCast(entries[last_state].baseline);
    buffers.state_bits[last] = entries[last_state].bits;
    var i = last;
    while (i > 0) {
        i -= 1;
        var candidate_state = symbol_heads[buffers.codes[i]];
        while (candidate_state != invalid_state) : (candidate_state = symbol_next[candidate_state]) {
            const candidate = entries[candidate_state];
            if (next_state >= candidate.baseline and
                next_state - candidate.baseline < (@as(usize, 1) << @intCast(candidate.bits))) break;
        }
        if (candidate_state == invalid_state) return error.CorruptFrame;
        const entry = entries[candidate_state];
        buffers.transition_values[i] = @intCast(next_state - entry.baseline);
        buffers.transition_bits[i] = entry.bits;
        buffers.next_states[i] = @intCast(entry.baseline);
        buffers.state_bits[i] = entry.bits;
        next_state = candidate_state;
    }
    return @intCast(next_state);
}

noinline fn fillLargeCompressedSequenceTransitionsDirect(
    buffers: LargeCompressedSequenceBuffers,
    table: *const FseCompressionTable,
) Error!u8 {
    return large_transition.fill(
        buffers.codes,
        table.state_table[0..table.table_len],
        &table.transforms,
        table.max_symbol,
        buffers.next_states,
        buffers.state_bits,
        buffers.transition_values,
        buffers.transition_bits,
    ) orelse error.CorruptFrame;
}

fn buildFseDecodeTableFromNormalized(
    normalized: []const i16,
    table_log: u8,
    entries: *[max_sequence_fse_table_size]FseTableEntry,
) Error!usize {
    const table_len: usize = @as(usize, 1) << @intCast(table_log);
    if (table_len > entries.len) return error.CorruptFrame;
    var values: [max_fse_compression_symbol + 1]u16 = undefined;
    if (normalized.len > values.len) return error.CorruptFrame;
    for (normalized, 0..) |value, i| {
        if (value < -1) return error.CorruptFrame;
        values[i] = if (value == -1) 0 else @intCast(value + 1);
    }
    try buildFseTable(values[0..normalized.len], entries[0..table_len]);
    return table_len;
}

fn fillCompressedSequenceTransitions(plan: *CompressedSequencePlan, entries: []const FseTableEntry) Error!void {
    if (plan.len == 0) return error.CorruptFrame;
    // Build compact per-symbol chains once. Walking only states whose symbol
    // matches the current code preserves the old ascending-state tie rule while
    // avoiding a full 32-entry table scan for every sequence position.
    const invalid_state = std.math.maxInt(u8);
    var symbol_heads: [max_fse_compression_symbol + 1]u8 = @splat(invalid_state);
    var symbol_next: [max_sequence_fse_table_size]u8 = undefined;
    var state = entries.len;
    while (state > 0) {
        state -= 1;
        const symbol = entries[state].symbol;
        if (symbol > max_fse_compression_symbol) return error.CorruptFrame;
        symbol_next[state] = symbol_heads[symbol];
        symbol_heads[symbol] = @intCast(state);
    }

    const last_state = symbol_heads[compressedSequenceCode(plan, plan.len - 1)];
    if (last_state == invalid_state) return error.CorruptFrame;
    var next_state = last_state;
    if (comptime builtin.is_test) {
        plan.next_states[plan.len - 1] = @intCast(entries[last_state].baseline);
        plan.state_bits[plan.len - 1] = entries[last_state].bits;
    }

    var i = plan.len - 1;
    var transition_bit_count: u16 = 0;
    while (i > 0) {
        i -= 1;
        var candidate_state = symbol_heads[compressedSequenceCode(plan, i)];
        while (candidate_state != invalid_state) : (candidate_state = symbol_next[candidate_state]) {
            const candidate = entries[candidate_state];
            if (next_state >= candidate.baseline and
                next_state - candidate.baseline < (@as(usize, 1) << @intCast(candidate.bits))) break;
        }
        if (candidate_state == invalid_state) return error.CorruptFrame;
        const entry = entries[candidate_state];
        if (next_state < entry.baseline) return error.CorruptFrame;
        const transition = next_state - entry.baseline;
        if (transition >= (@as(usize, 1) << @intCast(entry.bits))) return error.CorruptFrame;
        setCompressedSequenceTransition(plan, i, @intCast(transition), entry.bits);
        transition_bit_count += entry.bits;
        if (comptime builtin.is_test) {
            plan.next_states[i] = @intCast(entry.baseline);
            plan.state_bits[i] = entry.bits;
        }
        next_state = candidate_state;
    }
    plan.initial_state = @intCast(next_state);
    plan.transition_bit_count = transition_bit_count;
}

noinline fn fillCompressedSequenceTransitionsFromCompressionTable(
    plan: *CompressedSequencePlan,
    entries: []const FseTableEntry,
    table: *const FseCompressionTable,
) linksection(fse_encode_helper_text_section) Error!void {
    if (plan.len == 0 or entries.len != table.table_len) return error.CorruptFrame;
    const table_size = table.table_len;
    const initial = try fseInitialState(table, compressedSequenceCode(plan, plan.len - 1));
    if (initial < table_size or initial - table_size >= entries.len) return error.CorruptFrame;
    var next_state = initial - table_size;
    const last_entry = entries[next_state];
    if (comptime builtin.is_test) {
        plan.next_states[plan.len - 1] = @intCast(last_entry.baseline);
        plan.state_bits[plan.len - 1] = last_entry.bits;
    }

    var i = plan.len - 1;
    var transition_bit_count: u16 = 0;
    while (i > 0) {
        i -= 1;
        const code = compressedSequenceCode(plan, i);
        if (code > table.max_symbol) return error.CorruptFrame;
        const transform = table.transforms[code];
        const encoder_state = table_size + next_state;
        const bits: usize = @intCast((@as(i32, @intCast(encoder_state)) + transform.delta_nb_bits) >> 16);
        const state_index_signed = @as(i32, @intCast(encoder_state >> @intCast(bits))) + transform.delta_find_state;
        if (state_index_signed < 0) return error.CorruptFrame;
        const state_index: usize = @intCast(state_index_signed);
        if (state_index >= table_size) return error.CorruptFrame;
        const encoded_state = table.state_table[state_index];
        if (encoded_state < table_size or encoded_state - table_size >= entries.len) return error.CorruptFrame;
        const state = encoded_state - table_size;
        const entry = entries[state];
        if (entry.symbol != code or next_state < entry.baseline) return error.CorruptFrame;
        const transition = next_state - entry.baseline;
        if (transition >= (@as(usize, 1) << @intCast(entry.bits))) return error.CorruptFrame;
        setCompressedSequenceTransition(plan, i, @intCast(transition), entry.bits);
        transition_bit_count += entry.bits;
        if (comptime builtin.is_test) {
            plan.next_states[i] = @intCast(entry.baseline);
            plan.state_bits[i] = entry.bits;
        }
        next_state = state;
    }
    plan.initial_state = @intCast(next_state);
    plan.transition_bit_count = transition_bit_count;
}

noinline fn fillCompressedSequenceTransitionsDirect(
    plan: *CompressedSequencePlan,
    table: *const FseCompressionTable,
) linksection(fse_encode_helper_text_section) Error!void {
    if (plan.len == 0 or table.table_len == 0) return error.CorruptFrame;
    const table_size = table.table_len;
    var encoder_state = try fseInitialState(table, compressedSequenceCode(plan, plan.len - 1));
    if (encoder_state < table_size or encoder_state - table_size >= table_size) return error.CorruptFrame;

    var i = plan.len - 1;
    var transition_bit_count: u16 = 0;
    while (i > 0) {
        i -= 1;
        const code = compressedSequenceCode(plan, i);
        if (code > table.max_symbol) return error.CorruptFrame;
        const transform = table.transforms[code];
        const bits: u8 = @intCast((@as(i32, @intCast(encoder_state)) + transform.delta_nb_bits) >> 16);
        const state_index_signed = @as(i32, @intCast(encoder_state >> @intCast(bits))) + transform.delta_find_state;
        if (state_index_signed < 0) return error.CorruptFrame;
        const state_index: usize = @intCast(state_index_signed);
        if (state_index >= table_size) return error.CorruptFrame;
        const transition_mask = (@as(usize, 1) << @intCast(bits)) - 1;
        setCompressedSequenceTransition(plan, i, @intCast(encoder_state & transition_mask), bits);
        transition_bit_count += bits;
        encoder_state = table.state_table[state_index];
        if (encoder_state < table_size or encoder_state - table_size >= table_size) return error.CorruptFrame;
    }
    plan.initial_state = @intCast(encoder_state - table_size);
    plan.transition_bit_count = transition_bit_count;
}

fn findCompressedSequenceState(entries: []const FseTableEntry, code: u8, maybe_next_state: ?usize) ?usize {
    for (entries, 0..) |entry, state| {
        if (entry.symbol != code) continue;
        if (maybe_next_state) |next_state| {
            if (next_state < entry.baseline) continue;
            if (next_state - entry.baseline >= (@as(usize, 1) << @intCast(entry.bits))) continue;
        }
        return state;
    }
    return null;
}

fn fillCompressedSequenceTransitionsReference(plan: *CompressedSequencePlan, entries: []const FseTableEntry) Error!void {
    if (plan.len == 0) return error.CorruptFrame;
    const last_state = findCompressedSequenceState(entries, compressedSequenceCode(plan, plan.len - 1), null) orelse return error.CorruptFrame;
    var next_state = last_state;
    if (comptime builtin.is_test) {
        plan.next_states[plan.len - 1] = @intCast(entries[last_state].baseline);
        plan.state_bits[plan.len - 1] = entries[last_state].bits;
    }
    var i = plan.len - 1;
    var transition_bit_count: u16 = 0;
    while (i > 0) {
        i -= 1;
        const state = findCompressedSequenceState(entries, compressedSequenceCode(plan, i), next_state) orelse return error.CorruptFrame;
        const entry = entries[state];
        if (next_state < entry.baseline) return error.CorruptFrame;
        const transition = next_state - entry.baseline;
        if (transition >= (@as(usize, 1) << @intCast(entry.bits))) return error.CorruptFrame;
        setCompressedSequenceTransition(plan, i, @intCast(transition), entry.bits);
        transition_bit_count += entry.bits;
        if (comptime builtin.is_test) {
            plan.next_states[i] = @intCast(entry.baseline);
            plan.state_bits[i] = entry.bits;
        }
        next_state = state;
    }
    plan.initial_state = @intCast(next_state);
    plan.transition_bit_count = transition_bit_count;
}

fn sequencePayloadLenWithTablePlans(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: ?[]const usize,
    tail_start: usize,
    plan: SequenceCombinedEmitPlan,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    if (literal_ends) |ends| {
        if (ends.len != literal_lens.len) return error.CorruptFrame;
    }

    const literals_section_len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);
    return try sequencePayloadLenWithTablePlansAndLiteralsLen(literals_section_len, literal_lens, offsets, match_lens, plan);
}

fn sequencePayloadLenWithTablePlansAndLiteralsLen(
    literals_section_len: usize,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    plan: SequenceCombinedEmitPlan,
) Error!usize {
    return try sequencePayloadLenWithTablePlansAndLiteralsLenAndOffsets(literals_section_len, literal_lens, offsets, match_lens, plan, initial_repeated_offsets);
}

fn sequencePayloadLenWithTablePlansAndLiteralsLenAndOffsets(
    literals_section_len: usize,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    plan: SequenceCombinedEmitPlan,
    initial_offsets: [3]usize,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;

    var len = literals_section_len;
    len = std.math.add(usize, len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, 1) catch return error.IntegerOverflow; // sequence mode byte
    len = std.math.add(usize, len, sequenceTablePayloadLen(plan.literal)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, sequenceTablePayloadLen(plan.offset)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, sequenceTablePayloadLen(plan.match)) catch return error.IntegerOverflow;

    var read_fields: [max_native_sequence_count * 6]BitField = undefined;
    const read_field_count = try sequenceReadFieldsWithTablePlansAndOffsets(
        read_fields[0..],
        literal_lens,
        offsets,
        match_lens,
        plan,
        initial_offsets,
    );
    var bit_count: usize = 1; // Reverse bitstream end marker.
    for (read_fields[0..read_field_count]) |field| {
        bit_count = std.math.add(usize, bit_count, field.bits) catch return error.IntegerOverflow;
    }
    return std.math.add(usize, len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
}

fn sequenceReadFieldsWithTablePlans(
    out: []BitField,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    plan: SequenceCombinedEmitPlan,
) Error!usize {
    return try sequenceReadFieldsWithTablePlansAndOffsets(out, literal_lens, offsets, match_lens, plan, initial_repeated_offsets);
}

fn sequenceReadFieldsWithTablePlansAndOffsets(
    out: []BitField,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    plan: SequenceCombinedEmitPlan,
    initial_offsets: [3]usize,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    try validateSequenceTablePlanLen(plan.literal, literal_lens.len);
    try validateSequenceTablePlanLen(plan.offset, offsets.len);
    try validateSequenceTablePlanLen(plan.match, match_lens.len);

    var count: usize = 0;
    try appendInitialSequenceStateField(out, &count, plan.literal, .literal);
    try appendInitialSequenceStateField(out, &count, plan.offset, .offset);
    try appendInitialSequenceStateField(out, &count, plan.match, .match);

    var repeated_offsets = initial_offsets;
    for (0..literal_lens.len) |i| {
        const literal_symbol = try sequenceTableSymbol(plan.literal, .literal, i);
        const offset_symbol = try sequenceTableSymbol(plan.offset, .offset, i);
        const match_symbol = try sequenceTableSymbol(plan.match, .match, i);

        const offset_extra = try sequenceOffsetExtraForEncodedOffset(offset_symbol, literal_lens[i], offsets[i], &repeated_offsets);
        try appendBitField(out, &count, offset_extra, offset_symbol.additional_bits);
        try appendBitField(out, &count, match_lens[i] - match_symbol.base, match_symbol.additional_bits);
        try appendBitField(out, &count, literal_lens[i] - literal_symbol.base, literal_symbol.additional_bits);

        if (i + 1 < literal_lens.len) {
            try appendSequenceTransitionField(out, &count, plan.literal, .literal, i);
            try appendSequenceTransitionField(out, &count, plan.match, .match, i);
            try appendSequenceTransitionField(out, &count, plan.offset, .offset, i);
        }
    }
    return count;
}

noinline fn sequenceReadFieldsWithTablePlansAndOffsetsBorrowed(
    out: []BitField,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    plan: *const SequenceCombinedEmitPlan,
    initial_offsets: [3]usize,
) linksection(wide_sequence_emit_text_section) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len < wide_borrowed_sequence_plan_min or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    try validateSequenceTablePlanLenBorrowed(&plan.literal, literal_lens.len);
    try validateSequenceTablePlanLenBorrowed(&plan.offset, offsets.len);
    try validateSequenceTablePlanLenBorrowed(&plan.match, match_lens.len);

    var count: usize = 0;
    try appendInitialSequenceStateFieldBorrowed(out, &count, &plan.literal, .literal);
    try appendInitialSequenceStateFieldBorrowed(out, &count, &plan.offset, .offset);
    try appendInitialSequenceStateFieldBorrowed(out, &count, &plan.match, .match);

    const compressed_plans = switch (plan.literal) {
        .compressed => |*literal| switch (plan.offset) {
            .compressed => |*offset| switch (plan.match) {
                .compressed => |*match| .{ literal, offset, match },
                else => null,
            },
            else => null,
        },
        else => null,
    };
    if (compressed_plans) |compressed| {
        return try appendCompressedSequenceReadFields(
            out,
            count,
            literal_lens,
            offsets,
            match_lens,
            compressed[0],
            compressed[1],
            compressed[2],
            initial_offsets,
        );
    }

    var repeated_offsets = initial_offsets;
    for (0..literal_lens.len) |i| {
        const literal_symbol = try sequenceTableSymbolBorrowed(&plan.literal, .literal, i);
        const offset_symbol = try sequenceTableSymbolBorrowed(&plan.offset, .offset, i);
        const match_symbol = try sequenceTableSymbolBorrowed(&plan.match, .match, i);

        const offset_extra = try sequenceOffsetExtraForEncodedOffset(offset_symbol, literal_lens[i], offsets[i], &repeated_offsets);
        try appendBitField(out, &count, offset_extra, offset_symbol.additional_bits);
        try appendBitField(out, &count, match_lens[i] - match_symbol.base, match_symbol.additional_bits);
        try appendBitField(out, &count, literal_lens[i] - literal_symbol.base, literal_symbol.additional_bits);

        if (i + 1 < literal_lens.len) {
            try appendSequenceTransitionFieldBorrowed(out, &count, &plan.literal, .literal, i);
            try appendSequenceTransitionFieldBorrowed(out, &count, &plan.match, .match, i);
            try appendSequenceTransitionFieldBorrowed(out, &count, &plan.offset, .offset, i);
        }
    }
    return count;
}

noinline fn appendCompressedSequenceReadFields(
    out: []BitField,
    initial_count: usize,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_plan: *const CompressedSequencePlan,
    offset_plan: *const CompressedSequencePlan,
    match_plan: *const CompressedSequencePlan,
    initial_offsets: [3]usize,
) linksection(wide_sequence_emit_text_section) Error!usize {
    var count = initial_count;
    var repeated_offsets = initial_offsets;
    for (0..literal_lens.len) |i| {
        const literal_step = compressedSequencePackedStep(literal_plan, i);
        const offset_step = compressedSequencePackedStep(offset_plan, i);
        const match_step = compressedSequencePackedStep(match_plan, i);
        const literal_code = compressedSequencePackedCode(literal_step);
        const offset_code = compressedSequencePackedCode(offset_step);
        const match_code = compressedSequencePackedCode(match_step);
        if (literal_code >= ll_base.len or offset_code >= of_base.len or match_code >= ml_base.len) return error.CorruptFrame;

        const offset_symbol: SequenceSymbol = .{
            .base = @intCast(of_base[offset_code]),
            .additional_bits = of_bits[offset_code],
            .next_state = 0,
            .state_bits = 0,
        };
        const offset_extra = try sequenceOffsetExtraForEncodedOffset(offset_symbol, literal_lens[i], offsets[i], &repeated_offsets);
        try appendBitField(out, &count, offset_extra, offset_symbol.additional_bits);
        try appendBitField(out, &count, match_lens[i] - ml_base[match_code], ml_bits[match_code]);
        try appendBitField(out, &count, literal_lens[i] - ll_base[literal_code], ll_bits[literal_code]);

        if (i + 1 < literal_lens.len) {
            try appendBitField(out, &count, compressedSequencePackedTransitionValue(literal_step), compressedSequencePackedTransitionBits(literal_step));
            try appendBitField(out, &count, compressedSequencePackedTransitionValue(match_step), compressedSequencePackedTransitionBits(match_step));
            try appendBitField(out, &count, compressedSequencePackedTransitionValue(offset_step), compressedSequencePackedTransitionBits(offset_step));
        }
    }
    return count;
}

fn sequenceOffsetExtraForEncodedOffset(
    symbol: SequenceSymbol,
    literal_len: usize,
    offset: usize,
    repeated_offsets: *[3]usize,
) Error!usize {
    if (symbol.additional_bits > 1) {
        if (offset < symbol.base) return error.CorruptFrame;
        const extra = offset - symbol.base;
        if (extra >= (@as(usize, 1) << @intCast(symbol.additional_bits))) return error.CorruptFrame;
        updateRepeatedOffsets(repeated_offsets, offset);
        return extra;
    }
    if (symbol.additional_bits == 0 and symbol.base == 0) {
        const index: usize = @intFromBool(literal_len == 0);
        if (offset == 0 or repeated_offsets[index] != offset) return error.CorruptFrame;
        _ = try useRepeatedOffset(repeated_offsets, index);
        return 0;
    }
    if (symbol.additional_bits == 1 and symbol.base == 1) {
        if (literal_len == 0) {
            if (offset != 0 and repeated_offsets[2] == offset) {
                _ = try useRepeatedOffset(repeated_offsets, 2);
                return 0;
            }
            if (repeated_offsets[0] > 1 and repeated_offsets[0] - 1 == offset) {
                updateRepeatedOffsets(repeated_offsets, offset);
                return 1;
            }
        } else {
            if (offset != 0 and repeated_offsets[1] == offset) {
                _ = try useRepeatedOffset(repeated_offsets, 1);
                return 0;
            }
            if (offset != 0 and repeated_offsets[2] == offset) {
                _ = try useRepeatedOffset(repeated_offsets, 2);
                return 1;
            }
        }
        return error.CorruptFrame;
    }

    const alternatives: usize = @as(usize, 1) << @intCast(symbol.additional_bits);
    var extra: usize = 0;
    while (extra < alternatives) : (extra += 1) {
        var trial_offsets = repeated_offsets.*;
        const resolved = resolveSequenceOffset(
            symbol.base,
            symbol.additional_bits,
            extra,
            literal_len,
            &trial_offsets,
        ) catch |err| switch (err) {
            error.InvalidMatch, error.UnsupportedZstdFeature => continue,
            else => return err,
        };
        if (resolved == offset) {
            repeated_offsets.* = trial_offsets;
            return extra;
        }
    }
    return error.CorruptFrame;
}

fn sequenceOffsetExtraForEncodedOffsetReference(
    symbol: SequenceSymbol,
    literal_len: usize,
    offset: usize,
    repeated_offsets: *[3]usize,
) Error!usize {
    if (symbol.additional_bits > 1) {
        if (offset < symbol.base) return error.CorruptFrame;
        const extra = offset - symbol.base;
        if (extra >= (@as(usize, 1) << @intCast(symbol.additional_bits))) return error.CorruptFrame;
        updateRepeatedOffsets(repeated_offsets, offset);
        return extra;
    }
    const alternatives: usize = @as(usize, 1) << @intCast(symbol.additional_bits);
    var extra: usize = 0;
    while (extra < alternatives) : (extra += 1) {
        var trial_offsets = repeated_offsets.*;
        const resolved = resolveSequenceOffset(
            symbol.base,
            symbol.additional_bits,
            extra,
            literal_len,
            &trial_offsets,
        ) catch |err| switch (err) {
            error.InvalidMatch, error.UnsupportedZstdFeature => continue,
            else => return err,
        };
        if (resolved == offset) {
            repeated_offsets.* = trial_offsets;
            return extra;
        }
    }
    return error.CorruptFrame;
}

test "zstd direct repeated-offset extra mapping matches loop reference" {
    const histories = [_][3]usize{
        .{ 1, 4, 8 },
        .{ 4, 1, 8 },
        .{ 8, 4, 1 },
        .{ 2, 2, 2 },
        .{ 1, 1, 4 },
        .{ 2, 4, 8 },
        .{ 0, 4, 8 },
        .{ 1, 0, 8 },
        .{ 1, 4, 0 },
    };
    const symbols = [_]SequenceSymbol{
        try sequenceRleSymbol(.offset, 0),
        try sequenceRleSymbol(.offset, 1),
        sequence_predefined.offset_symbols[0],
        sequence_predefined.offset_symbols[23],
        sequence_predefined.offset_symbols[14],
    };
    for (symbols) |symbol| {
        for (histories) |history| {
            for ([_]usize{ 0, 1, 7 }) |literal_len| {
                for (0..17) |offset| {
                    var expected_offsets = history;
                    var actual_offsets = history;
                    const expected = sequenceOffsetExtraForEncodedOffsetReference(symbol, literal_len, offset, &expected_offsets);
                    const actual = sequenceOffsetExtraForEncodedOffset(symbol, literal_len, offset, &actual_offsets);
                    if (expected) |expected_extra| {
                        try std.testing.expectEqual(expected_extra, try actual);
                        try std.testing.expectEqual(expected_offsets, actual_offsets);
                    } else |expected_error| {
                        try std.testing.expectError(expected_error, actual);
                        try std.testing.expectEqual(expected_offsets, actual_offsets);
                    }
                }
            }
        }
    }
}

fn appendInitialSequenceStateField(out: []BitField, count: *usize, plan: SequenceTableEmitPlan, kind: SequenceTableKind) Error!void {
    switch (plan) {
        .rle => {},
        .predefined => |predefined| {
            if (predefined.len == 0) return error.CorruptFrame;
            try appendBitField(out, count, predefined.states[0], predefinedInitialStateBits(kind));
        },
        .compressed => |compressed| {
            if (compressed.len == 0) return error.CorruptFrame;
            try appendBitField(out, count, compressed.initial_state, compressed.accuracy_log);
        },
        .repeat => |repeat| {
            if (repeat.len == 0) return error.CorruptFrame;
            if (repeat.source.mode != .rle)
                try appendBitField(out, count, repeat.states[0], repeatSequenceInitialStateBits(repeat.source));
        },
    }
}

inline fn appendInitialSequenceStateFieldBorrowed(out: []BitField, count: *usize, plan: *const SequenceTableEmitPlan, kind: SequenceTableKind) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |*predefined| {
            if (predefined.len == 0) return error.CorruptFrame;
            try appendBitField(out, count, predefined.states[0], predefinedInitialStateBits(kind));
        },
        .compressed => |*compressed| {
            if (compressed.len == 0) return error.CorruptFrame;
            try appendBitField(out, count, compressed.initial_state, compressed.accuracy_log);
        },
        .repeat => |*repeat| {
            if (repeat.len == 0) return error.CorruptFrame;
            if (repeat.source.mode != .rle)
                try appendBitField(out, count, repeat.states[0], repeatSequenceInitialStateBits(repeat.source));
        },
    }
}

fn appendSequenceTransitionField(out: []BitField, count: *usize, plan: SequenceTableEmitPlan, kind: SequenceTableKind, index: usize) Error!void {
    switch (plan) {
        .rle => {},
        .predefined => |predefined| {
            if (index + 1 >= predefined.len) return error.CorruptFrame;
            const symbol = try sequenceTableSymbol(plan, kind, index);
            if (predefined.states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try appendBitField(out, count, predefined.states[index + 1] - symbol.next_state, symbol.state_bits);
        },
        .compressed => |compressed| {
            if (index + 1 >= compressed.len) return error.CorruptFrame;
            try appendBitField(out, count, compressedSequenceTransitionValue(&compressed, index), compressedSequenceTransitionBits(&compressed, index));
        },
        .repeat => |repeat| {
            if (index + 1 >= repeat.len) return error.CorruptFrame;
            if (repeat.source.mode == .rle) return;
            const symbol = try sequenceTableSymbol(plan, kind, index);
            if (repeat.states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try appendBitField(out, count, repeat.states[index + 1] - symbol.next_state, symbol.state_bits);
        },
    }
}

inline fn appendSequenceTransitionFieldBorrowed(out: []BitField, count: *usize, plan: *const SequenceTableEmitPlan, kind: SequenceTableKind, index: usize) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |*predefined| {
            if (index + 1 >= predefined.len) return error.CorruptFrame;
            const symbol = try sequenceTableSymbolBorrowed(plan, kind, index);
            if (predefined.states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try appendBitField(out, count, predefined.states[index + 1] - symbol.next_state, symbol.state_bits);
        },
        .compressed => |*compressed| {
            if (index + 1 >= compressed.len) return error.CorruptFrame;
            try appendBitField(out, count, compressedSequenceTransitionValue(compressed, index), compressedSequenceTransitionBits(compressed, index));
        },
        .repeat => |*repeat| {
            if (index + 1 >= repeat.len) return error.CorruptFrame;
            if (repeat.source.mode == .rle) return;
            const symbol = try sequenceTableSymbolBorrowed(plan, kind, index);
            if (repeat.states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try appendBitField(out, count, repeat.states[index + 1] - symbol.next_state, symbol.state_bits);
        },
    }
}

fn validateSequenceTablePlanLen(plan: SequenceTableEmitPlan, len: usize) Error!void {
    switch (plan) {
        .rle => {},
        .predefined => |predefined| if (predefined.len != len) return error.CorruptFrame,
        .compressed => |compressed| if (compressed.len != len) return error.CorruptFrame,
        .repeat => |repeat| if (repeat.len != len) return error.CorruptFrame,
    }
}

inline fn validateSequenceTablePlanLenBorrowed(plan: *const SequenceTableEmitPlan, len: usize) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |*predefined| if (predefined.len != len) return error.CorruptFrame,
        .compressed => |*compressed| if (compressed.len != len) return error.CorruptFrame,
        .repeat => |*repeat| if (repeat.len != len) return error.CorruptFrame,
    }
}

fn sequenceTableSymbol(plan: SequenceTableEmitPlan, kind: SequenceTableKind, index: usize) Error!SequenceSymbol {
    return switch (plan) {
        .rle => |code| sequenceRleSymbol(kind, code),
        .predefined => |predefined| blk: {
            if (index >= predefined.len) return error.CorruptFrame;
            const state = predefined.states[index];
            const symbols = sequenceTablePredefinedSymbols(kind);
            if (state >= symbols.len) return error.CorruptFrame;
            break :blk symbols[state];
        },
        .compressed => |compressed| blk: {
            if (index >= compressed.len) return error.CorruptFrame;
            break :blk try sequenceRleSymbol(kind, compressedSequenceCode(&compressed, index));
        },
        .repeat => |repeat| blk: {
            if (index >= repeat.len) return error.CorruptFrame;
            const state = repeat.states[index];
            break :blk switch (repeat.source.mode) {
                .predefined, .compressed => if (state < repeat.source.symbols.len) repeat.source.symbols[state] else return error.CorruptFrame,
                .rle => repeat.source.rle orelse return error.CorruptFrame,
                .repeat => unreachable,
            };
        },
    };
}

inline fn sequenceTableSymbolBorrowed(plan: *const SequenceTableEmitPlan, kind: SequenceTableKind, index: usize) Error!SequenceSymbol {
    return switch (plan.*) {
        .rle => |code| sequenceRleSymbol(kind, code),
        .predefined => |*predefined| blk: {
            if (index >= predefined.len) return error.CorruptFrame;
            const state = predefined.states[index];
            const symbols = sequenceTablePredefinedSymbols(kind);
            if (state >= symbols.len) return error.CorruptFrame;
            break :blk symbols[state];
        },
        .compressed => |*compressed| blk: {
            if (index >= compressed.len) return error.CorruptFrame;
            break :blk try sequenceRleSymbol(kind, compressedSequenceCode(compressed, index));
        },
        .repeat => |*repeat| blk: {
            if (index >= repeat.len) return error.CorruptFrame;
            const state = repeat.states[index];
            break :blk switch (repeat.source.mode) {
                .predefined, .compressed => if (state < repeat.source.symbols.len) repeat.source.symbols[state] else return error.CorruptFrame,
                .rle => repeat.source.rle orelse return error.CorruptFrame,
                .repeat => unreachable,
            };
        },
    };
}

fn sequenceRleSymbol(kind: SequenceTableKind, code: u8) Error!SequenceSymbol {
    const bases = sequenceTableBases(kind);
    const bits = sequenceTableBits(kind);
    if (code >= bases.len or code >= bits.len) return error.CorruptFrame;
    return .{
        .base = @intCast(bases[code]),
        .additional_bits = bits[code],
        .next_state = 0,
        .state_bits = 0,
    };
}

fn sequenceModeByte(plan: SequenceCombinedEmitPlan) u8 {
    return (@as(u8, @intFromEnum(sequenceTableMode(plan.literal))) << 6) |
        (@as(u8, @intFromEnum(sequenceTableMode(plan.offset))) << 4) |
        (@as(u8, @intFromEnum(sequenceTableMode(plan.match))) << 2);
}

fn sequenceModeByteBorrowed(plan: *const SequenceCombinedEmitPlan) u8 {
    return (@as(u8, @intFromEnum(sequenceTableModeBorrowed(&plan.literal))) << 6) |
        (@as(u8, @intFromEnum(sequenceTableModeBorrowed(&plan.offset))) << 4) |
        (@as(u8, @intFromEnum(sequenceTableModeBorrowed(&plan.match))) << 2);
}

fn largeSequenceModeByte(plan: LargeSequenceCombinedEmitPlan) u8 {
    return (@as(u8, @intFromEnum(largeSequenceTableMode(plan.literal))) << 6) |
        (@as(u8, @intFromEnum(largeSequenceTableMode(plan.offset))) << 4) |
        (@as(u8, @intFromEnum(largeSequenceTableMode(plan.match))) << 2);
}

fn sequenceTableMode(plan: SequenceTableEmitPlan) SymbolMode {
    return switch (plan) {
        .rle => .rle,
        .predefined => .predefined,
        .compressed => .compressed,
        .repeat => .repeat,
    };
}

fn sequenceTableModeBorrowed(plan: *const SequenceTableEmitPlan) SymbolMode {
    return switch (plan.*) {
        .rle => .rle,
        .predefined => .predefined,
        .compressed => .compressed,
        .repeat => .repeat,
    };
}

fn largeSequenceTableMode(plan: LargeSequenceTableEmitPlan) SymbolMode {
    return switch (plan) {
        .rle => .rle,
        .predefined => .predefined,
        .compressed => .compressed,
        .repeat => .repeat,
    };
}

fn appendSequenceTablePayload(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: SequenceTableEmitPlan) Error!void {
    switch (plan) {
        .rle => |code| try out.append(allocator, code),
        .predefined => {},
        .compressed => |compressed| try out.appendSlice(allocator, compressed.table_payload[0..compressed.table_payload_len]),
        .repeat => {},
    }
}

fn appendSequenceTablePayloadBorrowed(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: *const SequenceTableEmitPlan) Error!void {
    switch (plan.*) {
        .rle => |code| try out.append(allocator, code),
        .predefined => {},
        .compressed => |*compressed| try out.appendSlice(allocator, compressed.table_payload[0..compressed.table_payload_len]),
        .repeat => {},
    }
}

fn appendLargeSequenceTablePayload(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: *const LargeSequenceTableEmitPlan) Error!void {
    switch (plan.*) {
        .rle => |code| try out.append(allocator, code),
        .predefined => {},
        .compressed => |compressed| try out.appendSlice(allocator, compressed.table_payload[0..compressed.table_payload_len]),
        .repeat => {},
    }
}

fn sequenceTablePayloadLen(plan: SequenceTableEmitPlan) usize {
    return switch (plan) {
        .rle => 1,
        .predefined => 0,
        .compressed => |compressed| compressed.table_payload_len,
        .repeat => 0,
    };
}

fn largeSequenceTablePayloadLen(plan: *const LargeSequenceTableEmitPlan) usize {
    return switch (plan.*) {
        .rle => 1,
        .predefined => 0,
        .compressed => |compressed| compressed.table_payload_len,
        .repeat => 0,
    };
}

fn validateLargeSequenceTablePlanLen(plan: *const LargeSequenceTableEmitPlan, len: usize) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |states| if (states.len != len) return error.CorruptFrame,
        .compressed => |compressed| if (compressed.codes.len != len or
            compressed.next_states.len != len or
            compressed.state_bits.len != len or
            compressed.transition_values.len != len or
            compressed.transition_bits.len != len) return error.CorruptFrame,
        .repeat => |repeat| if (repeat.len != len or repeat.states.len != len) return error.CorruptFrame,
    }
}

fn largeSequenceTableSymbol(plan: *const LargeSequenceTableEmitPlan, kind: SequenceTableKind, index: usize) Error!SequenceSymbol {
    return switch (plan.*) {
        .rle => |code| sequenceRleSymbol(kind, code),
        .predefined => |states| blk: {
            if (index >= states.len) return error.CorruptFrame;
            const symbols = sequenceTablePredefinedSymbols(kind);
            if (states[index] >= symbols.len) return error.CorruptFrame;
            break :blk symbols[states[index]];
        },
        .compressed => |compressed| blk: {
            if (index >= compressed.codes.len) return error.CorruptFrame;
            var symbol = try sequenceRleSymbol(kind, compressed.codes[index]);
            symbol.next_state = compressed.next_states[index];
            symbol.state_bits = compressed.state_bits[index];
            break :blk symbol;
        },
        .repeat => |repeat| blk: {
            if (index >= repeat.len) return error.CorruptFrame;
            const state = repeat.states[index];
            break :blk switch (repeat.source.mode) {
                .predefined, .compressed => if (state < repeat.source.symbols.len) repeat.source.symbols[state] else return error.CorruptFrame,
                .rle => repeat.source.rle orelse return error.CorruptFrame,
                .repeat => unreachable,
            };
        },
    };
}

fn appendLargeInitialSequenceStateBits(
    writer: *ReverseBitstreamWriter,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    plan: *const LargeSequenceTableEmitPlan,
    kind: SequenceTableKind,
) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |states| {
            if (states.len == 0) return error.CorruptFrame;
            try addCheckedReverseBits(writer, allocator, out, states[0], predefinedInitialStateBits(kind));
        },
        .compressed => |compressed| try addCheckedReverseBits(writer, allocator, out, compressed.initial_state, compressed.accuracy_log),
        .repeat => |repeat| {
            if (repeat.len == 0) return error.CorruptFrame;
            if (repeat.source.mode != .rle)
                try addCheckedReverseBits(writer, allocator, out, repeat.states[0], repeatSequenceInitialStateBits(repeat.source));
        },
    }
}

fn appendLargeSequenceTransitionBits(
    writer: *ReverseBitstreamWriter,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    plan: *const LargeSequenceTableEmitPlan,
    kind: SequenceTableKind,
    index: usize,
) Error!void {
    switch (plan.*) {
        .rle => {},
        .predefined => |states| {
            if (index + 1 >= states.len) return error.CorruptFrame;
            const symbol = try largeSequenceTableSymbol(plan, kind, index);
            if (states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try addCheckedReverseBits(writer, allocator, out, states[index + 1] - symbol.next_state, symbol.state_bits);
        },
        .compressed => |compressed| {
            if (index + 1 >= compressed.codes.len) return error.CorruptFrame;
            try addCheckedReverseBits(writer, allocator, out, compressed.transition_values[index], compressed.transition_bits[index]);
        },
        .repeat => |repeat| {
            if (index + 1 >= repeat.len) return error.CorruptFrame;
            if (repeat.source.mode == .rle) return;
            const symbol = try largeSequenceTableSymbol(plan, kind, index);
            if (repeat.states[index + 1] < symbol.next_state) return error.CorruptFrame;
            try addCheckedReverseBits(writer, allocator, out, repeat.states[index + 1] - symbol.next_state, symbol.state_bits);
        },
    }
}

fn sequenceTableBases(kind: SequenceTableKind) []const usize {
    return switch (kind) {
        .literal => ll_base[0..],
        .offset => of_base[0..],
        .match => ml_base[0..],
    };
}

fn sequenceTableBits(kind: SequenceTableKind) []const u8 {
    return switch (kind) {
        .literal => ll_bits[0..],
        .offset => of_bits[0..],
        .match => ml_bits[0..],
    };
}

fn sequenceTablePredefinedSymbols(kind: SequenceTableKind) []const SequenceSymbol {
    return switch (kind) {
        .literal => sequence_predefined.literal_symbols[0..],
        .offset => sequence_predefined.offset_symbols[0..],
        .match => sequence_predefined.match_symbols[0..],
    };
}

fn sequenceTablePredefinedMinAdditionalBits(kind: SequenceTableKind) u8 {
    return switch (kind) {
        .literal, .match => 0,
        .offset => 2,
    };
}

fn sequenceTableSymbolCountMax(kind: SequenceTableKind) usize {
    return switch (kind) {
        .literal => sequence_table_symbol_count_max.literal,
        .offset => sequence_table_symbol_count_max.offset,
        .match => sequence_table_symbol_count_max.match,
    };
}

fn sequenceTableAccuracyLogMax(kind: SequenceTableKind) u4 {
    return switch (kind) {
        .literal => sequence_table_accuracy_log_max.literal,
        .offset => sequence_table_accuracy_log_max.offset,
        .match => sequence_table_accuracy_log_max.match,
    };
}

fn predefinedInitialStateBits(kind: SequenceTableKind) u8 {
    return switch (kind) {
        .literal, .match => 6,
        .offset => 5,
    };
}

fn multiSequencePayloadLenInternal(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: ?[]const usize,
    tail_start: usize,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    if (literal_ends) |ends| {
        if (ends.len != literal_lens.len) return error.CorruptFrame;
    }
    const literal_plan = (try planPredefinedSequenceValues(literal_lens, &sequence_predefined.literal_symbols, 0)) orelse return error.CorruptFrame;
    const offset_plan = (try planPredefinedSequenceValues(offsets, &sequence_predefined.offset_symbols, 2)) orelse return error.CorruptFrame;
    const match_plan = (try planPredefinedSequenceValues(match_lens, &sequence_predefined.match_symbols, 0)) orelse return error.CorruptFrame;

    const literals_section_len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);
    return try predefinedSequencePayloadLenFromPlans(literal_plan, offset_plan, match_plan, literal_lens, offsets, match_lens, literals_section_len);
}

fn predefinedSequencePayloadLenWithLiteralsLen(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    const literal_plan = (try planPredefinedSequenceValues(literal_lens, &sequence_predefined.literal_symbols, 0)) orelse return error.CorruptFrame;
    const offset_plan = (try planPredefinedSequenceValues(offsets, &sequence_predefined.offset_symbols, 2)) orelse return error.CorruptFrame;
    const match_plan = (try planPredefinedSequenceValues(match_lens, &sequence_predefined.match_symbols, 0)) orelse return error.CorruptFrame;
    return try predefinedSequencePayloadLenFromPlans(literal_plan, offset_plan, match_plan, literal_lens, offsets, match_lens, literals_section_len);
}

fn predefinedSequencePayloadLenFromPlans(
    literal_plan: PredefinedSequencePlan,
    offset_plan: PredefinedSequencePlan,
    match_plan: PredefinedSequencePlan,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
) Error!usize {
    if (literal_plan.len != offset_plan.len or literal_plan.len != match_plan.len) return error.CorruptFrame;
    if (literal_lens.len != literal_plan.len or offsets.len != literal_plan.len or match_lens.len != literal_plan.len) return error.CorruptFrame;
    var len = literals_section_len;
    len = std.math.add(usize, len, try sequenceCountLen(literal_plan.len)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, 1) catch return error.IntegerOverflow; // sequence mode byte

    var read_fields: [max_native_sequence_count * 6]BitField = undefined;
    const read_field_count = try predefinedSequenceReadFields(
        read_fields[0..],
        literal_plan,
        offset_plan,
        match_plan,
        literal_lens,
        offsets,
        match_lens,
    );
    var bit_count: usize = 1; // Reverse bitstream end marker.
    for (read_fields[0..read_field_count]) |field| {
        bit_count = std.math.add(usize, bit_count, field.bits) catch return error.IntegerOverflow;
    }
    const bitstream_len = (bit_count + 7) / 8;
    return std.math.add(usize, len, bitstream_len) catch return error.IntegerOverflow;
}

fn sequenceLiteralsPayloadInfo(
    block: []const u8,
    literal_lens: []const usize,
    literal_ends: ?[]const usize,
    tail_start: usize,
) Error!SequenceLiteralsInfo {
    if (literal_ends) |ends| return try sequenceLiteralsInfo(block, literal_lens, ends, tail_start);

    var regenerated_literals = block.len - tail_start;
    for (literal_lens) |literal_len| {
        regenerated_literals = std.math.add(usize, regenerated_literals, literal_len) catch return error.IntegerOverflow;
    }
    return .{
        .regenerated_len = regenerated_literals,
        .payload_len = regenerated_literals,
    };
}

fn singleRleSequencePayloadLen(
    block: []const u8,
    literal_len: usize,
    offset: usize,
    match_len: usize,
    tail_start: usize,
) Error!usize {
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{offset};
    const match_lens = [_]usize{match_len};
    const literal_ends = [_]usize{tail_start};
    return try rleSequencePayloadLenWithLiteralEnds(
        block,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        tail_start,
        try sequenceCodeForValue(literal_len, &ll_base, &ll_bits),
        try sequenceCodeForValue(offset, &of_base, &of_bits),
        try sequenceCodeForValue(match_len, &ml_base, &ml_bits),
    );
}

fn singleBestSequencePayloadLen(
    block: []const u8,
    literal_len: usize,
    offset: usize,
    match_len: usize,
    tail_start: usize,
) Error!usize {
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{offset};
    const match_lens = [_]usize{match_len};
    const literal_ends = [_]usize{tail_start};
    return try bestSequencePayloadLenWithLiteralEnds(
        block,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        tail_start,
    );
}

fn rleSequencePayloadLen(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    tail_start: usize,
    literal_code: u8,
    offset_code: u8,
    match_code: u8,
) Error!usize {
    return try rleSequencePayloadLenInternal(block, literal_lens, offsets, match_lens, null, tail_start, literal_code, offset_code, match_code);
}

fn rleSequencePayloadLenForValuesWithLiteralEnds(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
) Error!usize {
    if (literal_lens.len == 0 or literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    const literals_section_len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);
    return try rleSequencePayloadLenForValuesWithLiteralsLen(literal_lens, offsets, match_lens, literals_section_len);
}

fn rleSequencePayloadLenForValuesWithLiteralsLen(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
) Error!usize {
    if (literal_lens.len == 0 or literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    return try rleSequencePayloadLenWithLiteralsLen(
        literal_lens,
        offsets,
        match_lens,
        literals_section_len,
        try sequenceCodeForValue(literal_lens[0], &ll_base, &ll_bits),
        try sequenceCodeForValue(offsets[0], &of_base, &of_bits),
        try sequenceCodeForValue(match_lens[0], &ml_base, &ml_bits),
    );
}

fn rleSequencePayloadLenWithLiteralsLen(
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literals_section_len: usize,
    literal_code: u8,
    offset_code: u8,
    match_code: u8,
) Error!usize {
    if (literal_lens.len == 0 or literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len > max_native_sequence_count) return error.CorruptFrame;

    var bit_count: usize = 1;
    for (literal_lens, 0..) |literal_len, i| {
        if (try sequenceCodeForValue(literal_len, &ll_base, &ll_bits) != literal_code) return error.CorruptFrame;
        if (try sequenceCodeForValue(offsets[i], &of_base, &of_bits) != offset_code) return error.CorruptFrame;
        if (try sequenceCodeForValue(match_lens[i], &ml_base, &ml_bits) != match_code) return error.CorruptFrame;
        bit_count = std.math.add(usize, bit_count, ll_bits[literal_code]) catch return error.IntegerOverflow;
        bit_count = std.math.add(usize, bit_count, ml_bits[match_code]) catch return error.IntegerOverflow;
        bit_count = std.math.add(usize, bit_count, of_bits[offset_code]) catch return error.IntegerOverflow;
    }

    var len = literals_section_len;
    len = std.math.add(usize, len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, 1 + 3) catch return error.IntegerOverflow;
    return std.math.add(usize, len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
}

fn rleSequencePayloadLenWithLiteralEnds(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: []const usize,
    tail_start: usize,
    literal_code: u8,
    offset_code: u8,
    match_code: u8,
) Error!usize {
    return try rleSequencePayloadLenInternal(block, literal_lens, offsets, match_lens, literal_ends, tail_start, literal_code, offset_code, match_code);
}

fn rleSequencePayloadLenInternal(
    block: []const u8,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
    literal_ends: ?[]const usize,
    tail_start: usize,
    literal_code: u8,
    offset_code: u8,
    match_code: u8,
) Error!usize {
    if (literal_lens.len != offsets.len or literal_lens.len != match_lens.len) return error.CorruptFrame;
    if (literal_lens.len == 0 or literal_lens.len > max_native_sequence_count) return error.CorruptFrame;
    if (literal_ends) |ends| {
        if (ends.len != literal_lens.len) return error.CorruptFrame;
    }

    var bit_count: usize = 1; // Reverse bitstream end marker.
    for (literal_lens, 0..) |literal_len, i| {
        if (try sequenceCodeForValue(literal_len, &ll_base, &ll_bits) != literal_code) return error.CorruptFrame;
        if (try sequenceCodeForValue(offsets[i], &of_base, &of_bits) != offset_code) return error.CorruptFrame;
        if (try sequenceCodeForValue(match_lens[i], &ml_base, &ml_bits) != match_code) return error.CorruptFrame;
        bit_count = std.math.add(usize, bit_count, ll_bits[literal_code]) catch return error.IntegerOverflow;
        bit_count = std.math.add(usize, bit_count, ml_bits[match_code]) catch return error.IntegerOverflow;
        bit_count = std.math.add(usize, bit_count, of_bits[offset_code]) catch return error.IntegerOverflow;
    }

    var len = try sequenceLiteralsPayloadSectionLen(block, literal_lens, literal_ends, tail_start);
    len = std.math.add(usize, len, try sequenceCountLen(literal_lens.len)) catch return error.IntegerOverflow;
    len = std.math.add(usize, len, 1 + 3) catch return error.IntegerOverflow; // modes + three RLE symbol codes.
    return std.math.add(usize, len, (bit_count + 7) / 8) catch return error.IntegerOverflow;
}

fn sequenceCountLen(count: usize) Error!usize {
    if (count == 0) return error.CorruptFrame;
    if (count < 128) return 1;
    if (count < 0x7f00) return 2;
    return 3;
}

const SmallHuffmanLiteralPlan = struct {
    // Direct Huffman tree headers can describe symbols only through
    // `native_max_direct_huffman_symbol`; larger alphabets are serialized with
    // FSE-compressed Huffman weights. Keep the plan itself full-width so the
    // literal bitstream builder and tree re-use logic do not need separate
    // "small direct" and "high-byte FSE" code paths.
    symbols: [256]u8 = undefined,
    weights: [256]u4 = undefined,
    frequencies: [256]u32 = .{0} ** 256,
    // The format caps literal codes at 11 bits; u16 keeps the dense lookup
    // compact while avoiding repeated canonical-code reconstruction.
    codes: [256]u16 = [_]u16{0} ** 256,
    // Sequence-plan scoring visits every literal for every explored branch.
    // Keep the finalized code lengths addressable by byte value so that pass
    // is O(literals), rather than searching the sorted symbol list per byte.
    bit_counts: [256]u8 = .{0} ** 256,
    len: usize = 0,
    max_symbol: u8 = 0,
    max_bit_count: u4 = 0,
};

fn emitSmallHuffmanLiteralBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, previous_huffman_plan: *?SmallHuffmanLiteralPlan) Error!bool {
    const plan = smallHuffmanLiteralPlan(block) orelse return false;
    if (findRepeatedPatternSegment(block)) |pattern| {
        if (pattern.match_len >= 16) return false;
    }

    const reuse_previous_tree = if (previous_huffman_plan.*) |*previous| smallHuffmanPlansEqual(previous, &plan) else false;
    var huffman_tree: std.ArrayList(u8) = .empty;
    defer huffman_tree.deinit(allocator);
    if (!reuse_previous_tree and !try emitSmallHuffmanTree(allocator, &huffman_tree, &plan)) return false;

    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(allocator);
    try emitHuffmanLiteralsSectionWithPlan(allocator, &payload, block, &plan, huffman_tree.items, reuse_previous_tree) orelse return false;
    try payload.append(allocator, 0); // sequence_count=0: this block is literals-only.

    if (payload.items.len >= block.len) return false;
    try emitBlockHeader(allocator, out, 2, payload.items.len, last);
    try out.appendSlice(allocator, payload.items);
    previous_huffman_plan.* = plan;
    return true;
}

const LiteralOnlyEncoderState = struct {
    previous_huffman_plan: ?SmallHuffmanLiteralPlan = null,
    sequence_state: SequenceEncoderState = .{},
    sequence_state_initialized: bool = false,
};

const SequenceEncoderState = struct {
    previous_tables: ?SequenceTables = null,
    repeated_offsets: [3]usize = initial_repeated_offsets,
};

fn ensureEncoderSequenceState(state: *LiteralOnlyEncoderState, dictionary: ?NativeDictionary) Error!void {
    if (state.sequence_state_initialized) return;
    const dictionary_state = try initialSequenceFrameState(dictionary);
    state.sequence_state = .{
        .previous_tables = dictionary_state.previous_tables,
        .repeated_offsets = dictionary_state.repeated_offsets,
    };
    state.sequence_state_initialized = true;
}

fn smallHuffmanPlansEqual(a: *const SmallHuffmanLiteralPlan, b: *const SmallHuffmanLiteralPlan) bool {
    if (a.len != b.len or a.max_symbol != b.max_symbol or a.max_bit_count != b.max_bit_count) return false;
    return std.mem.eql(u8, a.symbols[0..a.len], b.symbols[0..b.len]) and
        std.mem.eql(u4, a.weights[0..a.len], b.weights[0..b.len]);
}

fn smallHuffmanLiteralPlan(block: []const u8) ?SmallHuffmanLiteralPlan {
    if (block.len < 64 or block.len > 0x3ffff) return null;
    var frequencies: SmallHuffmanFrequencies = @splat(@splat(0));
    addBytesToSmallHuffmanFrequencies(&frequencies, block);
    var plan = smallHuffmanLiteralPlanFromFrequencies(&frequencies);
    finalizeSmallHuffmanLiteralPlan(&plan) orelse return null;
    return plan;
}

fn fillSmallHuffmanWeights(plan: *SmallHuffmanLiteralPlan) ?void {
    // Every production caller constructs a fresh zero-initialized plan. Keep
    // absent-symbol bit counts at that initialized zero and overwrite the
    // complete active weight prefix below instead of clearing both 256-entry
    // arrays again for every candidate tree.
    const lengths = if (plan.max_symbol < 64) blk: {
        var compact: [64]u32 = @splat(0);
        @memcpy(compact[0 .. @as(usize, plan.max_symbol) + 1], plan.frequencies[0 .. @as(usize, plan.max_symbol) + 1]);
        const compact_lengths = huffman.treeCodeLengths(64, &compact, 11);
        var expanded: [256]u4 = @splat(0);
        @memcpy(expanded[0..64], &compact_lengths);
        break :blk expanded;
    } else blk: {
        // Symbols are collected in ascending byte order. Reuse that list so
        // medium and dense alphabets do not rescan all 256 frequencies merely
        // to recover the active count before package merge.
        break :blk huffman.treeCodeLengthsKnownActive(
            256,
            &plan.frequencies,
            11,
            plan.symbols[0..plan.len],
        );
    };
    var max_bit_count: u4 = 0;
    for (plan.symbols[0..plan.len]) |symbol| {
        const bit_count = lengths[symbol];
        if (bit_count == 0) return null;
        plan.bit_counts[symbol] = bit_count;
        max_bit_count = @max(max_bit_count, bit_count);
    }
    plan.max_bit_count = max_bit_count;

    sortSmallHuffmanSymbolsByLength(plan.symbols[0..plan.len], &lengths, plan.max_bit_count);
    var prefix: usize = 0;
    var previous_weight = plan.max_bit_count + 1 - lengths[plan.symbols[0]];
    for (plan.symbols[0..plan.len], 0..) |symbol, i| {
        const weight = plan.max_bit_count + 1 - lengths[symbol];
        if (i != 0) {
            prefix += 1;
            if (weight != previous_weight) prefix = ((prefix - 1) >> @intCast(weight - previous_weight)) + 1;
        }
        plan.weights[i] = weight;
        plan.codes[symbol] = @intCast(prefix);
        previous_weight = weight;
    }
    validateSmallHuffmanLastWeight(plan) orelse return null;
}

fn smallHuffmanSymbolLess(lengths: *const [256]u4, lhs: u8, rhs: u8) bool {
    const lhs_bits = lengths[lhs];
    const rhs_bits = lengths[rhs];
    if (lhs_bits != rhs_bits) return lhs_bits > rhs_bits;
    return lhs < rhs;
}

fn sortSmallHuffmanSymbolsByLength(symbols: []u8, lengths: *const [256]u4, max_bit_count: u4) void {
    std.debug.assert(max_bit_count <= 11);
    var count_by_bits: [12]u16 = @splat(0);
    for (symbols) |symbol| {
        const bit_count = lengths[symbol];
        std.debug.assert(bit_count != 0 and bit_count <= max_bit_count);
        count_by_bits[bit_count] += 1;
    }

    var next_by_bits: [12]u16 = @splat(0);
    var next: u16 = 0;
    var bit_count: usize = max_bit_count;
    while (bit_count != 0) : (bit_count -= 1) {
        next_by_bits[bit_count] = next;
        next += count_by_bits[bit_count];
    }
    std.debug.assert(next == symbols.len);

    // Callers collect active symbols in ascending byte order. Stable bucket
    // insertion therefore preserves the symbol-order tie-break within each
    // descending code-length bucket without a comparison sort.
    var ordered: [256]u8 = undefined;
    for (symbols) |symbol| {
        const symbol_bits = lengths[symbol];
        ordered[next_by_bits[symbol_bits]] = symbol;
        next_by_bits[symbol_bits] += 1;
    }
    @memcpy(symbols, ordered[0..symbols.len]);
}

pub fn benchmarkSmallHuffmanSymbolBucketSort(symbols: []u8, lengths: *const [256]u4, max_bit_count: u4) void {
    sortSmallHuffmanSymbolsByLength(symbols, lengths, max_bit_count);
}

pub fn benchmarkSmallHuffmanSymbolComparisonSort(symbols: []u8, lengths: *const [256]u4) void {
    std.mem.sort(u8, symbols, lengths, smallHuffmanSymbolLess);
}

fn validateSmallHuffmanLastWeight(plan: *const SmallHuffmanLiteralPlan) ?void {
    if (plan.len < 2) return null;
    var weight_power_sum: usize = 0;
    for (plan.symbols[0..plan.len], plan.weights[0..plan.len]) |symbol, weight| {
        if (symbol == plan.max_symbol) continue;
        weight_power_sum += (@as(usize, 1) << @intCast(weight)) >> 1;
    }
    if (weight_power_sum == 0 or weight_power_sum >= (@as(usize, 1) << @intCast(plan.max_bit_count))) return null;
    const remaining = (@as(usize, 1) << @intCast(plan.max_bit_count)) - weight_power_sum;
    if (!std.math.isPowerOfTwo(remaining)) return null;
    const reconstructed: u4 = @intCast(std.math.log2_int(usize, remaining) + 1);
    const max_symbol_bits = plan.bit_counts[plan.max_symbol];
    if (max_symbol_bits == 0) return null;
    if (reconstructed != plan.max_bit_count + 1 - max_symbol_bits) return null;
}

fn emitSmallHuffmanTree(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: *const SmallHuffmanLiteralPlan) Error!bool {
    var direct: std.ArrayList(u8) = .empty;
    defer direct.deinit(allocator);
    if (plan.max_symbol <= native_max_direct_huffman_symbol) try emitDirectHuffmanTree(allocator, &direct, plan);

    var fse: std.ArrayList(u8) = .empty;
    defer fse.deinit(allocator);
    const fse_ok = try emitFseHuffmanTree(allocator, &fse, plan);
    if (direct.items.len == 0 and !fse_ok) return false;
    const selected = if (fse_ok and (direct.items.len == 0 or fse.items.len < direct.items.len)) fse.items else direct.items;
    try out.appendSlice(allocator, selected);
    return true;
}

fn smallHuffmanTreeSerializedLen(plan: *const SmallHuffmanLiteralPlan) Error!?usize {
    const direct_len: ?usize = if (plan.max_symbol <= native_max_direct_huffman_symbol)
        1 + ((@as(usize, plan.max_symbol) + 1) / 2)
    else
        null;
    const fse_len = try fseHuffmanTreeSerializedLen(plan);
    if (direct_len) |len| {
        if (fse_len) |candidate| return @min(len, candidate);
        return len;
    }
    return fse_len;
}

test "zstd Huffman tree size estimator matches selected wire" {
    const payloads = [_][]const u8{
        "ABCD" ** 64,
        "The quick brown fox jumps over the lazy dog.\n" ** 64,
        @embedFile("zstd.zig")[0..8192],
    };
    for (payloads) |payload| {
        const plan = smallHuffmanLiteralPlan(payload) orelse return error.CorruptFrame;
        var encoded: std.ArrayList(u8) = .empty;
        defer encoded.deinit(std.testing.allocator);
        try std.testing.expect(try emitSmallHuffmanTree(std.testing.allocator, &encoded, &plan));
        try std.testing.expectEqual(encoded.items.len, (try smallHuffmanTreeSerializedLen(&plan)) orelse return error.CorruptFrame);
    }
}

test "zstd reserved Huffman stream matches checked append reference" {
    var payload: [8192]u8 = undefined;
    for (&payload, 0..) |*byte, i| byte.* = @intCast((i * 37 + i / 11) % 193);
    for ([_]usize{ 64, 65, 66, 67, 1023, 1024, 1025, 1026, 1027, payload.len }) |len| {
        const plan = smallHuffmanLiteralPlan(payload[0..len]) orelse return error.CorruptFrame;
        var expected: std.ArrayList(u8) = .empty;
        defer expected.deinit(std.testing.allocator);
        try emitSmallHuffmanStreamCheckedAppendReference(std.testing.allocator, &expected, payload[0..len], &plan);
        var actual: std.ArrayList(u8) = .empty;
        defer actual.deinit(std.testing.allocator);
        try emitSmallHuffmanStream(std.testing.allocator, &actual, payload[0..len], &plan);
        try std.testing.expectEqualSlices(u8, expected.items, actual.items);
        if (len >= 1024) {
            var long_actual: std.ArrayList(u8) = .empty;
            defer long_actual.deinit(std.testing.allocator);
            try emitLongHuffmanStream(false, std.testing.allocator, &long_actual, payload[0..len], &plan);
            try std.testing.expectEqualSlices(u8, expected.items, long_actual.items);
            var known_active: std.ArrayList(u8) = .empty;
            defer known_active.deinit(std.testing.allocator);
            try emitLongHuffmanStream(true, std.testing.allocator, &known_active, payload[0..len], &plan);
            try std.testing.expectEqualSlices(u8, expected.items, known_active.items);
        }

        if (plan.bit_counts[255] == 0) {
            var invalid: std.ArrayList(u8) = .empty;
            defer invalid.deinit(std.testing.allocator);
            try std.testing.expectError(
                error.CorruptFrame,
                emitSmallHuffmanStream(std.testing.allocator, &invalid, &.{255}, &plan),
            );
            try std.testing.expectEqual(@as(usize, 0), invalid.items.len);
        }
    }

    var max_width_plan: SmallHuffmanLiteralPlan = .{};
    max_width_plan.symbols[0] = 0;
    max_width_plan.bit_counts[0] = 11;
    max_width_plan.codes[0] = (1 << 11) - 1;
    max_width_plan.len = 1;
    max_width_plan.max_bit_count = 11;
    const max_width_payload: [1027]u8 = @splat(0);
    var max_width_expected: std.ArrayList(u8) = .empty;
    defer max_width_expected.deinit(std.testing.allocator);
    try emitSmallHuffmanStreamCheckedAppendReference(std.testing.allocator, &max_width_expected, &max_width_payload, &max_width_plan);
    var max_width_actual: std.ArrayList(u8) = .empty;
    defer max_width_actual.deinit(std.testing.allocator);
    try emitSmallHuffmanStream(std.testing.allocator, &max_width_actual, &max_width_payload, &max_width_plan);
    try std.testing.expectEqualSlices(u8, max_width_expected.items, max_width_actual.items);

    const plan = smallHuffmanLiteralPlan(&payload) orelse return error.CorruptFrame;
    var prefixed: std.ArrayList(u8) = .empty;
    defer prefixed.deinit(std.testing.allocator);
    try prefixed.appendSlice(std.testing.allocator, "prefix");
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    try std.testing.expectError(error.OutOfMemory, emitSmallHuffmanStream(failing.allocator(), &prefixed, &payload, &plan));
    try std.testing.expectEqualSlices(u8, "prefix", prefixed.items);
}

fn fseHuffmanTreeSerializedLen(plan: *const SmallHuffmanLiteralPlan) Error!?usize {
    var weights: [255]u8 = undefined;
    const weight_count: usize = plan.max_symbol;
    for (weights[0..weight_count], 0..) |*weight, symbol|
        weight.* = smallHuffmanExplicitWeight(plan, @intCast(symbol));

    var best: ?usize = null;
    for (huffman_weight_fse_table_logs) |table_log| {
        const len = try fseCompressedHuffmanWeightsSerializedLen(weights[0..weight_count], table_log) orelse continue;
        if (best == null or len < best.?) best = len;
    }
    const compressed_len = best orelse return null;
    if (compressed_len > 127) return null;
    return 1 + compressed_len;
}

fn emitDirectHuffmanTree(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: *const SmallHuffmanLiteralPlan) Error!void {
    if (plan.max_symbol > native_max_direct_huffman_symbol) return error.CorruptFrame;
    try out.append(allocator, 127 + plan.max_symbol);
    const weights_byte_count: usize = (@as(usize, plan.max_symbol) + 1) / 2;
    for (0..weights_byte_count) |i| {
        const even_symbol: u8 = @intCast(i * 2);
        const odd_symbol: u8 = @intCast(i * 2 + 1);
        const even_weight: u8 = smallHuffmanExplicitWeight(plan, even_symbol);
        const odd_weight: u8 = smallHuffmanExplicitWeight(plan, odd_symbol);
        try out.append(allocator, (even_weight << 4) | odd_weight);
    }
}

fn emitHuffmanLiteralsSectionWithPlan(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    literals: []const u8,
    plan: *const SmallHuffmanLiteralPlan,
    huffman_tree: []const u8,
    reuse_previous_tree: bool,
) Error!?void {
    if (literals.len <= 1023) {
        var stream: std.ArrayList(u8) = .empty;
        defer stream.deinit(allocator);
        try emitSmallHuffmanStreamKnownActive(allocator, &stream, literals, plan);
        const compressed_size = huffman_tree.len + stream.items.len;
        try emitHuffmanLiteralsHeader(allocator, out, literals.len, compressed_size, reuse_previous_tree) orelse return null;
        try out.appendSlice(allocator, huffman_tree);
        try out.appendSlice(allocator, stream.items);
    } else {
        var streams: [4]std.ArrayList(u8) = .{ .empty, .empty, .empty, .empty };
        defer for (&streams) |*stream| stream.deinit(allocator);
        // Zstandard four-stream literals split regenerated output with the first
        // three streams covering ceil(size / 4) bytes and the fourth stream
        // covering the remainder. Matching that layout lets the decoder switch
        // streams exactly when each reverse bitstream reaches its end mark,
        // including for non-4-divisible literal counts.
        const segment_len = (literals.len + 3) / 4;
        const segment_1_end = segment_len;
        const segment_2_end = segment_len * 2;
        const segment_3_end = segment_len * 3;
        const segments = [_][]const u8{
            literals[0..segment_1_end],
            literals[segment_1_end..segment_2_end],
            literals[segment_2_end..segment_3_end],
            literals[segment_3_end..],
        };
        for (&streams, segments) |*stream, segment| try emitSmallHuffmanStreamKnownActive(allocator, stream, segment, plan);
        const compressed_size = huffman_tree.len + 6 +
            streams[0].items.len + streams[1].items.len + streams[2].items.len + streams[3].items.len;
        if (streams[0].items.len > std.math.maxInt(u16) or
            streams[1].items.len > std.math.maxInt(u16) or
            streams[2].items.len > std.math.maxInt(u16)) return null;
        try emitHuffmanLiteralsHeader(allocator, out, literals.len, compressed_size, reuse_previous_tree) orelse return null;
        try out.appendSlice(allocator, huffman_tree);
        var stream_lengths: [6]u8 = undefined;
        std.mem.writeInt(u16, stream_lengths[0..2], @intCast(streams[0].items.len), .little);
        std.mem.writeInt(u16, stream_lengths[2..4], @intCast(streams[1].items.len), .little);
        std.mem.writeInt(u16, stream_lengths[4..6], @intCast(streams[2].items.len), .little);
        try out.appendSlice(allocator, &stream_lengths);
        for (&streams) |*stream| try out.appendSlice(allocator, stream.items);
    }
}

const huffman_weight_fse_table_logs = [_]u8{ 5, 6 };
const huffman_weight_symbol_max = 15;
const max_fse_compression_table_log = 9;
const max_fse_compression_table_size = 1 << max_fse_compression_table_log;
const max_fse_compression_symbol = 63;

const FseCompressionTransform = large_transition.Transform;

const FseCompressionTable = struct {
    state_table: [max_fse_compression_table_size]u16 = undefined,
    transforms: [max_fse_compression_symbol + 1]FseCompressionTransform =
        [_]FseCompressionTransform{.{}} ** (max_fse_compression_symbol + 1),
    table_log: u8 = 0,
    table_len: usize = 0,
    max_symbol: u8 = 0,
};

const ReverseBitstreamWriter = struct {
    accumulator: usize = 0,
    bit_count: u6 = 0,

    fn addBits(self: *ReverseBitstreamWriter, allocator: std.mem.Allocator, out: *std.ArrayList(u8), value: usize, bits: u8) Error!void {
        if (bits == 0) return;
        if (bits > @bitSizeOf(usize)) return error.CorruptFrame;
        const mask = (@as(usize, 1) << @intCast(bits)) - 1;
        self.accumulator |= (value & mask) << self.bit_count;
        self.bit_count += @intCast(bits);
        while (self.bit_count >= 8) {
            try out.append(allocator, @truncate(self.accumulator));
            self.accumulator >>= 8;
            self.bit_count -= 8;
        }
    }

    fn finish(self: *ReverseBitstreamWriter, allocator: std.mem.Allocator, out: *std.ArrayList(u8)) Error!void {
        self.accumulator |= @as(usize, 1) << self.bit_count;
        self.bit_count += 1;
        while (self.bit_count > 0) {
            try out.append(allocator, @truncate(self.accumulator));
            if (self.bit_count <= 8) break;
            self.accumulator >>= 8;
            self.bit_count -= 8;
        }
        self.* = .{};
    }
};

fn addCheckedReverseBits(
    writer: *ReverseBitstreamWriter,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    value: usize,
    bits: u8,
) Error!void {
    if (bits > @bitSizeOf(usize)) return error.CorruptFrame;
    if (bits == 0) {
        if (value != 0) return error.CorruptFrame;
    } else if (value >= (@as(usize, 1) << @intCast(bits))) return error.CorruptFrame;
    try writer.addBits(allocator, out, value, bits);
}

fn emitFseHuffmanTree(allocator: std.mem.Allocator, out: *std.ArrayList(u8), plan: *const SmallHuffmanLiteralPlan) Error!bool {
    var weights: [255]u8 = undefined;
    // Zstandard does not serialize the final Huffman weight. The decoder
    // reconstructs it from the power sum so that the complete tree exactly
    // fills the next power-of-two prefix space; keeping the highest symbol as
    // that reconstructed entry mirrors the direct-header path above.
    const weight_count: usize = plan.max_symbol;
    for (weights[0..weight_count], 0..) |*weight, symbol| {
        weight.* = smallHuffmanExplicitWeight(plan, @intCast(symbol));
    }

    var compressed: std.ArrayList(u8) = .empty;
    defer compressed.deinit(allocator);
    var candidate: std.ArrayList(u8) = .empty;
    defer candidate.deinit(allocator);
    for (huffman_weight_fse_table_logs) |table_log| {
        candidate.clearRetainingCapacity();
        if (!try emitFseCompressedHuffmanWeightsWithTableLog(allocator, &candidate, weights[0..weight_count], table_log)) continue;
        if (compressed.items.len == 0 or candidate.items.len < compressed.items.len) {
            compressed.clearRetainingCapacity();
            try compressed.appendSlice(allocator, candidate.items);
        }
    }
    if (compressed.items.len == 0 or compressed.items.len > 127) return false;

    try out.append(allocator, @intCast(compressed.items.len));
    try out.appendSlice(allocator, compressed.items);
    return true;
}

fn emitFseCompressedHuffmanWeights(allocator: std.mem.Allocator, out: *std.ArrayList(u8), weights: []const u8) Error!bool {
    return try emitFseCompressedHuffmanWeightsWithTableLog(allocator, out, weights, huffman_weight_fse_table_logs[huffman_weight_fse_table_logs.len - 1]);
}

fn emitFseCompressedHuffmanWeightsWithTableLog(allocator: std.mem.Allocator, out: *std.ArrayList(u8), weights: []const u8, table_log: u8) Error!bool {
    if (weights.len <= 2) return false;

    var counts: [huffman_weight_symbol_max + 1]u32 = .{0} ** (huffman_weight_symbol_max + 1);
    var max_symbol: u8 = 0;
    for (weights) |weight| {
        if (weight > huffman_weight_symbol_max) return error.CorruptFrame;
        counts[weight] += 1;
        max_symbol = @max(max_symbol, weight);
    }

    var max_count: u32 = 0;
    for (counts[0 .. @as(usize, max_symbol) + 1]) |count| max_count = @max(max_count, count);
    // Match zstd's Huffman-table writer behavior: all-one-symbol and
    // all-unique weight streams are not useful FSE payloads. For high-byte
    // direct-tree overflow we prefer a safe raw-block fallback over emitting a
    // malformed or non-beneficial Huffman tree.
    if (max_count == weights.len or max_count == 1) return false;

    var normalized: [huffman_weight_symbol_max + 1]i16 = .{0} ** (huffman_weight_symbol_max + 1);
    normalizeFseCounts(
        counts[0 .. @as(usize, max_symbol) + 1],
        weights.len,
        table_log,
        normalized[0 .. @as(usize, max_symbol) + 1],
    ) orelse return false;

    try emitFseNormalizedCount(
        allocator,
        out,
        normalized[0 .. @as(usize, max_symbol) + 1],
        max_symbol,
        table_log,
    );

    var table: FseCompressionTable = undefined;
    try buildFseCompressionTable(
        &table,
        normalized[0 .. @as(usize, max_symbol) + 1],
        max_symbol,
        table_log,
    );
    const bitstream_start = out.items.len;
    try emitFseCompressedSymbols(allocator, out, weights, &table);
    return out.items.len > bitstream_start;
}

fn fseCompressedHuffmanWeightsSerializedLen(weights: []const u8, table_log: u8) Error!?usize {
    if (weights.len <= 2) return null;

    var counts: [huffman_weight_symbol_max + 1]u32 = .{0} ** (huffman_weight_symbol_max + 1);
    var max_symbol: u8 = 0;
    for (weights) |weight| {
        if (weight > huffman_weight_symbol_max) return error.CorruptFrame;
        counts[weight] += 1;
        max_symbol = @max(max_symbol, weight);
    }
    var max_count: u32 = 0;
    for (counts[0 .. @as(usize, max_symbol) + 1]) |count| max_count = @max(max_count, count);
    if (max_count == weights.len or max_count == 1) return null;

    var normalized: [huffman_weight_symbol_max + 1]i16 = .{0} ** (huffman_weight_symbol_max + 1);
    normalizeFseCounts(
        counts[0 .. @as(usize, max_symbol) + 1],
        weights.len,
        table_log,
        normalized[0 .. @as(usize, max_symbol) + 1],
    ) orelse return null;
    const header_len = try fseNormalizedCountSerializedLen(
        normalized[0 .. @as(usize, max_symbol) + 1],
        max_symbol,
        table_log,
    );
    var table: FseCompressionTable = undefined;
    try buildFseCompressionTable(&table, normalized[0 .. @as(usize, max_symbol) + 1], max_symbol, table_log);
    return std.math.add(usize, header_len, try fseCompressedSymbolsSerializedLen(weights, &table)) catch return error.IntegerOverflow;
}

fn fseCompressedSymbolsSerializedLen(symbols: []const u8, table: *const FseCompressionTable) Error!usize {
    if (symbols.len <= 2) return error.CorruptFrame;
    var index = symbols.len;
    var state_1: usize = undefined;
    var state_2: usize = undefined;
    var bit_count: usize = 1; // Reverse bitstream end marker.

    if ((symbols.len & 1) != 0) {
        index -= 1;
        state_1 = try fseInitialState(table, symbols[index]);
        index -= 1;
        state_2 = try fseInitialState(table, symbols[index]);
        index -= 1;
        bit_count += try fseEncodedSymbolBitCount(table, &state_1, symbols[index]);
    } else {
        index -= 1;
        state_2 = try fseInitialState(table, symbols[index]);
        index -= 1;
        state_1 = try fseInitialState(table, symbols[index]);
    }

    var remaining = symbols.len - 2;
    if ((symbols.len & 1) != 0) remaining -= 1;
    if ((remaining & 2) != 0) {
        index -= 1;
        bit_count += try fseEncodedSymbolBitCount(table, &state_2, symbols[index]);
        index -= 1;
        bit_count += try fseEncodedSymbolBitCount(table, &state_1, symbols[index]);
    }
    while (index > 0) {
        index -= 1;
        bit_count += try fseEncodedSymbolBitCount(table, &state_2, symbols[index]);
        index -= 1;
        bit_count += try fseEncodedSymbolBitCount(table, &state_1, symbols[index]);
        if (index > 0) {
            index -= 1;
            bit_count += try fseEncodedSymbolBitCount(table, &state_2, symbols[index]);
            index -= 1;
            bit_count += try fseEncodedSymbolBitCount(table, &state_1, symbols[index]);
        }
    }
    bit_count += @as(usize, table.table_log) * 2;
    return (bit_count + 7) / 8;
}

fn fseEncodedSymbolBitCount(table: *const FseCompressionTable, state: *usize, symbol: u8) Error!usize {
    if (symbol > table.max_symbol) return error.CorruptFrame;
    const transform = table.transforms[symbol];
    const bits: usize = @intCast((@as(i32, @intCast(state.*)) + transform.delta_nb_bits) >> 16);
    state.* = try fseNextState(table, state.* >> @intCast(bits), 0, transform.delta_find_state);
    return bits;
}

fn normalizeFseCounts(counts: []const u32, total: usize, table_log: u8, normalized: []i16) ?void {
    if (counts.len != normalized.len or total == 0) return null;
    const table_size: i32 = @as(i32, 1) << @intCast(table_log);
    const scale: u6 = @intCast(62 - table_log);
    const step = (@as(u64, 1) << 62) / total;
    const rounding_thresholds = [_]u32{ 0, 473_195, 504_333, 520_860, 550_000, 700_000, 750_000, 830_000 };
    const rounding_step = @as(u64, 1) << @intCast(scale - 20);
    const low_threshold = total >> @intCast(table_log);
    var remaining = table_size;
    var largest: usize = 0;
    var largest_probability: i16 = 0;
    var non_zero_count: usize = 0;
    for (counts, 0..) |count, symbol| {
        if (count == 0) {
            normalized[symbol] = 0;
            continue;
        }
        non_zero_count += 1;
        if (count <= low_threshold) {
            normalized[symbol] = -1;
            remaining -= 1;
            continue;
        }
        const scaled = @as(u64, count) * step;
        var probability: i16 = @intCast(scaled >> scale);
        if (probability < rounding_thresholds.len) {
            const remainder = scaled - (@as(u64, @intCast(probability)) << scale);
            if (remainder > rounding_step * rounding_thresholds[@intCast(probability)]) probability += 1;
        }
        if (probability <= 0) return null;
        normalized[symbol] = probability;
        remaining -= probability;
        if (probability > largest_probability) {
            largest = symbol;
            largest_probability = probability;
        }
    }
    if (non_zero_count == 0 or non_zero_count > @as(usize, @intCast(table_size))) return null;
    if (-remaining >= @divTrunc(largest_probability, 2)) return normalizeFseCountsSecondary(counts, total, table_log, normalized);
    normalized[largest] += @intCast(remaining);
    if (normalized[largest] <= 0) return null;
}

fn normalizeFseCountsSimple(counts: []const u32, total: usize, table_log: u8, normalized: []i16) ?void {
    if (counts.len != normalized.len or total == 0) return null;
    const table_size: i32 = @as(i32, 1) << @intCast(table_log);
    var sum: i32 = 0;
    var largest: usize = 0;
    var largest_count: u32 = 0;
    var non_zero_count: usize = 0;
    for (counts, 0..) |count, symbol| {
        if (count == 0) {
            normalized[symbol] = 0;
            continue;
        }
        non_zero_count += 1;
        if (count > largest_count) {
            largest = symbol;
            largest_count = count;
        }
        const scaled = (@as(u64, count) * @as(u64, @intCast(table_size))) / total;
        const value: i16 = @intCast(@max(@as(u64, 1), scaled));
        normalized[symbol] = value;
        sum += value;
    }
    if (non_zero_count == 0 or non_zero_count > @as(usize, @intCast(table_size))) return null;
    var diff = table_size - sum;
    if (diff > 0) {
        normalized[largest] += @intCast(diff);
    } else while (diff < 0) {
        var reduce: ?usize = null;
        for (normalized, 0..) |value, symbol| {
            if (value <= 1) continue;
            if (reduce == null or value > normalized[reduce.?]) reduce = symbol;
        }
        const symbol = reduce orelse return null;
        normalized[symbol] -= 1;
        diff += 1;
    }
}

fn normalizeFseCountsSecondary(counts: []const u32, total_input: usize, table_log: u8, normalized: []i16) ?void {
    const not_assigned: i16 = -2;
    var total = total_input;
    const table_size: usize = @as(usize, 1) << @intCast(table_log);
    const low_threshold = total >> @intCast(table_log);
    var low_one = (total * 3) >> @intCast(table_log + 1);
    var distributed: usize = 0;
    for (counts, 0..) |count, symbol| {
        if (count == 0) normalized[symbol] = 0 else if (count <= low_threshold) {
            normalized[symbol] = -1;
            distributed += 1;
            total -= count;
        } else if (count <= low_one) {
            normalized[symbol] = 1;
            distributed += 1;
            total -= count;
        } else normalized[symbol] = not_assigned;
    }
    var to_distribute = table_size - distributed;
    if (to_distribute == 0) return;
    if (total / to_distribute > low_one) {
        low_one = (total * 3) / (to_distribute * 2);
        for (counts, 0..) |count, symbol| {
            if (normalized[symbol] == not_assigned and count <= low_one) {
                normalized[symbol] = 1;
                distributed += 1;
                total -= count;
            }
        }
        to_distribute = table_size - distributed;
    }
    if (total == 0) {
        var symbol: usize = 0;
        while (to_distribute != 0) : (symbol = (symbol + 1) % normalized.len) {
            if (normalized[symbol] > 0) {
                normalized[symbol] += 1;
                to_distribute -= 1;
            }
        }
        return;
    }
    const step_log: u6 = @intCast(62 - table_log);
    const midpoint = (@as(u64, 1) << @intCast(step_log - 1)) - 1;
    const step = (((@as(u64, 1) << step_log) * to_distribute) + midpoint) / total;
    var cumulative = midpoint;
    for (counts, 0..) |count, symbol| {
        if (normalized[symbol] != not_assigned) continue;
        const next = cumulative + @as(u64, count) * step;
        const weight = (next >> step_log) - (cumulative >> step_log);
        if (weight == 0) return null;
        normalized[symbol] = @intCast(weight);
        cumulative = next;
    }
}

fn emitFseNormalizedCount(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!void {
    if (table_log < 5 or table_log > max_fse_compression_table_log) return error.CorruptFrame;
    if (normalized.len != @as(usize, max_symbol) + 1) return error.CorruptFrame;

    // FSE normalized-count headers are a small forward bitstream. This mirrors
    // the zstd wire transform (`count + 1`, threshold-dependent bit width, and
    // compact zero-run coding) so Zig's std decoder can reuse its existing
    // Table.decode path without a Vort-specific side channel.
    var bit_stream: u64 = @as(u64, table_log - 5);
    var bit_count: u8 = 4;
    var remaining: i32 = (@as(i32, 1) << @intCast(table_log)) + 1;
    var threshold: i32 = @as(i32, 1) << @intCast(table_log);
    var nb_bits: u8 = table_log + 1;
    var symbol: usize = 0;
    var previous_is_zero = false;

    while (symbol < normalized.len and remaining > 1) {
        if (previous_is_zero) {
            const start = symbol;
            while (symbol < normalized.len and normalized[symbol] == 0) : (symbol += 1) {}
            if (symbol == normalized.len) return error.CorruptFrame;
            var run_start = start;
            while (symbol >= run_start + 24) {
                run_start += 24;
                bit_stream += @as(u64, 0xffff) << @intCast(bit_count);
                bit_count += 16;
                try flushFseNormalizedCountBits(allocator, out, &bit_stream, &bit_count);
            }
            while (symbol >= run_start + 3) {
                run_start += 3;
                bit_stream += @as(u64, 3) << @intCast(bit_count);
                bit_count += 2;
            }
            bit_stream += @as(u64, @intCast(symbol - run_start)) << @intCast(bit_count);
            bit_count += 2;
            if (bit_count > 16) try flushFseNormalizedCountBits(allocator, out, &bit_stream, &bit_count);
        }

        var count: i32 = normalized[symbol];
        symbol += 1;
        const max = (2 * threshold - 1) - remaining;
        remaining -= @intCast(@abs(count));
        count += 1;
        if (count >= threshold) count += max;
        if (count < 0) return error.CorruptFrame;
        bit_stream += @as(u64, @intCast(count)) << @intCast(bit_count);
        bit_count += nb_bits;
        if (count < max) bit_count -= 1;
        previous_is_zero = count == 1;
        if (remaining < 1) return error.CorruptFrame;
        while (remaining < threshold) {
            nb_bits -= 1;
            threshold >>= 1;
        }
        if (bit_count > 16) try flushFseNormalizedCountBits(allocator, out, &bit_stream, &bit_count);
    }

    if (remaining != 1) return error.CorruptFrame;
    const byte_count = (@as(usize, bit_count) + 7) / 8;
    for (0..byte_count) |_| {
        try out.append(allocator, @truncate(bit_stream));
        bit_stream >>= 8;
    }
}

fn emitFseNormalizedCountFixed(
    out: []u8,
    written: *usize,
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!void {
    try encodeFseNormalizedCountFixed(true, out, written, normalized, max_symbol, table_log);
}

fn fseNormalizedCountSerializedLen(
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!usize {
    var empty: [0]u8 = .{};
    var written: usize = 0;
    try encodeFseNormalizedCountFixed(false, &empty, &written, normalized, max_symbol, table_log);
    return written;
}

pub fn benchmarkFseNormalizedCountSerializedLen(
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!usize {
    return try fseNormalizedCountSerializedLen(normalized, max_symbol, table_log);
}

pub fn benchmarkEmitFseNormalizedCountFixed(
    out: []u8,
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!usize {
    var written: usize = 0;
    try emitFseNormalizedCountFixed(out, &written, normalized, max_symbol, table_log);
    return written;
}

fn encodeFseNormalizedCountFixed(
    comptime emit_bytes: bool,
    out: []u8,
    written: *usize,
    normalized: []const i16,
    max_symbol: u8,
    table_log: u8,
) Error!void {
    if (table_log < 5 or table_log > max_fse_compression_table_log) return error.CorruptFrame;
    if (normalized.len != @as(usize, max_symbol) + 1) return error.CorruptFrame;
    written.* = 0;

    var bit_stream: u64 = @as(u64, table_log - 5);
    var bit_count: u8 = 4;
    var remaining: i32 = (@as(i32, 1) << @intCast(table_log)) + 1;
    var threshold: i32 = @as(i32, 1) << @intCast(table_log);
    var nb_bits: u8 = table_log + 1;
    var symbol: usize = 0;
    var previous_is_zero = false;

    while (symbol < normalized.len and remaining > 1) {
        if (previous_is_zero) {
            const start = symbol;
            while (symbol < normalized.len and normalized[symbol] == 0) : (symbol += 1) {}
            if (symbol == normalized.len) return error.CorruptFrame;
            var run_start = start;
            while (symbol >= run_start + 24) {
                run_start += 24;
                bit_stream += @as(u64, 0xffff) << @intCast(bit_count);
                bit_count += 16;
                try flushFseNormalizedCountBitsFixed(emit_bytes, out, written, &bit_stream, &bit_count);
            }
            while (symbol >= run_start + 3) {
                run_start += 3;
                bit_stream += @as(u64, 3) << @intCast(bit_count);
                bit_count += 2;
            }
            bit_stream += @as(u64, @intCast(symbol - run_start)) << @intCast(bit_count);
            bit_count += 2;
            if (bit_count > 16) try flushFseNormalizedCountBitsFixed(emit_bytes, out, written, &bit_stream, &bit_count);
        }

        var count: i32 = normalized[symbol];
        symbol += 1;
        const max = (2 * threshold - 1) - remaining;
        remaining -= @intCast(@abs(count));
        count += 1;
        if (count >= threshold) count += max;
        if (count < 0) return error.CorruptFrame;
        bit_stream += @as(u64, @intCast(count)) << @intCast(bit_count);
        bit_count += nb_bits;
        if (count < max) bit_count -= 1;
        previous_is_zero = count == 1;
        if (remaining < 1) return error.CorruptFrame;
        while (remaining < threshold) {
            nb_bits -= 1;
            threshold >>= 1;
        }
        if (bit_count > 16) try flushFseNormalizedCountBitsFixed(emit_bytes, out, written, &bit_stream, &bit_count);
    }

    if (remaining != 1) return error.CorruptFrame;
    const byte_count = (@as(usize, bit_count) + 7) / 8;
    if (comptime emit_bytes) {
        for (0..byte_count) |_| {
            if (written.* >= out.len) return error.OutputTooSmall;
            out[written.*] = @truncate(bit_stream);
            written.* += 1;
            bit_stream >>= 8;
        }
    } else {
        written.* += byte_count;
    }
}

fn flushFseNormalizedCountBits(allocator: std.mem.Allocator, out: *std.ArrayList(u8), bit_stream: *u64, bit_count: *u8) Error!void {
    try out.append(allocator, @truncate(bit_stream.*));
    try out.append(allocator, @truncate(bit_stream.* >> 8));
    bit_stream.* >>= 16;
    bit_count.* -= 16;
}

fn flushFseNormalizedCountBitsFixed(comptime emit_bytes: bool, out: []u8, written: *usize, bit_stream: *u64, bit_count: *u8) Error!void {
    if (comptime emit_bytes) {
        if (out.len - written.* < 2) return error.OutputTooSmall;
        out[written.*] = @truncate(bit_stream.*);
        out[written.* + 1] = @truncate(bit_stream.* >> 8);
    }
    written.* += 2;
    bit_stream.* >>= 16;
    bit_count.* -= 16;
}

fn buildFseCompressionTable(table: *FseCompressionTable, normalized: []const i16, max_symbol: u8, table_log: u8) Error!void {
    if (normalized.len != @as(usize, max_symbol) + 1) return error.CorruptFrame;
    if (table_log > max_fse_compression_table_log or max_symbol > max_fse_compression_symbol) return error.CorruptFrame;
    const table_size: usize = @as(usize, 1) << @intCast(table_log);
    const table_mask = table_size - 1;
    const step = (table_size >> 1) + (table_size >> 3) + 3;

    table.table_log = table_log;
    table.table_len = table_size;
    table.max_symbol = max_symbol;
    var table_symbols: [max_fse_compression_table_size]u8 = undefined;
    var high_threshold: usize = table_size - 1;

    // The compressor table is the inverse of the decode table built earlier in
    // this file: spread symbols with the same step, sort each symbol's states
    // into `state_table`, then derive transforms that decide how many low bits
    // of the current state are emitted before moving to the next state.
    var cumul: [max_fse_compression_symbol + 2]u16 = .{0} ** (max_fse_compression_symbol + 2);
    for (normalized, 0..) |value, i| {
        if (value < -1) return error.CorruptFrame;
        if (value == -1) {
            cumul[i + 1] = cumul[i] + 1;
            table_symbols[high_threshold] = @intCast(i);
            high_threshold -= 1;
        } else {
            cumul[i + 1] = cumul[i] + @as(u16, @intCast(value));
        }
    }

    var position: usize = 0;
    for (normalized, 0..) |value, symbol| {
        if (value <= 0) continue;
        for (0..@as(usize, @intCast(value))) |_| {
            table_symbols[position] = @intCast(symbol);
            position = (position + step) & table_mask;
            while (position > high_threshold) {
                position = (position + step) & table_mask;
            }
        }
    }
    if (position != 0) return error.CorruptFrame;

    var next = cumul;
    for (table_symbols[0..table_size], 0..) |symbol, state| {
        const index = next[symbol];
        if (index >= table_size) return error.CorruptFrame;
        table.state_table[index] = @intCast(table_size + state);
        next[symbol] += 1;
    }

    var total: i32 = 0;
    for (normalized, 0..) |value, symbol| {
        const transform = &table.transforms[symbol];
        switch (value) {
            0 => {
                transform.delta_find_state = 0;
                transform.delta_nb_bits = ((@as(i32, table_log) + 1) << 16) - @as(i32, @intCast(table_size));
            },
            -1, 1 => {
                transform.delta_nb_bits = (@as(i32, table_log) << 16) - @as(i32, @intCast(table_size));
                transform.delta_find_state = total - 1;
                total += 1;
            },
            else => {
                const probability: u32 = @intCast(value);
                const max_bits_out: i32 = @as(i32, table_log) - @as(i32, @intCast(std.math.log2_int(u32, probability - 1)));
                const min_state_plus: i32 = @as(i32, @intCast(probability)) << @intCast(max_bits_out);
                transform.delta_nb_bits = (max_bits_out << 16) - min_state_plus;
                transform.delta_find_state = total - @as(i32, @intCast(probability));
                total += @intCast(probability);
            },
        }
    }
    if (total != table_size) return error.CorruptFrame;
}

fn buildFseCompressionTableReference(normalized: []const i16, max_symbol: u8, table_log: u8) Error!FseCompressionTable {
    var table: FseCompressionTable = .{};
    try buildFseCompressionTable(&table, normalized, max_symbol, table_log);
    return table;
}

fn emitFseCompressedSymbols(allocator: std.mem.Allocator, out: *std.ArrayList(u8), symbols: []const u8, table: *const FseCompressionTable) Error!void {
    if (symbols.len <= 2) return error.CorruptFrame;
    var writer: ReverseBitstreamWriter = .{};
    var index = symbols.len;
    var state_1: usize = undefined;
    var state_2: usize = undefined;

    // FSE stores two interleaved states in reverse source order. The last one or
    // two symbols seed the states for free; earlier symbols emit low state bits,
    // and the final two states are flushed into the reverse bitstream so the
    // decoder can recover them before replaying symbols forward.
    if ((symbols.len & 1) != 0) {
        index -= 1;
        state_1 = try fseInitialState(table, symbols[index]);
        index -= 1;
        state_2 = try fseInitialState(table, symbols[index]);
        index -= 1;
        try fseEncodeSymbol(allocator, out, &writer, table, &state_1, symbols[index]);
    } else {
        index -= 1;
        state_2 = try fseInitialState(table, symbols[index]);
        index -= 1;
        state_1 = try fseInitialState(table, symbols[index]);
    }

    var remaining = symbols.len - 2;
    if ((symbols.len & 1) != 0) remaining -= 1;
    if ((remaining & 2) != 0) {
        index -= 1;
        try fseEncodeSymbol(allocator, out, &writer, table, &state_2, symbols[index]);
        index -= 1;
        try fseEncodeSymbol(allocator, out, &writer, table, &state_1, symbols[index]);
        remaining -= 2;
    }

    while (index > 0) {
        index -= 1;
        try fseEncodeSymbol(allocator, out, &writer, table, &state_2, symbols[index]);
        index -= 1;
        try fseEncodeSymbol(allocator, out, &writer, table, &state_1, symbols[index]);
        if (index > 0) {
            index -= 1;
            try fseEncodeSymbol(allocator, out, &writer, table, &state_2, symbols[index]);
            index -= 1;
            try fseEncodeSymbol(allocator, out, &writer, table, &state_1, symbols[index]);
        }
    }

    try writer.addBits(allocator, out, state_2, table.table_log);
    try writer.addBits(allocator, out, state_1, table.table_log);
    try writer.finish(allocator, out);
}

fn fseInitialState(table: *const FseCompressionTable, symbol: u8) Error!usize {
    if (symbol > table.max_symbol) return error.CorruptFrame;
    const transform = table.transforms[symbol];
    const nb_bits_out: usize = @intCast(@divTrunc(transform.delta_nb_bits + (1 << 15), 1 << 16));
    const value: usize = @intCast((@as(i32, @intCast(nb_bits_out)) << 16) - transform.delta_nb_bits);
    return try fseNextState(table, value, nb_bits_out, transform.delta_find_state);
}

fn fseEncodeSymbol(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    writer: *ReverseBitstreamWriter,
    table: *const FseCompressionTable,
    state: *usize,
    symbol: u8,
) Error!void {
    if (symbol > table.max_symbol) return error.CorruptFrame;
    const transform = table.transforms[symbol];
    const nb_bits_out: usize = @intCast((@as(i32, @intCast(state.*)) + transform.delta_nb_bits) >> 16);
    try writer.addBits(allocator, out, state.*, @intCast(nb_bits_out));
    state.* = try fseNextState(table, state.* >> @intCast(nb_bits_out), 0, transform.delta_find_state);
}

fn fseNextState(table: *const FseCompressionTable, value: usize, shift_bits: usize, delta_find_state: i32) Error!usize {
    const shifted = value >> @intCast(shift_bits);
    const signed_index = @as(i32, @intCast(shifted)) + delta_find_state;
    if (signed_index < 0) return error.CorruptFrame;
    const index: usize = @intCast(signed_index);
    if (index >= table.table_len) return error.CorruptFrame;
    return table.state_table[index];
}

fn smallHuffmanExplicitWeight(plan: *const SmallHuffmanLiteralPlan, symbol: u8) u4 {
    if (symbol == plan.max_symbol) return 0;
    const bit_count = plan.bit_counts[symbol];
    if (bit_count == 0) return 0;
    return @intCast(plan.max_bit_count + 1 - bit_count);
}

fn smallHuffmanSymbolIndex(plan: *const SmallHuffmanLiteralPlan, symbol: u8) ?usize {
    for (plan.symbols[0..plan.len], 0..) |candidate, i| {
        if (candidate == symbol) return i;
    }
    return null;
}

fn smallHuffmanCode(plan: *const SmallHuffmanLiteralPlan, symbol: u8) ?usize {
    const index = smallHuffmanSymbolIndex(plan, symbol) orelse return null;
    var prefix: usize = 0;
    var previous_weight = plan.weights[0];
    for (0..index) |i| {
        const next_weight = plan.weights[i + 1];
        prefix += 1;
        if (next_weight != previous_weight) {
            prefix = ((prefix - 1) >> @intCast(next_weight - previous_weight)) + 1;
            previous_weight = next_weight;
        }
    }
    return prefix;
}

fn smallHuffmanBitCount(plan: *const SmallHuffmanLiteralPlan, symbol: u8) ?u8 {
    const bit_count = plan.bit_counts[symbol];
    return if (bit_count == 0) null else bit_count;
}

fn emitSmallHuffmanStream(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, plan: *const SmallHuffmanLiteralPlan) Error!void {
    if (comptime @bitSizeOf(usize) >= 64)
        if (block.len >= 1024) return emitLongHuffmanStream(false, allocator, out, block, plan);
    const lookup = try smallHuffmanLiteralLookup(plan);
    const max_payload_bits = std.math.mul(usize, block.len, @as(usize, plan.max_bit_count)) catch return error.IntegerOverflow;
    const max_stream_bits = std.math.add(usize, max_payload_bits, 1) catch return error.IntegerOverflow;
    const max_stream_bytes = std.math.add(usize, max_stream_bits, 7) catch return error.IntegerOverflow;
    try out.ensureUnusedCapacity(allocator, max_stream_bytes / 8);
    var accumulator: usize = 0;
    var bit_count: std.math.Log2Int(usize) = 0;
    var i = block.len;
    if (comptime @bitSizeOf(usize) >= 64) {
        comptime std.debug.assert(7 + 4 * 11 <= @bitSizeOf(usize));
        while (i >= 4) {
            const first_symbol = block[i - 1];
            const second_symbol = block[i - 2];
            const third_symbol = block[i - 3];
            const fourth_symbol = block[i - 4];
            const first_bits = lookup.bit_counts[first_symbol];
            const second_bits = lookup.bit_counts[second_symbol];
            const third_bits = lookup.bit_counts[third_symbol];
            const fourth_bits = lookup.bit_counts[fourth_symbol];
            if (first_bits == 0 or second_bits == 0 or third_bits == 0 or fourth_bits == 0) return error.CorruptFrame;
            const first_code: usize = lookup.codes[first_symbol];
            const second_code: usize = lookup.codes[second_symbol];
            const third_code: usize = lookup.codes[third_symbol];
            const fourth_code: usize = lookup.codes[fourth_symbol];
            const second_shift: std.math.Log2Int(usize) = bit_count + @as(std.math.Log2Int(usize), @intCast(first_bits));
            const third_shift: std.math.Log2Int(usize) = second_shift + @as(std.math.Log2Int(usize), @intCast(second_bits));
            const fourth_shift: std.math.Log2Int(usize) = third_shift + @as(std.math.Log2Int(usize), @intCast(third_bits));
            accumulator |= first_code << bit_count;
            accumulator |= second_code << second_shift;
            accumulator |= third_code << third_shift;
            accumulator |= fourth_code << fourth_shift;
            bit_count = fourth_shift + @as(u6, @intCast(fourth_bits));
            while (bit_count >= 8) {
                out.appendAssumeCapacity(@truncate(accumulator));
                accumulator >>= 8;
                bit_count -= 8;
            }
            i -= 4;
        }
    } else {
        comptime std.debug.assert(7 + 2 * 11 <= @bitSizeOf(usize));
        while (i >= 2) {
            const first_symbol = block[i - 1];
            const second_symbol = block[i - 2];
            const first_bits = lookup.bit_counts[first_symbol];
            const second_bits = lookup.bit_counts[second_symbol];
            if (first_bits == 0 or second_bits == 0) return error.CorruptFrame;
            const second_shift: std.math.Log2Int(usize) = bit_count + @as(std.math.Log2Int(usize), @intCast(first_bits));
            accumulator |= @as(usize, lookup.codes[first_symbol]) << bit_count;
            accumulator |= @as(usize, lookup.codes[second_symbol]) << second_shift;
            bit_count = second_shift + @as(std.math.Log2Int(usize), @intCast(second_bits));
            while (bit_count >= 8) {
                out.appendAssumeCapacity(@truncate(accumulator));
                accumulator >>= 8;
                bit_count -= 8;
            }
            i -= 2;
        }
    }
    while (i > 0) {
        i -= 1;
        const bits = lookup.bit_counts[block[i]];
        if (bits == 0) return error.CorruptFrame;
        accumulator |= lookup.codes[block[i]] << bit_count;
        bit_count += @intCast(bits);
        while (bit_count >= 8) {
            out.appendAssumeCapacity(@truncate(accumulator));
            accumulator >>= 8;
            bit_count -= 8;
        }
    }
    accumulator |= @as(usize, 1) << bit_count;
    bit_count += 1;
    while (bit_count > 0) {
        out.appendAssumeCapacity(@truncate(accumulator));
        if (bit_count <= 8) break;
        accumulator >>= 8;
        bit_count -= 8;
    }
}

fn emitSmallHuffmanStreamKnownActive(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, plan: *const SmallHuffmanLiteralPlan) Error!void {
    if (comptime @bitSizeOf(usize) >= 64)
        if (block.len >= 1024) return emitLongHuffmanStream(true, allocator, out, block, plan);
    return emitSmallHuffmanStream(allocator, out, block, plan);
}

noinline fn emitLongHuffmanStream(
    comptime known_active: bool,
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    plan: *const SmallHuffmanLiteralPlan,
) linksection(wide_sequence_emit_text_section) Error!void {
    if (comptime @bitSizeOf(usize) < 64) return emitSmallHuffmanStream(allocator, out, block, plan);

    std.debug.assert(block.len >= 1024);
    const lookup = try smallHuffmanLiteralLookup(plan);
    const max_payload_bits = std.math.mul(usize, block.len, @as(usize, plan.max_bit_count)) catch return error.IntegerOverflow;
    const max_stream_bits = std.math.add(usize, max_payload_bits, 1) catch return error.IntegerOverflow;
    const max_stream_bytes = std.math.add(usize, max_stream_bits, 7) catch return error.IntegerOverflow;
    try out.ensureUnusedCapacity(allocator, max_stream_bytes / 8);
    comptime std.debug.assert(7 + 4 * 11 <= @bitSizeOf(usize));
    var accumulator: usize = 0;
    var bit_count: u6 = 0;
    var i = block.len;
    while (i >= 4) {
        const first_symbol = block[i - 1];
        const second_symbol = block[i - 2];
        const third_symbol = block[i - 3];
        const fourth_symbol = block[i - 4];
        const first_bits = lookup.bit_counts[first_symbol];
        const second_bits = lookup.bit_counts[second_symbol];
        const third_bits = lookup.bit_counts[third_symbol];
        const fourth_bits = lookup.bit_counts[fourth_symbol];
        if (comptime !known_active)
            if (first_bits == 0 or second_bits == 0 or third_bits == 0 or fourth_bits == 0) return error.CorruptFrame;
        const first_code: usize = lookup.codes[first_symbol];
        const second_code: usize = lookup.codes[second_symbol];
        const third_code: usize = lookup.codes[third_symbol];
        const fourth_code: usize = lookup.codes[fourth_symbol];
        const second_shift: u6 = bit_count + @as(u6, @intCast(first_bits));
        const third_shift: u6 = second_shift + @as(u6, @intCast(second_bits));
        const fourth_shift: u6 = third_shift + @as(u6, @intCast(third_bits));
        accumulator |= first_code << bit_count;
        accumulator |= second_code << second_shift;
        accumulator |= third_code << third_shift;
        accumulator |= fourth_code << fourth_shift;
        bit_count = fourth_shift + @as(u6, @intCast(fourth_bits));
        if (bit_count >= 32) {
            var bytes: [4]u8 = undefined;
            std.mem.writeInt(u32, &bytes, @truncate(accumulator), .little);
            out.appendSliceAssumeCapacity(&bytes);
            accumulator >>= 32;
            bit_count -= 32;
        }
        while (bit_count >= 8) {
            out.appendAssumeCapacity(@truncate(accumulator));
            accumulator >>= 8;
            bit_count -= 8;
        }
        i -= 4;
    }
    while (i > 0) {
        i -= 1;
        const bits = lookup.bit_counts[block[i]];
        if (comptime !known_active) if (bits == 0) return error.CorruptFrame;
        accumulator |= lookup.codes[block[i]] << bit_count;
        bit_count += @intCast(bits);
        while (bit_count >= 8) {
            out.appendAssumeCapacity(@truncate(accumulator));
            accumulator >>= 8;
            bit_count -= 8;
        }
    }
    accumulator |= @as(usize, 1) << bit_count;
    bit_count += 1;
    while (bit_count > 0) {
        out.appendAssumeCapacity(@truncate(accumulator));
        if (bit_count <= 8) break;
        accumulator >>= 8;
        bit_count -= 8;
    }
}

fn emitSmallHuffmanStreamCheckedAppendReference(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, plan: *const SmallHuffmanLiteralPlan) Error!void {
    var accumulator: usize = 0;
    var bit_count: std.math.Log2Int(usize) = 0;
    var i = block.len;
    while (i > 0) {
        i -= 1;
        const bits = plan.bit_counts[block[i]];
        if (bits == 0) return error.CorruptFrame;
        const code: usize = plan.codes[block[i]];
        accumulator |= code << bit_count;
        bit_count += @intCast(bits);
        while (bit_count >= 8) {
            try out.append(allocator, @truncate(accumulator));
            accumulator >>= 8;
            bit_count -= 8;
        }
    }
    accumulator |= @as(usize, 1) << bit_count;
    bit_count += 1;
    while (bit_count > 0) {
        try out.append(allocator, @truncate(accumulator));
        if (bit_count <= 8) break;
        accumulator >>= 8;
        bit_count -= 8;
    }
}

const SmallHuffmanLiteralLookup = struct {
    codes: [256]usize = [_]usize{0} ** 256,
    bit_counts: [256]u8 = [_]u8{0} ** 256,
};

fn smallHuffmanLiteralLookup(plan: *const SmallHuffmanLiteralPlan) Error!SmallHuffmanLiteralLookup {
    var lookup: SmallHuffmanLiteralLookup = .{};
    for (plan.symbols[0..plan.len]) |symbol| {
        lookup.codes[symbol] = plan.codes[symbol];
        lookup.bit_counts[symbol] = smallHuffmanBitCount(plan, symbol) orelse return error.CorruptFrame;
    }
    return lookup;
}

const DuplicateMatch = struct {
    first_start: usize,
    second_start: usize,
    len: usize,
    payload_len: usize = 0,
};

const DuplicateMatchIndex = struct {
    // Large-match rows are dense and aligned with `candidate_positions`: row N
    // describes the source position in `candidate_positions[N]`. The fast
    // policy samples one predecessor from each pair of hash occurrences.
    predecessors: [duplicate_pair_row_capacity]u16 = undefined,
    // Match lengths are computed only for predecessor pairs actually visited,
    // then shared by mixed, multi, and single passes.
    // u16 is sufficient because an indexed match starts after byte zero and
    // therefore cannot reach the reserved 0xffff sentinel length.
    match_lengths: [duplicate_pair_row_capacity]u16 = undefined,
    // Each query needs only positions whose eight-byte hash has a predecessor.
    // Store those positions densely in ascending order so suffix searches can
    // walk contiguous memory without a second per-position link pass.
    candidate_positions: [duplicate_pair_row_capacity]u16 = undefined,
    candidate_position_count: u16 = 0,
    hash_predecessors: [duplicate_index_max_input_len]u16 = undefined,
    // Small-block exact matching walks a complete hash chain. Store its reverse
    // traversal here so candidates retain the old earliest-first tie order
    // without rebuilding an open-addressed table for every suffix query.
    exact_chain: [duplicate_exact_hash_input_max]u16 = undefined,
    high_byte_count: u16 = 0,
    max_byte_frequency: u16 = 0,

    fn build(index: *DuplicateMatchIndex, block: []const u8) void {
        std.debug.assert(block.len <= duplicate_index_max_input_len);
        index.high_byte_count = 0;
        index.max_byte_frequency = 0;
        index.candidate_position_count = 0;
        var byte_frequencies: [256]u16 = @splat(0);
        var paired_predecessors: [duplicate_hash_table_len]u16 = undefined;
        var pending: [duplicate_hash_table_len]bool = @splat(false);
        var latest: [duplicate_hash_table_len]u16 = @splat(duplicate_index_invalid);
        for (0..block.len) |position| {
            const byte = block[position];
            byte_frequencies[byte] += 1;
            index.max_byte_frequency = @max(index.max_byte_frequency, byte_frequencies[byte]);
            index.high_byte_count += @intFromBool(byte > native_max_direct_huffman_symbol);
            if (position + 8 > block.len) continue;
            const hash = duplicateHash8(block[position..][0..8]);
            index.hash_predecessors[position] = latest[hash];
            latest[hash] = @intCast(position);
            if (pending[hash]) {
                const row = index.candidate_position_count;
                index.candidate_positions[row] = @intCast(position);
                index.predecessors[row] = paired_predecessors[hash];
                index.match_lengths[row] = duplicate_index_invalid;
                index.candidate_position_count += 1;
                pending[hash] = false;
            } else {
                paired_predecessors[hash] = @intCast(position);
                pending[hash] = true;
            }
        }
    }

    noinline fn buildBounded(index: *DuplicateMatchIndex, block: []const u8) linksection(fast_encode_helper_text_section) void {
        std.debug.assert(block.len > duplicate_exact_hash_input_max and block.len <= duplicate_index_max_input_len);
        index.high_byte_count = 0;
        index.max_byte_frequency = 0;
        var candidate_position_count: u16 = 0;
        var byte_frequencies: [256]u16 = @splat(0);
        var paired_predecessors: [duplicate_hash_table_len]u16 = undefined;
        var pending: [duplicate_hash_table_len]bool = @splat(false);
        for (0..block.len) |position| {
            const byte = block[position];
            byte_frequencies[byte] += 1;
            index.max_byte_frequency = @max(index.max_byte_frequency, byte_frequencies[byte]);
            index.high_byte_count += @intFromBool(byte > native_max_direct_huffman_symbol);
            if (position + 8 > block.len) continue;
            const hash = duplicateHash8(block[position..][0..8]);
            if (pending[hash]) {
                const row = candidate_position_count;
                index.candidate_positions[row] = @intCast(position);
                index.predecessors[row] = paired_predecessors[hash];
                index.match_lengths[row] = duplicate_index_invalid;
                candidate_position_count += 1;
                pending[hash] = false;
            } else {
                paired_predecessors[hash] = @intCast(position);
                pending[hash] = true;
            }
        }
        index.candidate_position_count = candidate_position_count;
    }
};

fn duplicateCandidateStart(index: *const DuplicateMatchIndex, start_min: usize) usize {
    var lo: usize = 0;
    var hi: usize = index.candidate_position_count;
    while (lo < hi) {
        const middle = lo + (hi - lo) / 2;
        if (index.candidate_positions[middle] < start_min)
            lo = middle + 1
        else
            hi = middle;
    }
    return lo;
}

const DictionaryMatch = struct {
    dictionary_start: usize,
    block_start: usize,
    len: usize,
};

fn findDictionaryMatch(dictionary: []const u8, block: []const u8, frame_offset: usize) ?DictionaryMatch {
    return findDictionaryMatchIn(dictionary, block, 0, frame_offset);
}

fn findDictionaryMatchIn(dictionary: []const u8, block: []const u8, start_min: usize, frame_offset: usize) ?DictionaryMatch {
    // Keep this first dictionary encoder slice deliberately small and
    // deterministic: it emits dictionary sequences in native blocks, and each
    // sequence may start after caller literals. Offset accounting uses the bytes
    // already emitted in the frame plus the preset history length, matching the
    // decoder's explicit dictionary-history model.
    if (dictionary.len == 0 or block.len < 8 or start_min + 8 > block.len) return null;
    var best: ?DictionaryMatch = null;
    var best_payload_len: usize = std.math.maxInt(usize);
    var block_start = start_min;
    while (block_start + 8 <= block.len) : (block_start += 1) {
        for (dictionary, 0..) |_, dictionary_start| {
            var len: usize = 0;
            while (dictionary_start + len < dictionary.len and
                block_start + len < block.len and
                dictionary[dictionary_start + len] == block[block_start + len]) : (len += 1)
            {}
            if (len >= 8) {
                const candidate: DictionaryMatch = .{ .dictionary_start = dictionary_start, .block_start = block_start, .len = len };
                const candidate_payload_len = dictionaryMatchPayloadLenFrom(block, candidate, start_min, frame_offset, dictionary.len) orelse continue;
                if (candidate_payload_len < best_payload_len or
                    (candidate_payload_len == best_payload_len and len > (best orelse candidate).len))
                {
                    best = candidate;
                    best_payload_len = candidate_payload_len;
                }
            }
        }
    }
    return best;
}

fn dictionaryMatchOffset(dictionary_len: usize, frame_offset: usize, match: DictionaryMatch) Error!usize {
    const dict_distance = dictionary_len - match.dictionary_start;
    const frame_distance = std.math.add(usize, frame_offset, match.block_start) catch return error.IntegerOverflow;
    return std.math.add(usize, dict_distance, frame_distance) catch return error.IntegerOverflow;
}

fn dictionaryMatchPayloadLenFrom(
    block: []const u8,
    match: DictionaryMatch,
    literal_start: usize,
    frame_offset: usize,
    dictionary_len: usize,
) ?usize {
    if (match.block_start < literal_start) return null;
    const literal_len = match.block_start - literal_start;
    const match_offset = dictionaryMatchOffset(dictionary_len, frame_offset, match) catch return null;
    const tail_len = block.len - match.block_start - match.len;
    return singleBestSequencePayloadLen(block, literal_len, match_offset, match.len, block.len - tail_len) catch null;
}

fn findBestDuplicateMatch(block: []const u8) Error!?DuplicateMatch {
    return try findBestDuplicateMatchIn(block, 0);
}

fn findBestDuplicateMatchIn(block: []const u8, start_min: usize) Error!?DuplicateMatch {
    if (block.len < 24 or start_min + 16 > block.len) return null;
    if (block.len <= duplicate_exact_hash_input_max) return try findBestDuplicateMatchExactHashed(block, start_min);
    return try findBestDuplicateMatchHashed(block, start_min);
}

fn findBestDuplicateMatchIndexed(block: []const u8, start_min: usize, index: *DuplicateMatchIndex) Error!?DuplicateMatch {
    return try findBestDuplicateMatchIndexedCancellable(block, start_min, index, null);
}

fn findBestDuplicateMatchIndexedCancellable(block: []const u8, start_min: usize, index: *DuplicateMatchIndex, cancelled: ?*const std.atomic.Value(bool)) Error!?DuplicateMatch {
    if (block.len < 24 or start_min + 16 > block.len) return null;
    if (block.len <= duplicate_exact_hash_input_max)
        return try findBestDuplicateMatchIndexedExact(block, start_min, index, cancelled);
    var best: ?DuplicateMatch = null;
    var best_payload_len: usize = std.math.maxInt(usize);
    var candidate_position_index = duplicateCandidateStart(index, start_min);
    while (candidate_position_index < index.candidate_position_count) : (candidate_position_index += 1) {
        const row = candidate_position_index;
        const second: usize = index.candidate_positions[row];
        // The mixed worker's caller never observes a partial candidate after
        // cancellation. Poll at candidate positions so a long suffix search
        // does not delay joining a decisive non-mixed result.
        if (cancelled) |flag| if (flag.load(.acquire)) return null;
        if (best) |current| if (block.len - second < current.len) break;
        const first: usize = index.predecessors[row];
        if (first < start_min) continue;
        if (best) |current| if (block.len - second <= current.len) continue;
        const cached_len = index.match_lengths[row];
        const len: usize = if (cached_len == duplicate_index_invalid) blk: {
            const computed = duplicateMatchLength(block, first, second);
            // `second >= 1`, so the maximum suffix length fits below the
            // all-ones sentinel for every indexed block.
            index.match_lengths[row] = @intCast(computed);
            break :blk computed;
        } else cached_len;
        if (len < 8) continue;
        const candidate: DuplicateMatch = .{ .first_start = first, .second_start = second, .len = len };
        if (duplicateMatchCannotBeat(candidate, best)) continue;
        const candidate_payload_len = singleMatchPayloadLenFromIndex(block, candidate, start_min, index) catch continue;
        if (candidate_payload_len < best_payload_len or (candidate_payload_len == best_payload_len and len > (best orelse candidate).len)) {
            var scored = candidate;
            scored.payload_len = candidate_payload_len;
            best = scored;
            best_payload_len = candidate_payload_len;
        }
    }
    return best;
}

noinline fn indexedSingleMatchCannotBeat(
    block: []const u8,
    index: *DuplicateMatchIndex,
    total_len_limit: usize,
) linksection(fast_encode_helper_text_section) bool {
    if (comptime builtin.is_test) if (test_disable_indexed_single_lower_bound) return false;
    if (total_len_limit == 0) return false;
    if (block.len <= duplicate_exact_hash_input_max or block.len > duplicate_index_max_input_len or block.len < 24) return false;
    if (index.high_byte_count != 0) return false;
    // A one-sequence compressed block has a three-byte block header. If its
    // literals are not RLE, every symbol needs at least one Huffman bit. Keep
    // the whole-block maximum frequency as the conservative RLE escape hatch.
    const huffman_literal_limit = if (total_len_limit <= 3)
        0
    else
        std.math.mul(usize, total_len_limit - 4, 8) catch std.math.maxInt(usize);
    const maximum_regenerated = @max(@as(usize, index.max_byte_frequency), huffman_literal_limit);
    if (maximum_regenerated >= block.len) return false;
    const required_match_len = block.len - maximum_regenerated;

    for (index.candidate_positions[0..index.candidate_position_count], 0..) |candidate_position, row| {
        const second: usize = candidate_position;
        if (block.len - second < required_match_len) break;
        const first: usize = index.predecessors[row];
        const cached_len = index.match_lengths[row];
        const len: usize = if (cached_len == duplicate_index_invalid) blk: {
            const computed = duplicateMatchLength(block, first, second);
            index.match_lengths[row] = @intCast(computed);
            break :blk computed;
        } else cached_len;
        if (len >= required_match_len) return false;
    }
    return true;
}

noinline fn boundedSingleMatchCannotBeat(
    block: []const u8,
    total_len_limit: usize,
) linksection(dominance_helper_text_section) bool {
    var max_byte_frequency: ?u16 = null;
    return boundedSingleMatchCannotBeatWithSummary(block, total_len_limit, &max_byte_frequency);
}

noinline fn boundedSingleMatchCannotBeatWithSummary(
    block: []const u8,
    total_len_limit: usize,
    max_byte_frequency_out: *?u16,
) linksection(dominance_helper_text_section) bool {
    max_byte_frequency_out.* = null;
    if (comptime builtin.is_test) if (test_disable_indexed_single_lower_bound) return false;
    if (total_len_limit == 0) return false;
    if (block.len <= duplicate_exact_hash_input_max or block.len > duplicate_index_max_input_len or block.len < 24) return false;

    // Mirror the cheap indexed proof without materializing its roughly 384 KiB
    // candidate/match arrays. High-byte literals still require exact scoring.
    // For direct-tree input, a competitive one-sequence block must remove at
    // least `required_match_len` bytes; checking only that prefix avoids finding
    // or scoring the complete match.
    var byte_frequencies: [4][256]u16 = @splat(@splat(0));
    var max_byte_frequency: usize = 0;
    var i: usize = 0;
    while (i + 4 <= block.len) : (i += 4) {
        inline for (0..4) |lane| {
            const byte = block[i + lane];
            if (byte > native_max_direct_huffman_symbol) return false;
            byte_frequencies[lane][byte] += 1;
        }
    }
    while (i < block.len) : (i += 1) {
        const byte = block[i];
        if (byte > native_max_direct_huffman_symbol) return false;
        byte_frequencies[0][byte] += 1;
    }
    for (0..256) |symbol| {
        const frequency = @as(usize, byte_frequencies[0][symbol]) +
            byte_frequencies[1][symbol] +
            byte_frequencies[2][symbol] +
            byte_frequencies[3][symbol];
        max_byte_frequency = @max(max_byte_frequency, frequency);
    }
    max_byte_frequency_out.* = @intCast(max_byte_frequency);
    const huffman_literal_limit = if (total_len_limit <= 3)
        0
    else
        std.math.mul(usize, total_len_limit - 4, 8) catch std.math.maxInt(usize);
    const maximum_regenerated = @max(max_byte_frequency, huffman_literal_limit);
    if (maximum_regenerated >= block.len) return false;
    const required_match_len = block.len - maximum_regenerated;

    const pending_word_bits = @bitSizeOf(usize);
    comptime std.debug.assert(duplicate_hash_table_len % pending_word_bits == 0);
    var pending: [duplicate_hash_table_len / pending_word_bits]usize = @splat(0);
    var paired_predecessors: [duplicate_hash_table_len]u16 = undefined;
    const last_candidate_position = block.len - required_match_len;
    for (0..last_candidate_position + 1) |position| {
        if (position + 8 > block.len) break;
        const hash = duplicateHash8(block[position..][0..8]);
        const pending_word = &pending[hash / pending_word_bits];
        const pending_mask = @as(usize, 1) << @intCast(hash % pending_word_bits);
        if (pending_word.* & pending_mask != 0) {
            const first: usize = paired_predecessors[hash];
            if (std.mem.eql(
                u8,
                block[first..][0..required_match_len],
                block[position..][0..required_match_len],
            )) return false;
            pending_word.* &= ~pending_mask;
        } else {
            paired_predecessors[hash] = @intCast(position);
            pending_word.* |= pending_mask;
        }
    }
    return true;
}

noinline fn indexedSingleMatchDominatedBy(
    block: []const u8,
    index: *DuplicateMatchIndex,
    total_len_limit: usize,
) linksection(fast_encode_helper_text_section) bool {
    if (comptime builtin.is_test) if (test_disable_indexed_single_lower_bound) return false;
    if (total_len_limit == 0) return false;
    if (block.len <= duplicate_exact_hash_input_max or block.len > duplicate_index_max_input_len or block.len < 24) return false;
    var maximum_match_len: usize = 0;
    for (index.candidate_positions[0..index.candidate_position_count], 0..) |candidate_position, row| {
        const second: usize = candidate_position;
        if (block.len - second <= maximum_match_len) break;
        const first: usize = index.predecessors[row];
        const cached_len = index.match_lengths[row];
        const len: usize = if (cached_len == duplicate_index_invalid) blk: {
            const computed = duplicateMatchLength(block, first, second);
            index.match_lengths[row] = @intCast(computed);
            break :blk computed;
        } else cached_len;
        if (len >= 8) maximum_match_len = @max(maximum_match_len, len);
    }

    var byte_frequencies: [256]u16 = @splat(0);
    for (block) |byte| byte_frequencies[byte] += 1;
    return singleMatchDominatedByStatistics(&byte_frequencies, maximum_match_len, total_len_limit);
}

noinline fn boundedSingleMatchDominatedBy(
    block: []const u8,
    total_len_limit: usize,
) linksection(dominance_helper_text_section) bool {
    if (comptime builtin.is_test) if (test_disable_indexed_single_lower_bound) return false;
    if (total_len_limit == 0) return false;
    if (block.len <= duplicate_exact_hash_input_max or block.len > duplicate_index_max_input_len or block.len < 24) return false;

    const pending_word_bits = @bitSizeOf(usize);
    comptime std.debug.assert(duplicate_hash_table_len % pending_word_bits == 0);
    var pending: [duplicate_hash_table_len / pending_word_bits]usize = @splat(0);
    var paired_predecessors: [duplicate_hash_table_len]u16 = undefined;
    var byte_frequencies: [256]u16 = @splat(0);
    var maximum_match_len: usize = 0;
    for (block, 0..) |byte, position| {
        byte_frequencies[byte] += 1;
        if (position + 8 > block.len or block.len - position <= maximum_match_len) continue;
        const hash = duplicateHash8(block[position..][0..8]);
        const pending_word = &pending[hash / pending_word_bits];
        const pending_mask = @as(usize, 1) << @intCast(hash % pending_word_bits);
        if (pending_word.* & pending_mask != 0) {
            const len = duplicateMatchLength(block, paired_predecessors[hash], position);
            if (len >= 8) maximum_match_len = @max(maximum_match_len, len);
            pending_word.* &= ~pending_mask;
        } else {
            paired_predecessors[hash] = @intCast(position);
            pending_word.* |= pending_mask;
        }
    }

    return singleMatchDominatedByStatistics(&byte_frequencies, maximum_match_len, total_len_limit);
}

inline fn precomputedBeamSingleDominanceLimit(beam_len: usize, block_len: usize) Error!usize {
    return std.math.add(usize, @max(beam_len, block_len / 256), 1) catch return error.IntegerOverflow;
}

inline fn singleMatchDominatedByStatistics(
    byte_frequencies: *const [256]u16,
    maximum_match_len: usize,
    total_len_limit: usize,
) bool {
    // Every single-match candidate removes one interval of at most
    // `maximum_match_len` bytes. Therefore at least `frequency - max_match`
    // occurrences of each symbol must remain literal, regardless of where the
    // interval lies. The optimal length-limited Huffman cost of those
    // independently guaranteed counts is a lower bound for every real literal
    // stream: restricting any real code to this symbol subset remains a valid
    // prefix code. Omitting the tree, stream markers, sequence payload, and
    // block header only weakens the bound, so equality is enough to prove that
    // no exact single candidate can beat `total_len_limit`.
    var frequencies: [256]u32 = @splat(0);
    var active_symbols: [256]u8 = undefined;
    var active_count: usize = 0;
    var guaranteed_literals: usize = 0;
    for (byte_frequencies.*, 0..) |frequency, symbol| {
        const guaranteed = @as(usize, frequency) -| maximum_match_len;
        if (guaranteed == 0) continue;
        frequencies[symbol] = @intCast(guaranteed);
        active_symbols[active_count] = @intCast(symbol);
        active_count += 1;
        guaranteed_literals += guaranteed;
    }
    // With fewer than two guaranteed symbols the retained stream could still
    // be RLE, whose one-byte payload defeats this Huffman lower bound.
    if (active_count < 2) return false;
    const lengths = huffman.treeCodeLengthsKnownActive(
        256,
        &frequencies,
        11,
        active_symbols[0..active_count],
    );
    var huffman_bits: usize = 0;
    for (active_symbols[0..active_count]) |symbol| {
        huffman_bits = std.math.add(
            usize,
            huffman_bits,
            std.math.mul(usize, frequencies[symbol], lengths[symbol]) catch return false,
        ) catch return false;
    }
    const huffman_payload_lower_bound = (huffman_bits + 7) / 8;
    const literal_payload_lower_bound = @min(guaranteed_literals, huffman_payload_lower_bound);
    return literal_payload_lower_bound >= total_len_limit;
}

noinline fn indexedSingleMatchCannotBeatFullScan(
    block: []const u8,
    index: *DuplicateMatchIndex,
    total_len_limit: usize,
) linksection(fast_encode_helper_text_section) bool {
    if (total_len_limit == 0 or index.high_byte_count != 0) return false;
    var maximum_len: usize = 0;
    for (index.candidate_positions[0..index.candidate_position_count], 0..) |candidate_position, row| {
        const second: usize = candidate_position;
        if (block.len - second <= maximum_len) break;
        const cached_len = index.match_lengths[row];
        const len: usize = if (cached_len == duplicate_index_invalid) blk: {
            const computed = duplicateMatchLength(block, index.predecessors[row], second);
            index.match_lengths[row] = @intCast(computed);
            break :blk computed;
        } else cached_len;
        if (len >= 8) maximum_len = @max(maximum_len, len);
    }
    if (maximum_len == 0) return true;
    const regenerated_len = block.len - maximum_len;
    return index.max_byte_frequency < regenerated_len and (regenerated_len + 7) / 8 + 3 >= total_len_limit;
}

fn findBestDuplicateMatchIndexedExact(block: []const u8, start_min: usize, index: *DuplicateMatchIndex, cancelled: ?*const std.atomic.Value(bool)) Error!?DuplicateMatch {
    std.debug.assert(block.len <= duplicate_exact_hash_input_max);
    var best: ?DuplicateMatch = null;
    var best_payload_len: usize = std.math.maxInt(usize);
    var second = start_min;
    while (second + 8 <= block.len) : (second += 1) {
        if (cancelled) |flag| if (flag.load(.acquire)) return null;
        if (best) |current| if (block.len - second < current.len) break;

        var chain_len: usize = 0;
        var candidate_index = index.hash_predecessors[second];
        while (candidate_index != duplicate_index_invalid) {
            if (candidate_index < start_min) break;
            index.exact_chain[chain_len] = candidate_index;
            chain_len += 1;
            candidate_index = index.hash_predecessors[candidate_index];
        }
        while (chain_len != 0) {
            chain_len -= 1;
            const first: usize = index.exact_chain[chain_len];
            const len = duplicateMatchLength(block, first, second);
            if (len < 8) continue;
            const candidate: DuplicateMatch = .{ .first_start = first, .second_start = second, .len = len };
            if (duplicateMatchCannotBeat(candidate, best)) continue;
            const candidate_payload_len = singleMatchPayloadLenFrom(block, candidate, start_min) catch continue;
            if (candidate_payload_len < best_payload_len or
                (candidate_payload_len == best_payload_len and len > (best orelse candidate).len))
            {
                var scored = candidate;
                scored.payload_len = candidate_payload_len;
                best = scored;
                best_payload_len = candidate_payload_len;
            }
        }
    }
    return best;
}

/// Exact small-block matcher used by the single-match fallback. Every match of
/// at least eight bytes shares its first eight-byte hash, so walking the full
/// bucket chain removes non-candidates without changing the reference scan's
/// search space or tie order. The bounded stack tables are far cheaper than the
/// former O(n²) byte-pair scan across level-1's 1/2/4 KiB adaptive blocks.
fn findBestDuplicateMatchExactHashed(block: []const u8, start_min: usize) Error!?DuplicateMatch {
    std.debug.assert(block.len <= duplicate_exact_hash_input_max);
    var keys: [duplicate_exact_key_table_len]u64 = undefined;
    var heads: [duplicate_exact_key_table_len]u16 = undefined;
    var tails: [duplicate_exact_key_table_len]u16 = undefined;
    var occupied: [duplicate_exact_key_table_len / 64]u64 = @splat(0);
    var next: [duplicate_exact_hash_input_max]u16 = undefined;

    var best: ?DuplicateMatch = null;
    var best_payload_len: usize = std.math.maxInt(usize);
    var index = start_min;
    while (index + 8 <= block.len) : (index += 1) {
        // No match beginning here or later can exceed the remaining suffix.
        // Once that suffix is shorter than the current winner, later positions
        // cannot improve either length or the payload tie-break.
        if (best) |current| if (block.len - index < current.len) break;
        const key = std.mem.readInt(u64, block[index..][0..8], .little);
        var slot = duplicateHashKey(key) & (duplicate_exact_key_table_len - 1);
        while ((occupied[slot / 64] & (@as(u64, 1) << @intCast(slot & 63))) != 0 and keys[slot] != key)
            slot = (slot + 1) & (duplicate_exact_key_table_len - 1);
        const word = slot / 64;
        const bit = @as(u64, 1) << @intCast(slot & 63);
        const was_occupied = (occupied[word] & bit) != 0;
        var candidate_index = if (was_occupied) heads[slot] else duplicate_index_invalid;
        while (candidate_index != duplicate_index_invalid) {
            const first: usize = @intCast(candidate_index);
            candidate_index = next[candidate_index];
            const len = duplicateMatchLengthAfterAnchor(block, first, index);
            if (len >= 8) {
                const candidate: DuplicateMatch = .{ .first_start = first, .second_start = index, .len = len };
                if (duplicateMatchCannotBeat(candidate, best)) continue;
                const candidate_payload_len = singleMatchPayloadLenFrom(block, candidate, start_min) catch continue;
                if (candidate_payload_len < best_payload_len or (candidate_payload_len == best_payload_len and len > (best orelse candidate).len)) {
                    var scored = candidate;
                    scored.payload_len = candidate_payload_len;
                    best = scored;
                    best_payload_len = candidate_payload_len;
                }
            }
        }

        // Append rather than prepend so walking the collision chain preserves
        // the reference scan's earliest-first tie order without materializing
        // and reversing a temporary candidate list for every input position.
        next[index] = duplicate_index_invalid;
        if (!was_occupied) {
            keys[slot] = key;
            heads[slot] = @intCast(index);
            occupied[word] |= bit;
        } else {
            next[tails[slot]] = @intCast(index);
        }
        tails[slot] = @intCast(index);
    }
    return best;
}

fn findBestDuplicateMatchScanReference(block: []const u8, start_min: usize) Error!?DuplicateMatch {
    if (block.len < 24 or start_min + 16 > block.len) return null;
    var best: ?DuplicateMatch = null;
    var best_payload_len: usize = std.math.maxInt(usize);
    var second: usize = start_min + 1;
    while (second + 8 <= block.len) : (second += 1) {
        var first: usize = start_min;
        while (first < second) : (first += 1) {
            var len: usize = 0;
            while (second + len < block.len and block[first + len] == block[second + len]) : (len += 1) {}
            if (len < 8) continue;
            const candidate: DuplicateMatch = .{ .first_start = first, .second_start = second, .len = len };
            if (duplicateMatchCannotBeat(candidate, best)) continue;
            const candidate_payload_len = singleMatchPayloadLenFrom(block, candidate, start_min) catch continue;
            if (candidate_payload_len < best_payload_len or (candidate_payload_len == best_payload_len and len > (best orelse candidate).len)) {
                var scored = candidate;
                scored.payload_len = candidate_payload_len;
                best = scored;
                best_payload_len = candidate_payload_len;
            }
        }
    }
    return best;
}

test "zstd exact small duplicate hash matches scan reference" {
    var payload: [768]u8 = undefined;
