test "zstd bounded duplicate index preserves large-block search" {
    var payload: [32 * 1024]u8 = undefined;
    for (0..16) |seed| {
        var state: u32 = @truncate(0xa409_3822 +% seed *% 0x0100_0193);
        for (&payload, 0..) |*byte, i| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @intCast('a' + (i + seed) % 23),
                1 => if (i % 64 < 52) @intCast('A' + (i + seed) % 26) else @truncate(state >> 24),
                2 => @intCast((i * 17 + seed * 13) & 127),
                else => @truncate(state >> 24),
            };
        }
        const copy_len = payload.len / 4;
        @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);

        var full: DuplicateMatchIndex = undefined;
        full.build(&payload);
        var bounded: DuplicateMatchIndex = undefined;
        bounded.buildBounded(&payload);
        try std.testing.expectEqual(full.high_byte_count, bounded.high_byte_count);
        try std.testing.expectEqual(full.max_byte_frequency, bounded.max_byte_frequency);
        try std.testing.expectEqual(full.candidate_position_count, bounded.candidate_position_count);
        try std.testing.expectEqualSlices(
            u16,
            full.candidate_positions[0..full.candidate_position_count],
            bounded.candidate_positions[0..bounded.candidate_position_count],
        );
        var pending_positions: [duplicate_hash_table_len]u16 = undefined;
        var pending_hashes: [duplicate_hash_table_len]bool = @splat(false);
        var expected_candidate_count: usize = 0;
        for (0..payload.len) |position| {
            if (position + 8 <= payload.len) {
                const hash = duplicateHash8(payload[position..][0..8]);
                if (pending_hashes[hash]) {
                    const row = expected_candidate_count;
                    try std.testing.expectEqual(position, full.candidate_positions[row]);
                    try std.testing.expectEqual(pending_positions[hash], full.predecessors[row]);
                    try std.testing.expectEqual(full.predecessors[row], bounded.predecessors[row]);
                    try std.testing.expectEqual(full.match_lengths[row], bounded.match_lengths[row]);
                    expected_candidate_count += 1;
                    pending_hashes[hash] = false;
                } else {
                    pending_positions[hash] = @intCast(position);
                    pending_hashes[hash] = true;
                }
            }
        }
        try std.testing.expectEqual(expected_candidate_count, full.candidate_position_count);
        for ([_]usize{ 0, 257, 4096, 16 * 1024 }) |start_min| {
            var expected_start: usize = 0;
            while (expected_start < full.candidate_position_count and
                full.candidate_positions[expected_start] < start_min) : (expected_start += 1)
            {}
            try std.testing.expectEqual(expected_start, duplicateCandidateStart(&full, start_min));
            try std.testing.expectEqual(
                try findBestDuplicateMatchIndexed(&payload, start_min, &full),
                try findBestDuplicateMatchIndexed(&payload, start_min, &bounded),
            );
        }
    }
}

test "zstd indexed duplicate lower bound preserves competitive winners" {
    var payload: [8192]u8 = undefined;
    var retained_cases: usize = 0;
    for (0..16) |seed| {
        var state: u32 = @truncate(0x9e37_79b9 +% seed *% 0x0100_0193);
        for (&payload, 0..) |*byte, i| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = if (i % 64 < 52) @intCast('a' + (i + seed) % 23) else @intCast((state >> 24) & native_max_direct_huffman_symbol);
        }
        @memcpy(payload[4096..5120], payload[1024..2048]);
        @memcpy(payload[7168..7680], payload[2560..3072]);

        var index: DuplicateMatchIndex = undefined;
        index.buildBounded(&payload);
        try std.testing.expect(!indexedSingleMatchCannotBeat(&payload, &index, 0));
        const expected = (try findBestDuplicateMatchIndexed(&payload, 0, &index)) orelse continue;
        try std.testing.expect(expected.payload_len != 0);
        // If the exact selected single candidate beats a limit, the cheaper
        // threshold scan must conservatively retain the full search.
        try std.testing.expect(!indexedSingleMatchCannotBeat(&payload, &index, expected.payload_len + 4));
        for ([_]usize{ 4, 8, 16, 32, 64, 128, 512, 2048 }) |limit| {
            index.buildBounded(&payload);
            const actual = indexedSingleMatchCannotBeat(&payload, &index, limit);
            index.buildBounded(&payload);
            const reference = indexedSingleMatchCannotBeatFullScan(&payload, &index, limit);
            try std.testing.expectEqual(reference, actual);
            retained_cases += @intFromBool(!actual);
        }
    }
    try std.testing.expect(retained_cases != 0);
}

test "zstd decisive single dominance bound preserves competitive winners" {
    var payload: [32 * 1024]u8 = undefined;
    var pruned_cases: usize = 0;
    var retained_cases: usize = 0;
    for (0..32) |seed| {
        var state: u32 = @truncate(0x510e_527f +% seed *% 0x0100_0193);
        for (&payload, 0..) |*byte, i| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @intCast('a' + (i + seed) % 23),
                1 => if (i % 64 < 52) @intCast('A' + (i + seed) % 26) else @truncate(state >> 24),
                2 => @intCast((i * 17 + seed * 13) & 127),
                else => @truncate(state >> 24),
            };
        }
        if (seed % 3 != 0) {
            const copy_len = 256 + seed * 31;
            @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
        }

        var index: DuplicateMatchIndex = undefined;
        index.buildBounded(&payload);
        const expected = try findBestDuplicateMatchIndexed(&payload, 0, &index);
        for ([_]usize{ 128, 512, 2048, 8192, 16 * 1024 }) |limit| {
            index.buildBounded(&payload);
            const dominated = indexedSingleMatchDominatedBy(&payload, &index, limit);
            try std.testing.expectEqual(dominated, boundedSingleMatchDominatedBy(&payload, limit));
            if (dominated) {
                pruned_cases += 1;
                if (expected) |match| try std.testing.expect(match.payload_len + 3 >= limit);
            } else {
                retained_cases += 1;
            }
        }
    }
    try std.testing.expect(pruned_cases != 0);
    try std.testing.expect(retained_cases != 0);
}

