        for (payload, 0..) |*byte, i| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @intCast('a' + (i + seed) % 23),
                1 => if (i % 64 < 52) @intCast('A' + (i + seed) % 26) else @truncate(state >> 24),
                2 => @intCast((i * 17 + seed * 13) & 127),
