fn duplicateMatchCannotBeat(candidate: DuplicateMatch, current: ?DuplicateMatch) bool {
    const existing = current orelse return false;
    if (candidate.len < existing.len) return true;
    if (candidate.len > existing.len) return false;

    // Equal-length matches regenerate the same total literal bytes. A later
    // match with an equal-or-larger offset cannot improve the sequence payload:
    // it has a literal length that is at least as large and an offset code that
    // is no cheaper. Skipping these common hash-collision candidates keeps the
    // bootstrap large-block finder bounded on high-entropy Huffman-friendly
    // payloads while preserving closer equal-length matches.
    const candidate_offset = candidate.second_start - candidate.first_start;
    const existing_offset = existing.second_start - existing.first_start;
    return candidate.second_start >= existing.second_start and candidate_offset >= existing_offset;
}

fn duplicateHash8(bytes: *const [8]u8) usize {
    return duplicateHashKey(std.mem.readInt(u64, bytes, .little));
}

inline fn duplicateHashKey(value: u64) usize {
    const shift: u6 = @intCast(64 - duplicate_hash_bits);
    return @intCast((value *% 11_400_714_819_323_198_485) >> shift);
}

fn duplicateMatchLength(block: []const u8, first: usize, second: usize) usize {
    // The large matcher uses a truncated hash and can still see collisions;
    // verify its anchor word before extending the remaining suffix. Structured
    // data frequently produces long true matches, so word-at-a-time comparison
    // avoids the byte loop that dominated high-level mixed-plan search.
    const first_left = std.mem.readInt(u64, block[first..][0..8], .little);
    const first_right = std.mem.readInt(u64, block[second..][0..8], .little);
    if (first_left != first_right) return @ctz(first_left ^ first_right) / 8;
    return duplicateMatchLengthAfterAnchor(block, first, second);
}

fn duplicateMatchLengthAfterAnchor(block: []const u8, first: usize, second: usize) usize {
    const max_len = block.len - second;
    var len: usize = 8;
    while (len + 32 <= max_len) : (len += 32) {
        const left: @Vector(32, u8) = block[first + len ..][0..32].*;
        const right: @Vector(32, u8) = block[second + len ..][0..32].*;
        const equal_mask: u32 = @bitCast(left == right);
        const differing_mask = ~equal_mask;
        if (differing_mask != 0) return len + @ctz(differing_mask);
    }
    while (len + 8 <= max_len) : (len += 8) {
        const left = std.mem.readInt(u64, block[first + len ..][0..8], .little);
        const right = std.mem.readInt(u64, block[second + len ..][0..8], .little);
        if (left != right) return len + @ctz(left ^ right) / 8;
    }
    while (len < max_len and block[first + len] == block[second + len]) : (len += 1) {}
    return len;
}

fn singleMatchPayloadLen(block: []const u8, match: DuplicateMatch) Error!usize {
    return singleMatchPayloadLenFrom(block, match, 0);
}

fn singleMatchPayloadLenFrom(block: []const u8, match: DuplicateMatch, literal_start: usize) Error!usize {
    const literal_len = match.second_start - literal_start;
    const offset = match.second_start - match.first_start;
    return try singleBestSequencePayloadLen(block, literal_len, offset, match.len, match.second_start + match.len);
}

fn singleMatchPayloadLenFromIndex(block: []const u8, match: DuplicateMatch, literal_start: usize, index: *const DuplicateMatchIndex) Error!usize {
    const literal_len = match.second_start - literal_start;
    const offset = match.second_start - match.first_start;
    const tail_start = match.second_start + match.len;
    const regenerated_len = literal_len + block.len - tail_start;
    // This legacy high-byte shortcut predates full FSE-compressed Huffman
    // weight emission. It remains profitable for the common wide binary shape,
    // but can conservatively overestimate rare low-entropy high-byte literals;
    // keep that limitation explicit until exact scoring can be isolated without
    // regressing the common selector path. An RLE literal section is impossible
    // when no symbol occurs often enough to fill the retained stream.
    const removed_len = std.math.add(usize, literal_start, match.len) catch return error.IntegerOverflow;
    const literals_section_len = if (index.high_byte_count > removed_len and index.max_byte_frequency < regenerated_len)
        std.math.add(usize, try literalsHeaderLen(regenerated_len), regenerated_len) catch return error.IntegerOverflow
    else
        return try singleMatchPayloadLenFrom(block, match, literal_start);
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{offset};
    const match_lens = [_]usize{match.len};
    var best: ?usize = null;
    if (rleSequencePayloadLenForValuesWithLiteralsLen(&literal_lens, &offsets, &match_lens, literals_section_len)) |len| chooseShortestPayloadLen(len, &best) else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }
    if (predefinedSequencePayloadLenWithLiteralsLen(&literal_lens, &offsets, &match_lens, literals_section_len)) |len| chooseShortestPayloadLen(len, &best) else |err| switch (err) {
        error.CorruptFrame => {},
        else => return err,
    }
    return best orelse error.CorruptFrame;
}

fn repeatedPatternPayloadLenFrom(block: []const u8, segment: RepeatedPatternSegment, literal_start: usize) ?usize {
    if (segment.start < literal_start) return null;
    const literal_len = std.math.add(usize, segment.start - literal_start, segment.period) catch return null;
    const tail_start = std.math.add(usize, segment.start + segment.period, segment.match_len) catch return null;
    return singleBestSequencePayloadLen(block, literal_len, segment.period, segment.match_len, tail_start) catch null;
}

noinline fn repeatedPatternCandidateCannotBeat(
    block: []const u8,
    best_len: usize,
    max_byte_frequency: usize,
) linksection(dominance_helper_text_section) bool {
    if (best_len == 0 or block.len < 8) return false;
    var first_pattern: ?RepeatedPatternSegment = null;
    var multi_literal_len: usize = 0;
    var multi_tail_start: usize = 0;
    var count: usize = 0;
    var search_start: usize = 0;
    while (count < max_bootstrap_sequence_count and search_start < block.len) {
        const segment = findRepeatedPatternSegmentIn(block, search_start, block.len) orelse break;
        if (first_pattern == null) first_pattern = segment;
        if (segment.start - search_start > 16) break;
        const literal_len = std.math.add(usize, segment.start - search_start, segment.period) catch return false;
        const segment_prefix = std.math.add(usize, segment.start, segment.period) catch return false;
        const segment_end = std.math.add(usize, segment_prefix, segment.match_len) catch return false;
        multi_literal_len = std.math.add(usize, multi_literal_len, literal_len) catch return false;
        count += 1;
        search_start = segment_end;
        multi_tail_start = segment_end;
        if (segment.tail_len == 0) break;
    }
    const first = first_pattern orelse return true;
    const single_regenerated_len = block.len - first.match_len;
    var minimum_regenerated_len = single_regenerated_len;
    if (count >= 2) {
        const multi_regenerated_len = std.math.add(usize, multi_literal_len, block.len - multi_tail_start) catch return false;
        minimum_regenerated_len = @min(minimum_regenerated_len, multi_regenerated_len);
    }
    if (minimum_regenerated_len <= max_byte_frequency) return false;
    const literal_payload_lower_bound = (minimum_regenerated_len + 7) / 8;
    const block_lower_bound = std.math.add(usize, 3, literal_payload_lower_bound) catch return false;
    return block_lower_bound >= best_len;
}

fn emitRepeatedPatternCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool) Error!bool {
    return try emitRepeatedPatternCompressedBlockWithScratch(allocator, out, block, last, null);
}

fn emitRepeatedPatternCompressedBlockWithScratch(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool, single_scratch: ?*SingleSequenceEmitScratch) Error!bool {
    if (rleByte(block) != null) return false;
    if (single_scratch) |scratch| {
        const best_len = scratch.repeated_prune_best_len;
        scratch.repeated_prune_best_len = 0;
        if (best_len != 0 and repeatedPatternCandidateCannotBeat(
            block,
            best_len,
            scratch.repeated_prune_max_byte_frequency,
        )) {
            if (comptime builtin.is_test) test_precomputed_beam_repeated_prune_hits += 1;
            return false;
        }
        if (comptime builtin.is_test) test_precomputed_beam_repeated_prune_fallbacks += @intFromBool(best_len != 0);
    }
    if (try emitMultiRepeatedPatternCompressedBlock(allocator, out, block, last)) return true;
    const pattern = findRepeatedPatternSegment(block) orelse return false;
    const literal_len = pattern.start + pattern.period;
    const match_len = pattern.match_len;
    if (match_len < 3) return false;
    const tail_start = block.len - pattern.tail_len;
    const literal_lens = [_]usize{literal_len};
    const offsets = [_]usize{pattern.period};
    const match_lens = [_]usize{match_len};
    const literal_ends = [_]usize{tail_start};
    return try emitBestSequenceCompressedBlockWithScratch(allocator, out, block, last, &literal_lens, &offsets, &match_lens, &literal_ends, tail_start, single_scratch);
}

fn emitMultiRepeatedPatternCompressedBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool) Error!bool {
    var segments: [max_bootstrap_sequence_count]RepeatedPatternSegment = undefined;
    var literal_lens: [max_bootstrap_sequence_count]usize = undefined;
    var count: usize = 0;
    var search_start: usize = 0;
    while (count < segments.len and search_start < block.len) {
        const segment = findRepeatedPatternSegmentIn(block, search_start, block.len) orelse break;
        if (segment.start - search_start > 16) break;
        const literal_len = std.math.add(usize, segment.start - search_start, segment.period) catch return error.IntegerOverflow;
        const segment_prefix = std.math.add(usize, segment.start, segment.period) catch return error.IntegerOverflow;
        const segment_end = std.math.add(usize, segment_prefix, segment.match_len) catch return error.IntegerOverflow;
        segments[count] = segment;
        literal_lens[count] = literal_len;
        count += 1;
        search_start = segment_end;
        if (segment.tail_len == 0) break;
    }
    if (count < 2) return false;
    var offsets: [max_bootstrap_sequence_count]usize = undefined;
    var match_lens: [max_bootstrap_sequence_count]usize = undefined;
    var literal_ends: [max_bootstrap_sequence_count]usize = undefined;
    for (segments[0..count], 0..) |segment, i| {
        offsets[i] = segment.period;
        match_lens[i] = segment.match_len;
        literal_ends[i] = segment.start + segment.period + segment.match_len;
    }
    return try emitBestSequenceCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens[0..count],
        offsets[0..count],
        match_lens[0..count],
        literal_ends[0..count],
        search_start,
    );
}

fn emitMultiRepeatedPatternPredefinedCompressedBlock(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    block: []const u8,
    last: bool,
    segments: []const RepeatedPatternSegment,
    literal_lens: []const usize,
    tail_start: usize,
) Error!bool {
    if (segments.len != literal_lens.len or segments.len < 2 or segments.len > max_bootstrap_sequence_count) return false;

    var offsets: [max_bootstrap_sequence_count]usize = undefined;
    var match_lens: [max_bootstrap_sequence_count]usize = undefined;
    var literal_ends: [max_bootstrap_sequence_count]usize = undefined;
    for (segments, 0..) |segment, i| {
        offsets[i] = segment.period;
        match_lens[i] = segment.match_len;
        literal_ends[i] = segment.start + segment.period + segment.match_len;
    }
    return try emitMultiSequencePredefinedCompressedBlock(
        allocator,
        out,
        block,
        last,
        literal_lens,
        offsets[0..segments.len],
        match_lens[0..segments.len],
        literal_ends[0..segments.len],
        tail_start,
    );
}

fn emitSequenceCount(allocator: std.mem.Allocator, out: *std.ArrayList(u8), count: usize) Error!void {
    if (count == 0) return error.CorruptFrame;
    if (count < 128) return try out.append(allocator, @intCast(count));
    if (count < 0x7f00) {
        try out.append(allocator, @intCast((count >> 8) + 128));
        try out.append(allocator, @truncate(count));
        return;
    }
    const adjusted = count - 0x7f00;
    try out.append(allocator, 255);
    try out.append(allocator, @truncate(adjusted));
    try out.append(allocator, @truncate(adjusted >> 8));
}

const RepeatedPatternSegment = struct {
    start: usize,
    period: usize,
    match_len: usize,
    tail_len: usize,
};

const BitField = struct {
    value: usize,
    bits: u8,
};

const PredefinedSequencePlan = struct {
    len: usize = 0,
    // Source LL/OF/ML values stay in the caller-owned plan arrays. States are
    // bounded by max_predefined_sequence_states, so u8 retains every valid
    // state while keeping frequently copied alternatives compact.
    states: [max_native_sequence_count]u8 = undefined,
};

fn buildPredefinedStateMasks(
    comptime symbols: []const SequenceSymbol,
    comptime bases: []const usize,
    comptime bits: []const u8,
    comptime min_additional_bits: u8,
) [bases.len]u64 {
    @setEvalBranchQuota(10_000);
    var masks: [bases.len]u64 = @splat(0);
    for (symbols, 0..) |symbol, state| {
        if (symbol.additional_bits < min_additional_bits) continue;
        for (bases, bits, 0..) |base, bit_count, code| {
            if (symbol.base == base and symbol.additional_bits == bit_count) {
                masks[code] |= @as(u64, 1) << @intCast(state);
                break;
            }
        }
    }
    return masks;
}

const predefined_literal_state_masks = buildPredefinedStateMasks(&sequence_predefined.literal_symbols, &ll_base, &ll_bits, 0);
const predefined_offset_state_masks = buildPredefinedStateMasks(&sequence_predefined.offset_symbols, &of_base, &of_bits, 2);
const predefined_offset_code_state_masks = buildPredefinedStateMasks(&sequence_predefined.offset_symbols, &of_base, &of_bits, 0);
const predefined_match_state_masks = buildPredefinedStateMasks(&sequence_predefined.match_symbols, &ml_base, &ml_bits, 0);

fn buildPredefinedMinimumCosts(
    comptime symbols: []const SequenceSymbol,
    comptime bases: []const usize,
    comptime bits: []const u8,
    comptime min_additional_bits: u8,
) [bases.len][2]u8 {
    @setEvalBranchQuota(10_000);
    var costs: [bases.len][2]u8 = @splat(@splat(std.math.maxInt(u8)));
    for (symbols) |symbol| {
        if (symbol.additional_bits < min_additional_bits) continue;
        for (bases, bits, 0..) |base, bit_count, code| {
            if (symbol.base != base or symbol.additional_bits != bit_count) continue;
            costs[code][0] = @min(costs[code][0], symbol.additional_bits);
            costs[code][1] = @min(costs[code][1], symbol.additional_bits + symbol.state_bits);
            break;
        }
    }
    return costs;
}

const predefined_literal_minimum_costs = buildPredefinedMinimumCosts(&sequence_predefined.literal_symbols, &ll_base, &ll_bits, 0);
const predefined_offset_minimum_costs = buildPredefinedMinimumCosts(&sequence_predefined.offset_symbols, &of_base, &of_bits, 2);
const predefined_match_minimum_costs = buildPredefinedMinimumCosts(&sequence_predefined.match_symbols, &ml_base, &ml_bits, 0);

fn predefinedEncodableStateMask(value: usize, symbols: []const SequenceSymbol, min_additional_bits: u8) u64 {
    if (symbols.ptr == sequence_predefined.literal_symbols[0..].ptr and min_additional_bits == 0) {
        const code = sequenceCodeForValue(value, &ll_base, &ll_bits) catch return 0;
        return predefined_literal_state_masks[code];
    }
    if (symbols.ptr == sequence_predefined.offset_symbols[0..].ptr and min_additional_bits == 2) {
        const code = sequenceCodeForValue(value, &of_base, &of_bits) catch return 0;
        return predefined_offset_state_masks[code];
    }
    if (symbols.ptr == sequence_predefined.match_symbols[0..].ptr and min_additional_bits == 0) {
        const code = sequenceCodeForValue(value, &ml_base, &ml_bits) catch return 0;
        return predefined_match_state_masks[code];
    }

    var mask: u64 = 0;
    for (symbols, 0..) |symbol, state| {
        if (predefinedSymbolCanEncode(symbol, value, min_additional_bits)) mask |= @as(u64, 1) << @intCast(state);
    }
    return mask;
}

fn planPredefinedSequenceValues(values: []const usize, symbols: []const SequenceSymbol, min_additional_bits: u8) Error!?PredefinedSequencePlan {
    if (values.len == 0 or values.len > max_native_sequence_count) return null;
    if (symbols.len > max_predefined_sequence_states) return null;

    var next_choice: [max_native_sequence_count][max_predefined_sequence_states]u8 = undefined;

    var viable_next: u64 = 0;

    var pos = values.len;
    while (pos > 0) {
        pos -= 1;
        var viable_current: u64 = 0;

        var encodable_states = predefinedEncodableStateMask(values[pos], symbols, min_additional_bits);
        while (encodable_states != 0) {
            const state: usize = @ctz(encodable_states);
            encodable_states &= encodable_states - 1;
            if (pos == values.len - 1) {
                viable_current |= @as(u64, 1) << @intCast(state);
                continue;
            }

            const symbol = symbols[state];
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            if (first_next >= end_next) continue;
            const width = end_next - first_next;
            const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
            const possible = viable_next & (low_mask << @intCast(first_next));
            if (possible == 0) continue;
            viable_current |= @as(u64, 1) << @intCast(state);
            // `ctz` returns the same lowest viable state as the old ascending
            // transition loop, preserving deterministic tie behavior.
            next_choice[pos][state] = @intCast(@ctz(possible));
        }

        viable_next = viable_current;
    }

    if (viable_next == 0) return null;
    const initial_state: usize = @ctz(viable_next);

    var plan: PredefinedSequencePlan = .{ .len = values.len };
    plan.states[0] = @intCast(initial_state);
    for (0..values.len - 1) |i| {
        plan.states[i + 1] = next_choice[i][plan.states[i]];
        if (plan.states[i + 1] >= symbols.len) return null;
    }
    return plan;
}

fn planLargePredefinedSequenceValues(
    values: []const usize,
    symbols: []const SequenceSymbol,
    min_additional_bits: u8,
    states: []u8,
    viable_masks: []u64,
) bool {
    if (values.len == 0 or
        values.len > max_large_native_sequence_count or
        states.len != values.len or
        viable_masks.len != values.len or
        symbols.len == 0 or
        symbols.len > max_predefined_sequence_states) return false;

    // One viability mask per input value is enough to reconstruct the same
    // lowest-state path as the small planner. This keeps temporary planning
    // memory linear in the sequence count instead of count * table states.
    var viable_next: u64 = 0;
    var pos = values.len;
    while (pos > 0) {
        pos -= 1;
        var viable_current: u64 = 0;
        var encodable_states = predefinedEncodableStateMask(values[pos], symbols, min_additional_bits);
        while (encodable_states != 0) {
            const state: usize = @ctz(encodable_states);
            encodable_states &= encodable_states - 1;
            if (pos == values.len - 1) {
                viable_current |= @as(u64, 1) << @intCast(state);
                continue;
            }

            const symbol = symbols[state];
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            const first_next: usize = symbol.next_state;
            const end_next = @min(symbols.len, first_next + transition_count);
            if (first_next >= end_next) continue;
            const width = end_next - first_next;
            const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
            const possible = viable_next & (low_mask << @intCast(first_next));
            if (possible == 0) continue;
            viable_current |= @as(u64, 1) << @intCast(state);
        }
        viable_next = viable_current;
        viable_masks[pos] = viable_current;
    }

    if (viable_next == 0) return false;
    states[0] = @intCast(@ctz(viable_next));
    for (0..values.len - 1) |i| {
        const symbol = symbols[states[i]];
        const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
        const first_next: usize = symbol.next_state;
        const end_next = @min(symbols.len, first_next + transition_count);
        if (first_next >= end_next) return false;
        const width = end_next - first_next;
        const low_mask = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;
        const possible = viable_masks[i + 1] & (low_mask << @intCast(first_next));
        if (possible == 0) return false;
        states[i + 1] = @intCast(@ctz(possible));
        if (states[i + 1] >= symbols.len) return false;
    }
    return true;
}

fn planPredefinedSequenceValuesReference(values: []const usize, symbols: []const SequenceSymbol, min_additional_bits: u8) Error!?PredefinedSequencePlan {
    if (values.len == 0 or values.len > max_native_sequence_count) return null;
    if (symbols.len > max_predefined_sequence_states) return null;

    var next_choice: [max_native_sequence_count][max_predefined_sequence_states]usize = undefined;
    for (&next_choice) |*row| @memset(row[0..], max_predefined_sequence_states);
    var viable_next: [max_predefined_sequence_states]bool = @splat(false);
    var pos = values.len;
    while (pos > 0) {
        pos -= 1;
        var viable_current: [max_predefined_sequence_states]bool = @splat(false);
        for (symbols, 0..) |symbol, state| {
            if (!predefinedSymbolCanEncode(symbol, values[pos], min_additional_bits)) continue;
            if (pos == values.len - 1) {
                viable_current[state] = true;
                continue;
            }
            const transition_count: usize = @as(usize, 1) << @intCast(symbol.state_bits);
            for (0..transition_count) |bits| {
                const next_state = symbol.next_state + bits;
                if (next_state >= symbols.len or !viable_next[next_state]) continue;
                viable_current[state] = true;
                next_choice[pos][state] = next_state;
                break;
            }
        }
        viable_next = viable_current;
    }

    var first_state: ?usize = null;
    for (viable_next[0..symbols.len], 0..) |viable, state| if (viable) {
        first_state = state;
        break;
    };
    var plan: PredefinedSequencePlan = .{ .len = values.len };
    plan.states[0] = @intCast(first_state orelse return null);
    for (0..values.len - 1) |i| plan.states[i + 1] = @intCast(next_choice[i][plan.states[i]]);
    return plan;
}

test "zstd compact predefined planner matches usize reference" {
    var values: [max_bootstrap_sequence_count]usize = undefined;
    var state: u32 = 0x6a09_e667;
    const cases = [_]struct { []const SequenceSymbol, u8, usize }{
        .{ &sequence_predefined.literal_symbols, 0, 4096 },
        .{ &sequence_predefined.offset_symbols, 2, 32 * 1024 },
        .{ &sequence_predefined.match_symbols, 0, 1024 },
    };
    for (cases) |case| {
        for (1..values.len + 1) |len| {
            for (values[0..len]) |*value| {
                state = state *% 1_664_525 +% 1_013_904_223;
                value.* = (state >> 16) % case[2];
            }
            const expected = try planPredefinedSequenceValuesReference(values[0..len], case[0], case[1]);
            const actual = try planPredefinedSequenceValues(values[0..len], case[0], case[1]);
            try std.testing.expectEqual(expected == null, actual == null);
            if (expected) |expected_plan| {
                const actual_plan = actual.?;
                try std.testing.expectEqual(expected_plan.len, actual_plan.len);
                for (expected_plan.states[0..len], actual_plan.states[0..len]) |expected_state, actual_state| {
                    try std.testing.expectEqual(expected_state, actual_state);
                }
            }
        }
    }
}

test "zstd code-based predefined planner matches canonical value planner" {
    var values: [max_native_sequence_count]usize = undefined;
    var codes: [max_native_sequence_count]u8 = undefined;
    var state: u32 = 0x510e_527f;
    const cases = [_]struct { SequenceTableKind, usize }{
        .{ .literal, 131_071 },
        .{ .offset, 32 * 1024 },
        .{ .match, 131_074 },
    };
    for (cases) |case| {
        for ([_]usize{ 1, 2, 12, 31, 127, 256, max_native_sequence_count }) |len| {
            for (0..32) |_| {
                for (values[0..len], codes[0..len]) |*value, *code| {
                    state = state *% 1_664_525 +% 1_013_904_223;
                    value.* = switch (case[0]) {
                        .literal => (state >> 8) % (case[1] + 1),
                        .offset => 1 + (state % case[1]),
                        .match => lz77.min_match_len + (state % (case[1] - lz77.min_match_len + 1)),
                    };
                    code.* = try sequenceCodeForValue(value.*, sequenceTableBases(case[0]), sequenceTableBits(case[0]));
                }
                const expected = try planPredefinedSequenceValues(
                    values[0..len],
                    sequenceTablePredefinedSymbols(case[0]),
                    sequenceTablePredefinedMinAdditionalBits(case[0]),
                );
                const actual = try planPredefinedSequenceCodes(
                    codes[0..len],
                    sequenceTablePredefinedSymbols(case[0]),
                    case[0],
                );
                const code_reference = try planPredefinedSequenceCodesReference(
                    codes[0..len],
                    sequenceTablePredefinedSymbols(case[0]),
                    case[0],
                );
                try std.testing.expectEqual(code_reference == null, actual == null);
                if (code_reference) |want| {
                    const got = actual.?;
                    try std.testing.expectEqual(want.len, got.len);
                    try std.testing.expectEqualSlices(u8, want.states[0..want.len], got.states[0..got.len]);
                }
                try std.testing.expectEqual(expected == null, actual == null);
                if (expected) |want| {
                    const got = actual.?;
                    try std.testing.expectEqual(want.len, got.len);
                    try std.testing.expectEqualSlices(u8, want.states[0..want.len], got.states[0..got.len]);
                }
            }
        }
    }

    const repcode_cases = [_][]const u8{
        &.{0},
        &.{1},
        &.{ 0, 1, 0, 1 },
        &.{ 1, 0, 2, 1, 0, 3 },
        &.{ 0, 1, 2, 3, 4, 5, 1, 0 },
    };
    for (repcode_cases) |offset_codes| {
        const expected = try planPredefinedSequenceCodesReference(
            offset_codes,
            &sequence_predefined.offset_symbols,
            .offset,
        );
        const actual = try planPredefinedSequenceCodes(
            offset_codes,
            &sequence_predefined.offset_symbols,
            .offset,
        );
        try std.testing.expectEqual(expected == null, actual == null);
        if (expected) |want| {
            const got = actual.?;
            try std.testing.expectEqual(want.len, got.len);
            try std.testing.expectEqualSlices(u8, want.states[0..want.len], got.states[0..got.len]);
        }
    }
}

fn predefinedSymbolCanEncode(symbol: SequenceSymbol, value: usize, min_additional_bits: u8) bool {
    if (symbol.additional_bits < min_additional_bits) return false;
    if (value < symbol.base) return false;
    const span: usize = @as(usize, 1) << @intCast(symbol.additional_bits);
    return value - symbol.base < span;
}

fn predefinedSequenceReadFields(
    out: []BitField,
    literal_plan: PredefinedSequencePlan,
    offset_plan: PredefinedSequencePlan,
    match_plan: PredefinedSequencePlan,
    literal_lens: []const usize,
    offsets: []const usize,
    match_lens: []const usize,
) Error!usize {
    if (literal_plan.len != offset_plan.len or literal_plan.len != match_plan.len) return error.CorruptFrame;
    if (literal_lens.len != literal_plan.len or offsets.len != literal_plan.len or match_lens.len != literal_plan.len) return error.CorruptFrame;
    const needed = 3 + literal_plan.len * 3 + if (literal_plan.len > 1) (literal_plan.len - 1) * 3 else 0;
    if (out.len < needed) return error.OutputTooSmall;

    var count: usize = 0;
    try appendBitField(out, &count, literal_plan.states[0], 6);
    try appendBitField(out, &count, offset_plan.states[0], 5);
    try appendBitField(out, &count, match_plan.states[0], 6);

    for (0..literal_plan.len) |i| {
        const literal_symbol = sequence_predefined.literal_symbols[literal_plan.states[i]];
        const offset_symbol = sequence_predefined.offset_symbols[offset_plan.states[i]];
        const match_symbol = sequence_predefined.match_symbols[match_plan.states[i]];

        try appendBitField(out, &count, offsets[i] - offset_symbol.base, offset_symbol.additional_bits);
        try appendBitField(out, &count, match_lens[i] - match_symbol.base, match_symbol.additional_bits);
        try appendBitField(out, &count, literal_lens[i] - literal_symbol.base, literal_symbol.additional_bits);

        if (i + 1 < literal_plan.len) {
            try appendBitField(out, &count, literal_plan.states[i + 1] - literal_symbol.next_state, literal_symbol.state_bits);
            try appendBitField(out, &count, match_plan.states[i + 1] - match_symbol.next_state, match_symbol.state_bits);
            try appendBitField(out, &count, offset_plan.states[i + 1] - offset_symbol.next_state, offset_symbol.state_bits);
        }
    }
    return count;
}

fn appendBitField(out: []BitField, count: *usize, value: usize, bits: u8) Error!void {
    if (count.* >= out.len) return error.OutputTooSmall;
    out[count.*] = .{ .value = value, .bits = bits };
    count.* += 1;
}

fn emitReverseBitstreamFromReadOrder(allocator: std.mem.Allocator, out: *std.ArrayList(u8), read_fields: []const BitField) Error!void {
    if (read_fields.len > max_native_sequence_count * 6) return error.OutputTooSmall;
    var writer: ReverseBitstreamWriter = .{};
    var i = read_fields.len;
    while (i > 0) {
        i -= 1;
        const field = read_fields[i];
        if (field.bits > @bitSizeOf(usize) or
            (field.bits == 0 and field.value != 0) or
            (field.bits != 0 and field.value >= (@as(usize, 1) << @intCast(field.bits)))) return error.CorruptFrame;
        try writer.addBits(allocator, out, field.value, field.bits);
    }
    try writer.finish(allocator, out);
}

fn emitReverseBitstreamFromReadOrderReference(allocator: std.mem.Allocator, out: *std.ArrayList(u8), read_fields: []const BitField) Error!void {
    var reversed: [max_native_sequence_count * 6]BitField = undefined;
    if (read_fields.len > reversed.len) return error.OutputTooSmall;
    for (read_fields, 0..) |field, i| reversed[read_fields.len - 1 - i] = field;
    try emitReverseBitstream(allocator, out, reversed[0..read_fields.len]);
}

test "zstd reverse bitstream direct reverse traversal matches copied reference" {
    var fields: [max_native_sequence_count * 6]BitField = undefined;
    var random_state: u32 = 0x9e37_79b9;
    const lengths = [_]usize{ 0, 1, 2, 7, 31, 127, 511, 1024, fields.len };
    for (lengths) |len| {
        for (fields[0..len]) |*field| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            const bits: u8 = @intCast((random_state >> 27) % 16);
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            field.* = .{
                .value = if (bits == 0) 0 else @as(usize, random_state) & ((@as(usize, 1) << @intCast(bits)) - 1),
                .bits = bits,
            };
        }
        var expected: std.ArrayList(u8) = .empty;
        defer expected.deinit(std.testing.allocator);
        try emitReverseBitstreamFromReadOrderReference(std.testing.allocator, &expected, fields[0..len]);
        var actual: std.ArrayList(u8) = .empty;
        defer actual.deinit(std.testing.allocator);
        try emitReverseBitstreamFromReadOrder(std.testing.allocator, &actual, fields[0..len]);
        try std.testing.expectEqualSlices(u8, expected.items, actual.items);
    }

    var invalid = [_]BitField{.{ .value = 1, .bits = 0 }};
    var expected: std.ArrayList(u8) = .empty;
    defer expected.deinit(std.testing.allocator);
    try std.testing.expectError(error.CorruptFrame, emitReverseBitstreamFromReadOrderReference(std.testing.allocator, &expected, &invalid));
    var actual: std.ArrayList(u8) = .empty;
    defer actual.deinit(std.testing.allocator);
    try std.testing.expectError(error.CorruptFrame, emitReverseBitstreamFromReadOrder(std.testing.allocator, &actual, &invalid));

    var too_many: [max_native_sequence_count * 6 + 1]BitField = undefined;
    @memset(&too_many, .{ .value = 0, .bits = 0 });
    try std.testing.expectError(error.OutputTooSmall, emitReverseBitstreamFromReadOrderReference(std.testing.allocator, &expected, &too_many));
    try std.testing.expectError(error.OutputTooSmall, emitReverseBitstreamFromReadOrder(std.testing.allocator, &actual, &too_many));

    invalid[0] = .{ .value = 0, .bits = @bitSizeOf(usize) + 1 };
    try std.testing.expectError(error.CorruptFrame, emitReverseBitstreamFromReadOrderReference(std.testing.allocator, &expected, &invalid));
    try std.testing.expectError(error.CorruptFrame, emitReverseBitstreamFromReadOrder(std.testing.allocator, &actual, &invalid));
}

fn emitReverseBitstream(allocator: std.mem.Allocator, out: *std.ArrayList(u8), fields: []const BitField) Error!void {
    var accumulator: usize = 0;
    var bit_count: u6 = 0;
    for (fields) |field| {
        if (field.bits > @bitSizeOf(usize) or field.value >= (@as(usize, 1) << @intCast(field.bits))) return error.CorruptFrame;
        accumulator |= field.value << bit_count;
        bit_count += @intCast(field.bits);
        while (bit_count >= 8) {
            try out.append(allocator, @truncate(accumulator));
            accumulator >>= 8;
            bit_count -= 8;
        }
    }
    accumulator |= @as(usize, 1) << bit_count;
    bit_count += 1;
    while (bit_count > 0) {
        try out.append(allocator, @truncate(accumulator));
        if (bit_count <= 8) break;
        accumulator >>= 8;
        bit_count -= 8;
    }
}

fn findRepeatedPatternSegment(block: []const u8) ?RepeatedPatternSegment {
    return findRepeatedPatternSegmentIn(block, 0, block.len);
}

fn findRepeatedPatternSegmentReference(block: []const u8, start_min: usize, end: usize) ?RepeatedPatternSegment {
    if (block.len < 8 or start_min >= end or end - start_min < 8) return null;
    const max_start = @min(start_min + repeated_pattern_start_scan, end - 4);
    var best: ?RepeatedPatternSegment = null;
    for (start_min..max_start + 1) |start| {
        if (end - start < 8) break;
        for (2..@min((end - start) / 2, repeated_pattern_period_max) + 1) |period| {
            var i = start + period;
            while (i < end and block[i] == block[start + ((i - start) % period)]) : (i += 1) {}
            const match_len = i - start - period;
            if (match_len < 3) continue;
            const candidate: RepeatedPatternSegment = .{ .start = start, .period = period, .match_len = match_len, .tail_len = end - i };
            if (best == null or candidate.match_len > best.?.match_len) best = candidate;
        }
    }
    return best;
}

fn findRepeatedPatternSegmentIn(block: []const u8, start_min: usize, end: usize) ?RepeatedPatternSegment {
    if (block.len < 8) return null;
    if (start_min >= end or end - start_min < 8) return null;
    const max_start = @min(start_min + repeated_pattern_start_scan, end - 4);
    var best: ?RepeatedPatternSegment = null;
    for (start_min..max_start + 1) |start| {
        if (end - start < 8) break;
        for (2..@min((end - start) / 2, repeated_pattern_period_max) + 1) |period| {
            // A usable Zstd match needs at least three bytes. Reject the
            // overwhelmingly common non-periods before entering the dependent
            // extension loop.
            if (!std.mem.eql(u8, block[start..][0..3], block[start + period ..][0..3])) continue;
            var i = start + period;
            while (i < end and block[i] == block[start + ((i - start) % period)]) : (i += 1) {}
            const repeated_len = i - start;
            const match_len = repeated_len - period;
            if (match_len < 3) continue;
            const tail_len = end - i;
            const candidate: RepeatedPatternSegment = .{ .start = start, .period = period, .match_len = match_len, .tail_len = tail_len };
            if (best == null or candidate.match_len > best.?.match_len) best = candidate;
        }
    }
    return best;
}

test "zstd repeated pattern anchor filter matches reference" {
    var payload: [512]u8 = undefined;
    for (0..32) |seed| {
        var state: u32 = @intCast(0x9e37_79b9 + seed * 97);
        for (&payload) |*byte| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = @truncate(state >> 24);
        }
        if (seed % 3 == 0) {
            const repeated = payload[321..345].*;
            @memcpy(payload[333..357], &repeated);
        }
        for ([_]usize{ 0, 1, 17, 129, 400 }) |start_min| {
            try std.testing.expectEqual(
                findRepeatedPatternSegmentReference(&payload, start_min, payload.len),
                findRepeatedPatternSegmentIn(&payload, start_min, payload.len),
            );
        }
    }
}

fn sequenceCodeForValue(value: usize, bases: []const usize, bits: []const u8) Error!u8 {
    // All encoder hot paths use these three canonical tables. Their ranges are
    // monotone even though the predefined FSE states are not, so direct
    // arithmetic avoids rescanning 32-53 entries for every candidate value.
    if (bases.ptr == ll_base[0..].ptr and bits.ptr == ll_bits[0..].ptr) return literalLengthCode(value);
    if (bases.ptr == ml_base[0..].ptr and bits.ptr == ml_bits[0..].ptr) return matchLengthCode(value);
    if (bases.ptr == of_base[0..].ptr and bits.ptr == of_bits[0..].ptr) return offsetCode(value);
    return sequenceCodeForValueReference(value, bases, bits);
}

fn literalLengthCode(value: usize) Error!u8 {
    if (value <= 15) return @intCast(value);
    if (value < 24) {
        const code: usize = 16 + (value - 16) / 2;
        return @intCast(code);
    }
    if (value < 32) return @intCast(20 + (value - 24) / 4);
    if (value < 48) return @intCast(22 + (value - 32) / 8);
    if (value < 64) return 24;
    const log = std.math.log2_int(usize, value);
    const code: usize = 19 + log;
    if (code >= ll_base.len or value < ll_base[code] or value - ll_base[code] >= (@as(usize, 1) << @intCast(ll_bits[code]))) return error.CorruptFrame;
    return @intCast(code);
}

fn matchLengthCode(value: usize) Error!u8 {
    if (value < 3) return error.CorruptFrame;
    if (value <= 34) return @intCast(value - 3);
    if (value < 43) return @intCast(32 + (value - 35) / 2);
    if (value < 51) return @intCast(36 + (value - 43) / 4);
    if (value < 67) return @intCast(38 + (value - 51) / 8);
    if (value < 99) return @intCast(40 + (value - 67) / 16);
    if (value < 131) return 42;
    const log = std.math.log2_int(usize, value - 3);
    const code: usize = 36 + log;
    if (code >= ml_base.len or value < ml_base[code] or value - ml_base[code] >= (@as(usize, 1) << @intCast(ml_bits[code]))) return error.CorruptFrame;
    return @intCast(code);
}

fn offsetCode(value: usize) Error!u8 {
    if (value == 0) return 0;
    const code: usize = std.math.log2_int(usize, value + 3);
    if (code >= of_base.len or value < of_base[code] or value - of_base[code] >= (@as(usize, 1) << @intCast(of_bits[code]))) return error.CorruptFrame;
    return @intCast(code);
}

fn sequenceCodeForValueReference(value: usize, bases: []const usize, bits: []const u8) Error!u8 {
    var best: ?usize = null;
    for (bases, 0..) |base, code| {
        const bit_count = bits[code];
        if (value < base) continue;
        const span = @as(usize, 1) << @intCast(bit_count);
        if (value - base >= span) continue;
        if (best == null or base >= bases[best.?]) best = code;
    }
    return @intCast(best orelse return error.CorruptFrame);
}

test "zstd fast sequence codes match table scan" {
    const cases = [_]struct { []const usize, []const u8, usize }{
        .{ &ll_base, &ll_bits, 131_071 },
        .{ &ml_base, &ml_bits, 131_074 },
        .{ &of_base, &of_bits, 1 << 20 },
    };
    for (cases) |case| {
        for (0..case[2] + 1) |value| {
            const expected = sequenceCodeForValueReference(value, case[0], case[1]);
            const actual = sequenceCodeForValue(value, case[0], case[1]);
            if (expected) |code| {
                const actual_code = actual catch |err| {
                    std.debug.print("sequence code unexpected error case={*} value={} error={}\n", .{ case[0].ptr, value, err });
                    return err;
                };
                if (code != actual_code) std.debug.print("sequence code mismatch case={*} value={} expected={} actual={}\n", .{ case[0].ptr, value, code, actual_code });
                try std.testing.expectEqual(code, actual_code);
            } else |expected_error| {
                try std.testing.expectError(expected_error, actual);
            }
        }
    }
}

fn emitLiteralsHeader(allocator: std.mem.Allocator, out: *std.ArrayList(u8), kind: LiteralsKind, regenerated_size: usize) Error!void {
    _ = try literalsHeaderLen(regenerated_size);
    const kind_bits: u8 = switch (kind) {
        .raw => 0,
        .rle => 1,
        .compressed, .treeless => return error.CorruptFrame,
    };
    if (regenerated_size <= 31) {
        try out.append(allocator, kind_bits | @as(u8, @intCast(regenerated_size << 3)));
    } else if (regenerated_size <= 4095) {
        const low: u8 = @intCast(regenerated_size & 0x0f);
        const high: u8 = @intCast(regenerated_size >> 4);
        try out.append(allocator, kind_bits | (1 << 2) | (low << 4));
        try out.append(allocator, high);
    } else {
        const low: u8 = @intCast(regenerated_size & 0x0f);
        const mid: u8 = @intCast((regenerated_size >> 4) & 0xff);
        const high: u8 = @intCast(regenerated_size >> 12);
        try out.append(allocator, kind_bits | (3 << 2) | (low << 4));
        try out.append(allocator, mid);
        try out.append(allocator, high);
    }
}

fn literalsHeaderLen(regenerated_size: usize) Error!usize {
    if (regenerated_size > std.math.maxInt(u20)) return error.IntegerOverflow;
    if (regenerated_size <= 31) return 1;
    if (regenerated_size <= 4095) return 2;
    return 3;
}

fn emitHuffmanLiteralsHeader(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    regenerated_size: usize,
    compressed_size: usize,
    treeless: bool,
) Error!?void {
    if (compressed_size == 0) return error.CorruptFrame;
    const kind_bits: u8 = if (treeless) 0x03 else 0x02;
    if (regenerated_size <= 0x3ff and compressed_size <= 0x3ff) {
        const value = regenerated_size | (compressed_size << 10);
        try out.append(allocator, kind_bits | (@as(u8, @intCast(value & 0x0f)) << 4));
        try out.append(allocator, @truncate(value >> 4));
        try out.append(allocator, @truncate(value >> 12));
    } else if (regenerated_size <= 0x3fff and compressed_size <= 0x3fff) {
        const value = regenerated_size | (compressed_size << 14);
        try out.append(allocator, kind_bits | (2 << 2) | (@as(u8, @intCast(value & 0x0f)) << 4));
        try out.append(allocator, @truncate(value >> 4));
        try out.append(allocator, @truncate(value >> 12));
        try out.append(allocator, @truncate(value >> 20));
    } else if (regenerated_size <= 0x3ffff and compressed_size <= 0x3ffff) {
        const value = regenerated_size | (compressed_size << 18);
        try out.append(allocator, kind_bits | (3 << 2) | (@as(u8, @intCast(value & 0x0f)) << 4));
        try out.append(allocator, @truncate(value >> 4));
        try out.append(allocator, @truncate(value >> 12));
        try out.append(allocator, @truncate(value >> 20));
        try out.append(allocator, @truncate(value >> 28));
    } else return null;
}

fn emitCompressedLiteralsHeader(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    regenerated_size: usize,
    compressed_size: usize,
) Error!void {
    _ = try emitHuffmanLiteralsHeader(allocator, out, regenerated_size, compressed_size, false) orelse return error.UnsupportedZstdFeature;
}

fn emitRawBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block: []const u8, last: bool) Error!void {
    try emitBlockHeader(allocator, out, 0, block.len, last);
    try out.appendSlice(allocator, block);
}

fn emitRleBlock(allocator: std.mem.Allocator, out: *std.ArrayList(u8), byte: u8, len: usize, last: bool) Error!void {
    try emitBlockHeader(allocator, out, 1, len, last);
    try out.append(allocator, byte);
}

fn emitBlockHeader(allocator: std.mem.Allocator, out: *std.ArrayList(u8), block_type: u32, block_len: usize, last: bool) Error!void {
    if (block_len > std.compress.zstd.block_size_max) return error.IntegerOverflow;
    const header_value: u32 = (@as(u32, @intCast(block_len)) << 3) |
        (block_type << 1) |
        @as(u32, if (last) 1 else 0);
    const header: [3]u8 = .{
        @truncate(header_value),
        @truncate(header_value >> 8),
        @truncate(header_value >> 16),
    };
    try out.appendSlice(allocator, &header);
}

fn checkedUsizeToU64(value: usize) Error!u64 {
    return std.math.cast(u64, value) orelse error.IntegerOverflow;
}

fn checkedUsizeToU32(value: usize) Error!u32 {
    return std.math.cast(u32, value) orelse error.IntegerOverflow;
}

fn checkedU64ToUsize(value: u64) Error!usize {
    return std.math.cast(usize, value) orelse error.IntegerOverflow;
}

fn checkedU64ToU32(value: u64) Error!u32 {
    return std.math.cast(u32, value) orelse error.IntegerOverflow;
}

