test "zstd pure Zig facade decoder enforces allocation limits" {
    const payload = "zstd limited decode payload" ** 8;

    const known_size = try encodeFrameAlloc(std.testing.allocator, payload);
    defer std.testing.allocator.free(known_size);
    try std.testing.expectEqual(payload.len, try decodedFrameSize(known_size));
    try std.testing.expectEqual(payload.len, try decodedFrameSizeLimited(known_size, payload.len));
    try std.testing.expectError(error.OutputLimitExceeded, decodedFrameSizeLimited(known_size, payload.len - 1));
    const known_decoded = try decodeFrameAllocLimited(std.testing.allocator, known_size, payload.len);
    defer std.testing.allocator.free(known_decoded);
    try std.testing.expectEqualSlices(u8, payload, known_decoded);
    try std.testing.expectError(error.OutputLimitExceeded, decodeFrameAllocLimited(std.testing.allocator, known_size, payload.len - 1));
    var known_into_buffer: [payload.len]u8 = undefined;
    const known_written = try decodeFrameInto(known_size, &known_into_buffer);
    try std.testing.expectEqual(payload.len, known_written);
    try std.testing.expectEqualSlices(u8, payload, known_into_buffer[0..known_written]);
    try std.testing.expectError(error.OutputTooSmall, decodeFrameInto(known_size, known_into_buffer[0 .. known_into_buffer.len - 1]));

    const no_size = try encodeFrameWithOptionsAlloc(std.testing.allocator, payload, .{ .include_content_size = false });
    defer std.testing.allocator.free(no_size);
    try std.testing.expectEqual(payload.len, try decodedFrameSize(no_size));
    try std.testing.expectEqual(payload.len, try decodedFrameSizeLimited(no_size, payload.len));
    try std.testing.expectError(error.OutputLimitExceeded, decodedFrameSizeLimited(no_size, payload.len - 1));
    const no_size_decoded = try decodeFrameAllocLimited(std.testing.allocator, no_size, payload.len);
    defer std.testing.allocator.free(no_size_decoded);
    try std.testing.expectEqualSlices(u8, payload, no_size_decoded);
    try std.testing.expectError(error.OutputLimitExceeded, decodeFrameAllocLimited(std.testing.allocator, no_size, payload.len - 1));
    const no_size_into_buffer = try std.testing.allocator.alloc(u8, payload.len);
    defer std.testing.allocator.free(no_size_into_buffer);
    const no_size_written = try decodeFrameInto(no_size, no_size_into_buffer);
    try std.testing.expectEqual(payload.len, no_size_written);
    try std.testing.expectEqualSlices(u8, payload, no_size_into_buffer[0..no_size_written]);
    try std.testing.expectError(error.OutputTooSmall, decodeFrameInto(no_size, no_size_into_buffer[0 .. payload.len - 1]));
}

fn fillNonRlePayload(payload: []u8) void {
    for (payload, 0..) |*byte, i| {
        // A full-period byte progression avoids the long equal-byte runs that
        // the raw/RLE writer would intentionally split into RLE blocks. Tests
        // that assert exact encoded bounds can then reason about one raw block
        // per configured Zstd block without depending on match heuristics.
        byte.* = @intCast((i * 73 + 19) & 0xff);
    }
}

test "zstd native encoded bound follows emitted frame header widths" {
    const cases = [_]struct {
        len: usize,
        expected_descriptor: u8,
        expected_payload_offset: usize,
    }{
        .{ .len = 0, .expected_descriptor = 0x20, .expected_payload_offset = 6 },
        .{ .len = 255, .expected_descriptor = 0x20, .expected_payload_offset = 6 },
        .{ .len = 300, .expected_descriptor = 0x60, .expected_payload_offset = 7 },
        .{ .len = 70_000, .expected_descriptor = 0xa0, .expected_payload_offset = 9 },
    };

    for (cases) |case| {
        const payload = try std.testing.allocator.alloc(u8, case.len);
        defer std.testing.allocator.free(payload);
        fillNonRlePayload(payload);

        const options: NativeFrameOptions = .{
            .selection = .raw_or_rle,
            .content_checksum = false,
        };
        const encoded = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, payload, options);
        defer std.testing.allocator.free(encoded);
        const bound = try encodedNativeFrameBoundWithOptions(payload.len, options);
        try std.testing.expectEqual(encoded.len, bound);
        try std.testing.expectEqual(case.expected_descriptor, encoded[4]);
        try std.testing.expectEqual(case.expected_payload_offset, (try inspectNativeFrameHeader(encoded)).payload_offset);

        const into = try std.testing.allocator.alloc(u8, bound);
        defer std.testing.allocator.free(into);
        const into_result = try encodeNativeFrameIntoSlice(std.testing.allocator, payload, options, into);
        try std.testing.expectEqual(NativeFrameMode.raw_or_rle, into_result.mode);
        try std.testing.expectEqualSlices(u8, encoded, into[0..into_result.written]);
        try std.testing.expectError(error.OutputTooSmall, encodeNativeFrameIntoSlice(std.testing.allocator, payload, options, into[0 .. into.len - 1]));
    }

    const payload = try std.testing.allocator.alloc(u8, 300);
    defer std.testing.allocator.free(payload);
    fillNonRlePayload(payload);

    const no_size_options: NativeFrameOptions = .{
        .selection = .raw_or_rle,
        .content_checksum = false,
        .include_content_size = false,
    };
    const no_size = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, payload, no_size_options);
    defer std.testing.allocator.free(no_size);
    try std.testing.expectEqual(no_size.len, try encodedNativeFrameBoundWithOptions(payload.len, no_size_options));
    try std.testing.expectEqual(@as(u8, 0x00), no_size[4]);
    try std.testing.expectEqual(@as(usize, 6), (try inspectNativeFrameHeader(no_size)).payload_offset);

    const dictionary_options: NativeFrameOptions = .{
        .selection = .raw_or_rle,
        .content_checksum = false,
        .dictionary_id = 0x1234,
    };
    const with_dictionary_id = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, payload, dictionary_options);
    defer std.testing.allocator.free(with_dictionary_id);
    try std.testing.expectEqual(with_dictionary_id.len, try encodedNativeFrameBoundWithOptions(payload.len, dictionary_options));
    const dictionary_header = try inspectNativeFrameHeader(with_dictionary_id);
    try std.testing.expectEqual(@as(u32, 0x1234), dictionary_header.dictionary_id);
    try std.testing.expectEqual(@as(usize, 9), dictionary_header.payload_offset);

    try std.testing.expectEqual(@as(usize, 13), try nativeFrameHeaderLen(@as(u64, std.math.maxInt(u32)) + 1, .{}));
}

test "zstd raw/RLE frame writer round trips through std decompressor" {
    const payload = "zstd raw block payload zstd raw block payload";
    const encoded = try encodeRawOrRleFrameAlloc(std.testing.allocator, payload);
    defer std.testing.allocator.free(encoded);
    const decoded = try decodeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
    const native_decoded = try decodeRawOrRleFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(native_decoded);
    try std.testing.expectEqualSlices(u8, payload, native_decoded);
    try std.testing.expectEqual(payload.len, try decodedRawOrRleFrameSize(encoded));
    const first_block = try inspectNativeFrameFirstBlock(encoded);
    try std.testing.expectEqual(NativeBlockType.raw, first_block.block_type);
    try std.testing.expectEqual(true, first_block.last);
    try std.testing.expectEqual(payload.len, first_block.payload_len);
    const raw_modes = try inspectNativeFrameBlockSequenceModes(encoded, first_block);
    try std.testing.expectEqual(NativeLiteralsKind.raw, raw_modes.literals_kind);
    try std.testing.expectEqual(payload.len, raw_modes.regenerated_literals_size);
    try std.testing.expectEqual(@as(usize, 0), raw_modes.sequence_count);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, raw_modes.literal_length_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, raw_modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, raw_modes.match_length_mode);
    try std.testing.expectEqual((try inspectNativeFrameHeader(encoded)).payload_offset, first_block.header_offset);
    try std.testing.expectEqual(first_block.payload_offset + first_block.payload_len, first_block.next_header_offset);
    const first_block_again = try inspectNativeFrameBlockAt(encoded, first_block.header_offset);
    try std.testing.expectEqual(first_block.next_header_offset, first_block_again.next_header_offset);
    const raw_summary = try summarizeNativeFrameBlocks(encoded);
    try std.testing.expectEqual(@as(usize, 1), raw_summary.block_count);
    try std.testing.expectEqual(@as(usize, 1), raw_summary.raw_block_count);
    try std.testing.expectEqual(payload.len, raw_summary.payload_bytes);
    const raw_stream_summary = try summarizeNativeStream(encoded);
    try std.testing.expectEqual(@as(usize, 1), raw_stream_summary.frame_count);
    try std.testing.expectEqual(@as(usize, 1), raw_stream_summary.block_count);
    try std.testing.expectEqual(payload.len, raw_stream_summary.payload_bytes);
    var block_iterator = try iterateNativeFrameBlocks(encoded);
    var iterated_block_count: usize = 0;
    var iterated_payload_bytes: usize = 0;
    while (try block_iterator.next()) |block| {
        iterated_block_count += 1;
        iterated_payload_bytes += block.payload_len;
        try std.testing.expectEqual(NativeBlockType.raw, block.block_type);
    }
    try std.testing.expectEqual(raw_summary.block_count, iterated_block_count);
    try std.testing.expectEqual(raw_summary.payload_bytes, iterated_payload_bytes);
    try std.testing.expectEqual(encoded.len, block_iterator.next_header_offset);
    try std.testing.expectEqual(@as(?NativeFrameBlockHeader, null), try block_iterator.next());
    var native_appended: std.ArrayList(u8) = .empty;
    defer native_appended.deinit(std.testing.allocator);
    try native_appended.appendSlice(std.testing.allocator, "prefix:");
    const native_appended_written = try decodeNativeFrameAppend(std.testing.allocator, &native_appended, encoded);
    try std.testing.expectEqual(payload.len, native_appended_written);
    try std.testing.expectEqualSlices(u8, "prefix:", native_appended.items[0.."prefix:".len]);
    try std.testing.expectEqualSlices(u8, payload, native_appended.items["prefix:".len..]);
    try std.testing.expectEqual(payload.len, try decodedRawOrRleFrameSizeLimited(encoded, payload.len));
    try std.testing.expectError(error.OutputLimitExceeded, decodedRawOrRleFrameSizeLimited(encoded, payload.len - 1));
    native_appended.clearRetainingCapacity();
    try native_appended.appendSlice(std.testing.allocator, "prefix:");
    const native_appended_limited_written = try decodeNativeFrameAppendLimited(std.testing.allocator, &native_appended, encoded, payload.len);
    try std.testing.expectEqual(payload.len, native_appended_limited_written);
    try std.testing.expectEqualSlices(u8, "prefix:", native_appended.items[0.."prefix:".len]);
    try std.testing.expectEqualSlices(u8, payload, native_appended.items["prefix:".len..]);
    native_appended.clearRetainingCapacity();
    try native_appended.appendSlice(std.testing.allocator, "prefix:");
    try std.testing.expectError(error.OutputLimitExceeded, decodeNativeFrameAppendLimited(std.testing.allocator, &native_appended, encoded, payload.len - 1));
    try std.testing.expectEqualSlices(u8, "prefix:", native_appended.items);
    var reusable_decoder = NativeFrameDecoder.init(std.testing.allocator);
    defer reusable_decoder.deinit();
    const reusable_decoded = try reusable_decoder.decodeAlloc(encoded);
    defer std.testing.allocator.free(reusable_decoded);
    try std.testing.expectEqualSlices(u8, payload, reusable_decoded);
    const reusable_scratch = try reusable_decoder.decodeScratch(encoded);
    try std.testing.expectEqualSlices(u8, payload, reusable_scratch);
    const reusable_scratch_limited = try reusable_decoder.decodeScratchLimited(encoded, payload.len);
    try std.testing.expectEqualSlices(u8, payload, reusable_scratch_limited);
    try std.testing.expectError(error.OutputLimitExceeded, reusable_decoder.decodeScratchLimited(encoded, payload.len - 1));
    try std.testing.expectEqual(@as(usize, 0), reusable_decoder.scratch.items.len);
    native_appended.clearRetainingCapacity();
    try native_appended.appendSlice(std.testing.allocator, "prefix:");
    const reusable_append_written = try reusable_decoder.decodeAppendLimited(&native_appended, encoded, payload.len);
    try std.testing.expectEqual(payload.len, reusable_append_written);
    try std.testing.expectEqualSlices(u8, payload, native_appended.items["prefix:".len..]);
    var reusable_decode_into: [payload.len]u8 = undefined;
    const reusable_decode_into_written = try reusable_decoder.decodeIntoSlice(encoded, &reusable_decode_into);
    try std.testing.expectEqual(payload.len, reusable_decode_into_written);
    try std.testing.expectEqualSlices(u8, payload, &reusable_decode_into);
    const no_checksum = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, payload, .{ .content_checksum = false });
    defer std.testing.allocator.free(no_checksum);
    try std.testing.expectEqual(@as(u8, 0x20), no_checksum[4]);
    const no_checksum_decoded = try decodeNativeFrameAlloc(std.testing.allocator, no_checksum);
    defer std.testing.allocator.free(no_checksum_decoded);
    try std.testing.expectEqualSlices(u8, payload, no_checksum_decoded);
    const no_size = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, payload, .{ .include_content_size = false });
    defer std.testing.allocator.free(no_size);
    try std.testing.expectEqual(@as(u8, 0x04), no_size[4]);
    const no_size_decoded = try decodeNativeFrameAlloc(std.testing.allocator, no_size);
    defer std.testing.allocator.free(no_size_decoded);
    try std.testing.expectEqualSlices(u8, payload, no_size_decoded);
    const limited_decoded = try decodeRawOrRleFrameAllocLimited(std.testing.allocator, encoded, payload.len);
    defer std.testing.allocator.free(limited_decoded);
    try std.testing.expectEqualSlices(u8, payload, limited_decoded);
    try std.testing.expectError(
        error.OutputLimitExceeded,
        decodeRawOrRleFrameAllocLimited(std.testing.allocator, encoded, payload.len - 1),
    );
    var into_buffer: [payload.len]u8 = undefined;
    const into_written = try decodeRawOrRleFrameInto(encoded, &into_buffer);
    try std.testing.expectEqual(payload.len, into_written);
    try std.testing.expectEqualSlices(u8, payload, into_buffer[0..into_written]);
    try std.testing.expectError(error.OutputTooSmall, decodeRawOrRleFrameInto(encoded, into_buffer[0 .. into_buffer.len - 1]));
    const raw_bound = try encodedNativeFrameBoundWithOptions(payload.len, .{ .selection = .raw_or_rle });
    try std.testing.expectEqual(encoded.len, raw_bound);
    const raw_into = try std.testing.allocator.alloc(u8, raw_bound);
    defer std.testing.allocator.free(raw_into);
    const raw_into_written = try encodeRawOrRleFrameIntoSlice(std.testing.allocator, payload, .{}, raw_into);
    try std.testing.expectEqualSlices(u8, encoded, raw_into[0..raw_into_written]);
    try std.testing.expectError(error.OutputTooSmall, encodeRawOrRleFrameIntoSlice(std.testing.allocator, payload, .{}, raw_into[0 .. raw_into_written - 1]));
    try std.testing.expectEqual(@as(u8, 0x24), encoded[4]);
    try std.testing.expectEqual(@as(u8, payload.len), encoded[5]);

    const repeated = "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx";
    const rle_encoded = try encodeRawOrRleFrameAlloc(std.testing.allocator, repeated);
    defer std.testing.allocator.free(rle_encoded);
    try std.testing.expect(rle_encoded.len < repeated.len);
    var rle_block_offset: usize = 4;
    _ = try parseRawOrRleFrameHeader(rle_encoded, &rle_block_offset);
    const first_block_header = std.mem.readInt(u24, rle_encoded[rle_block_offset..][0..3], .little);
    try std.testing.expectEqual(@as(u24, 1), (first_block_header >> 1) & 0x3);
    const rle_decoded = try decodeFrameAlloc(std.testing.allocator, rle_encoded);
    defer std.testing.allocator.free(rle_decoded);
    try std.testing.expectEqualSlices(u8, repeated, rle_decoded);
    const native_rle_decoded = try decodeRawOrRleFrameAlloc(std.testing.allocator, rle_encoded);
    defer std.testing.allocator.free(native_rle_decoded);
    try std.testing.expectEqualSlices(u8, repeated, native_rle_decoded);
    const rle_first_block = try inspectNativeFrameFirstBlock(rle_encoded);
    try std.testing.expectEqual(NativeBlockType.rle, rle_first_block.block_type);
    try std.testing.expectEqual(repeated.len, rle_first_block.payload_len);
    try std.testing.expectEqual(true, rle_first_block.last);
    const rle_modes = try inspectNativeFrameBlockSequenceModes(rle_encoded, rle_first_block);
    try std.testing.expectEqual(NativeLiteralsKind.rle, rle_modes.literals_kind);
    try std.testing.expectEqual(repeated.len, rle_modes.regenerated_literals_size);
    try std.testing.expectEqual(@as(usize, 0), rle_modes.sequence_count);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, rle_modes.literal_length_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, rle_modes.offset_mode);
    try std.testing.expectEqual(NativeSequenceTableMode.predefined, rle_modes.match_length_mode);
    try std.testing.expectEqual(rle_first_block.payload_offset + 1, rle_first_block.next_header_offset);
    const rle_summary = try summarizeNativeFrameBlocks(rle_encoded);
    try std.testing.expectEqual(@as(usize, 1), rle_summary.block_count);
    try std.testing.expectEqual(@as(usize, 1), rle_summary.rle_block_count);
    try std.testing.expectEqual(repeated.len, rle_summary.payload_bytes);
    const rle_bound = try encodedNativeFrameBound(repeated.len);
    try std.testing.expect(rle_encoded.len <= rle_bound);
    const rle_into = try std.testing.allocator.alloc(u8, rle_bound);
    defer std.testing.allocator.free(rle_into);
    const rle_into_result = try encodeNativeFrameIntoSlice(std.testing.allocator, repeated, .{}, rle_into);
    try std.testing.expectEqual(NativeFrameMode.raw_or_rle, rle_into_result.mode);
    try std.testing.expectEqualSlices(u8, rle_encoded, rle_into[0..rle_into_result.written]);
    try std.testing.expectError(error.OutputTooSmall, encodeNativeFrameIntoSlice(std.testing.allocator, repeated, .{}, rle_into[0 .. rle_into_result.written - 1]));
    var rle_into_buffer: [repeated.len]u8 = undefined;
    const rle_into_written = try decodeNativeFrameInto(rle_encoded, &rle_into_buffer);
    try std.testing.expectEqual(repeated.len, rle_into_written);
    try std.testing.expectEqualSlices(u8, repeated, rle_into_buffer[0..rle_into_written]);
}

test "zstd raw/RLE native decoder handles skippable and concatenated frames" {
    const first = try encodeRawOrRleFrameAlloc(std.testing.allocator, "first");
    defer std.testing.allocator.free(first);
    const second = try encodeRawOrRleFrameAlloc(std.testing.allocator, "second");
    defer std.testing.allocator.free(second);

    var stream: std.ArrayList(u8) = .empty;
    defer stream.deinit(std.testing.allocator);
    try stream.appendSlice(std.testing.allocator, first);
    var skippable_header: [8]u8 = undefined;
    std.mem.writeInt(u32, skippable_header[0..4], skippable_magic_min + 3, .little);
    std.mem.writeInt(u32, skippable_header[4..8], 5, .little);
    try stream.appendSlice(std.testing.allocator, &skippable_header);
    try stream.appendSlice(std.testing.allocator, "noise");
    try stream.appendSlice(std.testing.allocator, second);

    const decoded = try decodeRawOrRleFrameAlloc(std.testing.allocator, stream.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, "firstsecond", decoded);
    const stream_summary = try summarizeNativeStream(stream.items);
    try std.testing.expectEqual(@as(usize, 2), stream_summary.frame_count);
    try std.testing.expectEqual(@as(usize, 1), stream_summary.skippable_frame_count);
    try std.testing.expectEqual(@as(usize, 5), stream_summary.skippable_payload_bytes);
    var stream_iterator = iterateNativeStream(stream.items);
    const first_element = (try stream_iterator.next()) orelse return error.CorruptFrame;
    switch (first_element) {
        .frame => |frame| {
            try std.testing.expectEqual(@as(usize, 0), frame.offset);
            try std.testing.expectEqualSlices(u8, first, frame.bytes);
            var first_blocks = try frame.blockIterator();
            var first_block_count: usize = 0;
            while (try first_blocks.next()) |_| first_block_count += 1;
            try std.testing.expectEqual((try summarizeNativeFrameBlocks(first)).block_count, first_block_count);
        },
        .skippable => return error.CorruptFrame,
    }
    const skip_element = (try stream_iterator.next()) orelse return error.CorruptFrame;
    switch (skip_element) {
        .frame => return error.CorruptFrame,
        .skippable => |skippable| {
            try std.testing.expectEqual(first.len, skippable.offset);
            try std.testing.expectEqualSlices(u8, "noise", skippable.payload);
            try std.testing.expectEqual(@as(u4, 3), skippable.header.skippable_id);
        },
    }
    const second_element = (try stream_iterator.next()) orelse return error.CorruptFrame;
    switch (second_element) {
        .frame => |frame| {
            try std.testing.expectEqual(first.len + 8 + 5, frame.offset);
            try std.testing.expectEqualSlices(u8, second, frame.bytes);
        },
        .skippable => return error.CorruptFrame,
    }
    try std.testing.expect((try stream_iterator.next()) == null);
    const native_concatenated = try decodeNativeConcatenatedFrameAlloc(std.testing.allocator, stream.items);
    defer std.testing.allocator.free(native_concatenated);
    try std.testing.expectEqualSlices(u8, "firstsecond", native_concatenated);
    const native_concatenated_exact = try decodeNativeConcatenatedFrameAllocExactSize(std.testing.allocator, stream.items, "firstsecond".len);
    defer std.testing.allocator.free(native_concatenated_exact);
    try std.testing.expectEqualSlices(u8, "firstsecond", native_concatenated_exact);
    try std.testing.expectError(error.SizeMismatch, decodeNativeConcatenatedFrameAllocExactSize(std.testing.allocator, stream.items, "firstsecond".len - 1));
    try std.testing.expectEqual(@as(usize, "firstsecond".len), try decodedNativeConcatenatedFrameSize(stream.items));
    var appended: std.ArrayList(u8) = .empty;
    defer appended.deinit(std.testing.allocator);
    try appended.appendSlice(std.testing.allocator, "prefix:");
    const appended_written = try decodeRawOrRleFrameAppend(std.testing.allocator, &appended, stream.items);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), appended_written);
    try std.testing.expectEqualSlices(u8, "prefix:firstsecond", appended.items);
    appended.clearRetainingCapacity();
    try appended.appendSlice(std.testing.allocator, "prefix:");
    const appended_limited_written = try decodeRawOrRleFrameAppendLimited(std.testing.allocator, &appended, stream.items, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), appended_limited_written);
    try std.testing.expectEqualSlices(u8, "prefix:firstsecond", appended.items);
    appended.clearRetainingCapacity();
    try appended.appendSlice(std.testing.allocator, "prefix:");
    const native_appended_limited_written = try decodeNativeConcatenatedFrameAppendLimited(std.testing.allocator, &appended, stream.items, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), native_appended_limited_written);
    try std.testing.expectEqualSlices(u8, "prefix:firstsecond", appended.items);
    appended.clearRetainingCapacity();
    try appended.appendSlice(std.testing.allocator, "prefix:");
    try std.testing.expectError(error.OutputLimitExceeded, decodeRawOrRleFrameAppendLimited(std.testing.allocator, &appended, stream.items, "firstsecond".len - 1));
    try std.testing.expectEqualSlices(u8, "prefix:", appended.items);

    var into_buffer: ["firstsecond".len]u8 = undefined;
    const written = try decodeRawOrRleFrameInto(stream.items, &into_buffer);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), written);
    try std.testing.expectEqualSlices(u8, "firstsecond", into_buffer[0..written]);
    @memset(&into_buffer, 0);
    const native_written = try decodeNativeConcatenatedFrameInto(stream.items, &into_buffer);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), native_written);
    try std.testing.expectEqualSlices(u8, "firstsecond", into_buffer[0..native_written]);
    const exact_written = try decodeNativeConcatenatedFrameIntoExactSize(stream.items, &into_buffer, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), exact_written);
    try std.testing.expectEqualSlices(u8, "firstsecond", into_buffer[0..exact_written]);
    try std.testing.expectError(error.OutputTooSmall, decodeNativeConcatenatedFrameIntoExactSize(stream.items, into_buffer[0 .. into_buffer.len - 1], "firstsecond".len));
    try std.testing.expectError(error.SizeMismatch, decodeNativeConcatenatedFrameIntoExactSize(stream.items, &into_buffer, "firstsecond".len - 1));
    var oversized_into: ["firstsecond".len + 1]u8 = undefined;
    try std.testing.expectError(error.SizeMismatch, decodeNativeConcatenatedFrameIntoExactSize(stream.items, &oversized_into, "firstsecond".len + 1));
    var reusable = NativeFrameDecoder.init(std.testing.allocator);
    defer reusable.deinit();
    const reusable_decoded = try reusable.decodeConcatenatedScratch(stream.items);
    try std.testing.expectEqualSlices(u8, "firstsecond", reusable_decoded);
    const reusable_exact_written = try reusable.decodeConcatenatedIntoSliceExactSize(stream.items, &into_buffer, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), reusable_exact_written);
    const chunks = [_][]const u8{
        stream.items[0..4],
        stream.items[4 .. stream.items.len - 3],
        stream.items[stream.items.len - 3 ..],
    };
    const join = try std.testing.allocator.alloc(u8, stream.items.len);
    defer std.testing.allocator.free(join);
    @memset(&into_buffer, 0);
    const chunked_exact_written = try decodeNativeConcatenatedFrameChunksIntoExactSize(&chunks, join, &into_buffer, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), chunked_exact_written);
    try std.testing.expectEqualSlices(u8, "firstsecond", &into_buffer);
    try std.testing.expectError(error.OutputTooSmall, decodeNativeConcatenatedFrameChunksIntoExactSize(&chunks, join, into_buffer[0 .. into_buffer.len - 1], "firstsecond".len));
    try std.testing.expectError(error.SizeMismatch, decodeNativeConcatenatedFrameChunksIntoExactSize(&chunks, join, &into_buffer, "firstsecond".len - 1));
    @memset(&into_buffer, 0);
    const reusable_chunked_exact_written = try reusable.decodeConcatenatedChunksIntoSliceExactSize(&chunks, join, &into_buffer, "firstsecond".len);
    try std.testing.expectEqual(@as(usize, "firstsecond".len), reusable_chunked_exact_written);
    try std.testing.expectEqualSlices(u8, "firstsecond", &into_buffer);
}

test "zstd stream summary resolves dictionary catalogs with diagnostics" {
    const first_dictionary = NativeDictionary.init(0x1234, "first dictionary history");
    const second_dictionary = NativeDictionary.init(0x5678, "second dictionary history");
    const first = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, "first", .{
        .content_checksum = false,
        .dictionary_id = first_dictionary.id,
    });
    defer std.testing.allocator.free(first);
    const second = try encodeRawOrRleFrameWithOptionsAlloc(std.testing.allocator, "second", .{
        .content_checksum = false,
        .dictionary_id = second_dictionary.id,
    });
    defer std.testing.allocator.free(second);

    var stream: std.ArrayList(u8) = .empty;
    defer stream.deinit(std.testing.allocator);
    try stream.appendSlice(std.testing.allocator, first);
    try stream.appendSlice(std.testing.allocator, second);

    const dictionaries = [_]NativeDictionary{ first_dictionary, second_dictionary };
    const summary = try summarizeNativeStreamWithDictionarySet(stream.items, NativeDictionarySet.init(&dictionaries));
    try std.testing.expectEqual(@as(usize, 2), summary.frame_count);
    try std.testing.expectEqual(@as(usize, 2), summary.dictionary_id_frame_count);
    try std.testing.expectEqual(@as(usize, 2), summary.resolved_dictionary_frame_count);
    try std.testing.expectEqual(@as(usize, 0), summary.standard_dictionary_frame_count);

    var diagnostics: NativeStreamSummaryErrorDiagnostics = .{};
    try std.testing.expectError(error.NeedDictionary, summarizeNativeStreamWithDictionaryDiagnostics(stream.items, first_dictionary, &diagnostics));
    try std.testing.expectEqual(NativeStreamSummaryErrorPhase.frame_header, diagnostics.phase);
    try std.testing.expectEqual(first.len, diagnostics.offset);

    const duplicate_dictionaries = [_]NativeDictionary{ first_dictionary, NativeDictionary.init(first_dictionary.id, "duplicate") };
    diagnostics = .{ .phase = .frame, .offset = 99 };
    try std.testing.expectError(
        error.DuplicateDictionaryId,
        summarizeNativeStreamWithDictionarySetAndDiagnostics(stream.items, NativeDictionarySet.init(&duplicate_dictionaries), &diagnostics),
    );
    try std.testing.expectEqual(NativeStreamSummaryErrorPhase.stream, diagnostics.phase);
    try std.testing.expectEqual(@as(usize, 0), diagnostics.offset);
}

test "zstd skippable frame writer composes with native streams" {
    const first = try encodeRawOrRleFrameAlloc(std.testing.allocator, "first");
    defer std.testing.allocator.free(first);
    const skip = try encodeSkippableFrameAlloc(std.testing.allocator, 9, "metadata");
    defer std.testing.allocator.free(skip);
    const second = try encodeLiteralOnlyFrameAlloc(std.testing.allocator, "second");
    defer std.testing.allocator.free(second);

    var stream: std.ArrayList(u8) = .empty;
    defer stream.deinit(std.testing.allocator);
    try stream.appendSlice(std.testing.allocator, first);
    try stream.appendSlice(std.testing.allocator, skip);
    try stream.appendSlice(std.testing.allocator, second);

    try std.testing.expectEqual(skippable_magic_min + 9, std.mem.readInt(u32, skip[0..4], .little));
    try std.testing.expectEqual(@as(u32, "metadata".len), std.mem.readInt(u32, skip[4..8], .little));
    try std.testing.expectEqualSlices(u8, "metadata", skip[8..]);
    const skip_header = try inspectNativeSkippableFrame(skip);
    try std.testing.expectEqual(@as(u4, 9), skip_header.skippable_id);
    try std.testing.expectEqual(@as(usize, 8), skip_header.payload_offset);
    try std.testing.expectEqual(@as(usize, "metadata".len), skip_header.payload_len);
    try std.testing.expectEqual(skip.len, skip_header.next_frame_offset);
    try std.testing.expectEqual(skip.len, try encodedSkippableFrameBound("metadata".len));
    var skip_appended: std.ArrayList(u8) = .empty;
    defer skip_appended.deinit(std.testing.allocator);
    try encodeSkippableFrameAppend(std.testing.allocator, &skip_appended, 9, "metadata");
    try std.testing.expectEqualSlices(u8, skip, skip_appended.items);
    var skip_into: [8 + "metadata".len]u8 = undefined;
    const skip_into_written = try encodeSkippableFrameIntoSlice(9, "metadata", &skip_into);
    try std.testing.expectEqual(skip.len, skip_into_written);
    try std.testing.expectEqualSlices(u8, skip, skip_into[0..skip_into_written]);
    try std.testing.expectError(error.OutputTooSmall, encodeSkippableFrameIntoSlice(9, "metadata", skip_into[0 .. skip_into.len - 1]));

    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, stream.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, "firstsecond", decoded);
}

test "zstd native seekable stream encoder round trips indexed frames" {
    const payload = "alpha-alpha-alpha-beta-beta-gamma-gamma-delta-delta\n";
    inline for (.{ false, true }) |with_checksums| {
        const options = NativeSeekableOptions{
            .frame_size = 13,
            .frame_options = .{ .content_checksum = false },
            .seek_checksums = with_checksums,
        };
        const encoded = try encodeNativeSeekableStreamAlloc(std.testing.allocator, payload, options);
        defer std.testing.allocator.free(encoded);
        const bound = try encodedNativeSeekableStreamBound(payload.len, options);
        try std.testing.expect(encoded.len <= bound);
        const encoded_into = try std.testing.allocator.alloc(u8, bound);
        defer std.testing.allocator.free(encoded_into);
        const into_written = try encodeNativeSeekableStreamIntoSlice(std.testing.allocator, payload, options, encoded_into);
        try std.testing.expectEqual(encoded.len, into_written);
        try std.testing.expectEqualSlices(u8, encoded, encoded_into[0..into_written]);
        try std.testing.expectEqual(encoded.len, try encodeNativeSeekableStreamIntoSlice(std.testing.allocator, payload, options, encoded_into[0..encoded.len]));
        try std.testing.expectError(error.OutputTooSmall, encodeNativeSeekableStreamIntoSlice(std.testing.allocator, payload, options, encoded_into[0 .. encoded.len - 1]));
        const table = try inspectNativeSeekTable(encoded);
        try std.testing.expectEqual(@as(u32, 4), table.entry_count);
        try std.testing.expectEqual(@as(u64, payload.len), table.decompressed_size);
        try std.testing.expectEqual(with_checksums, table.has_checksums);
        try std.testing.expectEqual(@as(u32, 0), try table.frameIndexForDecompressedOffset(0));
        try std.testing.expectEqual(@as(u32, 1), try table.frameIndexForDecompressedOffset(13));
        try std.testing.expectEqual(@as(u32, 3), try table.frameIndexForDecompressedOffset(payload.len - 1));
        var index_storage: [4]NativeSeekTableEntry = undefined;
        const index = try buildNativeSeekIndex(table, &index_storage);
        try std.testing.expectEqual(@as(u32, 1), try index.frameIndexForDecompressedOffset(13));
        try std.testing.expectEqual(@as(u64, 13), (try index.entry(1)).decompressed_offset);

        const decoded = try decodeNativeConcatenatedFrameAlloc(std.testing.allocator, encoded);
        defer std.testing.allocator.free(decoded);
        try std.testing.expectEqualSlices(u8, payload, decoded);
        var range_scratch: [13]u8 = undefined;
        var range_output: [34]u8 = undefined;
        try std.testing.expectEqual(@as(usize, 13), try nativeSeekableRangeScratchLen(table, 5, range_output.len));
        try std.testing.expectEqual(range_output.len, try decodeNativeSeekableRangeInto(encoded, 5, &range_output, &range_scratch));
        try std.testing.expectEqualSlices(u8, payload[5..39], &range_output);
        var indexed_range: [34]u8 = undefined;
        try std.testing.expectEqual(@as(usize, 13), try nativeSeekableRangeScratchLenWithIndex(index, 5, indexed_range.len));
        try std.testing.expectEqual(indexed_range.len, try decodeNativeSeekableRangeIntoWithIndex(index, 5, &indexed_range, &range_scratch));
        try std.testing.expectEqualSlices(u8, payload[5..39], &indexed_range);
        var reused_range: [9]u8 = undefined;
        try std.testing.expectEqual(reused_range.len, try decodeNativeSeekableRangeIntoWithIndex(index, 31, &reused_range, &range_scratch));
        try std.testing.expectEqualSlices(u8, payload[31..40], &reused_range);
        const allocated_range = try decodeNativeSeekableRangeAlloc(std.testing.allocator, encoded, 5, range_output.len);
        defer std.testing.allocator.free(allocated_range);
        try std.testing.expectEqualSlices(u8, &range_output, allocated_range);
        const indexed_allocated_range = try decodeNativeSeekableRangeAllocWithIndex(std.testing.allocator, index, 12, 17);
        defer std.testing.allocator.free(indexed_allocated_range);
        try std.testing.expectEqualSlices(u8, payload[12..29], indexed_allocated_range);
        try std.testing.expectError(error.OutputTooSmall, decodeNativeSeekableRangeInto(encoded, 5, &range_output, range_scratch[0..12]));
        try std.testing.expectError(error.OutputTooSmall, decodeNativeSeekableRangeIntoWithIndex(index, 5, &indexed_range, range_scratch[0..12]));
        try std.testing.expectError(error.RangeOutOfBounds, nativeSeekableRangeScratchLen(table, payload.len, 1));
        try std.testing.expectError(error.RangeOutOfBounds, nativeSeekableRangeScratchLenWithIndex(index, payload.len, 1));
        try std.testing.expectEqual(@as(usize, 0), try decodeNativeSeekableRangeInto(encoded, payload.len, &.{}, &.{}));
        try std.testing.expectEqual(@as(usize, 0), try decodeNativeSeekableRangeIntoWithIndex(index, payload.len, &.{}, &.{}));

        if (with_checksums) {
            var corrupt = try std.testing.allocator.dupe(u8, encoded);
            defer std.testing.allocator.free(corrupt);
            corrupt[table.frame_offset + 8 + 12 + 8] ^= 1;
            try std.testing.expectError(error.ChecksumMismatch, decodeNativeSeekableRangeInto(corrupt, 13, range_output[0..13], &range_scratch));
            const corrupt_table = try inspectNativeSeekTable(corrupt);
            var corrupt_index_storage: [4]NativeSeekTableEntry = undefined;
            const corrupt_index = try buildNativeSeekIndex(corrupt_table, &corrupt_index_storage);
            try std.testing.expectError(error.ChecksumMismatch, decodeNativeSeekableRangeIntoWithIndex(corrupt_index, 13, indexed_range[0..13], &range_scratch));
        }
        var entries = table.iterator();
        var frame_index: usize = 0;
        while (try entries.next()) |entry_value| : (frame_index += 1) {
            const expected_start = frame_index * 13;
            const expected_end = @min(payload.len, expected_start + 13);
            try std.testing.expectEqual(@as(u32, @intCast(expected_end - expected_start)), entry_value.decompressed_size);
            if (with_checksums)
                try std.testing.expectEqual(@as(?u32, @truncate(std.hash.XxHash64.hash(0, payload[expected_start..expected_end]))), entry_value.checksum);
        }
    }

    const empty = try encodeNativeSeekableStreamAlloc(std.testing.allocator, "", .{ .seek_checksums = false });
    defer std.testing.allocator.free(empty);
    const empty_bound = try encodedNativeSeekableStreamBound(0, .{ .seek_checksums = false });
    try std.testing.expect(empty.len <= empty_bound);
    const empty_into = try std.testing.allocator.alloc(u8, empty_bound);
    defer std.testing.allocator.free(empty_into);
    const empty_written = try encodeNativeSeekableStreamIntoSlice(std.testing.allocator, "", .{ .seek_checksums = false }, empty_into);
    try std.testing.expectEqualSlices(u8, empty, empty_into[0..empty_written]);
    const empty_table = try inspectNativeSeekTable(empty);
    try std.testing.expectEqual(@as(u32, 1), empty_table.entry_count);
    try std.testing.expectEqual(@as(u64, 0), empty_table.decompressed_size);
    const empty_decoded = try decodeNativeConcatenatedFrameAlloc(std.testing.allocator, empty);
    defer std.testing.allocator.free(empty_decoded);
    try std.testing.expectEqual(@as(usize, 0), empty_decoded.len);

    var appended: std.ArrayList(u8) = .empty;
    defer appended.deinit(std.testing.allocator);
    try appended.appendSlice(std.testing.allocator, "prefix:");
    try encodeNativeSeekableStreamAppend(std.testing.allocator, &appended, payload, .{
        .frame_size = 13,
        .frame_options = .{ .content_checksum = false },
        .seek_checksums = true,
    });
    const appended_table = try inspectNativeSeekTable(appended.items["prefix:".len..]);
    try std.testing.expectEqual(@as(u64, payload.len), appended_table.decompressed_size);
    try std.testing.expectEqualSlices(u8, "prefix:", appended.items[0.."prefix:".len]);
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamAlloc(std.testing.allocator, payload, .{ .frame_size = 0 }));
    try std.testing.expectError(error.InvalidBlockPlan, encodedNativeSeekableStreamBound(payload.len, .{ .frame_size = 0 }));
    try std.testing.expectError(error.InvalidBlockPlan, encodedNativeSeekableStreamBound(seekable.max_frames + 1, .{ .frame_size = 1 }));
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamAlloc(std.testing.allocator, payload, .{ .frame_size = seekable.max_frame_decompressed_size + 1 }));
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamAlloc(std.testing.allocator, payload, .{ .frame_options = .{ .dictionary_id = 1 } }));
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamAppend(std.testing.allocator, &appended, payload, .{ .frame_size = 0 }));
}

test "zstd parallel seekable encoder is deterministic across worker counts" {
    const payload = ("parallel-seekable-zstd-{\"id\":42,\"status\":\"ready\"}\n" ** 768);
    const options = NativeSeekableOptions{
        .frame_size = 4096,
        .frame_options = .{ .selection = .fast_compressed, .content_checksum = true },
        .seek_checksums = true,
    };
    const serial = try encodeNativeSeekableStreamAlloc(std.testing.allocator, payload, options);
    defer std.testing.allocator.free(serial);
    for ([_]usize{ 1, 2, 4, 64 }) |worker_count| {
        const parallel = try encodeNativeSeekableStreamParallelAlloc(std.testing.allocator, payload, options, worker_count);
        defer std.testing.allocator.free(parallel);
        try std.testing.expectEqualSlices(u8, serial, parallel);
        const table = try inspectNativeSeekTable(parallel);
        try std.testing.expectEqual(try nativeSeekableFrameCount(payload.len, options.frame_size), table.entry_count);
        const range_start: u64 = options.frame_size - 31;
        var output: [options.frame_size + 79]u8 = undefined;
        var scratch: [options.frame_size]u8 = undefined;
        try std.testing.expectEqual(output.len, try decodeNativeSeekableRangeInto(parallel, range_start, &output, &scratch));
        try std.testing.expectEqualSlices(u8, payload[@intCast(range_start)..][0..output.len], &output);
    }

    const empty_serial = try encodeNativeSeekableStreamAlloc(std.testing.allocator, "", options);
    defer std.testing.allocator.free(empty_serial);
    const empty_parallel = try encodeNativeSeekableStreamParallelAlloc(std.testing.allocator, "", options, 8);
    defer std.testing.allocator.free(empty_parallel);
    try std.testing.expectEqualSlices(u8, empty_serial, empty_parallel);
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamParallelAlloc(std.testing.allocator, payload, options, 0));
    try std.testing.expectError(error.InvalidBlockPlan, encodeNativeSeekableStreamParallelAlloc(std.testing.allocator, payload, options, native_seekable_parallel_workers_max + 1));
}

test "zstd parallel seekable encoder preserves dictionary routing" {
    const dictionary = NativeDictionary.init(0x7654, "parallel dictionary prefix alpha beta gamma delta");
    const dictionary_set = NativeDictionarySet.init(&.{dictionary});
    const payload = ("parallel dictionary prefix alpha beta gamma delta payload\n" ** 384);
    const options = NativeSeekableOptions{
        .frame_size = 2048,
        .frame_options = .{ .selection = .literal_only, .content_checksum = false },
        .seek_checksums = true,
    };
    const serial = try encodeNativeSeekableStreamWithDictionaryAlloc(std.testing.allocator, payload, options, dictionary);
    defer std.testing.allocator.free(serial);
    const parallel = try encodeNativeSeekableStreamParallelWithDictionaryAlloc(std.testing.allocator, payload, options, dictionary, 4);
    defer std.testing.allocator.free(parallel);
    try std.testing.expectEqualSlices(u8, serial, parallel);
    const selected = try encodeNativeSeekableStreamParallelWithDictionarySetAlloc(std.testing.allocator, payload, options, dictionary_set, dictionary.id, 3);
    defer std.testing.allocator.free(selected);
    try std.testing.expectEqualSlices(u8, serial, selected);

    const table = try inspectNativeSeekTable(parallel);
    var output: [4096]u8 = undefined;
    var scratch: [options.frame_size]u8 = undefined;
    try std.testing.expectEqual(output.len, try decodeNativeSeekableRangeIntoWithDictionary(parallel, options.frame_size - 17, &output, &scratch, dictionary));
    try std.testing.expectEqualSlices(u8, payload[options.frame_size - 17 ..][0..output.len], &output);
    try std.testing.expect(table.entry_count > 2);
    try std.testing.expectError(error.NeedDictionary, encodeNativeSeekableStreamParallelWithDictionarySetAlloc(std.testing.allocator, payload, options, dictionary_set, 0x9999, 2));
}

test "zstd parallel seekable encoder releases allocation failures" {
    const payload = ("parallel seekable allocation failure\n" ** 256);
    const options = NativeSeekableOptions{
        .frame_size = 1024,
        .frame_options = .{ .selection = .literal_only, .content_checksum = false },
        .seek_checksums = false,
    };
    const Test = struct {
        fn run(allocator: std.mem.Allocator, input: []const u8, opts: NativeSeekableOptions) !void {
            const encoded = try encodeNativeSeekableStreamParallelAlloc(allocator, input, opts, 1);
            defer allocator.free(encoded);
            const decoded = try decodeNativeSeekableRangeAlloc(allocator, encoded, 0, input.len);
            defer allocator.free(decoded);
            try std.testing.expectEqualSlices(u8, input, decoded);
        }
    };
    // Worker count one covers every allocation/rollback point without creating
    // threads from the intentionally non-thread-safe failing allocator.
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Test.run, .{ payload, options });
}

test "zstd parallel seekable encoder handles metadata allocation failure before spawning" {
    const payload = ("parallel seekable metadata allocation failure\n" ** 128);
    const options = NativeSeekableOptions{
        .frame_size = 512,
        .frame_options = .{ .selection = .literal_only, .content_checksum = false },
        .seek_checksums = false,
    };

    // The first three allocations are the entry array, per-frame result array,
    // and thread-handle array. All must exist before any worker can start.
    for (0..3) |fail_index| {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
        });
        try std.testing.expectError(
            error.OutOfMemory,
            encodeNativeSeekableStreamParallelAlloc(failing.allocator(), payload, options, 4),
        );
        try std.testing.expect(failing.has_induced_failure);
        try std.testing.expectEqual(fail_index, failing.allocations);
        try std.testing.expectEqual(fail_index, failing.deallocations);
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

test "zstd parallel seekable encoder joins workers after encoder allocation failure" {
    const payload = ("parallel worker allocation failure\n" ** 128);
    const options = NativeSeekableOptions{
        .frame_size = 512,
        .frame_options = .{ .selection = .literal_only, .content_checksum = false },
        .seek_checksums = false,
    };

    // Three metadata allocations complete before worker threads start. The
    // next allocation is made by a frame encoder through LockedAllocator.
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
        .fail_index = 3,
    });
    try std.testing.expectError(
        error.OutOfMemory,
        encodeNativeSeekableStreamParallelAlloc(failing.allocator(), payload, options, 4),
    );
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqual(@as(usize, 3), failing.allocations);
    try std.testing.expectEqual(failing.allocations, failing.deallocations);
    try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
}

test "zstd seekable range decoder resolves per-frame dictionaries" {
    const first_dictionary = NativeDictionary.init(0x1234, "abcdefghijklmnop");
    const second_dictionary = NativeDictionary.init(0x5678, "QRSTUVWXYZabcd1234");
    const first_payload = "abcdefghijklmnop-first";
    const second_payload = "QRSTUVWXYZabcd1234-second";
    const frame_options = NativeFrameOptions{ .content_checksum = false, .selection = .literal_only };
    const first = try encodeNativeFrameWithDictionaryAlloc(std.testing.allocator, first_payload, frame_options, first_dictionary);
    defer std.testing.allocator.free(first.frame);
    const second = try encodeNativeFrameWithDictionaryAlloc(std.testing.allocator, second_payload, frame_options, second_dictionary);
    defer std.testing.allocator.free(second.frame);

    const entries = [_]NativeSeekTableFrameSize{
        .{ .compressed_size = @intCast(first.frame.len), .decompressed_size = @intCast(first_payload.len), .checksum = @truncate(std.hash.XxHash64.hash(0, first_payload)) },
        .{ .compressed_size = @intCast(second.frame.len), .decompressed_size = @intCast(second_payload.len), .checksum = @truncate(std.hash.XxHash64.hash(0, second_payload)) },
    };
    var stream: std.ArrayList(u8) = .empty;
    defer stream.deinit(std.testing.allocator);
    try stream.appendSlice(std.testing.allocator, first.frame);
    try stream.appendSlice(std.testing.allocator, second.frame);
    try encodeNativeSeekTableAppend(std.testing.allocator, &stream, &entries, true);

    const dictionaries = [_]NativeDictionary{ first_dictionary, second_dictionary };
    const dictionary_set = NativeDictionarySet.init(&dictionaries);
    var index_storage: [entries.len]NativeSeekTableEntry = undefined;
    const index = try buildNativeSeekIndex(try inspectNativeSeekTable(stream.items), &index_storage);
    const range_start = first_payload.len - 3;
    var output: [12]u8 = undefined;
    var scratch: [second_payload.len]u8 = undefined;
    try std.testing.expectEqual(output.len, try decodeNativeSeekableRangeIntoWithDictionarySet(stream.items, range_start, &output, &scratch, dictionary_set));
    try std.testing.expectEqualSlices(u8, (first_payload ++ second_payload)[range_start..][0..output.len], &output);
    var indexed_output: [output.len]u8 = undefined;
    try std.testing.expectEqual(indexed_output.len, try decodeNativeSeekableRangeIntoWithIndexAndDictionarySet(index, range_start, &indexed_output, &scratch, dictionary_set));
    try std.testing.expectEqualSlices(u8, &output, &indexed_output);
    const allocated = try decodeNativeSeekableRangeAllocWithDictionarySet(std.testing.allocator, stream.items, range_start, output.len, dictionary_set);
    defer std.testing.allocator.free(allocated);
    try std.testing.expectEqualSlices(u8, &output, allocated);
    const indexed_allocated = try decodeNativeSeekableRangeAllocWithIndexAndDictionarySet(std.testing.allocator, index, range_start, output.len, dictionary_set);
    defer std.testing.allocator.free(indexed_allocated);
    try std.testing.expectEqualSlices(u8, &output, indexed_allocated);
    try std.testing.expectError(error.NeedDictionary, decodeNativeSeekableRangeInto(stream.items, range_start, &output, &scratch));
    try std.testing.expectError(error.NeedDictionary, decodeNativeSeekableRangeIntoWithDictionarySet(stream.items, range_start, &output, &scratch, NativeDictionarySet.init(&.{first_dictionary})));
    try std.testing.expectError(error.NeedDictionary, decodeNativeSeekableRangeIntoWithIndex(index, range_start, &output, &scratch));
    try std.testing.expectError(error.NeedDictionary, decodeNativeSeekableRangeIntoWithIndexAndDictionarySet(index, range_start, &output, &scratch, NativeDictionarySet.init(&.{first_dictionary})));
}

test "zstd indexed seekable range crosses an empty frame" {
    const payloads = [_][]const u8{ "abc", "", "def" };
    var stream: std.ArrayList(u8) = .empty;
    defer stream.deinit(std.testing.allocator);
    var frame_sizes: [payloads.len]NativeSeekTableFrameSize = undefined;
    for (payloads, 0..) |payload, i| {
        const frame = try encodeNativeFrameAlloc(std.testing.allocator, payload);
        defer std.testing.allocator.free(frame);
        try stream.appendSlice(std.testing.allocator, frame);
        frame_sizes[i] = .{
            .compressed_size = @intCast(frame.len),
            .decompressed_size = @intCast(payload.len),
            .checksum = @truncate(std.hash.XxHash64.hash(0, payload)),
        };
    }
    try encodeNativeSeekTableAppend(std.testing.allocator, &stream, &frame_sizes, true);

    const table = try inspectNativeSeekTable(stream.items);
    var index_storage: [payloads.len]NativeSeekTableEntry = undefined;
    const index = try buildNativeSeekIndex(table, &index_storage);
    try std.testing.expectEqual(@as(u32, 2), try index.frameIndexForDecompressedOffset(3));

    var output: [3]u8 = undefined;
    var scratch: [3]u8 = undefined;
    try std.testing.expectEqual(output.len, try decodeNativeSeekableRangeIntoWithIndex(index, 2, &output, &scratch));
    try std.testing.expectEqualSlices(u8, "cde", &output);
}

test "zstd native seekable encoder applies a dictionary to every frame" {
    const dictionary = NativeDictionary.init(0x3456, "abcdefghijklmnopQRSTUVWXYZ");
    const payload = "abcdefghijklmnop-tail-QRSTUVWXYZ-tail";
    const options = NativeSeekableOptions{
        .frame_size = 20,
        .frame_options = .{ .selection = .literal_only, .content_checksum = false },
        .seek_checksums = true,
    };
    const encoded = try encodeNativeSeekableStreamWithDictionaryAlloc(std.testing.allocator, payload, options, dictionary);
    defer std.testing.allocator.free(encoded);
    const dictionary_bound = try encodedNativeSeekableStreamBoundWithDictionary(payload.len, options, dictionary);
    try std.testing.expect(encoded.len <= dictionary_bound);
    const encoded_into = try std.testing.allocator.alloc(u8, dictionary_bound);
    defer std.testing.allocator.free(encoded_into);
    const into_written = try encodeNativeSeekableStreamIntoSliceWithDictionary(std.testing.allocator, payload, options, dictionary, encoded_into);
    try std.testing.expectEqualSlices(u8, encoded, encoded_into[0..into_written]);
    const table = try inspectNativeSeekTable(encoded);
    try std.testing.expectEqual(@as(u32, 2), table.entry_count);

    var entries = table.iterator();
    while (try entries.next()) |entry_value| {
        const frame_start: usize = @intCast(entry_value.compressed_offset);
        const frame_end = frame_start + entry_value.compressed_size;
        try std.testing.expectEqual(dictionary.id, (try inspectNativeFrameHeader(encoded[frame_start..frame_end])).dictionary_id);
    }
    const dictionary_set = NativeDictionarySet.init(&.{dictionary});
    const decoded = try decodeNativeSeekableRangeAllocWithDictionarySet(std.testing.allocator, encoded, 0, payload.len, dictionary_set);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);

    const selected = try encodeNativeSeekableStreamWithDictionarySetAlloc(std.testing.allocator, payload, options, dictionary_set, dictionary.id);
    defer std.testing.allocator.free(selected);
    try std.testing.expectEqualSlices(u8, encoded, selected);
    try std.testing.expectEqual(dictionary_bound, try encodedNativeSeekableStreamBoundWithDictionarySet(payload.len, options, dictionary_set, dictionary.id));
    @memset(encoded_into, 0);
    const selected_into_written = try encodeNativeSeekableStreamIntoSliceWithDictionarySet(std.testing.allocator, payload, options, dictionary_set, dictionary.id, encoded_into);
    try std.testing.expectEqualSlices(u8, selected, encoded_into[0..selected_into_written]);
    try std.testing.expectError(error.NeedDictionary, encodeNativeSeekableStreamWithDictionarySetAlloc(std.testing.allocator, payload, options, dictionary_set, 0x9999));
    try std.testing.expectError(error.NeedDictionary, encodedNativeSeekableStreamBoundWithDictionarySet(payload.len, options, dictionary_set, 0x9999));
    try std.testing.expectError(error.NeedDictionary, encodeNativeSeekableStreamIntoSliceWithDictionarySet(std.testing.allocator, payload, options, dictionary_set, 0x9999, encoded_into));

    const raw_dictionary = NativeDictionary.initRawContent(dictionary.content);
    try std.testing.expectError(error.NeedDictionary, NativeDictionarySet.initChecked(&.{raw_dictionary}));
    const idless = try encodeNativeSeekableStreamWithDictionaryAlloc(std.testing.allocator, payload, options, raw_dictionary);
    defer std.testing.allocator.free(idless);
    const idless_bound = try encodedNativeSeekableStreamBoundWithDictionary(payload.len, options, raw_dictionary);
    const idless_into = try std.testing.allocator.alloc(u8, idless_bound);
    defer std.testing.allocator.free(idless_into);
    const idless_written = try encodeNativeSeekableStreamIntoSliceWithDictionary(std.testing.allocator, payload, options, raw_dictionary, idless_into);
    try std.testing.expectEqualSlices(u8, idless, idless_into[0..idless_written]);
    const idless_table = try inspectNativeSeekTable(idless);
    var idless_entries = idless_table.iterator();
    while (try idless_entries.next()) |entry_value| {
        const frame_start: usize = @intCast(entry_value.compressed_offset);
        const frame_end = frame_start + entry_value.compressed_size;
        try std.testing.expectEqual(@as(u32, 0), (try inspectNativeFrameHeader(idless[frame_start..frame_end])).dictionary_id);
    }

    const range_start: u64 = options.frame_size - 3;
    const range_len: usize = 17;
    const expected_range = payload[@intCast(range_start)..][0..range_len];
    var range_output: [range_len]u8 = undefined;
    var range_scratch: [options.frame_size]u8 = undefined;
    try std.testing.expectEqual(
        range_len,
        try decodeNativeSeekableRangeIntoWithDictionary(idless, range_start, &range_output, &range_scratch, raw_dictionary),
    );
    try std.testing.expectEqualSlices(u8, expected_range, &range_output);
    try std.testing.expectError(error.InvalidMatch, decodeNativeSeekableRangeInto(idless, range_start, &range_output, &range_scratch));

    var idless_index_storage: [2]NativeSeekTableEntry = undefined;
    const idless_index = try buildNativeSeekIndex(idless_table, &idless_index_storage);
    @memset(&range_output, 0);
    try std.testing.expectEqual(
        range_len,
        try decodeNativeSeekableRangeIntoWithIndexAndDictionary(idless_index, range_start, &range_output, &range_scratch, raw_dictionary),
    );
    try std.testing.expectEqualSlices(u8, expected_range, &range_output);
    const allocated_range = try decodeNativeSeekableRangeAllocWithDictionary(std.testing.allocator, idless, range_start, range_len, raw_dictionary);
    defer std.testing.allocator.free(allocated_range);
    try std.testing.expectEqualSlices(u8, expected_range, allocated_range);
    const indexed_allocated_range = try decodeNativeSeekableRangeAllocWithIndexAndDictionary(std.testing.allocator, idless_index, range_start, range_len, raw_dictionary);
    defer std.testing.allocator.free(indexed_allocated_range);
    try std.testing.expectEqualSlices(u8, expected_range, indexed_allocated_range);
    const wrong_raw_dictionary = NativeDictionary.initRawContent("ABCDEFGHIJKLMNOPQRSTUVWXYZ");
    try std.testing.expectError(
        error.ChecksumMismatch,
        decodeNativeSeekableRangeIntoWithDictionary(idless, range_start, &range_output, &range_scratch, wrong_raw_dictionary),
    );
    try std.testing.expectError(
        error.ChecksumMismatch,
        decodeNativeSeekableRangeIntoWithIndexAndDictionary(idless_index, range_start, &range_output, &range_scratch, wrong_raw_dictionary),
    );
}

test "zstd reusable seekable encoder retains frame and table scratch" {
    const payload = ("reusable seekable zstd frame payload-" ** 96);
    const options: NativeSeekableOptions = .{
        .frame_size = 1024,
        .frame_options = .{ .selection = .literal_only, .content_checksum = true },
        .seek_checksums = true,
    };
    var counting = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var encoder = NativeSeekableStreamEncoder.init(counting.allocator());
    var encoder_live = true;
    defer if (encoder_live) encoder.deinit();

    const first = try encoder.encodeScratch(payload, options);
    const expected = try std.testing.allocator.dupe(u8, first);
    defer std.testing.allocator.free(expected);
    const first_allocations = counting.allocations;
    const entry_capacity = encoder.entries.capacity;
    const output_capacity = encoder.output_scratch.capacity;
    const frame_capacity = encoder.frame_encoder.output_scratch.capacity;
    const block_candidate_capacity = encoder.frame_encoder.block_scratch.candidate.capacity;
    const block_best_capacity = encoder.frame_encoder.block_scratch.best.capacity;
    const match_candidate_capacity = encoder.frame_encoder.block_scratch.match_candidate.capacity;
    const match_best_capacity = encoder.frame_encoder.block_scratch.match_best.capacity;
    const greedy_tokens_capacity = encoder.frame_encoder.block_scratch.greedy_tokens.capacity;
    const lazy_tokens_capacity = encoder.frame_encoder.block_scratch.lazy_tokens.capacity;
    const optimal_costs_capacity = encoder.frame_encoder.block_scratch.optimal.costs.capacity;
    const optimal_steps_capacity = encoder.frame_encoder.block_scratch.optimal.steps.capacity;
    const optimal_compact_head_capacity = encoder.frame_encoder.block_scratch.optimal.compact_head.capacity;
    const optimal_compact_prev_capacity = encoder.frame_encoder.block_scratch.optimal.compact_prev.capacity;
    const optimal_tokens_capacity = encoder.frame_encoder.block_scratch.optimal.tokens.capacity;
    const single_literals_capacity = encoder.frame_encoder.block_scratch.single_sequence_emit.literals_prefix.capacity;
    const single_payload_capacity = encoder.frame_encoder.block_scratch.single_sequence_emit.payload.capacity;
    const single_bits_capacity = encoder.frame_encoder.block_scratch.single_sequence_emit.sequence_bits.capacity;
    try std.testing.expect(single_literals_capacity != 0);
    try std.testing.expect(single_payload_capacity != 0);
    try std.testing.expect(single_bits_capacity != 0);
    const first_deallocations = counting.deallocations;
    const first_allocated_bytes = counting.allocated_bytes;
    const first_freed_bytes = counting.freed_bytes;

    const second = try encoder.encodeScratch(payload, options);
    const second_allocations = counting.allocations - first_allocations;
    const second_deallocations = counting.deallocations - first_deallocations;
    const second_allocated_bytes = counting.allocated_bytes - first_allocated_bytes;
    const second_freed_bytes = counting.freed_bytes - first_freed_bytes;
    try std.testing.expectEqualSlices(u8, expected, second);
    try std.testing.expectEqual(entry_capacity, encoder.entries.capacity);
    try std.testing.expectEqual(output_capacity, encoder.output_scratch.capacity);
    try std.testing.expectEqual(frame_capacity, encoder.frame_encoder.output_scratch.capacity);
    try std.testing.expectEqual(block_candidate_capacity, encoder.frame_encoder.block_scratch.candidate.capacity);
    try std.testing.expectEqual(block_best_capacity, encoder.frame_encoder.block_scratch.best.capacity);
    try std.testing.expectEqual(match_candidate_capacity, encoder.frame_encoder.block_scratch.match_candidate.capacity);
    try std.testing.expectEqual(match_best_capacity, encoder.frame_encoder.block_scratch.match_best.capacity);
    try std.testing.expectEqual(greedy_tokens_capacity, encoder.frame_encoder.block_scratch.greedy_tokens.capacity);
    try std.testing.expectEqual(lazy_tokens_capacity, encoder.frame_encoder.block_scratch.lazy_tokens.capacity);
    try std.testing.expectEqual(optimal_costs_capacity, encoder.frame_encoder.block_scratch.optimal.costs.capacity);
    try std.testing.expectEqual(optimal_steps_capacity, encoder.frame_encoder.block_scratch.optimal.steps.capacity);
    try std.testing.expectEqual(optimal_compact_head_capacity, encoder.frame_encoder.block_scratch.optimal.compact_head.capacity);
    try std.testing.expectEqual(optimal_compact_prev_capacity, encoder.frame_encoder.block_scratch.optimal.compact_prev.capacity);
    try std.testing.expectEqual(optimal_tokens_capacity, encoder.frame_encoder.block_scratch.optimal.tokens.capacity);
    try std.testing.expectEqual(single_literals_capacity, encoder.frame_encoder.block_scratch.single_sequence_emit.literals_prefix.capacity);
    try std.testing.expectEqual(single_payload_capacity, encoder.frame_encoder.block_scratch.single_sequence_emit.payload.capacity);
    try std.testing.expectEqual(single_bits_capacity, encoder.frame_encoder.block_scratch.single_sequence_emit.sequence_bits.capacity);
    try std.testing.expectEqual(first_allocations - 17, second_allocations);
    try std.testing.expectEqual(@as(usize, 0), second_allocations);
    try std.testing.expectEqual(second_allocations, second_deallocations);
    try std.testing.expectEqual(second_allocated_bytes, second_freed_bytes);

    {
        const dictionary = NativeDictionary.init(0x4455, "reusable seekable zstd frame payload-");
        const dictionary_set = NativeDictionarySet.init(&.{dictionary});
        const expected_with_dictionary = try encodeNativeSeekableStreamWithDictionaryAlloc(std.testing.allocator, payload, options, dictionary);
        defer std.testing.allocator.free(expected_with_dictionary);
        const allocated_with_set = try encoder.encodeWithDictionarySetAlloc(payload, options, dictionary_set, dictionary.id);
        defer counting.allocator().free(allocated_with_set);
        try std.testing.expectEqualSlices(u8, expected_with_dictionary, allocated_with_set);
        const scratch_with_set = try encoder.encodeScratchWithDictionarySet(payload, options, dictionary_set, dictionary.id);
        try std.testing.expectEqualSlices(u8, expected_with_dictionary, scratch_with_set);
        var appended_with_set: std.ArrayList(u8) = .empty;
        defer appended_with_set.deinit(counting.allocator());
        try encoder.encodeAppendWithDictionarySet(&appended_with_set, payload, options, dictionary_set, dictionary.id);
        try std.testing.expectEqualSlices(u8, expected_with_dictionary, appended_with_set.items);
    }

    counting.fail_index = counting.alloc_index;
    try std.testing.expectError(error.OutOfMemory, encoder.encodeScratch(payload ++ payload, options));
    try std.testing.expectEqual(@as(usize, 0), encoder.output_scratch.items.len);
    counting.fail_index = std.math.maxInt(usize);
    const recovered = try encoder.encodeScratch(payload, options);
    try std.testing.expectEqualSlices(u8, expected, recovered);
    encoder.deinit();
    encoder_live = false;
    try std.testing.expectEqual(counting.allocated_bytes, counting.freed_bytes);
}

