fn appendNumberedJsonPayload(allocator: std.mem.Allocator, out: *std.ArrayList(u8), count: usize) !void {
    for (0..count) |i| {
        const line = try std.fmt.allocPrint(
            allocator,
            "{{\"k\":\"{d:0>4}\",\"n\":{d},\"txt\":\"abcdefghijklmnopqrstuvwxyz0123456789\"}}\n",
            .{ i, i },
        );
        defer allocator.free(line);
        try out.appendSlice(allocator, line);
    }
}

fn appendStructuredZstdJsonPayload(allocator: std.mem.Allocator, out: *std.ArrayList(u8), min_len: usize) !void {
    while (out.items.len < min_len) {
        var line: [128]u8 = undefined;
        const index = out.items.len / 64;
        const formatted = try std.fmt.bufPrint(
            &line,
            "{{\"id\":{d},\"service\":\"vort\",\"message\":\"structured zstd corpus payload\"}}\n",
            .{index},
        );
        try out.appendSlice(allocator, formatted);
    }
}

test "zstd native decoder accepts FSE compressed sequence tables" {
    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(std.testing.allocator);
    try appendNumberedJsonPayload(std.testing.allocator, &payload, 20);

    const offset_fse_hex =
        "28b52ffd04480d05008246171b604fda9c7c0c3be3e2e30209a920082d844864" ++
        "7777ec670a42a39c2921d4cdbcab9a89786767971242ddccbbaa99887780cc13" ++
        "6a5e4d3cbb582a94896445200f47e3612c1c4502713014080341e0eaabb2de" ++
        "98faf3e6666657778e092720f0750344c9ae87b9d2732eeb11f77a982b7dce" ++
        "653de25e0f73a5e7dc65254ec31a8f60d7c330e97318eb11ec7a18263d87" ++
        "b11ec1ae0ec3a4e70833602852141ad6cc48";
    var offset_fse_frame: [offset_fse_hex.len / 2]u8 = undefined;
    _ = try std.fmt.hexToBytes(&offset_fse_frame, offset_fse_hex);

    const first_block = try inspectNativeFrameFirstBlock(&offset_fse_frame);
    const block = offset_fse_frame[first_block.payload_offset..][0..first_block.payload_len];
    var parse_state: SequenceFrameState = .{};
    const section = try parseLiteralsSection(block, &parse_state);
    var first: SequenceFseTable = undefined;
    @memset(std.mem.asBytes(&first), 0x5a);
    var first_offset = section.sequence_payload_offset + 1;
    try readFseSequenceTableInto(
        &first,
        block,
        &first_offset,
        &of_base,
        &of_bits,
        sequence_table_symbol_count_max.offset,
        sequence_table_accuracy_log_max.offset,
    );
    var second: SequenceFseTable = undefined;
    @memset(std.mem.asBytes(&second), 0xa5);
    var second_offset = section.sequence_payload_offset + 1;
    try readFseSequenceTableInto(
        &second,
        block,
        &second_offset,
        &of_base,
        &of_bits,
        sequence_table_symbol_count_max.offset,
        sequence_table_accuracy_log_max.offset,
    );
    try std.testing.expectEqual(first_offset, second_offset);
    try std.testing.expectEqual(first.len, second.len);
    try std.testing.expectEqual(first.accuracy_log, second.accuracy_log);
    try std.testing.expectEqualSlices(SequenceSymbol, first.entries[0..first.len], second.entries[0..second.len]);

    const all_fse_hex =
        "28b52ffd0458bd04006286161d404fd4010c12709f71cdcb65012b8aa20c2b" ++
        "adb44686e60ccbf0189303ffffffff9fbfe75c6b8cada5544a083d20d3e71" ++
        "a5b2aa1f362a950269218813c1c8d87b1701409c4c150200c0481c2c64a6" ++
        "c93b04f9b666616d6292627a831ecebff6790734a0f1118396384ffff1d1f" ++
        "351a6514ea22a98a124d541551a887841a1aa91692544238998e4eabd5ea" ++
        "745a261a1840a4061ad6cc48";
    var all_fse_frame: [all_fse_hex.len / 2]u8 = undefined;
    _ = try std.fmt.hexToBytes(&all_fse_frame, all_fse_hex);

    for ([_][]const u8{ &offset_fse_frame, &all_fse_frame }) |frame| {
        const parsed_block = try inspectNativeFrameFirstBlock(frame);
        const block_bytes = frame[parsed_block.payload_offset..][0..parsed_block.payload_len];
        var direct_frame_state: SequenceFrameState = .{};
        const direct_section = try parseLiteralsSection(block_bytes, &direct_frame_state);
        var returned_offset = direct_section.sequence_payload_offset;
        const returned_spec = try resolveSequenceModeSpec(
            try parseSequenceModeSpec(block_bytes, &returned_offset, direct_section.sequence_count),
            null,
        );
        var direct_spec: SequenceModeSpec = undefined;
        @memset(std.mem.asBytes(&direct_spec), 0xa5);
        var direct_offset = direct_section.sequence_payload_offset;
        try parseSequenceModeSpecInto(&direct_spec, block_bytes, &direct_offset, direct_section.sequence_count);
        try std.testing.expect(direct_spec.ll_mode != .repeat);
        try std.testing.expect(direct_spec.of_mode != .repeat);
        try std.testing.expect(direct_spec.ml_mode != .repeat);
        try std.testing.expectEqual(returned_offset, direct_offset);
        try expectSequenceModeSpecsEqual(&returned_spec, &direct_spec);

        const std_decoded = try decodeFrameAlloc(std.testing.allocator, frame);
        defer std.testing.allocator.free(std_decoded);
        try std.testing.expectEqualSlices(u8, payload.items, std_decoded);

        const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame);
        defer std.testing.allocator.free(decoded);
        try std.testing.expectEqualSlices(u8, payload.items, decoded);

        const into_buffer = try std.testing.allocator.alloc(u8, payload.items.len);
        defer std.testing.allocator.free(into_buffer);
        const written = try decodeNativeFrameInto(frame, into_buffer);
        try std.testing.expectEqual(payload.items.len, written);
        try std.testing.expectEqualSlices(u8, payload.items, into_buffer[0..written]);

        const decoded_len = try decodedRawOrRleFrameSize(frame);
        try std.testing.expectEqual(payload.items.len, decoded_len);
    }
}

test "zstd small predefined offset-FSE Huffman path matches generic decode" {
    test_small_mixed_fse_fast_literal_hits = 0;
    test_small_mixed_fse_match_56_hits = 0;
    test_small_mixed_fse_match_6_7_hits = 0;
    test_small_mixed_field_group_hits = 0;
    test_small_mixed_single_literal_hits = 0;
    test_small_mixed_reservoir_literal_hits = 0;
    defer {
        test_small_mixed_fse_fast_literal_hits = 0;
        test_small_mixed_fse_match_56_hits = 0;
        test_small_mixed_fse_match_6_7_hits = 0;
        test_small_mixed_field_group_hits = 0;
        test_small_mixed_single_literal_hits = 0;
        test_small_mixed_reservoir_literal_hits = 0;
    }
    const encoded_hex_file = @embedFile("zstd/testdata/libzstd-numbered-json.frame.hex");
    const encoded_hex = std.mem.trim(u8, encoded_hex_file, " \r\n\t");
    var encoded: [(encoded_hex_file.len - 1) / 2]u8 = undefined;
    _ = try std.fmt.hexToBytes(&encoded, encoded_hex);

    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(std.testing.allocator);
    try appendNumberedJsonPayload(std.testing.allocator, &payload, 20);
    const first_block = try inspectNativeFrameFirstBlock(&encoded);
    const block = encoded[first_block.payload_offset..][0..first_block.payload_len];

    var generic_state: SequenceFrameState = .{};
    const generic_section = try parseLiteralsSection(block, &generic_state);
    try std.testing.expectEqual(@as(usize, 39), generic_section.sequence_count);
    try std.testing.expectEqual(LiteralsKind.compressed, generic_section.kind);
    try std.testing.expectEqual(NarrowHuffmanLiteralLookup.bit_width, generic_section.huffman_tree.?.max_bit_count);
    try std.testing.expectEqual(@as(u8, 0x20), block[generic_section.sequence_payload_offset]);

    var direct_previous_tree: ?StdZstdHuffmanTree = null;
    const direct_section = try parseLiteralsSectionWithPreviousTree(block, &direct_previous_tree);
    try std.testing.expectEqual(generic_section.kind, direct_section.kind);
    try std.testing.expectEqual(generic_section.size_format, direct_section.size_format);
    try std.testing.expectEqual(generic_section.regenerated_size, direct_section.regenerated_size);
    try std.testing.expectEqual(generic_section.literal_payload_offset, direct_section.literal_payload_offset);
    try std.testing.expectEqual(generic_section.huffman_stream_offset, direct_section.huffman_stream_offset);
    try std.testing.expectEqual(generic_section.compressed_size, direct_section.compressed_size);
    try std.testing.expectEqual(generic_section.sequence_count, direct_section.sequence_count);
    try std.testing.expectEqual(generic_section.sequence_payload_offset, direct_section.sequence_payload_offset);
    try std.testing.expectEqual(std.meta.activeTag(generic_section.huffman_streams), std.meta.activeTag(direct_section.huffman_streams));
    switch (generic_section.huffman_streams) {
        .none, .one => {},
        .four => |expected_streams| for (expected_streams, direct_section.huffman_streams.four) |expected_stream, actual_stream|
            try std.testing.expectEqualSlices(u8, expected_stream, actual_stream),
    }
    try expectHuffmanTreesEqual(generic_section.huffman_tree.?, direct_section.huffman_tree.?);
    try expectHuffmanTreesEqual(generic_state.previous_huffman_tree.?, direct_previous_tree.?);

    var generic_output: [1290 + 64]u8 = @splat(0xa5);
    var generic_written: usize = 0;
    try decodeRleSequencesCompressedBlockIntoBuffer(
        block,
        generic_section,
        &generic_output,
        &generic_written,
        0,
        &.{},
        &generic_state,
        .terminal,
        false,
    );

    var specialized_state: SequenceFrameState = .{};
    var specialized_lookup: PreparedNarrowHuffmanLookup = .{};
    const specialized_section = try parseLiteralsSectionWithPreviousTreeAndNarrowLookup(
        block,
        &specialized_state.previous_huffman_tree,
        &specialized_lookup,
    );
    try std.testing.expect(specialized_lookup.complete);
    var expected_lookup: NarrowHuffmanLiteralLookup = undefined;
    try std.testing.expect(expected_lookup.buildComplete(&generic_section.huffman_tree.?));
    try std.testing.expectEqualSlices(
        u8,
        std.mem.asBytes(&expected_lookup.entries),
        std.mem.asBytes(&specialized_lookup.table.entries),
    );
    var specialized_output: [1290 + 64]u8 = @splat(0xa5);
    var specialized_written: usize = 0;
    try decodePredefinedOffsetFsePredefinedHuffman(
        block,
        &specialized_section,
        specialized_section.sequence_payload_offset + 1,
        &specialized_output,
        &specialized_written,
        0,
        specialized_state.repeated_offsets,
        &specialized_lookup.table,
    );
    try std.testing.expectEqual(generic_section.regenerated_size, test_small_mixed_fse_fast_literal_hits);
    try std.testing.expectEqual(@as(usize, 17), test_small_mixed_fse_match_56_hits);
    try std.testing.expectEqual(@as(usize, 18), test_small_mixed_fse_match_6_7_hits);
    try std.testing.expect(test_small_mixed_field_group_hits > 30);
    try std.testing.expectEqual(@as(usize, 33), test_small_mixed_single_literal_hits);
    try std.testing.expect(test_small_mixed_reservoir_literal_hits >= 48);

    try std.testing.expectEqual(payload.items.len, generic_written);
    try std.testing.expectEqual(generic_written, specialized_written);
    try std.testing.expectEqualSlices(u8, payload.items, generic_output[0..generic_written]);
    try std.testing.expectEqualSlices(u8, &generic_output, &specialized_output);
    try std.testing.expectEqual(@as(?SequenceTables, null), generic_state.previous_tables);
    try std.testing.expectEqual(@as(?SequenceTables, null), specialized_state.previous_tables);
    try std.testing.expectEqual(initial_repeated_offsets, generic_state.repeated_offsets);
    try std.testing.expectEqual(initial_repeated_offsets, specialized_state.repeated_offsets);

    var public_output: [1290 + 64]u8 = @splat(0xa5);
    try std.testing.expectEqual(payload.items.len, try decodeFrameInto(&encoded, &public_output));
    try std.testing.expectEqualSlices(u8, &specialized_output, &public_output);

    var reusable_decoder = NativeFrameDecoder.init(std.testing.allocator);
    defer reusable_decoder.deinit();
    var reusable_output: [1290 + 64]u8 = @splat(0xa5);
    _ = try reusable_decoder.decodeIntoSlice(&encoded, &reusable_output);
    try std.testing.expectEqual(@as(usize, 0), reusable_decoder.reusableHuffmanTreeHitCount());
    test_small_mixed_fse_match_56_hits = 0;
    test_small_mixed_fse_match_6_7_hits = 0;
    test_small_mixed_single_literal_hits = 0;
    try std.testing.expectEqual(payload.items.len, try reusable_decoder.decodeIntoSlice(&encoded, &reusable_output));
    try std.testing.expectEqualSlices(u8, &specialized_output, &reusable_output);
    try std.testing.expectEqual(@as(usize, 1), reusable_decoder.reusableHuffmanTreeHitCount());
    try std.testing.expectEqual(@as(usize, 1), reusable_decoder.reusableSequenceTableHitCount());
    try std.testing.expectEqual(@as(usize, 17), test_small_mixed_fse_match_56_hits);
    try std.testing.expectEqual(@as(usize, 18), test_small_mixed_fse_match_6_7_hits);
    try std.testing.expectEqual(@as(usize, 33), test_small_mixed_single_literal_hits);

    var missed_frame = encoded;
    missed_frame[first_block.payload_offset + generic_section.sequence_payload_offset] = 0;
    var missed_output: [1290 + 64]u8 = @splat(0x5a);
    try std.testing.expectEqual(@as(?usize, null), try tryDecodeSmallPredefinedOffsetFseFrame(&missed_frame, &missed_output));
    for (&missed_output) |byte| try std.testing.expectEqual(@as(u8, 0x5a), byte);

    var bad_content_size = encoded;
    bad_content_size[5] -= 1;
    var generic_bad_size_output: [1290 + 64]u8 = undefined;
    try std.testing.expectError(error.SizeMismatch, decodeNativeFrameInto(&bad_content_size, &generic_bad_size_output));
    var public_bad_size_output: [1290 + 64]u8 = undefined;
    try std.testing.expectError(error.SizeMismatch, decodeFrameInto(&bad_content_size, &public_bad_size_output));

    var generic_short: [1289]u8 = undefined;
    var generic_short_written: usize = 0;
    var generic_short_state: SequenceFrameState = .{};
    const generic_short_section = try parseLiteralsSection(block, &generic_short_state);
    try std.testing.expectError(error.OutputTooSmall, decodeRleSequencesCompressedBlockIntoBuffer(
        block,
        generic_short_section,
        &generic_short,
        &generic_short_written,
        0,
        &.{},
        &generic_short_state,
        .terminal,
        false,
    ));

    var specialized_short: [1289]u8 = undefined;
    var specialized_short_written: usize = 0;
    var specialized_short_state: SequenceFrameState = .{};
    const specialized_short_section = try parseLiteralsSection(block, &specialized_short_state);
    try std.testing.expectError(error.OutputTooSmall, decodePredefinedOffsetFsePredefinedHuffman(
        block,
        &specialized_short_section,
        specialized_short_section.sequence_payload_offset + 1,
        &specialized_short,
        &specialized_short_written,
        0,
        specialized_short_state.repeated_offsets,
        null,
    ));
    try std.testing.expectEqual(generic_short_written, specialized_short_written);
    try std.testing.expectEqualSlices(u8, generic_short[0..generic_short_written], specialized_short[0..specialized_short_written]);
    try std.testing.expectError(error.OutputTooSmall, tryDecodeSmallPredefinedOffsetFseFrame(&encoded, &specialized_short));

    var saw_invalid_match = false;
    var mutation_cases: usize = 0;
    for (generic_section.sequence_payload_offset + 1..block.len) |byte_index| {
        for (0..8) |bit_index| {
            var mutated = encoded;
            mutated[first_block.payload_offset + byte_index] ^= @as(u8, 1) << @as(u3, @intCast(bit_index));
            const mutated_block = mutated[first_block.payload_offset..][0..first_block.payload_len];
            var mutated_generic_state: SequenceFrameState = .{};
            const mutated_generic_section = try parseLiteralsSection(mutated_block, &mutated_generic_state);
            var mutated_generic_output: [1290]u8 = undefined;
            var mutated_generic_written: usize = 0;
            const generic_result = decodeRleSequencesCompressedBlockIntoBuffer(
                mutated_block,
                mutated_generic_section,
                &mutated_generic_output,
                &mutated_generic_written,
                0,
                &.{},
                &mutated_generic_state,
                .terminal,
                false,
            );
            var mutated_specialized_state: SequenceFrameState = .{};
            const mutated_specialized_section = try parseLiteralsSection(mutated_block, &mutated_specialized_state);
            var mutated_specialized_output: [1290]u8 = undefined;
            var mutated_specialized_written: usize = 0;
            if (generic_result) |_| {
                try decodePredefinedOffsetFsePredefinedHuffman(
                    mutated_block,
                    &mutated_specialized_section,
                    mutated_specialized_section.sequence_payload_offset + 1,
                    &mutated_specialized_output,
                    &mutated_specialized_written,
                    0,
                    mutated_specialized_state.repeated_offsets,
                    null,
                );
                try std.testing.expectEqual(mutated_generic_written, mutated_specialized_written);
                try std.testing.expectEqualSlices(
                    u8,
                    mutated_generic_output[0..mutated_generic_written],
                    mutated_specialized_output[0..mutated_specialized_written],
                );
            } else |err| {
                try std.testing.expectError(err, decodePredefinedOffsetFsePredefinedHuffman(
                    mutated_block,
                    &mutated_specialized_section,
                    mutated_specialized_section.sequence_payload_offset + 1,
                    &mutated_specialized_output,
                    &mutated_specialized_written,
                    0,
                    mutated_specialized_state.repeated_offsets,
                    null,
                ));
                saw_invalid_match = saw_invalid_match or err == error.InvalidMatch;
            }
            // Reuse the same cache across changed FSE descriptions and
            // malformed sequence payloads, then compare with the generic
            // block decoder before the frame layer remaps size errors.
            var mutated_cached_state: SequenceFrameState = .{};
            var mutated_cached_written: usize = 0;
            var mutated_cached_output: [1290 + 16]u8 = @splat(0xa5);
            const cached_result = decodeLiteralOnlyCompressedBlockIntoBufferWithSequenceWorkspace(
                mutated_block,
                mutated_cached_output[0..1290],
                &mutated_cached_written,
                128 * 1024,
                0,
                &.{},
                &mutated_cached_state,
                .terminal,
                reusable_decoder.sequence_workspace.?,
                false,
            );
            if (generic_result) |_| {
                try cached_result;
                try std.testing.expectEqual(mutated_generic_written, mutated_cached_written);
                try std.testing.expectEqualSlices(u8, mutated_generic_output[0..mutated_generic_written], mutated_cached_output[0..mutated_cached_written]);
            } else |err| try std.testing.expectError(err, cached_result);
            for (mutated_cached_output[1290..]) |byte| try std.testing.expectEqual(@as(u8, 0xa5), byte);
            mutation_cases += 1;
        }
    }
    try std.testing.expect(mutation_cases >= 100);
    try std.testing.expect(saw_invalid_match);
    @memset(&reusable_output, 0xa5);
    try std.testing.expectEqual(payload.items.len, try reusable_decoder.decodeIntoSlice(&encoded, &reusable_output));
    try std.testing.expectEqualSlices(u8, &specialized_output, &reusable_output);
}

test "zstd dense sparse-literal blocks select grouped decode" {
    try decode_policy_tests.run(@This(), &test_disable_split_huffman_decode, &test_split_huffman_field_group_hits);
}

test "zstd split Huffman all-FSE path matches generic decode" {
    defer {
        test_disable_split_huffman_decode = false;
        test_split_huffman_decode_hits = 0;
        test_split_huffman_single_literal_hits = 0;
        test_split_huffman_match_68_70_hits = 0;
        test_split_huffman_match_6_63_hits = 0;
        test_split_huffman_positive_rep0_hits = 0;
        test_split_huffman_compact_literal_rep0_hits = 0;
        test_split_huffman_direct_offset_hits = 0;
        test_split_huffman_direct_offset_single_literal_hits = 0;
        test_split_huffman_direct_offset_match_68_71_hits = 0;
        test_split_huffman_direct_offset_fast_hits = 0;
        test_split_huffman_short_literal_hits = 0;
        test_split_huffman_common_sequence_hits = 0;
        test_split_huffman_compact_direct_hits = 0;
        test_split_huffman_compact_pair_hits = 0;
        test_split_huffman_short_rep0_fast_hits = 0;
        test_split_huffman_field_group_hits = 0;
        test_large_fse_no_low_builder_hits = 0;
    }
    const encoded_hex_file = @embedFile("zstd/testdata/libzstd-large-json-128k.frame.hex");
    var encoded: [2874]u8 = undefined;
    var encoded_len: usize = 0;
    var encoded_lines = std.mem.tokenizeAny(u8, encoded_hex_file, " \r\n\t");
    while (encoded_lines.next()) |line| {
        if (line.len & 1 != 0 or encoded.len - encoded_len < line.len / 2) return error.InvalidLength;
        _ = try std.fmt.hexToBytes(encoded[encoded_len..][0 .. line.len / 2], line);
        encoded_len += line.len / 2;
    }
    try std.testing.expectEqual(encoded.len, encoded_len);

    var payload: std.ArrayList(u8) = .empty;
    defer payload.deinit(std.testing.allocator);
    try appendStructuredZstdJsonPayload(std.testing.allocator, &payload, 128 * 1024);
    const expected = payload.items[0 .. 128 * 1024];

    var interleaved_stage = try prepareNativeInterleavedDecodeStage(
        std.testing.allocator,
        &encoded,
        expected,
        .{
            .min_sequence_count = 1024,
            .max_sequence_count = 4096,
            .require_match_wildcopy = false,
        },
    );
    defer interleaved_stage.deinit();
    const interleaved_stage_shape = interleaved_stage.shape();
    try std.testing.expect(interleaved_stage_shape.block_count != 0);
    try std.testing.expectEqual(@as(usize, 1834), interleaved_stage_shape.sequence_count);
    const interleaved_stage_result = try interleaved_stage.decode();
    try std.testing.expectEqual(interleaved_stage_shape.decoded_bytes, interleaved_stage_result.decoded_bytes);
    try std.testing.expectEqual(interleaved_stage_shape.block_count, interleaved_stage_result.block_count);
    try std.testing.expectEqualSlices(u8, expected, interleaved_stage.decoded());

    const first_block = try inspectNativeFrameFirstBlock(&encoded);
    try std.testing.expect(first_block.last);
    try std.testing.expectEqual(NativeBlockType.compressed, first_block.block_type);
    const block = encoded[first_block.payload_offset..][0..first_block.payload_len];
    var frame_state: SequenceFrameState = .{};
    const section = try parseLiteralsSection(block, &frame_state);
    var sequence_offset = section.sequence_payload_offset;
    const spec = try resolveSequenceModeSpec(
        try parseSequenceModeSpec(block, &sequence_offset, section.sequence_count),
        null,
    );
    try std.testing.expect(section.huffman_streams == .four);
    try std.testing.expect(section.regenerated_size <= 4096);
    try std.testing.expect(section.sequence_count >= 1024);
    try std.testing.expect(sequence_decode_policy.preferSmall(section.regenerated_size, section.sequence_count));
    try std.testing.expect(sequence_decode_policy.preferSmallCopies(section.regenerated_size, section.sequence_count));
    try std.testing.expectEqual(SymbolMode.compressed, spec.ll_mode);
    try std.testing.expectEqual(SymbolMode.compressed, spec.of_mode);
    try std.testing.expectEqual(SymbolMode.compressed, spec.ml_mode);
    const output_len = expected.len + 64;
    const fast_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(fast_output);
    const generic_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(generic_output);
    @memset(fast_output, 0xa5);
    @memset(generic_output, 0xa5);

    const medium_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(medium_output);
    @memset(medium_output, 0xa5);
    var medium_written: usize = 0;
    var medium_frame_state: SequenceFrameState = .{};
    var medium_state = try initSequenceDecodeState(
        &spec,
        section.sequence_count,
        try ReverseBitReader.init(block[spec.bitstream_offset..]),
        medium_frame_state.repeated_offsets,
    );
    try std.testing.expect(try tryDecodeMediumSplitHuffmanSequences(
        section,
        medium_output[0..expected.len],
        &medium_written,
        0,
        &medium_frame_state,
        .terminal,
        &medium_state,
    ));
    try std.testing.expectEqual(expected.len, medium_written);
    try std.testing.expectEqualSlices(u8, expected, medium_output[0..medium_written]);
    for (medium_output[medium_written..]) |byte| try std.testing.expectEqual(@as(u8, 0xa5), byte);

    test_disable_split_huffman_decode = false;
    test_split_huffman_decode_hits = 0;
    test_split_huffman_single_literal_hits = 0;
    test_split_huffman_match_68_70_hits = 0;
    test_split_huffman_match_6_63_hits = 0;
    test_split_huffman_positive_rep0_hits = 0;
    test_split_huffman_compact_literal_rep0_hits = 0;
    test_split_huffman_direct_offset_hits = 0;
    test_split_huffman_direct_offset_single_literal_hits = 0;
    test_split_huffman_direct_offset_match_68_71_hits = 0;
    test_split_huffman_direct_offset_fast_hits = 0;
    test_split_huffman_short_literal_hits = 0;
    test_split_huffman_common_sequence_hits = 0;
    test_split_huffman_compact_direct_hits = 0;
    test_split_huffman_compact_pair_hits = 0;
    test_split_huffman_short_rep0_fast_hits = 0;
    test_split_huffman_field_group_hits = 0;
    test_large_fse_no_low_builder_hits = 0;
    const fast_written = try decodeNativeFrameInto(&encoded, fast_output);
    try std.testing.expectEqual(@as(usize, 3), test_large_fse_no_low_builder_hits);
    try std.testing.expectEqual(@as(usize, 1), test_split_huffman_decode_hits);
    try std.testing.expect(test_split_huffman_single_literal_hits > 1000);
    try std.testing.expect(test_split_huffman_match_68_70_hits > 100);
    try std.testing.expect(test_split_huffman_match_6_63_hits > 0);
    try std.testing.expect(test_split_huffman_positive_rep0_hits > 1000);
    try std.testing.expect(test_split_huffman_compact_literal_rep0_hits > 1000);
    try std.testing.expect(test_split_huffman_common_sequence_hits > 500);
    try std.testing.expect(test_split_huffman_compact_direct_hits > 500);
    try std.testing.expect(test_split_huffman_compact_pair_hits > 100);
    try std.testing.expect(test_split_huffman_direct_offset_fast_hits > 100);
    try std.testing.expect(test_split_huffman_short_rep0_fast_hits > 100);
    try std.testing.expect(test_split_huffman_field_group_hits > 1000);

    var discarded_table_state: SequenceFrameState = .{ .retain_sequence_tables = false };
    var discarded_output: [expected.len]u8 = undefined;
    var discarded_written: usize = 0;
    try decodeRleSequencesCompressedBlockIntoBuffer(
        block,
        section,
        &discarded_output,
        &discarded_written,
        0,
        &.{},
        &discarded_table_state,
        .followed_by_block,
        true,
    );
    try std.testing.expectEqual(expected.len, discarded_written);
    try std.testing.expectEqualSlices(u8, expected, &discarded_output);
    try std.testing.expectEqual(@as(?SequenceTables, null), discarded_table_state.previous_tables);

    test_disable_split_huffman_decode = true;
    defer test_disable_split_huffman_decode = false;
    const generic_written = try decodeNativeFrameInto(&encoded, generic_output);

    const dense_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(dense_output);
    @memset(dense_output, 0xa5);
    var dense_written: usize = 0;
    var dense_frame_state: SequenceFrameState = .{};
    var dense_state = try initSequenceDecodeState(
        &spec,
        section.sequence_count,
        try ReverseBitReader.init(block[spec.bitstream_offset..]),
        dense_frame_state.repeated_offsets,
    );
    test_split_huffman_direct_offset_hits = 0;
    test_split_huffman_short_literal_hits = 0;
    test_split_huffman_field_group_hits = 0;
    try std.testing.expect(try decodeAllFseSplitHuffmanSequences(
        split_huffman_literal_capacity,
        true,
        true,
        false,
        section,
        dense_output,
        &dense_written,
        0,
        &dense_frame_state,
        .terminal,
        &dense_state,
        false,
    ));

    try std.testing.expectEqual(expected.len, fast_written);
    try std.testing.expectEqual(fast_written, generic_written);
    try std.testing.expectEqual(fast_written, dense_written);
    try std.testing.expect(test_split_huffman_field_group_hits > 1000);
    try std.testing.expectEqualSlices(u8, expected, fast_output[0..fast_written]);
    try std.testing.expectEqualSlices(u8, fast_output, generic_output);
    try std.testing.expectEqualSlices(u8, fast_output, dense_output);
    try std.testing.expect(test_split_huffman_direct_offset_hits > 0);
    try std.testing.expect(test_split_huffman_short_literal_hits > 0);

    const wide_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(wide_output);
    @memset(wide_output, 0xa5);
    var wide_frame_state: SequenceFrameState = .{};
    var wide_state = try initSequenceDecodeState(
        &spec,
        section.sequence_count,
        try ReverseBitReader.init(block[spec.bitstream_offset..]),
        wide_frame_state.repeated_offsets,
    );
    var wide_written: usize = 0;
    try std.testing.expect(try tryDecodeAllFseSplitWideHuffmanSequences(
        section,
        wide_output[0..expected.len],
        &wide_written,
        0,
        &wide_frame_state,
        .terminal,
        &wide_state,
        true,
    ));
    try std.testing.expectEqual(fast_written, wide_written);
    try std.testing.expectEqualSlices(u8, fast_output, wide_output);

    const generic_split_output = try std.testing.allocator.alloc(u8, output_len);
    defer std.testing.allocator.free(generic_split_output);
    @memset(generic_split_output, 0xa5);
    var generic_split_frame_state: SequenceFrameState = .{};
    var generic_split_state = try initSequenceDecodeState(
        &spec,
        section.sequence_count,
        try ReverseBitReader.init(block[spec.bitstream_offset..]),
        initial_repeated_offsets,
    );
    var generic_split_written: usize = 0;
    try std.testing.expect(try tryDecodeGenericSplitHuffmanSequences(
        section,
        generic_split_output,
        &generic_split_written,
        0,
        &generic_split_frame_state,
        .terminal,
        &generic_split_state,
    ));
    try std.testing.expectEqual(fast_written, generic_split_written);
    try std.testing.expectEqualSlices(u8, fast_output, generic_split_output);

    var invalid_frame_start_state = try initSequenceDecodeState(
        &spec,
        section.sequence_count,
        try ReverseBitReader.init(block[spec.bitstream_offset..]),
        initial_repeated_offsets,
    );
    var invalid_frame_start_written: usize = 0;
    try std.testing.expectError(error.CorruptFrame, tryDecodeAllFseSplitWideHuffmanSequences(
        section,
        wide_output,
        &invalid_frame_start_written,
        1,
        &wide_frame_state,
        .terminal,
        &invalid_frame_start_state,
        true,
    ));

    @memset(fast_output, 0x3c);
    @memset(generic_output, 0x3c);
    test_disable_split_huffman_decode = false;
    try std.testing.expectError(error.OutputTooSmall, decodeNativeFrameInto(
        &encoded,
        fast_output[0 .. expected.len - 1],
    ));
    test_disable_split_huffman_decode = true;
    try std.testing.expectError(error.OutputTooSmall, decodeNativeFrameInto(
        &encoded,
        generic_output[0 .. expected.len - 1],
    ));
    try std.testing.expectEqualSlices(u8, fast_output, generic_output);

    const bitstream_start = first_block.payload_offset + spec.bitstream_offset;
    const bitstream_bits = (encoded.len - bitstream_start) * 8;
    try std.testing.expect(bitstream_bits >= 64);
    for (0..64) |mutation_index| {
        const bit = mutation_index * bitstream_bits / 64;
        var mutated = try std.testing.allocator.dupe(u8, &encoded);
        defer std.testing.allocator.free(mutated);
        mutated[bitstream_start + bit / 8] ^= @as(u8, 1) << @as(u3, @intCast(bit & 7));
        @memset(fast_output, 0xa5);
        @memset(generic_output, 0xa5);

        test_disable_split_huffman_decode = false;
        const before_hits = test_split_huffman_decode_hits;
        const fast_result = decodeNativeFrameInto(mutated, fast_output);
        try std.testing.expectEqual(before_hits + 1, test_split_huffman_decode_hits);
        test_disable_split_huffman_decode = true;
        const generic_result = decodeNativeFrameInto(mutated, generic_output);
        // Exercise grouped reads directly even though this compact fixture's
        // public selector prefers the small-literal specialization.
        @memset(wide_output, 0xa5);
        var mutated_wide_written: usize = 0;
        var mutated_wide_frame_state: SequenceFrameState = .{};
        const wide_result: Error!bool = blk: {
            const reader = ReverseBitReader.init(mutated[bitstream_start..first_block.next_header_offset]) catch |err| break :blk err;
            var mutated_wide_state = initSequenceDecodeState(&spec, section.sequence_count, reader, initial_repeated_offsets) catch |err| break :blk err;
            break :blk tryDecodeAllFseSplitWideHuffmanSequences(
                section,
                wide_output[0..expected.len],
                &mutated_wide_written,
                0,
                &mutated_wide_frame_state,
                .terminal,
                &mutated_wide_state,
                true,
            );
        };
        // Compare block errors at the same layer, excluding the frame checksum.
        @memset(dense_output, 0xa5);
        var block_reference_written: usize = 0;
        var block_reference_state: SequenceFrameState = .{};
        const block_reference = decodeRleSequencesCompressedBlockIntoBuffer(
            mutated[first_block.payload_offset..first_block.next_header_offset],
            section,
            dense_output[0..expected.len],
            &block_reference_written,
            0,
            &.{},
            &block_reference_state,
            .terminal,
            false,
        );
        if (block_reference) |_| {
            try std.testing.expect(try wide_result);
            try std.testing.expectEqual(block_reference_written, mutated_wide_written);
            try std.testing.expectEqualSlices(u8, dense_output[0..block_reference_written], wide_output[0..mutated_wide_written]);
        } else |err| try std.testing.expectError(err, wide_result);
        for (wide_output[expected.len..]) |byte| try std.testing.expectEqual(@as(u8, 0xa5), byte);
        if (fast_result) |fast_len| {
            const generic_len = try generic_result;
            try std.testing.expectEqual(fast_len, generic_len);
            try std.testing.expectEqualSlices(u8, fast_output[0..fast_len], generic_output[0..generic_len]);
        } else |fast_err| {
            try std.testing.expectError(fast_err, generic_result);
        }
    }

    const literal_start = first_block.payload_offset + section.literal_payload_offset;
    const literal_bits = section.compressed_size * 8;
    try std.testing.expect(literal_bits >= 64);
    for (0..64) |mutation_index| {
        const bit = mutation_index * literal_bits / 64;
        var mutated = try std.testing.allocator.dupe(u8, &encoded);
        defer std.testing.allocator.free(mutated);
        mutated[literal_start + bit / 8] ^= @as(u8, 1) << @as(u3, @intCast(bit & 7));
        @memset(fast_output, 0xa5);
        @memset(generic_output, 0xa5);

        test_disable_split_huffman_decode = false;
        const fast_result = decodeNativeFrameInto(mutated, fast_output);
        test_disable_split_huffman_decode = true;
        const generic_result = decodeNativeFrameInto(mutated, generic_output);
        if (fast_result) |fast_len| {
            const generic_len = try generic_result;
            try std.testing.expectEqual(fast_len, generic_len);
            try std.testing.expectEqualSlices(u8, fast_output[0..fast_len], generic_output[0..generic_len]);
        } else |fast_err| {
            try std.testing.expectError(fast_err, generic_result);
        }
    }
}

