test "zstd speed levels overlap multiblock primary and adaptive candidates" {
    var payload: [129 * 1024]u8 = undefined;
    var state: u32 = @truncate(0x9e37_79b9 +% 129 *% 0x10001 +% 16 *% 0x101 +% 23);
    for (&payload, 0..) |*byte, index| {
        state = state *% 1_664_525 +% 1_013_904_223;
        byte.* = if (index % 64 < 48) @truncate(index * 17) else @truncate(state >> 16);
    }
    const copy_len = payload.len / 4;
    @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);

    for ([_]c_int{ 1, 2, 3 }) |level| {
        const primary_options = try nativeFrameOptionsForLevel(level, .{});
        var expected = try encodeNativeFrameWithOptionsAlloc(std.testing.allocator, &payload, primary_options);
        defer std.testing.allocator.free(expected.frame);
        if (level <= 2) {
            const preflight = try encodeNativeFrameWithOptionsAlloc(
                std.testing.allocator,
                &payload,
                adaptiveLevelCandidateOptions(primary_options, preflightAdaptiveBlockSize(level)),
            );
            if (preflight.frame.len < expected.frame.len) {
                std.testing.allocator.free(expected.frame);
                expected = preflight;
            } else std.testing.allocator.free(preflight.frame);
        }
        for (adaptiveLevelBlockSizes(level)) |block_size| {
            const candidate = try encodeNativeFrameWithOptionsAlloc(std.testing.allocator, &payload, adaptiveLevelCandidateOptions(primary_options, block_size));
            if (candidate.frame.len < expected.frame.len) {
                std.testing.allocator.free(expected.frame);
                expected = candidate;
            } else std.testing.allocator.free(candidate.frame);
        }

        const actual = try encodeFrameWithLevelAlloc(std.testing.allocator, &payload, level);
        defer std.testing.allocator.free(actual);
        try std.testing.expectEqual(if (level <= 2) @as(usize, 27_363) else 27_517, actual.len);
        try std.testing.expectEqualSlices(u8, expected.frame, actual);
        var reusable = LevelFrameEncoder.init(std.testing.allocator);
        defer reusable.deinit();
        try std.testing.expectEqualSlices(u8, actual, try reusable.encodeScratch(&payload, level));
        const decoded = try decodeFrameAlloc(std.testing.allocator, actual);
        defer std.testing.allocator.free(decoded);
        try std.testing.expectEqualSlices(u8, &payload, decoded);
    }
}

test "zstd decisive larger adaptive candidate matches exhaustive generated arbitration" {
    var decisive_cases: usize = 0;
    var preflight_cases: usize = 0;
    const levels = [_]c_int{ 1, 2, 3, 4, 5, 6, 9, 22 };
    for (levels) |level| {
        for ([_]usize{ 129 * 1024, 192 * 1024 }) |input_len| {
            for (0..4) |seed| {
                const payload = try std.testing.allocator.alloc(u8, input_len);
                defer std.testing.allocator.free(payload);
                var random_state: u32 = @truncate(0x243f_6a88 +% seed *% 0x0100_0193 +% input_len);
                for (payload, 0..) |*byte, i| {
                    random_state = random_state *% 1_664_525 +% 1_013_904_223;
                    const structured_len: usize = 40 + (seed % 4) * 4;
                    byte.* = if (i % 64 < structured_len)
                        @truncate(i * 17 + seed * 13)
                    else
                        @truncate(random_state >> 16);
                }
                if (seed & 1 != 0) {
                    const copy_len = payload.len / 4;
                    @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
                }

                const policy = try nativeEncodeLevelDiagnostics(level, .{});
                const primary = try encodeNativeFrameWithOptionsAlloc(std.testing.allocator, payload, policy.primary_options);
                defer std.testing.allocator.free(primary.frame);
                const larger = try encodeNativeFrameWithOptionsAlloc(
                    std.testing.allocator,
                    payload,
                    adaptiveLevelCandidateOptions(policy.primary_options, policy.adaptive_block_sizes[1]),
                );
                defer std.testing.allocator.free(larger.frame);
                const smaller = try encodeNativeFrameWithOptionsAlloc(
                    std.testing.allocator,
                    payload,
                    adaptiveLevelCandidateOptions(policy.primary_options, policy.adaptive_block_sizes[0]),
                );
                defer std.testing.allocator.free(smaller.frame);
                const preflight = try encodeNativeFrameWithOptionsAlloc(
                    std.testing.allocator,
                    payload,
                    adaptiveLevelCandidateOptions(policy.primary_options, preflightAdaptiveBlockSize(level)),
                );
                defer std.testing.allocator.free(preflight.frame);
                const preflight_frame = if (level >= 19 and larger.frame.len < preflight.frame.len)
                    larger.frame
                else
                    preflight.frame;
                if (largerAdaptiveCandidateIsDecisive(payload, larger.frame.len, primary.frame.len)) {
                    decisive_cases += 1;
                    try std.testing.expect(larger.frame.len <= smaller.frame.len);
                }
                const preflight_hit = !preferSerialMixedSearch(payload) and
                    hasQuarterTailHistoryEvidence(payload) and
                    preflight_frame.len <= payload.len / 4;
                if (preflight_hit) {
                    preflight_cases += 1;
                    try std.testing.expect(preflight_frame.len <= primary.frame.len);
                    try std.testing.expect(preflight_frame.len <= larger.frame.len);
                    try std.testing.expect(preflight_frame.len <= smaller.frame.len);
                }

                const fast = try encodeFrameWithLevelAndOptionsAlloc(std.testing.allocator, payload, level, .{});
                defer std.testing.allocator.free(fast);
                const exhaustive = try encodeFrameWithLevelAndOptionsAllocImpl(false, std.testing.allocator, payload, level, .{});
                defer std.testing.allocator.free(exhaustive);
                if (preflight_hit)
                    try std.testing.expectEqualSlices(u8, preflight_frame, fast)
                else
                    try std.testing.expectEqualSlices(u8, exhaustive, fast);
            }
        }
    }
    try std.testing.expect(decisive_cases != 0);
    try std.testing.expect(preflight_cases != 0);
}

