        byte.* = if (index % 64 < 48) @truncate(index * 17) else @truncate(state >> 16);
    }
    try std.testing.expect(!preferSerialMixedSearch(&payload));

    try std.testing.expect(shouldProbeDecisiveWideMatch(&payload, 16, true));
    try std.testing.expect(!shouldProbeDecisiveWideMatch(&payload, 15, true));
    try std.testing.expect(!shouldProbeDecisiveWideMatch(&payload, 96, false));
    for ([_]usize{ 16, 32, 64, 96 }) |budget| {
        var consensus: std.ArrayList(u8) = .empty;
        defer consensus.deinit(std.testing.allocator);
        try consensus.appendSlice(std.testing.allocator, "prefix");
        var beam_scratch: lz77.RepBeamScratch = .{};
        defer beam_scratch.deinit(std.testing.allocator);
        var beam_stats: ?lz77.PlanStats = null;
        try std.testing.expect(try emitDecisiveWideMatchCompressedBlock(std.testing.allocator, &consensus, &payload, true, .strict, &beam_scratch, &beam_stats));
        try std.testing.expect(beam_stats != null);
        try std.testing.expectEqualSlices(u8, "prefix", consensus.items[0.."prefix".len]);
        try std.testing.expectEqual(@as(usize, "prefix".len + 8600), consensus.items.len);
        var exhaustive: std.ArrayList(u8) = .empty;
        defer exhaustive.deinit(std.testing.allocator);
        try std.testing.expect(try emitNativeMatchCompressedBlockSerialWithBeam(std.testing.allocator, &exhaustive, &payload, true, budget, true, null, null));
        try std.testing.expectEqualSlices(u8, exhaustive.items, consensus.items["prefix".len..]);
        var selected: std.ArrayList(u8) = .empty;
        defer selected.deinit(std.testing.allocator);
        try std.testing.expect(try emitNativeMatchCompressedBlockWithWideProbe(std.testing.allocator, &selected, &payload, true, budget, null));
        try std.testing.expectEqualSlices(u8, exhaustive.items, selected.items);
    }
}

test "zstd wide consensus applies current frame sequence state directly" {
    var payload: [33 * 1024]u8 = undefined;
    var random_state: u32 = 0xfeed_beef;
    for (&payload, 0..) |*byte, index| {
        random_state = random_state *% 1_664_525 +% 1_013_904_223;
        byte.* = if (index % 64 < 48) @truncate(index * 17) else @truncate(random_state >> 16);
    }

    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, payload.len * 2, .{ .content_checksum = false });
    var sequence_state: SequenceEncoderState = .{};
    var beam: lz77.RepBeamScratch = .{};
    defer beam.deinit(std.testing.allocator);

    var first: std.ArrayList(u8) = .empty;
    defer first.deinit(std.testing.allocator);
    var first_state_applied = false;
    try std.testing.expect(try emitNativeMatchCompressedBlockWithWideProbeForFrame(
        std.testing.allocator,
        &first,
        &payload,
        false,
        16,
        &beam,
        &sequence_state,
        &first_state_applied,
        null,
    ));
    try std.testing.expect(first_state_applied);
    try appendSequenceCandidateAndCommit(std.testing.allocator, &frame, first.items, false, &sequence_state);

    var direct: std.ArrayList(u8) = .empty;
    defer direct.deinit(std.testing.allocator);
    var second_state_applied = false;
    try std.testing.expect(try emitNativeMatchCompressedBlockWithWideProbeForFrame(
        std.testing.allocator,
        &direct,
        &payload,
        true,
        16,
        &beam,
        &sequence_state,
        &second_state_applied,
        null,
    ));
    try std.testing.expect(second_state_applied);
    var strict: std.ArrayList(u8) = .empty;
    defer strict.deinit(std.testing.allocator);
    var strict_state_applied = true;
    try std.testing.expect(try emitNativeMatchCompressedBlockWithWideProbeForFrame(
        std.testing.allocator,
        &strict,
        &payload,
        true,
        96,
        &beam,
        &sequence_state,
        &strict_state_applied,
        null,
    ));
    try std.testing.expect(!strict_state_applied);

    var rewritten: std.ArrayList(u8) = .empty;
    defer rewritten.deinit(std.testing.allocator);
    try std.testing.expect(try emitNativeMatchCompressedBlockWithWideProbe(
        std.testing.allocator,
        &rewritten,
        &payload,
        true,
        16,
        &beam,
    ));
    try std.testing.expect(try prepareSequenceCandidateForFrame(
        std.testing.allocator,
        &rewritten,
        &payload,
        true,
        &sequence_state,
    ));
    try std.testing.expectEqualSlices(u8, rewritten.items, direct.items);
    try frame.appendSlice(std.testing.allocator, direct.items);

    const first_block = try inspectNativeFrameFirstBlock(frame.items);
    const second_block = try inspectNativeFrameBlockAt(frame.items, first_block.next_header_offset);
    const second_modes = try inspectNativeFrameBlockSequenceModes(frame.items, second_block);
    try std.testing.expect(second_modes.sequence_count > max_native_sequence_count);
    try std.testing.expect(
        second_modes.literal_length_mode == .repeat or
            second_modes.offset_mode == .repeat or
            second_modes.match_length_mode == .repeat,
    );
    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, &payload, decoded[0..payload.len]);
    try std.testing.expectEqualSlices(u8, &payload, decoded[payload.len..]);

    const Test = struct {
        fn run(allocator: std.mem.Allocator, input: []const u8, initial_state: SequenceEncoderState) !void {
            var output: std.ArrayList(u8) = .empty;
            defer output.deinit(allocator);
            try output.appendSlice(allocator, "prefix");
            var local_beam: lz77.RepBeamScratch = .{};
            defer local_beam.deinit(allocator);
            var state_applied = true;
            const result = emitNativeMatchCompressedBlockWithWideProbeForFrame(
                allocator,
                &output,
                input,
                true,
                16,
                &local_beam,
                &initial_state,
                &state_applied,
                null,
            ) catch |err| {
                try std.testing.expect(!state_applied);
                try std.testing.expectEqualSlices(u8, "prefix", output.items);
                return err;
            };
            try std.testing.expect(result);
            try std.testing.expect(state_applied);
            try std.testing.expectEqualSlices(u8, "prefix", output.items[0.."prefix".len]);
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Test.run, .{ &payload, sequence_state });
}

test "zstd level one single-state beam audits generated block sizes" {
    var changed: usize = 0;
    var larger: usize = 0;
    var smaller: usize = 0;
    var total_single: usize = 0;
    var total_double: usize = 0;
    var worst_extra: usize = 0;
    for (0..64) |seed| {
        const length = 16 * 1024 + (seed % 4) * 4 * 1024;
        const payload = try std.testing.allocator.alloc(u8, length);
        defer std.testing.allocator.free(payload);
        var state: u32 = @truncate(0x243f_6a88 +% seed *% 0x0100_0193);
        for (payload, 0..) |*byte, index| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @truncate(index * 17 + seed * 13),
                1 => if (index % 64 < 52) @intCast('a' + (index + seed) % 23) else @truncate(state >> 24),
                2 => @truncate((state >> 16) ^ (index / 31)),
                else => @truncate((index * 37 + (index / 7) * 13) ^ (index >> 3)),
            };
        }
        if (seed % 3 == 0) {
            const copy_len = payload.len / 4;
            @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
        }

        var single: std.ArrayList(u8) = .empty;
        defer single.deinit(std.testing.allocator);
        const single_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
            std.testing.allocator,
            &single,
            payload,
            true,
            fastest_wide_match_search_budget,
            true,
            null,
            null,
        );
        var double: std.ArrayList(u8) = .empty;
        defer double.deinit(std.testing.allocator);
        const double_ok = try emitNativeMatchCompressedBlockSerialWithTwoStateBeamReference(
            std.testing.allocator,
            &double,
            payload,
            true,
            fastest_wide_match_search_budget,
            null,
        );
        const single_len = if (single_ok) single.items.len else payload.len + 3;
        const double_len = if (double_ok) double.items.len else payload.len + 3;
        changed += @intFromBool(single_len != double_len);
        larger += @intFromBool(single_len > double_len);
        smaller += @intFromBool(single_len < double_len);
        total_single += single_len;
        total_double += double_len;
        worst_extra = @max(worst_extra, single_len -| double_len);
    }
    std.debug.print(
        "single beam audit: changed={d} larger={d} smaller={d} total={d}/{d} worst_extra={d}\n",
        .{ changed, larger, smaller, total_single, total_double, worst_extra },
    );
    try std.testing.expectEqual(@as(usize, 1), changed);
    try std.testing.expectEqual(@as(usize, 0), larger);
    try std.testing.expectEqual(@as(usize, 1), smaller);
    try std.testing.expectEqual(@as(usize, 0), worst_extra);
    try std.testing.expectEqual(total_double - 3, total_single);

    var json_changed: usize = 0;
    var json_total_single: usize = 0;
    var json_total_double: usize = 0;
    var json_worst_extra: usize = 0;
    for (0..24) |seed| {
        var payload: std.ArrayList(u8) = .empty;
        defer payload.deinit(std.testing.allocator);
        const target_len = 16 * 1024 + seed * 613;
        while (payload.items.len < target_len) {
            var line: [160]u8 = undefined;
            const formatted = try std.fmt.bufPrint(
                &line,
                "{{\"id\":{d},\"shard\":{d},\"service\":\"vort\",\"message\":\"single beam audit\"}}\n",
                .{ payload.items.len / 64, seed % 7 },
            );
            try payload.appendSlice(std.testing.allocator, formatted);
        }

        var single: std.ArrayList(u8) = .empty;
        defer single.deinit(std.testing.allocator);
        try std.testing.expect(try emitNativeMatchCompressedBlockSerialWithBeam(
            std.testing.allocator,
            &single,
            payload.items,
            true,
            fastest_wide_match_search_budget,
            true,
            null,
            null,
        ));
        var double: std.ArrayList(u8) = .empty;
        defer double.deinit(std.testing.allocator);
        try std.testing.expect(try emitNativeMatchCompressedBlockSerialWithTwoStateBeamReference(
            std.testing.allocator,
            &double,
            payload.items,
            true,
            fastest_wide_match_search_budget,
            null,
        ));
        json_changed += @intFromBool(single.items.len != double.items.len);
        json_total_single += single.items.len;
        json_total_double += double.items.len;
        json_worst_extra = @max(json_worst_extra, single.items.len -| double.items.len);
    }
    std.debug.print(
        "single beam JSON audit: changed={d} total={d}/{d} worst_extra={d}\n",
        .{ json_changed, json_total_single, json_total_double, json_worst_extra },
    );
    try std.testing.expectEqual(@as(usize, 20), json_changed);
    try std.testing.expectEqual(@as(usize, 12_581), json_total_single);
    try std.testing.expectEqual(@as(usize, 12_534), json_total_double);
    try std.testing.expectEqual(@as(usize, 3), json_worst_extra);
}

const LevelThreeBeamComparison = struct {
    selected_ok: bool,
    reference_ok: bool,
    raw_single_ok: bool,
    selected_len: usize,
    reference_len: usize,
    raw_single_len: usize,
    raw_single_fixed_bits: usize,
    double_fast_len: usize,
    double_fast_fixed_bits: usize,
    selected_equals_reference: bool,
};

fn compareLevelThreeSingleBeam(allocator: std.mem.Allocator, payload: []const u8) !LevelThreeBeamComparison {
    var selected: std.ArrayList(u8) = .empty;
    defer selected.deinit(allocator);
    const selected_ok = try emitNativeMatchCompressedBlockSerialWithBeam(
        allocator,
        &selected,
        payload,
        true,
        fast_wide_match_search_budget,
        true,
        null,
        null,
    );
    var reference: std.ArrayList(u8) = .empty;
    defer reference.deinit(allocator);
    const reference_ok = try emitNativeMatchCompressedBlockSerialWithTwoStateBeamReference(
        allocator,
        &reference,
        payload,
        true,
        fast_wide_match_search_budget,
        null,
    );
    var raw_single_scratch: single_beam_match.Scratch = .{};
    defer raw_single_scratch.deinit(allocator);
    const raw_single_stats = try single_beam_match.planReuse(&raw_single_scratch, allocator, payload);
    var raw_single: std.ArrayList(u8) = .empty;
    defer raw_single.deinit(allocator);
    const raw_single_ok = try emitHashTokenSequenceBlock(
        allocator,
        &raw_single,
        payload,
        true,
        raw_single_scratch.reversed.items,
        raw_single_stats,
    );
    var double_fast_tokens: std.ArrayList(lz77.Token) = .empty;
    defer double_fast_tokens.deinit(allocator);
    const double_fast_stats = try double_fast_match.planReuse(
        &double_fast_tokens,
        allocator,
        payload,
        zstdHashParserOptions(payload.len),
    );
    var double_fast: std.ArrayList(u8) = .empty;
    defer double_fast.deinit(allocator);
    const double_fast_ok = try emitHashTokenSequenceBlock(
        allocator,
        &double_fast,
        payload,
        true,
        double_fast_tokens.items,
        double_fast_stats,
    );
    return .{
        .selected_ok = selected_ok,
        .reference_ok = reference_ok,
        .raw_single_ok = raw_single_ok,
        .selected_len = if (selected_ok) selected.items.len else payload.len + 3,
        .reference_len = if (reference_ok) reference.items.len else payload.len + 3,
        .raw_single_len = if (raw_single_ok) raw_single.items.len else payload.len + 3,
        .raw_single_fixed_bits = lz77.fixedBitCost(raw_single_scratch.reversed.items),
        .double_fast_len = if (double_fast_ok) double_fast.items.len else payload.len + 3,
        .double_fast_fixed_bits = lz77.fixedBitCost(double_fast_tokens.items),
        .selected_equals_reference = selected_ok == reference_ok and std.mem.eql(u8, selected.items, reference.items),
    };
}

test "zstd level three single-state beam audits generated block sizes" {
    var changed: usize = 0;
    var larger: usize = 0;
    var smaller: usize = 0;
    var total_single: usize = 0;
    var total_double: usize = 0;
    var worst_extra: usize = 0;
    var policy_selected: usize = 0;
    var absolute_selected: usize = 0;
    var absolute_larger: usize = 0;
    var absolute_worst_extra: usize = 0;
    var proxy_selected: usize = 0;
    var proxy_larger: usize = 0;
    var proxy_worst_extra: usize = 0;
    for (0..128) |seed| {
        const length = 32 * 1024 + 1 + (seed % 7) * 4 * 1024;
        const payload = try std.testing.allocator.alloc(u8, length);
        defer std.testing.allocator.free(payload);
        var state: u32 = @truncate(0x9e37_79b9 +% seed *% 0x0100_0193);
        for (payload, 0..) |*byte, index| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 7) {
                0 => @truncate(state >> 24),
                1 => @intCast('a' + (index + seed) % 23),
                2 => if (index % 64 < 52) @intCast('a' + (index / 7 + seed) % 19) else @truncate(state >> 24),
                3 => @truncate((index * 37 + (index / 11) * 17 + seed) & 0xff),
                4 => @intCast('0' + (index / 13 + seed) % 10),
                5 => if (index % 96 < 80) @intCast('A' + (index / 17 + seed) % 26) else @truncate(state >> 16),
                6 => @truncate((index / 5) ^ (index * 29) ^ seed),
                else => @truncate((state >> 16) ^ (index / 31)),
            };
        }
        if (seed % 3 == 0) {
            const copy_len = payload.len / 4;
            @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
        }

        const comparison = try compareLevelThreeSingleBeam(std.testing.allocator, payload);
        try std.testing.expectEqual(comparison.reference_ok, comparison.selected_ok);
        const single_len = comparison.selected_len;
        const double_len = comparison.reference_len;
        const absolute_accept = shouldTryLevelThreeSingleBeam(payload, fast_wide_match_search_budget) and
            comparison.raw_single_ok and comparison.raw_single_len > payload.len / 128 and comparison.raw_single_len <= payload.len / 32;
        absolute_selected += @intFromBool(absolute_accept);
        if (absolute_accept and comparison.raw_single_len > double_len) {
            absolute_larger += 1;
            absolute_worst_extra = @max(absolute_worst_extra, comparison.raw_single_len - double_len);
        }
        const proxy_accept = absolute_accept and comparison.raw_single_fixed_bits <=
            comparison.double_fast_fixed_bits - comparison.double_fast_fixed_bits / 32;
        proxy_selected += @intFromBool(proxy_accept);
        if (proxy_accept and comparison.raw_single_len > double_len) {
            proxy_larger += 1;
            proxy_worst_extra = @max(proxy_worst_extra, comparison.raw_single_len - double_len);
        }
        changed += @intFromBool(single_len != double_len);
        larger += @intFromBool(single_len > double_len);
        smaller += @intFromBool(single_len < double_len);
        total_single += single_len;
        total_double += double_len;
        worst_extra = @max(worst_extra, single_len -| double_len);
        policy_selected += @intFromBool(!comparison.selected_equals_reference);
    }
    std.debug.print(
        "level three single beam audit: changed={d} larger={d} smaller={d} total={d}/{d} worst_extra={d} absolute_selected={d} absolute_larger={d} absolute_worst_extra={d} proxy_selected={d} proxy_larger={d} proxy_worst_extra={d}\n",
        .{ changed, larger, smaller, total_single, total_double, worst_extra, absolute_selected, absolute_larger, absolute_worst_extra, proxy_selected, proxy_larger, proxy_worst_extra },
    );
    try std.testing.expectEqual(@as(usize, 0), changed);
    try std.testing.expectEqual(@as(usize, 0), larger);
    try std.testing.expectEqual(@as(usize, 0), smaller);
    try std.testing.expectEqual(@as(usize, 0), worst_extra);
    try std.testing.expectEqual(total_double, total_single);
    try std.testing.expectEqual(@as(usize, 0), policy_selected);
    try std.testing.expectEqual(@as(usize, 0), absolute_selected);
    try std.testing.expectEqual(@as(usize, 0), absolute_larger);
    try std.testing.expectEqual(@as(usize, 0), absolute_worst_extra);
    try std.testing.expectEqual(@as(usize, 0), proxy_selected);
    try std.testing.expectEqual(@as(usize, 0), proxy_larger);
    try std.testing.expectEqual(@as(usize, 0), proxy_worst_extra);

    var json_changed: usize = 0;
    var json_larger: usize = 0;
    var json_total_single: usize = 0;
    var json_total_double: usize = 0;
    var json_worst_extra: usize = 0;
    var rejected_larger_single: usize = 0;
