test "zstd level three single-state policy audits structured families" {
    var eligible: usize = 0;
    var changed: usize = 0;
    var larger: usize = 0;
    var smaller: usize = 0;
    var total_selected: usize = 0;
    var total_reference: usize = 0;
    var worst_extra: usize = 0;
    var screened: usize = 0;
    var proxy_eligible: usize = 0;
    var proxy_larger: usize = 0;
    var proxy_smaller: usize = 0;
    var proxy_total: usize = 0;
    var proxy_worst_extra: usize = 0;

    for (0..4) |shape| {
        for (0..16) |seed| {
            var payload: std.ArrayList(u8) = .empty;
            defer payload.deinit(std.testing.allocator);
            const target_len = 32 * 1024 + 1 + seed * 733;
            while (payload.items.len < target_len) {
                var line: [256]u8 = undefined;
                const row = payload.items.len / 64;
                const formatted = switch (shape) {
                    0 => try std.fmt.bufPrint(
                        &line,
                        "{{\"id\":{d},\"shard\":{d},\"service\":\"gateway\",\"status\":{d},\"message\":\"structured event\"}}\n",
                        .{ row, seed % 7, 200 + row % 9 },
                    ),
                    1 => try std.fmt.bufPrint(
                        &line,
                        "2026-09-12T12:{d:0>2}:{d:0>2}Z level=INFO worker={d} request={d} status=complete bytes={d}\n",
                        .{ row % 60, seed % 60, seed % 8, row, row * 17 },
                    ),
                    2 => try std.fmt.bufPrint(
                        &line,
                        "pub fn handler_{d}(state: *State) !void {{ state.items[{d}] +%= {d}; }}\n",
                        .{ row % 97, row % 31, seed + row % 13 },
                    ),
                    else => try std.fmt.bufPrint(
                        &line,
                        "2026-09-12T12:{d:0>2}:{d:0>2}Z,service-{d},region-{d},{d},{d},ok\n",
                        .{ row % 60, seed % 60, row % 11, seed % 5, row, row * 29 },
                    ),
                };
                try payload.appendSlice(std.testing.allocator, formatted);
            }

            if (!shouldTryLevelThreeSingleBeam(payload.items, fast_wide_match_search_budget)) {
                screened += 1;
                continue;
            }
            const comparison = try compareLevelThreeSingleBeam(std.testing.allocator, payload.items);
            try std.testing.expect(comparison.selected_ok and comparison.reference_ok and comparison.raw_single_ok);
            const accepted = acceptLevelThreeSingleBeam(
                comparison.raw_single_len,
                comparison.raw_single_fixed_bits,
                comparison.double_fast_fixed_bits,
                payload.items.len,
            );
            eligible += @intFromBool(accepted);
            changed += @intFromBool(comparison.selected_len != comparison.reference_len);
            larger += @intFromBool(comparison.selected_len > comparison.reference_len);
            smaller += @intFromBool(comparison.selected_len < comparison.reference_len);
            total_selected += comparison.selected_len;
            total_reference += comparison.reference_len;
            worst_extra = @max(worst_extra, comparison.selected_len -| comparison.reference_len);
            const proxy_accept = comparison.raw_single_len > payload.items.len / 128 and
                comparison.raw_single_len <= payload.items.len / 32 and
                comparison.raw_single_fixed_bits <= comparison.double_fast_fixed_bits - comparison.double_fast_fixed_bits / 32;
            const proxy_len = if (proxy_accept) comparison.raw_single_len else comparison.reference_len;
            proxy_eligible += @intFromBool(proxy_accept);
            proxy_larger += @intFromBool(proxy_len > comparison.reference_len);
            proxy_smaller += @intFromBool(proxy_len < comparison.reference_len);
            proxy_total += proxy_len;
            proxy_worst_extra = @max(proxy_worst_extra, proxy_len -| comparison.reference_len);
        }
    }

    std.debug.print(
        "level three structured-family audit: screened={d} eligible={d} changed={d} larger={d} smaller={d} total={d}/{d} worst_extra={d} proxy_eligible={d} proxy_larger={d} proxy_smaller={d} proxy_total={d} proxy_worst_extra={d}\n",
        .{ screened, eligible, changed, larger, smaller, total_selected, total_reference, worst_extra, proxy_eligible, proxy_larger, proxy_smaller, proxy_total, proxy_worst_extra },
    );
    try std.testing.expectEqual(@as(usize, 16), screened);
    try std.testing.expectEqual(@as(usize, 0), eligible);
    try std.testing.expectEqual(@as(usize, 0), changed);
    try std.testing.expectEqual(@as(usize, 0), larger);
    try std.testing.expectEqual(@as(usize, 0), smaller);
    try std.testing.expectEqual(total_reference, total_selected);
    try std.testing.expectEqual(@as(usize, 0), worst_extra);
    try std.testing.expectEqual(@as(usize, 0), proxy_eligible);
    try std.testing.expectEqual(@as(usize, 0), proxy_larger);
    try std.testing.expectEqual(@as(usize, 0), proxy_smaller);
    try std.testing.expectEqual(total_reference, proxy_total);
    try std.testing.expectEqual(@as(usize, 0), proxy_worst_extra);
}

test "zstd level one bounded single-state chain preserves candidate bytes" {
    var changed: usize = 0;
    var total_fast: usize = 0;
    var total_deep: usize = 0;
    for (0..128) |seed| {
        const length = 4 * 1024 + (seed % 8) * 4 * 1024;
        const payload = try std.testing.allocator.alloc(u8, length);
        defer std.testing.allocator.free(payload);
        var state: u32 = @truncate(0x6a09_e667 +% seed *% 0x0100_0193);
        for (payload, 0..) |*byte, index| {
            state = state *% 1_664_525 +% 1_013_904_223;
            byte.* = switch (seed & 3) {
                0 => @truncate(state >> 24),
                1 => @intCast('a' + (index + seed) % 23),
                2 => if (index % 64 < 52) @intCast('a' + (index / 7 + seed) % 19) else @truncate(state >> 24),
                else => @truncate((index * 37 + (index / 11) * 17 + seed) & 0xff),
            };
        }
        if (seed % 3 == 0) {
            const copy_len = payload.len / 4;
            @memcpy(payload[payload.len - copy_len ..], payload[payload.len / 4 ..][0..copy_len]);
        }

        var fast: std.ArrayList(u8) = .empty;
        defer fast.deinit(std.testing.allocator);
        const fast_ok = try emitNativeMatchCompressedBlockSerialWithBeam(std.testing.allocator, &fast, payload, true, fastest_wide_match_search_budget, true, null, null);
        var deep: std.ArrayList(u8) = .empty;
        defer deep.deinit(std.testing.allocator);
        const deep_ok = try emitNativeMatchCompressedBlockSerialWithDeepSingleBeamReference(std.testing.allocator, &deep, payload, true, fastest_wide_match_search_budget);
        changed += @intFromBool(fast_ok != deep_ok or (fast_ok and !std.mem.eql(u8, fast.items, deep.items)));
        total_fast += if (fast_ok) fast.items.len else payload.len + 3;
        total_deep += if (deep_ok) deep.items.len else payload.len + 3;
    }
    try std.testing.expectEqual(@as(usize, 0), changed);
    try std.testing.expectEqual(@as(usize, 649_786), total_fast);
    try std.testing.expectEqual(total_fast, total_deep);
}

test "zstd level one bounded single-state chain preserves collision candidate" {
    var payload: [1024]u8 = undefined;
    var random_state: u32 = 0x510e_527f;
    for (&payload) |*byte| {
        random_state = random_state *% 1_664_525 +% 1_013_904_223;
        byte.* = @truncate(random_state >> 24);
    }
    const source_start = 16;
    const target_start = 704;
    const match_len = 258;
    const target_word = std.mem.readInt(u32, payload[source_start..][0..4], .little);
    const target_hash = ((target_word *% 2_654_435_761) >> 17) & 4095;
    var collision_count: usize = 0;
    var word: u32 = 0;
    while (collision_count < 24) : (word +%= 1) {
        if (word == target_word or ((word *% 2_654_435_761) >> 17) & 4095 != target_hash) continue;
        std.mem.writeInt(u32, payload[384 + collision_count * 8 ..][0..4], word, .little);
        collision_count += 1;
    }
    @memcpy(payload[target_start..][0..match_len], payload[source_start..][0..match_len]);

    var fast: std.ArrayList(u8) = .empty;
    defer fast.deinit(std.testing.allocator);
    try std.testing.expect(try emitNativeMatchCompressedBlockSerialWithBeam(std.testing.allocator, &fast, &payload, true, fastest_wide_match_search_budget, true, null, null));
    var deep: std.ArrayList(u8) = .empty;
    defer deep.deinit(std.testing.allocator);
    try std.testing.expect(try emitNativeMatchCompressedBlockSerialWithDeepSingleBeamReference(std.testing.allocator, &deep, &payload, true, fastest_wide_match_search_budget));
    try std.testing.expectEqual(@as(usize, 779), fast.items.len);
    try std.testing.expectEqualSlices(u8, fast.items, deep.items);
}

test "zstd reusable encoder retains wide sequence scratch" {
    const block_len = 33 * 1024;
    var payload: [block_len * 2]u8 = undefined;
    for (0..2) |block_index| {
        const block = payload[block_index * block_len ..][0..block_len];
        var random_state: u32 = @truncate(0xfeed_beef +% block_index *% 0x9e37_79b9);
        for (block, 0..) |*byte, index| {
            random_state = random_state *% 1_664_525 +% 1_013_904_223;
            const low: u8 = if (index % 64 < 48) @truncate((index * 17) & 0x7f) else @truncate((random_state >> 16) & 0x7f);
            byte.* = low | @as(u8, @intCast(block_index << 7));
        }
    }
    const options: NativeFrameOptions = .{
        .selection = .literal_only,
        .content_checksum = false,
        .block_size_max = block_len,
        .match_search_budget = 16,
        .rep_beam_search = true,
    };
    var counting = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var encoder = NativeFrameEncoder.init(counting.allocator());
    var encoder_live = true;
    defer if (encoder_live) encoder.deinit();
    const first = try encoder.encodeScratch(&payload, options);
    const expected = try std.testing.allocator.dupe(u8, first.frame);
    defer std.testing.allocator.free(expected);
    const first_allocations = counting.allocations;
    const capacities = .{
        encoder.large_sequence_scratch.values.capacity,
        encoder.large_sequence_scratch.states.capacity,
        encoder.large_sequence_scratch.repeat_states.capacity,
        encoder.large_sequence_scratch.repeat_viable_masks.capacity,
        encoder.large_sequence_scratch.sequence_bits.capacity,
        encoder.block_scratch.candidate.capacity,
        encoder.block_scratch.best.capacity,
        encoder.block_scratch.match_candidate.capacity,
        encoder.block_scratch.match_best.capacity,
        encoder.block_scratch.greedy_tokens.capacity,
        encoder.block_scratch.lazy_tokens.capacity,
        encoder.block_scratch.optimal.costs.capacity,
        encoder.block_scratch.optimal.steps.capacity,
        encoder.block_scratch.optimal.compact_head.capacity,
        encoder.block_scratch.optimal.compact_prev.capacity,
        encoder.block_scratch.optimal.tokens.capacity,
    };
    const second = try encoder.encodeScratch(&payload, options);
    const second_allocations = counting.allocations - first_allocations;
    try std.testing.expectEqualSlices(u8, expected, second.frame);
    try std.testing.expectEqual(capacities, .{
        encoder.large_sequence_scratch.values.capacity,
        encoder.large_sequence_scratch.states.capacity,
        encoder.large_sequence_scratch.repeat_states.capacity,
        encoder.large_sequence_scratch.repeat_viable_masks.capacity,
        encoder.large_sequence_scratch.sequence_bits.capacity,
        encoder.block_scratch.candidate.capacity,
        encoder.block_scratch.best.capacity,
        encoder.block_scratch.match_candidate.capacity,
        encoder.block_scratch.match_best.capacity,
        encoder.block_scratch.greedy_tokens.capacity,
        encoder.block_scratch.lazy_tokens.capacity,
        encoder.block_scratch.optimal.costs.capacity,
        encoder.block_scratch.optimal.steps.capacity,
        encoder.block_scratch.optimal.compact_head.capacity,
        encoder.block_scratch.optimal.compact_prev.capacity,
        encoder.block_scratch.optimal.tokens.capacity,
    });
    try std.testing.expectEqual(first_allocations - 22, second_allocations);

    counting.fail_index = counting.alloc_index;
    try std.testing.expectError(error.OutOfMemory, encoder.encodeScratch(&payload, options));
    try std.testing.expectEqual(@as(usize, 0), encoder.output_scratch.items.len);
    counting.fail_index = std.math.maxInt(usize);
    const recovered = try encoder.encodeScratch(&payload, options);
    try std.testing.expectEqualSlices(u8, expected, recovered.frame);
    encoder.deinit();
    encoder_live = false;
    try std.testing.expectEqual(counting.allocated_bytes, counting.freed_bytes);
}

