        .stream_lens = .{ streams[0].len, streams[1].len, streams[2].len, streams[3].len },
        .dest_ptr = direct_output.ptr,
        .dest_len = direct_output.len,
    };
    try std.testing.expectEqual(huffman_x2_abi.Status.success, huffman_x2_test.decodeRequest(&request));
    try std.testing.expectEqualSlices(u8, payload, direct_output);
    request.stream_lens[0] -= 1;
    try std.testing.expectEqual(huffman_x2_abi.Status.truncated, huffman_x2_test.decodeRequest(&request));

    const std_decoded = try decodeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(std_decoded);
    try std.testing.expectEqualSlices(u8, payload, std_decoded);

    test_disable_x2_huffman_decode = false;
    test_x2_huffman_decode_hits = 0;
    defer {
        test_disable_x2_huffman_decode = false;
        test_x2_huffman_decode_hits = 0;
    }
    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
    try std.testing.expectEqual(@as(usize, 1), test_x2_huffman_decode_hits);
    try std.testing.expect(encoded.len < raw_encoded.len);

    const x1_output = try std.testing.allocator.alloc(u8, payload.len);
    defer std.testing.allocator.free(x1_output);
    test_disable_x2_huffman_decode = true;
    try std.testing.expectEqual(payload.len, try decodeNativeFrameInto(encoded, x1_output));
    try std.testing.expectEqualSlices(u8, decoded, x1_output);
    try std.testing.expectEqual(@as(usize, 1), test_x2_huffman_decode_hits);
    test_disable_x2_huffman_decode = false;

    var guarded_output = try std.testing.allocator.alloc(u8, payload.len + 64);
    defer std.testing.allocator.free(guarded_output);
    @memset(guarded_output, 0xa5);
    try std.testing.expectEqual(payload.len, try decodeNativeFrameInto(encoded, guarded_output));
    try std.testing.expectEqualSlices(u8, payload, guarded_output[0..payload.len]);
    for (guarded_output[payload.len..]) |byte| try std.testing.expectEqual(@as(u8, 0xa5), byte);
    try std.testing.expectError(error.OutputTooSmall, decodeNativeFrameInto(encoded, guarded_output[0 .. payload.len - 1]));

    // The interleaved bulk path must validate every reverse-stream end marker,
    // including streams it no longer visits through the shared cursor.
    const corrupt_output = try std.testing.allocator.alloc(u8, payload.len);
    defer std.testing.allocator.free(corrupt_output);
    for (streams) |stream| {
        const corrupt = try std.testing.allocator.dupe(u8, encoded);
        defer std.testing.allocator.free(corrupt);
        const stream_offset = @intFromPtr(stream.ptr) - @intFromPtr(block.ptr);
        corrupt[block_offset + 3 + stream_offset + stream.len - 1] = 0;
        try std.testing.expectError(error.CorruptFrame, decodeNativeFrameInto(corrupt, corrupt_output));
    }
}

test "zstd wide X2 table decodes seven-bit four-stream literals" {
    const payload = try std.testing.allocator.alloc(u8, 64 * 1024);
    defer std.testing.allocator.free(payload);
    var state: u32 = 31;
    for (payload) |*byte| {
        state = state *% 1_664_525 +% 1_013_904_223;
        byte.* = @intCast(32 + ((state >> 16) % 95));
    }

    const encoded = try encodeLiteralOnlyFrameAlloc(std.testing.allocator, payload);
    defer std.testing.allocator.free(encoded);
    var block_offset: usize = 4;
    _ = try parseRawOrRleFrameHeader(encoded, &block_offset);
    const block_header = std.mem.readInt(u24, encoded[block_offset..][0..3], .little);
    const block_len: usize = @intCast(block_header >> 3);
    const block = encoded[block_offset + 3 ..][0..block_len];
    var frame_state: SequenceFrameState = .{};
    const section = try parseLiteralsSection(block, &frame_state);
    try std.testing.expectEqual(LiteralsKind.compressed, section.kind);
    try std.testing.expectEqual(HuffmanLiteralStreams.four, std.meta.activeTag(section.huffman_streams));
    try std.testing.expectEqual(@as(usize, 0), section.sequence_count);
    const tree = section.huffman_tree orelse return error.CorruptFrame;
    try std.testing.expectEqual(@as(u4, 7), tree.max_bit_count);
    try std.testing.expect(section.compressed_size * 1000 > section.regenerated_size * 660);
    try std.testing.expect(section.compressed_size * 1000 <= section.regenerated_size * 900);

    const streams = section.huffman_streams.four;
    const guarded = try std.testing.allocator.alloc(u8, payload.len + 64);
    defer std.testing.allocator.free(guarded);
    @memset(guarded, 0xa5);
    var request: huffman_x2_abi.Request = .{
        .tree = &tree,
        .stream_ptrs = .{ streams[0].ptr, streams[1].ptr, streams[2].ptr, streams[3].ptr },
        .stream_lens = .{ streams[0].len, streams[1].len, streams[2].len, streams[3].len },
        .dest_ptr = guarded.ptr,
        .dest_len = payload.len,
    };
    try std.testing.expectEqual(huffman_x2_abi.Status.success, huffman_x2_test.decodeWideRequest(&request));
    try std.testing.expectEqualSlices(u8, payload, guarded[0..payload.len]);
    for (guarded[payload.len..]) |byte| try std.testing.expectEqual(@as(u8, 0xa5), byte);
    request.stream_lens[0] -= 1;
    try std.testing.expectEqual(huffman_x2_abi.Status.truncated, huffman_x2_test.decodeWideRequest(&request));

    test_disable_x2_huffman_decode = false;
    test_x2_huffman_decode_hits = 0;
    defer {
        test_disable_x2_huffman_decode = false;
        test_x2_huffman_decode_hits = 0;
    }
    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
    try std.testing.expectEqual(@as(usize, 1), test_x2_huffman_decode_hits);
}

test "zstd literal-only writer reuses Huffman tree across blocks" {
    const payload = try std.testing.allocator.alloc(u8, std.compress.zstd.block_size_max + 4096);
    defer std.testing.allocator.free(payload);
    var state: u32 = 0x577d_f00d;
    var payload_offset: usize = 0;
    while (payload_offset < payload.len) {
        var symbols: [64]u8 = undefined;
        for (&symbols, 0..) |*symbol, i| {
            symbol.* = @intCast(32 + i);
        }
        var i = symbols.len;
        while (i > 1) {
            i -= 1;
            state = state *% 1_664_525 +% 1_013_904_223;
            const j: usize = @intCast((state >> 16) % (i + 1));
            const tmp = symbols[i];
            symbols[i] = symbols[j];
            symbols[j] = tmp;
        }
        @memcpy(payload[payload_offset..][0..symbols.len], &symbols);
        payload_offset += symbols.len;
    }

    const encoded = try encodeLiteralOnlyFrameAlloc(std.testing.allocator, payload);
    defer std.testing.allocator.free(encoded);
    const raw_encoded = try encodeRawOrRleFrameAlloc(std.testing.allocator, payload);
    defer std.testing.allocator.free(raw_encoded);

    var block_offset: usize = 4;
    _ = try parseRawOrRleFrameHeader(encoded, &block_offset);
    const first_header = std.mem.readInt(u24, encoded[block_offset..][0..3], .little);
    try std.testing.expectEqual(@as(u24, 2), (first_header >> 1) & 0x3);
    try std.testing.expectEqual(false, (first_header & 1) != 0);
    const first_block_len: usize = @intCast(first_header >> 3);
    var frame_state: SequenceFrameState = .{};
    const first_section = try parseLiteralsSection(encoded[block_offset + 3 ..][0..first_block_len], &frame_state);
    try std.testing.expectEqual(LiteralsKind.compressed, first_section.kind);
    try std.testing.expectEqual(HuffmanLiteralStreams.four, std.meta.activeTag(first_section.huffman_streams));
    try std.testing.expectEqual(@as(usize, 0), first_section.sequence_count);

    block_offset += 3 + first_block_len;
    const second_header = std.mem.readInt(u24, encoded[block_offset..][0..3], .little);
    try std.testing.expectEqual(@as(u24, 2), (second_header >> 1) & 0x3);
    try std.testing.expectEqual(true, (second_header & 1) != 0);
    const second_block_len: usize = @intCast(second_header >> 3);
    const second_section = try parseLiteralsSection(encoded[block_offset + 3 ..][0..second_block_len], &frame_state);
    try std.testing.expectEqual(LiteralsKind.treeless, second_section.kind);
    try std.testing.expectEqual(HuffmanLiteralStreams.four, std.meta.activeTag(second_section.huffman_streams));
    try std.testing.expectEqual(@as(usize, 0), second_section.sequence_count);

    const std_decoded = try decodeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(std_decoded);
    try std.testing.expectEqualSlices(u8, payload, std_decoded);

    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, encoded);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, payload, decoded);
    try std.testing.expect(encoded.len < raw_encoded.len);

    const first_header_offset = (try inspectNativeFrameHeader(encoded)).payload_offset;
    const first_payload_len: usize = @intCast(std.mem.readInt(u24, encoded[first_header_offset..][0..3], .little) >> 3);
    const compressed_limit = first_payload_len + 3;
    try std.testing.expect(compressed_limit < encoded.len);
    var incremental = NativeIncrementalFrameDecoder.initWithOptions(std.testing.allocator, .{
        .expected_output_len = payload.len,
        .max_compressed_buffer_len = compressed_limit,
        .max_decoded_buffer_len = payload.len,
    });
    defer incremental.deinit();
    const incremental_output = try std.testing.allocator.alloc(u8, payload.len);
    defer std.testing.allocator.free(incremental_output);
    var incremental_input: usize = 0;
    var incremental_written: usize = 0;
    var saw_block_stream = false;
    while (incremental.snapshot().phase != .done) {
        const input_end = @min(encoded.len, incremental_input + 997);
        const output_end = @min(payload.len, incremental_written + 257);
        const step_result = try incremental.step(
            encoded[incremental_input..input_end],
            incremental_output[incremental_written..output_end],
        );
        incremental_input += step_result.progress.input_read;
        incremental_written += step_result.progress.output_written;
        saw_block_stream = saw_block_stream or incremental.isBlockStreaming();
        try std.testing.expectEqual(@as(usize, 0), incremental.decodedBufferedBytes());
        try std.testing.expectEqual(@as(usize, 0), incremental.decodedBufferCapacity());
        try std.testing.expect(incremental.compressedBufferCapacity() <= compressed_limit);
        if (step_result.status == .need_input) try std.testing.expect(incremental_input < encoded.len);
        if (step_result.status == .need_output) try std.testing.expect(incremental_written < payload.len);
    }
    try incremental.finish();
    try std.testing.expect(saw_block_stream);
    try std.testing.expectEqual(encoded.len, incremental_input);
    try std.testing.expectEqual(payload.len, incremental_written);
    try std.testing.expectEqualSlices(u8, payload, incremental_output);
}

