test "zstd known-valid compressed offset cost matches stateful scorer" {
    var literal_lens: [64]usize = undefined;
    var offsets: [64]usize = undefined;
    var state: u32 = 0x6a09_e667;
    for (&literal_lens, &offsets, 0..) |*literal_len, *offset, i| {
        state = state *% 1_664_525 +% 1_013_904_223;
        literal_len.* = if (i % 7 == 0) 0 else (state >> 29) + 1;
        offset.* = switch (i % 5) {
            0 => 1,
            1 => 4,
            2 => 8,
            else => 9 + (state & 2047),
        };
    }

    var compared: usize = 0;
    for ([_][3]usize{ initial_repeated_offsets, .{ 9, 5, 2 } }) |initial_offsets| {
        const plan = (try planCompressedOffsetSequenceValuesWithOffsets(
            &literal_lens,
            &offsets,
            initial_offsets,
        )) orelse continue;
        const expected = (try sequenceTablePlanBitCostWithOffsets(
            .{ .compressed = plan },
            .offset,
            &offsets,
            &literal_lens,
            &offsets,
            initial_offsets,
        )) orelse return error.CorruptFrame;
        try std.testing.expectEqual(expected, try compressedOffsetSequenceTablePlanBitCostKnownValid(&plan));
        compared += 1;
    }
    try std.testing.expect(compared != 0);
}

test "zstd wide borrowed sequence fields match by-value reference" {
    var literal_lens: [max_native_sequence_count]usize = undefined;
    var offsets: [max_native_sequence_count]usize = undefined;
    var match_lens: [max_native_sequence_count]usize = undefined;
    var state: u32 = 0x9e37_79b9;
    for (&literal_lens, &offsets, &match_lens, 0..) |*literal_len, *offset, *match_len, index| {
        state = state *% 1_664_525 +% 1_013_904_223;
        literal_len.* = if (index % 17 == 0) 0 else (state >> 28) % 9;
        state = state *% 1_664_525 +% 1_013_904_223;
        offset.* = 4 + state % 4092;
        state = state *% 1_664_525 +% 1_013_904_223;
        match_len.* = 3 + (state >> 25) % 96;
    }

    const narrow_plan = (try bestTablePlanSequenceWithLiteralsLen(
        literal_lens[0 .. wide_borrowed_sequence_plan_min - 1],
        offsets[0 .. wide_borrowed_sequence_plan_min - 1],
        match_lens[0 .. wide_borrowed_sequence_plan_min - 1],
        1234,
    )) orelse return error.CorruptFrame;
    var fields: [max_native_sequence_count * 6]BitField = undefined;
    try std.testing.expectError(
        error.CorruptFrame,
        sequenceReadFieldsWithTablePlansAndOffsetsBorrowed(
            &fields,
            literal_lens[0 .. wide_borrowed_sequence_plan_min - 1],
            offsets[0 .. wide_borrowed_sequence_plan_min - 1],
            match_lens[0 .. wide_borrowed_sequence_plan_min - 1],
            &narrow_plan.plan,
            initial_repeated_offsets,
        ),
    );

    var all_compressed_cases: usize = 0;
    for ([_]usize{ wide_borrowed_sequence_plan_min, max_native_sequence_count }) |len| {
        const plan = (try bestTablePlanSequenceWithLiteralsLen(
            literal_lens[0..len],
            offsets[0..len],
            match_lens[0..len],
            1234,
        )) orelse return error.CorruptFrame;
        var expected: [max_native_sequence_count * 6]BitField = undefined;
        const expected_count = try sequenceReadFieldsWithTablePlansAndOffsets(
            &expected,
            literal_lens[0..len],
            offsets[0..len],
            match_lens[0..len],
            plan.plan,
            initial_repeated_offsets,
        );
        var actual: [max_native_sequence_count * 6]BitField = undefined;
        const actual_count = try sequenceReadFieldsWithTablePlansAndOffsetsBorrowed(
            &actual,
            literal_lens[0..len],
            offsets[0..len],
            match_lens[0..len],
            &plan.plan,
            initial_repeated_offsets,
        );
        try std.testing.expectEqualSlices(BitField, expected[0..expected_count], actual[0..actual_count]);
        switch (plan.plan.literal) {
            .compressed => |*literal| switch (plan.plan.offset) {
                .compressed => |*offset| switch (plan.plan.match) {
                    .compressed => |*match| {
                        var specialized: [max_native_sequence_count * 6]BitField = undefined;
                        var initial_count: usize = 0;
                        try appendInitialSequenceStateFieldBorrowed(&specialized, &initial_count, &plan.plan.literal, .literal);
                        try appendInitialSequenceStateFieldBorrowed(&specialized, &initial_count, &plan.plan.offset, .offset);
                        try appendInitialSequenceStateFieldBorrowed(&specialized, &initial_count, &plan.plan.match, .match);
                        const specialized_count = try appendCompressedSequenceReadFields(
                            &specialized,
                            initial_count,
                            literal_lens[0..len],
                            offsets[0..len],
                            match_lens[0..len],
                            literal,
                            offset,
                            match,
                            initial_repeated_offsets,
                        );
                        try std.testing.expectEqualSlices(BitField, expected[0..expected_count], specialized[0..specialized_count]);
                        all_compressed_cases += 1;
                    },
                    else => {},
                },
                else => {},
            },
            else => {},
        }
    }
    try std.testing.expect(all_compressed_cases != 0);

    const sequence_count = wide_borrowed_sequence_plan_min;
    var payload: [sequence_count * 5]u8 = undefined;
    for (&payload, 0..) |*byte, index| byte.* = "abcd"[index & 3];
    var block_literal_lens: [sequence_count]usize = undefined;
    var block_offsets: [sequence_count]usize = @splat(4);
    var block_match_lens: [sequence_count]usize = undefined;
    var literal_ends: [sequence_count]usize = undefined;
    var position: usize = 0;
    for (0..sequence_count) |index| {
        const literal_len: usize = if (index == 0) 4 else if (index % 5 == 0) 1 else 0;
        const match_len: usize = if (index % 7 == 0) 3 else 4;
        block_literal_lens[index] = literal_len;
        block_match_lens[index] = match_len;
        position += literal_len + match_len;
        literal_ends[index] = position;
    }
    const block = payload[0..position];
    var literals_prefix: std.ArrayList(u8) = .empty;
    defer literals_prefix.deinit(std.testing.allocator);
    _ = try emitSequenceLiteralsSection(std.testing.allocator, &literals_prefix, block, &block_literal_lens, &literal_ends, position);
    const block_plan = (try bestTablePlanSequenceWithLiteralsLen(
        &block_literal_lens,
        &block_offsets,
        &block_match_lens,
        literals_prefix.items.len,
    )) orelse return error.CorruptFrame;
    var expected_block: std.ArrayList(u8) = .empty;
    defer expected_block.deinit(std.testing.allocator);
    try std.testing.expect(try emitSequenceCompressedBlockWithTablePlansAndOffsets(
        std.testing.allocator,
        &expected_block,
        block,
        true,
        &block_literal_lens,
        &block_offsets,
        &block_match_lens,
        &literal_ends,
        position,
        block_plan.plan,
        literals_prefix.items,
        null,
        initial_repeated_offsets,
    ));
    var actual_block: std.ArrayList(u8) = .empty;
    defer actual_block.deinit(std.testing.allocator);
    try std.testing.expect(try emitSequenceCompressedBlockWithTablePlansAndOffsetsBorrowed(
        std.testing.allocator,
        &actual_block,
        block,
        true,
        &block_literal_lens,
        &block_offsets,
        &block_match_lens,
        &literal_ends,
        position,
        &block_plan.plan,
        literals_prefix.items,
        null,
        initial_repeated_offsets,
    ));
    try std.testing.expectEqualSlices(u8, expected_block.items, actual_block.items);

    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, block.len, .{ .content_checksum = false });
    try frame.appendSlice(std.testing.allocator, actual_block.items);
    const decoded = try decodeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, block, decoded);
}

test "zstd sparse sequence alternatives match initialized reference" {
    const Test = struct {
        fn expectPlanEqual(expected: SequenceTableEmitPlan, actual: SequenceTableEmitPlan) !void {
            try std.testing.expectEqual(std.meta.activeTag(expected), std.meta.activeTag(actual));
            switch (expected) {
                .rle => |code| try std.testing.expectEqual(code, actual.rle),
                .predefined => |plan| {
                    const other = actual.predefined;
                    try std.testing.expectEqual(plan.len, other.len);
                    try std.testing.expectEqualSlices(u8, plan.states[0..plan.len], other.states[0..other.len]);
                },
                .compressed => |plan| {
                    const other = actual.compressed;
                    try std.testing.expectEqual(plan.len, other.len);
                    try std.testing.expectEqual(plan.accuracy_log, other.accuracy_log);
                    try std.testing.expectEqual(plan.initial_state, other.initial_state);
                    try std.testing.expectEqual(plan.value_bit_count, other.value_bit_count);
                    try std.testing.expectEqual(plan.transition_bit_count, other.transition_bit_count);
                    try std.testing.expectEqual(plan.table_payload_len, other.table_payload_len);
                    try std.testing.expectEqualSlices(u8, plan.codes[0..plan.len], other.codes[0..other.len]);
                    try std.testing.expectEqualSlices(u8, plan.next_states[0..plan.len], other.next_states[0..other.len]);
                    try std.testing.expectEqualSlices(u8, plan.state_bits[0..plan.len], other.state_bits[0..other.len]);
                    const transition_len = plan.len - 1;
                    try std.testing.expectEqualSlices(u8, plan.transition_values[0..transition_len], other.transition_values[0..transition_len]);
                    try std.testing.expectEqualSlices(u8, plan.transition_bits[0..transition_len], other.transition_bits[0..transition_len]);
                    try std.testing.expectEqualSlices(u8, plan.table_payload[0..plan.table_payload_len], other.table_payload[0..other.table_payload_len]);
                },
                .repeat => unreachable,
            }
        }

        fn expectAlternativesEqual(expected: SequenceTablePlanAlternatives, actual: SequenceTablePlanAlternatives) !void {
            try std.testing.expectEqual(expected.len, actual.len);
            for (expected.items[0..expected.len], actual.items[0..actual.len]) |want, got|
                try expectPlanEqual(want, got);
        }

        fn compare(
            expected: SequenceTablePlanAlternatives,
            actual: SequenceTablePlanAlternatives,
            kind: SequenceTableKind,
            values: []const usize,
            literal_lens: []const usize,
            offsets: []const usize,
            coverage: *u8,
        ) !void {
            for (expected.items[0..expected.len]) |want| {
                coverage.* |= switch (std.meta.activeTag(want)) {
                    .rle => 1,
                    .predefined => 2,
                    .compressed => 4,
                    .repeat => 8,
                };
            }
            var expected_best: ?usize = null;
            for (expected.items[0..expected.len]) |plan| {
                const cost = (try sequenceTablePlanBitCost(plan, kind, values, literal_lens, offsets)) orelse continue;
                const bytes = cost.payload_len + (cost.bit_count + 1 + 7) / 8;
                if (expected_best == null or bytes < expected_best.?) expected_best = bytes;
            }
            var actual_best: ?usize = null;
            for (actual.items[0..actual.len]) |plan| {
                const cost = (try sequenceTablePlanBitCost(plan, kind, values, literal_lens, offsets)) orelse continue;
                const bytes = cost.payload_len + (cost.bit_count + 1 + 7) / 8;
                if (actual_best == null or bytes < actual_best.?) actual_best = bytes;
            }
            try std.testing.expectEqual(expected_best, actual_best);
        }
    };

    var literal_lens: [128]usize = undefined;
    var offsets: [128]usize = undefined;
    var match_lens: [128]usize = undefined;
    var state: u32 = 0x243f_6a88;
    var coverage: u8 = 0;
    for (0..64) |case_index| {
        const len = 2 + case_index * 2;
        for (0..len) |i| {
            state = state *% 1_664_525 +% 1_013_904_223;
            literal_lens[i] = if (case_index % 8 == 0) 3 else (state >> 24) % 36;
            state = state *% 1_664_525 +% 1_013_904_223;
            match_lens[i] = if (case_index % 9 == 0) 7 else 3 + (state >> 24) % 51;
            state = state *% 1_664_525 +% 1_013_904_223;
            offsets[i] = 4 + (state % 4092);
        }
        inline for (.{ SequenceTableKind.literal, .match }) |kind| {
            const values = if (kind == .literal) literal_lens[0..len] else match_lens[0..len];
            const unshared = try sequenceTablePlanAlternativesWithPreviousUnshared(values, kind, null);
            const shared = try sequenceTablePlanAlternatives(values, kind);
            try Test.expectAlternativesEqual(unshared, shared);
            try Test.compare(
                try sequenceTablePlanAlternativesInitializedReference(values, kind),
                shared,
                kind,
                values,
                literal_lens[0..len],
                offsets[0..len],
                &coverage,
            );
        }
        try Test.compare(
            try offsetSequenceTablePlanAlternativesInitializedReference(literal_lens[0..len], offsets[0..len]),
            try offsetSequenceTablePlanAlternatives(literal_lens[0..len], offsets[0..len]),
            .offset,
            offsets[0..len],
            literal_lens[0..len],
            offsets[0..len],
            &coverage,
        );
    }
    try std.testing.expectEqual(@as(u8, 0x07), coverage & 0x07);
}

test "zstd sequence emitter supports mixed RLE and predefined tables" {
    var payload: [409]u8 = undefined;
    var cursor: usize = 0;
    @memset(payload[cursor..][0..74], 'A');
    cursor += 74;
    @memset(payload[cursor..][0..57], 'A');
    cursor += 57;
    @memset(payload[cursor..][0..76], 'B');
    cursor += 76;
    @memset(payload[cursor..][0..202], 'B');
    cursor += 202;
    try std.testing.expectEqual(payload.len, cursor);

    const literal_lens = [_]usize{ 74, 76 };
    const offsets = [_]usize{ 72, 52 };
    const match_lens = [_]usize{ 57, 202 };
    const literal_ends = [_]usize{ 131, payload.len };
    const table_plan = (try bestTablePlanSequence(&payload, &literal_lens, &offsets, &match_lens, &literal_ends, payload.len)) orelse return error.CorruptFrame;
    try std.testing.expectEqual(SymbolMode.rle, sequenceTableMode(table_plan.plan.literal));
    try std.testing.expectEqual(SymbolMode.predefined, sequenceTableMode(table_plan.plan.offset));
    try std.testing.expectEqual(SymbolMode.predefined, sequenceTableMode(table_plan.plan.match));
    try std.testing.expect(table_plan.payload_len < try multiSequencePayloadLenWithLiteralEnds(&payload, &literal_lens, &offsets, &match_lens, &literal_ends, payload.len));
    try std.testing.expectEqual(table_plan.payload_len, try bestSequencePayloadLenWithLiteralEnds(&payload, &literal_lens, &offsets, &match_lens, &literal_ends, payload.len));

    var frame: std.ArrayList(u8) = .empty;
    defer frame.deinit(std.testing.allocator);
    try emitFrameHeader(std.testing.allocator, &frame, payload.len, .{ .content_checksum = false });
    try std.testing.expect(try emitBestSequenceCompressedBlock(
        std.testing.allocator,
        &frame,
        &payload,
        true,
        &literal_lens,
        &offsets,
        &match_lens,
        &literal_ends,
        payload.len,
    ));

    const first_block = try inspectNativeFrameFirstBlock(frame.items);
    try std.testing.expectEqual(NativeBlockType.compressed, first_block.block_type);
    try std.testing.expectEqual(table_plan.payload_len, first_block.payload_len);
    const block = frame.items[first_block.payload_offset..][0..first_block.payload_len];
    var frame_state: SequenceFrameState = .{};
    const section = try parseLiteralsSection(block, &frame_state);
    try std.testing.expectEqual(@as(usize, literal_lens[0] + literal_lens[1]), section.regenerated_size);
    try std.testing.expectEqual(@as(usize, 2), section.sequence_count);
    try std.testing.expectEqual(@as(u8, 0x40), block[section.sequence_payload_offset]); // LL=RLE, OF/ML=Predefined.

    const decoded = try decodeNativeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, &payload, decoded);

    const std_decoded = try decodeFrameAlloc(std.testing.allocator, frame.items);
    defer std.testing.allocator.free(std_decoded);
    try std.testing.expectEqualSlices(u8, &payload, std_decoded);
}

