test "zstd compressed sequence state scratch fits one byte" {
    const values = [_]usize{ 8, 1, 2, 3, 2, 4, 3, 1, 2, 3, 2, 4, 3, 1, 2, 3 };
    const plan = (try planCompressedSequenceValues(&values, .literal)) orelse return error.CorruptFrame;
    try std.testing.expectEqual(@as(usize, 0), @sizeOf(@FieldType(CompressedSequencePlan, "packed_steps")));
    try std.testing.expect(plan.initial_state < max_predefined_sequence_states);
    for (plan.next_states[0..plan.len]) |state| try std.testing.expect(state < max_predefined_sequence_states);
    for (plan.transition_values[0 .. plan.len - 1], plan.transition_bits[0 .. plan.len - 1]) |value, bits| {
        try std.testing.expect(value < (@as(usize, 1) << @intCast(bits)));
    }
}

test "zstd large compressed sequence planner matches fixed-capacity planner" {
    const Test = struct {
        fn expectSame(expected: CompressedSequencePlan, actual: LargeCompressedSequencePlan) !void {
            try std.testing.expectEqual(expected.accuracy_log, actual.accuracy_log);
            try std.testing.expectEqual(expected.initial_state, actual.initial_state);
            try std.testing.expectEqual(expected.table_payload_len, actual.table_payload_len);
            try std.testing.expectEqualSlices(u8, expected.table_payload[0..expected.table_payload_len], actual.table_payload[0..actual.table_payload_len]);
            try std.testing.expectEqualSlices(u8, expected.codes[0..expected.len], actual.codes);
            try std.testing.expectEqualSlices(u8, expected.next_states[0..expected.len], actual.next_states);
            try std.testing.expectEqualSlices(u8, expected.state_bits[0..expected.len], actual.state_bits);
            try std.testing.expectEqualSlices(u8, expected.transition_values[0 .. expected.len - 1], actual.transition_values[0 .. actual.transition_values.len - 1]);
            try std.testing.expectEqualSlices(u8, expected.transition_bits[0 .. expected.len - 1], actual.transition_bits[0 .. actual.transition_bits.len - 1]);
        }
    };

    var values: [max_native_sequence_count]usize = undefined;
    var codes: [max_native_sequence_count]u8 = undefined;
    var next_states: [max_native_sequence_count]u8 = undefined;
    var state_bits: [max_native_sequence_count]u8 = undefined;
    var transition_values: [max_native_sequence_count]u8 = undefined;
    var transition_bits: [max_native_sequence_count]u8 = undefined;
    const buffers = LargeCompressedSequenceBuffers{
        .codes = &codes,
        .next_states = &next_states,
        .state_bits = &state_bits,
        .transition_values = &transition_values,
        .transition_bits = &transition_bits,
    };

    for (&values, 0..) |*value, i| value.* = i % 9;
    const expected_literal = (try planCompressedSequenceValues(&values, .literal)) orelse return error.CorruptFrame;
    const actual_literal = (try planLargeCompressedSequenceValues(&values, .literal, buffers)) orelse return error.CorruptFrame;
    try Test.expectSame(expected_literal, actual_literal);

    for (&values, 0..) |*value, i| value.* = lz77.min_match_len + i % 13;
    const expected_match = (try planCompressedSequenceValues(&values, .match)) orelse return error.CorruptFrame;
    const actual_match = (try planLargeCompressedSequenceValues(&values, .match, buffers)) orelse return error.CorruptFrame;
    try Test.expectSame(expected_match, actual_match);

    var literal_lens: [max_native_sequence_count]usize = undefined;
    var offsets: [max_native_sequence_count]usize = undefined;
    const offset_pattern = [_]usize{ 4, 4, 1, 8, 8, 4, 4, 8, 1, 1, 8, 4, 4, 8, 1, 1 };
    for (&literal_lens, &offsets, 0..) |*literal_len, *offset, i| {
        literal_len.* = if (i == 0) 8 else 1;
        offset.* = offset_pattern[i % offset_pattern.len];
    }
    const expected_offset = (try planCompressedOffsetSequenceValues(&literal_lens, &offsets)) orelse return error.CorruptFrame;
    const actual_offset = (try planLargeCompressedOffsetSequenceValues(&literal_lens, &offsets, buffers)) orelse return error.CorruptFrame;
    try Test.expectSame(expected_offset, actual_offset);
}

test "zstd large sequence plans select a larger FSE table" {
    var values: [256]usize = undefined;
    for (&values, 0..) |*value, i| value.* = 1 + i % 8;
    const plan = (try planCompressedSequenceValues(&values, .literal)) orelse return error.CorruptFrame;
    try std.testing.expectEqual(@as(u8, 7), plan.accuracy_log);
    const state_count = @as(usize, 1) << @as(u6, @intCast(plan.accuracy_log));
    try std.testing.expect(plan.initial_state < state_count);
    for (plan.next_states[0..plan.len]) |state| try std.testing.expect(state < state_count);
}

test "zstd large repeat planner sizes viability rows to the source table" {
    const sequence_count = max_native_sequence_count + 1;
    var codes: [sequence_count]u8 = @splat(0);
    var states: [sequence_count]u16 = undefined;
    var symbols: [max_sequence_fse_table_size]SequenceSymbol = undefined;
    var masks: [sequence_count * (max_sequence_fse_table_size / 64) + 1]u64 = undefined;

    for ([_]usize{ 64, 128, 256, 512 }) |table_len| {
        const state_bits: u8 = @intCast(std.math.log2_int(usize, table_len));
        for (symbols[0..table_len]) |*symbol| symbol.* = .{
            .base = 1,
            .additional_bits = 0,
            .next_state = 0,
            .state_bits = 0,
        };
        symbols[table_len - 1] = .{
            .base = 0,
            .additional_bits = 0,
            .next_state = @intCast(table_len - 1),
            .state_bits = 0,
        };
        const source: RepeatSequenceSource = .{
            .mode = .compressed,
            .rle = null,
            .symbols = symbols[0..table_len],
            .accuracy_log = state_bits,
        };
        const mask_words = table_len / 64;
        try std.testing.expectEqual(mask_words, try repeatSequenceMaskWordCount(source));
        @memset(&masks, 0xa5a5_a5a5_a5a5_a5a5);
        const required_mask_len = sequence_count * mask_words;
        const plan = (try planLargeRepeatSequenceCodes(&codes, .literal, source, &states, masks[0..required_mask_len])) orelse return error.CorruptFrame;
        try std.testing.expectEqual(sequence_count, plan.len);
        for (plan.states) |state| try std.testing.expectEqual(@as(u16, @intCast(table_len - 1)), state);
        try std.testing.expectEqual(@as(u64, 0xa5a5_a5a5_a5a5_a5a5), masks[required_mask_len]);
        try std.testing.expectEqual(@as(?LargeRepeatSequencePlan, null), try planLargeRepeatSequenceCodes(
            &codes,
            .literal,
            source,
            &states,
            masks[0 .. required_mask_len - 1],
        ));
    }
}

test "zstd reference FSE normalization preserves probability mass" {
    var state: u32 = 0x6a09_e667;
    for (5..9) |table_log| {
        for (2..33) |symbol_count| {
            var counts: [32]u32 = @splat(0);
            var total: usize = 0;
            for (counts[0..symbol_count]) |*count| {
                state = state *% 1_664_525 +% 1_013_904_223;
                count.* = 1 + (state >> 24);
                total += count.*;
            }
            var normalized: [32]i16 = @splat(0);
            normalizeFseCounts(counts[0..symbol_count], total, @intCast(table_log), normalized[0..symbol_count]) orelse return error.CorruptFrame;
            var sum: usize = 0;
            for (normalized[0..symbol_count]) |value| {
                try std.testing.expect(value != 0);
                sum += @abs(value);
            }
            try std.testing.expectEqual(@as(usize, 1) << @intCast(table_log), sum);
        }
    }
}

test "zstd reference FSE normalization improves locked sequence distributions" {
    const counts = [_]u32{ 184, 111, 73, 46, 31, 17, 9 };
