noinline fn tryDecodeSmallPredefinedOffsetFseFrame(
    frame: []const u8,
    output: []u8,
) linksection(small_sequence_decode_text_section) Error!?usize {
    if (frame.len > 4096 or frame.len < 9) return null;
    if (std.mem.readInt(u32, frame[0..4], .little) != frame_magic_u32) return null;

    var offset: usize = 4;
    const header = parseRawOrRleFrameHeaderWithOptions(frame, &offset, false) catch return null;
    if (header.has_checksum or header.content_size == null or header.content_size.? > 4096) return null;
    const output_len: usize = @intCast(header.content_size.?);
    if (output.len < output_len) return error.OutputTooSmall;
    if (frame.len - offset < 3) return null;
    const block_header = std.mem.readInt(u24, frame[offset..][0..3], .little);
    offset += 3;
    if ((block_header & 1) == 0 or ((block_header >> 1) & 0x3) != 2) return null;
    const block_len: usize = @intCast(block_header >> 3);
    if (frame.len - offset != block_len) return null;
    if (block_len > header.block_size_max) return null;
    const block = frame[offset..][0..block_len];

    var previous_huffman_tree: ?StdZstdHuffmanTree = null;
    var prepared_narrow: PreparedNarrowHuffmanLookup = .{};
    const section = parseLiteralsSectionWithPreviousTreeAndNarrowLookup(block, &previous_huffman_tree, &prepared_narrow) catch return null;
    if (section.regenerated_size > header.block_size_max or
        section.sequence_count < 2 or section.sequence_count > 256 or
        (section.kind != .compressed and section.kind != .treeless) or
        !prepared_narrow.complete or
        section.huffman_tree.?.max_bit_count > NarrowHuffmanLiteralLookup.bit_width or
        section.sequence_payload_offset >= block.len or
        block[section.sequence_payload_offset] != 0x20) return null;

    var written: usize = 0;
    try decodePredefinedOffsetFsePredefinedHuffman(
        block,
        &section,
        section.sequence_payload_offset + 1,
        output,
        &written,
        0,
        initial_repeated_offsets,
        &prepared_narrow.table,
    );
    if (written != output_len) return error.SizeMismatch;
    return written;
}

fn copySmallMixedHuffmanLiterals(
    cursor: *HuffmanLiteralCursor,
    tree: *const StdZstdHuffmanTree,
    lookup: *const NarrowHuffmanLiteralLookup,
    decoded: *usize,
    regenerated_size: usize,
    dest: []u8,
) Error!void {
    if (decoded.* > regenerated_size or regenerated_size - decoded.* < dest.len)
        return error.CorruptFrame;
    const width = tree.max_bit_count;
    if (width == 0 or width > NarrowHuffmanLiteralLookup.bit_width)
        return error.CorruptFrame;
    var output_index: usize = 0;
    if (cursor.streams == .one) {
        if (huffman_reservoir.Reservoir.init(cursor.reader)) |initial_reservoir| {
            var active = initial_reservoir;
            while (dest.len - output_index >= 8 and active.canDecodeEight(width)) {
                var symbols: [8]u8 = undefined;
                inline for (0..8) |symbol_index| {
                    const prefix = active.peek(NarrowHuffmanLiteralLookup.bit_width);
                    const entry = lookup.lookupAssumeComplete(prefix);
                    symbols[symbol_index] = entry.symbol;
                    active.consume(entry.bit_count);
                }
                dest[output_index..][0..8].* = symbols;
                active.reload();
                output_index += 8;
                decoded.* += 8;
                if (builtin.is_test) test_small_mixed_reservoir_literal_hits += 8;
            }
            cursor.reader.remaining_bits = active.remainingBits();
        }
    }
    try huffman_lookup.copyBorrowed(
        Error,
        cursor,
        tree,
        lookup,
        decoded,
        regenerated_size,
        decoded.*,
        dest[output_index..],
        readHuffmanLiteralSymbolFromCursorCold,
        expectHuffmanLiteralCursorEnd,
    );
}

noinline fn decodePredefinedOffsetFsePredefinedHuffman(
    block: []const u8,
    section: *const LiteralOnlySection,
    table_offset: usize,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    repeated_offsets: [3]usize,
    prepared_lookup: ?*const NarrowHuffmanLiteralLookup,
) linksection(small_sequence_decode_text_section) Error!void {
    std.debug.assert(section.sequence_count >= 2 and section.sequence_count <= 256);
    std.debug.assert(section.kind == .compressed or section.kind == .treeless);

    var offset = table_offset;
    var offset_fse: SequenceFseTable = undefined;
    try readFseSequenceTableInto(
        &offset_fse,
        block,
        &offset,
        &of_base,
        &of_bits,
        sequence_table_symbol_count_max.offset,
        sequence_table_accuracy_log_max.offset,
    );
    if (offset >= block.len) return error.TruncatedFrame;

    return decodePredefinedOffsetFsePredefinedHuffmanPrepared(block, section, offset, &offset_fse, output, written, frame_output_start, repeated_offsets, prepared_lookup);
}

/// A terminal block can borrow its resolved offset table until execution ends;
/// it does not need to copy the cached table or retain it as continuation state.
noinline fn decodeSmallHuffmanBlockWithSequenceWorkspace(
    block: []const u8,
    section: *const LiteralOnlySection,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    repeated_offsets: [3]usize,
    workspace: *SequenceDecodeWorkspace,
) linksection(small_sequence_decode_text_section) Error!void {
    const description_start = section.sequence_payload_offset;
    if (workspace.sequence.find(block, description_start, section.sequence_count)) |cached| {
        return decodePredefinedOffsetFsePredefinedHuffmanPrepared(block, section, description_start + cached.description_len, &cached.spec.offset_fse, output, written, frame_output_start, repeated_offsets, null);
    }
    var spec: SequenceModeSpec = undefined;
    var offset = description_start;
    try parseSequenceModeSpecInto(&spec, block, &offset, section.sequence_count);
    workspace.sequence.store(block, description_start, section.sequence_count, spec);
    return decodePredefinedOffsetFsePredefinedHuffmanPrepared(block, section, spec.bitstream_offset, &spec.offset_fse, output, written, frame_output_start, repeated_offsets, null);
}

noinline fn decodePredefinedOffsetFsePredefinedHuffmanPrepared(
    block: []const u8,
    section: *const LiteralOnlySection,
    bitstream_offset: usize,
    offset_fse: *const SequenceFseTable,
    output: []u8,
    written: *usize,
    frame_output_start: usize,
    repeated_offsets: [3]usize,
    prepared_lookup: ?*const NarrowHuffmanLiteralLookup,
) align(256) linksection(small_sequence_decode_text_section) Error!void {
    var reader = try ReverseBitReader.init(block[bitstream_offset..]);
    var ll_state = try reader.readSmall(6);
    var of_state = try reader.readSmall(@intCast(offset_fse.accuracy_log));
    var ml_state = try reader.readSmall(6);
    var repcodes = repeated_offsets;
    var local_huffman_lookup: NarrowHuffmanLiteralLookup = undefined;
    const huffman_tree = if (section.huffman_tree) |*tree| tree else return error.CorruptFrame;
    const huffman_lookup_table = prepared_lookup orelse lookup: {
        if (!local_huffman_lookup.buildComplete(huffman_tree)) return error.CorruptFrame;
        break :lookup &local_huffman_lookup;
    };
    var huffman_cursor = try initHuffmanLiteralCursor(block, section.*);
    var huffman_decoded: usize = 0;
    var remaining = section.sequence_count;

    while (remaining != 0) {
        if (ll_state >= sequence_predefined.literal_symbols.len or
            ml_state >= sequence_predefined.match_symbols.len or
            of_state >= offset_fse.len) return error.CorruptFrame;
        const ll_symbol = sequence_predefined.literal_symbols[ll_state];
        const of_symbol = offset_fse.entries[of_state];
        const ml_symbol = sequence_predefined.match_symbols[ml_state];
        const transition_bits: u8 = if (remaining == 1)
            0
        else
            ll_symbol.state_bits + ml_symbol.state_bits + of_symbol.state_bits;
        const total_bits = of_symbol.additional_bits + ml_symbol.additional_bits +
            ll_symbol.additional_bits + transition_bits;
        const sequence: DecodedSequence = if (total_bits <= 56 and reader.remaining_bits >= 64) grouped: {
            var fields = sequence_field_group.Group.init(&reader, total_bits) orelse unreachable;
            if (builtin.is_test) test_small_mixed_field_group_hits += 1;
            const offset_extra = fields.read(of_symbol.additional_bits);
            const match_len = std.math.add(usize, ml_symbol.base, fields.read(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
            const literal_len = std.math.add(usize, ll_symbol.base, fields.read(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
            const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &repcodes);
            remaining -= 1;
            if (remaining != 0) {
                ll_state = ll_symbol.next_state + fields.read(ll_symbol.state_bits);
                ml_state = ml_symbol.next_state + fields.read(ml_symbol.state_bits);
                of_state = of_symbol.next_state + fields.read(of_symbol.state_bits);
            } else try reader.expectEnd();
            break :grouped .{ .literal_len = literal_len, .match_len = match_len, .match_offset = match_offset };
        } else fallback: {
            const offset_extra = try reader.readSequenceField(of_symbol.additional_bits);
            const match_len = std.math.add(usize, ml_symbol.base, try reader.readSequenceField(ml_symbol.additional_bits)) catch return error.IntegerOverflow;
            const literal_len = std.math.add(usize, ll_symbol.base, try reader.readSequenceField(ll_symbol.additional_bits)) catch return error.IntegerOverflow;
            const match_offset = try resolveSequenceOffset(of_symbol.base, of_symbol.additional_bits, offset_extra, literal_len, &repcodes);
            remaining -= 1;
            if (remaining != 0) {
                ll_state = try nextSequenceState(&reader, ll_symbol);
                ml_state = try nextSequenceState(&reader, ml_symbol);
                of_state = try nextSequenceState(&reader, of_symbol);
            } else try reader.expectEnd();
            break :fallback .{ .literal_len = literal_len, .match_len = match_len, .match_offset = match_offset };
        };
        const literal_len = sequence.literal_len;
        const match_len = sequence.match_len;
        const match_offset = sequence.match_offset;

        if (output.len - written.* < literal_len) return error.OutputTooSmall;
        if (literal_len == 1 and
            huffman_decoded < section.regenerated_size and
            huffman_tree.max_bit_count != 0 and
            huffman_cursor.reader.available() >= huffman_tree.max_bit_count)
        {
            const width = huffman_tree.max_bit_count;
            const prefix = huffman_cursor.reader.peekBulkHuffman(width);
            const entry = huffman_lookup_table.lookupAssumeComplete(prefix << @intCast(NarrowHuffmanLiteralLookup.bit_width - width));
            huffman_cursor.reader.skipBulkHuffman(entry.bit_count);
            output[written.*] = entry.symbol;
            huffman_decoded += 1;
            if (builtin.is_test) test_small_mixed_single_literal_hits += 1;
            if (huffman_decoded == section.regenerated_size) try huffman_cursor.expectEnd();
        } else {
            const use_reservoir = literal_len >= 16 and switch (huffman_cursor.streams) {
                .one => true,
                .four, .none => false,
            };
            if (use_reservoir) {
                try copySmallMixedHuffmanLiterals(
                    &huffman_cursor,
                    huffman_tree,
                    huffman_lookup_table,
                    &huffman_decoded,
                    section.regenerated_size,
                    output[written.*..][0..literal_len],
                );
            } else {
                try huffman_lookup.copyBorrowed(
                    Error,
                    &huffman_cursor,
                    huffman_tree,
                    huffman_lookup_table,
                    &huffman_decoded,
                    section.regenerated_size,
                    huffman_decoded,
                    output[written.*..][0..literal_len],
                    readHuffmanLiteralSymbolFromCursorCold,
                    expectHuffmanLiteralCursorEnd,
                );
            }
        }
        if (comptime builtin.is_test) test_small_mixed_fse_fast_literal_hits += literal_len;
        written.* += literal_len;
        if (match_len == 56 and match_offset >= 56 and frame_output_start <= written.* and match_offset <= written.* - frame_output_start) {
            if (output.len - written.* < match_len) return error.OutputTooSmall;
            if (builtin.is_test) test_small_mixed_fse_match_56_hits += 1;
            sequence_match_copy.appendNonOverlapping56(output, written, written.* - match_offset);
        } else if ((match_len == 6 or match_len == 7) and match_offset >= match_len and frame_output_start <= written.* and match_offset <= written.* - frame_output_start) {
            if (output.len - written.* < match_len) return error.OutputTooSmall;
            if (builtin.is_test) test_small_mixed_fse_match_6_7_hits += 1;
            sequence_match_copy.appendNonOverlapping6Or7(output, written, written.* - match_offset, match_len);
        } else {
            try copyMatchFromHistory(output, written, frame_output_start, &.{}, match_offset, match_len);
        }
    }
    if (section.regenerated_size < huffman_decoded) return error.CorruptFrame;
    const last_literals = section.regenerated_size - huffman_decoded;
    if (output.len - written.* < last_literals) return error.OutputTooSmall;
    try huffman_lookup.copyBorrowed(
        Error,
        &huffman_cursor,
        huffman_tree,
        huffman_lookup_table,
        &huffman_decoded,
        section.regenerated_size,
        huffman_decoded,
        output[written.*..][0..last_literals],
        readHuffmanLiteralSymbolFromCursorCold,
        expectHuffmanLiteralCursorEnd,
    );
    if (comptime builtin.is_test) test_small_mixed_fse_fast_literal_hits += last_literals;
    written.* += last_literals;
}

noinline fn compressedSequencePlanStrictlyDominatesPredefinedCodes(
    plan: *const CompressedSequencePlan,
    kind: SequenceTableKind,
    predefined_values: []const usize,
) linksection(dominance_helper_text_section) Error!bool {
    if (plan.len == 0 or plan.len > max_native_sequence_count or plan.len != predefined_values.len) return error.CorruptFrame;
    const costs = switch (kind) {
        .literal => predefined_literal_minimum_costs[0..],
        .offset => predefined_offset_minimum_costs[0..],
        .match => predefined_match_minimum_costs[0..],
    };
    const value_bits = sequenceTableBits(kind);
    const compressed_bits = compressedSequencePlanBitCostKnownValid(plan).bit_count;
    var predefined_bits: usize = predefinedInitialStateBits(kind);
    for (0..plan.len) |i| {
        const code = compressedSequenceCode(plan, i);
        if (code >= value_bits.len) return error.CorruptFrame;
        const predefined_code = try sequenceCodeForValue(predefined_values[i], sequenceTableBases(kind), value_bits);
        if (predefined_code >= costs.len) return error.CorruptFrame;
        const predefined_cost = costs[predefined_code][@intFromBool(i + 1 < plan.len)];
        if (predefined_cost == std.math.maxInt(u8)) return false;
        predefined_bits = std.math.add(usize, predefined_bits, predefined_cost) catch return error.IntegerOverflow;
    }
    const compressed_bytes = std.math.add(usize, plan.table_payload_len, (compressed_bits + 1 + 7) / 8) catch return error.IntegerOverflow;
    const predefined_bytes = (predefined_bits + 1 + 7) / 8;
    return compressed_bytes < predefined_bytes;
}

noinline fn compressedSequencePlanStrictlyDominatesPredefinedCodeSlice(
    plan: *const CompressedSequencePlan,
    kind: SequenceTableKind,
    predefined_codes: []const u8,
) linksection(dominance_helper_text_section) Error!bool {
    if (plan.len == 0 or plan.len > max_native_sequence_count or plan.len != predefined_codes.len) return error.CorruptFrame;
    const costs = switch (kind) {
        .literal => predefined_literal_minimum_costs[0..],
        .offset => predefined_offset_minimum_costs[0..],
        .match => predefined_match_minimum_costs[0..],
    };
    const value_bits = sequenceTableBits(kind);
    const compressed_bits = compressedSequencePlanBitCostKnownValid(plan).bit_count;
    var predefined_bits: usize = predefinedInitialStateBits(kind);
    for (predefined_codes, 0..) |predefined_code, i| {
        const code = compressedSequenceCode(plan, i);
        if (code >= value_bits.len or predefined_code >= costs.len) return error.CorruptFrame;
        const predefined_cost = costs[predefined_code][@intFromBool(i + 1 < plan.len)];
        if (predefined_cost == std.math.maxInt(u8)) return false;
        predefined_bits = std.math.add(usize, predefined_bits, predefined_cost) catch return error.IntegerOverflow;
    }
    const compressed_bytes = std.math.add(usize, plan.table_payload_len, (compressed_bits + 1 + 7) / 8) catch return error.IntegerOverflow;
    const predefined_bytes = (predefined_bits + 1 + 7) / 8;
    return compressed_bytes < predefined_bytes;
}
